import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../pages/utils/supabaseConfig';
import { normalizeSearchTerm } from '../pages/utils/textUtils';
import DropdownPortal from './shared/DropdownPortal';

export interface AttributeNode {
    id: string;
    name: string;
}

interface AttributeRow {
    id: string;
    name: string;
}

interface AttributeAutocompleteProps {
    onSelect: (attribute: AttributeNode) => void;
    selectedIds: string[];
    placeholder?: string;
    className?: string;
    inputClassName?: string;
    disabled?: boolean;
}

const AttributeAutocomplete: React.FC<AttributeAutocompleteProps> = ({
    onSelect,
    selectedIds,
    placeholder = "Digite para buscar atributos (ex: Cor, Voltagem)...",
    className = "",
    inputClassName = "w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all placeholder:text-slate-400/60",
    disabled = false
}) => {
    const [query, setQuery] = useState("");
    const [suggestions, setSuggestions] = useState<AttributeNode[]>([]);
    const [allNodes, setAllNodes] = useState<AttributeNode[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [activeIndex, setActiveIndex] = useState(0);
    const wrapperRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchAll = async () => {
            setIsLoading(true);
            try {
                const { data } = await supabase.from('attributes').select('id, name').order('name');
                if (data) {
                    setAllNodes((data as AttributeRow[]).map(d => ({ id: d.id, name: d.name })));
                }
            } catch (err) {
                console.error('Erro ao buscar atributos:', err);
            } finally {
                setIsLoading(false);
            }
        };
        fetchAll();
    }, []);

    useEffect(() => {
        const trimmed = query.trim();
        if (trimmed.length < 2) {
            setSuggestions([]);
            return;
        }

        const normalizedQuery = normalizeSearchTerm(trimmed);
        const filtered = allNodes.filter(node =>
            normalizeSearchTerm(node.name).includes(normalizedQuery)
        );
        setSuggestions(filtered);
        setActiveIndex(0);
    }, [query, allNodes]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleToggle = (node: AttributeNode) => {
        onSelect(node);
    };

    const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Escape') {
            setShowSuggestions(false);
            return;
        }

        if (!showSuggestions || suggestions.length === 0) return;

        if (event.key === 'ArrowDown') {
            event.preventDefault();
            setActiveIndex(index => Math.min(index + 1, suggestions.length - 1));
        } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setActiveIndex(index => Math.max(index - 1, 0));
        } else if (event.key === 'Enter') {
            event.preventDefault();
            if (suggestions[activeIndex]) {
                handleToggle(suggestions[activeIndex]);
            }
        }
    };

    return (
        <div className={`relative ${className}`} ref={wrapperRef}>
            <div className="relative">
                <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input
                    type="text"
                    value={query}
                    onChange={(e) => {
                        setQuery(e.target.value);
                        setShowSuggestions(true);
                    }}
                    onFocus={() => setShowSuggestions(true)}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    className={inputClassName}
                    autoComplete="off"
                    disabled={disabled}
                />
                {isLoading && (
                    <i className="bi bi-arrow-repeat absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 animate-spin" />
                )}
            </div>

            <DropdownPortal
                isOpen={showSuggestions && query.trim().length >= 2}
                anchorRef={wrapperRef}
                onClose={() => setShowSuggestions(false)}
            >
                <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl shadow-xl overflow-hidden max-h-64 overflow-y-auto custom-scrollbar p-2">
                    {suggestions.length === 0 ? (
                        <div className="p-4 text-center text-xs font-semibold text-slate-500">
                            Nenhuma característica encontrada para &ldquo;{query}&rdquo;
                        </div>
                    ) : (
                        <div className="flex flex-col gap-1">
                            {suggestions.map((node, index) => {
                                const isChecked = selectedIds.includes(node.id);
                                return (
                                    <button
                                        type="button"
                                        key={node.id}
                                        onClick={() => handleToggle(node)}
                                        className={`flex items-center justify-between w-full text-left p-2.5 rounded-xl transition-all ${
                                            index === activeIndex
                                                ? 'bg-blue-50/70 dark:bg-blue-500/10'
                                                : 'hover:bg-slate-50 dark:hover:bg-slate-800/60'
                                        }`}
                                    >
                                        <div className="flex items-center gap-2.5 overflow-hidden">
                                            <input
                                                type="checkbox"
                                                checked={isChecked}
                                                onChange={() => {}} // controlado pelo clique do container
                                                className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer pointer-events-none"
                                            />
                                            <span className={`text-xs font-semibold truncate ${
                                                isChecked ? 'text-blue-600 dark:text-blue-400 font-bold' : 'text-slate-700 dark:text-slate-300'
                                            }`}>
                                                {node.name}
                                            </span>
                                        </div>
                                        {isChecked && (
                                            <span className="text-[10px] font-bold uppercase tracking-wider text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/30 px-2 py-0.5 rounded-md">
                                                Ativo
                                            </span>
                                        )}
                                    </button>
                                );
                            })}
                        </div>
                    )}
                </div>
            </DropdownPortal>
        </div>
    );
};

export default AttributeAutocomplete;

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '../pages/utils/supabaseConfig';
import { normalizeSearchTerm } from '../pages/utils/textUtils';
import DropdownPortal from './shared/DropdownPortal';

interface CategoryNode {
    id: string;
    name: string;
    parents?: string[]; // IDs of environments (if it's a category)
    isEnvironment?: boolean;
}

interface CategoryAutocompleteProps {
    onSelect: (category: CategoryNode) => void;
    onRemove: (categoryId: string) => void;
    selectedIds: string[];
    onSearch?: () => void;
    placeholder?: string;
    className?: string;
    inputClassName?: string;
    filter?: 'environments' | 'categories' | 'all';
}

const CategoryAutocomplete: React.FC<CategoryAutocompleteProps> = ({
    onSelect,
    onRemove,
    selectedIds,
    onSearch,
    placeholder = "Digite para buscar...",
    className = "",
    inputClassName = "w-full pl-11 pr-4 py-4 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all placeholder:text-slate-400/60",
    filter = "all"
}) => {
    const [query, setQuery] = useState("");
    const [suggestions, setSuggestions] = useState<CategoryNode[]>([]);
    const [allNodes, setAllNodes] = useState<CategoryNode[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [showSuggestions, setShowSuggestions] = useState(false);
    const wrapperRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const fetchAll = async () => {
            setIsLoading(true);
            const { data: envs } = await supabase.from('environments').select('id, name').order('name');
            const { data: cats } = await supabase.from('categories').select('id, name').order('name');
            const { data: rels } = await supabase.from('environment_categories').select('environment_id, category_id');
            
            const nodes: CategoryNode[] = [];

            if (envs) {
                nodes.push(...envs.map((e: any) => ({
                    id: e.id,
                    name: e.name,
                    isEnvironment: true,
                    parents: []
                })));
            }

            if (cats) {
                nodes.push(...cats.map((c: any) => ({
                    id: c.id,
                    name: c.name,
                    isEnvironment: false,
                    parents: rels?.filter((r: any) => r.category_id === c.id).map((r: any) => r.environment_id) || []
                })));
            }

            setAllNodes(nodes);
            setIsLoading(false);
        };
        
        fetchAll();

        window.addEventListener('focus', fetchAll);
        return () => {
            window.removeEventListener('focus', fetchAll);
        };
    }, []);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setShowSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        const filteredList = allNodes.filter(c => {
            if (filter === 'all') return true;
            if (filter === 'environments') return c.isEnvironment;
            if (filter === 'categories') return !c.isEnvironment;
            return true;
        });

        if (query.trim() === "") {
            setSuggestions(filteredList.slice(0, 30));
            return;
        }

        const normQuery = normalizeSearchTerm(query);
        const filtered = filteredList.filter(c => 
            normalizeSearchTerm(c.name).includes(normQuery)
        ).slice(0, 50);
        
        setSuggestions(filtered);
    }, [query, allNodes, filter]);

    const handleSelect = (category: CategoryNode) => {
        onSelect(category);
        setQuery("");
    };

    return (
        <div ref={wrapperRef} className={`relative flex flex-col gap-3 ${className}`}>
            {selectedIds.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-1">
                    {selectedIds.map(id => {
                        const cat = allNodes.find(c => c.id === id);
                        if (!cat) return null;
                        return (
                            <div key={id} className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest rounded-xl animate-in zoom-in-95 duration-200">
                                <span>{cat.name}</span>
                                <button type="button" onClick={() => onRemove(id)} className="hover:text-red-200 transition-colors">
                                    <i className="bi bi-x-lg"></i>
                                </button>
                            </div>
                        );
                    })}
                </div>
            )}

            <div className="flex gap-2">
                <div className="relative flex-1">
                    <i className="bi bi-tag absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
                    <input
                        type="text"
                        value={query}
                        onChange={(e) => {
                            setQuery(e.target.value);
                            setShowSuggestions(true);
                        }}
                        onFocus={() => setShowSuggestions(true)}
                        placeholder={placeholder}
                        className={inputClassName}
                    />
                    {isLoading && (
                        <div className="absolute right-4 top-1/2 -translate-y-1/2">
                            <i className="bi bi-arrow-repeat animate-spin text-blue-500"></i>
                        </div>
                    )}
                </div>

                {onSearch && (
                    <button
                        type="button"
                        onClick={onSearch}
                        className="p-4 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 border border-blue-100 dark:border-blue-800 rounded-2xl hover:bg-blue-100 transition-all shadow-sm"
                        title="Busca Avançada"
                    >
                        <i className="bi bi-search"></i>
                    </button>
                )}
            </div>

            <DropdownPortal anchorRef={wrapperRef} isOpen={showSuggestions}>
                <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl shadow-2xl max-h-64 overflow-y-auto animate-in fade-in slide-in-from-top-2 duration-200 p-2 space-y-1">
                    {suggestions.length > 0 ? (
                        suggestions.map((cat) => {
                            const isSelected = selectedIds.includes(cat.id);
                            return (
                                <button
                                    key={cat.id}
                                    type="button"
                                    onClick={() => handleSelect(cat)}
                                    disabled={isSelected}
                                    className={`w-full px-4 py-3 text-left rounded-xl transition-all flex items-center justify-between group ${isSelected ? 'opacity-50 grayscale cursor-not-allowed' : 'hover:bg-blue-50 dark:hover:bg-blue-900/20'}`}
                                >
                                    <div className="flex flex-col">
                                        <span className="text-sm font-bold text-slate-700 dark:text-slate-200">{cat.name}</span>
                                        {!cat.isEnvironment && cat.parents && cat.parents.length > 0 && (
                                            <span className="text-[9px] uppercase font-black text-slate-400">
                                                {allNodes.find(c => c.id === cat.parents![0])?.name || 'Ambiente'} &gt; Categoria
                                            </span>
                                        )}
                                        {cat.isEnvironment && (
                                            <span className="text-[9px] uppercase font-black text-blue-500">
                                                Ambiente
                                            </span>
                                        )}
                                    </div>
                                    {!isSelected && <i className="bi bi-plus-lg text-blue-500 opacity-0 group-hover:opacity-100 transition-all"></i>}
                                </button>
                            );
                        })
                    ) : (
                        <div className="p-8 text-center">
                            <i className="bi bi-search text-2xl text-slate-200 mb-2 block"></i>
                            <p className="text-[10px] uppercase font-black text-slate-400 tracking-widest">Nenhum resultado encontrado</p>
                        </div>
                    )}
                </div>
            </DropdownPortal>
        </div>
    );
};

export default CategoryAutocomplete;

/**
 * @vitest-environment jsdom
 */
import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import CurrencyInput from './CurrencyInput';
import React from 'react';

describe('CurrencyInput', () => {
    it('deve renderizar o valor null como vazio/placeholder', () => {
        render(<CurrencyInput value={null} onChangeValue={vi.fn()} testID="curr-input" />);
        const input = screen.getByTestId('curr-input') as HTMLInputElement;
        expect(input.value).toBe('');
    });

    it('deve formatar valor inicial corretamente (BRL)', () => {
        render(<CurrencyInput value={1234.56} onChangeValue={vi.fn()} testID="curr-input" />);
        const input = screen.getByTestId('curr-input') as HTMLInputElement;
        // Dependendo da implementação do Intl, o espaço do milhar pode ser `.`
        // Usaremos expressão regular ou string replace em whitespace caso falhe por espaço non-breaking.
        const normalizedVal = input.value.replace(/\s/g, ' ');
        expect(normalizedVal).toContain('1.234,56');
    });

    it('deve formatar 0 corretamente', () => {
        render(<CurrencyInput value={0} onChangeValue={vi.fn()} testID="curr-input" />);
        const input = screen.getByTestId('curr-input') as HTMLInputElement;
        expect(input.value).toContain('0,00');
    });

    it('deve formatar bancario RTL ao digitar', async () => {
        const handleChange = vi.fn();
        render(<CurrencyInput value={null} onChangeValue={handleChange} testID="curr-input" />);
        const input = screen.getByTestId('curr-input');

        const user = userEvent.setup();
        // 1 => 0.01
        await user.type(input, '1');
        expect(handleChange).toHaveBeenLastCalledWith(0.01);

        // +2 => 12 => 0.12
        await user.type(input, '2');
        expect(handleChange).toHaveBeenLastCalledWith(0.12);

        // +3 => 123 => 1.23
        await user.type(input, '3');
        expect(handleChange).toHaveBeenLastCalledWith(1.23);

        // +456 => 123456 => 1234.56
        await user.type(input, '456');
        expect(handleChange).toHaveBeenLastCalledWith(1234.56);
    });

    it('deve testar colagem no componente', () => {
        const handleChange = vi.fn();
        render(<CurrencyInput value={null} onChangeValue={handleChange} testID="curr-input" />);
        const input = screen.getByTestId('curr-input');

        // Simular colagem de R$ 1.234,56
        fireEvent.change(input, { target: { value: 'R$ 1.234,56' } });
        // O regex vai pegar \d -> 123456 -> num 1234.56
        expect(handleChange).toHaveBeenLastCalledWith(1234.56);

        // Simular colar americano
        fireEvent.change(input, { target: { value: '1234.56' } });
        expect(handleChange).toHaveBeenLastCalledWith(1234.56);
    });

    it('deve respeitar max', async () => {
        const handleChange = vi.fn();
        render(<CurrencyInput value={100} max={150} onChangeValue={handleChange} testID="curr-input" />);
        const input = screen.getByTestId('curr-input');

        fireEvent.change(input, { target: { value: '20000' } }); // 200,00

        // Como o max é 150, ele deve ter chamado com 150
        expect(handleChange).toHaveBeenLastCalledWith(150);
    });

    it('deve renderizar label e error quando fornecidos', () => {
        render(
            <CurrencyInput 
                value={10} 
                onChangeValue={vi.fn()} 
                label="Preço Teste" 
                error="Valor inválido" 
                testID="curr-input" 
            />
        );
        expect(screen.getByText('Preço Teste')).toBeDefined();
        expect(screen.getByText('Valor inválido')).toBeDefined();
    });
});

import React, { useState, useEffect, useRef } from 'react';

export interface CurrencyInputProps {
    value: number | string | undefined | null;
    onChangeValue?: (val: number) => void;
    onChange?: (val: number) => void;
    className?: string;
    style?: React.CSSProperties;
    onBlur?: () => void;
    onFocus?: () => void;
    placeholder?: string;
    disabled?: boolean;
    readOnly?: boolean;
    required?: boolean;
    id?: string;
    name?: string;
    prefix?: string;
    suffix?: string;
    autoFocus?: boolean;
    min?: number;
    max?: number;
    showBadge?: boolean;
    badgeText?: string;
    label?: string;
    error?: string | boolean;
    helperText?: string;
    testID?: string;
}

const CurrencyInput = ({
    value,
    onChangeValue,
    onChange,
    className,
    style,
    onBlur,
    onFocus,
    placeholder = "0,00",
    disabled = false,
    readOnly = false,
    required = false,
    id,
    name,
    prefix = "",
    suffix = "",
    autoFocus = false,
    min,
    max,
    showBadge = true,
    badgeText,
    label,
    error,
    helperText,
    testID,
}: CurrencyInputProps) => {
    const handleChange = onChangeValue || onChange;
    const displayBadge = badgeText || (suffix.trim() || "R$");
    const hasError = typeof error === 'string' ? !!error : error;
    const errorMessage = typeof error === 'string' ? error : undefined;

    const [displayValue, setDisplayValue] = useState("");
    
    const formatBRL = (numValue: number) => {
        const formatted = new Intl.NumberFormat('pt-BR', {
            style: 'currency',
            currency: 'BRL',
            minimumFractionDigits: 2,
        }).format(numValue);
        // Remove a parte do R$ e os espaços que o Intl coloca, pois o input nativo vai ter o R$ fora ou prefix
        const numberPart = formatted.replace(/^R$\s?/, '');
        return prefix + numberPart + suffix;
    };

    // Sincroniza valor recebido de fora (number) para a tela (string pt-BR)
    useEffect(() => {
        if (value === null || value === undefined || isNaN(Number(value))) {
            setDisplayValue("");
            return;
        }
        setDisplayValue(formatBRL(Number(value)));
    }, [value, prefix, suffix]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!handleChange || readOnly || disabled) return;
        
        const text = e.target.value;
        // Pega apenas os dígitos digitados ou colados
        const digitsOnly = text.replace(/\\D/g, '');
        
        if (!digitsOnly) {
            handleChange(0); // Emite zero quando limpo, ou pode emitir null se adaptado
            setDisplayValue("");
            return;
        }

        // Converte pra float com 2 casas
        let numericValue = parseInt(digitsOnly, 10) / 100;

        // Limites
        if (max !== undefined && max > 0 && numericValue > max) numericValue = max;
        // Não aplica min no handleChange para não impedir a digitação, aplica no onBlur ou deixa o usuario digitar
        // O NumericFormat também permitia digitar abaixo do min temporariamente? Sim, senão vc não apaga para reescrever
        
        handleChange(numericValue);
        setDisplayValue(formatBRL(numericValue));
    };

    const handleFocusInternal = (e: React.FocusEvent<HTMLInputElement>) => {
        e.target.select();
        onFocus?.();
    };

    const handleBlurInternal = () => {
        if (min !== undefined && value !== undefined && value !== null) {
            const numVal = Number(value);
            if (!isNaN(numVal) && numVal < min && handleChange && !readOnly && !disabled) {
                handleChange(min);
                setDisplayValue(formatBRL(min));
            }
        }
        onBlur?.();
    };

    const borderClass = hasError
        ? "border-red-500 dark:border-red-400"
        : "border-slate-200 dark:border-slate-700";

    const focusBorderClass = hasError
        ? "focus-within:border-red-500"
        : "focus-within:border-blue-600 dark:focus-within:border-blue-500";

    const renderInput = () => {
        if (showBadge) {
            return (
                <div className={`flex w-full items-center border-b-2 bg-transparent transition-colors ${borderClass} ${focusBorderClass}`}>
                    <div className="bg-transparent text-blue-700 dark:text-blue-300 font-black text-[10px] uppercase tracking-wider pl-1 pr-1.5 py-2 flex items-center justify-center shrink-0 self-stretch">
                        {displayBadge}
                    </div>
                    <input
                        id={id}
                        name={name}
                        style={style}
                        value={displayValue}
                        onChange={handleInputChange}
                        onFocus={handleFocusInternal}
                        onBlur={handleBlurInternal}
                        disabled={disabled || readOnly}
                        placeholder={placeholder}
                        autoFocus={autoFocus}
                        data-testid={testID}
                        inputMode="numeric"
                        className="w-full min-w-[50px] text-right bg-transparent px-2.5 py-2 outline-none border-none rounded-none text-xs font-bold text-slate-800 dark:text-slate-100 focus:ring-0"
                    />
                </div>
            );
        }

        return (
            <input
                id={id}
                name={name}
                style={style}
                value={displayValue}
                onChange={handleInputChange}
                onFocus={handleFocusInternal}
                onBlur={handleBlurInternal}
                disabled={disabled || readOnly}
                placeholder={placeholder}
                autoFocus={autoFocus}
                data-testid={testID}
                inputMode="numeric"
                className={className || "w-full min-w-[95px] text-right bg-transparent border border-slate-100 dark:border-slate-800 focus:border-blue-500 px-2 py-1.5 rounded-xl outline-none transition-all text-xs font-bold"}
            />
        );
    };

    if (label || errorMessage || helperText) {
        return (
            <div className="flex flex-col gap-1 w-full">
                {label && (
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-wider" htmlFor={id}>
                        {label}
                        {required && <span className="text-red-500 ml-0.5">*</span>}
                    </label>
                )}
                {renderInput()}
                {errorMessage && <span className="text-[10px] text-red-500 font-medium">{errorMessage}</span>}
                {helperText && !errorMessage && (
                    <span className="text-[10px] text-slate-400">{helperText}</span>
                )}
            </div>
        );
    }

    return renderInput();
};

export default CurrencyInput;

import React, { useState, KeyboardEvent, FocusEvent, useEffect, useMemo } from 'react';
import { getNoticeFrequency } from '../pages/utils/orderHistoryService';
import DropdownPortal from './shared/DropdownPortal';
import { useRef } from 'react';
import { joinNoticeTags, splitNoticeTags } from '../pages/utils/noticeTags';

interface NoticeInputProps {
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
    className?: string;
    label?: string;
}

const NoticeInput = ({ value, onChange, placeholder = "Adicionar aviso...", className = "", label }: NoticeInputProps) => {
    const [inputValue, setInputValue] = useState("");
    const [frequencies, setFrequencies] = useState<Record<string, number>>({});
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [editingIndex, setEditingIndex] = useState<number | null>(null);
    const [editingValue, setEditingValue] = useState("");
    const containerRef = useRef<HTMLDivElement>(null);

    const tags = useMemo(() => splitNoticeTags(value), [value]);

    useEffect(() => {
        const loadFrequencies = async () => {
            const freq = await getNoticeFrequency();
            setFrequencies(freq);
        };
        loadFrequencies();
    }, []);

    const suggestions = useMemo(() => {
        const query = inputValue.toLowerCase().trim();
        return Object.entries(frequencies)
            .filter(([text]) => !tags.includes(text) && (query === "" || text.toLowerCase().includes(query)))
            .sort((a, b) => b[1] - a[1]) // Sort by frequency
            .slice(0, 10);
    }, [frequencies, inputValue, tags]);

    const addTag = (tag: string) => {
        const trimmedTag = tag.trim();
        if (trimmedTag && !tags.includes(trimmedTag)) {
            const newTags = [...tags, trimmedTag];
            onChange(joinNoticeTags(newTags));
        }
        setInputValue("");
        setShowSuggestions(false);
    };

    const removeTag = (indexToRemove: number) => {
        const newTags = tags.filter((_, index) => index !== indexToRemove);
        onChange(joinNoticeTags(newTags));
    };

    const startEditing = (index: number, text: string) => {
        setEditingIndex(index);
        setEditingValue(text);
    };

    const saveEdit = () => {
        if (editingIndex !== null) {
            const trimmed = editingValue.trim();
            if (trimmed) {
                const newTags = [...tags];
                newTags[editingIndex] = trimmed;
                onChange(joinNoticeTags(newTags));
            } else {
                removeTag(editingIndex);
            }
            setEditingIndex(null);
            setEditingValue("");
        }
    };

    const cancelEdit = () => {
        setEditingIndex(null);
        setEditingValue("");
    };

    const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            if (inputValue) addTag(inputValue);
        } else if (e.key === 'Backspace' && !inputValue && tags.length > 0) {
            removeTag(tags.length - 1);
        } else if (e.key === 'Escape') {
            setShowSuggestions(false);
        } else if (e.key === 'ArrowDown' && !showSuggestions) {
            setShowSuggestions(true);
        }
    };

    const getTagColor = (tag: string) => {
        return "bg-red-50 text-red-600 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-900/30 shadow-sm shadow-red-100 dark:shadow-none font-black";
    };

    return (
        <div className={`flex flex-col gap-2 relative ${className}`} ref={containerRef}>
            {label && (
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 ml-1 flex items-center gap-2">
                    <i className="bi bi-megaphone text-red-500 animate-pulse" />
                    {label}
                </label>
            )}
            
            <div className="flex flex-wrap gap-2 p-4 bg-white dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-[2rem] min-h-[120px] items-start transition-all focus-within:border-red-500/30 focus-within:ring-4 focus-within:ring-red-500/5 shadow-inner">
                {tags.map((tag, index) => (
                    editingIndex === index ? (
                        <input
                            key={index}
                            autoFocus
                            value={editingValue}
                            onChange={(e) => setEditingValue(e.target.value)}
                            onBlur={saveEdit}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    e.preventDefault();
                                    saveEdit();
                                } else if (e.key === 'Escape') {
                                    cancelEdit();
                                }
                            }}
                            className={`px-4 py-2 rounded-2xl text-[11px] border outline-none min-w-[100px] border-blue-500 bg-white dark:bg-slate-900 transition-all font-bold ${getTagColor(tag)}`}
                        />
                    ) : (
                        <span
                            key={index}
                            onClick={() => startEditing(index, tag)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-2xl text-[11px] border transition-all animate-in fade-in zoom-in-95 duration-300 cursor-pointer hover:ring-2 hover:ring-slate-200 dark:hover:ring-slate-800 ${getTagColor(tag)}`}
                        >
                            {tag}
                            <button
                                type="button"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    removeTag(index);
                                }}
                                className="hover:scale-125 transition-transform"
                            >
                                <i className="bi bi-x-circle-fill opacity-50 hover:opacity-100 transition-opacity" />
                            </button>
                        </span>
                    )
                ))}
                <input
                    type="text"
                    value={inputValue}
                    onChange={(e) => {
                        setInputValue(e.target.value);
                        setShowSuggestions(true);
                    }}
                    onFocus={() => setShowSuggestions(true)}
                    onKeyDown={handleKeyDown}
                    placeholder={tags.length === 0 ? placeholder : ""}
                    className="flex-1 min-w-[150px] bg-transparent outline-none text-sm py-2 placeholder:text-slate-300 dark:placeholder:text-slate-700 dark:text-slate-300 font-bold tracking-tight"
                />
            </div>

            {/* Suggestions Dropdown */}
            <DropdownPortal anchorRef={containerRef} isOpen={showSuggestions && suggestions.length > 0}>
                <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl shadow-2xl overflow-hidden animate-slide-up py-2">
                    <div className="px-5 py-2 border-b border-slate-50 dark:border-slate-800">
                        <span className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400">Sugestões (Mais Usados)</span>
                    </div>
                    <div className="max-h-60 overflow-y-auto custom-scrollbar">
                        {suggestions.map(([text, count]) => (
                            <button
                                key={text}
                                type="button"
                                onClick={() => addTag(text)}
                                className="w-full text-left px-5 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all flex items-center justify-between group"
                            >
                                <span className="text-sm font-bold text-slate-700 dark:text-slate-200 group-hover:translate-x-1 transition-transform">{text}</span>
                                <span className={`text-[10px] font-black px-2 py-0.5 rounded-lg ${count >= 5 ? 'bg-blue-50 text-blue-500 dark:bg-blue-900/30' : 'bg-red-50 text-red-500 dark:bg-red-900/30'}`}>
                                    {count}x
                                </span>
                            </button>
                        ))}
                    </div>
                </div>
            </DropdownPortal>
        </div>
    );
};

export default NoticeInput;

import React from 'react';
import Product, { Variation } from '../pages/types/product.type';
import DropdownPortal from './shared/DropdownPortal';
import TruncatedProductTitle from './TruncatedProductTitle';
import { getVariationDisplayName } from './productAutocompleteUtils';
import { useProductAutocomplete } from './hooks/useProductAutocomplete';

interface ProductAutocompleteProps {
    onSelect: (product: Product, variation?: Variation) => void;
    onSelectDescription?: (description: string) => void;
    onChange?: (value: string) => void;
    onSearch?: () => void;
    onCreateNew?: () => void;
    isSelected?: boolean;
    isTemporary?: boolean;
    isAiSuggestion?: boolean;
    onAcceptSuggestion?: () => void;
    onRejectSuggestion?: () => void;
    value?: string;
    placeholder?: string;
    className?: string;
    inputClassName?: string;
    supplierId?: string;
    onlyName?: boolean;
    variationsOnly?: boolean;
    excludeCombos?: boolean;
    /** Limita a busca aos cadastros de produto, sem oferecer variações filhas. */
    parentsOnly?: boolean;
    /** Inclui produtos e variações desativados; variações fundidas continuam ocultas. */
    includeDeactivated?: boolean;
    products?: Product[];
    clearOnSelect?: boolean;
    disabled?: boolean;
    isLoadingSuggestions?: boolean;
    onEditClick?: (product: Product, variation?: Variation) => void;
}

const ProductAutocomplete: React.FC<ProductAutocompleteProps> = ({
    onSelect,
    onChange,
    onSearch,
    onCreateNew,
    isSelected = false,
    isTemporary = false,
    isAiSuggestion = false,
    onAcceptSuggestion,
    onRejectSuggestion,
    value = "",
    placeholder = "Digite o nome ou código do produto...",
    className = "",
    inputClassName,
    supplierId,
    onlyName = false,
    variationsOnly = false,
    excludeCombos = false,
    parentsOnly = false,
    includeDeactivated = false,
    products: localProducts,
    clearOnSelect = false,
    disabled = false,
    isLoadingSuggestions = false,
    onEditClick,
}) => {
    const {
        query,
        setQuery,
        handleQueryChange,
        suggestions,
        isLoading,
        showSuggestions,
        setShowSuggestions,
        wrapperRef,
    } = useProductAutocomplete({
        value,
        supplierId,
        parentsOnly,
        variationsOnly,
        includeDeactivated,
        localProducts,
        excludeCombos,
        onChange: (v) => {
            if (onChange) onChange(v);
        },
    });

    return (
        <div ref={wrapperRef} className={`relative ${className}`}>
            <div className="flex gap-1.5">
                <div className="relative flex-1">
                    <input
                        type="text"
                        autoComplete="off"
                        aria-busy={isLoadingSuggestions}
                        disabled={disabled}
                        value={query || ''}
                        onChange={(e) => {
                            handleQueryChange(e.target.value);
                        }}
                        onFocus={() => setShowSuggestions(query.trim().length >= 2)}
                        placeholder={placeholder}
                        className={inputClassName || `w-full border-b-2 bg-transparent px-3 py-2 text-sm font-medium outline-none transition-colors ${
                            isAiSuggestion
                                ? 'border-amber-400 text-amber-950 dark:text-amber-100 focus:border-amber-500 bg-amber-50/20 dark:bg-amber-950/20 rounded-t-lg'
                                : isTemporary 
                                    ? 'border-amber-400 text-amber-950 dark:text-amber-100 focus:border-amber-500'
                                    : isSelected 
                                        ? 'border-emerald-500 text-emerald-950 dark:text-emerald-100 font-semibold focus:border-emerald-600 pr-9'
                                        : 'border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-500'
                        } ${disabled ? 'opacity-60 cursor-not-allowed' : ''} ${className}`}
                    />

                    {/* Faixa amarela animada passando no input durante o processamento */}
                    {isLoadingSuggestions && (
                        <div className="absolute inset-x-0 bottom-0 h-[2px] overflow-hidden rounded-b-lg pointer-events-none">
                            <div className="ncm-input-shimmer absolute inset-0 w-1/2" />
                        </div>
                    )}

                    {isLoadingSuggestions ? (
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1 text-amber-600 dark:text-amber-400">
                            <i className="bi bi-arrow-repeat animate-spin text-sm" />
                        </div>
                    ) : isLoading ? (
                        <div className="absolute right-3 top-1/2 -translate-y-1/2">
                            <i className="bi bi-arrow-repeat animate-spin text-slate-400"></i>
                        </div>
                    ) : isSelected ? (
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" title="Produto vinculado ao catálogo">
                            <i className="bi bi-check-circle-fill text-emerald-500 text-sm"></i>
                        </div>
                    ) : isAiSuggestion ? (
                        <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" title="Sugestão de IA">
                            <i className="bi bi-stars text-amber-500 text-sm animate-pulse"></i>
                        </div>
                    ) : null}
                </div>
                
                {onSearch && (
                    <button
                        type="button"
                        onClick={onSearch}
                        className="p-2 bg-slate-50 dark:bg-slate-800/50 text-slate-600 dark:text-slate-400 border border-slate-100 dark:border-slate-700 rounded-xl hover:bg-slate-100 transition-all shadow-sm"
                        title="Busca Avançada (Lupa)"
                    >
                        <i className="bi bi-search"></i>
                    </button>
                )}

                {onCreateNew && (
                    <button
                        type="button"
                        onClick={onCreateNew}
                        className="p-2 bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400 border border-emerald-100 dark:border-emerald-800 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm"
                        title="Criar Novo Produto"
                    >
                        <i className="bi bi-plus-lg"></i>
                    </button>
                )}
            </div>

            {isAiSuggestion && (
                <div className="flex items-center justify-between mt-1.5 px-1">
                    <span className="flex items-center gap-1.5 text-[11px] font-bold text-amber-700 dark:text-amber-400">
                        <i className="bi bi-stars text-amber-500 text-xs" />
                        Sugestão de IA
                    </span>
                    <div className="flex items-center gap-1.5">
                        {onAcceptSuggestion && (
                            <button
                                type="button"
                                aria-label="Aceitar sugestão da IA"
                                onClick={(e) => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    onAcceptSuggestion();
                                }}
                                className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold bg-emerald-600 hover:bg-emerald-700 text-white shadow-sm transition-colors"
                                title="Aceitar sugestão da IA"
                            >
                                <i className="bi bi-check-lg" />
                                Aceitar
                            </button>
                        )}
                        {onRejectSuggestion && (
                            <button
                                type="button"
                                aria-label="Recusar sugestão da IA"
                                onClick={(e) => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    onRejectSuggestion();
                                }}
                                className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-semibold border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-950/30 dark:hover:text-red-300 transition-colors"
                                title="Recusar sugestão da IA"
                            >
                                <i className="bi bi-x-lg text-[10px]" />
                                Recusar
                            </button>
                        )}
                    </div>
                </div>
            )}

            <DropdownPortal anchorRef={wrapperRef} isOpen={showSuggestions && query.trim().length >= 2}>
                <div className="bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl shadow-2xl max-h-72 overflow-y-auto animate-in fade-in slide-in-from-top-2 duration-200 divide-y divide-slate-100 dark:divide-slate-800/50">
                    {isLoading ? (
                        <div className="flex items-center justify-center gap-2 px-4 py-5 text-xs font-bold text-slate-400">
                            <i className="bi bi-arrow-repeat animate-spin" />
                            Buscando produtos...
                        </div>
                    ) : suggestions.length === 0 ? (
                        <div className="px-4 py-5 text-center text-xs font-bold text-slate-400">
                            Nenhum produto encontrado para esta busca.
                        </div>
                    ) : suggestions.map((item, index) => {
                        const { product: p, variation: v } = item;
                        const fullName = getVariationDisplayName(p, v);
                        const displayName = v?.name?.trim() || fullName;

                        const displayCode = v?.sku || p.code || '';
                        const displayPrice = v 
                            ? (v.promoPrice || v.unitPrice || p.promoPrice || p.unitPrice || 0) 
                            : (p.promoPrice || p.unitPrice || 0);
                        const displayStock = v ? (v.stock ?? 0) : (p.stock ?? 0);

                        return (
                            <button
                                key={`${p.id}-${v?.id || 'base'}-${index}`}
                                type="button"
                                onClick={() => {
                                    onSelect(p, v);
                                    if (clearOnSelect) {
                                        setQuery('');
                                        onChange?.('');
                                    } else {
                                        setQuery(fullName);
                                    }
                                    setShowSuggestions(false);
                                }}
                                className="w-full px-4 py-2.5 text-left hover:bg-emerald-50/70 dark:hover:bg-slate-800/60 transition-all flex items-center justify-between gap-3 group"
                            >
                                <div className="flex flex-col min-w-0 flex-1">
                                    <TruncatedProductTitle
                                        fullName={fullName}
                                        displayName={displayName}
                                        query={query}
                                    />
                                    {!onlyName && displayCode && (
                                        <span className="text-[10px] font-mono text-slate-400">
                                            Cód: {displayCode}
                                        </span>
                                    )}
                                </div>

                                {!onlyName && (
                                    <div className="flex items-center gap-3 shrink-0">
                                        <span className="text-xs font-black text-blue-600 dark:text-blue-400 font-sans">
                                            {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(displayPrice)}
                                        </span>
                                        {onEditClick ? (
                                            <button
                                                type="button"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    onEditClick(p, v);
                                                }}
                                                className="p-1 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/30 rounded-md transition-colors"
                                                title="Editar produto/variação"
                                            >
                                                <i className="bi bi-pencil-square text-sm" />
                                            </button>
                                        ) : (
                                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md ${displayStock > 0 ? 'bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400' : 'bg-red-50 dark:bg-red-900/30 text-red-500'}`}>
                                                {displayStock > 0 ? `${displayStock} un` : 'Sem estoque'}
                                            </span>
                                        )}
                                    </div>
                                )}
                            </button>
                        );
                    })}
                </div>
            </DropdownPortal>
        </div>
    );
};

export default ProductAutocomplete;

import React, { useState } from 'react';
import ProductAutocomplete from './ProductAutocomplete';
import CurrencyInput from './CurrencyInput';
import { PurchaseItem } from '../pages/types/purchase.type';
import Product, { Variation } from '../pages/types/product.type';
import { toast } from 'react-toastify';

interface Props {
    items: PurchaseItem[];
    onAddItem: (item: PurchaseItem) => boolean | void;
    onRemoveItem: (idx: number) => void;
    onUpdateItem?: (idx: number, item: PurchaseItem) => void;
    ipiPercent: number;
    freightPercent: number;
    formatCurrency: (value: number) => string;
    supplierId?: string;
    onSupplierAutoSelect?: (supplierId: string) => void;
    hasError?: boolean;
    isReceiptMode?: boolean;
}

export const PurchaseItemsSection = ({
    items,
    onAddItem,
    onRemoveItem,
    onUpdateItem,
    ipiPercent,
    freightPercent,
    formatCurrency,
    supplierId,
    onSupplierAutoSelect,
    hasError = false,
    isReceiptMode = true
}: Props) => {
    // Current item being added (utilizado no modo Compras tradicional)
    const [currentProductId, setCurrentProductId] = useState("");
    const [currentVariationId, setCurrentVariationId] = useState<string | undefined>(undefined);
    const [currentDescription, setCurrentDescription] = useState("");
    const [currentQty, setCurrentQty] = useState(1);
    const [currentCost, setCurrentCost] = useState(0);

    const tempIpiVal = currentCost * (ipiPercent / 100);
    const tempFreightVal = currentCost * (freightPercent / 100);
    const tempTotalUnit = currentCost + tempIpiVal + tempFreightVal;

    const handleAddItemClick = () => {
        if (!currentProductId) {
            toast.error('Selecione um produto antes de adicionar.');
            return;
        }

        const qtyToAdd = isReceiptMode ? 1 : Math.max(1, currentQty);

        const added = onAddItem({
            productId: currentProductId,
            variationId: currentVariationId,
            description: currentDescription,
            quantity: qtyToAdd,
            baseCost: currentCost,
            unitCost: tempTotalUnit,
            totalCost: qtyToAdd * tempTotalUnit
        });

        if (added === false) return;

        toast.success('Item adicionado.');
        setCurrentProductId("");
        setCurrentVariationId(undefined);
        setCurrentDescription("");
        setCurrentQty(1);
        setCurrentCost(0);
    };

    // No modo de recebimento: adiciona linha vazia para digitar o produto diretamente nela
    const handleAddNewItemRow = () => {
        if (isReceiptMode && !supplierId) {
            toast.warn('Selecione o fornecedor acima primeiro.');
            return;
        }

        onAddItem({
            productId: '',
            description: '',
            quantity: 1,
            baseCost: 0,
            unitCost: 0,
            totalCost: 0
        });
    };

    const handleSelectProductInRow = (idx: number, product: Product, variation?: Variation) => {
        const prodName = product.name || product.title || product.description || '';
        const description = variation ? (variation.name && variation.name.toLowerCase().includes(prodName.toLowerCase()) ? variation.name : `${prodName} - ${variation.name}`) : prodName;
        const cost = variation?.costPrice || product.costPrice || 0;
        const tempIpi = cost * (ipiPercent / 100);
        const tempFreight = cost * (freightPercent / 100);
        const unitCost = cost + tempIpi + tempFreight;
        const currentItem = items[idx];
        const quantity = currentItem?.quantity || 1;

        if (onUpdateItem) {
            onUpdateItem(idx, {
                ...currentItem,
                productId: product.id!,
                variationId: variation?.id,
                description,
                baseCost: cost,
                unitCost,
                totalCost: quantity * unitCost,
            });
        }

        const prodSupplierId = product.mainSupplierId || product.supplierId || (product as any).main_supplier_id || (product as any).supplier_id;
        if (!supplierId && prodSupplierId && onSupplierAutoSelect) {
            onSupplierAutoSelect(prodSupplierId);
        }
    };

    const handleEditProductInRow = (idx: number) => {
        if (onUpdateItem) {
            onUpdateItem(idx, {
                ...items[idx],
                productId: '',
            });
        }
    };

    const handleQtyChange = (idx: number, newQty: number) => {
        const item = items[idx];
        const validQty = Math.max(1, newQty);
        const updated: PurchaseItem = {
            ...item,
            quantity: validQty,
        };

        if (onUpdateItem) {
            onUpdateItem(idx, updated);
        }
    };

    const handleCostChange = (idx: number, newCost: number) => {
        const item = items[idx];
        const validCost = Math.max(0, newCost);
        const updated: PurchaseItem = {
            ...item,
            baseCost: validCost,
        };

        if (onUpdateItem) {
            onUpdateItem(idx, updated);
        }
    };

    const totalValue = items.reduce((sum, item) => sum + item.totalCost, 0);

    return (
        <div className="space-y-4">
            {/* Modo Recebimento: Barra compacta com Título e Botão na MESMA linha */}
            {isReceiptMode ? (
                <div className="flex flex-wrap items-center justify-between gap-3 pb-3 border-b border-slate-200/80 dark:border-slate-800">
                    <div className="flex items-center gap-2">
                        <i className="bi bi-plus-circle-fill text-emerald-600 text-sm" />
                        <h3 className="text-xs font-black uppercase tracking-widest text-slate-700 dark:text-slate-200">
                            Adicionar Item
                        </h3>
                        {items.length > 0 && (
                            <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-600 border border-emerald-200/60 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-900/40">
                                {items.length} item(ns)
                            </span>
                        )}
                        {!supplierId && (
                            <span className="text-[10px] font-bold text-amber-500 ml-2">
                                (Selecione o fornecedor acima primeiro)
                            </span>
                        )}
                        {hasError && (
                            <span className="text-[10px] font-bold text-red-500 ml-2">
                                Adicione pelo menos um item ao recebimento.
                            </span>
                        )}
                    </div>

                    <button
                        type="button"
                        onClick={handleAddNewItemRow}
                        disabled={!supplierId}
                        className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white text-xs font-bold transition-all shadow-sm hover:shadow disabled:opacity-50 disabled:cursor-not-allowed disabled:active:scale-100"
                        title={!supplierId ? "Selecione o fornecedor acima primeiro" : "Adicionar Item"}
                    >
                        <i className="bi bi-plus-lg text-sm font-black" />
                        <span>Adicionar Item</span>
                    </button>
                </div>
            ) : (
                /* Container de Adicionar Item original para compras */
                <div className={`rounded-2xl border p-4 sm:p-5 bg-slate-50/50 dark:bg-slate-900/30 space-y-4 ${hasError ? 'border-red-500 ring-2 ring-red-500/15' : 'border-slate-200 dark:border-slate-800'}`}>
                    <div className="flex items-center gap-2 pb-2 border-b border-slate-200/60 dark:border-slate-800">
                        <i className="bi bi-plus-circle-fill text-emerald-600 text-sm" />
                        <h3 className="text-xs font-black uppercase tracking-widest text-slate-700 dark:text-slate-200">Adicionar Item</h3>
                    </div>
                    {hasError && <p className="text-xs font-bold text-red-500">Adicione pelo menos um item ao recebimento.</p>}
                    
                    <div className="grid grid-cols-1 sm:grid-cols-12 gap-3 items-end">
                        <div className="sm:col-span-6 flex flex-col gap-1.5">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Produto</label>
                            <ProductAutocomplete
                                supplierId={supplierId || undefined}
                                value={currentDescription}
                                onChange={setCurrentDescription}
                                disabled={Boolean(isReceiptMode && !supplierId)}
                                onSelect={(p, v) => {
                                    setCurrentProductId(p.id!);
                                    setCurrentVariationId(v?.id);
                                    const prodName = p.name || p.title || p.description;
                                    setCurrentDescription(v ? (v.name && v.name.toLowerCase().includes(prodName.toLowerCase()) ? v.name : `${prodName} - ${v.name}`) : prodName);
                                    
                                    if (v?.costPrice) setCurrentCost(v.costPrice);
                                    else if (p.costPrice) setCurrentCost(p.costPrice);
                                    else setCurrentCost(0);

                                    const prodSupplierId = p.mainSupplierId || p.supplierId || (p as any).main_supplier_id || (p as any).supplier_id;
                                    if (!supplierId && prodSupplierId && onSupplierAutoSelect) {
                                        onSupplierAutoSelect(prodSupplierId);
                                    }
                                }}                                 onSelectDescription={setCurrentDescription}
                                placeholder="Buscar produto..."
                                inputClassName="w-full bg-white dark:bg-slate-900 border-0 border-b-2 border-slate-200 dark:border-slate-700 p-2 focus:border-blue-600 dark:focus:border-blue-500 outline-none text-sm font-bold text-slate-700 dark:text-slate-300 transition-all focus:ring-0 rounded-none disabled:opacity-50 disabled:cursor-not-allowed"
                            />
                        </div>

                        <div className="sm:col-span-2 flex flex-col gap-1.5">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 text-center">Qtd</label>
                            <div className="flex bg-white dark:bg-slate-900 border-0 border-b-2 border-slate-200 dark:border-slate-700 p-1.5 focus-within:border-blue-600 transition-all items-center justify-center">
                                <input 
                                    type="number"
                                    placeholder="0"
                                    value={currentQty || ""}
                                    max={999}
                                    onChange={(e) => setCurrentQty(Math.min(999, Math.max(1, Number(e.target.value))))}
                                    className="w-full bg-transparent outline-none font-bold text-sm text-center border-none focus:ring-0 p-0 text-slate-700 dark:text-slate-300 rounded-none"
                                />
                                <span className="text-[10px] font-black text-slate-400 ml-1">un</span>
                            </div>
                        </div>

                        <div className="sm:col-span-3 flex flex-col gap-1.5">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 text-center">Custo unitário</label>
                            <CurrencyInput 
                                showBadge={false}
                                prefix="R$ "
                                placeholder="R$ 0,00"
                                value={currentCost || 0}
                                onChange={(val) => setCurrentCost(val)}
                                className="w-full bg-white dark:bg-slate-900 border-0 border-b-2 border-slate-200 dark:border-slate-700 p-2 focus:border-blue-600 dark:focus:border-blue-500 outline-none text-sm font-bold text-slate-700 dark:text-slate-300 transition-all text-center rounded-none"
                            />
                        </div>

                        <div className="sm:col-span-1 flex justify-end">
                            <button 
                                type="button"
                                onClick={handleAddItemClick}
                                className="py-2.5 px-3 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 transition-all active:scale-95 flex items-center justify-center gap-1.5 font-bold shadow-md text-xs w-full"
                            >
                                <i className="bi bi-plus-lg text-lg font-black" />
                                <span className="font-black uppercase tracking-wider">Adicionar</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}

