                                        {formatCurrency(itemSubtotal)}
                                    </span>
                                </div>

                                {/* Total do item final: Não-Editável -> Fundo Cinza */}
                                <div className="flex-1 min-w-fit p-2 sm:p-2.5 bg-slate-100/80 dark:bg-slate-800/60 rounded-xl border border-slate-200/80 dark:border-slate-700/80 flex flex-col justify-center">
                                    <span className="text-slate-400 uppercase tracking-wider text-[9px] font-black block mb-0.5 whitespace-nowrap">Total do item final</span>
                                    <span className="font-black text-slate-800 dark:text-slate-100 block text-sm leading-normal whitespace-nowrap">{formatCurrency(item.totalCost || 0)}</span>
                                </div>
                            </div>
                        </div>
                    );
                })}
                {items.length === 0 && (
                    <div className="text-center py-10 bg-white dark:bg-slate-955 border border-dashed border-slate-200 dark:border-slate-800 rounded-3xl p-6 flex flex-col items-center justify-center gap-2">
                        <i className="bi bi-box-seam text-2xl text-slate-300 dark:text-slate-600" />
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Nenhum item adicionado</p>
                        {isReceiptMode && supplierId && (
                            <button
                                type="button"
                                onClick={handleAddNewItemRow}
                                className="mt-1 text-xs font-black text-emerald-600 dark:text-emerald-400 hover:underline inline-flex items-center gap-1"
                            >
                                <i className="bi bi-plus-circle-fill" /> Clique para adicionar o primeiro item
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { DropdownPortal } from './DropdownPortal';
import { AddressSuggestionsMenu } from './AddressSuggestionsMenu';
import { searchAddressSuggestions, fetchPlaceDetails, normalizeUf } from '@/pages/utils/maps';

export interface AddressSelectedData {
    street: string;
    number?: string;
    neighborhood?: string;
    city?: string;
    state?: string;
    cep?: string;
    placeId?: string;
    coords?: [number, number];
    formattedAddress?: string;
}

interface Props {
    value: string;
    onChange: (street: string) => void;
    onSelectAddress: (data: AddressSelectedData) => void;
    cityHint?: string;
    stateHint?: string;
    label?: string;
    placeholder?: string;
    required?: boolean;
    routeUrl?: string;
    disabled?: boolean;
    className?: string;
    inputClassName?: string;
    showLabel?: boolean;
    variant?: 'default' | 'underline';
    hasError?: boolean;
    onBlur?: () => void;
}

export const AddressAutocompleteInput: React.FC<Props> = ({
    value,
    onChange,
    onSelectAddress,
    cityHint,
    stateHint = 'PR',
    label = 'Logradouro',
    placeholder = 'Ex: Rua das Flores, Avenida Brasil, Travessa, Marginal...',
    required = false,
    routeUrl,
    disabled = false,
    className = 'flex flex-col gap-2',
    inputClassName,
    showLabel = true,
    variant = 'default',
    hasError = false,
    onBlur,
}) => {
    const wrapperRef = useRef<HTMLDivElement>(null);
    const searchTimerRef = useRef<any>(null);
    const lastSearchValRef = useRef<string>('');

    const [suggestions, setSuggestions] = useState<any[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleInputChange = (val: string) => {
        onChange(val);
        lastSearchValRef.current = val;

        if (searchTimerRef.current) {
            clearTimeout(searchTimerRef.current);
        }

        if (val.trim().length >= 3) {
            setLoading(true);
            setIsOpen(true);

            searchTimerRef.current = setTimeout(async () => {
                try {
                    const results = await searchAddressSuggestions(val, cityHint, stateHint);
                    if (lastSearchValRef.current === val) {
                        setSuggestions(results);
                        setIsOpen(true);
                    }
                } catch {
                    if (lastSearchValRef.current === val) {
                        setSuggestions([]);
                        setIsOpen(true);
                    }
                } finally {
                    if (lastSearchValRef.current === val) {
                        setLoading(false);
                    }
                }
            }, 600);
        } else {
            setSuggestions([]);
            setIsOpen(false);
            setLoading(false);
        }
    };

    const handleSelectSuggestion = async (suggestion: any) => {
        setIsOpen(false);

        let streetName = suggestion.address?.road || suggestion.display_name.split(',')[0].split('-')[0].trim();
        let neighborhood = suggestion.address?.suburb || suggestion.address?.neighbourhood || '';
        let city = suggestion.address?.city || cityHint || 'Colombo';
        let state = normalizeUf(suggestion.address?.state || stateHint || 'PR');
        let cep = suggestion.address?.postcode || '';
        let number = '';
        let coords: [number, number] | undefined = undefined;

        // Disparo síncrono e imediato com os dados da sugestão (Rua, Bairro, Cidade, UF)
        onChange(streetName);
        onSelectAddress({
            street: streetName,
            number,
            neighborhood,
            city,
            state,
            cep,
            placeId: suggestion.place_id,
            coords,
            formattedAddress: suggestion.display_name,
        });

        // Enriquecimento assíncrono via Place Details (número, CEP, coords precisas)
        if (suggestion.place_id) {
            try {
                const details = await fetchPlaceDetails(suggestion.place_id);
                if (details) {
                    const refinedStreet = details.street || streetName;
                    const refinedNeighborhood = details.neighborhood || neighborhood;
                    const refinedCity = details.city || city;
                    const refinedState = normalizeUf(details.state || state);
                    const refinedCep = details.cep || cep;
                    const refinedNumber = details.number || number;
                    const refinedCoords = details.coords || coords;

                    if (refinedStreet !== streetName) {
                        onChange(refinedStreet);
                    }

                    onSelectAddress({
                        street: refinedStreet,
                        number: refinedNumber,
                        neighborhood: refinedNeighborhood,
                        city: refinedCity,
                        state: refinedState,
                        cep: refinedCep,
                        placeId: suggestion.place_id,
                        coords: refinedCoords,
                        formattedAddress: details.formattedAddress || suggestion.display_name,
                    });
                }
            } catch (e) {
                console.warn("AddressAutocompleteInput: erro ao buscar detalhes Places API:", e);
            }
        }
    };

    const resolvedInputClass = inputClassName || (
        variant === 'underline'
            ? `w-full border-b-2 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors dark:text-slate-300 ${hasError ? 'border-red-500 focus:border-red-500' : 'border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-500'}`
            : `w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border ${hasError ? 'border-red-500 ring-2 ring-red-500/20' : 'border-slate-100 dark:border-slate-800 focus:ring-2 focus:ring-blue-500'} rounded-2xl outline-none transition-all text-sm font-bold dark:text-slate-100 placeholder:text-slate-400 dark:placeholder:text-slate-600 placeholder:font-normal disabled:opacity-60`
    );

    return (
        <div className={className} ref={wrapperRef}>
            {showLabel && (
                <div className="flex items-center justify-between">
                    <label className={variant === 'underline' ? 'text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1 ml-1 block' : 'text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500'}>
                        {label} {required && <span className="text-red-500">*</span>}
                    </label>
                    {routeUrl && (
                        <a
                            href={routeUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex shrink-0 items-center gap-1 whitespace-nowrap text-[9px] font-black uppercase leading-none tracking-wider text-blue-600 transition-colors hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                            title="Ver rota no Google Maps"
                        >
                            <i className="bi bi-geo-alt-fill" />
                            <span>Rota</span>
                        </a>
                    )}
                </div>
            )}

            <div className="relative w-full">
                <input
                    type="text"
                    value={value || ''}
                    disabled={disabled}
                    onChange={(e) => handleInputChange(e.target.value)}
                    onFocus={() => {
                        if (suggestions.length > 0) setIsOpen(true);
                    }}
                    onBlur={onBlur}
                    placeholder={placeholder}
                    className={resolvedInputClass}
                />

                {loading && (
                    <div className="absolute right-3.5 top-1/2 -translate-y-1/2 pointer-events-none">
                        <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />
                    </div>
                )}
            </div>

            <DropdownPortal anchorRef={wrapperRef} isOpen={isOpen}>
                <AddressSuggestionsMenu
                    suggestions={suggestions}
                    loading={loading}
                    onSelect={(s) => void handleSelectSuggestion(s)}
                />
            </DropdownPortal>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { getSettings, AppSettings, subscribeToSettings } from '@/pages/utils/settingsService';
import { toast } from 'react-toastify';
import { GeminiAgentService } from '@/services/aiAgent/geminiAgentService';
import { GeminiContent, ExecutedToolRecord, AgentPageContext } from '@/services/aiAgent/geminiAgentTypes';

interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: Date;
  executedTools?: ExecutedToolRecord[];
}

export interface AIChatAssistantProps {
  isFloating?: boolean;
  forceOpen?: boolean;
  isOpen?: boolean;
  onClose?: () => void;
  mode?: 'drawer' | 'floating';
}

const STORAGE_KEY = 'lisandro_chat_history_v2';
const HISTORY_RAW_KEY = 'lisandro_gemini_raw_history_v2';
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

export default function AIChatAssistant({
  isFloating = false,
  isOpen: controlledIsOpen,
  onClose: controlledOnClose,
  mode = 'drawer',
}: AIChatAssistantProps) {
  const location = useLocation();
  const [internalIsOpen, setInternalIsOpen] = useState(false);
  const isOpen = controlledIsOpen !== undefined ? controlledIsOpen : internalIsOpen;

  const handleClose = () => {
    if (controlledOnClose) {
      controlledOnClose();
    } else {
      setInternalIsOpen(false);
    }
  };

  useEffect(() => {
    const handleGlobalOpen = () => {
      setInternalIsOpen(true);
    };
    window.addEventListener('morante:open-agent', handleGlobalOpen);
    return () => window.removeEventListener('morante:open-agent', handleGlobalOpen);
  }, []);

  const getPageContext = (): AgentPageContext => {
    const path = location.pathname;
    let currentModule = 'Geral';
    if (path.startsWith('/finance')) currentModule = 'Financeiro';
    else if (path.startsWith('/estoque') || path.startsWith('/inventory')) currentModule = 'Estoque';
    else if (path.startsWith('/orders') || path.startsWith('/pedidos')) currentModule = 'Vendas & Pedidos';
    else if (path.startsWith('/purchases') || path.startsWith('/compras')) currentModule = 'Compras';
    else if (path.startsWith('/customers') || path.startsWith('/clientes')) currentModule = 'Clientes';
    else if (path.startsWith('/deliveries') || path.startsWith('/logistica')) currentModule = 'Logística & Entregas';
    else if (path.startsWith('/catalog')) currentModule = 'Catálogo Digital';
    else if (path === '/' || path === '/dashboard') currentModule = 'Dashboard';

    const segments = path.split('/').filter(Boolean);
    const pageName = segments.length > 1 ? segments.slice(1).join('/') : segments[0] || 'Início';

    return {
      currentModule,
      currentPage: pageName,
      currentPath: path,
    };
  };

  const [settings, setSettings] = useState<AppSettings>(getSettings());

  useEffect(() => {
    const unsubscribe = subscribeToSettings(newSettings => setSettings(newSettings));
    return () => unsubscribe();
  }, []);

  const aiName = settings.aiPrompts?.aiName || 'Seu Lizandro';
  const aiAvatar = settings.aiPrompts?.aiAvatar || '/lizandro.png';

  const [messages, setMessages] = useState<ChatMessage[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    const initial: ChatMessage = {
      id: 'init',
      role: 'assistant',
      content: `Olá! Sou ${aiName}, seu Agente Inteligente do ERP. Posso lançar despesas, receitas, consultar o fluxo de caixa ou tirar dúvidas do sistema. Como posso te ajudar hoje?`,
      timestamp: new Date(),
    };
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        const now = Date.now();
        const recent = parsed
          .filter((m: any) => now - new Date(m.timestamp).getTime() < SEVEN_DAYS_MS)
          .map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) }));
        return recent.length > 0 ? recent : [initial];
      } catch {
        return [initial];
      }
    }
    return [initial];
  });

  const [geminiHistory, setGeminiHistory] = useState<GeminiContent[]>(() => {
    const saved = localStorage.getItem(HISTORY_RAW_KEY);
    if (saved) {
      try { return JSON.parse(saved); } catch { return []; }
    }
    return [];
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
  }, [messages]);

  useEffect(() => {
    localStorage.setItem(HISTORY_RAW_KEY, JSON.stringify(geminiHistory));
  }, [geminiHistory]);

  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isCallMode, setIsCallMode] = useState(false);
  const [isAutoSpeakEnabled, setIsAutoSpeakEnabled] = useState(() => localStorage.getItem('lisandro_auto_speak') === 'true');

  const scrollRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<any>(null);
  const silenceTimerRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem('lisandro_auto_speak', String(isAutoSpeakEnabled));
  }, [isAutoSpeakEnabled]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = true;
      recognitionRef.current.lang = 'pt-BR';
      recognitionRef.current.interimResults = true;

      recognitionRef.current.onresult = (event: any) => {
        window.speechSynthesis?.cancel();
        let interimTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            const transcript = event.results[i][0].transcript;
            setInput(prev => {
              const newText = (prev + ' ' + transcript).trim();
              if (isCallMode) {
                if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
                silenceTimerRef.current = setTimeout(() => handleSendMessage(newText), 1200);
              }
              return newText;
            });
          } else {
            interimTranscript += event.results[i][0].transcript;
          }
        }
      };

      recognitionRef.current.onstart = () => {
        setIsListening(true);
        window.speechSynthesis?.cancel();
      };

      recognitionRef.current.onerror = (event: any) => {
        if (event.error === 'no-speech') return;
        setIsListening(false);
        setIsCallMode(false);
        toast.error('Erro no microfone ou reconhecimento de voz.');
      };

      recognitionRef.current.onend = () => {
        if (isCallMode) {
          try { recognitionRef.current.start(); } catch {}
        } else {
          setIsListening(false);
        }
      };
    }
  }, [isCallMode]);

  const toggleListening = () => {
    if (isListening) {
      setIsCallMode(false);
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      if (!recognitionRef.current) {
        toast.error('Reconhecimento de voz não suportado neste navegador.');
        return;
      }
      recognitionRef.current.start();
    }
  };

  const toggleCallMode = () => {
    if (isCallMode) {
      setIsCallMode(false);
      recognitionRef.current?.stop();
    } else {
      setIsCallMode(true);
      setIsAutoSpeakEnabled(true);
      if (!isListening) recognitionRef.current?.start();
    }
  };

  const speak = (text: string) => {
    if (!isAutoSpeakEnabled || !window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const cleanText = text.replace(/[*#_`]/g, '').trim();
    const utterance = new SpeechSynthesisUtterance(cleanText);
    utterance.lang = 'pt-BR';
    utterance.rate = 1.3;
    utterance.pitch = 0.9;

    const voices = window.speechSynthesis.getVoices();
    const naturalVoice = voices.find(v => v.lang.includes('pt-BR') && (v.name.includes('Daniel') || v.name.includes('Google')));
    if (naturalVoice) utterance.voice = naturalVoice;

    window.speechSynthesis.speak(utterance);
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isOpen, isLoading]);

  const handleSendMessage = async (textToSend?: string) => {
    const text = (textToSend || input).trim();
    if (!text || isLoading) return;

    const userMsg: ChatMessage = {
      id: `u-${Date.now()}`,
      role: 'user',
      content: text,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

    const pageCtx = getPageContext();

    try {
      const response = await GeminiAgentService.sendMessage(text, geminiHistory, pageCtx);
      setGeminiHistory(response.updatedHistory);

      const assistantMsg: ChatMessage = {
        id: `a-${Date.now()}`,
        role: 'assistant',
        content: response.result.answer,
        timestamp: new Date(),
        executedTools: response.result.executedTools,
      };

      setMessages(prev => [...prev, assistantMsg]);
      speak(response.result.answer);
    } catch (err: any) {
      console.error('Erro no assistente Gemini:', err);
      const errMsg = err?.message || 'Erro ao processar mensagem com a IA.';
      toast.error(errMsg);
      setMessages(prev => [
        ...prev,
        {
          id: `err-${Date.now()}`,
          role: 'assistant',
          content: `Desculpe, ocorreu um erro: ${errMsg}`,
          timestamp: new Date(),
        },
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClearHistory = () => {
    if (window.confirm('Deseja limpar o histórico da conversa com o assistente?')) {
      const initial: ChatMessage = {
        id: 'init',
        role: 'assistant',
        content: `Olá! Sou ${aiName}, seu Agente Inteligente do ERP. Posso lançar despesas, receitas, consultar o fluxo de caixa ou tirar dúvidas do sistema. Como posso te ajudar hoje?`,
        timestamp: new Date(),
      };
      setMessages([initial]);
      setGeminiHistory([]);
      localStorage.removeItem(STORAGE_KEY);
      localStorage.removeItem(HISTORY_RAW_KEY);
    }
  };

  const activePageContext = getPageContext();

  // Modo Drawer Lateral Global (Slide-over panel)
  if (mode === 'drawer') {
    if (!isOpen) return null;

    return (
      <div className="fixed inset-0 z-[99999] flex justify-end" data-testid="agent-drawer-root">
        {/* Backdrop escuro e suave */}
        <div
          onClick={handleClose}
          className="fixed inset-0 bg-slate-950/40 backdrop-blur-sm transition-opacity"
        />

        {/* Painel do Drawer */}
        <div className="relative w-full sm:w-[480px] md:w-[520px] h-full bg-white dark:bg-slate-900 border-l border-slate-200 dark:border-slate-800 shadow-2xl flex flex-col z-10">
          {/* Header */}
          <header className="p-4 sm:p-5 bg-gradient-to-r from-indigo-600 via-indigo-500 to-blue-600 text-white flex items-center justify-between relative overflow-hidden shrink-0 shadow-md">
            <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full -mr-16 -mt-16 blur-3xl pointer-events-none"></div>
            <div className="flex items-center gap-3 relative z-10">
              <div className="w-11 h-11 rounded-2xl bg-white/20 backdrop-blur-md border border-white/30 flex items-center justify-center overflow-hidden shadow-lg">
                {aiAvatar ? (
                  <img src={aiAvatar} alt={aiName} className="w-full h-full object-cover" />
                ) : (
                  <i className="bi bi-robot text-2xl text-white"></i>
                )}
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <h4 className="font-black text-base sm:text-lg tracking-tight leading-none text-white">{aiName}</h4>
                  <span className="px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-white/20 text-white border border-white/30">
                    Agente ERP
                  </span>
                </div>
                <div className="flex items-center gap-2 mt-1">
                  <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse shadow-[0_0_8px_rgba(52,211,153,0.6)]"></span>
                  <span className="text-[10px] text-white/90 font-medium truncate max-w-[220px]">
                    Tela: {activePageContext.currentModule}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-1.5 relative z-10">
              <button
                onClick={toggleCallMode}
                className={`w-8 h-8 sm:w-9 sm:h-9 rounded-xl transition-all flex items-center justify-center ${isCallMode ? 'bg-white text-red-600 shadow-lg' : 'bg-white/15 hover:bg-white/25 text-white'}`}
                title={isCallMode ? 'Desligar Chamada' : 'Iniciar Chamada de Voz'}
              >
                <i className={`bi ${isCallMode ? 'bi-telephone-fill' : 'bi-telephone'} text-sm sm:text-base`}></i>
              </button>
              <button
                onClick={handleClearHistory}
                className="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-white/15 hover:bg-white/25 text-white flex items-center justify-center transition-all"
                title="Limpar histórico da conversa"
              >
                <i className="bi bi-trash3 text-sm sm:text-base"></i>
              </button>
              <button
                onClick={handleClose}
                data-testid="agent-drawer-close"
                className="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-white/15 hover:bg-white/25 text-white flex items-center justify-center transition-all"
                title="Fechar assistente"
              >
                <i className="bi bi-x-lg text-sm sm:text-base"></i>
              </button>
            </div>
          </header>

          {/* Messages Feed */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 sm:p-5 flex flex-col gap-4 custom-scrollbar bg-slate-50/50 dark:bg-slate-950/30">
            {messages.map(msg => (
              <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                <div className={`flex gap-3 max-w-[92%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                  {msg.role === 'assistant' && (
                    <div className="w-8 h-8 rounded-xl bg-indigo-100 dark:bg-indigo-900/50 flex flex-shrink-0 items-center justify-center overflow-hidden mt-1 shadow-sm">
                      {aiAvatar ? (
                        <img src={aiAvatar} alt={aiName} className="w-full h-full object-cover" />
                      ) : (
                        <i className="bi bi-robot text-indigo-600 dark:text-indigo-400 text-sm"></i>
                      )}
                    </div>
                  )}

                  <div className="flex flex-col gap-2">
                    {/* Tool execution badges */}
                    {msg.executedTools && msg.executedTools.length > 0 && (
                      <div className="flex flex-col gap-1.5 mb-1">
                        {msg.executedTools.map((tool, tIdx) => (
                          <div
                            key={tIdx}
                            className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[10px] font-bold border transition-all ${
                              tool.success
                                ? 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-800/40'
                                : 'bg-rose-50 text-rose-700 border-rose-200 dark:bg-rose-950/40 dark:text-rose-400 dark:border-rose-800/40'
