import React, { useState, useEffect } from 'react';
import Person from '../../../types/person.type';
import { UserRole } from '@/context/AuthContext';
import { roleLabel } from '@/pages/utils/accessRoles';
import PersonFormModal from '../../Registrations/shared/modals/PersonFormModal';
import { updatePerson } from '@/pages/utils/personService';
import { toast } from 'react-toastify';

interface Props {
  people: Person[];
  loading: boolean;
  onRefresh: () => void;
}

const ROLE_BADGE_STYLES: Record<UserRole, { bg: string; text: string; icon: string }> = {
  administrator: { bg: 'bg-blue-50 dark:bg-blue-950/40 border-blue-200 dark:border-blue-800', text: 'text-blue-700 dark:text-blue-300', icon: 'bi-shield-shaded' },
  manager: { bg: 'bg-amber-50 dark:bg-amber-950/40 border-amber-200 dark:border-amber-800', text: 'text-amber-700 dark:text-amber-300', icon: 'bi-briefcase-fill' },
  stockist: { bg: 'bg-teal-50 dark:bg-teal-950/40 border-teal-200 dark:border-teal-800', text: 'text-teal-700 dark:text-teal-300', icon: 'bi-boxes' },
  seller: { bg: 'bg-emerald-50 dark:bg-emerald-950/40 border-emerald-200 dark:border-emerald-800', text: 'text-emerald-700 dark:text-emerald-300', icon: 'bi-tag-fill' },
  deliverer: { bg: 'bg-purple-50 dark:bg-purple-950/40 border-purple-200 dark:border-purple-800', text: 'text-purple-700 dark:text-purple-300', icon: 'bi-truck' },
  accountant: { bg: 'bg-indigo-50 dark:bg-indigo-950/40 border-indigo-200 dark:border-indigo-800', text: 'text-indigo-700 dark:text-indigo-300', icon: 'bi-calculator' },
  pending: { bg: 'bg-rose-50 dark:bg-rose-950/40 border-rose-200 dark:border-rose-800', text: 'text-rose-700 dark:text-rose-300', icon: 'bi-slash-circle' },
};

export const UsersTab: React.FC<Props> = ({ people, loading, onRefresh }) => {
  const [search, setSearch] = useState('');
  const [selectedRole, setSelectedRole] = useState<string>('all');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingPerson, setEditingPerson] = useState<Person | null>(null);

  // Pagination states
  const [pageWithRole, setPageWithRole] = useState(1);
  const [pageWithoutRole, setPageWithoutRole] = useState(1);
  const ITEMS_PER_PAGE = 10;

  // Reset pagination on filter change
  useEffect(() => {
    setPageWithRole(1);
    setPageWithoutRole(1);
  }, [search, selectedRole]);

  const filteredPeople = people.filter((p) => {
    const term = search.toLowerCase().trim();
    const matchesSearch = !term ||
      (p.fullName || '').toLowerCase().includes(term) ||
      (p.email || '').toLowerCase().includes(term) ||
      (p.phone || '').includes(term);

    const rolesList = p.roles && p.roles.length > 0 ? p.roles : (p.role ? [p.role] : ['pending']);
    const matchesRole = selectedRole === 'all' || rolesList.includes(selectedRole as UserRole);

    return matchesSearch && matchesRole;
  });

  const isSemAcesso = (p: Person) => {
      const rolesList = p.roles && p.roles.length > 0 ? p.roles : (p.role ? [p.role] : ['pending']);
      return rolesList.includes('pending') || rolesList.includes('sem acesso' as any);
  };

  const usersWithRole = filteredPeople.filter(p => !isSemAcesso(p));
  const usersWithoutRole = filteredPeople.filter(p => isSemAcesso(p));

  const handleOpenAdd = () => {
    setEditingPerson(null);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (person: Person) => {
    setEditingPerson(person);
    setIsModalOpen(true);
  };

  const handleToggleActive = async (person: Person) => {
    try {
      await updatePerson('employees', String(person.id), { active: !person.active });
      toast.success(person.active ? 'Colaborador inativado.' : 'Colaborador ativado.');
      onRefresh();
    } catch (err) {
      toast.error('Erro ao alterar status.');
    }
  };

  // Helper render method for tables
  const renderTable = (data: Person[], title: string, page: number, setPage: (p: number) => void) => {
    if (data.length === 0) return null;

    const totalPages = Math.ceil(data.length / ITEMS_PER_PAGE);
    const paginatedData = data.slice((page - 1) * ITEMS_PER_PAGE, page * ITEMS_PER_PAGE);

    return (
      <div className="mb-6 overflow-hidden rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 shadow-sm">
        <div className="px-4 py-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950">
          <h3 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-wide">{title} <span className="text-slate-400 font-medium normal-case text-xs ml-2">({data.length})</span></h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs border-collapse">
            <thead>
              <tr className="border-b border-slate-100 dark:border-slate-800 bg-slate-50/60 dark:bg-slate-950/40 text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">
                <th className="py-3.5 px-4">Usuário / Colaborador</th>
                <th className="py-3.5 px-4">Perfis de Acesso</th>
                <th className="py-3.5 px-4 hidden md:table-cell">Telefone</th>
                <th className="py-3.5 px-4 hidden lg:table-cell">Endereço</th>
                <th className="py-3.5 px-4 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-800/60">
              {paginatedData.map((person) => {
                const rolesList = person.roles && person.roles.length > 0 ? person.roles : (person.role ? [person.role] : ['pending']);
                const initials = (person.fullName || person.email || 'U').substring(0, 2).toUpperCase();

                return (
                  <tr key={person.id} className="hover:bg-slate-50/70 dark:hover:bg-slate-800/40 transition-colors">
                    {/* Usuário e Email */}
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-3">
                        <div className="w-9 h-9 rounded-xl bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300 flex items-center justify-center font-black text-xs shrink-0 shadow-xs">
                          {initials}
                        </div>
                        <div className="min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <p className="font-bold text-slate-800 dark:text-slate-100 truncate">{person.fullName || 'Sem nome'}</p>
                            {person.position && (
                              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200/60 dark:border-slate-700/60">
                                <i className="bi bi-briefcase text-[9px] text-slate-400" />
                                {person.position}
                              </span>
                            )}
                          </div>
                          <p className="text-[11px] text-slate-400 dark:text-slate-500 truncate">{person.email}</p>
                        </div>
                      </div>
                    </td>

                    {/* Cargos */}
                    <td className="py-3 px-4">
                      <div className="flex flex-wrap gap-1.5">
                        {rolesList.map((r) => {
                          const badge = ROLE_BADGE_STYLES[r as UserRole] || ROLE_BADGE_STYLES.pending;
                          return (
                            <span
                              key={r}
                              className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider border ${badge.bg} ${badge.text}`}
                            >
                              <i className={`bi ${badge.icon} text-[10px]`} />
                              {roleLabel(r as UserRole)}
                            </span>
                          );
                        })}
                      </div>
                    </td>

                    {/* Telefone */}
                    <td className="py-3 px-4 hidden md:table-cell text-slate-600 dark:text-slate-300 font-medium">
                      {person.phone || '-'}
                    </td>

                    {/* Endereço */}
                    <td className="py-3 px-4 hidden lg:table-cell text-slate-500 dark:text-slate-400 text-[11px]">
                      {person.fullAddress?.street ? (
                        <span className="truncate block max-w-xs">{person.fullAddress.street}, {person.fullAddress.number} - {person.fullAddress.city}</span>
                      ) : (
                        <span className="text-slate-300 dark:text-slate-600 italic">Não informado</span>
                      )}
                    </td>



                    {/* Ações */}
                    <td className="py-3 px-4 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <button
                          type="button"
                          onClick={() => handleOpenEdit(person)}
                          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold text-blue-600 bg-blue-50 dark:bg-blue-900/30 hover:bg-blue-100 dark:hover:bg-blue-900/50 transition-all cursor-pointer"
                          title="Editar dados e perfis de acesso do usuário"
                        >
                          <i className="bi bi-person-gear text-sm" />
                          <span>Definir Perfis / Editar</span>
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        {/* Paginação */}
        {totalPages > 1 && (
          <div className="px-4 py-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-950/50">
            <span className="text-xs text-slate-500 font-medium">Página {page} de {totalPages}</span>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => setPage(Math.max(1, page - 1))}
                disabled={page === 1}
                className="px-3 py-1.5 rounded-lg text-xs font-bold border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 disabled:opacity-50 transition-colors hover:bg-slate-50 dark:hover:bg-slate-700"
              >
                Anterior
              </button>
              <button
                type="button"
                onClick={() => setPage(Math.min(totalPages, page + 1))}
                disabled={page === totalPages}
                className="px-3 py-1.5 rounded-lg text-xs font-bold border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 disabled:opacity-50 transition-colors hover:bg-slate-50 dark:hover:bg-slate-700"
              >
                Próxima
              </button>
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-4">
      {/* Barra Superior: Busca, Filtros de Cargo e Botão Novo */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 shadow-sm">
        <div className="flex flex-1 items-center gap-2 bg-slate-50 dark:bg-slate-950 px-3 py-2 rounded-xl border border-slate-200/80 dark:border-slate-800">
          <i className="bi bi-search text-slate-400 text-sm" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nome, e-mail ou telefone..."
            className="bg-transparent text-xs font-semibold text-slate-700 dark:text-slate-200 outline-none w-full placeholder-slate-400"
          />
          {search && (
            <button onClick={() => setSearch('')} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 text-xs">
              <i className="bi bi-x-circle-fill" />
            </button>
          )}
        </div>

        <div className="flex items-center gap-2">
          <select
            value={selectedRole}
            onChange={(e) => setSelectedRole(e.target.value)}
            className="px-3 py-2 rounded-xl text-xs font-bold border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-200 outline-none cursor-pointer"
          >
            <option value="all">Todos os Perfis de Acesso</option>
            <option value="administrator">Administrador</option>
            <option value="manager">Gestor</option>
            <option value="stockist">Estoquista</option>
            <option value="seller">Vendedor</option>
            <option value="deliverer">Entregador / Montador</option>
            <option value="pending">Sem Acesso</option>
          </select>

          <button
            type="button"
            onClick={handleOpenAdd}
            className="flex items-center gap-1.5 px-3.5 py-2 rounded-xl text-xs font-black uppercase tracking-wider bg-blue-600 hover:bg-blue-700 text-white shadow-sm shadow-blue-600/25 transition-all active:scale-95 cursor-pointer whitespace-nowrap"
          >
            <i className="bi bi-person-plus-fill" />
            <span>Novo Colaborador</span>
          </button>
        </div>
      </div>

      {loading ? (
        <div className="overflow-hidden rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 shadow-sm py-16 text-center">
          <div className="mx-auto h-8 w-8 animate-spin rounded-full border-2 border-blue-600/30 border-t-blue-600" />
          <p className="text-xs text-slate-400 mt-3 font-bold">Carregando usuários...</p>
        </div>
      ) : filteredPeople.length === 0 ? (
        <div className="overflow-hidden rounded-2xl bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 shadow-sm py-16 text-center space-y-2">
          <i className="bi bi-people text-4xl text-slate-300 dark:text-slate-600" />
          <p className="text-sm font-bold text-slate-600 dark:text-slate-300">Nenhum usuário ou colaborador encontrado</p>
          <p className="text-xs text-slate-400">Tente ajustar os termos de busca ou filtros.</p>
        </div>
      ) : (
        <>
          {renderTable(usersWithRole, "Usuários com Cargo", pageWithRole, setPageWithRole)}
          {renderTable(usersWithoutRole, "Sem Cargo", pageWithoutRole, setPageWithoutRole)}
        </>
      )}

      {/* Modal de Edição com Atribuição de Perfis */}
      {isModalOpen && (
        <PersonFormModal
          isOpen={isModalOpen}
          onClose={() => { setIsModalOpen(false); setEditingPerson(null); }}
          onSuccess={() => { setIsModalOpen(false); setEditingPerson(null); onRefresh(); }}
          person={editingPerson}
          collectionName="employees"
          title={editingPerson ? "Editar Usuário e Perfis de Acesso" : "Colaborador"}
        />
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { ApiConfiguration } from '@/services/apiMonitoring/apiMonitoringTypes';
import { ApiConfigService } from '@/services/apiMonitoring/apiConfigService';
import { ApiUsageGuard } from '@/services/apiMonitoring/apiUsageGuard';
import { toast } from 'react-toastify';

interface ApiConfigEditModalProps {
    config: ApiConfiguration;
    isOpen: boolean;
    onClose: () => void;
    onSaved: () => void;
}

export default function ApiConfigEditModal({ config, isOpen, onClose, onSaved }: ApiConfigEditModalProps) {
    const [formData, setFormData] = useState<ApiConfiguration>({ ...config });
    const [saving, setSaving] = useState(false);

    if (!isOpen) return null;

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);
        try {
            const success = await ApiConfigService.saveConfiguration(formData);
            if (success) {
                ApiUsageGuard.clearCache(formData.service_id);
                toast.success(`Configurações de ${formData.service_name} salvas com sucesso!`);
                onSaved();
                onClose();
            } else {
                toast.error("Erro ao salvar configuração.");
            }
        } catch (err: any) {
            toast.error(err.message || "Erro ao salvar.");
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[9999999] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-white dark:bg-slate-900 rounded-3xl max-w-lg w-full p-6 shadow-2xl border border-slate-200 dark:border-slate-800 animate-reveal">
                {/* Header */}
                <div className="flex items-center justify-between pb-4 border-b border-slate-100 dark:border-slate-800">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-2xl bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 flex items-center justify-center">
                            <i className="bi bi-sliders2 text-lg" />
                        </div>
                        <div>
                            <h3 className="text-base font-black text-slate-900 dark:text-slate-100">
                                {formData.service_name}
                            </h3>
                            <p className="text-xs font-bold text-slate-400">
                                Configurações de Limites e Custos
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="w-8 h-8 rounded-full flex items-center justify-center text-slate-400 hover:text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                    >
                        <i className="bi bi-x-lg text-sm" />
                    </button>
                </div>

                <form onSubmit={handleSave} className="space-y-4 pt-4">
                    {/* Status Ativo / Inativo */}
                    <div className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200/60 dark:border-slate-800">
                        <div>
                            <div className="text-xs font-black text-slate-800 dark:text-slate-200">Integração Ativa</div>
                            <div className="text-[11px] text-slate-400">Habilita ou suspende as chamadas externas deste serviço</div>
                        </div>
                        <input
                            type="checkbox"
                            checked={formData.enabled}
                            onChange={e => setFormData({ ...formData, enabled: e.target.checked })}
                            className="w-5 h-5 rounded text-blue-600 focus:ring-blue-500 cursor-pointer"
                        />
                    </div>

                    {/* Limite Mensal e Franquia */}
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="block text-[11px] font-black uppercase text-slate-500 mb-1">
                                Limite Mensal ({formData.billing_unit})
                            </label>
                            <input
                                type="number"
                                min={0}
                                value={formData.monthly_limit}
                                onChange={e => setFormData({ ...formData, monthly_limit: Number(e.target.value) })}
                                className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-[11px] font-black uppercase text-slate-500 mb-1">
                                Franquia Gratuita
                            </label>
                            <input
                                type="number"
                                min={0}
                                value={formData.free_allowance}
                                onChange={e => setFormData({ ...formData, free_allowance: Number(e.target.value) })}
                                className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100"
                            />
                        </div>
                    </div>

                    {/* Thresholds: Aviso, Crítico, Hard Limit */}
                    <div className="grid grid-cols-3 gap-2">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-amber-600 mb-1">
                                Aviso (%)
                            </label>
                            <input
                                type="number"
                                min={1}
                                max={100}
                                value={formData.warning_threshold}
                                onChange={e => setFormData({ ...formData, warning_threshold: Number(e.target.value) })}
                                className="w-full px-2 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100 text-center"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-rose-500 mb-1">
                                Crítico (%)
                            </label>
                            <input
                                type="number"
                                min={1}
                                max={100}
                                value={formData.critical_threshold}
                                onChange={e => setFormData({ ...formData, critical_threshold: Number(e.target.value) })}
                                className="w-full px-2 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100 text-center"
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-rose-700 dark:text-rose-400 mb-1">
                                Hard Limit (%)
                            </label>
                            <input
                                type="number"
                                min={1}
                                max={100}
                                value={formData.hard_limit}
                                onChange={e => setFormData({ ...formData, hard_limit: Number(e.target.value) })}
                                className="w-full px-2 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100 text-center"
                                required
                            />
                        </div>
                    </div>

                    {/* Bloqueio no Hard Limit */}
                    <div className="flex items-center justify-between p-3 rounded-2xl bg-rose-50/60 dark:bg-rose-950/20 border border-rose-200 dark:border-rose-900/40">
                        <div>
                            <div className="text-xs font-black text-rose-800 dark:text-rose-300">
                                Bloqueio Preventivo (Hard Limit)
                            </div>
                            <div className="text-[11px] text-rose-600/80 dark:text-rose-400">
                                Suspende novas chamadas não críticas antes de gerar cobrança comercial
                            </div>
                        </div>
                        <input
                            type="checkbox"
                            checked={formData.block_on_hard_limit}
                            disabled={formData.criticality === 'CRITICAL'}
                            onChange={e => setFormData({ ...formData, block_on_hard_limit: e.target.checked })}
                            className="w-5 h-5 rounded text-rose-600 focus:ring-rose-500 cursor-pointer"
                        />
                    </div>

                    {/* Preço por Unidade e Moeda */}
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="block text-[11px] font-black uppercase text-slate-500 mb-1">
                                Preço por Unidade
                            </label>
                            <input
                                type="number"
                                step="0.0001"
                                min={0}
                                value={formData.price_per_unit}
                                onChange={e => setFormData({ ...formData, price_per_unit: Number(e.target.value) })}
                                className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100"
                            />
                        </div>
                        <div>
                            <label className="block text-[11px] font-black uppercase text-slate-500 mb-1">
                                Moeda
                            </label>
                            <select
                                value={formData.currency}
                                onChange={e => setFormData({ ...formData, currency: e.target.value as 'BRL' | 'USD' })}
                                className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100"
                            >
                                <option value="BRL">Real (BRL - R$)</option>
                                <option value="USD">Dólar (USD - $)</option>
                            </select>
                        </div>
                    </div>

                    {/* Circuit Breaker (Teto por Minuto) */}
                    <div>
                        <label className="block text-[11px] font-black uppercase text-slate-500 mb-1">
                            Circuit Breaker (Máx. chamadas/minuto)
                        </label>
                        <input
                            type="number"
                            min={10}
                            value={formData.circuit_breaker_max_per_minute}
                            onChange={e => setFormData({ ...formData, circuit_breaker_max_per_minute: Number(e.target.value) })}
                            className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-xs font-bold text-slate-800 dark:text-slate-100"
                            required
                        />
                        <p className="text-[10px] text-slate-400 mt-1">
                            Proteção automática contra loops acidentais ou bugs no frontend/mobile.
                        </p>
                    </div>

                    {/* Botões */}
                    <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800">
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-4 py-2 rounded-xl text-xs font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={saving}
                            className="px-5 py-2 rounded-xl text-xs font-black bg-blue-600 hover:bg-blue-700 text-white shadow-md shadow-blue-500/20 transition-all flex items-center gap-2"
                        >
                            {saving ? (
                                <>
                                    <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                    <span>Salvando...</span>
                                </>
                            ) : (
                                <span>Salvar Configuração</span>
                            )}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

import React, { useEffect, useRef, useState, useMemo } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import Order from '@/pages/types/order.type';
import { geocodeAddress, getNeighborhoodCoords } from '@/pages/utils/maps';

interface ProfitHeatMapProps {
    orders: Order[];
}

type MetricType = 'value' | 'count';

export const ProfitHeatMap: React.FC<ProfitHeatMapProps> = ({ orders }) => {
    const mapContainer = useRef<HTMLDivElement>(null);
    const map = useRef<maplibregl.Map | null>(null);
    const [metric, setMetric] = useState<MetricType>('value');
    const [opacity, setOpacity] = useState(0.8);
    const [isLoaded, setIsLoaded] = useState(false);
    const [ordersWithCoords, setOrdersWithCoords] = useState<Record<string, [number, number]>>({});

    // Efeito para Geocodificação em Segundo Plano
    useEffect(() => {
        const fetchMissingCoords = async () => {
            const newCoords = { ...ordersWithCoords };
            let updated = false;

            // Filtra pedidos que não tem coordenadas e ainda não foram processados nesta sessão
            const toGeocode = orders.filter(o => 
                o.id && 
                !o.shipping?.destinationCoords && 
                !newCoords[o.id]
            ).slice(0, 50); // Aumentado limite para 50 para cobrir mais do período

            if (toGeocode.length === 0) return;

            for (const order of toGeocode) {
                if (!order.id) continue;
                const fullAddr = order.customerData?.fullAddress;
                // Exige rua para tentar geocodificar
                if (!fullAddr?.street) continue;

                try {
                    // Tenta geocodificar usando Rua, Número, Bairro e Cidade
                    const geoRes = await geocodeAddress(fullAddr);
                    if (geoRes) {
                        newCoords[order.id] = geoRes.coords;
                        updated = true;
                    }
                } catch (e) {
                    console.warn(`Erro ao geocodificar pedido ${order.id}:`, e);
                }
                
                // Pequeno delay entre requisições de geocodificação
                await new Promise(r => setTimeout(r, 250));
            }

            if (updated) {
                setOrdersWithCoords(newCoords);
            }
        };

        // Inicia após carregar o mapa
        const timer = setTimeout(fetchMissingCoords, 2500);
        return () => clearTimeout(timer);
    }, [orders, ordersWithCoords]);

    // Converte ordens em GeoJSON para MapLibre
    const geoJsonData = useMemo(() => {
        const features = orders.map(order => {
            const fullAddr = order.customerData?.fullAddress;
            const neighborhood = (fullAddr?.neighborhood || '').toUpperCase().trim();
            const city = (fullAddr?.city || '').toUpperCase().trim();
            
            // Ordem de prioridade de Coordenadas:
            // 1. Coordenadas salvas no pedido
            // 2. Coordenadas encontradas pela geocodificação dinâmica
            // 3. Fallback de bairro/cidade via utilitário global
            let finalCoords: [number, number];
            
            if (order.shipping?.destinationCoords && order.shipping.destinationCoords[0] !== 0) {
                finalCoords = order.shipping.destinationCoords;
            } else if (ordersWithCoords[order.id || '']) {
                const c = ordersWithCoords[order.id || ''];
                finalCoords = [c[0], c[1]];
            } else {
                const fall = getNeighborhoodCoords(neighborhood, city);
                finalCoords = fall ? [fall.lng, fall.lat] : [-49.2671, -25.4290];
            }
            
            // Jittering inteligente (evita sobreposição total de pontos no mesmo local)
            const addrNumber = fullAddr?.number ? parseInt(fullAddr.number.replace(/\D/g, '')) : 0;
            const seed = (order.id || '').length + addrNumber + (fullAddr?.street || '').length;
            
            // Jittering ultra-reduzido para pontos precisos, mantendo o ponto na rua correta
            const isPrecision = (order.shipping?.destinationCoords || ordersWithCoords[order.id || '']);
            const jitterScale = isPrecision ? 0.00005 : 0.0006;
            const jitterLat = ((seed % 20) - 10) * jitterScale;
            const jitterLng = ((Math.floor(seed / 5) % 20) - 10) * jitterScale;

            const totalValue = order.itemsSummary?.itemsTotalValue || 0;

            return {
                type: 'Feature',
                properties: {
                    value: totalValue,
                    count: 1
                },
                geometry: {
                    type: 'Point',
                    coordinates: [finalCoords[0] + jitterLng, finalCoords[1] + jitterLat]
                }
            };
        });

        return {
            type: 'FeatureCollection',
            features
        } as any;
    }, [orders, ordersWithCoords]);

    useEffect(() => {
        if (!mapContainer.current) return;

        map.current = new maplibregl.Map({
            container: mapContainer.current,
            style: 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json',
            center: [-49.2671, -25.4290], // Curitiba
            zoom: 11,
            attributionControl: false
        });

        map.current.on('load', () => {
            if (!map.current) return;

            map.current.addSource('heat-source', {
                type: 'geojson',
                data: geoJsonData
            });

            map.current.addLayer({
                id: 'heat-layer',
                type: 'heatmap',
                source: 'heat-source',
                maxzoom: 15,
                paint: {
                    'heatmap-weight': ['interpolate', ['linear'], ['get', metric], 0, 0, 1000, 1],
                    'heatmap-intensity': ['interpolate', ['linear'], ['zoom'], 0, 1, 15, 3],
                    'heatmap-color': [
                        'interpolate',
                        ['linear'],
                        ['heatmap-density'],
                        0, 'rgba(0,0,0,0)',
                        0.2, '#fde047', // Amarelo
                        0.5, '#f97316', // Laranja
                        0.8, '#dc2626', // Vermelho
                        1.0, '#7f1d1d' // Vermelho escuro
                    ],
                    'heatmap-radius': ['interpolate', ['linear'], ['zoom'], 0, 2, 9, 20, 15, 40],
                    'heatmap-opacity': opacity
                }
            });

            setIsLoaded(true);
        });

        return () => {
            map.current?.remove();
        };
    }, []);

    // Atualiza dados e estilos quando mudam
    useEffect(() => {
        if (!map.current || !isLoaded) return;

        const source = map.current.getSource('heat-source') as maplibregl.GeoJSONSource;
        if (source) source.setData(geoJsonData);

        const maxValue = Math.max(...geoJsonData.features.map((f: any) => f.properties[metric]), 1);

        map.current.setPaintProperty('heat-layer', 'heatmap-weight', [
            'interpolate', ['linear'], ['get', metric], 0, 0, maxValue, 1
        ]);

        map.current.setPaintProperty('heat-layer', 'heatmap-color', [
            'interpolate',
            ['linear'],
            ['heatmap-density'],
            0, 'rgba(0,0,0,0)',
            0.2, '#fde047',
            0.5, '#f97316',
            0.8, '#dc2626',
            1.0, '#7f1d1d'
        ]);

        map.current.setPaintProperty('heat-layer', 'heatmap-opacity', opacity);
    }, [geoJsonData, metric, opacity, isLoaded]);

    return (
        <div className="bg-white dark:bg-slate-900 rounded-[2rem] p-8 border border-slate-100 dark:border-slate-800 shadow-xl overflow-hidden animate-fade-in">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                <div>
                    <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight flex items-center gap-3">
                        <i className="bi bi-geo-alt-fill text-blue-500"></i>
                        Radar Geográfico de Vendas
                    </h2>
                    <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1 uppercase tracking-widest text-[10px]">
                        Mapeamento Térmico de Performance - Curitiba e RMC
                    </p>
                </div>

                <div className="flex flex-wrap items-center gap-4">
                    <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
                        {(['value', 'count'] as MetricType[]).map((m) => (
                            <button
                                key={m}
                                onClick={() => setMetric(m)}
                                className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                                    metric === m 
                                    ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm scale-105' 
                                    : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                                }`}
                            >
                                {m === 'value' ? 'Venda' : 'Pedidos'}
