                    </div>
                </div>
            )}

            <div ref={mapContainer} className="flex-1 w-full filter grayscale-[0.2] brightness-110 contrast-110" />
            
            <style dangerouslySetInnerHTML={{ __html: `
                .marker-disk:hover {
                    transform: scale(1.4);
