                <span className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-amber-50 dark:bg-amber-900/20 text-amber-600 dark:text-amber-400 rounded-xl text-[10px] font-black uppercase tracking-widest">
                    <i className="bi bi-funnel-fill" /> {typeFilter.length} Tipos
                </span>
                {!isStandalone && (
                    <div className="flex items-center gap-2 ml-auto w-full sm:w-auto mt-2 sm:mt-0">
                        <Link
                            to="/logistics/assembly-list"
                            className="flex-1 sm:flex-none inline-flex items-center justify-center gap-2 bg-blue-50 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 font-black text-[10px] uppercase tracking-widest px-4 py-1.5 rounded-xl border border-blue-100 dark:border-blue-800"
                        >
                            <i className="bi bi-list-check" /> Lista de Montagens
                        </Link>
                        <button
                            onClick={handleShare}
                            className="flex-1 sm:flex-none inline-flex items-center justify-center gap-2 bg-emerald-500 hover:bg-emerald-600 text-white font-black text-[10px] uppercase tracking-widest px-4 py-1.5 rounded-xl shadow-md shadow-emerald-100 dark:shadow-emerald-900/20 transition-all active:scale-95"
                        >
                            <i className="bi bi-whatsapp" /> Compartilhar
                        </button>
                    </div>
                )}
            </div>
        </div>
    );

    const renderContent = () => {
        if (loading) {
            return (
                <div className="flex flex-col items-center justify-center py-40 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-slate-800 shadow-sm transition-colors duration-300">
                    <div className="relative w-20 h-20">
                        <div className="absolute inset-0 border-[6px] border-slate-50 dark:border-slate-800 rounded-full"></div>
                        <div className="absolute inset-0 border-[6px] border-blue-600 dark:border-blue-500 rounded-full border-t-transparent animate-spin"></div>
                    </div>
                    <p className="mt-8 text-slate-400 dark:text-slate-500 font-black uppercase tracking-[0.3em] text-[10px] animate-pulse">
                        Sincronizando Agenda...
                    </p>
                </div>
            );
        }

        if (Object.keys(schedule).length === 0) {
            return (
                <div className="flex flex-col items-center justify-center py-40 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-[3rem] bg-slate-50/30 dark:bg-slate-950/30 mx-4 transition-colors duration-300">
                    <div className="bg-white dark:bg-slate-900 p-10 rounded-full shadow-2xl shadow-slate-100 dark:shadow-none mb-8 border border-slate-50 dark:border-slate-800">
                        <i className="bi bi-calendar-x text-6xl text-slate-200 dark:text-slate-800" />
                    </div>
                    <h3 className="text-slate-800 dark:text-slate-100 font-black text-xl mb-2">Nada por aqui!</h3>
                    <p className="text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest text-[10px]">
                        Nenhum agendamento para o período selecionado
                    </p>
                    <button
                        onClick={() => setFilter('all')}
                        className="mt-8 text-blue-600 dark:text-blue-400 font-black text-[10px] uppercase tracking-widest hover:underline"
                    >
                        Ver todos os agendamentos
                    </button>
                </div>
            );
        }

        return (
            <div className="transition-all duration-500 ease-in-out">
                <ScheduleCardView
                    schedule={schedule}
                    onOrderClick={openOrderDetails}
                    isReadOnly={isStandalone}
                    hasInitialScrolled={hasInitialScrolledCard}
                    pendingOrders={pendingOrders}
                />
            </div>
        );
    };

    return (
        <div className={`w-full mx-auto transition-all duration-300 ${isMobileAppView ? 'max-w-none p-1.5 sm:p-4 mt-0 pb-4' : 'max-w-full mt-4 sm:mt-8 px-4 sm:px-6 md:px-8 pb-10'}`}>
            {renderHeader()}

            <div className="relative">
                {renderContent()}
            </div>

            {/* Mobile filter sidebar */}
            {sidebarOpen && <FilterSidebar />}

            {selectedOrder && (
                <OrderDetailsModal
                    order={selectedOrder}
                    onClose={closeOrderDetails}
                        onEdit={isStandalone ? undefined : (ord) => {
                            closeOrderDetails();
                            if (ord.orderType === 'assistance') {
                                setOrderToEdit(ord);
                            } else {
                                navigate(`/sales-order/edit/${ord.id}`);
                            }
                        }}
                    isReadOnly={isStandalone}
                />
            )}

            {orderToEdit && orderToEdit.orderType === 'assistance' && (
                <AssistanceOrderModal
                    order={orderToEdit}
                    onClose={() => setOrderToEdit(null)}
                    onSaveSuccess={() => setOrderToEdit(null)}
                />
            )}

            {showShowroomModal && (
                <ShowroomAssemblyModal
                    onClose={() => setShowShowroomModal(false)}
                />
            )}

            <style dangerouslySetInnerHTML={{
                __html: `
                .custom-scrollbar::-webkit-scrollbar { width: 8px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 20px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #cbd5e1; }
                @keyframes slide-left { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
                .animate-slide-left { animation: slide-left 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
                @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
                .animate-fade-in { animation: fade-in 0.2s ease-out forwards; }
            `}} />
        </div>
    );
};

export default DeliverySchedule;

import React, { useState, useEffect } from "react";
import { supabase } from "@/pages/utils/supabaseConfig";
import { formatToBRDate } from "../../utils/formatters";
import { Drill } from "@/components/shared/DrillIcon";

export interface ShowroomAssembly {
    id?: string;
    item: string;
    date: string;
    time: string;
    created_at?: string;
}

interface ShowroomAssemblyModalProps {
    onClose: () => void;
}

const ShowroomAssemblyModal = ({ onClose }: ShowroomAssemblyModalProps) => {
    const [assemblies, setAssemblies] = useState<ShowroomAssembly[]>([]);
    const [loading, setLoading] = useState(true);
    const [editingId, setEditingId] = useState<string | null>(null);

    // Form state
    const [item, setItem] = useState("");
    const [date, setDate] = useState("");
    const [time, setTime] = useState("");

    const TABLE_NAME = "showroom_assemblies";

    const fetchAssemblies = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from(TABLE_NAME)
                .select("*")
                .order("date", { ascending: true });
            
            if (error) {
                if (error.code === "PGRST116" || error.message.includes("does not exist")) {
                   // Table might not exist yet
                   console.warn("Table showroom_assemblies does not exist. Please create it.");
                   setAssemblies([]);
                } else {
                    throw error;
                }
            } else {
                setAssemblies(data || []);
            }
        } catch (err: any) {
            console.error("Erro ao buscar montagens de mostruário:", err);
            toast.error("Erro ao carregar dados do mostruário");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchAssemblies();
    }, []);

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!item || !date || !time) {
            toast.warning("Preencha todos os campos");
            return;
        }

        try {
            if (editingId) {
                const { error } = await supabase
                    .from(TABLE_NAME)
                    .update({ item, date, time })
                    .eq("id", editingId);
                if (error) throw error;
                toast.success("Montagem atualizada!");
            } else {
                const { error } = await supabase
                    .from(TABLE_NAME)
                    .insert([{ item, date, time }]);
                if (error) throw error;
                toast.success("Montagem agendada!");
            }

            // Reset form
            setItem("");
            setDate("");
            setTime("");
            setEditingId(null);
            fetchAssemblies();
        } catch (err: any) {
            console.error("Erro ao salvar montagem:", err);
            toast.error("Erro ao salvar. Verifique se a tabela 'showroom_assemblies' existe.");
        }
    };

    const handleEdit = (as: ShowroomAssembly) => {
        setEditingId(as.id || null);
        setItem(as.item);
        setDate(as.date);
        setTime(as.time);
    };

    const handleDelete = async (id: string) => {
        if (!window.confirm("Deseja excluir este agendamento de mostruário?")) return;
        try {
            const { error } = await supabase.from(TABLE_NAME).delete().eq("id", id);
            if (error) throw error;
            toast.success("Excluído com sucesso");
            fetchAssemblies();
        } catch (err: any) {
            console.error("Erro ao deletar:", err);
            toast.error("Erro ao excluir");
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300" onClick={onClose} />
            
            <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-[2.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-300">
                {/* Header */}
                <div className="px-8 py-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-white dark:bg-slate-900 sticky top-0 z-10">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-red-100 dark:bg-red-900/30 rounded-2xl">
                            <Drill className="text-red-600 dark:text-red-400 w-6 h-6" />
                        </div>
                        <div>
                            <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                Montagem para Mostruário
                            </h3>
                            <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">
                                Gestão de Agendamentos Internos
                            </p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-2 rounded-xl text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
                        <i className="bi bi-x-lg text-lg" />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
                    {/* Form Section */}
                    <form onSubmit={handleSave} className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-700/50">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="md:col-span-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 ml-2 mb-1.5 block">Item a ser montado</label>
                                <input 
                                    type="text" 
                                    value={item}
                                    onChange={(e) => setItem(e.target.value)}
                                    placeholder="Ex: Guarda-roupa casal 6 portas..."
                                    className="w-full bg-white dark:bg-slate-900 px-4 py-3 rounded-2xl text-sm font-bold border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-red-500 outline-none transition-all placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 ml-2 mb-1.5 block">Data</label>
                                <input 
                                    type="date"
                                    value={date}
                                    onChange={(e) => setDate(e.target.value)}
                                    className="w-full bg-white dark:bg-slate-900 px-4 py-3 rounded-2xl text-sm font-bold border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-red-500 outline-none transition-all"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 ml-2 mb-1.5 block">Horário / Período</label>
                                <input 
                                    type="text"
                                    value={time}
                                    onChange={(e) => setTime(e.target.value)}
                                    placeholder="Ex: 09:00 ou Manhã"
                                    className="w-full bg-white dark:bg-slate-900 px-4 py-3 rounded-2xl text-sm font-bold border border-slate-200 dark:border-slate-700 focus:ring-2 focus:ring-red-500 outline-none transition-all"
                                />
                            </div>
                        </div>
                        <div className="mt-6 flex gap-3">
                            <button 
                                type="submit"
                                className="flex-1 bg-red-600 hover:bg-red-700 text-white font-black text-xs uppercase tracking-widest py-4 px-8 rounded-2xl shadow-xl shadow-red-100 dark:shadow-red-950/20 transition-all active:scale-95 flex items-center justify-center gap-2"
                            >
                                <i className={`bi ${editingId ? 'bi-check-circle' : 'bi-plus-circle'} text-lg`} />
                                {editingId ? "Atualizar Agendamento" : "Agendar Montagem"}
                            </button>
                            {editingId && (
                                <button 
                                    type="button"
                                    onClick={() => { setEditingId(null); setItem(""); setDate(""); setTime(""); }}
                                    className="px-6 py-4 bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-slate-300 dark:hover:bg-slate-600 transition-all"
                                >
                                    Cancelar
                                </button>
                            )}
                        </div>
                    </form>

                    {/* List Section */}
                    <div>
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-slate-500 mb-4 flex items-center gap-2">
                            <i className="bi bi-list-ul" /> Agendamentos Ativos
                        </p>
                        
                        <div className="space-y-3">
                            {loading ? (
                                <div className="text-center py-10">
                                    <div className="w-8 h-8 border-4 border-red-500 border-t-transparent rounded-full animate-spin mx-auto mr-3"></div>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mt-4">Carregando...</p>
                                </div>
                            ) : assemblies.length === 0 ? (
                                <div className="text-center py-10 border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-[2rem]">
                                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-300">Nenhum agendamento para o mostruário</p>
                                </div>
                            ) : (
                                assemblies.map(as => (
                                    <div key={as.id} className="group flex items-center justify-between p-4 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-red-200 dark:hover:border-red-900/30 transition-all">
                                        <div className="flex items-center gap-4">
                                            <div className="w-10 h-10 rounded-xl bg-red-50 dark:bg-red-900/20 flex items-center justify-center text-red-600 dark:text-red-400 font-black text-xs">
                                                {formatToBRDate(as.date).split('/')[0]}
                                            </div>
                                            <div>
                                                <h4 className="text-sm font-bold text-slate-700 dark:text-slate-200">{as.item}</h4>
                                                <div className="flex items-center gap-3 mt-0.5">
                                                    <span className="text-[10px] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">
                                                        <i className="bi bi-calendar3 mr-1" /> {formatToBRDate(as.date)}
                                                    </span>
                                                    <span className="text-[10px] text-red-500 font-black uppercase tracking-widest">
                                                        <i className="bi bi-clock mr-1" /> {as.time}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button 
                                                onClick={() => handleEdit(as)}
                                                className="p-2 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-all"
                                            >
                                                <i className="bi bi-pencil-fill" />
                                            </button>
                                            <button 
                                                onClick={() => handleDelete(as.id!)}
                                                className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-all"
                                            >
                                                <i className="bi bi-trash3-fill" />
                                            </button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ShowroomAssemblyModal;

import React, { useState, useEffect } from "react";
import { financeService } from '@/pages/services/financeService';
import { AccountPayable } from "../../../types/finance.type";
import { normalizeSearchTerm } from "@/pages/utils/textUtils";
import PayableModal from "./PayableModal";

const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
};

const formatToBRDate = (dateString: string) => {
    if (!dateString) return "-";
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short' }).format(date);
};

export default function Payables() {
    const [payables, setPayables] = useState<AccountPayable[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedPayable, setSelectedPayable] = useState<AccountPayable | null>(null);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState("all");

    const fetchPayables = async () => {
        setLoading(true);
        try {
            const data = await financeService.getPayables(statusFilter !== "all" ? statusFilter : undefined);
            setPayables(data || []);
        } catch (error) {
            console.error("Erro ao buscar contas a pagar:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchPayables();
    }, [statusFilter]);

    const handleEdit = (payable: AccountPayable) => {
        setSelectedPayable(payable);
        setIsModalOpen(true);
    };

    const handleNew = () => {
        setSelectedPayable(null);
        setIsModalOpen(true);
    };

    const handleModalClose = (saved: boolean) => {
        setIsModalOpen(false);
        if (saved) fetchPayables();
    };

    const getStatusStyle = (status: string) => {
        switch (status) {
            case 'paid': return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/20';
            case 'pending': return 'bg-amber-100 text-amber-600 dark:bg-amber-900/20';
            case 'overdue': return 'bg-rose-100 text-rose-600 dark:bg-rose-900/20';
            case 'cancelled': return 'bg-slate-100 text-slate-600 dark:bg-slate-800';
            default: return 'bg-slate-100 text-slate-600 dark:bg-slate-800';
        }
    };

    const getStatusText = (status: string) => {
        switch (status) {
            case 'paid': return 'Pago';
            case 'pending': return 'Pendente';
            case 'overdue': return 'Atrasado';
            case 'cancelled': return 'Cancelado';
            default: return status;
        }
    };

    const normSearch = normalizeSearchTerm(search);
    const filtered = payables.filter(p => 
        normalizeSearchTerm(p.description || '').includes(normSearch) || 
        normalizeSearchTerm(p.supplier_name || '').includes(normSearch)
    );

    return (
        <div className="flex flex-col h-[calc(100vh-64px)] xl:h-[calc(100vh-80px)] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
            <div className="flex-1 flex flex-col min-w-0 overflow-y-auto overflow-x-hidden p-4 md:p-10">
                <div className="flex flex-col xl:flex-row justify-between xl:items-center mb-6 md:mb-10 gap-6">
                    <div className="flex items-start xl:items-center gap-4 xl:gap-6">
                        <div className="w-12 h-12 xl:w-16 xl:h-16 rounded-2xl bg-rose-500 flex items-center justify-center text-white shadow-xl shadow-rose-200 dark:shadow-none">
                            <i className="bi bi-file-earmark-minus text-2xl xl:text-3xl"></i>
                        </div>
                        <div>
                            <h1 className="text-2xl xl:text-4xl font-black text-slate-800 dark:text-slate-100 tracking-tight transition-colors">
                                Contas a Pagar
                            </h1>
                            <p className="text-slate-500 dark:text-slate-400 font-medium text-sm xl:text-lg hidden sm:block">
                                Gestão de despesas, boletos e pagamentos de fornecedores.
                            </p>
                        </div>
                    </div>

                    <div className="flex gap-4">
                        <button
                            onClick={handleNew}
                            className="flex items-center justify-center gap-2 xl:gap-3 bg-rose-600 hover:bg-rose-700 text-white px-4 py-3 xl:px-8 xl:py-4 rounded-xl font-black uppercase tracking-widest text-xs shadow-xl shadow-rose-200 dark:shadow-none transition-all active:scale-95 w-full sm:w-auto"
                        >
                            <i className="bi bi-plus-lg text-sm xl:text-base" />
                            Nova Despesa
                        </button>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-800 overflow-hidden transition-all flex-col flex h-full">
                    <div className="p-6 border-b border-slate-50 dark:border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div className="relative flex-1 max-w-md">
                            <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
                            <input 
                                type="text" 
                                placeholder="Buscar por descrição ou credor..." 
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                className="w-full pl-12 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border-none rounded-2xl text-sm outline-none focus:ring-2 focus:ring-rose-500 transition-all dark:text-slate-200"
                            />
                        </div>
                        <div className="flex gap-2 border border-slate-100 dark:border-slate-800 p-1 rounded-xl bg-slate-50 dark:bg-slate-950">
                            {[
                              { id: 'all', label: 'Todas' },
                              { id: 'pending', label: 'Pendentes' },
                              { id: 'overdue', label: 'Atrasadas' },
                              { id: 'paid', label: 'Pagas' }
                            ].map(filter => (
                                <button
                                    key={filter.id}
                                    onClick={() => setStatusFilter(filter.id)}
                                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                                        statusFilter === filter.id 
                                            ? 'bg-white dark:bg-slate-800 text-rose-600 dark:text-rose-400 shadow-sm' 
                                            : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'
                                    }`}
                                >
                                    {filter.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead>
                                <tr className="bg-slate-50/50 dark:bg-slate-950/20">
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800">Cód.</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800">Vencimento</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800">Descrição / Credor</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800 text-center">Status</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800 text-right">Valor Pagar</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800 text-right">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                {filtered.map((payable) => (
                                    <tr key={payable.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-colors group">
                                        <td className="px-8 py-5 text-xs font-mono font-bold text-slate-400">
                                            #{payable.id?.slice(0, 8)}
                                        </td>
                                        <td className="px-8 py-5 text-xs font-medium text-slate-500 whitespace-nowrap">
                                            {formatToBRDate(payable.due_date)}
                                        </td>
                                        <td className="px-8 py-5">
                                            <span className="block font-bold text-slate-700 dark:text-slate-200">{payable.description}</span>
                                            {payable.supplier_name && (
                                              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1 mt-1">
                                                <i className="bi bi-person"></i> {payable.supplier_name}
                                              </span>
                                            )}
                                        </td>
                                        <td className="px-8 py-5 text-center">
                                            <span className={`inline-flex px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${getStatusStyle(payable.status)}`}>
                                                {getStatusText(payable.status)}
                                            </span>
                                        </td>
                                        <td className="px-8 py-5 text-right font-black text-slate-700 dark:text-slate-200">
                                            {formatCurrency(payable.amount)}
                                        </td>
                                        <td className="px-8 py-5 text-right">
                                            <button 
                                                onClick={() => handleEdit(payable)}
                                                className="p-2 text-slate-300 hover:text-rose-600 transition-colors"
                                                title="Visualizar / Editar"
                                            >
                                                <i className="bi bi-pencil-square text-lg"></i>
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    {loading && (
                        <div className="p-20 flex flex-col items-center justify-center flex-1">
                            <div className="w-12 h-12 border-4 border-rose-600/30 border-t-rose-600 rounded-full animate-spin mb-4" />
                            <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Buscando Despesas...</p>
                        </div>
                    )}

                    {filtered.length === 0 && !loading && (
                        <div className="p-20 flex flex-col items-center justify-center text-center flex-1">
                            <div className="w-20 h-20 bg-slate-50 dark:bg-slate-900 rounded-[2rem] flex items-center justify-center text-slate-200 dark:text-slate-800 mb-6 border border-slate-100 dark:border-slate-800">
                                <i className="bi bi-check-circle text-4xl"></i>
                            </div>
                            <h4 className="text-xl font-black text-slate-400">Nenhuma conta a pagar encontrada.</h4>
                            <p className="text-slate-500 mt-2 text-sm">Tudo em dia!</p>
                        </div>
                    )}
                </div>
            </div>

            {isModalOpen && (
                <PayableModal 
                  onClose={() => handleModalClose(false)} 
                  onSaved={() => handleModalClose(true)} 
                  payable={selectedPayable} 
                />
            )}
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { toast } from "react-toastify";
import { financeService } from '@/pages/services/financeService';
import { AccountPayable, FinancialCategory, PaymentStatus } from "../../../types/finance.type";

interface PayableModalProps {
    onClose: () => void;
    onSaved: () => void;
    payable?: AccountPayable | null;
}

export default function PayableModal({ onClose, onSaved, payable }: PayableModalProps) {
    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState<FinancialCategory[]>([]);
    
    const [formData, setFormData] = useState({
        description: payable?.description || "",
        amount: payable?.amount || 0,
        due_date: payable?.due_date || new Date().toISOString().split('T')[0],
        status: payable?.status || "pending" as PaymentStatus,
        category_id: payable?.category_id || "",
        supplier_name: payable?.supplier_name || "",
        notes: payable?.notes || ""
    });

    const [expenseType, setExpenseType] = useState<'single' | 'installments' | 'recurring'>('single');
    const [installmentsCount, setInstallmentsCount] = useState(2);
    const [recurringFrequency, setRecurringFrequency] = useState<'monthly' | 'yearly'>('monthly');

    useEffect(() => {
        const fetchCats = async () => {
            try {
                const cats = await financeService.getCategories('expense');
                setCategories(cats || []);
            } catch (error) {
                console.error("Erro ao buscar categorias", error);
            }
        };
        fetchCats();
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: name === 'amount' ? Number(value) : value
        }));
    };

    const handleSave = async () => {
        if (!formData.description || formData.amount <= 0 || !formData.due_date || !formData.category_id) {
            toast.error("Preencha descrição, valor, vencimento e categoria.");
            return;
        }

        setLoading(true);
        try {
            if (payable?.id) {
                // Edição de uma conta existente (sempre altera só ela)
                await financeService.updatePayable(payable.id, formData);
                toast.success("Conta a pagar atualizada!");
            } else {
                // Criação
                const startDate = new Date(formData.due_date);
                
                if (expenseType === 'single') {
                    await financeService.createPayable(formData);
                    toast.success("Conta a pagar cadastrada!");
                } 
                else if (expenseType === 'installments') {
                    const payables = [];
                    const amountPerInstallment = formData.amount / installmentsCount;
                    
                    for (let i = 0; i < installmentsCount; i++) {
                        const dueDate = new Date(startDate);
                        dueDate.setMonth(dueDate.getMonth() + i);
                        
                        payables.push({
                            ...formData,
                            description: `${formData.description} (Parc. ${i + 1}/${installmentsCount})`,
                            amount: amountPerInstallment,
                            due_date: dueDate.toISOString().split('T')[0]
                        });
                    }
                    await financeService.bulkCreatePayables(payables);
                    toast.success(`${installmentsCount} parcelas cadastradas com sucesso!`);
                } 
                else if (expenseType === 'recurring') {
                    // Cadastra a Recorrente
                    const dueDayParam = startDate.getDate() + 1; // +1 devido ao timezone local se a data for meia noite
                    await financeService.createRecurringExpense({
                        description: formData.description,
                        amount: formData.amount,
                        category_id: formData.category_id,
                        frequency: recurringFrequency,
                        due_day: dueDayParam > 31 ? 31 : dueDayParam,
                        start_date: formData.due_date,
                        active: true
                    });

                    // Lança automaticamente os primeiros 12 meses no contas a pagar para previsão de fluxo de caixa
                    const preGenerated = [];
                    for (let i = 0; i < 12; i++) {
                        const dueDate = new Date(startDate);
                        if (recurringFrequency === 'monthly') {
                            dueDate.setMonth(dueDate.getMonth() + i);
                        } else {
                            dueDate.setFullYear(dueDate.getFullYear() + i);
                        }
                        
                        preGenerated.push({
                            ...formData,
                            description: `${formData.description} (Auto)`,
                            due_date: dueDate.toISOString().split('T')[0]
                        });
                    }
                    await financeService.bulkCreatePayables(preGenerated);
                    toast.success("Despesa fixa ativada e previsão para 12 meses gerada!");
                }
            }
            onSaved();
        } catch (error) {
            console.error(error);
            toast.error("Erro ao salvar conta a pagar.");
        } finally {
            setLoading(false);
        }
    };

    const handlePay = async () => {
        if (!payable?.id) return;
        setLoading(true);
        try {
            await financeService.updatePayable(payable.id, { 
                status: 'paid', 
                payment_date: new Date().toISOString().split('T')[0] 
            });
            
            // Generate Transaction Record automaticaly
            await financeService.createTransaction({
                type: 'expense',
                amount: payable.amount,
                date: new Date().toISOString().split('T')[0],
                description: `Pagamento: ${payable.description}`,
                payment_method: 'Manual', // Can be improved to select method
                category_id: payable.category_id,
                payable_id: payable.id
            });

            toast.success("Conta baixada com sucesso!");
            onSaved();
        } catch (error) {
            console.error(error);
            toast.error("Erro ao baixar conta a pagar.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose}></div>
            
            <div className="relative w-full max-w-2xl bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 flex flex-col max-h-[90vh] overflow-hidden animate-slide-up">
                {/* Header */}
                <div className="flex items-center justify-between p-6 xl:p-8 border-b border-slate-50 dark:border-slate-800">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-rose-500 text-white flex items-center justify-center shadow-lg shadow-rose-200 dark:shadow-none">
                            <i className="bi bi-file-earmark-minus text-xl"></i>
                        </div>
                        <div>
                            <h2 className="text-xl xl:text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                {payable ? 'Editar Despesa' : 'Nova Despesa'}
                            </h2>
                            <p className="text-sm font-medium text-slate-500 dark:text-slate-400">
                                Preencha os dados do compromisso
                            </p>
                        </div>
                    </div>
                    <button 
                        onClick={onClose}
                        className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-50 hover:bg-slate-100 text-slate-500 transition-colors"
                    >
                        <i className="bi bi-x-lg"></i>
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-6 xl:p-8 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2 md:col-span-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500 flex items-center gap-1">Descrição <span className="text-rose-500">*</span></label>
                            <input
                                type="text"
                                name="description"
                                value={formData.description}
                                onChange={handleChange}
                                placeholder="Aluguel, Luz, Fornecedor X..."
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500 transition-all"
                            />
                        </div>

                        {!payable && (
                            <div className="space-y-2 md:col-span-2 bg-slate-50 dark:bg-slate-900/50 p-4 rounded-3xl border border-slate-100 dark:border-slate-800">
                                <div className="flex flex-col sm:flex-row gap-4">
                                    <label className={`flex-1 flex items-center justify-center p-3 rounded-2xl cursor-pointer transition-all border ${expenseType === 'single' ? 'bg-white border-blue-500 text-blue-600 shadow-sm' : 'border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}>
                                        <input type="radio" className="hidden" checked={expenseType === 'single'} onChange={() => setExpenseType('single')} />
                                        <span className="text-sm font-bold text-center">Único</span>
                                    </label>
                                    <label className={`flex-1 flex items-center justify-center p-3 rounded-2xl cursor-pointer transition-all border ${expenseType === 'installments' ? 'bg-white border-blue-500 text-blue-600 shadow-sm' : 'border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}>
                                        <input type="radio" className="hidden" checked={expenseType === 'installments'} onChange={() => setExpenseType('installments')} />
                                        <span className="text-sm font-bold text-center">Parcelado</span>
                                    </label>
                                    <label className={`flex-1 flex items-center justify-center p-3 rounded-2xl cursor-pointer transition-all border ${expenseType === 'recurring' ? 'bg-white border-rose-500 text-rose-600 shadow-sm' : 'border-transparent text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800'}`}>
                                        <input type="radio" className="hidden" checked={expenseType === 'recurring'} onChange={() => setExpenseType('recurring')} />
                                        <span className="text-sm font-bold text-center flex items-center gap-1"><i className="bi bi-arrow-repeat"></i> Todo mês (recorrente)</span>
                                    </label>
                                </div>
                                
                                {expenseType === 'installments' && (
                                    <div className="mt-4 pt-4 border-t border-slate-200 dark:border-slate-800 flex items-center gap-4">
                                        <label className="text-xs font-bold text-slate-600 dark:text-slate-400">Quantidade de Parcelas:</label>
                                        <input type="number" min="2" max="120" value={installmentsCount} onChange={(e) => setInstallmentsCount(Number(e.target.value))} className="w-24 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-blue-500" />
                                        <span className="text-[10px] text-slate-400 max-w-[200px] leading-tight">*O valor total abaixo será dividido por {installmentsCount}</span>
                                    </div>
                                )}

                                {expenseType === 'recurring' && (
                                    <div className="mt-4 pt-4 border-t border-slate-200 dark:border-slate-800 flex flex-col sm:flex-row gap-4 items-center">
                                        <div className="flex-1 space-y-1">
                                            <label className="text-xs font-bold text-slate-600 dark:text-slate-400">Começa em qual mês?</label>
                                            <select 
                                                value={new Date(formData.due_date).getMonth()} 
                                                onChange={(e) => {
                                                    const d = new Date(formData.due_date);
                                                    d.setMonth(parseInt(e.target.value));
                                                    setFormData({...formData, due_date: d.toISOString().split('T')[0]});
                                                }}
                                                className="w-full bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500"
                                            >
                                                {['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'].map((m, i) => (
                                                    <option key={i} value={i}>{m}</option>
                                                ))}
                                            </select>
                                        </div>
                                        <span className="text-[10px] text-slate-400 max-w-[200px] leading-tight">*Geraremos automaticamente 12 meses de cobrança no Contas a Pagar</span>
                                    </div>
                                )}
                            </div>
                        )}

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500 flex items-center gap-1">Valor (R$) <span className="text-rose-500">*</span></label>
                            <input
                                type="number"
                                name="amount"
                                value={formData.amount}
                                onChange={handleChange}
                                min="0" step="0.01"
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500 transition-all"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500 flex items-center gap-1">
                                {expenseType === 'single' ? 'Data do Pagamento' : (expenseType === 'recurring' ? 'Dia do Vencimento' : 'Data de Vencimento')} <span className="text-rose-500">*</span>
                            </label>
                            <div className="relative group/date">
                                {expenseType === 'recurring' ? (
                                    <select
                                        name="due_day_select"
                                        value={new Date(formData.due_date).getDate()}
                                        onChange={(e) => {
                                            const d = new Date(formData.due_date);
                                            d.setDate(parseInt(e.target.value));
                                            setFormData({...formData, due_date: d.toISOString().split('T')[0]});
                                        }}
                                        className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500 transition-all font-sans"
                                    >
                                        {Array.from({length: 31}, (_, i) => i + 1).map(day => (
                                            <option key={day} value={day}>{day}</option>
                                        ))}
                                    </select>
                                ) : (
                                    <input
                                        type="date"
                                        name="due_date"
                                        value={formData.due_date}
                                        onChange={handleChange}
                                        className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500 transition-all"
                                    />
                                )}
                                {expenseType === 'recurring' && (
                                    <div className="mt-2 flex items-center gap-2 px-3 py-2 bg-blue-50/50 dark:bg-blue-900/10 border border-blue-100/50 dark:border-blue-800/30 rounded-xl">
                                        <i className="bi bi-info-circle-fill text-blue-500 text-xs" />
                                        <span className="text-[10px] font-bold text-blue-600 dark:text-blue-400 uppercase tracking-tight">
                                            Será lançado e marcado como pago automaticamente ao passar da data
                                        </span>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Credor / Fornecedor</label>
                            <input
                                type="text"
                                name="supplier_name"
                                value={formData.supplier_name}
                                onChange={handleChange}
                                placeholder="Nome da empresa ou pessoa"
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500 transition-all"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500 flex items-center gap-1">Categoria <span className="text-rose-500">*</span></label>
                            <select
                                name="category_id"
                                value={formData.category_id}
                                onChange={handleChange}
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500 transition-all font-sans"
                            >
                                <option value="" disabled>Selecione uma categoria</option>
                                {categories.map(c => (
                                    <option key={c.id} value={c.id}>{c.name}</option>
                                ))}
                            </select>
                        </div>

                        <div className="space-y-2 md:col-span-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Observações adicionais</label>
                            <textarea
                                name="notes"
                                value={formData.notes}
                                onChange={handleChange}
                                rows={3}
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-rose-500 transition-all resize-none"
                            ></textarea>
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className="p-6 xl:p-8 border-t border-slate-50 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 flex items-center justify-between gap-4">
                    {payable?.id && payable.status !== 'paid' ? (
                        <button
                            onClick={handlePay}
                            disabled={loading}
                            className="bg-emerald-500 hover:bg-emerald-600 text-white px-6 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95 flex items-center gap-2"
                        >
                            <i className="bi bi-check2-all text-lg"></i>
                            Baixar Pagamento
                        </button>
                    ) : <div></div>}

                    <div className="flex gap-4">
                        <button
                            onClick={onClose}
                            className="flex-1 px-6 py-3 rounded-xl font-black uppercase tracking-widest text-xs text-slate-500 hover:bg-slate-100 transition-colors"
                        >
                            Cancelar
                        </button>
                        <button
                            onClick={handleSave}
                            disabled={loading}
                            className="flex-1 bg-rose-600 hover:bg-rose-700 text-white px-6 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-lg shadow-rose-200 dark:shadow-none transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                        >
                            {loading ? <i className="bi bi-arrow-repeat animate-spin"></i> : <i className="bi bi-save"></i>}
                            Salvar
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { financeService } from '@/pages/services/financeService';
import { AccountReceivable } from "../../../types/finance.type";
import { normalizeSearchTerm } from "@/pages/utils/textUtils";
import ReceivableModal from "./ReceivableModal";

const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
};

const formatToBRDate = (dateString: string) => {
    if (!dateString) return "-";
    const date = new Date(dateString);
    return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short' }).format(date);
};

export default function Receivables() {
    const [receivables, setReceivables] = useState<AccountReceivable[]>([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedReceivable, setSelectedReceivable] = useState<AccountReceivable | null>(null);
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState("all");

    const fetchReceivables = async () => {
        setLoading(true);
        try {
            const data = await financeService.getReceivables(statusFilter !== "all" ? statusFilter : undefined);
            setReceivables(data || []);
        } catch (error) {
            console.error("Erro ao buscar contas a receber:", error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchReceivables();
    }, [statusFilter]);

    const handleEdit = (receivable: AccountReceivable) => {
        setSelectedReceivable(receivable);
        setIsModalOpen(true);
    };

    const handleNew = () => {
        setSelectedReceivable(null);
        setIsModalOpen(true);
    };

    const handleModalClose = (saved: boolean) => {
        setIsModalOpen(false);
        if (saved) fetchReceivables();
    };

    const getStatusStyle = (status: string) => {
        switch (status) {
            case 'paid': return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/20';
            case 'pending': return 'bg-amber-100 text-amber-600 dark:bg-amber-900/20';
            case 'overdue': return 'bg-rose-100 text-rose-600 dark:bg-rose-900/20';
            case 'cancelled': return 'bg-slate-100 text-slate-600 dark:bg-slate-800';
            default: return 'bg-slate-100 text-slate-600 dark:bg-slate-800';
        }
    };

    const getStatusText = (status: string) => {
        switch (status) {
            case 'paid': return 'Recebido';
            case 'pending': return 'Pendente';
            case 'overdue': return 'Atrasado';
            case 'cancelled': return 'Cancelada';
            default: return status;
        }
    };

    const normSearch = normalizeSearchTerm(search);
    const filtered = receivables.filter(r => 
        normalizeSearchTerm(r.description || '').includes(normSearch) || 
        normalizeSearchTerm(r.customer_name || '').includes(normSearch)
    );

    return (
        <div className="flex flex-col h-[calc(100vh-64px)] xl:h-[calc(100vh-80px)] overflow-hidden bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
            <div className="flex-1 flex flex-col min-w-0 overflow-y-auto overflow-x-hidden p-4 md:p-10">
                <div className="flex flex-col xl:flex-row justify-between xl:items-center mb-6 md:mb-10 gap-6">
                    <div className="flex items-start xl:items-center gap-4 xl:gap-6">
                        <div className="w-12 h-12 xl:w-16 xl:h-16 rounded-2xl bg-emerald-500 flex items-center justify-center text-white shadow-xl shadow-emerald-200 dark:shadow-none">
                            <i className="bi bi-file-earmark-plus text-2xl xl:text-3xl"></i>
                        </div>
                        <div>
                            <h1 className="text-2xl xl:text-4xl font-black text-slate-800 dark:text-slate-100 tracking-tight transition-colors">
                                Contas a Receber
                            </h1>
                            <p className="text-slate-500 dark:text-slate-400 font-medium text-sm xl:text-lg hidden sm:block">
                                Previsão de entradas, crediários e parcelamentos.
                            </p>
                        </div>
                    </div>

                    <div className="flex gap-4">
                        <button
                            onClick={handleNew}
                            className="flex items-center justify-center gap-2 xl:gap-3 bg-emerald-600 hover:bg-emerald-700 text-white px-4 py-3 xl:px-8 xl:py-4 rounded-xl font-black uppercase tracking-widest text-xs shadow-xl shadow-emerald-200 dark:shadow-none transition-all active:scale-95 w-full sm:w-auto"
                        >
                            <i className="bi bi-plus-lg text-sm xl:text-base" />
                            Novo Recebimento
                        </button>
                    </div>
                </div>

                <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-800 overflow-hidden transition-all flex-col flex h-full">
                    <div className="p-6 border-b border-slate-50 dark:border-slate-800 flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div className="relative flex-1 max-w-md">
                            <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
                            <input 
                                type="text" 
                                placeholder="Buscar por descrição ou cliente..." 
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                className="w-full pl-12 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border-none rounded-2xl text-sm outline-none focus:ring-2 focus:ring-emerald-500 transition-all dark:text-slate-200"
                            />
                        </div>
                        <div className="flex gap-2 border border-slate-100 dark:border-slate-800 p-1 rounded-xl bg-slate-50 dark:bg-slate-950">
                            {[
                              { id: 'all', label: 'Todas' },
                              { id: 'pending', label: 'Pendentes' },
                              { id: 'overdue', label: 'Atrasadas' },
                              { id: 'paid', label: 'Recebidas' }
                            ].map(filter => (
                                <button
                                    key={filter.id}
                                    onClick={() => setStatusFilter(filter.id)}
                                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                                        statusFilter === filter.id 
                                            ? 'bg-white dark:bg-slate-800 text-emerald-600 dark:text-emerald-400 shadow-sm' 
                                            : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200'
                                    }`}
                                >
                                    {filter.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead>
                                <tr className="bg-slate-50/50 dark:bg-slate-950/20">
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800">Cód.</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800">Vencimento</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800">Descrição / Cliente</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800 text-center">Status</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800 text-right">Valor Receber</th>
                                    <th className="px-8 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-50 dark:border-slate-800 text-right">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                {filtered.map((receivable) => (
                                    <tr key={receivable.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/20 transition-colors group">
                                        <td className="px-8 py-5 text-xs font-mono font-bold text-slate-400">
                                            #{receivable.id?.slice(0, 8)}
                                        </td>
                                        <td className="px-8 py-5 text-xs font-medium text-slate-500 whitespace-nowrap">
                                            {formatToBRDate(receivable.due_date)}
                                        </td>
                                        <td className="px-8 py-5">
                                            <span className="block font-bold text-slate-700 dark:text-slate-200">{receivable.description}</span>
                                            {receivable.customer_name && (
                                              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1 mt-1">
                                                <i className="bi bi-person"></i> {receivable.customer_name}
                                              </span>
                                            )}
                                        </td>
                                        <td className="px-8 py-5 text-center">
                                            <span className={`inline-flex px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${getStatusStyle(receivable.status)}`}>
                                                {getStatusText(receivable.status)}
                                            </span>
                                        </td>
                                        <td className="px-8 py-5 text-right font-black text-slate-700 dark:text-slate-200">
                                            {formatCurrency(receivable.amount)}
                                        </td>
                                        <td className="px-8 py-5 text-right">
                                            <button 
                                                onClick={() => handleEdit(receivable)}
                                                className="p-2 text-slate-300 hover:text-emerald-600 transition-colors"
                                                title="Visualizar / Editar"
                                            >
                                                <i className="bi bi-pencil-square text-lg"></i>
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    {loading && (
                        <div className="p-20 flex flex-col items-center justify-center flex-1">
                            <div className="w-12 h-12 border-4 border-emerald-600/30 border-t-emerald-600 rounded-full animate-spin mb-4" />
                            <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Buscando Recebimentos...</p>
                        </div>
                    )}

                    {filtered.length === 0 && !loading && (
                        <div className="p-20 flex flex-col items-center justify-center text-center flex-1">
                            <div className="w-20 h-20 bg-slate-50 dark:bg-slate-900 rounded-[2rem] flex items-center justify-center text-slate-200 dark:text-slate-800 mb-6 border border-slate-100 dark:border-slate-800">
                                <i className="bi bi-check-circle text-4xl"></i>
                            </div>
                            <h4 className="text-xl font-black text-slate-400">Nenhuma conta a receber encontrada.</h4>
                        </div>
                    )}
                </div>
            </div>

            {isModalOpen && (
                <ReceivableModal 
                  onClose={() => handleModalClose(false)} 
                  onSaved={() => handleModalClose(true)} 
                  receivable={selectedReceivable} 
                />
            )}
        </div>
    );
}

import React, { useState, useEffect } from "react";
import { toast } from "react-toastify";
import { financeService } from '@/pages/services/financeService';
import { AccountReceivable, FinancialCategory, PaymentStatus } from "../../../types/finance.type";

interface ReceivableModalProps {
    onClose: () => void;
    onSaved: () => void;
    receivable?: AccountReceivable | null;
}

export default function ReceivableModal({ onClose, onSaved, receivable }: ReceivableModalProps) {
    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState<FinancialCategory[]>([]);
    
    const [formData, setFormData] = useState({
        description: receivable?.description || "",
        amount: receivable?.amount || 0,
        due_date: receivable?.due_date || new Date().toISOString().split('T')[0],
        status: receivable?.status || "pending" as PaymentStatus,
        category_id: receivable?.category_id || "",
        customer_name: receivable?.customer_name || "",
        notes: receivable?.notes || ""
    });

    useEffect(() => {
        const fetchCats = async () => {
            try {
                const cats = await financeService.getCategories('income');
                setCategories(cats || []);
            } catch (error) {
                console.error("Erro ao buscar categorias", error);
            }
        };
        fetchCats();
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: name === 'amount' ? Number(value) : value
        }));
    };

    const handleSave = async () => {
        if (!formData.description || formData.amount <= 0 || !formData.due_date) {
            toast.error("Preencha descrição, valor e vencimento.");
            return;
        }

        setLoading(true);
        try {
            if (receivable?.id) {
                await financeService.updateReceivable(receivable.id, formData);
                toast.success("Conta a receber atualizada!");
            } else {
                await financeService.createReceivable(formData);
                toast.success("Conta a receber cadastrada!");
            }
            onSaved();
        } catch (error) {
            console.error(error);
            toast.error("Erro ao salvar conta a receber.");
        } finally {
            setLoading(false);
        }
    };

    const handleReceive = async () => {
        if (!receivable?.id) return;
        setLoading(true);
        try {
            await financeService.updateReceivable(receivable.id, { 
                status: 'paid', 
                payment_date: new Date().toISOString().split('T')[0] 
            });
            
            // Generate Transaction Record automaticaly
            await financeService.createTransaction({
                type: 'income',
                amount: receivable.amount,
                date: new Date().toISOString().split('T')[0],
                description: `Recebimento: ${receivable.description}`,
                payment_method: 'Manual/Outros', 
                category_id: receivable.category_id,
                receivable_id: receivable.id
            });

            toast.success("Conta recebida com sucesso!");
            onSaved();
        } catch (error) {
            console.error(error);
            toast.error("Erro ao receber conta.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose}></div>
            
            <div className="relative w-full max-w-2xl bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 flex flex-col max-h-[90vh] overflow-hidden animate-slide-up">
                {/* Header */}
                <div className="flex items-center justify-between p-6 xl:p-8 border-b border-slate-50 dark:border-slate-800">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-emerald-500 text-white flex items-center justify-center shadow-lg shadow-emerald-200 dark:shadow-none">
                            <i className="bi bi-file-earmark-plus text-xl"></i>
                        </div>
                        <div>
                            <h2 className="text-xl xl:text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                {receivable ? 'Editar Recebimento' : 'Novo Recebimento'}
                            </h2>
                            <p className="text-sm font-medium text-slate-500 dark:text-slate-400">
                                Preencha os dados do recebimento financeiro
                            </p>
                        </div>
                    </div>
                    <button 
                        onClick={onClose}
                        className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-50 hover:bg-slate-100 text-slate-500 transition-colors"
                    >
                        <i className="bi bi-x-lg"></i>
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-y-auto p-6 xl:p-8 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2 md:col-span-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Descrição</label>
                            <input
                                type="text"
                                name="description"
                                value={formData.description}
                                onChange={handleChange}
                                placeholder="Referente à venda X, Serviço Y..."
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Valor (R$)</label>
                            <input
                                type="number"
                                name="amount"
                                value={formData.amount}
                                onChange={handleChange}
                                min="0" step="0.01"
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Data de Vencimento</label>
                            <input
                                type="date"
                                name="due_date"
                                value={formData.due_date}
                                onChange={handleChange}
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Cliente</label>
                            <input
                                type="text"
                                name="customer_name"
                                value={formData.customer_name}
                                onChange={handleChange}
                                placeholder="Nome do cliente (opcional)"
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Categoria</label>
                            <select
                                name="category_id"
                                value={formData.category_id}
                                onChange={handleChange}
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
                            >
                                <option value="">Sem categoria</option>
                                {categories.map(c => (
                                    <option key={c.id} value={c.id}>{c.name}</option>
                                ))}
                            </select>
                        </div>

                        <div className="space-y-2 md:col-span-2">
                            <label className="text-xs font-black uppercase tracking-widest text-slate-500">Observações adicionais</label>
                            <textarea
                                name="notes"
                                value={formData.notes}
                                onChange={handleChange}
                                rows={3}
                                className="w-full bg-slate-50 dark:bg-slate-950 border-none rounded-2xl px-4 py-3 text-sm font-bold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-emerald-500 transition-all resize-none"
                            ></textarea>
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className="p-6 xl:p-8 border-t border-slate-50 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 flex items-center justify-between gap-4">
                    {receivable?.id && receivable.status !== 'paid' ? (
                        <button
                            onClick={handleReceive}
                            disabled={loading}
                            className="bg-emerald-500 hover:bg-emerald-600 text-white px-6 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95 flex items-center gap-2"
                        >
                            <i className="bi bi-arrow-down-circle text-lg"></i>
                            Confirmar Recebimento
                        </button>
                    ) : <div></div>}

                    <div className="flex gap-4">
                        <button
                            onClick={onClose}
                            className="flex-1 px-6 py-3 rounded-xl font-black uppercase tracking-widest text-xs text-slate-500 hover:bg-slate-100 transition-colors"
                        >
                            Cancelar
                        </button>
                        <button
                            onClick={handleSave}
                            disabled={loading}
                            className="flex-1 bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-3 rounded-xl font-black uppercase tracking-widest text-xs shadow-lg shadow-emerald-200 dark:shadow-none transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                        >
                            {loading ? <i className="bi bi-arrow-repeat animate-spin"></i> : <i className="bi bi-save"></i>}
                            Salvar
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { financeService } from '@/pages/services/financeService';
import { toast } from 'react-toastify';
import { 
  CreditCard, 
  ShieldCheck, 
  Settings as SettingsIcon, 
  Zap, 
  TrendingUp, 
  History,
  Lock,
  Globe
} from 'lucide-react';

const FinanceSettings: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [config, setConfig] = useState({
    pv: '',
    client_id: '',
    client_secret: '',
    environment: 'sandbox',
    active: false,
    anticipation_enabled: false
  });
  const [transactions, setTransactions] = useState<any[]>([]);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [configData, transData] = await Promise.all([
        financeService.getRedeConfig(),
        financeService.getRedeTransactions(5)
      ]);
      if (configData) setConfig(configData);
      if (transData) setTransactions(transData);
    } catch (error: any) {
      toast.error('Erro ao carregar configurações: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await financeService.updateRedeConfig(config);
      toast.success('Configurações da Rede salvas com sucesso!');
    } catch (error: any) {
      toast.error('Erro ao salvar: ' + error.message);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-20">
        <div className="w-8 h-8 border-4 border-orange-500 border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="p-6 max-w-6xl mx-auto animate-in fade-in duration-500">
      <div className="flex items-center gap-3 mb-8">
        <div className="p-3 bg-orange-100 dark:bg-orange-950/30 rounded-2xl text-orange-600">
          <SettingsIcon size={28} />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Configurações Financeiras</h1>
          <p className="text-slate-500 text-sm">Gerencie integrações de pagamento e automações</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Coluna Principal: Configuração Rede */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
            <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-slate-100 dark:bg-slate-800 rounded-lg">
                  <CreditCard size={20} className="text-orange-600" />
                </div>
                <h2 className="font-semibold text-slate-800 dark:text-slate-100">Integração Rede (Itaú)</h2>
              </div>
              <div className="flex items-center gap-2 px-3 py-1 bg-orange-50 dark:bg-orange-900/20 text-orange-700 dark:text-orange-400 rounded-full text-xs font-bold uppercase tracking-wider">
                {config.environment === 'sandbox' ? 'Ambiente de Testes' : 'Produção'}
              </div>
            </div>

            <form onSubmit={handleSave} className="p-6 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Número PV (Afiliação)</label>
                  <input 
                    type="text" 
                    value={config.pv}
                    onChange={(e) => setConfig({...config, pv: e.target.value})}
                    placeholder="Ex: 12345678"
                    className="w-full h-11 bg-slate-50 dark:bg-slate-950 border-slate-200 dark:border-slate-800 rounded-xl px-4 focus:ring-2 focus:ring-orange-500 outline-none transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Ambiente</label>
                  <select 
                    value={config.environment}
                    onChange={(e) => setConfig({...config, environment: e.target.value})}
                    className="w-full h-11 bg-slate-50 dark:bg-slate-950 border-slate-200 dark:border-slate-800 rounded-xl px-4 focus:ring-2 focus:ring-orange-500 outline-none transition-all"
                  >
                    <option value="sandbox">Sandbox (Testes)</option>
                    <option value="production">Produção</option>
                  </select>
                </div>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Client ID</label>
                  <input 
                    type="text" 
                    value={config.client_id}
                    onChange={(e) => setConfig({...config, client_id: e.target.value})}
                    className="w-full h-11 bg-slate-50 dark:bg-slate-950 border-slate-200 dark:border-slate-800 rounded-xl px-4 focus:ring-2 focus:ring-orange-500 outline-none transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Client Secret</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={config.client_secret}
                      onChange={(e) => setConfig({...config, client_secret: e.target.value})}
                      className="w-full h-11 bg-slate-50 dark:bg-slate-950 border-slate-200 dark:border-slate-800 rounded-xl px-4 pr-10 focus:ring-2 focus:ring-orange-500 outline-none transition-all"
                    />
                    <Lock size={16} className="absolute right-4 top-3.5 text-slate-400" />
                  </div>
                </div>
              </div>

              <div className="p-4 bg-orange-50 dark:bg-orange-950/20 rounded-2xl flex items-start gap-3">
                <ShieldCheck className="text-orange-600 mt-1 shrink-0" size={18} />
                <p className="text-xs text-orange-900 dark:text-orange-200 leading-relaxed">
                  As credenciais são armazenadas de forma segura e utilizadas apenas pelas Supabase Edge Functions. O Checkout Transparente e o Pix estarão disponíveis assim que ativado.
                </p>
              </div>

              <div className="flex items-center justify-between pt-4">
                <label className="flex items-center gap-3 cursor-pointer">
                  <div className="relative inline-flex items-center cursor-pointer">
                    <input 
                      type="checkbox" 
                      checked={config.active}
                      onChange={(e) => setConfig({...config, active: e.target.checked})}
                      className="sr-only peer" 
                    />
                    <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer dark:bg-slate-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-orange-600"></div>
                  </div>
                  <span className="text-sm font-semibold text-slate-700 dark:text-slate-300">Ativar Integração</span>
                </label>
                <button type="submit" className="px-8 h-11 bg-orange-600 hover:bg-orange-700 text-white font-bold rounded-xl transition-all shadow-lg shadow-orange-600/20">
                  Salvar Alterações
                </button>
              </div>
            </form>
          </div>

          {/* Automação: Antecipação */}
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-6 space-y-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-100 dark:bg-blue-950/30 rounded-lg">
                  <Zap size={20} className="text-blue-600" />
                </div>
                <h2 className="font-semibold text-slate-800 dark:text-slate-100">Motor de Antecipação Inteligente</h2>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={config.anticipation_enabled}
                  onChange={(e) => setConfig({...config, anticipation_enabled: e.target.checked})}
                  className="sr-only peer" 
                />
                <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer dark:bg-slate-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-gray-600 peer-checked:bg-blue-600"></div>
              </label>
            </div>
            <p className="text-sm text-slate-500 leading-relaxed">
              O sistema analisa seu fluxo de caixa de 30 dias. Se houver previsão de saldo negativo, sugerimos a antecipação automática dos recebíveis de cartão de crédito para cobrir o rombo com o menor custo possível.
            </p>
            {config.anticipation_enabled && (
              <div className="p-4 border border-blue-100 dark:border-blue-900/50 bg-blue-50/30 dark:bg-blue-950/20 rounded-2xl flex items-center justify-between">
                <div className="flex items-center gap-3 text-blue-700 dark:text-blue-400">
                  <TrendingUp size={18} />
                  <span className="text-xs font-bold uppercase tracking-wider">Algoritmo Ativo</span>
                </div>
                <span className="text-xs text-blue-600 font-medium">Análise em tempo real</span>
              </div>
            )}
          </div>
        </div>

        {/* Coluna Sidebar: Histórico Recente */}
        <div className="space-y-6">
          <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-6">
