                        <p className={`text-2xl font-black ${saldoPeriodo >= 0 ? 'text-blue-600 dark:text-blue-400' : 'text-amber-600 dark:text-amber-500'}`}>
                            {formatCurrency(saldoPeriodo)}
                        </p>
                    </div>
                </div>

