import React, { useState, useEffect, useMemo } from 'react';
import { MarketingAsset, AssetCategory } from '../../types';
import { assetService } from '../../services/assetService';
import { AssetCard } from './AssetCard';

interface AssetLibraryModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectAsset: (asset: MarketingAsset) => void;
  selectedCampaignId?: string | null;
}

const CATEGORIES: { label: string; value: AssetCategory | 'ALL' }[] = [
  { label: 'Todas', value: 'ALL' },
  { label: 'Selos de Campanha', value: 'CAMPAIGN_BADGE' },
  { label: 'Pagamento & Bandeiras', value: 'PAYMENT' },
  { label: 'Logos & Marcas', value: 'BRAND' },
  { label: 'Descontos & Etiquetas', value: 'DISCOUNT' },
  { label: 'Decorações', value: 'DECORATION' },
  { label: 'Molduras', value: 'FRAME' },
  { label: 'Ícones', value: 'ICON' }
];

export const AssetLibraryModal: React.FC<AssetLibraryModalProps> = ({
  isOpen,
  onClose,
  onSelectAsset,
  selectedCampaignId
}) => {
  const [assets, setAssets] = useState<MarketingAsset[]>([]);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<AssetCategory | 'ALL'>('ALL');
  const [uploadUrl, setUploadUrl] = useState('');
  const [uploadName, setUploadName] = useState('');

  useEffect(() => {
    if (isOpen) {
      loadAssets();
    }
  }, [isOpen]);

  const loadAssets = async () => {
    const data = await assetService.getAll();
    setAssets(data);
  };

  const filteredAssets = useMemo(() => {
    return assets.filter(asset => {
      const matchCategory = selectedCategory === 'ALL' || asset.category === selectedCategory;
      const matchSearch = asset.name.toLowerCase().includes(search.toLowerCase());
      const matchCampaign = !selectedCampaignId || !asset.campaignId || asset.campaignId === selectedCampaignId;
      return matchCategory && matchSearch && matchCampaign;
    });
  }, [assets, selectedCategory, search, selectedCampaignId]);

  const handleAddCustomAsset = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!uploadUrl || !uploadName) return;
    
    await assetService.save({
      name: uploadName,
      type: 'image/png',
      category: selectedCategory === 'ALL' ? 'DECORATION' : selectedCategory,
      fileUrl: uploadUrl,
      campaignId: selectedCampaignId || null,
      width: 400,
      height: 400,
      aspectRatio: 1
    });

    setUploadUrl('');
    setUploadName('');
    loadAssets();
  };

  const handleDelete = async (id: string) => {
    if (confirm('Deseja remover este asset?')) {
      await assetService.delete(id);
      loadAssets();
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[999999] bg-slate-950/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-4xl max-h-[85vh] flex flex-col shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-800 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <i className="bi bi-collection-play-fill text-indigo-400 text-xl"></i>
            <h3 className="text-lg font-bold text-white">Biblioteca de Assets Graficos</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white p-1 text-xl">
            <i className="bi bi-x-lg"></i>
          </button>
        </div>

        {/* Filtros e Busca */}
        <div className="p-4 bg-slate-800/40 border-b border-slate-800 flex flex-wrap items-center gap-3">
          <div className="relative flex-1 min-w-[200px]">
            <i className="bi bi-search absolute left-3 top-2.5 text-slate-400"></i>
            <input
              type="text"
              placeholder="Pesquisar asset..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full bg-slate-950 border border-slate-700 rounded-xl pl-9 pr-3 py-2 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-indigo-500"
            />
          </div>

          <div className="flex items-center gap-1 overflow-x-auto pb-1 max-w-full">
            {CATEGORIES.map(cat => (
              <button
                key={cat.value}
                onClick={() => setSelectedCategory(cat.value)}
                className={`px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-colors ${
                  selectedCategory === cat.value
                    ? 'bg-indigo-600 text-white'
                    : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* Grid de Assets */}
        <div className="flex-1 overflow-y-auto p-6 grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
          {filteredAssets.map(asset => (
            <AssetCard
              key={asset.id}
              asset={asset}
              onSelect={asset => {
                onSelectAsset(asset);
                onClose();
              }}
              onDelete={handleDelete}
            />
          ))}

          {filteredAssets.length === 0 && (
            <div className="col-span-full py-12 text-center text-slate-400">
              <i className="bi bi-image text-4xl block mb-2 opacity-50"></i>
              Nenhum asset encontrado para este filtro.
            </div>
          )}
        </div>

        {/* Adicionar Novo Asset Rápido */}
        <form onSubmit={handleAddCustomAsset} className="p-4 border-t border-slate-800 bg-slate-950/60 flex items-center gap-3">
          <input
            type="text"
            placeholder="Nome do Asset"
            value={uploadName}
            onChange={e => setUploadName(e.target.value)}
            className="bg-slate-900 border border-slate-800 rounded-lg px-3 py-1.5 text-xs text-white placeholder-slate-500 flex-1"
          />
          <input
            type="url"
            placeholder="URL da Imagem (PNG/WebP/SVG)"
            value={uploadUrl}
            onChange={e => setUploadUrl(e.target.value)}
            className="bg-slate-900 border border-slate-800 rounded-lg px-3 py-1.5 text-xs text-white placeholder-slate-500 flex-1"
          />
          <button
            type="submit"
            className="px-4 py-1.5 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold rounded-lg transition-colors"
          >
            Adicionar Asset
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { PostCampaign } from '../types/postCreator';

type Props = { campaigns: PostCampaign[]; onClose: () => void; onSave: (value: Partial<PostCampaign>) => Promise<void>; onRemove: (id: string) => Promise<void>; onSavingChange: (saving: boolean) => void };

export function CampaignManagerModal({ campaigns, onClose, onSave, onRemove, onSavingChange }: Props) {
  const [editing, setEditing] = useState<Partial<PostCampaign>>(); const [busy, setBusy] = useState(false); const initialEdit = useRef(true);
  const persist = async (closeAfterSave = false) => { if (!editing?.name?.trim()) return; setBusy(true); onSavingChange(true); try { await onSave(editing); if (closeAfterSave) setEditing(undefined); } finally { setBusy(false); onSavingChange(false); } };
  const save = async (event: React.FormEvent) => { event.preventDefault(); await persist(true); };
  useEffect(() => {
    if (!editing?.id) { initialEdit.current = true; return; }
    if (initialEdit.current) { initialEdit.current = false; return; }
    const timeout = window.setTimeout(() => void persist(), 700);
    return () => window.clearTimeout(timeout);
  }, [editing]);
  return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4"><div className="w-full max-w-2xl rounded-xl border border-slate-700 bg-slate-900 text-white shadow-2xl"><header className="flex items-center justify-between border-b border-slate-700 p-5"><div><h2 className="font-bold">Gerenciar Campanhas</h2><p className="mt-1 text-xs text-slate-400">Crie, edite, desative ou exclua campanhas.</p></div><button onClick={onClose}>✕</button></header><div className="max-h-[65vh] overflow-auto p-5">{editing ? <form onSubmit={event => void save(event)} className="space-y-3"><label className="block text-xs">Nome<input required value={editing.name || ''} onChange={event => setEditing(value => ({ ...value, name: event.target.value }))} className="mt-1 w-full rounded bg-slate-950 p-2" /></label><label className="block text-xs">Descrição<textarea value={editing.description || ''} onChange={event => setEditing(value => ({ ...value, description: event.target.value }))} className="mt-1 w-full rounded bg-slate-950 p-2" rows={3} /></label><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={editing.active !== false} onChange={event => setEditing(value => ({ ...value, active: event.target.checked }))} /> Campanha ativa</label><div className="flex justify-end gap-2"><button type="button" onClick={() => setEditing(undefined)} className="px-3 py-2 text-xs">Cancelar</button><button disabled={busy} className="rounded bg-indigo-600 px-3 py-2 text-xs font-bold">{editing.id ? 'Salvar agora' : 'Criar campanha'}</button></div></form> : <><button onClick={() => setEditing({ name: '', active: true })} className="mb-3 rounded border border-indigo-400 px-3 py-2 text-xs text-indigo-300">+ Criar campanha</button><div className="space-y-2">{campaigns.map(campaign => <article key={campaign.id} className="flex items-center justify-between gap-3 rounded-lg border border-slate-700 p-3"><div><b className="text-sm">{campaign.name}</b><p className="text-xs text-slate-400">{campaign.active ? 'Ativa' : 'Desativada'}{campaign.description ? ` · ${campaign.description}` : ''}</p></div><div className="flex gap-2 text-xs"><button onClick={() => setEditing(campaign)} className="text-indigo-300">Editar</button><button onClick={() => { if (window.confirm(`Excluir a campanha "${campaign.name}"?`)) void onRemove(campaign.id); }} className="text-rose-300">Excluir</button></div></article>)}</div></>}</div></div></div>;
}

import React, { useEffect, useState } from 'react';
import { uploadFile } from '@/pages/utils/storageService';
import { Layer, DynamicTextLayer } from '../../types';
import { ElementModel, loadElementModels, saveElementModel, applyElementModel } from '../../services/elementModels';

interface Props { layers: Layer[]; selected: string | null; opportunityId?: string; opportunityName?: string; onChange: (layer: Layer) => void; onMessage: (message: string) => void }
export function ElementModelsPanel({ layers, selected, opportunityId, opportunityName, onChange, onMessage }: Props) {
  const [models, setModels] = useState<ElementModel[]>([]), [busy, setBusy] = useState(false);
  const layer = layers.find(l => l.id === selected);
  useEffect(() => { loadElementModels().then(setModels).catch(e => onMessage(e.message)); }, []);
  async function save() {
    if (!layer?.role) return;
    const name = window.prompt('Nome do modelo deste elemento:'); if (!name?.trim()) return;
    setBusy(true);
    try { const saved = await saveElementModel(name.trim(), { ...layer, opportunityId: layer.role === 'badge' ? opportunityId : undefined });
      setModels(await loadElementModels()); onMessage(saved.persistedRemotely ? 'Modelo salvo na biblioteca.' : 'Modelo salvo neste navegador. Sincronização indisponível.');
    } catch (e) { onMessage((e as Error).message); } finally { setBusy(false); }
  }
  async function upload(file?: File) {
    if (!file || !layer) return;
    if (!['image/png', 'image/webp', 'image/jpeg'].includes(file.type)) { onMessage('Use PNG, WebP ou JPEG.'); return; }
    setBusy(true);
    try { const url = await uploadFile(file, `marketing/elements/${crypto.randomUUID()}-${file.name}`);
      onChange({ ...layer, type: 'ASSET', assetId: crypto.randomUUID(), assetUrl: url, visible: true,
        opportunityId: layer.role === 'badge' ? opportunityId : undefined } as Layer);
    } catch (e) { onMessage((e as Error).message); } finally { setBusy(false); }
  }
  const input = 'w-full bg-slate-950 border border-slate-700 rounded p-2 text-xs';
  const regions = [
    ['TOP_LEFT', '↖'], ['TOP_CENTER', '↑'], ['TOP_RIGHT', '↗'],
    ['CENTER_LEFT', '←'], ['CENTER', '●'], ['CENTER_RIGHT', '→'],
    ['BOTTOM_LEFT', '↙'], ['BOTTOM_CENTER', '↓'], ['BOTTOM_RIGHT', '↘'],
  ] as const;
  return <section className="p-4 bg-slate-900 rounded-xl space-y-3">
    <h2 className="font-semibold">Propriedades do elemento</h2>
    {!layer && <p className="text-xs text-slate-400">Selecione um elemento no painel de camadas para definir suas regras.</p>}
    {layer && <div className="space-y-2 border-t border-slate-700 pt-3">
      <p className="text-sm">Editar: {layer.name}</p>
      {layer.role === 'main' && <div className="rounded border border-cyan-900/70 bg-cyan-950/20 p-2 text-[11px] text-cyan-100">
        Região: {layer.preferredRegion || 'CENTER'} · Escala resultante: {Math.round(Math.min(100, layer.width / .65 * 100))}% · alvo: 90%<br />
        Ocupação visual: {Math.round(layer.width * (layer.height || .1) * ((layer.subjectBounds?.width || .9) * (layer.subjectBounds?.height || .9)) * 100)}%
      </div>}
      <div><p className="text-xs mb-1">Posição preferida</p><div className="grid grid-cols-3 gap-1">
        {regions.map(([region, icon]) => <button key={region} title={region} onClick={() => onChange({ ...layer, preferredRegion: region })}
          className={layer.preferredRegion === region ? 'bg-indigo-600 rounded p-2' : 'bg-slate-800 hover:bg-slate-700 rounded p-2'}>{icon}</button>)}
      </div></div>
      <div className="grid grid-cols-2 gap-2"><label className="text-xs">Tamanho<select className={input} value={layer.preferredSize || 'medium'} onChange={e => onChange({ ...layer, preferredSize: e.target.value as Layer['preferredSize'] })}>
        <option value="small">Pequeno</option><option value="medium">Médio</option><option value="large">Grande</option></select></label>
        <label className="text-xs">Prioridade<select className={input} value={layer.priority || 'MEDIUM'} onChange={e => onChange({ ...layer, priority: e.target.value as Layer['priority'] })}>
          <option value="VERY_HIGH">Muito alta</option><option value="HIGH">Alta</option><option value="MEDIUM">Média</option><option value="LOW">Baixa</option></select></label></div>
      <label className="block text-xs">Flexibilidade<select className={input} value={layer.positionTolerance || 'automatic'} onChange={e => onChange({ ...layer, positionTolerance: e.target.value as Layer['positionTolerance'] })}>
        <option value="automatic">Automática dentro da região</option><option value="strict">Manter estritamente na região</option></select></label>
      <label className="block text-xs">Comportamento para IA<textarea className={input} value={layer.aiInstructions || ''} placeholder="Ex.: reduzir fonte antes de reduzir o preço" onChange={e => onChange({ ...layer, aiInstructions: e.target.value })} /></label>
      <div><p className="text-xs mb-1">Estilos disponíveis</p><div className="grid grid-cols-2 gap-2">{models.filter(model => model.role === layer.role && (!model.opportunityId || model.opportunityId === opportunityId) &&
        (model.id !== 'default-badge' || /queima|salvados/i.test(opportunityName || ''))).map(model => <button key={model.id} onClick={() => onChange({ ...applyElementModel(layer, model), ...(layer.role === 'badge' ? { visible: !!opportunityId, opportunityId } : {}) })}
          className={layer.modelId === model.id ? 'border-2 border-indigo-400 rounded p-2 text-left bg-indigo-950/30' : 'border border-slate-700 rounded p-2 text-left hover:border-slate-500'}><span className="block h-6 rounded bg-slate-800 mb-1" /><span className="text-xs">{model.name}</span></button>)}</div></div>
      {'fontFamily' in layer && <>
        <label className="block text-xs">Fonte<select className={input} value={layer.fontFamily} onChange={e => onChange({ ...layer, fontFamily: e.target.value })}>
          {Array.from(new Set([layer.fontFamily, 'Arial, sans-serif', 'Georgia, serif', 'Impact, sans-serif', 'cursive'])).map(font => <option key={font}>{font}</option>)}
        </select></label>
        <label className="block text-xs">Tamanho da fonte<input className={input} type="range" min="1.4" max="9" step="0.1"
          value={layer.fontSizeRelative * 100} onChange={e => onChange({ ...layer, fontSizeRelative: Number(e.target.value) / 100 })} /></label>
        <label className="text-xs">Cor <input type="color" value={layer.color} onChange={e => onChange({ ...layer, color: e.target.value })} /></label>
        <label className="text-xs ml-3">Fundo <input type="color" value={layer.backgroundColor || '#24170e'} onChange={e => onChange({ ...layer, backgroundColor: e.target.value })} /></label>
      </>}
      {layer.type === 'VARIATION_GALLERY' && <label className="block text-xs">Distribuição<select className={input} value={(layer as any).direction}
        onChange={e => onChange({ ...layer, direction: e.target.value } as Layer)}>
        <option value="horizontal">Linha</option><option value="vertical">Coluna</option><option value="grid">Grid</option>
      </select></label>}
      {['badge', 'brand', 'installment', 'storeSlogan'].includes(layer.role || '') && <label className="block text-xs">Usar imagem deste elemento
        <input disabled={busy} type="file" accept="image/png,image/webp,image/jpeg" onChange={e => { upload(e.target.files?.[0]); e.target.value = ''; }} className="block w-full mt-1" />
      </label>}
      <button disabled={busy || !layer.role} onClick={save} className="w-full bg-indigo-600 rounded p-2 text-xs">Salvar como novo modelo</button>
    </div>}
    <p className="text-xs text-slate-400">O template guarda a região e as regras. O estilo visual escolhido pela campanha será aplicado no fluxo de geração.</p>
  </section>;
}

import React, { useEffect, useRef, useState } from 'react';
import { usePostEditor } from './usePostEditor';
export function ModelProductPicker({ editor: e, onSelected }: { editor: ReturnType<typeof usePostEditor>; onSelected?: (id: string) => void }) {
  const [open, setOpen] = useState(false);
  const listRef = useRef<HTMLDivElement>(null);
  useEffect(() => { if (!open) e.setSearch(''); }, [open]);
  const select = async (id: string) => { await e.selectProduct(id); onSelected?.(id); setOpen(false); };
  const loadMore = () => {
    const node = listRef.current;
    if (node && node.scrollTop + node.clientHeight >= node.scrollHeight - 48 && !e.loading && e.products.length < e.total) e.setPage(e.page + 1);
  };
  return <div className="relative">
    <button title="Usado somente para visualizar o template" onClick={() => setOpen(value => !value)}
      className="h-9 max-w-64 rounded-md border border-slate-700 bg-slate-900 px-3 text-xs text-left hover:border-slate-500 flex items-center gap-2">
      <i className="bi bi-eye text-indigo-300" />
      <span className="truncate">{e.product ? e.product.name || e.product.title : 'Produto de preview'}</span>
      {e.product && <span onClick={event => { event.stopPropagation(); void select(''); }} className="text-slate-400 hover:text-white" aria-label="Limpar produto de preview">×</span>}
      <i className="bi bi-chevron-down text-[10px]" />
    </button>
    {open && <div className="absolute right-0 top-11 z-50 w-80 rounded-lg border border-slate-700 bg-slate-900 p-2 shadow-2xl">
      <label className="sr-only" htmlFor="template-model-product">Buscar produto de preview</label>
      <div className="relative"><i className="bi bi-search absolute left-2 top-2 text-slate-500" /><input id="template-model-product" autoFocus aria-label="Buscar produto de preview"
        className="w-full rounded bg-slate-950 py-2 pl-7 pr-2 text-xs outline-none ring-indigo-500 focus:ring-1" placeholder="Buscar produto..."
        value={e.search} onChange={event => e.setSearch(event.target.value)} /></div>
      <div ref={listRef} onScroll={loadMore} className="mt-2 max-h-64 overflow-y-auto">
        {e.products.filter(product => !!product.id).map(product => <button key={product.id} onClick={() => void select(product.id!)} className="block w-full rounded px-2 py-2 text-left text-xs hover:bg-slate-800">
          {product.name || product.title}
        </button>)}
        {!e.loading && e.products.length === 0 && <p className="p-3 text-center text-xs text-slate-500">Nenhum produto encontrado.</p>}
        {e.loading && <p className="p-3 text-center text-xs text-slate-400">Buscando produtos…</p>}
      </div>
      <p className="px-1 pt-2 text-[10px] text-slate-500">Usado somente para visualizar o template.</p>
    </div>}
  </div>;
}

import React, { useEffect, useMemo, useState } from 'react';
import { usePostEditor } from './usePostEditor';
import { environmentGuidance } from '../../services/environmentGuidance';

interface Props {
  editor: ReturnType<typeof usePostEditor>;
  savedPrompts?: Record<string, string>;
  onPromptChange: (key: string, prompt: string) => void;
}
export function ProductPostControls({ editor: e, savedPrompts = {}, onPromptChange }: Props) {
  const guidance = useMemo(() => environmentGuidance(e.product?.category || '', e.product?.name || ''), [e.product?.category, e.product?.name]);
  const [prompt, setPrompt] = useState('');
  useEffect(() => { setPrompt(savedPrompts[guidance.key] || guidance.prompt); }, [guidance.key, guidance.prompt, savedPrompts]);
  return <section className="space-y-2 text-sm">
    <div className="border-b border-slate-800 pb-2"><h2 className="text-xs font-bold uppercase tracking-wider text-slate-300">Template</h2>
      <p className="mt-1 text-xs text-slate-500">Defina regras gerais; a ambientação é um fluxo separado.</p></div>
    <details className="rounded border border-slate-800 bg-slate-900/60 p-2">
      <summary className="cursor-pointer text-xs font-medium">Orientação de ambientação</summary>
      <p className="mt-2 text-[11px] text-slate-500">Padrão para: {guidance.category}.</p>
      <textarea className="mt-2 min-h-32 w-full rounded border border-slate-700 bg-slate-950 p-2 text-xs" value={prompt}
        onChange={event => { const value = event.target.value; setPrompt(value); onPromptChange(guidance.key, value); }} />
