    <details className="rounded border border-slate-800 bg-slate-900/60 p-2">
      <summary className="cursor-pointer text-xs font-medium">Texto de preview</summary>
      <label className="mt-2 block text-xs">Slogan de exemplo<input className="mt-1 w-full rounded bg-slate-950 p-2" maxLength={160}
        value={e.slogan} onChange={event => e.setSlogan(event.target.value)} placeholder="Usado somente na prévia" /></label>
    </details>
    <details className="rounded border border-slate-800 bg-slate-900/60 p-2"><summary className="cursor-pointer text-xs font-medium">Safe area e regras de layout</summary>
      <p className="mt-2 text-xs text-slate-500">As áreas seguras e regiões preferidas são respeitadas pela IA ao encaixar o post.</p></details>
  </section>;
}

import React, { useEffect, useMemo, useState } from 'react';
import { PostModelAsset, PostModelExtra, PostTemplate } from '../types/postTemplate';
import { usePostEditor } from './Editor/usePostEditor';
import { generatePostModelPreview } from '../services/postModelPreviewGenerator';
import {
  extractProductImagesFromProduct,
  resolveModelAssets,
  validateGenerationPreFlight,
} from '../services/postModelAssetResolver';
import {
  assemblePreviewPrompt,
} from '../services/postModelPreviewGenerator';
import { postGenerationGuidelines } from '../services/postGenerationGuidelines';
import { buildPostTemplateDraft } from '../services/postTemplateDraft';
import { getPostModelPreviewCacheKey, readPostModelPreviewCache, writePostModelPreviewCache } from '../services/postModelPreviewCache';
import {
  GenerationContextData,
  GenerationContextModal,
} from './GenerationContextModal';

interface Props {
  value?: PostTemplate;
  onClose: () => void;
  onSave: (value: Partial<PostTemplate>) => Promise<void>;
}

const readFile = (file: File) =>
  new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });

export function ModelFormModal({ value, onClose, onSave }: Props) {
  const editor = usePostEditor();
  const [name, setName] = useState(value?.name || '');
  const [description] = useState('');
  const [prompt, setPrompt] = useState(value?.imagePrompt || '');
  const [format, setFormat] = useState<'4:5' | '9:16'>(
    value?.aspectRatio === '9:16' ? '9:16' : '4:5'
  );
  const [assets, setAssets] = useState<PostModelAsset[]>(value?.assets || []);
  const [extras, setExtras] = useState<PostModelExtra[]>(value?.extras || []);
  const [saving, setSaving] = useState(false);

  // Estados do Preview e Debug
  const [previewImage, setPreviewImage] = useState<string>();
  const [previewHash, setPreviewHash] = useState('');
  const [previewStatus, setPreviewStatus] = useState<'updated' | 'stale' | 'incomplete' | 'none'>('none');
  const [previewBusy, setPreviewBusy] = useState(false);
  const [previewError, setPreviewError] = useState('');
  const [debugModalOpen, setDebugModalOpen] = useState(false);
  const [productResultsOpen, setProductResultsOpen] = useState(false);

  useEffect(() => {
    setName(value?.name || '');
    setPrompt(value?.imagePrompt || '');
    setAssets(value?.assets || []);
    setExtras(value?.extras || []);
  }, [value?.id]);

  const draft: PostTemplate = useMemo(
    () => buildPostTemplateDraft({ value, name, description, prompt, format, assets, extras, now: new Date().toISOString() }),
    [value, name, description, prompt, format, assets, extras]
  );

  // Extração semântica das imagens do produto (Regras 4 e 5)
  const productImages = useMemo(() => {
    if (!editor.product && !editor.data) return { primary: '', variations: [] };
    return extractProductImagesFromProduct(editor.product || editor.data);
  }, [editor.product, editor.data]);

  const resolvedAssets = useMemo(
    () => resolveModelAssets(draft, editor.opportunity?.name),
    [draft, editor.opportunity?.name]
  );

  // Hash completo para controle de cache e invalidação (Regra 17)
  const currentHash = useMemo(() => {
    const guidelines = postGenerationGuidelines.get();
    return JSON.stringify({
      prompt,
      format,
      opportunity: editor.opportunity?.name || '',
      productName: editor.data?.name || '',
      productPrice: editor.data?.price || '',
      guidelines: guidelines.content,
      primaryImage: productImages.primary,
      secondaryImage: productImages.secondary || '',
      variationImages: productImages.variations,
      assets: assets.map((a) => [a.id, a.name, a.fileUrl]),
      referenceUrl: resolvedAssets.primaryVisualReference?.fileUrl || '',
    });
  }, [prompt, format, editor.opportunity?.name, editor.data, productImages, assets, resolvedAssets]);

  // Recupera preview salvo no localStorage
  useEffect(() => {
    const key = getPostModelPreviewCacheKey(draft.id, editor.product?.id || '', format);
    {
      const cached = readPostModelPreviewCache(key);
      if (cached) {
        setPreviewImage(cached.image);
        setPreviewHash(cached.hash || '');
        setPreviewStatus(cached.hash === currentHash ? 'updated' : 'stale');
      } else {
        setPreviewImage(undefined);
        setPreviewHash('');
        setPreviewStatus('none');
      }
    }
  }, [editor.product?.id, draft.id, format, currentHash]);

  // Monta contexto completo para depuração / inspeção (Regra 13)
  const currentDebugData: GenerationContextData = useMemo(() => {
    let finalPromptStr = '';
    try {
      if (editor.data && prompt.trim()) {
        finalPromptStr = assemblePreviewPrompt({
          template: draft,
          product: {
            name: editor.data.name,
            price: editor.data.price,
            oldPrice: editor.data.oldPrice,
              installmentValue: (editor.data as any).installmentValue,
            mainImageUrl: productImages.primary,
            category: editor.product?.category,
            description: editor.product?.description,
          },
          format,
          opportunityName: editor.opportunity?.name,
          images: productImages,
          assets: resolvedAssets,
        });
      }
    } catch (e: any) {
      finalPromptStr = `[Erro na validação do prompt]: ${e.message}`;
    }

    return {
      productName: editor.data?.name || 'Nenhum produto selecionado',
      productPrice: editor.data?.price || '—',
      productOldPrice: editor.data?.oldPrice,
      opportunityName: editor.opportunity?.name,
      resolvedOpportunity: /queima|salvados/i.test(editor.opportunity?.name || '')
        ? 'QUEIMA_DOS_SALVADOS'
        : 'SEM_OPORTUNIDADE',
      format,
      hasPrimaryImage: !!productImages.primary,
      hasSecondaryImage: !!productImages.secondary,
      variationImagesCount: productImages.variations.length,
      hasPrimaryVisualReference: !!resolvedAssets.primaryVisualReference,
      hasLogoAsset: !!resolvedAssets.logoAsset,
      hasOpportunityAsset: !!resolvedAssets.opportunityAsset,
      hasInstallmentAsset: !!resolvedAssets.installmentAsset,
      finalPrompt: finalPromptStr || prompt,
    };
  }, [draft, editor.data, editor.product, editor.opportunity, format, productImages, resolvedAssets, prompt]);

  const addFiles = async (files: FileList | null) => {
    if (!files) return;
    const added = await Promise.all(
      [...files]
        .filter((file) => /^image\/(png|jpeg|webp|svg\+xml)$/.test(file.type) || file.type === 'application/pdf')
        .map(async (file) => ({
          id: crypto.randomUUID(),
          name: file.name,
          fileUrl: await readFile(file),
          mimeType: file.type,
        }))
    );
    setAssets((current) => [...current, ...added]);
  };

  const generatePreview = async () => {
    if (!editor.data || !prompt.trim()) return;
    setPreviewBusy(true);
    setPreviewError('');

    try {
      const result = await generatePostModelPreview({
        model: draft,
        product: {
          name: editor.data.name,
          price: editor.data.price,
          oldPrice: editor.data.oldPrice,
          installmentValue: (editor.data as any).installmentValue,
          mainImageUrl: productImages.primary,
          category: editor.product?.category,
          description: editor.product?.description,
        },
        productId: editor.product?.id || '',
        format,
        opportunity: editor.opportunity?.name,
        images: productImages,
      });

      const key = getPostModelPreviewCacheKey(draft.id, editor.product?.id || '', format);
      writePostModelPreviewCache(key, {
          image: result.imageUrl,
          hash: currentHash,
          generatedAt: new Date().toISOString(),
          provider: 'gemini',
      });

      setPreviewImage(result.imageUrl);
      setPreviewHash(currentHash);
      setPreviewStatus('updated');
    } catch (error: any) {
      setPreviewError(error.message || 'Não foi possível gerar um novo preview.');
      setPreviewStatus('incomplete');
    } finally {
      setPreviewBusy(false);
    }
  };

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!name.trim() || !prompt.trim()) return;
    setSaving(true);
    try {
      await onSave(draft);
      onClose();
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 p-4 backdrop-blur-sm animate-fadeIn">
      <form
        onSubmit={submit}
        className="max-h-[94vh] w-full max-w-6xl overflow-hidden rounded-xl border border-slate-700 bg-slate-900 text-white shadow-2xl flex flex-col"
      >
        <header className="flex items-center justify-between border-b border-slate-700 p-5 shrink-0">
          <div>
            <h2 className="text-lg font-bold text-white">
              {value ? 'Editar modelo de post' : 'Novo modelo de post'}
            </h2>
            <p className="text-xs text-slate-400">
              Instruções de IA, referências visuais oficiais e preview de teste multimodal.
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-white transition-colors text-lg"
          >
            ✕
          </button>
        </header>

        <div className="grid flex-1 grid-cols-1 overflow-hidden lg:grid-cols-[1fr_1.1fr]">
          {/* Coluna Esquerda: Formulário de Configuração */}
          <div className="overflow-y-auto p-5 space-y-4 border-r border-slate-800">
            <div className="relative">
              <label className="block text-xs font-semibold text-slate-300">
                Nome do Modelo *
              </label>
              <input
                required
                className="mt-1 w-full rounded-lg bg-slate-950 border border-slate-800 p-2.5 text-sm text-white focus:border-indigo-500 outline-none"
                placeholder="Ex: Queima dos Salvados — Produto Promocional"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>

            <div className="relative">
              <label className="block text-xs font-semibold text-slate-300">
                Produto para Testar Preview
              </label>
              <input
                className="mt-1 w-full rounded-lg bg-slate-950 border border-slate-800 p-2 text-xs text-white"
                placeholder="Buscar produto por nome..."
                value={editor.search}
                onFocus={() => setProductResultsOpen(true)}
                onChange={(e) => { editor.setSearch(e.target.value); setProductResultsOpen(true); }}
              />
              {productResultsOpen && <div className="absolute z-30 mt-1 max-h-56 w-full overflow-y-auto rounded-lg border border-slate-700 bg-slate-950 p-1 shadow-xl">
                {editor.products.filter((p) => p.id).map((p) => <button key={p.id} type="button" onClick={() => { void editor.selectProduct(p.id!); setProductResultsOpen(false); }} className="block w-full rounded px-3 py-2 text-left text-xs text-slate-200 hover:bg-slate-800">{p.name || p.title}</button>)}
                {!editor.loading && editor.products.length === 0 && <p className="p-3 text-center text-xs text-slate-500">Nenhum produto encontrado.</p>}
              </div>}
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-300">Oportunidade</label>
              <div className="mt-1 flex h-9 items-center rounded-lg border border-slate-800 bg-slate-950 px-3 text-xs text-amber-300 font-medium">
                {editor.opportunity?.name || ''}
              </div>
            </div>

            <div>
              <div>
                <label className="block text-xs font-semibold text-slate-300">
                  Prompt do Modelo *
                </label>
              </div>
              <textarea
                required
                rows={10}
                className="mt-1 w-full rounded-lg bg-slate-950 border border-slate-800 p-2.5 text-xs leading-relaxed text-white focus:border-indigo-500 outline-none font-mono"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Instruções de layout e estética para a geração..."
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">
                Arquivos e Referências do Modelo ({assets.length})
              </label>
              <div className="grid grid-cols-2 gap-2 mb-2">
                {assets.map((asset) => (
                  <article
                    key={asset.id}
                    className="overflow-hidden rounded border border-slate-700 bg-slate-950 text-[11px] text-slate-300"
                  >
                    <div className="flex items-center justify-between gap-2 border-b border-slate-800 px-2 py-1.5"><span className="truncate font-medium" title={asset.name}>{asset.name}</span><button type="button" onClick={() => setAssets((curr) => curr.filter((a) => a.id !== asset.id))} className="text-slate-400 hover:text-rose-300">×</button></div>
                    {asset.mimeType === 'application/pdf' || /\.pdf$/i.test(asset.name) ? <div className="flex h-20 items-center justify-center gap-2 text-rose-300"><i className="bi bi-file-earmark-pdf text-2xl" /><b>PDF</b></div> : <img src={asset.fileUrl} alt={asset.name} className="h-20 w-full object-contain p-1" />}
                  </article>
                ))}
              </div>
              <label className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-slate-800 bg-slate-950 px-3 py-1.5 text-xs text-slate-300 hover:bg-slate-800 transition-colors">
                <span>+ Adicionar referências</span>
                <input
                  type="file"
                  multiple
                  accept="image/*,application/pdf"
                  className="hidden"
                  onChange={(e) => void addFiles(e.target.files)}
                />
              </label>
            </div>

            <footer className="pt-3 flex gap-2 border-t border-slate-800">
              <button
                type="button"
                onClick={onClose}
                className="rounded-lg border border-slate-700 bg-slate-800 px-4 py-2 text-xs font-medium text-slate-300 hover:bg-slate-700 transition-colors"
              >
                Cancelar
              </button>
              <button
                type="submit"
                disabled={saving}
                className="rounded-lg bg-indigo-600 px-4 py-2 text-xs font-semibold text-white hover:bg-indigo-500 transition-colors disabled:opacity-50"
              >
                {saving ? 'Salvando...' : 'Salvar modelo'}
              </button>
            </footer>
          </div>

          {/* Coluna Direita: Preview e Inspeção de Debug */}
          <aside className="flex flex-col items-center justify-between bg-slate-950/80 p-5 overflow-y-auto">
            <div className="w-full flex items-center justify-between border-b border-slate-800/80 pb-3">
              <div className="flex items-center gap-2">
                <b className="text-xs uppercase tracking-wider text-slate-400">Preview Multimodal</b>
                {previewStatus === 'updated' && (
                  <span className="rounded bg-emerald-500/10 border border-emerald-500/20 px-2 py-0.5 text-[11px] font-semibold text-emerald-400">
                    ✓ Atualizado
                  </span>
                )}
                {previewStatus === 'stale' && (
                  <span className="rounded bg-amber-500/10 border border-amber-500/20 px-2 py-0.5 text-[11px] font-semibold text-amber-400">
                    ⚠ Desatualizado
                  </span>
                )}
                {previewStatus === 'incomplete' && (
                  <span className="rounded bg-rose-500/10 border border-rose-500/20 px-2 py-0.5 text-[11px] font-semibold text-rose-400">
                    ⚠ Resultado incompleto
                  </span>
                )}
              </div>

              <button
                type="button"
                onClick={() => setDebugModalOpen(true)}
                className="inline-flex items-center gap-1.5 rounded border border-slate-800 bg-slate-900 px-2.5 py-1 text-[11px] font-medium text-indigo-300 hover:bg-slate-800 hover:text-indigo-200 transition-colors"
              >
                <span>[Ver contexto da geração]</span>
              </button>
            </div>

            <div className="my-auto flex flex-col items-center justify-center p-2 text-center w-full">
              {previewImage ? (
                <div className="relative group max-w-full">
                  <img
                    src={previewImage}
                    alt="Preview do post gerado"
                    className="max-h-[58vh] max-w-full rounded-lg shadow-xl object-contain border border-slate-800"
                  />
                </div>
              ) : (
                <div className="rounded-xl border border-dashed border-slate-800 p-8 max-w-sm">
                  <p className="text-xs text-slate-400 leading-relaxed">
                    Nenhum preview gerado para este produto.
                    <br />
                    Selecione um produto ao lado e gere uma arte para validar o modelo.
                  </p>
                </div>
              )}

              {previewError && (
                <div className="mt-3 w-full max-w-md rounded-lg border border-rose-500/20 bg-rose-500/10 p-2.5 text-xs text-rose-300">
                  {previewError}
                </div>
              )}
            </div>

            <div className="w-full pt-3 border-t border-slate-800 flex items-center justify-between gap-3">
              <span className="text-[11px] text-slate-400">
                {productImages.primary ? (
                  <>
                    Variações: <strong className="text-white">{productImages.variations.length}</strong>
                    {productImages.secondary ? ' · 2ª foto inclusa' : ''}
                  </>
                ) : (
                  'Selecione um produto com foto'
                )}
              </span>

              <button
                type="button"
                disabled={!editor.data || !productImages.primary || previewBusy}
                onClick={() => void generatePreview()}
                className="inline-flex items-center gap-2 rounded-lg bg-amber-500 px-4 py-2.5 text-xs font-bold text-slate-950 hover:bg-amber-400 transition-colors disabled:opacity-50 shadow-lg"
              >
                {previewBusy ? (
                  <>
                    <svg className="h-3.5 w-3.5 animate-spin" viewBox="0 0 24 24" fill="none">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
                    </svg>
                    <span>Gerando preview...</span>
                  </>
                ) : (
                  <span>✨ {previewImage ? 'Gerar novo preview' : 'Gerar preview com IA'}</span>
                )}
              </button>
            </div>
          </aside>
        </div>
      </form>

      {/* Modal de Debug / Inspeção do Contexto da Geração */}
      {debugModalOpen && (
        <GenerationContextModal
          data={currentDebugData}
          onClose={() => setDebugModalOpen(false)}
        />
      )}
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { defaultContentKind, ElementModel, ElementModelReference, ElementType, elementLabel } from '../types/postCreator';

type Props = { elementType: ElementType; value?: ElementModel; initialOpportunityId?: string; opportunities: Array<{ id: string; name: string }>; onClose: () => void; onSave: (model: ElementModel) => Promise<void>; onSavingChange: (saving: boolean) => void };
const fileToReference = (file: File): Promise<ElementModelReference> => new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve({ id: crypto.randomUUID(), name: file.name, fileUrl: String(reader.result), mimeType: file.type }); reader.onerror = reject; reader.readAsDataURL(file); });

export function PostCreatorModelModal({ elementType, value, initialOpportunityId, opportunities, onClose, onSave, onSavingChange }: Props) {
  const [name, setName] = useState(value?.name || ''); const [prompt, setPrompt] = useState(value?.prompt || '');
  const [references, setReferences] = useState<ElementModelReference[]>(value?.referenceFiles || []); const [opportunityId, setOpportunityId] = useState(value?.opportunityId || initialOpportunityId || ''); const [saving, setSaving] = useState(false); const initialEdit = useRef(true);
  useEffect(() => { setName(value?.name || ''); setPrompt(value?.prompt || ''); setReferences(value?.referenceFiles || []); setOpportunityId(value?.opportunityId || initialOpportunityId || ''); }, [value?.id, initialOpportunityId]);
  const modelValue = (): ElementModel => ({ id: value?.id || crypto.randomUUID(), name: name.trim(), elementType, contentKind: value?.contentKind || defaultContentKind[elementType], opportunityId: elementType === 'BADGE' ? opportunityId : null, prompt, referenceFiles: references, generatedAssetUrl: value?.generatedAssetUrl, generationInputHash: value?.generationInputHash, generationVersion: value?.generationVersion || 1, status: value?.status || 'NO_PREVIEW', createdAt: value?.createdAt || new Date().toISOString(), updatedAt: new Date().toISOString() });
  const persist = async (closeAfterSave = false) => { if (!name.trim() || (elementType === 'BADGE' && !opportunityId)) return; setSaving(true); onSavingChange(true); try { await onSave(modelValue()); if (closeAfterSave) onClose(); } finally { setSaving(false); onSavingChange(false); } };
  const submit = async (event: React.FormEvent) => { event.preventDefault(); await persist(true); };
  useEffect(() => {
    if (!value) return;
    if (initialEdit.current) { initialEdit.current = false; return; }
    const timeout = window.setTimeout(() => void persist(), 700);
    return () => window.clearTimeout(timeout);
  }, [name, prompt, references, opportunityId]);
  const addReferences = async (files: FileList | null) => { if (!files) return; const added = await Promise.all(Array.from(files).map(fileToReference)); setReferences(items => items.concat(added)); };
  return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4"><form onSubmit={submit} className="w-full max-w-xl rounded-xl border border-slate-700 bg-slate-900 text-white shadow-2xl"><header className="flex items-start justify-between border-b border-slate-700 p-5"><div><h2 className="font-bold">{value ? 'Editar' : 'Configurar'} prompt do elemento</h2><p className="mt-1 text-xs text-slate-400">Tipo: {elementLabel[elementType]}. Instruções visuais e diretrizes de arte para o post.</p></div><button type="button" onClick={onClose}>✕</button></header><div className="space-y-4 p-5"><label className="block text-xs font-semibold text-slate-300">Identificação / Nome<input required value={name} onChange={event => setName(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-700 bg-slate-950 p-2.5 text-sm" placeholder={`Ex.: ${elementLabel[elementType]} Padrão`} /></label>{elementType === 'BADGE' && <label className="block text-xs font-semibold text-slate-300">Oportunidade *<select required value={opportunityId} onChange={event => setOpportunityId(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-700 bg-slate-950 p-2.5 text-sm"><option value="">Selecionar oportunidade</option>{opportunities.map(opportunity => <option key={opportunity.id} value={opportunity.id}>{opportunity.name}</option>)}</select></label>}<label className="block text-xs font-semibold text-slate-300">Prompt do elemento<textarea value={prompt} onChange={event => setPrompt(event.target.value)} rows={6} className="mt-1 w-full rounded-lg border border-slate-700 bg-slate-950 p-2.5 text-sm" placeholder="Descreva apenas o estilo, decoração e hierarquia visual; não fixe preço ou dados comerciais." /></label><div><p className="text-xs font-semibold text-slate-300">Anexos ({references.length})</p><div className="mt-2 flex flex-wrap gap-2">{references.map(reference => <figure key={reference.id} className="relative w-20 overflow-hidden rounded border border-slate-700"><img src={reference.fileUrl} alt={reference.name} className="h-16 w-full object-cover" /><button type="button" onClick={() => setReferences(items => items.filter(item => item.id !== reference.id))} className="absolute right-1 top-1 rounded bg-black/70 px-1 text-xs">×</button><figcaption className="truncate p-1 text-[9px]">{reference.name}</figcaption></figure>)}</div><label className="mt-2 inline-flex cursor-pointer rounded-lg border border-slate-700 px-3 py-2 text-xs hover:bg-slate-800">Adicionar anexo<input type="file" className="hidden" multiple accept="image/*" onChange={event => void addReferences(event.target.files)} /></label></div>{value?.generatedAssetUrl && <img src={value.generatedAssetUrl} alt="Asset atual" className="max-h-40 rounded border border-slate-700 object-contain" />}</div><footer className="flex justify-end gap-2 border-t border-slate-700 p-4"><button type="button" onClick={onClose} className="rounded-lg px-3 py-2 text-xs">Cancelar</button><button disabled={saving} className="rounded-lg bg-indigo-600 px-4 py-2 text-xs font-bold">Salvar prompt</button></footer></form></div>;
}

import React, { useCallback, useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import { supabase } from '@/pages/utils/supabaseConfig';
import { PostCampaign } from '../../types/postCreator';
import { ProductPost, ProductPostFormat, productPostFormatLabel } from '../../types/postSpecification';
import { productPostsService } from '../../services/productPostsService';
import { PostCard } from './PostCard';
import { UploadPostModal } from './UploadPostModal';

interface PostsLibraryPageProps {
  campaigns: PostCampaign[];
  /** Se fornecido, a biblioteca é aberta já filtrada por esse produto. */
  initialProductId?: string;
  initialProductName?: string;
}

interface ProductOption {
  id: string;
  name: string;
  slug: string;
}

export function PostsLibraryPage({ campaigns, initialProductId, initialProductName }: PostsLibraryPageProps) {
  const [posts, setPosts] = useState<ProductPost[]>([]);
  const [loading, setLoading] = useState(false);
  const [uploadOpen, setUploadOpen] = useState(false);
  const [deletingId, setDeletingId] = useState<string>();

  // Filtros
  const [filterProductId, setFilterProductId] = useState(initialProductId ?? '');
  const [filterProductName, setFilterProductName] = useState(initialProductName ?? '');
  const [filterCampaignId, setFilterCampaignId] = useState('');
  const [filterFormat, setFilterFormat] = useState<ProductPostFormat | ''>('');
  const [productSearch, setProductSearch] = useState('');
  const [productSuggestions, setProductSuggestions] = useState<ProductOption[]>([]);

  // Mapa de nomes
  const [productNames, setProductNames] = useState<Record<string, string>>({});
  const campaignMap = Object.fromEntries(campaigns.map(c => [c.id, c.name]));

  const loadPosts = useCallback(async () => {
    setLoading(true);
    try {
      const results = await productPostsService.listPosts({
        productId: filterProductId || undefined,
        campaignId: filterCampaignId || undefined,
        format: filterFormat || undefined,
      });
      setPosts(results);

      // Carregar nomes dos produtos que ainda não temos
      const missingIds = [...new Set(results.map(p => p.productId))].filter(id => !productNames[id]);
      if (missingIds.length > 0) {
        const { data } = await supabase
          .from('products')
          .select('id, name, description')
          .in('id', missingIds);
        if (data) {
          setProductNames(prev => ({
            ...prev,
            ...Object.fromEntries(data.map((p: any) => [p.id, p.name ?? p.description ?? 'Produto'])),
          }));
        }
      }
    } catch (err: any) {
      toast.error(err.message || 'Erro ao carregar a biblioteca.');
    } finally {
      setLoading(false);
    }
  }, [filterProductId, filterCampaignId, filterFormat, productNames]);

  useEffect(() => { void loadPosts(); }, [filterProductId, filterCampaignId, filterFormat]); // eslint-disable-line react-hooks/exhaustive-deps

  const handleSearchProducts = useCallback(async (query: string): Promise<ProductOption[]> => {
    const { data } = await supabase
      .from('products')
      .select('id, name, description, slug')
      .or(`name.ilike.%${query}%,description.ilike.%${query}%`)
      .eq('is_draft', false)
      .limit(10);
    return (data ?? []).map((p: any) => ({ id: p.id, name: p.name ?? p.description ?? 'Produto', slug: p.slug ?? '' }));
  }, []);

  const handleProductSearch = async (q: string) => {
    setProductSearch(q);
    if (!q.trim()) { setProductSuggestions([]); return; }
    const results = await handleSearchProducts(q);
    setProductSuggestions(results);
  };

  const handleDelete = async (post: ProductPost) => {
    if (!confirm('Excluir esta arte da Biblioteca? A ação não pode ser desfeita.')) return;
    setDeletingId(post.id);
    try {
      await productPostsService.deletePost(post);
      toast.success('Post removido da Biblioteca.');
      void loadPosts();
    } catch (err: any) {
      toast.error(err.message || 'Erro ao excluir o post.');
    } finally {
      setDeletingId(undefined);
    }
  };

  const handleDownload = (post: ProductPost) => {
    const link = document.createElement('a');
    link.href = post.imageUrl;
    link.download = `post-${post.format.toLowerCase()}-${post.id.slice(0, 8)}.webp`;
    link.target = '_blank';
    link.click();
  };

  const totalByFormat = {
    feed: posts.filter(p => p.format === 'FEED_4_5').length,
    story: posts.filter(p => p.format === 'STORY_STATUS_9_16').length,
  };

  return (
    <div className="space-y-5">
      {/* Filtros */}
      <div className="flex flex-wrap items-end gap-3 rounded-xl border border-slate-800 bg-slate-900/60 p-4">
        {/* Busca de produto */}
        <div className="min-w-[200px] flex-1">
          <label className="mb-1 block text-xs font-semibold text-slate-400">Produto</label>
          {filterProductId ? (
            <div className="flex items-center justify-between rounded-lg bg-slate-800 px-3 py-2 text-sm text-white">
              <span className="truncate">{filterProductName}</span>
              <button
                onClick={() => { setFilterProductId(''); setFilterProductName(''); }}
                className="ml-2 text-xs text-slate-400 hover:text-red-400"
              >
                ✕
              </button>
            </div>
          ) : (
            <div className="relative">
              <input
                value={productSearch}
                onChange={e => void handleProductSearch(e.target.value)}
                placeholder="Filtrar por produto..."
                className="w-full rounded-lg bg-slate-800 px-3 py-2 text-sm text-white placeholder-slate-500 outline-none ring-1 ring-slate-700 focus:ring-indigo-500"
              />
              {productSuggestions.length > 0 && (
                <ul className="absolute top-full z-10 mt-1 max-h-48 w-full overflow-y-auto rounded-lg border border-slate-700 bg-slate-800 shadow-xl">
                  {productSuggestions.map(p => (
                    <li key={p.id}>
                      <button
                        onClick={() => {
                          setFilterProductId(p.id);
                          setFilterProductName(p.name);
                          setProductSearch('');
                          setProductSuggestions([]);
                        }}
                        className="w-full px-3 py-2 text-left text-sm text-slate-200 hover:bg-slate-700"
                      >
                        {p.name}
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          )}
        </div>

        {/* Campanha */}
        <div className="min-w-[160px]">
          <label className="mb-1 block text-xs font-semibold text-slate-400">Campanha</label>
          <select
            value={filterCampaignId}
            onChange={e => setFilterCampaignId(e.target.value)}
            className="w-full rounded-lg bg-slate-800 px-3 py-2 text-sm text-white outline-none ring-1 ring-slate-700 focus:ring-indigo-500"
          >
            <option value="">Todas</option>
            {campaigns.filter(c => c.active).map(c => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>
        </div>

        {/* Formato */}
        <div className="min-w-[150px]">
          <label className="mb-1 block text-xs font-semibold text-slate-400">Formato</label>
          <select
            value={filterFormat}
            onChange={e => setFilterFormat(e.target.value as ProductPostFormat | '')}
            className="w-full rounded-lg bg-slate-800 px-3 py-2 text-sm text-white outline-none ring-1 ring-slate-700 focus:ring-indigo-500"
          >
            <option value="">Todos</option>
            <option value="FEED_4_5">Feed 4:5</option>
            <option value="STORY_STATUS_9_16">Story/Status 9:16</option>
          </select>
        </div>

        <button
          onClick={() => setUploadOpen(true)}
          className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-semibold text-white hover:bg-indigo-500"
        >
          + Adicionar post
        </button>
      </div>

      {/* Resumo */}
      {posts.length > 0 && (
        <div className="flex gap-3 text-xs text-slate-400">
          <span>{posts.length} {posts.length === 1 ? 'arte' : 'artes'} na biblioteca</span>
          {totalByFormat.feed > 0 && <span className="text-indigo-400">· {totalByFormat.feed} Feed 4:5</span>}
          {totalByFormat.story > 0 && <span className="text-purple-400">· {totalByFormat.story} Story/Status 9:16</span>}
        </div>
      )}

      {/* Grid */}
      {loading ? (
        <div className="flex items-center justify-center py-20 text-slate-500">
          <div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-400 border-t-transparent" />
          <span className="ml-3 text-sm">Carregando biblioteca…</span>
        </div>
      ) : posts.length === 0 ? (
        <div className="flex flex-col items-center justify-center gap-3 py-20 text-center text-slate-500">
          <span className="text-4xl">🖼️</span>
          <p className="text-sm">Nenhuma arte encontrada</p>
          <p className="text-xs text-slate-600">
            Crie a arte no ChatGPT ou Gemini e adicione aqui via <strong>+ Adicionar post</strong>.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5">
          {posts.map(post => (
            <PostCard
              key={post.id}
              post={post}
              productName={productNames[post.productId]}
              campaignName={post.campaignId ? campaignMap[post.campaignId] : undefined}
              onDelete={p => { if (!deletingId) void handleDelete(p); }}
              onDownload={handleDownload}
            />
          ))}
        </div>
      )}

      {uploadOpen && (
        <UploadPostModal
          campaigns={campaigns}
          preselectedProductId={filterProductId || undefined}
          preselectedProductName={filterProductName || undefined}
          onSearchProducts={handleSearchProducts}
          onClose={() => setUploadOpen(false)}
          onUploaded={loadPosts}
        />
      )}
    </div>
  );
}

import React, { useCallback, useRef, useState } from 'react';
import { toast } from 'react-toastify';
import { PostCampaign } from '../../types/postCreator';
import { ProductPostFormat, productPostFormatLabel } from '../../types/postSpecification';
import { productPostsService } from '../../services/productPostsService';

interface UploadPostModalProps {
  campaigns: PostCampaign[];
  /** Se fornecido, o produto já está selecionado e não pode ser alterado. */
  preselectedProductId?: string;
  preselectedProductName?: string;
  onClose: () => void;
  onUploaded: () => void;
  /** Necessário quando productId não está pré-selecionado — lista para busca */
  onSearchProducts?: (query: string) => Promise<Array<{ id: string; name: string; slug: string }>>;
}

type StepKey = 'product' | 'campaign' | 'format' | 'image' | 'confirm';

interface FormState {
  productId: string;
  productName: string;
  campaignId: string;
  format: ProductPostFormat | '';
  file: File | null;
  previewUrl: string;
  ratioMessage: string;
  ratioValid: boolean;
}

const INITIAL: FormState = {
  productId: '',
  productName: '',
  campaignId: '',
  format: '',
  file: null,
  previewUrl: '',
  ratioMessage: '',
  ratioValid: false,
};

export function UploadPostModal({
  campaigns,
  preselectedProductId,
  preselectedProductName,
  onClose,
  onUploaded,
  onSearchProducts,
}: UploadPostModalProps) {
  const [form, setForm] = useState<FormState>({
    ...INITIAL,
    productId: preselectedProductId ?? '',
    productName: preselectedProductName ?? '',
  });
  const [productQuery, setProductQuery] = useState('');
  const [productResults, setProductResults] = useState<Array<{ id: string; name: string; slug: string }>>([]);
  const [searching, setSearching] = useState(false);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const step: StepKey = (() => {
    if (!preselectedProductId && !form.productId) return 'product';
    if (!form.format) return 'format';
    if (!form.file) return 'image';
    return 'confirm';
  })();

  const handleSearchProduct = useCallback(async (q: string) => {
    setProductQuery(q);
    if (!q.trim() || !onSearchProducts) { setProductResults([]); return; }
    setSearching(true);
    try {
      const results = await onSearchProducts(q);
      setProductResults(results);
    } finally {
      setSearching(false);
    }
  }, [onSearchProducts]);

  const handleFileChange = async (file: File) => {
    const previewUrl = URL.createObjectURL(file);
    const validation = await productPostsService.validateImageRatio(file);

    const suggestedFormat = validation.format ?? form.format;

    setForm(prev => ({
      ...prev,
      file,
      previewUrl,
      ratioValid: validation.valid,
      ratioMessage: validation.message ?? '',
      format: suggestedFormat || prev.format,
    }));

    if (!validation.valid && validation.message) {
      toast.warn(validation.message);
    } else if (validation.format) {
      toast.info(`Formato detectado automaticamente: ${productPostFormatLabel[validation.format]}`);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file?.type.startsWith('image/')) void handleFileChange(file);
  };

  const handleUpload = async () => {
    if (!form.productId || !form.format || !form.file) return;
    setUploading(true);
    try {
      await productPostsService.uploadPost({
        productId: form.productId,
        file: form.file,
        format: form.format as ProductPostFormat,
        campaignId: form.campaignId || null,
      });
      toast.success('Post adicionado à Biblioteca!');
      onUploaded();
      onClose();
    } catch (err: any) {
      toast.error(err.message || 'Erro ao enviar o post.');
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 p-4 backdrop-blur-sm">
      <div className="w-full max-w-lg overflow-hidden rounded-2xl border border-slate-700 bg-slate-900 shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-800 px-5 py-4">
          <h2 className="font-bold text-white">Adicionar post à Biblioteca</h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white">✕</button>
        </div>

        <div className="space-y-5 p-5">
          {/* Produto */}
          {preselectedProductId ? (
            <div className="rounded-lg bg-slate-800/60 px-3 py-2">
              <span className="text-xs text-slate-400">Produto:</span>
              <p className="font-semibold text-white">{form.productName}</p>
            </div>
          ) : (
            <div>
              <label className="mb-1.5 block text-xs font-semibold text-slate-300">Produto *</label>
              {form.productId ? (
                <div className="flex items-center justify-between rounded-lg bg-slate-800 px-3 py-2">
                  <span className="text-sm text-white">{form.productName}</span>
                  <button onClick={() => setForm(prev => ({ ...prev, productId: '', productName: '' }))} className="text-xs text-slate-400 hover:text-red-400">Trocar</button>
                </div>
              ) : (
                <div className="relative">
                  <input
                    value={productQuery}
                    onChange={e => void handleSearchProduct(e.target.value)}
                    placeholder="Buscar produto..."
                    className="w-full rounded-lg bg-slate-800 px-3 py-2 text-sm text-white placeholder-slate-500 outline-none ring-1 ring-slate-700 focus:ring-indigo-500"
                  />
                  {productResults.length > 0 && (
                    <ul className="absolute top-full z-10 mt-1 max-h-48 w-full overflow-y-auto rounded-lg border border-slate-700 bg-slate-800 shadow-xl">
                      {productResults.map(p => (
                        <li key={p.id}>
                          <button
                            onClick={() => { setForm(prev => ({ ...prev, productId: p.id, productName: p.name })); setProductResults([]); }}
                            className="w-full px-3 py-2 text-left text-sm text-slate-200 hover:bg-slate-700"
                          >
                            {p.name}
                          </button>
                        </li>
                      ))}
                    </ul>
                  )}
                  {searching && <p className="mt-1 text-xs text-slate-500">Buscando…</p>}
                </div>
              )}
            </div>
          )}

          {/* Campanha (opcional) */}
          <div>
            <label className="mb-1.5 block text-xs font-semibold text-slate-300">
              Campanha <span className="text-slate-500">(opcional)</span>
            </label>
            <select
              value={form.campaignId}
              onChange={e => setForm(prev => ({ ...prev, campaignId: e.target.value }))}
              className="w-full rounded-lg bg-slate-800 px-3 py-2 text-sm text-white outline-none ring-1 ring-slate-700 focus:ring-indigo-500"
            >
              <option value="">— Sem campanha específica —</option>
              {campaigns.filter(c => c.active).map(c => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>

          {/* Formato */}
          <div>
            <label className="mb-1.5 block text-xs font-semibold text-slate-300">Formato *</label>
            <div className="flex gap-2">
              {(['FEED_4_5', 'STORY_STATUS_9_16'] as ProductPostFormat[]).map(fmt => (
                <button
                  key={fmt}
                  onClick={() => setForm(prev => ({ ...prev, format: fmt }))}
                  className={`flex-1 rounded-lg border py-2 text-xs font-semibold transition ${form.format === fmt ? 'border-indigo-500 bg-indigo-600/30 text-white' : 'border-slate-700 bg-slate-800 text-slate-400 hover:border-slate-500'}`}
                >
                  {productPostFormatLabel[fmt]}
                </button>
              ))}
            </div>
          </div>

          {/* Upload */}
          <div>
            <label className="mb-1.5 block text-xs font-semibold text-slate-300">Imagem *</label>
            <div
              onDrop={handleDrop}
              onDragOver={e => e.preventDefault()}
              onClick={() => fileInputRef.current?.click()}
              className="flex cursor-pointer flex-col items-center justify-center gap-2 rounded-xl border-2 border-dashed border-slate-700 bg-slate-800/40 p-6 text-center transition hover:border-indigo-500/60 hover:bg-slate-800"
            >
              {form.previewUrl ? (
                <img src={form.previewUrl} alt="preview" className="max-h-40 rounded-lg object-contain" />
              ) : (
                <>
                  <span className="text-3xl">🖼️</span>
                  <p className="text-xs text-slate-400">Clique ou arraste a imagem aqui</p>
                  <p className="text-[10px] text-slate-600">Feed 4:5 ou Story/Status 9:16 — proporção detectada automaticamente</p>
                </>
              )}
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={e => { const f = e.target.files?.[0]; if (f) void handleFileChange(f); }}
            />
            {form.ratioMessage && (
              <p className={`mt-1.5 text-[10px] ${form.ratioValid ? 'text-emerald-400' : 'text-amber-400'}`}>
                {form.ratioMessage}
              </p>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="flex justify-end gap-2 border-t border-slate-800 px-5 py-4">
          <button onClick={onClose} className="rounded-lg px-4 py-2 text-sm text-slate-400 hover:text-white">Cancelar</button>
          <button
            onClick={() => void handleUpload()}
            disabled={!form.productId || !form.format || !form.file || uploading}
            className="rounded-lg bg-indigo-600 px-5 py-2 text-sm font-semibold text-white hover:bg-indigo-500 disabled:cursor-not-allowed disabled:opacity-40"
          >
            {uploading ? 'Enviando…' : 'Adicionar à Biblioteca'}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { Product } from '@/pages/types/product.type';

type Props = { search: string; products: Product[]; selected: Product | null; loading: boolean; onSearch: (value: string) => void; onSelect: (id: string) => void };

export function PreviewProductPicker({ search, products, selected, loading, onSearch, onSelect }: Props) {
  const [open, setOpen] = useState(false); const container = useRef<HTMLDivElement>(null);
  useEffect(() => { const close = (event: MouseEvent) => { if (!container.current?.contains(event.target as Node)) setOpen(false); }; document.addEventListener('mousedown', close); return () => document.removeEventListener('mousedown', close); }, []);
  const clear = () => { onSearch(''); onSelect(''); setOpen(false); };
  const showSuggestions = open && !selected && search.trim().length >= 2;
  return <div ref={container} className="relative text-xs font-semibold">Produto para preview padrão<div className={`mt-1 flex items-center rounded border ${selected ? 'border-emerald-500/60 bg-emerald-500/10' : 'border-slate-700 bg-slate-950'}`}><i className={`bi ${selected ? 'bi-check-circle-fill text-emerald-400' : 'bi-search text-slate-500'} ml-2`} /><input value={selected ? (selected.name || selected.title || '') : search} onFocus={() => setOpen(true)} onChange={event => { onSearch(event.target.value); setOpen(true); }} placeholder="Buscar produto" className="min-w-0 flex-1 bg-transparent p-2 outline-none" />{selected && <button type="button" onClick={clear} aria-label="Limpar produto selecionado" className="px-2 text-slate-300 hover:text-white">✕</button>}</div>{selected && <p className="mt-1 text-[10px] text-emerald-300">Produto selecionado</p>}{showSuggestions && <div className="absolute z-40 mt-1 max-h-64 w-full overflow-auto rounded-lg border border-slate-700 bg-slate-950 p-1 shadow-xl">{products.map(product => <button key={product.id} type="button" onClick={() => { onSelect(product.id || ''); setOpen(false); }} className="block w-full rounded px-3 py-2 text-left text-xs hover:bg-slate-800">{product.name || product.title}</button>)}{loading && <p className="p-3 text-slate-400">Buscando produtos…</p>}{!loading && !products.length && <p className="p-3 text-slate-500">Nenhum produto encontrado.</p>}</div>}</div>;
}

import React, { useRef, useState } from 'react';
import FixedAspectImageCropper from './FixedAspectImageCropper';

type Props = {
  name: string;
  headerImage: string;
  footerImage: string;
  uploading: boolean;
  onNameChange: (name: string) => void;
  onImageChange: (kind: 'header' | 'footer', file: File) => void;
  onRemoveImage: (kind: 'header' | 'footer') => void;
  onClose: () => void;
};

export default function HeaderFooterModelEditor(props: Props) {
  const headerInput = useRef<HTMLInputElement>(null);
  const footerInput = useRef<HTMLInputElement>(null);
  const [cropRequest, setCropRequest] = useState<{ kind: 'header' | 'footer'; file: File } | null>(null);
  const imagePicker = (kind: 'header' | 'footer', image: string, input: React.RefObject<HTMLInputElement>, size: string) => (
    <div>
      <div className="mb-1 flex items-center justify-between text-xs font-bold text-slate-600 dark:text-slate-300"><span>{kind === 'header' ? 'Cabeçalho' : 'Rodapé'}</span><span className="text-[10px] text-slate-400">{size}</span></div>
      <button type="button" onClick={() => input.current?.click()} style={{ aspectRatio: '1080 / 170' }} className="relative flex w-full items-center justify-center overflow-hidden rounded-xl border-2 border-dashed border-slate-300 bg-slate-100 dark:border-slate-700 dark:bg-slate-800">
        {image ? <img src={image} alt={kind} className="h-full w-full object-contain" /> : <span className="text-xs font-bold text-slate-400"><i className="bi bi-image mr-1" />Adicionar imagem</span>}
        <span className="absolute inset-x-0 bottom-0 bg-black/60 py-1 text-[10px] font-bold text-white">Clique para alterar</span>
      </button>
      <input ref={input} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={event => { const file = event.target.files?.[0]; if (file) setCropRequest({ kind, file }); event.target.value = ''; }} />
      {image && <button type="button" onClick={() => props.onRemoveImage(kind)} className="mt-1 text-[10px] font-bold text-rose-600">Remover imagem</button>}
    </div>
  );
  return <><div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-4">
    <div className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900">
      <div className="flex items-center justify-between"><h4 className="text-sm font-black text-slate-800 dark:text-slate-100">Cabeçalho e rodapé</h4><button type="button" onClick={props.onClose}><i className="bi bi-x-lg" /></button></div>
      <label className="mt-4 block text-xs font-bold text-slate-600 dark:text-slate-300">Nome do modelo<input value={props.name} onChange={event => props.onNameChange(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-200 px-3 py-2 dark:border-slate-700 dark:bg-slate-800" /></label>
      <div className="mt-4 space-y-5">{imagePicker('header', props.headerImage, headerInput, '1080 × 170 px')}{imagePicker('footer', props.footerImage, footerInput, '1080 × 170 px')}</div>
      <button type="button" disabled={props.uploading} onClick={props.onClose} className="mt-5 rounded-lg bg-blue-600 px-4 py-2 text-xs font-black text-white disabled:opacity-50">{props.uploading ? 'Enviando...' : 'Concluir'}</button>
