import { useRef } from 'react';

type Props = {
  image: string;
  uploading: boolean;
  onImageChange: (file: File) => void;
  onRemoveImage: () => void;
  onClose: () => void;
};

const MAX_FILE_SIZE = 2 * 1024 * 1024;

export default function InstallmentImageEditor({ image, uploading, onImageChange, onRemoveImage, onClose }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const selectFile = (file?: File) => {
    if (!file) return;
    if (file.size > MAX_FILE_SIZE) return alert('A imagem do parcelamento deve ter no máximo 2 MB.');
    onImageChange(file);
  };

  return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-4">
    <div className="w-full max-w-xl rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900">
      <div className="flex items-center justify-between"><h4 className="text-sm font-black text-slate-800 dark:text-slate-100">Imagem do parcelamento</h4><button type="button" onClick={onClose}><i className="bi bi-x-lg" /></button></div>
      <p className="mt-2 text-xs text-slate-500 dark:text-slate-400">A proporção é livre. Use PNG, JPG ou WebP com até 2 MB.</p>
