import { useRef, useState } from 'react';
import FixedAspectImageCropper from './FixedAspectImageCropper';

type Props = {
  image: string;
  uploading: boolean;
  onImageChange: (file: File) => void;
  onRemoveImage: () => void;
  onClose: () => void;
};

const MAX_FILE_SIZE = 2 * 1024 * 1024;

export default function OpportunitySealImageEditor({ image, uploading, onImageChange, onRemoveImage, onClose }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [cropFile, setCropFile] = useState<File | null>(null);
  const selectFile = (file?: File) => {
    if (!file) return;
    if (file.size > MAX_FILE_SIZE) return alert('A imagem do selo deve ter no máximo 2 MB.');
    setCropFile(file);
  };

  return <><div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-4">
    <div className="w-full max-w-xl rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900">
      <div className="flex items-center justify-between"><h4 className="text-sm font-black text-slate-800 dark:text-slate-100">Imagem do selo</h4><button type="button" onClick={onClose}><i className="bi bi-x-lg" /></button></div>
      <p className="mt-2 text-xs text-slate-500 dark:text-slate-400">Proporção 8:2 (800 × 200 px). PNG, JPG ou WebP, com até 2 MB.</p>
      <button type="button" onClick={() => inputRef.current?.click()} style={{ aspectRatio: '800 / 200' }} className="relative mt-4 flex w-full items-center justify-center overflow-hidden rounded-xl border-2 border-dashed border-slate-300 bg-slate-100 dark:border-slate-700 dark:bg-slate-800">
        {image ? <img src={image} alt="Selo de oportunidade" className="h-full w-full object-contain" /> : <span className="text-xs font-bold text-slate-400"><i className="bi bi-image mr-1" />Adicionar imagem do selo</span>}
        <span className="absolute inset-x-0 bottom-0 bg-black/60 py-1 text-[10px] font-bold text-white">Clique para alterar e recortar</span>
      </button>
      <input ref={inputRef} hidden type="file" accept="image/png,image/jpeg,image/webp" onChange={event => { selectFile(event.target.files?.[0]); event.target.value = ''; }} />
      {image && <button type="button" onClick={onRemoveImage} className="mt-2 text-[10px] font-bold text-rose-600">Remover imagem</button>}
      <div className="mt-5 flex justify-end"><button type="button" disabled={uploading} onClick={onClose} className="rounded-lg bg-blue-600 px-4 py-2 text-xs font-black text-white disabled:opacity-50">{uploading ? 'Enviando...' : 'Concluir'}</button></div>
    </div>
  </div>{cropFile && <FixedAspectImageCropper file={cropFile} kind="seal" onCancel={() => setCropFile(null)} onConfirm={file => { onImageChange(file); setCropFile(null); }} />}</>;
}

export type TextBackground = {
  color: string;
  paddingLeft?: number;
  paddingRight?: number;
  paddingTop?: number;
  paddingBottom?: number;
  // Mantidos para carregar os templates salvos antes da separação por lado.
  paddingX?: number;
  paddingY?: number;
  opacity: number;
  borderColor?: string;
  borderWidth?: number;
};

type Props = {
  value: TextBackground;
  onChange: (value: TextBackground) => void;
  title?: string;
  hideSpacing?: boolean;
};

export default function TextBackgroundControls({ value, onChange, title = 'Fundo do texto', hideSpacing = false }: Props) {
  const update = <K extends keyof TextBackground>(key: K, next: TextBackground[K]) => onChange({ ...value, [key]: next });
  const horizontalSpacing = value.paddingX ?? value.paddingLeft ?? value.paddingRight ?? 0;
  const verticalSpacing = value.paddingY ?? value.paddingTop ?? value.paddingBottom ?? 0;
  const updateHorizontalSpacing = (next: number) => onChange({ ...value, paddingX: next, paddingLeft: next, paddingRight: next });
  const updateVerticalSpacing = (next: number) => onChange({ ...value, paddingY: next, paddingTop: next, paddingBottom: next });

  return <div className="flex flex-col gap-3 rounded-xl border border-slate-200 bg-white p-3 dark:border-slate-700 dark:bg-slate-800">
    <p className="text-[9px] font-black uppercase tracking-wider text-slate-400">{title}</p>
    <label className="flex items-center justify-between gap-2 text-[10px] font-black text-slate-500">Cor
      <input type="color" value={value.color} onChange={event => update('color', event.target.value)} className="h-8 w-12 cursor-pointer rounded-lg border border-slate-200 bg-white p-1 dark:border-slate-700 dark:bg-slate-900" />
    </label>
    <div className="grid grid-cols-2 gap-2">
      <label className="flex flex-col gap-1 text-[10px] font-black text-slate-500">Cor da borda<input type="color" value={value.borderColor || '#0f172a'} onChange={event => update('borderColor', event.target.value)} className="h-8 w-full cursor-pointer rounded-lg border border-slate-200 bg-white p-1 dark:border-slate-700 dark:bg-slate-900" /></label>
      <label className="flex flex-col gap-1 text-[10px] font-black text-slate-500">Borda (px)<input type="number" min="0" max="40" value={value.borderWidth || 0} onChange={event => update('borderWidth', Math.max(0, Math.min(40, Number(event.target.value) || 0)))} className="rounded-lg border border-slate-200 px-2 py-2 text-xs font-bold outline-none dark:border-slate-700 dark:bg-slate-900" /></label>
    </div>
    {!hideSpacing && <>
      <p className="text-[10px] font-black text-slate-500">Espaçamento</p>
      <div className="grid grid-cols-2 gap-2">
        <label className="flex flex-col gap-1 text-[10px] font-black text-slate-500">Horizontal
          <input type="number" min="0" max="200" value={horizontalSpacing} onChange={event => updateHorizontalSpacing(Math.max(0, Number(event.target.value) || 0))} className="rounded-lg border border-slate-200 px-2 py-2 text-xs font-bold outline-none dark:border-slate-700 dark:bg-slate-900" />
        </label>
        <label className="flex flex-col gap-1 text-[10px] font-black text-slate-500">Vertical
          <input type="number" min="0" max="200" value={verticalSpacing} onChange={event => updateVerticalSpacing(Math.max(0, Number(event.target.value) || 0))} className="rounded-lg border border-slate-200 px-2 py-2 text-xs font-bold outline-none dark:border-slate-700 dark:bg-slate-900" />
        </label>
      </div>
    </>}
    <label className="flex flex-col gap-1 text-[10px] font-black text-slate-500">Transparência: {Math.round((1 - value.opacity) * 100)}%
      <input type="range" min="0" max="100" value={Math.round(value.opacity * 100)} onChange={event => update('opacity', Number(event.target.value) / 100)} className="accent-pink-600" />
    </label>
  </div>;
}

import { useRef, useState } from 'react';

type Props = {
  color: string;
  label: string;
  onChange: (color: string) => void;
  onCommit: (color: string) => void;
  recentColors: string[];
};

export default function TextColorPicker({ color, label, onChange, onCommit, recentColors }: Props) {
  const [isOpen, setIsOpen] = useState(false);
  const [openedColor, setOpenedColor] = useState(color);
  const [pendingColor, setPendingColor] = useState(color);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const [popupPosition, setPopupPosition] = useState({ left: 12, top: 12 });
  const selectColor = (nextColor: string) => {
    onChange(nextColor);
    setPendingColor(nextColor);
  };
  const openPicker = () => {
    const rect = triggerRef.current?.getBoundingClientRect();
    const popupWidth = 384;
    const left = rect && rect.right + popupWidth + 12 <= window.innerWidth ? rect.right + 12 : Math.max(12, (rect?.left || 12) - popupWidth - 12);
    const top = Math.max(12, Math.min(rect?.top || 12, window.innerHeight - 430));
    setPopupPosition({ left, top });
    setOpenedColor(color);
    setPendingColor(color);
    setIsOpen(true);
  };
  const closePicker = () => { if (pendingColor !== openedColor) onCommit(pendingColor); setIsOpen(false); };

  return <div className="relative flex items-center gap-2">
    <span className="text-xs font-bold text-slate-600 dark:text-slate-200">Cor</span>
    <button ref={triggerRef} type="button" onClick={openPicker} className="flex h-8 w-8 items-center justify-center overflow-hidden rounded-xl border border-slate-300 bg-white p-0.5 shadow-xs transition-all active:scale-95 dark:border-slate-700 dark:bg-slate-900" title="Alterar cor">
      <span className="h-full w-full rounded-lg border border-white/60" style={{ backgroundColor: color }} />
    </button>
    <output className="w-18 font-mono text-[10px] font-bold uppercase text-slate-400">{color}</output>

    {isOpen && <>
      <div style={{ left: popupPosition.left, top: popupPosition.top }} className="fixed z-[10000] w-[calc(100%-2rem)] max-w-md rounded-3xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-800 dark:bg-slate-900">
        <div className="mb-4 flex items-center justify-between border-b border-slate-100 pb-3 dark:border-slate-800">
          <div className="flex items-center gap-2.5">
            <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-100 text-blue-600 dark:bg-blue-950/40 dark:text-blue-400"><i className="bi bi-palette-fill" /></span>
            <div><h3 className="text-sm font-black uppercase tracking-tight text-slate-800 dark:text-white">Cor do texto</h3><p className="text-[10px] font-bold text-slate-400">{label}</p></div>
          </div>
          <button type="button" onClick={closePicker} className="flex h-8 w-8 items-center justify-center rounded-xl text-slate-400 hover:bg-slate-100 hover:text-slate-700 dark:hover:bg-slate-800" aria-label="Fechar"><i className="bi bi-x-lg" /></button>
        </div>
        <div className="mb-4 flex items-center gap-3">
          <label className="relative flex h-11 w-11 cursor-pointer items-center justify-center overflow-hidden rounded-xl border border-slate-300 bg-gradient-to-r from-red-500 via-green-500 to-blue-500 p-0.5 shadow-md transition-all hover:scale-105 active:scale-95 dark:border-slate-700">
            <input type="color" value={color} onChange={event => selectColor(event.target.value)} className="absolute inset-0 h-full w-full cursor-pointer opacity-0" />
            <span className="h-full w-full rounded-lg border border-white/60" style={{ backgroundColor: color }} />
          </label>
          <div><p className="text-[9px] font-bold uppercase text-slate-400">Cor da fonte</p><output className="font-mono text-sm font-black uppercase text-slate-800 dark:text-slate-200">{color}</output></div>
        </div>
        <div className="border-t border-slate-200 pt-3 dark:border-slate-800"><p className="mb-2 text-[9px] font-bold uppercase tracking-wider text-slate-400">Cores recentes</p><div className="flex flex-wrap gap-1.5">{recentColors.map(recentColor => <button key={recentColor} type="button" onClick={() => selectColor(recentColor)} className={`h-7 w-7 rounded-lg border shadow-2xs transition-all hover:scale-110 active:scale-95 ${recentColor.toLowerCase() === color.toLowerCase() ? 'border-blue-500 ring-2 ring-blue-500/20' : 'border-slate-300/40 dark:border-slate-700/60'}`} style={{ backgroundColor: recentColor }} title={recentColor} />)}</div></div>
      </div>
    </>}
  </div>;
}

