                </div>

                <div className="flex flex-col gap-2">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">
                        {isEnv ? 'Vincular Categorias' : 'Vincular a Ambientes'}
                    </label>
                    <div className="border border-slate-100 dark:border-slate-800 rounded-xl bg-slate-50/50 dark:bg-slate-950/20 max-h-48 overflow-y-auto p-3 grid grid-cols-2 gap-2 custom-scrollbar">
                        {isEnv ? (
                            categories.map(cat => {
                                const isChecked = selectedLinks.includes(cat.id);
                                return (
                                    <label
                                        key={cat.id}
                                        className="flex items-center gap-2.5 p-1 rounded hover:bg-white dark:hover:bg-slate-900 transition-colors cursor-pointer select-none"
                                    >
                                        <input
                                            type="checkbox"
                                            checked={isChecked}
                                            onChange={() => onToggleLink(cat.id)}
                                            className="h-4 w-4 rounded border-slate-350 text-blue-600 focus:ring-blue-500"
                                            disabled={isSubmitting}
                                        />
                                        <span className="text-xs text-slate-700 dark:text-slate-300 font-medium truncate">
                                            {cat.name}
                                        </span>
                                    </label>
                                );
                            })
                        ) : (
                            environments.map(env => {
                                const isChecked = selectedLinks.includes(env.id);
                                return (
                                    <label
                                        key={env.id}
                                        className="flex items-center gap-2.5 p-1 rounded hover:bg-white dark:hover:bg-slate-900 transition-colors cursor-pointer select-none"
                                    >
                                        <input
                                            type="checkbox"
                                            checked={isChecked}
                                            onChange={() => onToggleLink(env.id)}
                                            className="h-4 w-4 rounded border-slate-350 text-blue-600 focus:ring-blue-500"
                                            disabled={isSubmitting}
                                        />
                                        <span className="text-xs text-slate-700 dark:text-slate-300 font-medium truncate">
                                            {env.name}
                                        </span>
                                    </label>
                                );
                            })
                        )}
                    </div>
                </div>

                {!isEnv && setSelectedAttributes && (
                    <div className="flex flex-col gap-2 pt-2">
                        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest">
                            Características da Categoria
                        </label>
                        <p className="text-xs text-slate-500 dark:text-slate-400">
                            Selecione as características aplicáveis aos produtos desta categoria.
                        </p>
                        {isLoadingAttributes && (
                            <p className="flex items-center gap-2 text-xs text-slate-500" role="status">
                                <i className="bi bi-arrow-repeat animate-spin" /> Carregando características...
                            </p>
                        )}
                        {attributeLoadFailed && (
                            <p className="text-xs font-semibold text-red-600 dark:text-red-400" role="alert">
                                Não foi possível carregar a configuração atual. Feche o modal e tente novamente.
                            </p>
                        )}
                        <AttributeAutocomplete
                            selectedIds={selectedAttributes.map(a => a.id)}
                            onSelect={(attr) => {
                                setSelectedAttributes(prev => {
                                    const exists = prev.some(a => a.id === attr.id);
                                    if (exists) {
                                        return prev.filter(a => a.id !== attr.id);
                                    }
                                    return [...prev, attr];
                                });
                            }}
                            placeholder="Buscar característica (mínimo 2 letras)..."
                            disabled={isSubmitting || isLoadingAttributes || attributeLoadFailed}
                        />
                        {selectedAttributes.length > 0 && (
                            <div className="flex flex-wrap gap-2 mt-1 max-h-36 overflow-y-auto custom-scrollbar p-1">
                                {selectedAttributes.map(attr => (
                                    <div
                                        key={attr.id}
                                        className="flex items-center gap-1.5 px-3 py-1 bg-blue-50 dark:bg-blue-500/10 text-blue-700 dark:text-blue-400 rounded-full border border-blue-200 dark:border-blue-500/20 text-xs font-bold shadow-2xs"
                                    >
                                        <span>{attr.name}</span>
                                        <button
                                            type="button"
                                            onClick={() => setSelectedAttributes(prev => prev.filter(a => a.id !== attr.id))}
                                            className="hover:text-blue-900 dark:hover:text-blue-200 transition-colors bg-transparent border-0 flex items-center justify-center rounded-full outline-none"
                                            disabled={isSubmitting}
                                            aria-label={`Remover especificação ${attr.name}`}
                                        >
                                            <i className="bi bi-x-lg text-[10px]" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}
                </div>

                <div className="flex shrink-0 items-center justify-between border-t border-slate-100 dark:border-slate-800 bg-white px-6 py-4 dark:bg-slate-900">
                    <div>
                        {editingNode && onDelete && (
                            (() => {
                                if (isEnv) {
                                    const env = environments.find(e => e.id === editingNode.id);
                                    const count = env?.categories?.length || 0;
                                    const isDisabled = count > 0;
                                    const reason = `Não é possível excluir este ambiente porque ele possui ${count} categoria${count > 1 ? 's vinculadas' : ' vinculada'}. Desvincule todas as categorias deste ambiente antes de excluí-lo.`;
                                    return (
                                        <SecureDeleteButton
                                            disabled={isDisabled}
                                            disabledReason={reason}
                                            onDelete={() => {
                                                onClose();
                                                onDelete(editingNode.id, true);
                                            }}
                                            ariaLabel={`Excluir ambiente ${nameInput}`}
                                            title="Excluir ambiente"
                                        />
                                    );
                                } else {
                                    const cat = categories.find(c => c.id === editingNode.id);
                                    const count = cat?.productCount || 0;
                                    const isDisabled = count > 0;
                                    const reason = `Não é possível excluir esta categoria porque ela está sendo utilizada por ${count} produto${count > 1 ? 's' : ''}. Remova ou altere a categoria desses produtos antes de excluí-la.`;
                                    return (
                                        <SecureDeleteButton
                                            disabled={isDisabled}
                                            disabledReason={reason}
                                            onDelete={() => {
                                                onClose();
                                                onDelete(editingNode.id, false);
                                            }}
                                            ariaLabel={`Excluir categoria ${nameInput}`}
                                            title="Excluir categoria"
                                        />
                                    );
                                }
                            })()
                        )}
                    </div>
                    <div className="flex gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            disabled={isSubmitting || isLoadingAttributes || attributeLoadFailed}
                            className="px-4 py-2 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-200 transition-colors disabled:opacity-50"
                        >
                            Cancelar
                        </button>
                        <button
                            type="submit"
                            disabled={isSubmitting}
                            className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg flex items-center gap-2 transition-all disabled:opacity-60"
                        >
                            {isSubmitting && (
                                <div className="w-3.5 h-3.5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                            )}
                            <span>{isSubmitting ? 'Salvando...' : 'Salvar'}</span>
                        </button>
                    </div>
                </div>
            </form>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { supabase } from '@/pages/utils/supabaseConfig';
import Product, { ComboItem, Variation } from '../../../types/product.type';
import { toast } from 'react-toastify';
import DropdownPortal from '@/components/shared/DropdownPortal';
import { useRef } from 'react';
import { getSelectedProductDisplayName } from '../../../utils/productVariationDefaults';

interface ProductSearchResult {
    id: string;
    description?: string;
    unitPrice?: number;
    stock?: number;
    hasVariations?: boolean;
    variations?: Variation[];
}

interface ComboItemSelectorProps {
    readonly currentItems: readonly ComboItem[];
    readonly onAdd: (item: ComboItem) => void;
    readonly onRemove: (index: number) => void;
    readonly onUpdateQuantity: (index: number, quantity: number) => void;
}

export const ComboItemSelector: React.FC<ComboItemSelectorProps> = ({ currentItems, onAdd, onRemove, onUpdateQuantity }) => {
    const [search, setSearch] = useState('');
    const [results, setResults] = useState<ProductSearchResult[]>([]);
    const [loading, setLoading] = useState(false);
    const inputContainerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (search.length < 2) {
            setResults([]);
            return;
        }

        const delayDebounceFn = setTimeout(async () => {
            setLoading(true);
            try {
                const { data, error } = await supabase
                    .from('products')
                    .select('id, description, unitPrice, stock, hasVariations, variations')
                    .ilike('description', `%${search}%`)
                    .eq('is_combo', false) // Evitar combos recursivos
                    .limit(5);

                if (error) throw error;
                setResults((data as ProductSearchResult[]) || []);
            } catch (error: unknown) {
                console.error('[ComboItemSelector] Erro ao buscar produtos:', error);
            } finally {
                setLoading(false);
            }
        }, 300);

        return () => clearTimeout(delayDebounceFn);
    }, [search]);

    const handleAddItem = (prod: ProductSearchResult, variation?: Variation) => {
        const item: ComboItem = {
            productId: prod.id,
            variationId: variation?.id,
            description: getSelectedProductDisplayName(prod as unknown as Partial<Product>, variation),
            unitPrice: Number(variation ? variation.unitPrice : prod.unitPrice) || 0,
            stock: Number(variation ? variation.stock : prod.stock) || 0,
            quantity: 1
        };

        // Verificar se já existe
        const exists = currentItems.some((i) => i.productId === item.productId && i.variationId === item.variationId);
        if (exists) {
            toast.warning('Este item já foi adicionado ao combo.');
            return;
        }

        onAdd(item);
        setSearch('');
        setResults([]);
    };

    return (
        <div className="flex flex-col gap-4">
            {/* Search Input */}
            <div className="relative">
                <div className="relative" ref={inputContainerRef}>
                    <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-purple-400" aria-hidden="true" />
                    <input
                        type="text"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        placeholder="Buscar produto para adicionar ao combo..."
                        className="w-full pl-12 pr-4 py-3 bg-white dark:bg-slate-900 border border-purple-100 dark:border-purple-900/30 rounded-2xl outline-none text-sm focus:ring-2 focus:ring-purple-500 transition-all"
                    />
                    {loading && <div className="absolute right-4 top-1/2 -translate-y-1/2 w-4 h-4 border-2 border-purple-500 border-t-transparent rounded-full animate-spin" />}
                </div>

                <DropdownPortal anchorRef={inputContainerRef} isOpen={results.length > 0}>
                    <div className="mt-2 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 shadow-xl rounded-2xl overflow-hidden animate-in fade-in slide-in-from-top-2">
                        {results.map((prod) => (
                            <div key={prod.id}>
                                {prod.hasVariations && prod.variations && prod.variations.length > 0 ? (
                                    prod.variations.map((v: Variation) => (
                                        <button
                                            key={v.id}
                                            type="button"
                                            onClick={() => handleAddItem(prod, v)}
                                            className="w-full px-4 py-3 flex items-center justify-between hover:bg-purple-50 dark:hover:bg-purple-900/10 transition-colors border-b border-slate-50 dark:border-slate-800 last:border-0 cursor-pointer"
                                        >
                                            <div className="text-left">
                                                <p className="text-xs font-bold text-slate-700 dark:text-slate-200">{prod.description}</p>
                                                <p className="text-[10px] text-purple-600 font-black uppercase tracking-widest">{v.name}</p>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-xs font-black text-slate-800 dark:text-slate-100">R$ {Number(v.unitPrice || 0).toFixed(2)}</p>
                                                <p className="text-[10px] text-slate-400 font-bold uppercase">{Number(v.stock || 0)} em estoque</p>
                                            </div>
                                        </button>
                                    ))
                                ) : (
                                    <button
                                        type="button"
                                        onClick={() => handleAddItem(prod)}
                                        className="w-full px-4 py-3 flex items-center justify-between hover:bg-purple-50 dark:hover:bg-purple-900/10 transition-colors border-b border-slate-50 dark:border-slate-800 last:border-0 cursor-pointer"
                                    >
                                        <div className="text-left">
                                            <p className="text-xs font-bold text-slate-700 dark:text-slate-200">{prod.description}</p>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-xs font-black text-slate-800 dark:text-slate-100">R$ {Number(prod.unitPrice || 0).toFixed(2)}</p>
                                            <p className="text-[10px] text-slate-400 font-bold uppercase">{Number(prod.stock || 0)} em estoque</p>
                                        </div>
                                    </button>
                                )}
                            </div>
                        ))}
                    </div>
                </DropdownPortal>
            </div>

            {/* Selected Items List */}
            <div className="flex flex-col gap-2">
                {currentItems.map((item, idx) => (
                    <div key={`${item.productId}-${item.variationId}-${idx}`} className="flex items-center gap-4 bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-100 dark:border-slate-800 group transition-all hover:shadow-md">
                        <div className="flex-1">
                            <p className="text-xs font-black text-slate-800 dark:text-slate-200">{item.description}</p>
                            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">
                                Unit: R$ {item.unitPrice.toFixed(2)} | Est: {item.stock}
                            </p>
                        </div>

                        <div className="flex items-center gap-3">
                            <div className="flex items-center bg-slate-50 dark:bg-slate-950 rounded-xl border border-slate-100 dark:border-slate-800 p-1">
                                <button
                                    type="button"
                                    onClick={() => onUpdateQuantity(idx, Math.max(1, item.quantity - 1))}
                                    className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-purple-600 transition-colors"
                                >
                                    <i className="bi bi-dash"></i>
                                </button>
                                <span className="w-8 text-center text-xs font-black text-slate-700 dark:text-slate-200">{item.quantity}</span>
                                <button
                                    type="button"
                                    onClick={() => onUpdateQuantity(idx, item.quantity + 1)}
                                    className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-purple-600 transition-colors"
                                >
                                    <i className="bi bi-plus"></i>
                                </button>
                            </div>

                            <button
                                type="button"
                                onClick={() => onRemove(idx)}
                                className="w-8 h-8 flex items-center justify-center text-slate-300 hover:text-red-500 transition-colors"
                            >
                                <i className="bi bi-trash-fill"></i>
                            </button>
                        </div>
                    </div>
                ))}

                {currentItems.length === 0 && (
                    <div className="text-center py-8 opacity-40">
                        <i className="bi bi-inbox text-4xl mb-2 block"></i>
                        <p className="text-[10px] font-black uppercase tracking-widest">Nenhum item adicionado ainda</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default ComboItemSelector;

import React, { useState, useEffect } from 'react';
import { InitialStockEntry } from '../../../types/product.type';
import CurrencyInput from '@/components/CurrencyInput';

interface InitialStockListProps {
    readonly entries?: readonly InitialStockEntry[];
    readonly onChange: (entries: InitialStockEntry[]) => void;
}

const DEFAULT_ENTRY: InitialStockEntry = {
    quantity: 0,
    unitCost: 0,
    ipiPercent: 0,
    ipiType: 'percentage',
    freightCost: 0,
    freightType: 'fixed',
    finalUnitCost: 0,
};

const calcFinal = (e: InitialStockEntry): number => {
    const base = Number(e.unitCost) || 0;
    const ipiVal = Number(e.ipiPercent) || 0;
    const freightVal = Number(e.freightCost) || 0;
    const ipi = e.ipiType === 'percentage'
        ? base * (ipiVal / 100)
        : ipiVal;
    const freight = e.freightType === 'percentage'
        ? base * (freightVal / 100)
        : freightVal;
    const total = base + ipi + freight;
    return Number.isNaN(total) ? 0 : Math.max(0, total);
};

export const InitialStockList: React.FC<InitialStockListProps> = ({ entries, onChange }) => {
    const [entry, setEntry] = useState<InitialStockEntry>(entries?.[0] || DEFAULT_ENTRY);

    // Sync from parent only on mount or when entries are reset externally (e.g. clear form)
    useEffect(() => {
        if (entries && entries.length > 0) {
            setEntry(entries[0]);
        } else {
            setEntry(DEFAULT_ENTRY);
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Only on mount - prevents the infinite loop

    const update = <K extends keyof InitialStockEntry>(field: K, value: InitialStockEntry[K]) => {
        const next = { ...entry, [field]: value };
        next.finalUnitCost = calcFinal(next);
        setEntry(next);
        onChange([next]);
    };

    return (
        <div className="flex flex-col gap-4">
            {/* Quantidade */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="flex flex-col gap-1.5">
                    <label htmlFor="initial-stock-qty" className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1">
                        Quantidade Inicial <span className="text-red-500">*</span>
                    </label>
                    <input
                        id="initial-stock-qty"
                        type="number"
                        min={0}
                        value={entry.quantity || ''}
                        onChange={(e) => update('quantity', Math.max(0, parseInt(e.target.value, 10) || 0))}
                        className="w-full px-4 py-3 bg-white dark:bg-slate-900 border-2 border-blue-200 dark:border-blue-900/40 focus:border-blue-500 rounded-xl outline-none text-sm font-black text-blue-600 dark:text-blue-400 transition-colors"
                        placeholder="0"
                    />
                </div>

                {/* Custo Unitário */}
                <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 px-1">
                        Custo Unitário (R$)
                    </label>
                    <CurrencyInput
                        value={entry.unitCost}
                        onChange={(val) => update('unitCost', val)}
                        className="w-full text-left px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 focus:border-blue-500 rounded-xl outline-none text-sm font-bold dark:text-slate-200 transition-colors"
                        placeholder="0,00"
                    />
                </div>
            </div>

            {/* IPI */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="flex flex-col gap-1.5">
                    <div className="flex items-center justify-between px-1">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">IPI</label>
                        <div className="flex gap-1">
                            <button
                                type="button"
                                onClick={() => update('ipiType', 'percentage')}
                                className={`text-[8px] px-2 py-0.5 rounded-md font-black transition-all ${entry.ipiType !== 'fixed' ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                            >%</button>
                            <button
                                type="button"
                                onClick={() => update('ipiType', 'fixed')}
                                className={`text-[8px] px-2 py-0.5 rounded-md font-black transition-all ${entry.ipiType === 'fixed' ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                            >R$</button>
                        </div>
                    </div>
                    {entry.ipiType === 'fixed' ? (
                        <CurrencyInput
                            value={entry.ipiPercent}
                            onChange={(val) => update('ipiPercent', val)}
                            className="w-full text-left px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 focus:border-blue-500 rounded-xl outline-none text-sm font-bold dark:text-slate-200 transition-colors"
                            placeholder="0,00"
                        />
                    ) : (
                        <div className="relative">
                            <input
                                type="number"
                                step="0.01"
                                min={0}
                                value={entry.ipiPercent || ''}
                                onChange={(e) => update('ipiPercent', parseFloat(e.target.value) || 0)}
                                className="w-full px-4 py-3 pr-10 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 focus:border-blue-500 rounded-xl outline-none text-sm font-bold dark:text-slate-200 transition-colors"
                                placeholder="0,00"
                            />
                            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-black text-slate-400 pointer-events-none">%</span>
                        </div>
                    )}
                </div>

                {/* Frete */}
                <div className="flex flex-col gap-1.5">
                    <div className="flex items-center justify-between px-1">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Frete</label>
                        <div className="flex gap-1">
                            <button
                                type="button"
                                onClick={() => update('freightType', 'percentage')}
                                className={`text-[8px] px-2 py-0.5 rounded-md font-black transition-all ${entry.freightType === 'percentage' ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                            >%</button>
                            <button
                                type="button"
                                onClick={() => update('freightType', 'fixed')}
                                className={`text-[8px] px-2 py-0.5 rounded-md font-black transition-all ${entry.freightType !== 'percentage' ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                            >R$</button>
                        </div>
                    </div>
                    {entry.freightType === 'percentage' ? (
                        <div className="relative">
                            <input
                                type="number"
                                step="0.01"
                                min={0}
                                value={entry.freightCost || ''}
                                onChange={(e) => update('freightCost', parseFloat(e.target.value) || 0)}
                                className="w-full px-4 py-3 pr-10 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 focus:border-blue-500 rounded-xl outline-none text-sm font-bold dark:text-slate-200 transition-colors"
                                placeholder="0,00"
                            />
                            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs font-black text-slate-400 pointer-events-none">%</span>
                        </div>
                    ) : (
                        <CurrencyInput
                            value={entry.freightCost}
                            onChange={(val) => update('freightCost', val)}
                            className="w-full text-left px-4 py-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 focus:border-blue-500 rounded-xl outline-none text-sm font-bold dark:text-slate-200 transition-colors"
                            placeholder="0,00"
                        />
                    )}
                </div>
            </div>

            {/* Custo Final Calculado */}
            <div className="flex items-center justify-between p-4 bg-blue-600 rounded-2xl shadow-lg shadow-blue-500/20">
                <div>
                    <p className="text-[9px] font-black uppercase tracking-widest text-blue-200">Custo Final Unitário (calculado)</p>
                    <p className="text-[9px] text-blue-200/70 mt-0.5">Custo + IPI + Frete</p>
                </div>
                <p className="text-xl font-black text-white">
                    R$ {(entry.finalUnitCost || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </p>
            </div>
        </div>
    );
};

export default InitialStockList;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import VariationType from '../../../../types/variation.type';
import { subscribeToVariations } from '../../../../utils/variationService';
import { normalizeSearchTerm } from '../../../../utils/textUtils';

export interface AttributeSelectionModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly onSelect: (attribute: { name: string; value: string }) => void;
    readonly onManageAttributes: () => void;
}

/**
 * Modal de seleção guiada de atributos (ex: Cor, Tamanho, Voltagem) e seus respectivos valores para o produto.
 */
export const AttributeSelectionModal: React.FC<AttributeSelectionModalProps> = ({
    isOpen,
    onClose,
    onSelect,
    onManageAttributes,
}) => {
    const [availableVariations, setAvailableVariations] = useState<VariationType[]>([]);
    const [selectedAttribute, setSelectedAttribute] = useState<VariationType | null>(null);
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        if (!isOpen) return;

        const unsubscribe = subscribeToVariations((data) => {
            setAvailableVariations(data.filter((v) => v.active && !v.deleted));
        });

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                if (selectedAttribute) {
                    setSelectedAttribute(null);
                } else {
                    onClose();
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => {
            unsubscribe();
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [isOpen, onClose, selectedAttribute]);

    if (!isOpen) return null;

    const normSearch = normalizeSearchTerm(searchTerm);
    const filteredAttributes = availableVariations.filter((v) =>
        normalizeSearchTerm(v.name).includes(normSearch)
    );

    return createPortal(
        <div
            className="fixed inset-0 z-[10001] flex items-center justify-center p-4"
            role="dialog"
            aria-modal="true"
            aria-labelledby="attribute-selection-modal-title"
        >
            <button
                type="button"
                className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm cursor-default"
                onClick={onClose}
                aria-label="Fechar modal"
            />
            <div className="relative bg-white dark:bg-slate-900 w-full max-w-lg rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-100 dark:border-slate-800">
                {/* Header */}
                <div className="px-8 py-6 border-b border-slate-50 dark:border-slate-800 flex items-center justify-between shrink-0">
                    <div>
                        <h3 id="attribute-selection-modal-title" className="text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight flex items-center gap-3">
                            <i className="bi bi-plus-circle-fill text-blue-600" aria-hidden="true" />
                            Adicionar Atributo
                        </h3>
                        <p className="text-[10px] uppercase font-black text-slate-400 tracking-widest mt-1">
                            Selecione um atributo e seu valor
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-2 text-slate-400 hover:text-red-500 transition-colors bg-slate-50 dark:bg-slate-800 rounded-xl cursor-pointer"
                        aria-label="Fechar modal"
                    >
                        <i className="bi bi-x-lg" aria-hidden="true" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-8 custom-scrollbar min-h-[400px]">
                    {!selectedAttribute ? (
                        <div className="space-y-6">
                            <div className="relative group">
                                <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                                <input
                                    type="text"
                                    placeholder="Buscar atributo (Cor, Tamanho...)"
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-800 rounded-[1.2rem] text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all font-bold dark:text-slate-300"
                                />
                            </div>

                            <div className="grid grid-cols-1 gap-2">
                                {filteredAttributes.map((attr) => (
                                    <button
                                        type="button"
                                        key={attr.id}
                                        onClick={() => setSelectedAttribute(attr)}
                                        className="flex items-center justify-between p-4 bg-white dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-blue-500 hover:bg-blue-50/30 dark:hover:bg-blue-900/10 transition-all group text-left"
                                    >
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-xl bg-slate-50 dark:bg-slate-900 flex items-center justify-center text-slate-400 group-hover:text-blue-600 transition-colors">
                                                <i className="bi bi-tag text-lg" aria-hidden="true" />
                                            </div>
                                            <span className="font-bold text-slate-700 dark:text-slate-200">
                                                {attr.name}
                                            </span>
                                        </div>
                                        <i className="bi bi-chevron-right text-slate-300 group-hover:text-blue-500 transition-all" aria-hidden="true" />
                                    </button>
                                ))}
                                {filteredAttributes.length === 0 && (
                                    <div className="text-center py-10 opacity-40">
                                        <i className="bi bi-search text-3xl mb-2 block" aria-hidden="true" />
                                        <p className="text-xs font-bold uppercase tracking-widest">
                                            Nenhum atributo encontrado
                                        </p>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                            <button
                                type="button"
                                onClick={() => setSelectedAttribute(null)}
                                className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:text-blue-700 transition-colors mb-2"
                            >
                                <i className="bi bi-arrow-left" aria-hidden="true" /> Voltar para Atributos
                            </button>

                            <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-2xl border border-blue-100 dark:border-blue-800 mb-6">
                                <p className="text-[10px] font-black uppercase tracking-widest text-blue-500 mb-1">
                                    Selecionado:
                                </p>
                                <p className="text-lg font-black text-slate-800 dark:text-slate-100">
                                    {selectedAttribute.name}
                                </p>
                            </div>

                            <div className="space-y-3">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                    Escolha o Valor:
                                </label>
                                <div className="grid grid-cols-2 gap-3">
                                    {selectedAttribute.options.map((opt) => (
                                        <button
                                            type="button"
                                            key={opt.id}
                                            onClick={() => {
                                                onSelect({ name: selectedAttribute.name, value: opt.value });
                                                onClose();
                                            }}
                                            className="p-4 bg-white dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-blue-500 hover:bg-blue-600 hover:text-white transition-all font-bold text-sm text-slate-700 dark:text-slate-200 shadow-sm active:scale-95 text-center"
                                        >
                                            {opt.value}
                                        </button>
                                    ))}
                                    {selectedAttribute.options.length === 0 && (
                                        <div className="col-span-2 text-center py-8 opacity-40">
                                            <p className="text-xs font-bold">
                                                Sem valores cadastrados para este atributo
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="p-8 border-t border-slate-50 dark:border-slate-800 flex flex-col gap-4 shrink-0 bg-white dark:bg-slate-900">
                    <button
                        type="button"
                        onClick={onManageAttributes}
                        className="w-full py-4 bg-slate-900 text-white dark:bg-slate-100 dark:text-slate-900 rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-xl transition-all active:scale-95 flex items-center justify-center gap-2"
                    >
                        <i className="bi bi-gear-fill" aria-hidden="true" />
                        Gerenciar Atributos e Valores
                    </button>
                    <button
                        type="button"
                        onClick={onClose}
                        className="w-full py-3 text-slate-400 rounded-2xl font-black uppercase tracking-widest text-[9px] hover:bg-slate-50 dark:hover:bg-slate-800 transition-all"
                    >
                        Cancelar
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
};

export default AttributeSelectionModal;

import React, { useState, useMemo, useEffect } from "react";
import { normalizeSearchTerm } from "@/pages/utils/textUtils";

export interface CategoryItem {
    readonly id: string;
    readonly name: string;
    readonly parents?: readonly string[];
}

export interface CategorySearchModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly categories: readonly CategoryItem[];
    readonly onSelect: (categoryId: string) => void;
    readonly selectedIds: readonly string[];
}

export const CategorySearchModal: React.FC<CategorySearchModalProps> = ({
    isOpen,
    onClose,
    categories,
    onSelect,
    selectedIds
}) => {
    const [search, setSearch] = useState("");

    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === "Escape") {
                onClose();
            }
        };
        window.addEventListener("keydown", handleKeyDown);
        return () => window.removeEventListener("keydown", handleKeyDown);
    }, [isOpen, onClose]);

    const filtered = useMemo(() => {
        const s = normalizeSearchTerm(search);
        return (categories || [])
            .filter(c => normalizeSearchTerm(c.name).includes(s))
            .sort((a, b) => a.name.localeCompare(b.name))
            .slice(0, 30);
    }, [categories, search]);

    if (!isOpen) return null;

    return (
        <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="category-search-modal-title"
            className="fixed inset-0 z-[1000020] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm"
            onClick={onClose}
        >
            <div
                className="bg-white dark:bg-slate-900 w-full max-w-lg rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-slide-up border border-slate-100 dark:border-slate-800"
                onClick={e => e.stopPropagation()}
            >
                <div className="p-8 border-b border-slate-50 dark:border-slate-800 flex items-center justify-between">
                    <div>
                        <h3 id="category-search-modal-title" className="text-lg font-black uppercase tracking-tight text-slate-800 dark:text-slate-100">
                            Categorias
                        </h3>
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mt-1">
                            Selecione para associar ao produto
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-2 text-slate-400 hover:text-red-500 transition-colors cursor-pointer"
                        aria-label="Fechar busca de categorias"
                    >
                        <i className="bi bi-x-lg text-xl" aria-hidden="true" />
                    </button>
                </div>
                
                <div className="p-6 border-b border-slate-50 dark:border-slate-800">
                    <div className="relative">
                        <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" aria-hidden="true" />
                        <input
                            autoFocus
                            aria-label="Buscar categoria ou subcategoria"
                            value={search}
                            onChange={e => setSearch(e.target.value)}
                            placeholder="Buscar categoria ou subcategoria..."
                            className="w-full pl-11 pr-4 py-4 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all dark:text-slate-100"
                        />
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto max-h-[40vh] p-4 space-y-2 custom-scrollbar" role="listbox" aria-label="Lista de categorias disponíveis">
                    {filtered.map(cat => {
                        const isSelected = selectedIds.includes(cat.id);
                        const isEnv = !cat.parents || cat.parents.length === 0;
                        return (
                            <button
                                key={cat.id}
                                type="button"
                                role="option"
                                aria-selected={isSelected}
                                onClick={() => onSelect(cat.id)}
                                className={`w-full flex items-center justify-between px-5 py-4 rounded-2xl transition-all cursor-pointer ${
                                    isSelected 
                                        ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/30' 
                                        : 'hover:bg-slate-50 dark:hover:bg-slate-800/50 text-slate-600 dark:text-slate-400'
                                }`}
                            >
                                <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${isEnv ? 'bg-emerald-500' : 'bg-blue-400'}`} aria-hidden="true" />
                                    <div className="flex flex-col items-start translate-y-[-1px]">
                                        <span className={`text-sm font-bold ${isSelected ? 'text-white' : 'dark:text-slate-200'}`}>
                                            {cat.name}
                                        </span>
                                        <span className="text-[8px] font-black uppercase tracking-widest opacity-60">
                                            {isEnv ? 'Ambiente' : 'Categoria'}
                                        </span>
                                    </div>
                                </div>
                                {isSelected ? (
                                    <i className="bi bi-check-circle-fill text-lg" aria-hidden="true" />
                                ) : (
                                    <i className="bi bi-plus-circle opacity-30 text-lg" aria-hidden="true" />
                                )}
                            </button>
                        );
                    })}
                    {filtered.length === 0 && (
                        <div className="p-8 text-center text-slate-400 text-xs font-bold">
                            Nenhuma categoria encontrada para "{search}".
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default CategorySearchModal;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '@/pages/utils/supabaseConfig';
import {
    createInitialLabelPrintSelection,
    orderLabelPrintProducts,
    setLabelPrintQuantity,
    toggleLabelPrintProduct,
    type LabelPrintProduct,
    type SelectedLabelPrintProduct,
} from '../labelPrintSelection';

export type LabelPrintType = 'identification' | 'price';

type ProductItem = LabelPrintProduct;

export interface LabelPrintSelectionModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly initialProduct: ProductItem;
    readonly labelType: LabelPrintType;
}

interface RawProductDbRow {
    readonly id: string;
    readonly description: string | null;
    readonly code: string | null;
    readonly sku: string | null;
    readonly unit_price: number | null;
    readonly images: readonly string[] | null;
}

/**
 * Modal para seleção de produtos e quantidades para impressão de etiquetas (identificação ou preço).
 */
export const LabelPrintSelectionModal: React.FC<LabelPrintSelectionModalProps> = ({
    isOpen,
    onClose,
    initialProduct,
    labelType,
}) => {
    const navigate = useNavigate();
    const [allProducts, setAllProducts] = useState<ProductItem[]>([]);
    const [search, setSearch] = useState('');
    const [loading, setLoading] = useState(false);
    const [selected, setSelected] = useState<Map<string, SelectedLabelPrintProduct>>(new Map());
    const searchInputRef = useRef<HTMLInputElement>(null);

    // Carrega todos os produtos ativos elegíveis ao abrir
    useEffect(() => {
        if (!isOpen) return;
        setLoading(true);
        setSearch('');

        // Pré-seleciona produto inicial com quantidade 1
        setSelected(createInitialLabelPrintSelection(initialProduct));

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                onClose();
            }
        };

        window.addEventListener('keydown', handleKeyDown);

        supabase
            .from('products')
            .select('id, description, code, sku, unit_price, images')
            .eq('active', true)
            .is('parent_id', null)
            .order('description', { ascending: true })
            .then(({ data, error }) => {
                if (!error && data) {
                    const rows = data as unknown as readonly RawProductDbRow[];
                    setAllProducts(
                        rows.map((p) => ({
                            id: p.id,
                            description: p.description || '',
                            code: p.code || '',
                            sku: p.sku || '',
                            unitPrice: Number(p.unit_price) || 0,
                            images: Array.isArray(p.images) ? [...p.images] : [],
                        }))
                    );
                }
                setLoading(false);
            })
            .catch(() => {
                setLoading(false);
            });

        const timer = setTimeout(() => searchInputRef.current?.focus(), 200);

        return () => {
            window.removeEventListener('keydown', handleKeyDown);
            clearTimeout(timer);
        };
    }, [isOpen, initialProduct, onClose]);

    const toggleProduct = useCallback((product: ProductItem) => {
        setSelected((prev) => toggleLabelPrintProduct(prev, product));
    }, []);

    const setQty = useCallback((id: string, qty: number) => {
        setSelected((prev) => setLabelPrintQuantity(prev, id, qty));
    }, []);

    const orderedProducts = orderLabelPrintProducts(allProducts, search, selected);

    const handleConfirm = () => {
        if (selected.size === 0) return;
        const products = Array.from(selected.values()).map((s) => ({
            ...s.product,
            labelQty: s.qty,
        }));
        navigate('/estoque/etiquetas', {
            state: {
                batchProducts: products,
                labelType,
            },
        });
        onClose();
    };

    if (!isOpen) return null;

    const typeInfo = {
        identification: {
            title: 'Etiqueta de Identificação',
            icon: 'bi-qr-code',
            color: 'blue',
            description: 'Código de barras, SKU e nome do produto',
        },
        price: {
            title: 'Etiqueta de Preço',
            icon: 'bi-tag-fill',
            color: 'emerald',
            description: 'Nome do produto e preço de venda',
        },
    }[labelType];

    const totalLabelsCount = Array.from(selected.values()).reduce((acc, s) => acc + s.qty, 0);

    return (
        <div
            className="fixed inset-0 z-[500] flex items-center justify-center p-4"
            role="dialog"
            aria-modal="true"
            aria-labelledby="label-print-modal-title"
        >
            <button
                type="button"
                className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm cursor-default"
                onClick={onClose}
                aria-label="Fechar modal"
            />
            <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl max-h-[92vh] rounded-[2.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                {/* Header */}
                <div
                    className={`px-8 py-6 border-b border-slate-50 dark:border-slate-800 flex items-center justify-between shrink-0 bg-${typeInfo.color}-50/50 dark:bg-${typeInfo.color}-900/10`}
                >
                    <div className="flex items-center gap-4">
                        <div
                            className={`w-10 h-10 rounded-2xl bg-${typeInfo.color}-100 dark:bg-${typeInfo.color}-900/30 flex items-center justify-center`}
                        >
                            <i
                                className={`bi ${typeInfo.icon} text-${typeInfo.color}-600 dark:text-${typeInfo.color}-400 text-lg`}
                                aria-hidden="true"
                            />
                        </div>
                        <div>
                            <h3 id="label-print-modal-title" className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">
                                {typeInfo.title}
                            </h3>
                            <p className="text-[10px] text-slate-400 uppercase tracking-widest mt-0.5">
                                {typeInfo.description}
                            </p>
                        </div>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-2 text-slate-400 hover:text-red-500 transition-colors rounded-xl hover:bg-red-50 dark:hover:bg-red-900/20 cursor-pointer"
                        aria-label="Fechar modal"
                    >
                        <i className="bi bi-x-lg text-lg" aria-hidden="true" />
                    </button>
                </div>

                {/* Search */}
                <div className="px-6 py-4 border-b border-slate-50 dark:border-slate-800 shrink-0">
                    <div className="relative">
                        <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 text-sm" />
                        <input
                            ref={searchInputRef}
                            type="text"
                            placeholder="Filtrar produtos..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl text-sm font-medium outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-300 dark:focus:border-blue-700 transition-all"
                        />
                        {search && (
                            <button
                                type="button"
                                onClick={() => setSearch('')}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                                aria-label="Limpar filtro de busca"
                            >
                                <i className="bi bi-x-circle-fill text-sm" aria-hidden="true" />
                            </button>
                        )}
                    </div>
                    <div className="flex items-center justify-between mt-2 px-1">
                        <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">
                            {selected.size} selecionado{selected.size !== 1 ? 's' : ''} ·{' '}
                            {orderedProducts.length} produto{orderedProducts.length !== 1 ? 's' : ''} encontrado{orderedProducts.length !== 1 ? 's' : ''}
                        </span>
                        {selected.size > 0 && (
                            <button
                                type="button"
                                onClick={() => setSelected(new Map())}
                                className="text-[9px] font-black uppercase tracking-widest text-red-400 hover:text-red-600 transition-colors"
                            >
                                Limpar seleção
                            </button>
                        )}
                    </div>
                </div>

                {/* Product List */}
                <div className="flex-1 overflow-y-auto custom-scrollbar">
                    {loading ? (
                        <div className="flex items-center justify-center py-16">
                            <div className="flex flex-col items-center gap-3">
                                <i className="bi bi-arrow-repeat animate-spin text-3xl text-blue-400" aria-hidden="true" />
                                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">
                                    Carregando produtos...
                                </span>
                            </div>
                        </div>
                    ) : orderedProducts.length === 0 ? (
                        <div className="flex items-center justify-center py-16">
                            <div className="flex flex-col items-center gap-3 text-slate-400">
                                <i className="bi bi-search text-3xl" aria-hidden="true" />
                                <span className="text-xs font-bold uppercase tracking-widest">
                                    Nenhum produto encontrado
                                </span>
                            </div>
                        </div>
                    ) : (
                        <div className="divide-y divide-slate-50 dark:divide-slate-800">
                            {orderedProducts.map((product) => {
                                const isChecked = selected.has(product.id);
                                const selItem = selected.get(product.id);
                                const isSeparator =
                                    !isChecked &&
                                    selected.size > 0 &&
                                    orderedProducts.indexOf(product) === selected.size;

                                return (
                                    <React.Fragment key={product.id}>
                                        {isSeparator && (
                                            <div className="px-6 py-2 bg-slate-50 dark:bg-slate-950 border-t border-b border-slate-100 dark:border-slate-800">
                                                <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">
                                                    Outros produtos
                                                </span>
                                            </div>
                                        )}
                                        <div
                                            className={`flex items-center gap-4 px-6 py-3 transition-colors cursor-pointer group ${
                                                isChecked
                                                    ? 'bg-blue-50/50 dark:bg-blue-900/10 hover:bg-blue-50 dark:hover:bg-blue-900/20'
                                                    : 'hover:bg-slate-50 dark:hover:bg-slate-800/30'
                                            }`}
                                            onClick={() => toggleProduct(product)}
                                        >
                                            {/* Checkbox */}
                                            <div
                                                className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center shrink-0 transition-all ${
                                                    isChecked
                                                        ? 'bg-blue-600 border-blue-600'
                                                        : 'border-slate-300 dark:border-slate-700 group-hover:border-blue-400'
                                                }`}
                                            >
                                                {isChecked && (
                                                    <i className="bi bi-check text-white text-[10px] font-black" aria-hidden="true" />
                                                )}
                                            </div>

                                            {/* Thumbnail */}
                                            <div className="shrink-0">
                                                {product.images?.[0] ? (
                                                    <img
                                                        src={product.images[0]}
                                                        alt=""
                                                        className="w-9 h-9 rounded-xl object-cover border border-slate-100 dark:border-slate-800"
                                                    />
                                                ) : (
                                                    <div className="w-9 h-9 rounded-xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-300">
                                                        <i className="bi bi-image text-sm" aria-hidden="true" />
                                                    </div>
                                                )}
                                            </div>

                                            {/* Info */}
                                            <div className="flex-1 min-w-0">
                                                <p
                                                    className={`text-xs font-bold truncate ${
                                                        isChecked
                                                            ? 'text-blue-700 dark:text-blue-300'
                                                            : 'text-slate-700 dark:text-slate-200'
                                                    }`}
                                                >
                                                    {product.description}
                                                </p>
                                                <p className="text-[10px] text-slate-400 font-mono mt-0.5">
                                                    {product.sku || product.code || '—'}
                                                    {product.unitPrice
                                                        ? ` · R$ ${product.unitPrice.toFixed(2).replace('.', ',')}`
                                                        : ''}
                                                </p>
                                            </div>

                                            {/* Quantity Input - only shown when selected */}
                                            {isChecked && (
                                                <div
                                                    className="flex items-center gap-1 shrink-0"
                                                    onClick={(e) => e.stopPropagation()}
                                                >
                                                    <button
                                                        type="button"
                                                        onClick={() => setQty(product.id, (selItem?.qty || 1) - 1)}
                                                        disabled={(selItem?.qty || 1) <= 1}
                                                        className="w-7 h-7 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-blue-100 hover:text-blue-600 transition-all flex items-center justify-center disabled:opacity-30 disabled:cursor-not-allowed text-xs font-black"
                                                        aria-label="Diminuir quantidade de etiquetas"
                                                    >
                                                        −
                                                    </button>
                                                    <input
                                                        type="number"
                                                        min={1}
                                                        value={selItem?.qty || 1}
                                                        onChange={(e) => setQty(product.id, parseInt(e.target.value, 10) || 1)}
                                                        className="w-12 text-center text-xs font-black text-blue-600 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg py-1 outline-none focus:ring-2 focus:ring-blue-400"
                                                        aria-label="Quantidade de etiquetas"
                                                    />
                                                    <button
                                                        type="button"
                                                        onClick={() => setQty(product.id, (selItem?.qty || 1) + 1)}
                                                        className="w-7 h-7 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-500 hover:bg-blue-100 hover:text-blue-600 transition-all flex items-center justify-center text-xs font-black"
                                                        aria-label="Aumentar quantidade de etiquetas"
                                                    >
                                                        +
                                                    </button>
                                                    <span className="text-[9px] text-slate-400 font-bold ml-1">un</span>
                                                </div>
                                            )}
                                        </div>
                                    </React.Fragment>
                                );
                            })}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-8 py-5 border-t border-slate-50 dark:border-slate-800 flex items-center justify-between shrink-0">
                    <div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                            {totalLabelsCount} etiqueta{totalLabelsCount !== 1 ? 's' : ''} no total
                        </p>
                        <p className="text-[9px] text-slate-400 mt-0.5">
                            {selected.size} produto{selected.size !== 1 ? 's' : ''} selecionado{selected.size !== 1 ? 's' : ''}
                        </p>
                    </div>
                    <div className="flex gap-3">
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-5 py-2.5 text-slate-400 hover:text-slate-600 font-black text-xs uppercase tracking-widest transition-all"
                        >
                            Cancelar
                        </button>
                        <button
                            type="button"
                            onClick={handleConfirm}
                            disabled={selected.size === 0}
                            className={`px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-lg flex items-center gap-2 disabled:opacity-40 disabled:cursor-not-allowed ${
                                labelType === 'identification'
                                    ? 'bg-blue-600 hover:bg-blue-700 text-white shadow-blue-200/50'
                                    : 'bg-emerald-600 hover:bg-emerald-700 text-white shadow-emerald-200/50'
                            }`}
                        >
                            <i className="bi bi-printer-fill" aria-hidden="true" />
                            Imprimir Etiquetas
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default LabelPrintSelectionModal;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import VariationType, { VariationOption } from '../../../../types/variation.type';
import { useVariations } from '../../../Variations/useVariations';
import { saveVariation, updateVariation, checkVariationUsage } from '../../../../utils/variationService';
import { toast } from 'react-toastify';
import { normalizeSearchTerm } from '../../../../utils/textUtils';
import {
    appendAttributeDraftValue,
    finalizeAttributeDraftValues,
    normalizeAttributeDraftValue,
} from '../attributeValueDraft';

export interface ManageAttributesModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
}

export const ManageAttributesModal: React.FC<ManageAttributesModalProps> = ({ isOpen, onClose }) => {
    const { variations, loading, handleDelete, refresh } = useVariations();

    const [searchTerm, setSearchTerm] = useState('');
    const [newAttrName, setNewAttrName] = useState('');
    const [newDataType, setNewDataType] = useState<VariationType['dataType']>('list');
    const [newUnit, setNewUnit] = useState('');
    const [tempValues, setTempValues] = useState<string[]>([]);
    const [currentValInput, setCurrentValInput] = useState('');
    const [isSaving, setIsSaving] = useState(false);
    const [existingValInputs, setExistingValInputs] = useState<Record<string, string>>({});

    useEffect(() => {
        if (!isOpen) return;

        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape' && !isSaving) {
                onClose();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, onClose, isSaving]);

    if (!isOpen) return null;

    const handleKeyDownTagInput = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter' || e.key === ',') {
            e.preventDefault();
            const val = normalizeAttributeDraftValue(currentValInput);
            if (val) {
                if (tempValues.includes(val)) {
                    toast.error('Este valor já foi adicionado!');
                    return;
                }
                setTempValues((prev) => appendAttributeDraftValue(prev, currentValInput));
            }
            setCurrentValInput('');
        } else if (e.key === 'Backspace' && !currentValInput) {
            setTempValues((prev) => prev.slice(0, -1));
        }
    };

    const handleSaveAttribute = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newAttrName.trim()) {
            toast.error('Preencha o nome do atributo!');
            return;
        }

        const finalValues = finalizeAttributeDraftValues(tempValues, currentValInput);

        if (newDataType === 'list' && finalValues.length === 0) {
            toast.error('Adicione pelo menos um valor/rótulo!');
            return;
        }

        setIsSaving(true);
        try {
            await saveVariation({
                name: newAttrName.trim(),
                active: true,
                dataType: newDataType,
                unit: newDataType === 'measure' ? newUnit.trim() : '',
                options: newDataType === 'list' ? finalValues.map((val) => ({ id: '', value: val })) : []
            });

            toast.success('Atributo criado com sucesso!');
            setNewAttrName('');
            setNewDataType('list');
            setNewUnit('');
            setTempValues([]);
            setCurrentValInput('');
            refresh();
        } catch (err: unknown) {
            const message = err instanceof Error ? err.message : 'Erro desconhecido ao salvar atributo';
            toast.error(`Erro ao salvar: ${message}`);
        } finally {
            setIsSaving(false);
        }
    };

    const handleDeleteValue = async (attr: VariationType, opt: VariationOption) => {
        if (!confirm(`Tem certeza que deseja remover o valor "${opt.value}" do atributo "${attr.name}"?`)) return;

        try {
            const isUsed = await checkVariationUsage(attr.name, opt.value);
            if (isUsed) {
                toast.warning(`Não é possível excluir o valor "${opt.value}" pois ele está em uso em uma ou mais variações de produtos.`);
                return;
            }

            const updatedOptions = attr.options.filter((o) => o.id !== opt.id);
            await updateVariation(attr.id!, { options: updatedOptions });
            toast.success('Valor removido com sucesso!');
            refresh();
        } catch (err: unknown) {
            const message = err instanceof Error ? err.message : 'Erro ao remover valor';
            toast.error(`Erro ao remover valor: ${message}`);
        }
    };

    const handleAddValueToExisting = async (attr: VariationType) => {
        const valText = existingValInputs[attr.id!] || '';
        if (!valText.trim()) return;

        if (attr.options.some((o) => o.value.toLowerCase() === valText.trim().toLowerCase())) {
            toast.error('Este valor já existe para este atributo!');
            return;
        }

        try {
            const updatedOptions = [...attr.options, { id: '', value: valText.trim() }];
            await updateVariation(attr.id!, { options: updatedOptions });
            toast.success('Valor adicionado com sucesso!');
            setExistingValInputs((prev) => ({ ...prev, [attr.id!]: '' }));
            refresh();
        } catch (err: unknown) {
            const message = err instanceof Error ? err.message : 'Erro ao adicionar valor';
            toast.error(`Erro ao adicionar valor: ${message}`);
        }
    };

    const filteredVariations = variations.filter(
        (v) =>
            normalizeSearchTerm(v.name).includes(normalizeSearchTerm(searchTerm)) ||
            (v.id && normalizeSearchTerm(v.id).includes(normalizeSearchTerm(searchTerm)))
    );

    return createPortal(
        <div className="fixed inset-0 z-[1000025] flex items-center justify-center p-4 sm:p-6">
            <button 
                type="button" 
                aria-label="Fechar modal" 
                className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200 cursor-default" 
                onClick={onClose} 
            />
            <div 
                role="dialog"
                aria-modal="true"
                aria-labelledby="manage-attributes-modal-title"
                className="relative bg-white dark:bg-slate-950 w-full max-w-5xl max-h-[90vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95 duration-200 border border-slate-100 dark:border-slate-800 z-10"
            >
                {/* Header */}
                <div className="px-6 py-5 sm:px-8 sm:py-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between shrink-0 bg-white dark:bg-slate-950">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-2xl bg-blue-50 dark:bg-blue-900/20 flex items-center justify-center text-blue-600 dark:text-blue-400 shrink-0">
                            <i className="bi bi-gear-wide-connected text-xl" aria-hidden="true" />
                        </div>
                        <div>
                            <h3 id="manage-attributes-modal-title" className="text-lg sm:text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                Gerenciar Atributos e Valores
                            </h3>
                            <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">
                                Atributos globais do sistema para variações de produtos
                            </p>
                        </div>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        aria-label="Fechar"
                        className="w-10 h-10 flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-xl transition-all cursor-pointer"
                    >
                        <i className="bi bi-x-lg text-lg" aria-hidden="true" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-6 sm:p-8 custom-scrollbar space-y-6">
                    {/* Barra de busca */}
                    <div className="relative max-w-md">
                        <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 text-xs" aria-hidden="true" />
                        <input
                            type="text"
                            placeholder="Buscar atributos cadastrados..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all font-bold dark:text-slate-300"
                        />
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
                        {/* Formulário Novo Atributo (Coluna Esquerda) */}
                        <div className="lg:col-span-1 bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl p-6 space-y-4">
                            <div>
                                <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 flex items-center gap-2">
                                    <i className="bi bi-plus-circle-fill text-blue-600 text-xs" aria-hidden="true" />
                                    Novo Atributo
                                </h4>
                                <p className="text-[9px] font-black uppercase tracking-widest text-slate-400 mt-0.5">
                                    Ex: Cor, Tamanho, Voltagem
                                </p>
                            </div>

                            <form onSubmit={handleSaveAttribute} className="space-y-4">
                                <div className="space-y-1.5">
                                    <label htmlFor="new-attr-name-input" className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                        Nome do Atributo
                                    </label>
                                    <input
                                        id="new-attr-name-input"
                                        placeholder="Ex: Cor, Tamanho, Material"
                                        value={newAttrName}
                                        onChange={(e) => setNewAttrName(e.target.value)}
                                        className="w-full px-3.5 py-2.5 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-bold dark:text-slate-300"
                                        required
                                    />
                                </div>

                                <div className="space-y-1.5">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                        Tipo de Dado
                                    </label>
                                    <select
                                        value={newDataType}
                                        onChange={(e) => setNewDataType(e.target.value as VariationType['dataType'])}
                                        className="w-full px-3.5 py-2.5 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-bold dark:text-slate-300"
                                    >
                                        <option value="list">Lista de Valores</option>
                                        <option value="text">Texto Livre</option>
                                        <option value="integer">Número Inteiro</option>
                                        <option value="decimal">Número Decimal</option>
                                        <option value="boolean">Booleano (Sim/Não)</option>
                                        <option value="measure">Medida (com unidade)</option>
                                    </select>
                                </div>

                                {newDataType === 'measure' && (
                                    <div className="space-y-1.5 animate-in fade-in zoom-in-95 duration-200">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                            Unidade (Ex: cm, kg, L)
                                        </label>
                                        <input
                                            placeholder="Unidade..."
                                            value={newUnit}
                                            onChange={(e) => setNewUnit(e.target.value)}
                                            className="w-full px-3.5 py-2.5 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-bold dark:text-slate-300"
                                        />
                                    </div>
                                )}

                                {newDataType === 'list' && (
                                    <div className="space-y-1.5 animate-in fade-in zoom-in-95 duration-200">
                                        <label htmlFor="new-attr-tags-input" className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                            Valores (Enter ou Vírgula)
                                        </label>
                                        <div className="min-h-[4.5rem] flex flex-wrap gap-1.5 p-2.5 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl items-center">
                                            {tempValues.map((val, idx) => (
                                                <span
                                                    key={idx}
                                                    className="h-7 bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 font-bold text-[11px] gap-1 px-2.5 rounded-lg border border-blue-100 dark:border-blue-900/30 flex items-center shrink-0"
                                                >
                                                    {val}
                                                    <button
                                                        type="button"
                                                        onClick={() => setTempValues((prev) => prev.filter((_, i) => i !== idx))}
                                                        aria-label={`Remover valor ${val}`}
                                                        className="text-blue-400 hover:text-red-500 transition-colors cursor-pointer"
                                                    >
                                                        <i className="bi bi-x text-xs" aria-hidden="true" />
                                                    </button>
                                                </span>
                                            ))}
                                            <input
                                                id="new-attr-tags-input"
                                                type="text"
                                                placeholder={tempValues.length === 0 ? 'Ex: Azul, Preto...' : ''}
                                                value={currentValInput}
                                                onChange={(e) => setCurrentValInput(e.target.value)}
                                                onKeyDown={handleKeyDownTagInput}
                                                className="flex-1 min-w-[80px] bg-transparent outline-none border-none text-xs p-1 font-bold dark:text-slate-300"
                                            />
                                        </div>
                                    </div>
                                )}

                                <button
                                    type="submit"
                                    disabled={isSaving}
                                    className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-md shadow-blue-500/20 transition-all active:scale-95 flex items-center justify-center gap-2 cursor-pointer"
                                >
                                    {isSaving ? (
                                        <i className="bi bi-arrow-clockwise animate-spin text-sm" aria-hidden="true" />
                                    ) : (
                                        <>Criar Atributo</>
                                    )}
                                </button>
                            </form>
                        </div>

                        {/* Lista de Atributos Existentes (Coluna Direita) */}
                        <div className="lg:col-span-2 space-y-4">
                            {loading ? (
                                <div className="bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 p-8 text-center flex flex-col items-center justify-center gap-2">
                                    <i className="bi bi-arrow-clockwise animate-spin text-2xl text-blue-600" aria-hidden="true" />
                                    <p className="text-xs font-black uppercase tracking-widest text-slate-400">Carregando atributos...</p>
                                </div>
                            ) : filteredVariations.length === 0 ? (
                                <div className="bg-slate-50 dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 p-8 text-center text-slate-400 font-bold text-xs">
                                    Nenhum atributo encontrado.
                                </div>
                            ) : (
                                filteredVariations.map((attr) => (
                                    <div
                                        key={attr.id}
                                        className="bg-slate-50 dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl p-5 space-y-3"
                                    >
                                        <div className="flex items-start justify-between">
                                            <div>
                                                <h5 className="text-sm font-black text-slate-800 dark:text-slate-100">{attr.name}</h5>
                                                <p className="text-[9px] font-black uppercase tracking-widest text-slate-400">
                                                    {attr.options?.length || 0} valores vinculados
                                                </p>
                                            </div>
                                            <button
                                                type="button"
                                                onClick={(e) => handleDelete(attr.id!, e)}
                                                className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg transition-all cursor-pointer"
                                                title="Excluir Atributo"
                                                aria-label={`Excluir atributo ${attr.name}`}
                                            >
                                                <i className="bi bi-trash text-sm" aria-hidden="true" />
                                            </button>
                                        </div>

                                        <div className="flex flex-wrap gap-1.5">
                                            {attr.options?.map((opt) => (
                                                <span
                                                    key={opt.id}
                                                    className="h-7 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-300 font-bold text-[11px] gap-1.5 py-0 px-2.5 rounded-full flex items-center shrink-0"
                                                >
                                                    {opt.value}
                                                    <button
                                                        type="button"
                                                        onClick={() => handleDeleteValue(attr, opt)}
                                                        className="text-slate-400 hover:text-red-500 transition-colors flex items-center cursor-pointer"
                                                        title="Remover este valor"
                                                        aria-label={`Remover valor ${opt.value}`}
                                                    >
                                                        <i className="bi bi-x text-xs" aria-hidden="true" />
                                                    </button>
                                                </span>
                                            ))}
                                            {attr.options?.length === 0 && (
                                                <span className="text-slate-400 italic text-xs">Sem valores cadastrados</span>
                                            )}
                                        </div>

                                        {/* Adição rápida de valor */}
                                        <div className="flex gap-2 max-w-sm pt-1">
                                            <input
                                                placeholder="Novo valor..."
                                                value={existingValInputs[attr.id!] || ''}
                                                onChange={(e) => setExistingValInputs((prev) => ({ ...prev, [attr.id!]: e.target.value }))}
                                                onKeyDown={async (e) => {
                                                    if (e.key === 'Enter') {
                                                        await handleAddValueToExisting(attr);
                                                    }
                                                }}
                                                aria-label={`Adicionar novo valor ao atributo ${attr.name}`}
                                                className="flex-1 px-3 py-1.5 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-xs focus:outline-none focus:ring-2 focus:ring-blue-500/20 font-bold dark:text-slate-300"
                                            />
                                            <button
                                                type="button"
                                                onClick={() => void handleAddValueToExisting(attr)}
                                                className="bg-white hover:bg-slate-100 dark:bg-slate-950 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-800 font-bold text-xs px-3 py-1.5 rounded-xl transition-all cursor-pointer"
                                            >
                                                Adicionar
                                            </button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 flex justify-end bg-white dark:bg-slate-950 shrink-0">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-2.5 bg-slate-900 text-white dark:bg-slate-100 dark:text-slate-900 rounded-xl font-black uppercase tracking-widest text-[10px] shadow-sm hover:opacity-90 transition-all cursor-pointer"
                    >
                        Concluir
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
};

export default ManageAttributesModal;

import React, { useState, useEffect } from 'react';
import Product, { Variation } from '../../../../types/product.type';

export interface ProductConversionModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly formData: Partial<Product>;
    readonly onConvert: (updatedData: Partial<Product>) => void;
}

/**
 * Modal para conversão de um produto simples em um produto pai com grade de variações inicial.
 */
export const ProductConversionModal: React.FC<ProductConversionModalProps> = ({
    isOpen,
    onClose,
    formData,
    onConvert,
}) => {
    const [attrName, setAttrName] = useState('Cor');
    const [attrValue, setAttrValue] = useState('Padrão');

    useEffect(() => {
        if (!isOpen) return;

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                onClose();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    const handleConvert = () => {
        const variationId = typeof crypto !== 'undefined' && crypto.randomUUID
            ? crypto.randomUUID()
            : `var_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;

        const newVariation: Variation = {
            id: variationId,
            name: `${attrName.trim().toUpperCase()}: ${attrValue.trim().toUpperCase()}`,
            sku: formData.code || '',
            stock: formData.stock || 0,
            unitPrice: formData.unitPrice || 0,
            costPrice: formData.costPrice || 0,
            syncUnitPrice: true,
            syncCostPrice: true,
            syncDescription: true,
            images: [],
            active: true,
            attributes: [{ name: attrName.trim(), value: attrValue.trim() }],
            comboItems: [],
        };

        const updatedData: Partial<Product> = {
            ...formData,
            hasVariations: true,
            variations: [newVariation],
            // Limpa código e estoque do pai, que foram transferidos para a primeira variação
            code: '',
            stock: 0,
        };

        onConvert(updatedData);
        onClose();
    };

    return (
        <div
            className="fixed inset-0 z-[1000020] flex items-center justify-center p-4"
            role="dialog"
            aria-modal="true"
            aria-labelledby="product-conversion-modal-title"
        >
            <button
                type="button"
                className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm cursor-default"
                onClick={onClose}
                aria-label="Fechar modal"
            />
            <div className="relative bg-white dark:bg-slate-900 w-full max-w-md rounded-[2.5rem] shadow-2xl p-8 border border-slate-100 dark:border-slate-800 animate-in fade-in zoom-in-95 duration-300">
                <div className="flex items-center gap-3 mb-6">
                    <div className="w-12 h-12 bg-blue-100 dark:bg-blue-900/30 rounded-2xl flex items-center justify-center text-blue-600">
                        <i className="bi bi-layers-fill text-2xl" aria-hidden="true" />
                    </div>
                    <div>
                        <h3 id="product-conversion-modal-title" className="text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                            Converter para Variação
                        </h3>
                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-0.5">
                            Criar grade de atributos
                        </p>
                    </div>
                </div>

                <p className="text-sm text-slate-500 dark:text-slate-400 mb-8 leading-relaxed">
                    Você está transformando este produto simples em um produto com variações.
                    O <strong>SKU ({formData.code || '—'})</strong> e o <strong>Estoque ({formData.stock || 0})</strong> serão movidos para a primeira variação.
                </p>

                <div className="flex flex-col gap-6">
                    <div className="flex flex-col gap-2">
                        <label htmlFor="conversion-attr-name" className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                            Nome do Atributo (Ex: Cor, Tamanho)
                        </label>
                        <input
                            id="conversion-attr-name"
                            value={attrName}
                            onChange={(e) => setAttrName(e.target.value)}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none text-sm font-bold dark:text-slate-200 focus:ring-2 focus:ring-blue-500/20"
                            placeholder="Ex: Cor"
                        />
                    </div>

                    <div className="flex flex-col gap-2">
                        <label htmlFor="conversion-attr-value" className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                            Valor do Atributo (Ex: Branco, G)
                        </label>
                        <input
                            id="conversion-attr-value"
                            value={attrValue}
                            onChange={(e) => setAttrValue(e.target.value)}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none text-sm font-bold dark:text-slate-200 focus:ring-2 focus:ring-blue-500/20"
                            placeholder="Ex: Padrão"
                        />
                    </div>
                </div>

                <div className="flex gap-3 mt-10">
                    <button
                        type="button"
                        onClick={onClose}
