import React, { useState, useEffect, useRef } from 'react';
import Product from '../../../../../types/product.type';
import { ncmService, NcmSearchResult } from '@/services/fiscal/ncmService';
import type { NcmAiSuggestion } from '@/pages/utils/aiService/aiFiscalClassificationService';

interface ProductNcmSelectorProps {
    formData: Partial<Product>;
    setFormData: React.Dispatch<React.SetStateAction<Partial<Product>>>;
    isNcmAutoEnabled: boolean;
    readonly toggleNcmAuto: () => void;
    isGeneratingNCM: boolean;
    suggestion: NcmAiSuggestion | null;
    onAcceptSuggestion: () => void;
    onDismissSuggestion: () => void;
}

export const ProductNcmSelector: React.FC<ProductNcmSelectorProps> = ({
    formData,
    setFormData,
    isNcmAutoEnabled,
    toggleNcmAuto,
    isGeneratingNCM,
    suggestion,
    onAcceptSuggestion,
    onDismissSuggestion,
}) => {
    const [searchQuery, setSearchQuery] = useState(formData.fiscal?.ncm || '');
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const [isInfoModalOpen, setIsInfoModalOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => setSearchQuery(formData.fiscal?.ncm || ''), [formData.fiscal?.ncm]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const [results, setResults] = useState<NcmSearchResult[]>([]);
    const [isLoadingNcms, setIsLoadingNcms] = useState(false);
    const [currentCatalogEntry, setCurrentCatalogEntry] = useState<Awaited<ReturnType<typeof ncmService.getCatalogEntry>>>(null);
    const [hasCheckedCatalogEntry, setHasCheckedCatalogEntry] = useState(false);

    useEffect(() => {
        const fetchNcms = async () => {
            if (searchQuery.trim().length < 2) {
                setResults([]);
                return;
            }
            setIsLoadingNcms(true);
            try {
                const res = await ncmService.searchNcms(searchQuery, 10);
                setResults(res);
            } catch (err) {
                console.error("Erro ao buscar NCMs:", err);
                setResults([]);
            } finally {
                setIsLoadingNcms(false);
            }
        };
        const timer = setTimeout(fetchNcms, 300);
        return () => clearTimeout(timer);
    }, [searchQuery]);

    useEffect(() => {
        const code = (formData.fiscal?.ncm || '').replace(/\D/g, '');
        if (code.length !== 8) {
            setCurrentCatalogEntry(null);
            setHasCheckedCatalogEntry(false);
            return;
        }
        let cancelled = false;
        setHasCheckedCatalogEntry(false);
        const timer = window.setTimeout(async () => {
            try {
                const entry = await ncmService.getCatalogEntry(code);
                if (!cancelled) setCurrentCatalogEntry(entry);
            } catch (error) {
                console.warn('[NCM] Não foi possível consultar a vigência do código.', error);
                if (!cancelled) setCurrentCatalogEntry(null);
            } finally {
                if (!cancelled) setHasCheckedCatalogEntry(true);
            }
        }, 250);
        return () => { cancelled = true; window.clearTimeout(timer); };
    }, [formData.fiscal?.ncm]);

    return (
        <div className="flex flex-col gap-2 relative" ref={dropdownRef}>
            <div className="flex items-center justify-between gap-2">
                <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">NCM *</label>
                <div className="flex items-center gap-2">
                    <button
                        type="button"
                        role="switch"
                        aria-checked={isNcmAutoEnabled}
                        aria-label="Autopreencher NCM"
                        onClick={toggleNcmAuto}
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-purple-100/80 hover:bg-purple-200/80 dark:bg-purple-950/60 dark:hover:bg-purple-900/60 border border-purple-200 dark:border-purple-800/70 text-amber-600 dark:text-amber-400 font-black uppercase text-[9px] tracking-wider transition-all disabled:opacity-50 active:scale-95 shadow-sm"
                        title="Ativar sugestões de NCM por IA"
                    >
                        {isGeneratingNCM ? <i className="bi bi-arrow-repeat animate-spin text-amber-500" /> : <i className="bi bi-stars text-amber-500 text-xs font-bold" />}
                        <span>Autopreencher</span>
                        <span aria-hidden="true" className={`relative inline-flex h-5 w-9 rounded-full transition-colors ${isNcmAutoEnabled ? 'bg-purple-600' : 'bg-slate-400'}`}>
                            <span className={`absolute top-0.5 left-0.5 h-4 w-4 rounded-full bg-white shadow transition-transform ${isNcmAutoEnabled ? 'translate-x-4' : ''}`} />
                        </span>
                    </button>

                    <button
                        type="button"
                        onClick={() => setIsInfoModalOpen(true)}
                        onMouseEnter={() => setIsInfoModalOpen(true)}
                        onFocus={() => setIsInfoModalOpen(true)}
                        aria-label="Como funciona o autopreenchimento do NCM"
                        className="p-1 text-slate-400 hover:text-blue-500 transition-colors"
                        title="Como funciona a IA do NCM?"
                    >
                        <i className="bi bi-info-circle text-xs" />
                    </button>
                </div>
            </div>
            <div
                className={`relative overflow-hidden rounded-2xl transition-all ${
                    isGeneratingNCM
                        ? 'ring-2 ring-amber-400/70 shadow-[0_0_18px_rgba(251,191,36,0.32)]'
                        : ''
                }`}
                aria-busy={isGeneratingNCM}
            >
                <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => {
                        const val = e.target.value;
                        setSearchQuery(val);
                        setFormData(prev => ({
                            ...prev,
                            fiscal: {
                                ...prev.fiscal!,
                                ncm: val
                            }
                        }));
                        setIsDropdownOpen(true);
                    }}
                    onFocus={() => setIsDropdownOpen(true)}
                    placeholder="Digite ou pesquise o NCM..."
                    className={`w-full pl-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 outline-none text-xs font-bold dark:text-slate-200 tracking-wider font-mono transition-colors ${
                        isGeneratingNCM
                            ? 'pr-20 border-amber-400'
                            : 'pr-8 border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-400'
                    }`}
                />
                {isGeneratingNCM ? (
                    <>
                        <span className="pointer-events-none absolute inset-0 overflow-hidden rounded-2xl" aria-hidden="true">
                            <span className="ncm-input-shimmer absolute inset-y-0 left-0 w-1/3" />
                        </span>
                        <span
                            role="status"
                            className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[9px] font-black uppercase tracking-wider text-amber-600 dark:text-amber-300"
                        >
                            Gerando...
                        </span>
                    </>
                ) : (
                    <i className={`bi bi-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 transition-transform pointer-events-none ${isDropdownOpen ? 'rotate-180' : ''}`} />
                )}
            </div>

            {currentCatalogEntry && !currentCatalogEntry.active && (
                <p role="alert" className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-[10px] leading-relaxed text-amber-800 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-200">
                    Este NCM não está vigente na base local. Revise a classificação antes de usar em novas operações.
                </p>
            )}
            {hasCheckedCatalogEntry && currentCatalogEntry === null && (
                <p className="text-[10px] text-slate-500">Não foi possível confirmar a vigência deste NCM. Sincronize a tabela oficial antes de emitir documentos fiscais.</p>
            )}
            {suggestion?.ncm && (
                <div className="rounded-xl border border-violet-200 bg-violet-50 p-3 dark:border-violet-900 dark:bg-violet-950/20">
                    <div className="flex items-start justify-between gap-3">
                        <div>
                            <p className="text-[10px] font-black uppercase tracking-wider text-violet-800 dark:text-violet-200">Sugestão de NCM · confirme antes de aplicar</p>
                            <p className="mt-1 font-mono text-xs font-bold text-slate-800 dark:text-slate-100">{suggestion.ncm}</p>
                            <p className="mt-0.5 text-[10px] text-slate-600 dark:text-slate-300">{suggestion.description}</p>
                            <p className="mt-2 text-[10px] leading-relaxed text-violet-800 dark:text-violet-200">{suggestion.reviewReason}</p>
                        </div>
                        <button type="button" onClick={onDismissSuggestion} aria-label="Descartar sugestão de NCM" className="shrink-0 p-1 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200"><i className="bi bi-x-lg" /></button>
                    </div>
                    <div className="mt-3 flex items-center justify-between gap-3">
                        <span className="text-[9px] text-slate-500">Confiança informada pela IA: {Math.round(suggestion.confidence * 100)}%</span>
                        <button type="button" onClick={onAcceptSuggestion} className="rounded-lg bg-violet-600 px-3 py-2 text-[10px] font-bold text-white hover:bg-violet-700">Aplicar sugestão</button>
                    </div>
                </div>
            )}

            {isDropdownOpen && (
                <div className="absolute left-0 right-0 top-full mt-2 bg-white dark:bg-slate-900 border border-slate-150 dark:border-slate-800 rounded-2xl shadow-xl z-50 p-2 max-h-60 overflow-y-auto custom-scrollbar flex flex-col gap-0.5">
                    {isLoadingNcms ? (
                        <div className="p-3 text-center text-xs text-slate-400">
                            <i className="bi bi-arrow-repeat animate-spin mr-2" /> Buscando NCMs...
                        </div>
                    ) : results.length > 0 ? (
                        results.map(item => (
                            <div
                                key={item.code}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    setFormData(prev => ({
                                        ...prev,
                                        fiscal: {
                                            ...prev.fiscal!,
                                            ncm: item.code,
                                            ncmDescription: item.official_description
                                        }
                                    }));
                                    setSearchQuery(item.code);
                                    setIsDropdownOpen(false);
                                }}
                                className="px-3 py-2 hover:bg-slate-50 dark:hover:bg-slate-800/60 cursor-pointer transition-colors text-left rounded-xl group"
                            >
                                <span className="text-xs font-mono font-bold text-slate-800 dark:text-slate-100 group-hover:text-blue-600">{item.code}</span>
                                <p className="text-[10px] text-slate-500 line-clamp-2">{item.official_description}</p>
                                {item.alias_match && (
                                    <p className="text-[9px] text-slate-400 mt-1 italic flex items-center gap-1">
                                        <i className="bi bi-tag-fill" /> {item.alias_match}
                                    </p>
                                )}
                            </div>
                        ))
                    ) : searchQuery.length >= 2 ? (
                        <div className="p-3 text-center text-xs text-slate-400">
                            Nenhum NCM encontrado.
                        </div>
                    ) : (
                        <div className="p-3 text-center text-xs text-slate-400">
                            Digite pelo menos 2 caracteres para buscar...
                        </div>
                    )}
                </div>
            )}

            {isInfoModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-xs">
                    <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 max-w-md w-full border border-slate-200 dark:border-slate-800 shadow-2xl flex flex-col gap-4">
                        <div className="flex items-center justify-between">
                            <h4 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-wider flex items-center gap-2">
                                <i className="bi bi-stars text-amber-500" /> Inteligência Fiscal NCM
                            </h4>
                            <button type="button" onClick={() => setIsInfoModalOpen(false)} className="p-1 text-slate-400 hover:text-slate-600">
                                <i className="bi bi-x-lg" />
                            </button>
                        </div>
                        <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed">
                            A IA sugere um NCM a partir do nome, categoria, descrição e material. Ela não altera o código do produto automaticamente: confira o código e a descrição oficial e clique em “Aplicar sugestão” se a classificação estiver correta. Quando o material não está claro, MDF/MDP/madeira pode aparecer como hipótese, que exige confirmação do material real.
                        </p>
                        <button
                            type="button"
                            onClick={() => setIsInfoModalOpen(false)}
                            className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl transition-colors"
                        >
                            Entendido
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Product from '../../../../types/product.type';
import { getSettings } from '@/pages/utils/settingsService';
import { CEST_OPTIONS, CFOP_OPTIONS, CSOSN_OPTIONS, ORIGEM_OPTIONS, PIS_COFINS_OPTIONS } from './productFiscalOptions';
import { createInitialProductFiscalInfo } from './productFiscalDefaults';
import { ProductNcmSelector } from './fiscal/ProductNcmSelector';
import type { NcmAiSuggestion } from '@/pages/utils/aiService/aiFiscalClassificationService';

interface ProductFiscalTabProps {
    readonly formData: Partial<Product>;
    readonly setFormData: React.Dispatch<React.SetStateAction<Partial<Product>>>;
    readonly isNcmAutoEnabled: boolean;
    readonly toggleNcmAuto: () => void;
    readonly isGeneratingNCM: boolean;
    readonly ncmSuggestion: NcmAiSuggestion | null;
    readonly acceptNcmSuggestion: () => void;
    readonly dismissNcmSuggestion: () => void;
}

const ProductFiscalTab: React.FC<ProductFiscalTabProps> = ({
    formData,
    setFormData,
    isNcmAutoEnabled,
    toggleNcmAuto,
    isGeneratingNCM,
    ncmSuggestion,
    acceptNcmSuggestion,
    dismissNcmSuggestion,
}) => {
    const [isInfoModalOpen, setIsInfoModalOpen] = useState(false);

    // Fechar modal com tecla Escape
    useEffect(() => {
        if (!isInfoModalOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setIsInfoModalOpen(false);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isInfoModalOpen]);

    // Carrega os dados padrões fiscais das configurações apenas se a estrutura fiscal ainda não foi inicializada
    useEffect(() => {
        if (!formData.fiscal || Object.keys(formData.fiscal).length === 0) {
            const settings = getSettings();
            if (settings.fiscalDefaults) {
                setFormData(prev => {
                    if (prev.fiscal && Object.keys(prev.fiscal).length > 0) return prev;
                    return {
                        ...prev,
                        fiscal: createInitialProductFiscalInfo(prev.itemType, settings.fiscalDefaults),
                    };
                });
            }
        }
    }, []);

    return (
        <div className="flex flex-col gap-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
            <div className="flex flex-col gap-6">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                    <div>
                        <h4 className="text-xs font-black uppercase tracking-widest text-slate-800 dark:text-slate-200 flex items-center gap-2">
                            <i className="bi bi-file-earmark-text text-blue-600"></i> Informações Fiscais para NF-e
                        </h4>
                        <p className="text-[9px] text-slate-400 uppercase font-black tracking-widest mt-1">Dados essenciais para emissão de nota fiscal e conformidade tributária</p>
                    </div>
                </div>

                <div className={`grid grid-cols-1 ${['201', '202', '500'].includes(formData.fiscal?.cst || '') ? 'md:grid-cols-2' : ''} gap-8`}>
                    {formData.itemType === 'service' ? (
                        <div className="flex flex-col gap-2">
                            <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">Código Municipal / Serviço (LC 116/03) *</label>
                            <input
                                value={formData.fiscal?.codigoServico || ''}
                                onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, codigoServico: e.target.value.replace(/\D/g, '').slice(0, 8) } })}
                                className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold tracking-[0.2em] focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                                placeholder="Ex: 0101"
                            />
                        </div>
                    ) : (
                        <>
                            <ProductNcmSelector
                                formData={formData}
                                setFormData={setFormData}
                                isNcmAutoEnabled={isNcmAutoEnabled}
                                toggleNcmAuto={toggleNcmAuto}
                                isGeneratingNCM={isGeneratingNCM}
                                suggestion={ncmSuggestion}
                                onAcceptSuggestion={acceptNcmSuggestion}
                                onDismissSuggestion={dismissNcmSuggestion}
                            />

                            {/* CEST - Exibido apenas se a operação for sujeita à Substituição Tributária (CSOSN 201, 202, 500) */}
                            {['201', '202', '500'].includes(formData.fiscal?.cst || '') && (
                                <div className="flex flex-col gap-2">
                                    <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">Código CEST (Substituição Tributária)</label>
                                    <div className="flex flex-col gap-2">
                                        <select
                                            value={formData.fiscal?.cest || ''}
                                            onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, cest: e.target.value } })}
                                            className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                                        >
                                            {CEST_OPTIONS.map(c => (
                                                <option key={c.value} value={c.value}>{c.label}</option>
                                            ))}
                                        </select>
                                        <input
                                            type="text"
                                            maxLength={7}
                                            value={formData.fiscal?.cest || ''}
                                            onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, cest: e.target.value.replace(/\D/g, '') } })}
                                            placeholder="Ou digite outro CEST (7 dígitos)..."
                                            className="w-full px-1 py-2 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-mono font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-300"
                                        />
                                    </div>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>

            <div className="flex flex-col gap-6 pt-2 border-t border-slate-100 dark:border-slate-800">
                <h4 className="text-xs font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Configurações de Imposto por Produto</h4>
                
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {formData.itemType !== 'service' && (
                        <div className="flex flex-col gap-2">
                            <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">Origem da Mercadoria</label>
                            <select
                                value={formData.fiscal?.origem || '0'}
                                onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, origem: e.target.value } })}
                                className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                            >
                                {ORIGEM_OPTIONS.map(o => (
                                    <option key={o.value} value={o.value}>{o.label}</option>
                                ))}
                            </select>
                        </div>
                    )}

                    {/* CST/CSOSN como Select */}
                    <div className="flex flex-col gap-2">
                        <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">
                            {formData.itemType === 'service' ? 'CST / CSOSN ISSQN' : 'CST / CSOSN ICMS (Simples Nacional)'}
                        </label>
                        <select
                            value={formData.fiscal?.cst || '102'}
                            onChange={(e) => {
                                const val = e.target.value;
                                const isSt = ['201', '202', '500'].includes(val);
                                setFormData(prev => ({
                                    ...prev,
                                    fiscal: {
                                        ...prev.fiscal!,
                                        cst: val,
                                        cest: isSt ? (prev.fiscal?.cest || '') : ''
                                    }
                                }));
                            }}
                            className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                        >
                            {CSOSN_OPTIONS.map(c => (
                                <option key={c.value} value={c.value}>{c.label}</option>
                            ))}
                        </select>
                    </div>

                    {/* CFOP como Select */}
                    <div className="flex flex-col gap-2">
                        <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">
                            {formData.itemType === 'service' ? 'CFOP Padrão (Municipal)' : 'CFOP Padrão (Estadual)'}
                        </label>
                        {formData.itemType === 'service' ? (
                            <select
                                value={formData.fiscal?.cfop || '5933'}
                                onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, cfop: e.target.value } })}
                                className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                            >
                                <option value="5933">5933 - Prestação de serviço dentro do Estado</option>
                                <option value="6933">6933 - Prestação de serviço para fora do Estado</option>
                            </select>
                        ) : (
                            <select
                                value={formData.fiscal?.cfop || '5102'}
                                onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, cfop: e.target.value } })}
                                className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                            >
                                {CFOP_OPTIONS.map(cf => (
                                    <option key={cf.value} value={cf.value}>{cf.label}</option>
                                ))}
                            </select>
                        )}
                    </div>

                    <div className="flex flex-col gap-2">
                        <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">
                            {formData.itemType === 'service' ? 'Alíquota ISS (%)' : 'Alíquota ICMS (%)'}
                        </label>
                        <input
                            type="number"
                            step="0.01"
                            value={formData.itemType === 'service' ? (formData.fiscal?.issPercent ?? 0) : (formData.fiscal?.icmsPercent ?? 0)}
                            onChange={(e) => {
                                const val = parseFloat(e.target.value);
                                setFormData(prev => ({ 
                                    ...prev, 
                                    fiscal: { 
                                        ...prev.fiscal!, 
                                        ...(prev.itemType === 'service' ? { issPercent: isNaN(val) ? 0 : val } : { icmsPercent: isNaN(val) ? 0 : val }) 
                                    } 
                                }));
                            }}
                            className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                        />
                    </div>

                    {/* PIS CST como Select */}
                    <div className="flex flex-col gap-2">
                        <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">PIS CST</label>
                        <select
                            value={formData.fiscal?.pisCst || '49'}
                            onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, pisCst: e.target.value } })}
                            className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                        >
                            {PIS_COFINS_OPTIONS.map(p => (
                                <option key={p.value} value={p.value}>{p.label}</option>
                            ))}
                        </select>
                    </div>

                    {/* COFINS CST como Select */}
                    <div className="flex flex-col gap-2">
                        <label className="text-[9px] font-black uppercase tracking-widest text-slate-400">COFINS CST</label>
                        <select
                            value={formData.fiscal?.cofinsCst || '49'}
                            onChange={(e) => setFormData({ ...formData, fiscal: { ...formData.fiscal!, cofinsCst: e.target.value } })}
                            className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold focus:border-blue-600 dark:focus:border-blue-400 transition-all dark:text-slate-200"
                        >
                            {PIS_COFINS_OPTIONS.map(p => (
                                <option key={p.value} value={p.value}>{p.label}</option>
                            ))}
                        </select>
                    </div>
                </div>
            </div>

            {/* Modal de Informação sobre NCM por IA */}
            {isInfoModalOpen && (
                <div 
                    role="dialog" 
                    aria-modal="true" 
                    aria-labelledby="fiscal-info-title"
                    className="fixed inset-0 z-[300] flex items-center justify-center p-4 animate-fade-in"
                >
                    <button 
                        type="button" 
                        aria-label="Fechar informações fiscais" 
                        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm cursor-default border-0 p-0 m-0 w-full h-full" 
                        onClick={() => setIsInfoModalOpen(false)} 
                    />
                    <div className="relative bg-white dark:bg-slate-900 w-full max-w-md rounded-3xl p-6 shadow-2xl border border-slate-100 dark:border-slate-800 space-y-4 animate-scale-up" onClick={e => e.stopPropagation()}>
                        <div className="flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-3">
                            <div className="flex items-center gap-2.5">
                                <div className="p-2 bg-amber-50 dark:bg-amber-900/20 text-amber-500 rounded-xl">
                                    <i className="bi bi-stars text-base" />
                                </div>
                                <h3 id="fiscal-info-title" className="text-sm font-black text-slate-800 dark:text-slate-100">
                                    Classificação Fiscal por IA
                                </h3>
                            </div>
                            <button type="button" onClick={() => setIsInfoModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">
                                <i className="bi bi-x-lg text-sm" />
                            </button>
                        </div>
                        <p className="text-xs text-slate-600 dark:text-slate-300 font-medium leading-relaxed">
                            A IA pode sugerir um NCM com base no <strong className="text-slate-800 dark:text-slate-100">título</strong>, na <strong className="text-slate-800 dark:text-slate-100">descrição</strong> e na <strong className="text-slate-800 dark:text-slate-100">categoria</strong>. A sugestão não altera o cadastro até você revisar e confirmar.
                        </p>
                        <p className="text-xs text-slate-600 dark:text-slate-300 font-medium leading-relaxed">
                            Se o material não estiver informado, a IA pode usar MDF/MDP/madeira como hipótese inicial. Essa hipótese será destacada e exigirá confirmação; ela não garante a classificação fiscal correta.
                        </p>
                        <div className="pt-2 flex justify-end">
                            <button
                                type="button"
                                onClick={() => setIsInfoModalOpen(false)}
                                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-xl transition-all shadow-md active:scale-95"
                            >
                                Entendi
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProductFiscalTab;

import React from 'react';
import { Product } from '@/pages/types/product.type';
import { toTitleCase } from '@/pages/utils/textUtils';
import { useProductOpportunities } from '../../hooks/useProductOpportunities';
import {
    filterProductSelectableCategories,
    getProductCategoryRootNames,
    searchProductCategories,
    type ProductCategoryOption,
} from './productCategoryEnvironment';
import { matchCategoryByRules } from '@/pages/utils/categoryResolutionService';

interface ProductGeneralTabProps {
    readonly onOpenCategorySearch: () => void;
    readonly isService: boolean;
    readonly formData: Partial<Product>;
    readonly setFormData: React.Dispatch<React.SetStateAction<Partial<Product>>>;
    readonly availableCategories: readonly ProductCategoryOption[];
    readonly validationErrors?: Record<string, boolean>;
    readonly setValidationErrors?: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
    readonly isGeneratingCategory?: boolean;
}

const ProductGeneralTab: React.FC<ProductGeneralTabProps> = ({
    onOpenCategorySearch,
    isService,
    formData,
    setFormData,
    availableCategories,
    validationErrors = {},
    setValidationErrors,
    isGeneratingCategory = false
}) => {
    const { opportunities } = useProductOpportunities();

    const [diferenciarTitulo, setDiferenciarTitulo] = React.useState<boolean>(
        Boolean(formData.title && formData.title !== formData.name) || Boolean(formData.marketplaceTitle && formData.marketplaceTitle !== formData.name)
    );

    const [categorySearch, setCategorySearch] = React.useState<string>('');

    const selectableCategories = React.useMemo(
        () => filterProductSelectableCategories([...availableCategories]),
        [availableCategories]
    );

    const selectedCategories = React.useMemo(
        () => selectableCategories.filter(cat => (formData.categoryIds || []).includes(cat.id)),
        [selectableCategories, formData.categoryIds]
    );

    const suggestedCategories = React.useMemo(
        () => searchProductCategories(selectableCategories, [...availableCategories], categorySearch),
        [selectableCategories, availableCategories, categorySearch]
    );

    const handleToggleCategory = React.useCallback((catId: string, isChecked: boolean) => {
        if (isChecked && setValidationErrors) {
            setValidationErrors(prev => {
                const next = { ...prev };
                delete next.categoryIds;
                return next;
            });
        }
        setFormData(prev => {
            const ids = prev.categoryIds || [];
            const nextIds = isChecked
                ? [...ids, catId]
                : ids.filter(id => id !== catId);

            const next = { ...prev, categoryIds: nextIds };
            const allEnvs = getProductCategoryRootNames(nextIds, [...availableCategories]);
            let detectedEnv = prev.environment;
            if (!detectedEnv || !allEnvs.includes(detectedEnv)) {
                detectedEnv = allEnvs[0] || '';
            }
            next.environment = detectedEnv;
            next.availableEnvironments = allEnvs;
            return next;
        });
    }, [availableCategories, setFormData, setValidationErrors]);

    React.useEffect(() => {
        if (formData.hasVariations && formData.variations?.length) {
            const colorsSet = new Set<string>();
            formData.variations.forEach(v => {
                v.attributes?.forEach(attr => {
                    const attrName = attr.name?.toUpperCase() || '';
                    if (attrName === 'COR' && attr.value) {
                        colorsSet.add(attr.value.toUpperCase());
                    }
                });
            });

            const detectedColors = Array.from(colorsSet).join(' / ');
            if (detectedColors && detectedColors !== formData.colors) {
                setFormData(prev => ({ ...prev, colors: detectedColors, noColors: false }));
            }
        }
    }, [formData.variations, formData.hasVariations]);

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
            {/* Title Section (Agrupados na mesma linha em 2 colunas) */}
            <div className="md:col-span-2 grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Nome do Produto (ERP) */}
                <div id="field-product-name" className="flex flex-col gap-1.5 transition-all p-2 rounded-2xl">
                    <div className="flex items-center justify-between h-6">
                        <label className={`text-[10px] uppercase font-black tracking-widest flex items-center gap-1.5 ${validationErrors?.name ? 'text-red-500 dark:text-red-400' : 'text-slate-400 dark:text-slate-500'}`}>
                            <span>Nome</span>
                            <span className="text-red-500 ml-0.5">*</span>
                        </label>
                        <button
                            type="button"
                            onClick={() => {
                                const newValue = !diferenciarTitulo;
                                setDiferenciarTitulo(newValue);
                                if (!newValue) {
                                    setFormData(prev => ({
                                        ...prev,
                                        title: prev.name,
                                        marketplaceTitle: prev.name
                                    }));
                                }
                            }}
                            className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-colors ${
                                diferenciarTitulo 
                                    ? 'bg-purple-100 text-purple-700 dark:bg-purple-950/40 dark:text-purple-300' 
                                    : 'bg-slate-100 text-slate-500 dark:bg-slate-800 hover:bg-slate-200'
                            }`}
                        >
                            {diferenciarTitulo ? 'Usando Título Diferente' : 'Diferenciar Título no Catálogo'}
                        </button>
                    </div>
                    <input
                        value={formData.name || ''}
                        onChange={(e) => {
                            const val = e.target.value;
                            setFormData(prev => ({ 
                                ...prev, 
                                name: val,
                                ...(!diferenciarTitulo ? { title: val, marketplaceTitle: val } : {})
                            }));
                        }}
                        onBlur={() => {
                            if (formData.name) {
                                const formatted = toTitleCase(formData.name);
                                if (formatted !== formData.name) {
                                    setFormData(prev => ({
                                        ...prev,
                                        name: formatted,
                                        ...(!diferenciarTitulo ? { title: formatted, marketplaceTitle: formatted } : {})
                                    }));
                                }
                                
                                // Auto-select category if none is selected
                                if (!formData.categoryIds || formData.categoryIds.length === 0) {
                                    const matchedCategory = matchCategoryByRules(formData.name, availableCategories as any);
                                    if (matchedCategory) {
                                        setFormData(prev => {
                                            if (prev.categoryIds?.includes(matchedCategory.id)) return prev;
                                            return { ...prev, categoryIds: [matchedCategory.id] };
                                        });
                                        if (setValidationErrors) {
                                            setValidationErrors(prev => {
                                                const next = { ...prev };
                                                delete next.categoryIds;
                                                return next;
                                            });
                                        }
                                    }
                                }
                            }
                            if ((formData.name || '').trim() && setValidationErrors) {
                                setValidationErrors(prev => {
                                    const next = { ...prev };
                                    delete next.name;
                                    return next;
                                });
                            }
                        }}
                        className={`w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 outline-none text-xs font-bold transition-all font-mono ${
                            validationErrors?.name 
                                ? 'border-red-500 text-red-600 focus:border-red-600' 
                                : 'border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-100 focus:border-blue-600 dark:focus:border-blue-400'
                        }`}
                        placeholder="Digite o nome interno do produto (ex: SOFA 3 LUG)..."
                    />
                </div>

                {/* Catalog / Ecommerce Title Section (Exibido apenas se diferenciarTitulo for true) */}
                {diferenciarTitulo ? (
                    <div id="field-marketplace-title" className="flex flex-col gap-1.5 transition-all p-2 rounded-2xl animate-in slide-in-from-right-2 duration-200">
                        <label className="text-[10px] uppercase font-black text-slate-400 dark:text-slate-500 tracking-widest flex items-center gap-1.5 h-6">
                            <span>Título no Catálogo</span>
                        </label>
                        <input
                            value={formData.title || formData.marketplaceTitle || ''}
                            onChange={(e) => {
                                const val = e.target.value;
                                setFormData(prev => ({ 
                                    ...prev, 
                                    title: val, 
                                    marketplaceTitle: val 
                                }));
                            }}
                            onBlur={() => {
                                const currentVal = formData.title || formData.marketplaceTitle || '';
                                if (currentVal) {
                                    const formatted = toTitleCase(currentVal);
                                    if (formatted !== currentVal) {
                                        setFormData(prev => ({
                                            ...prev,
                                            title: formatted,
                                            marketplaceTitle: formatted
                                        }));
                                    }
                                }
                            }}
                            className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold text-slate-800 dark:text-slate-100 focus:border-blue-600 dark:focus:border-blue-400 transition-all font-mono"
                            placeholder="Digite o título no catálogo..."
                        />
                    </div>
                ) : null}
            </div>

            {/* Selection Row */}
            {!isService && (
                <div id="field-product-categories" className="md:col-span-2 flex flex-col gap-3 transition-all p-2 rounded-2xl">
                    <div className="flex flex-col gap-2 w-full">
                        <div className="flex items-center justify-between h-6">
                            <div className="flex items-center gap-2">
                                <label
                                    htmlFor="input-search-product-categories"
                                    className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 ${validationErrors?.categoryIds ? 'text-red-500 dark:text-red-400' : 'text-slate-400 dark:text-slate-500'}`}
                                >
                                    <span>Categoria(s)</span>
                                    <span className="text-red-500 ml-0.5">*</span>
                                </label>
                                <button
                                    type="button"
                                    onClick={() => {
                                        const newWindow = window.open('/registrations/product-categories', '_blank');
                                        if (newWindow) {
                                            newWindow.blur();
                                            window.focus();
                                        }
                                    }}
                                    className="inline-flex items-center gap-1 text-[10px] font-black uppercase tracking-wider text-slate-400 hover:text-blue-600 dark:hover:text-blue-400 transition-colors p-0.5 rounded"
                                    title="Gerenciar Categorias"
                                    aria-label="Gerenciar Categorias de Produtos"
                                >
                                    <span>GERENCIAR</span>
                                    <i className="bi bi-gear-fill text-xs" />
                                </button>
                                {isGeneratingCategory && (
                                    <span className="inline-flex items-center gap-1 text-[9px] font-black bg-amber-100 text-amber-800 dark:bg-amber-955/80 dark:text-amber-300 px-2 py-0.5 rounded-full border border-amber-300/80 dark:border-amber-700/80 animate-pulse select-none">
                                        <i className="bi bi-stars text-amber-500 animate-spin text-[10px]" />
                                        <span>IA analisando categoria...</span>
                                    </span>
                                )}
                            </div>

                            {selectedCategories.length > 0 && (
                                <span className="text-[10px] font-bold text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-950/40 px-2 py-0.5 rounded-full">
                                    {selectedCategories.length} selecionada{selectedCategories.length > 1 ? 's' : ''}
                                </span>
                            )}
                        </div>

                        <div className={`flex flex-wrap items-center gap-1.5 w-full px-1 py-2 border-b-2 transition-colors ${
                            validationErrors?.categoryIds && selectedCategories.length === 0
                                ? 'border-red-500 focus-within:border-red-600'
                                : 'border-slate-200 dark:border-slate-800 focus-within:border-blue-600 dark:focus-within:border-blue-400'
                        }`}>
                        {/* Categorias selecionadas dentro do campo de pesquisa */}
                        {selectedCategories.length > 0 && (
                            <div className="contents">
                                {selectedCategories.map((cat) => {
                                    const parentNames = (cat.parents || [])
                                        .map((pid: string) => availableCategories.find(item => item.id === pid)?.name)
                                        .filter(Boolean)
                                        .join(', ');

                                    return (
                                        <span
                                            key={cat.id}
                                            className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-100 border border-slate-200 dark:border-slate-700 shadow-sm"
                                        >
                                            <i className="bi bi-check2 text-blue-600 dark:text-blue-400 font-bold" />
                                            <span>{cat.name}</span>
                                            {parentNames && (
                                                <span className="text-[10px] font-normal text-slate-400 dark:text-slate-500">
                                                    ({parentNames})
                                                </span>
                                            )}
                                            <button
                                                type="button"
                                                onClick={() => handleToggleCategory(cat.id, false)}
                                                className="ml-1 text-slate-400 hover:text-red-500 transition-colors p-0.5 rounded focus:outline-none"
                                                title={`Remover ${cat.name}`}
                                                aria-label={`Remover categoria ${cat.name}`}
                                            >
                                                <i className="bi bi-x text-sm leading-none" />
                                            </button>
                                        </span>
                                    );
                                })}
                            </div>
                        )}

                        {/* Campo de Pesquisa de Categorias */}
                        <div className="relative flex items-center flex-1 min-w-[180px]">
                            <i className="bi bi-search absolute left-3 text-slate-400 text-xs pointer-events-none" />
                            <input
                                id="input-search-product-categories"
                                type="text"
                                value={categorySearch}
                                onChange={(e) => setCategorySearch(e.target.value)}
                                placeholder="Pesquisar categorias..."
                                aria-label="Pesquisar categorias"
                                className={`w-full pl-8 pr-8 py-0.5 text-xs font-semibold rounded-none bg-transparent border-0 outline-none focus:ring-0 transition-all ${
                                    validationErrors?.categoryIds && selectedCategories.length === 0
                                        ? 'text-red-600'
                                        : 'text-slate-800 dark:text-slate-100'
                                }`}
                            />
                            {categorySearch && (
                                <button
                                    type="button"
                                    onClick={() => setCategorySearch('')}
                                    className="absolute right-2.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-0.5 rounded transition-colors"
                                    title="Limpar busca"
                                    aria-label="Limpar termo de busca"
                                >
                                    <i className="bi bi-x-circle-fill text-xs" />
                                </button>
                            )}
                        </div>

                        </div>

                        {/* Caixa de Sugestões e Resultados */}
                        {categorySearch.trim().length >= 2 && (
                        <div className={`overflow-y-auto custom-scrollbar w-full border rounded-xl p-2 transition-all ${
                            isGeneratingCategory
                                ? 'border-amber-400 bg-amber-50/20 dark:bg-amber-950/20 ring-2 ring-amber-400/40 animate-pulse'
                                : validationErrors?.categoryIds && selectedCategories.length === 0
                                    ? 'border-red-500/80 bg-red-50/10 dark:bg-red-950/5'
                                    : 'border-slate-200/80 dark:border-slate-800 bg-slate-50/30 dark:bg-slate-900/30'
                        }`}>
                            {suggestedCategories.length === 0 ? (
                                <div className="py-5 px-3 text-center text-xs text-slate-400 dark:text-slate-500 flex flex-col items-center justify-center gap-1">
                                    <i className="bi bi-inbox text-base opacity-40 mb-0.5" />
                                    <span>Nenhuma categoria encontrada para &ldquo;<strong className="text-slate-600 dark:text-slate-300">{categorySearch}</strong>&rdquo;.</span>
                                </div>
                            ) : (
                                <div className="max-h-60 overflow-y-auto space-y-1 custom-scrollbar">
                                    <div className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500 px-2 py-1">
                                        Sugestões encontradas ({suggestedCategories.length}):
                                    </div>
                                    {suggestedCategories.map((cat) => {
                                        const isChecked = (formData.categoryIds || []).includes(cat.id);
                                        const parentNames = (cat.parents || [])
                                            .map((pid: string) => availableCategories.find(item => item.id === pid)?.name)
                                            .filter(Boolean)
                                            .join(', ');

                                        return (
                                            <label
                                                key={cat.id}
                                                className={`flex items-start gap-3 p-2 rounded-lg transition-colors cursor-pointer select-none ${
                                                    isChecked
                                                        ? 'bg-blue-50/70 dark:bg-blue-950/30 border border-blue-200/60 dark:border-blue-900/50'
                                                        : 'hover:bg-slate-100/70 dark:hover:bg-slate-800/60 border border-transparent'
                                                }`}
                                            >
                                                <input
                                                    type="checkbox"
                                                    checked={isChecked}
                                                    onChange={(e) => {
                                                        handleToggleCategory(cat.id, e.target.checked);
                                                        setCategorySearch('');
                                                    }}
                                                    className="mt-1 h-4 w-4 rounded border-slate-350 text-blue-600 focus:ring-blue-500 cursor-pointer"
                                                />
                                                <div className="flex flex-col flex-1 min-w-0">
                                                    <span className={`text-xs font-bold ${
                                                        isChecked ? 'text-blue-700 dark:text-blue-300' : 'text-slate-800 dark:text-slate-200'
                                                    }`}>
                                                        {cat.name}
                                                    </span>
                                                    {parentNames && (
                                                        <span className="text-[10px] text-slate-400 dark:text-slate-500">
                                                            Ambientes: {parentNames}
                                                        </span>
                                                    )}
                                                </div>
                                            </label>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                        )}
                    </div>
                </div>
            )}

            {/* Oportunidade */}
            <div className="md:col-span-2">
                <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] uppercase font-black text-slate-400 dark:text-slate-500 tracking-widest flex items-center gap-1.5 h-6">
                        <span>Oportunidade</span>
                    </label>
                    <select
                        value={formData.opportunityId || ''}
                        onChange={(e) => setFormData(prev => ({ ...prev, opportunityId: e.target.value || null }))}
                        className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold text-slate-800 dark:text-slate-100 focus:border-blue-600 dark:focus:border-blue-400 transition-all"
                    >
                        <option value="">Nenhuma (Produto Normal)</option>
                        {opportunities.map((opp) => (
                            <option key={opp.id} value={opp.id}>
                                {opp.name}
                            </option>
                        ))}
                    </select>
                </div>
            </div>

            {/* Observations */}
            <div className="md:col-span-2">
                <div className="flex flex-col gap-2.5">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 flex items-center gap-1.5 h-6">
                        <span>Observações Internas</span>
                    </label>
                    <textarea
                        value={formData.observations || ''}
                        onChange={(e) => setFormData({ ...formData, observations: e.target.value })}
                        placeholder="Digite notas internas sobre este produto, processos ou detalhes específicos..."
                        className="w-full h-24 px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold dark:text-slate-200 resize-none focus:border-blue-600 dark:focus:border-blue-400 transition-all"
                    />
                </div>
            </div>
        </div>
    );
};

export default ProductGeneralTab;

import React from 'react';
import type { Product } from '@/pages/types/product.type';
import type { Person } from '../../../../types/person.type';
import { ProductSupplierField } from './ProductSupplierField';
import { ProductPricingFields } from './ProductPricingFields';
import { syncVariationsWithParent } from '../../utils/variationParentSync';

interface ProductInventoryTabProps {
    readonly formData: Partial<Product>;
    readonly setFormData: React.Dispatch<React.SetStateAction<Partial<Product>>>;
    readonly suppliers: readonly Person[];
    readonly handleSuggestPrices?: () => void;
    readonly onSuggestPrices?: () => void;
    readonly isSuggestingPrices?: boolean;
    readonly suggestPricesResults?: { readonly low: number; readonly medium: number; readonly high: number } | null;
    readonly discountPercent: string;
    readonly setDiscountPercent?: React.Dispatch<React.SetStateAction<string>>;
    readonly discountFixed: string;
    readonly setDiscountFixed?: React.Dispatch<React.SetStateAction<string>>;
    readonly handlePriceChange?: (newPrice: string) => void;
    readonly onPriceChange?: (newPrice: string) => void;
    readonly handleDiscountPercentChange?: (valStr: string) => void;
    readonly onDiscountPercentChange?: (valStr: string) => void;
    readonly handleDiscountFixedChange?: (valStr: string) => void;
    readonly onDiscountFixedChange?: (valStr: string) => void;
    readonly handlePromoPriceFieldChange?: (valStr: string) => void;
    readonly onPromoPriceChange?: (valStr: string) => void;
    readonly validationErrors?: Record<string, boolean>;
    readonly setValidationErrors?: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
}

const ProductInventoryTab: React.FC<ProductInventoryTabProps> = ({
    formData,
    setFormData,
    suppliers,
    discountPercent,
    discountFixed,
    handlePriceChange,
    onPriceChange,
    handleDiscountPercentChange,
    onDiscountPercentChange,
    handleDiscountFixedChange,
    onDiscountFixedChange,
    handlePromoPriceFieldChange,
    onPromoPriceChange,
    validationErrors = {},
    setValidationErrors
}) => {
    const finalOnPriceChange = onPriceChange || handlePriceChange || (() => {});
    const finalOnDiscountPercentChange = onDiscountPercentChange || handleDiscountPercentChange || (() => {});
    const finalOnDiscountFixedChange = onDiscountFixedChange || handleDiscountFixedChange || (() => {});
    const finalOnPromoPriceChange = onPromoPriceChange || handlePromoPriceFieldChange || (() => {});
    const updateCost = (fields: Partial<Product>) => {
        if (fields.mainSupplierId && setValidationErrors) {
            setValidationErrors(previous => {
                const next = { ...previous };
                delete next.mainSupplierId;
                return next;
            });
        }
        setFormData(prev => {
            const next: Partial<Product> = { ...prev, ...fields };
            const cost = Number(next.costPrice) || 0;
            const ipi = Number(next.ipiPercent) || 0;
            const freight = Number(next.freightCost) || 0;
            const freightType = next.freightType || 'fixed';

            let finalCost = cost + (cost * (ipi / 100));
            if (freightType === 'fixed') {
                finalCost += freight;
            } else {
                finalCost += cost * (freight / 100);
            }

            next.finalPurchasePrice = Number(finalCost.toFixed(2));

            // Propagar campos de custo para variações herdando do pai
            if (next.variations?.length) {
                next.variations = syncVariationsWithParent(next.variations, {
                    costPrice: next.costPrice,
                    ipiPercent: next.ipiPercent,
                    freightCost: next.freightCost,
                    freightType: next.freightType as 'fixed' | 'percentage' | 'none' | undefined,
                });
            }

            return next;
        });
    };

    const minStockValue = (formData.minStock === null || formData.minStock === undefined || Number.isNaN(Number(formData.minStock)))
        ? ''
        : formData.minStock;

    return (
        <div className="flex flex-col gap-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
            {/* Fornecedor e Estoque Mínimo - Sempre Visíveis */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <ProductSupplierField
                    formData={formData}
                    suppliers={suppliers}
                    onChange={updateCost}
                    hasError={validationErrors.mainSupplierId}
                />

                {!formData.hasVariations && (
                    <div className="flex flex-col gap-2 p-2 rounded-2xl">
                        <label htmlFor="product-min-stock-input" className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-1.5 h-6">
                            <span>Estoque Mínimo</span>
                        </label>
                        <input
                            id="product-min-stock-input"
                            type="number"
                            min="0"
                            aria-label="Estoque mínimo do produto"
                            value={minStockValue}
                            onChange={(e) => {
                                const parsed = parseInt(e.target.value, 10);
                                setFormData(prev => ({ ...prev, minStock: Number.isNaN(parsed) ? 0 : parsed }));
                            }}
                            className="w-full px-4 py-2.5 bg-white dark:bg-slate-955 border border-slate-200 dark:border-slate-800 rounded-xl outline-none text-xs font-black text-amber-600 dark:text-amber-500 focus:ring-2 focus:ring-amber-500/20"
                            placeholder="0"
                        />
                    </div>
                )}
            </div>

            <ProductPricingFields
                formData={formData}
                discountPercent={discountPercent}
                discountFixed={discountFixed}
                onPriceChange={finalOnPriceChange}
                onDiscountPercentChange={finalOnDiscountPercentChange}
                onDiscountFixedChange={finalOnDiscountFixedChange}
                onPromoPriceChange={finalOnPromoPriceChange}
                validationErrors={validationErrors}
                setValidationErrors={setValidationErrors}
            />
        </div>
    );
};

export default ProductInventoryTab;

import type React from 'react';
import type { Product } from '@/pages/types/product.type';
import CurrencyInput from '@/components/CurrencyInput';

interface ProductPricingFieldsProps {
    readonly formData: Partial<Product>;
    readonly discountPercent: string;
    readonly discountFixed: string;
    readonly onPriceChange?: (value: string) => void;
    readonly onDiscountPercentChange?: (value: string) => void;
    readonly onDiscountFixedChange?: (value: string) => void;
    readonly onPromoPriceChange?: (value: string) => void;
    readonly validationErrors: Record<string, boolean>;
    readonly setValidationErrors?: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
}

export function ProductPricingFields({
    formData,
    discountPercent,
    discountFixed,
    onPriceChange = () => {},
    onDiscountPercentChange = () => {},
    onDiscountFixedChange = () => {},
    onPromoPriceChange = () => {},
    validationErrors,
    setValidationErrors,
}: ProductPricingFieldsProps) {
    const handleBlurPrice = () => {
        const parsed = Number(formData.unitPrice);
        if (formData.unitPrice && !Number.isNaN(parsed) && parsed > 0 && setValidationErrors) {
            setValidationErrors(previous => {
                const next = { ...previous };
                delete next.unitPrice;
                return next;
            });
        }
    };

    return (
        <div className="border-t border-slate-150 dark:border-slate-800/80 pt-6">
            <h5 className="text-[10px] font-black uppercase tracking-widest text-blue-600 mb-2 flex items-center gap-1.5">
                <i className="bi bi-tag-fill" aria-hidden="true" /> Precificação e Descontos {formData.hasVariations ? '(Produto Pai)' : ''}
            </h5>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
                <div id="field-unit-price" className="flex flex-col gap-2 transition-all p-2 rounded-2xl">
                    <label
                        htmlFor="product-unit-price-input"
                        className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-1.5 h-6 ${validationErrors.unitPrice ? 'text-red-500 dark:text-red-400' : 'text-slate-400'}`}
                    >
                        <span>Preço de Venda</span><span className="text-red-500 ml-0.5" aria-hidden="true">*</span>
                    </label>
                    <CurrencyInput
                        id="product-unit-price-input"
                        aria-label="Preço de venda do produto"
                        aria-invalid={!!validationErrors.unitPrice}
                        value={formData.unitPrice}
                        onChange={(value) => onPriceChange(String(value))}
                        onBlur={handleBlurPrice}
                        className={`w-full text-left px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 outline-none text-xs font-bold transition-all ${validationErrors.unitPrice ? 'border-red-500 text-red-600 focus:border-red-600' : 'border-slate-200 dark:border-slate-800 text-blue-600 focus:border-blue-600 dark:focus:border-blue-400'}`}
                    />
                </div>
                <div className="flex flex-col gap-2 p-2 rounded-2xl">
                    <label htmlFor="product-discount-percent-input" className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-1.5 h-6">
                        <span>Desconto (%)</span>
                    </label>
                    <div className="relative">
                        <input
                            id="product-discount-percent-input"
                            type="number"
                            min="0"
                            max="100"
                            placeholder="0"
                            aria-label="Percentual de desconto"
                            value={discountPercent}
                            onChange={(event) => onDiscountPercentChange(event.target.value)}
                            className="w-full pl-1 pr-6 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold text-emerald-600 focus:border-emerald-600"
                        />
                        <span className="absolute right-1 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400 pointer-events-none" aria-hidden="true">%</span>
                    </div>
                </div>
                <div className="flex flex-col gap-2 p-2 rounded-2xl">
                    <label htmlFor="product-discount-fixed-input" className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-1.5 h-6">
                        <span>Desconto (R$)</span>
                    </label>
                    <CurrencyInput
                        id="product-discount-fixed-input"
                        aria-label="Valor fixo de desconto em reais"
                        value={discountFixed}
                        onChange={(value) => onDiscountFixedChange(String(value))}
                        className="w-full text-left px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold text-emerald-600 focus:border-emerald-600"
                    />
                </div>
                <div className="flex flex-col gap-2 p-2 rounded-2xl">
                    <label htmlFor="product-promo-price-input" className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-1.5 h-6">
                        <span>Preço Promocional Final</span>
                    </label>
                    <CurrencyInput
                        id="product-promo-price-input"
                        placeholder="Sem desconto"
                        aria-label="Preço promocional com desconto aplicado"
                        value={formData.promoPrice}
                        onChange={(value) => onPromoPriceChange(String(value))}
                        className="w-full text-left px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-amber-200 dark:border-amber-800 outline-none text-xs font-black text-amber-600 dark:text-amber-500 focus:border-amber-600"
                    />
                </div>
            </div>
        </div>
    );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import type { Product } from '@/pages/types/product.type';
import type { Person } from '../../../../types/person.type';
import DropdownPortal from '@/components/shared/DropdownPortal';
import PersonFormModal from '../../../Registrations/shared/modals/PersonFormModal';

interface ProductSupplierFieldProps {
    readonly formData: Partial<Product>;
    readonly suppliers: readonly Person[];
    readonly onChange: (fields: Partial<Product>) => void;
    readonly hasError?: boolean;
}

const MAX_SUPPLIERS = 3;

export function ProductSupplierField({ formData, suppliers, onChange, hasError = false }: ProductSupplierFieldProps) {
    const [search, setSearch] = useState('');
    const [isOpen, setIsOpen] = useState(false);
    const [isPersonFormOpen, setIsPersonFormOpen] = useState(false);
    const [extraSuppliers, setExtraSuppliers] = useState<Person[]>([]);
    const anchorRef = useRef<HTMLDivElement>(null);

    // Fechar dropdown ao pressionar Escape
    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                setIsOpen(false);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen]);

    const allSuppliers = useMemo(() => {
        const map = new Map<string, Person>();
        (suppliers || []).forEach(s => { if (s && s.id) map.set(String(s.id), s); });
        extraSuppliers.forEach(s => { if (s && s.id) map.set(String(s.id), s); });
        return Array.from(map.values());
    }, [suppliers, extraSuppliers]);

    const selectedIds = useMemo(() => {
        const raw = formData.supplierIds?.length 
            ? formData.supplierIds 
            : [formData.mainSupplierId || formData.supplierId];
        return Array.from(new Set(raw.filter(Boolean).map(String)));
    }, [formData.supplierIds, formData.mainSupplierId, formData.supplierId]);

    const visibleSuppliers = useMemo(() => {
        const query = search.trim().toLowerCase();
        if (query.length < 2) return [];
        return allSuppliers.filter((supplier) => {
            const sid = String(supplier.id || '');
            if (selectedIds.includes(sid)) return false;
            const name = (supplier.fullName || supplier.socialName || supplier.nickname || supplier.tradeName || '').toLowerCase();
            return name.includes(query);
        });
    }, [allSuppliers, selectedIds, search]);

    const addSupplier = (supplier: Person) => {
        if (!supplier || !supplier.id) return;
        const sid = String(supplier.id);
        if (selectedIds.includes(sid) || selectedIds.length >= MAX_SUPPLIERS) return;

        setExtraSuppliers(prev => {
            if (prev.some(s => String(s.id) === sid)) return prev;
            return [...prev, supplier];
        });

        const supplierIds = [...selectedIds, sid];
        onChange({
            supplierIds,
            mainSupplierId: supplierIds[0],
            supplierId: supplierIds[0],
            ipiPercent: supplier.defaultIpiPercent ?? formData.ipiPercent,
            freightCost: supplier.defaultFreightCost ?? formData.freightCost,
            freightType: supplier.defaultFreightType || formData.freightType
        });

        setSearch('');
        setIsOpen(false);
    };

    const removeSupplier = (supplierId: string) => {
        const sid = String(supplierId);
        const supplierIds = selectedIds.filter((id) => id !== sid);
        onChange({
            supplierIds,
            mainSupplierId: supplierIds[0] || '',
            supplierId: supplierIds[0] || ''
        });
    };

    return (
        <div id="field-main-supplier" className="relative flex flex-col gap-2 rounded-2xl p-2 md:col-span-2" ref={anchorRef}>
            <label className={`flex h-6 items-center justify-between text-[10px] font-black uppercase tracking-widest ${hasError ? 'text-red-500 dark:text-red-400' : 'text-slate-400'}`}>
                <span>Fornecedores <span className="text-red-500" aria-hidden="true">*</span></span>
                <button
                    type="button"
                    onClick={() => setIsPersonFormOpen(true)}
                    className="flex items-center gap-1 text-[9px] font-black uppercase tracking-widest text-blue-600 hover:underline cursor-pointer"
                >
                    <i className="bi bi-plus-lg" aria-hidden="true" /> Novo
                </button>
            </label>

            <div className="flex gap-2">
                <div className="relative flex-1">
                    <i className="bi bi-search absolute left-2 top-1/2 -translate-y-1/2 text-xs text-slate-400 pointer-events-none" aria-hidden="true" />
                    <input
                        type="text"
                        role="combobox"
                        aria-expanded={isOpen && visibleSuppliers.length > 0}
                        aria-autocomplete="list"
                        aria-haspopup="listbox"
                        aria-invalid={hasError}
                        aria-label="Buscar fornecedor por nome ou razão social"
                        value={search}
                        onChange={(event) => {
                            setSearch(event.target.value);
                            setIsOpen(true);
                        }}
                        onFocus={() => setIsOpen(true)}
                        placeholder="Digite 2 ou mais letras para buscar fornecedor..."
                        className={`w-full bg-transparent border-b-2 border-t-0 border-x-0 py-2.5 pl-8 pr-4 text-xs font-bold outline-none transition-all dark:text-slate-200 ${
                            hasError ? 'border-red-500 text-red-600 focus:border-red-600' : 'border-slate-200 focus:border-blue-600 dark:focus:border-blue-400 dark:border-slate-800'
                        }`}
                    />
                </div>
                <button
                    type="button"
                    onClick={() => setIsOpen(prev => !prev)}
                    disabled={selectedIds.length >= MAX_SUPPLIERS}
                    aria-label="Adicionar fornecedor"
                    className="rounded-xl bg-blue-600 px-3 text-xs font-black text-white disabled:opacity-40 hover:bg-blue-700 transition-colors cursor-pointer disabled:cursor-not-allowed"
                    title="Adicionar fornecedor"
                >
                    <i className="bi bi-plus-lg" aria-hidden="true" />
                </button>
            </div>

            {hasError && <span role="alert" className="text-[9px] font-bold text-red-500">Adicione ao menos um fornecedor.</span>}

            <DropdownPortal anchorRef={anchorRef} isOpen={isOpen && visibleSuppliers.length > 0}>
                <div role="listbox" aria-label="Sugestões de fornecedores" className="mt-2 max-h-60 overflow-y-auto rounded-xl border border-slate-100 bg-white shadow-2xl dark:border-slate-800 dark:bg-slate-900">
                    {visibleSuppliers.map((supplier) => {
                        const name = supplier.fullName || supplier.socialName || supplier.nickname || supplier.tradeName || 'Fornecedor sem nome';
                        return (
                            <button
                                key={supplier.id}
                                type="button"
                                role="option"
                                aria-selected="false"
                                onClick={() => addSupplier(supplier)}
                                className="w-full border-b border-slate-50 p-3 text-left text-xs font-black text-slate-800 hover:bg-slate-50 last:border-0 dark:border-slate-800 dark:text-slate-200 dark:hover:bg-slate-800 cursor-pointer"
                            >
                                {name}
                            </button>
                        );
                    })}
                </div>
            </DropdownPortal>

            {selectedIds.length > 0 && (
                <div className="flex flex-wrap gap-2 pt-1" aria-label="Fornecedores vinculados">
                    {selectedIds.map((id) => {
                        const supplier = allSuppliers.find((item) => String(item.id) === String(id));
                        const name = supplier?.fullName || supplier?.socialName || supplier?.nickname || supplier?.tradeName || 'Fornecedor';
                        return (
                            <span
                                key={id}
                                className="flex items-center gap-2 rounded-lg bg-blue-50 px-2.5 py-1.5 text-[10px] font-black text-blue-700 dark:bg-blue-900/20 dark:text-blue-300"
                            >
                                {name}
                                <button
                                    type="button"
                                    onClick={() => removeSupplier(id)}
                                    className="text-blue-500 hover:text-red-500 cursor-pointer"
                                    aria-label={`Remover fornecedor ${name}`}
                                    title="Remover fornecedor"
                                >
                                    <i className="bi bi-x-lg" aria-hidden="true" />
                                </button>
                            </span>
                        );
                    })}
                    <span className="self-center text-[9px] font-bold text-slate-400">{selectedIds.length}/{MAX_SUPPLIERS}</span>
                </div>
            )}

            {isPersonFormOpen && (
                <PersonFormModal
                    isOpen={isPersonFormOpen}
                    onClose={() => setIsPersonFormOpen(false)}
                    onSuccess={(createdPerson) => {
                        if (createdPerson && createdPerson.id) {
                            addSupplier(createdPerson);
                        }
                        setIsPersonFormOpen(false);
                    }}
                    collectionName="suppliers"
                    title="Novo Fornecedor"
                />
            )}
        </div>
    );
}

import React from 'react';
import type { Product } from '@/pages/types/product.type';
import { DragDropContext, Droppable, Draggable, type DropResult } from '@hello-pangea/dnd';
import { toast } from 'react-toastify';
import { toTitleCase } from '@/pages/utils/textUtils';

export type TitlePartId = 'environment' | 'line' | 'brand' | 'complement';

interface ProductTitleTabProps {
    readonly formData: Partial<Product>;
    readonly setFormData: React.Dispatch<React.SetStateAction<Partial<Product>>>;
    readonly productTypes?: readonly { readonly id: string; readonly name: string }[];
}

const DEFAULT_TITLE_ORDER: TitlePartId[] = ['environment', 'line', 'brand', 'complement'];

const ProductTitleTab: React.FC<ProductTitleTabProps> = ({
    formData,
    setFormData,
}) => {
    const titleOrder = (formData.titleOrder as TitlePartId[]) || DEFAULT_TITLE_ORDER;
    
    // Prefixo Fixo: Tipo do Produto
    const typeName = formData.productTypeName || 'TIPO';

    const onDragEnd = (result: DropResult) => {
        if (!result.destination) return;
        const items = Array.from(titleOrder);
        const [reorderedItem] = items.splice(result.source.index, 1);
        items.splice(result.destination.index, 0, reorderedItem);
        setFormData(prev => ({ ...prev, titleOrder: items }));
    };

    const togglePart = (id: TitlePartId) => {
        setFormData(prev => {
            const field = `include${id.charAt(0).toUpperCase() + id.slice(1)}` as keyof Product;
            return { ...prev, [field]: !prev[field] };
        });
    };

    const getPartValue = (id: TitlePartId): string => {
        switch (id) {
            case 'environment': return formData.environment || 'AMBIENTE';
            case 'line': return formData.line || 'LINHA/MODELO';
            case 'brand': return formData.brand || 'MARCA';
            case 'complement': return formData.titleComplement || 'COMPLEMENTO';
            default: return '';
        }
    };

    const getPartOn = (id: TitlePartId): boolean => {
        switch (id) {
            case 'environment': return formData.includeEnvironment ?? true;
            case 'line': return formData.includeLine ?? true;
            case 'brand': return formData.includeBrand ?? true;
            case 'complement': return formData.includeComplement ?? true;
            default: return true;
        }
    };

    const previewTitle = (): string => {
        const parts = [typeName];
        titleOrder.forEach(id => {
            if (getPartOn(id)) {
                const val = getPartValue(id);
                if (val && val !== 'AMBIENTE' && val !== 'LINHA/MODELO' && val !== 'MARCA' && val !== 'COMPLEMENTO') {
                    parts.push(val);
                }
            }
        });
        return toTitleCase(parts.join(' '));
    };

    const applyTitle = () => {
        const title = previewTitle();
        setFormData(prev => ({
            ...prev,
            description: title,
            name: title,
            title,
            marketplaceTitle: title
        }));
        toast.info("Título montado e aplicado!");
    };

    const getPartLabel = (id: TitlePartId): string => {
        switch (id) {
            case 'environment': return 'Ambiente';
            case 'line': return 'Linha/Modelo';
            case 'brand': return 'Marca';
            case 'complement': return 'Complemento';
        }
    };

    return (
        <div className="space-y-10 animate-in fade-in slide-in-from-bottom-2 duration-300">
            {/* Preview Section */}
            <div className="bg-blue-600 p-8 rounded-[3rem] text-white shadow-2xl shadow-blue-500/20">
                <div className="flex items-center justify-between mb-6">
                    <div>
                        <h4 className="text-[10px] font-black uppercase tracking-widest opacity-60">Prévia do Título Dinâmico</h4>
                        <p className="text-[9px] font-bold opacity-40 uppercase tracking-tighter">Este é o nome que aparecerá no catálogo e etiquetas</p>
                    </div>
                    <button 
                        type="button"
                        onClick={applyTitle}
                        className="px-6 py-3 bg-white text-blue-600 rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-lg hover:scale-105 transition-all cursor-pointer active:scale-95"
                    >
                        Fixar como Título do Produto
                    </button>
                </div>
                <div className="bg-blue-700/30 p-8 rounded-[2rem] border border-blue-400/20">
                    <h2 className="text-2xl font-black tracking-tight leading-relaxed break-words">
                        {previewTitle() || "NENHUM COMPONENTE ATIVO"}
                    </h2>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                {/* Fixed Prefix Section */}
                <div className="bg-slate-50 dark:bg-slate-950/20 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-6 flex items-center gap-2">
                        <i className="bi bi-pin-angle-fill text-blue-500" aria-hidden="true" /> Prefixo Fixo
                    </h4>
                    <div className="space-y-4">
                        <div className="flex flex-col gap-2">
                            <label htmlFor="product-type-fixed-prefix" className="text-[10px] font-black uppercase tracking-widest text-slate-500">Tipo de Produto</label>
                            <input 
                                id="product-type-fixed-prefix"
                                disabled
                                value={typeName}
                                className="w-full px-5 py-4 bg-slate-100 dark:bg-slate-900 border border-transparent rounded-2xl text-sm font-black text-slate-400 cursor-not-allowed uppercase"
                            />
                            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter italic">* O prefixo é obrigatório e vem da categoria selecionada.</p>
                        </div>
                    </div>
                </div>

                {/* Reorderable Components Section */}
                <div className="bg-white dark:bg-slate-900/40 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-6 flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            <i className="bi bi-grip-vertical text-blue-500" aria-hidden="true" /> Componentes Reordenáveis
                        </div>
                        <span className="text-[8px] opacity-60">Arraste para mudar a ordem</span>
                    </h4>

                    <DragDropContext onDragEnd={onDragEnd}>
                        <Droppable droppableId="title-parts">
                            {(provided) => (
                                <div {...provided.droppableProps} ref={provided.innerRef} className="space-y-3">
                                    {titleOrder.map((id, index) => {
                                        const isOn = getPartOn(id);
                                        const val = getPartValue(id);
                                        return (
                                            <Draggable key={id} draggableId={id} index={index}>
                                                {(draggableProvided, snapshot) => (
                                                    <div
                                                        ref={draggableProvided.innerRef}
                                                        {...draggableProvided.draggableProps}
                                                        {...draggableProvided.dragHandleProps}
                                                        className={`flex items-center justify-between p-4 rounded-2xl border transition-all ${snapshot.isDragging ? 'bg-blue-50 border-blue-200 shadow-xl' : 'bg-slate-50 dark:bg-slate-800 border-slate-100 dark:border-slate-700 hover:border-slate-200'}`}
                                                    >
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-8 h-8 rounded-lg bg-white dark:bg-slate-900 flex items-center justify-center text-slate-300 pointer-events-none" aria-hidden="true">
                                                                <i className="bi bi-grip-vertical" />
                                                            </div>
                                                            <div>
                                                                <p className="text-[9px] font-black uppercase tracking-widest text-slate-400">{getPartLabel(id)}</p>
                                                                <p className={`text-sm font-black ${isOn ? 'text-slate-700 dark:text-slate-200' : 'text-slate-300'}`}>{val}</p>
                                                            </div>
                                                        </div>
                                                        <button 
                                                            type="button"
                                                            role="switch"
                                                            aria-checked={isOn}
                                                            aria-label={`Incluir ${getPartLabel(id)} no título`}
                                                            onClick={(e) => { e.stopPropagation(); togglePart(id); }}
                                                            className={`w-10 h-5 rounded-full p-1 cursor-pointer transition-colors ${isOn ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-700'}`}
                                                        >
                                                            <div className={`w-3 h-3 bg-white rounded-full transition-transform ${isOn ? 'translate-x-5' : 'translate-x-0'}`} />
                                                        </button>
                                                    </div>
                                                )}
                                            </Draggable>
                                        );
                                    })}
                                    {provided.placeholder}
                                </div>
                            )}
                        </Droppable>
                    </DragDropContext>
                </div>
            </div>

            {/* Title Complement Input */}
            <div className="bg-slate-50 dark:bg-slate-950 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800">
                <div className="flex flex-col gap-4">
                    <label htmlFor="title-complement-input" className="text-[10px] font-black uppercase tracking-widest text-slate-400">Complemento do Título (Manual)</label>
                    <input 
                        id="title-complement-input"
                        value={formData.titleComplement || ''}
                        onChange={(e) => setFormData(prev => ({ ...prev, titleComplement: e.target.value }))}
                        onBlur={(e) => {
                            if (e.target.value) {
                                setFormData(prev => ({ ...prev, titleComplement: toTitleCase(e.target.value) }));
                            }
                        }}
                        placeholder="Ex: 2 Gavetas, Madeira Maciça..."
                        className="w-full px-6 py-4 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none font-bold text-sm shadow-sm"
                    />
                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Use este campo para adicionar informações que não estão nas categorias ou modelo.</p>
                </div>
            </div>
        </div>
    );
};

export default ProductTitleTab;

import React, { useEffect, useRef, useState } from 'react';
import { compressImageToFile } from '@/pages/utils/imageUtils';
import { toast } from 'react-toastify';
import { buildImageFetchCandidates } from '@/pages/utils/imageFetchCandidates';
import {
    createCenteredSquareSelection,
    moveSquareSelection,
    resizeSquareSelection,
    type CropCorner,
    type SquareSelection,
} from './squareCropSelection';

type Drag = { mode: 'move'; x: number; y: number; selection: SquareSelection } | { mode: 'resize'; x: number; corner: CropCorner; selection: SquareSelection };

interface SquareImageCropperProps {
    imageUrl: string;
    onCancel: () => void;
    onConfirm: (file: File) => void;
}

export function SquareImageCropper({ imageUrl, onCancel, onConfirm }: SquareImageCropperProps) {
    const [selection, setSelection] = useState<SquareSelection | null>(null);
    const [imageSrc, setImageSrc] = useState<string>('');
    const [loading, setLoading] = useState<boolean>(true);
    const [loadError, setLoadError] = useState<boolean>(false);
    const [isApplying, setIsApplying] = useState<boolean>(false);

    const [paddingPercent, setPaddingPercent] = useState<number>(0);

    const imageRef = useRef<HTMLImageElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const dragRef = useRef<Drag | null>(null);

    useEffect(() => {
        setSelection(null);
        setLoadError(false);
        setLoading(true);

        let active = true;
        let objectUrl = '';

        async function prepareImage() {
            if (!imageUrl) {
                setLoading(false);
                setLoadError(true);
                return;
            }

            // Se já for data URL ou blob URL local, usa diretamente
            if (imageUrl.startsWith('data:') || imageUrl.startsWith('blob:')) {
                setImageSrc(imageUrl);
                setLoading(false);
                return;
            }

            const urlsToTry = buildImageFetchCandidates(imageUrl, true);

            for (const url of urlsToTry) {
                try {
                    const res = await fetch(url);
                    if (res.ok) {
                        const blob = await res.blob();
                        if (!active) return;
                        objectUrl = URL.createObjectURL(blob);
                        setImageSrc(objectUrl);
                        setLoading(false);
                        return;
                    }
                } catch {
                    // Tenta a próxima URL da lista
                }
            }

            // Fallback final: se tudo falhar, atribui a URL direta
            if (!active) return;
            setImageSrc(imageUrl);
            setLoading(false);
        }

        prepareImage();

        return () => {
            active = false;
            if (objectUrl) {
                URL.revokeObjectURL(objectUrl);
            }
        };
    }, [imageUrl]);

    const initializeSelection = () => {
        const container = containerRef.current;
        if (!container) return;
        setSelection(createCenteredSquareSelection(container.clientWidth, container.clientHeight));
    };

    // Atualiza/reajusta a seleção quando a margem de moldura muda ou na carga
    useEffect(() => {
        if (!loading && !loadError && imageSrc) {
            // Pequeno timeout para garantir renderização do container
            const timer = setTimeout(() => {
                initializeSelection();
            }, 50);
            return () => clearTimeout(timer);
        }
    }, [loading, loadError, imageSrc, paddingPercent]);

    const move = (event: React.PointerEvent<HTMLElement>) => {
        const container = containerRef.current;
        const drag = dragRef.current;
        if (!container || !drag || !selection) return;
        if (drag.mode === 'resize') {
            setSelection(resizeSquareSelection(event.clientX, drag.x, drag.corner, drag.selection, container.clientWidth, container.clientHeight));
            return;
        }
        setSelection(moveSquareSelection(event.clientX, event.clientY, drag.x, drag.y, drag.selection, container.clientWidth, container.clientHeight));
    };

    const finish = async () => {
        const image = imageRef.current;
        const container = containerRef.current;
        if (!image || !container || !selection) return;

        setIsApplying(true);
        try {
            // 1. Criar um canvas temporário do palco quadrado 1080x1080 com o padding configurado
            const stageCanvas = document.createElement('canvas');
            stageCanvas.width = 1080;
            stageCanvas.height = 1080;
            const stageCtx = stageCanvas.getContext('2d');
            if (!stageCtx) throw new Error('Não foi possível obter contexto 2D');

            // Fundo branco da moldura
            stageCtx.fillStyle = '#FFFFFF';
            stageCtx.fillRect(0, 0, 1080, 1080);

            const naturalW = image.naturalWidth || image.clientWidth;
            const naturalH = image.naturalHeight || image.clientHeight;

            // Desenhar a foto centralizada mantendo proporção dentro do padding da moldura
            const innerAvailable = 1080 * (1 - (paddingPercent * 2) / 100);
            const scale = Math.min(innerAvailable / naturalW, innerAvailable / naturalH);
            const drawW = naturalW * scale;
            const drawH = naturalH * scale;
            const drawX = (1080 - drawW) / 2;
            const drawY = (1080 - drawH) / 2;

            stageCtx.drawImage(image, drawX, drawY, drawW, drawH);

            // 2. Extrair a área recortada da seleção proporcional sobre o palco 1080x1080
            const finalCanvas = document.createElement('canvas');
            finalCanvas.width = 1080;
            finalCanvas.height = 1080;
            const finalCtx = finalCanvas.getContext('2d');
            if (!finalCtx) throw new Error('Não foi possível obter contexto final 2D');

            finalCtx.fillStyle = '#FFFFFF';
            finalCtx.fillRect(0, 0, 1080, 1080);

            const scaleSelectionX = 1080 / container.clientWidth;
            const scaleSelectionY = 1080 / container.clientHeight;

            finalCtx.drawImage(
                stageCanvas,
                selection.x * scaleSelectionX,
                selection.y * scaleSelectionY,
                selection.size * scaleSelectionX,
                selection.size * scaleSelectionY,
                0,
                0,
                1080,
                1080
            );

            const blob = await new Promise<Blob | null>(resolve => finalCanvas.toBlob(resolve, 'image/png', 1));
            if (blob) {
                const file = new File([blob], `produto-quadrado-${Date.now()}.png`, { type: 'image/png' });
                const compressed = await compressImageToFile(file, { maxMB: 0.3, maxWidth: 1080 });
                onConfirm(compressed);
            }
        } catch (err: unknown) {
            console.error("Erro ao aplicar recorte/moldura:", err);
            toast.error("Erro ao processar imagem. Tente novamente.");
        } finally {
            setIsApplying(false);
        }
    };

    const startResize = (event: React.PointerEvent<HTMLSpanElement>, corner: CropCorner) => {
        if (!selection) return;
        event.stopPropagation();
        event.currentTarget.setPointerCapture(event.pointerId);
        dragRef.current = { mode: 'resize', x: event.clientX, corner, selection };
    };

    const resetToFull = () => {
        const container = containerRef.current;
        if (!container) return;
        setSelection(createCenteredSquareSelection(container.clientWidth, container.clientHeight));
    };

    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape' && !isApplying) {
                onCancel();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [onCancel, isApplying]);

    return (
        <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="cropper-dialog-title"
            className="fixed inset-0 z-[1000025] flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4 animate-in fade-in duration-200"
        >
            <div className="w-full max-w-3xl rounded-3xl bg-white p-6 shadow-2xl dark:bg-slate-900 border border-slate-100 dark:border-slate-800 flex flex-col gap-4">
                {/* Header */}
                <div className="flex items-center justify-between">
                    <div>
                        <h4 id="cropper-dialog-title" className="text-sm font-black text-slate-800 dark:text-slate-100 flex items-center gap-2">
                            <i className="bi bi-crop text-blue-600" aria-hidden="true" />
                            Recortar e Ajustar Foto do Produto (1:1)
                        </h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider mt-0.5">
                            Arraste/redimensione o quadrado de recorte ou adicione moldura branca em volta
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={onCancel}
                        disabled={isApplying}
                        className="w-8 h-8 flex items-center justify-center rounded-xl text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-colors cursor-pointer"
                        aria-label="Fechar"
                    >
                        <i className="bi bi-x-lg" aria-hidden="true" />
                    </button>
                </div>

                {/* Barra de Controles Simultâneos */}
                <div className="flex flex-wrap items-center justify-between gap-3 bg-slate-100 dark:bg-slate-800/80 px-4 py-2.5 rounded-2xl border border-slate-200/50 dark:border-slate-700/50">
                    {/* Controle de Moldura Branca */}
                    <div className="flex items-center gap-3">
                        <span className="text-xs font-bold text-slate-700 dark:text-slate-200 flex items-center gap-1.5 whitespace-nowrap">
                            <i className="bi bi-bounding-box text-blue-600" aria-hidden="true" />
                            Moldura Branca: <span className="text-blue-600 font-black min-w-[32px]">{paddingPercent}%</span>
                        </span>
                        <input
                            type="range"
                            min="0"
                            max="35"
                            step="5"
                            aria-label="Percentual de moldura branca"
                            value={paddingPercent}
                            onChange={(e) => setPaddingPercent(Number(e.target.value))}
                            className="w-28 h-1.5 accent-blue-600 cursor-pointer"
                        />
                        {paddingPercent > 0 && (
                            <button
                                type="button"
                                onClick={() => setPaddingPercent(0)}
                                className="text-[10px] font-bold text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 underline cursor-pointer"
                            >
                                Zerar
                            </button>
                        )}
                    </div>

                    {/* Botões Rápidos de Ação */}
                    <div className="flex items-center gap-2">
                        <button
                            type="button"
                            onClick={resetToFull}
                            className="flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-bold bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 shadow-sm transition-all cursor-pointer border border-slate-200/60 dark:border-slate-700/60"
                        >
                            <i className="bi bi-arrows-fullscreen text-blue-600 text-[11px]" aria-hidden="true" />
                            Centralizar 1:1
                        </button>
                    </div>
                </div>

                {/* Área de Visualização e Recorte */}
                <div
                    ref={containerRef}
                    className="relative w-full aspect-square max-h-[500px] overflow-hidden rounded-2xl bg-slate-950 flex items-center justify-center select-none shadow-inner"
                >
                    {loading && (
                        <div className="flex flex-col items-center gap-3 text-white/70">
                            <i className="bi bi-arrow-clockwise animate-spin text-2xl text-blue-500" aria-hidden="true" />
                            <span className="text-xs font-bold">Carregando imagem...</span>
                        </div>
                    )}

                    {loadError && !loading && (
                        <div className="flex flex-col items-center gap-3 text-red-400 p-6 text-center">
                            <i className="bi bi-exclamation-triangle text-3xl" aria-hidden="true" />
                            <span className="text-xs font-bold">Falha ao carregar a imagem original</span>
                            <span className="text-[10px] opacity-70">A URL pode estar indisponível ou protegida por CORS.</span>
                        </div>
                    )}

                    {!loading && !loadError && (
                        <div
                            className="relative flex items-center justify-center w-full h-full"
                            style={{
                                padding: `${paddingPercent}%`,
                                transition: 'padding 0.15s ease-out'
                            }}
                        >
                            {/* Imagem do Produto Centralizada com Moldura Dinâmica */}
                            <img
                                ref={imageRef}
                                src={imageSrc}
                                alt="Recorte do produto"
                                onLoad={initializeSelection}
                                className="max-w-full max-h-full object-contain pointer-events-none drop-shadow-md"
                            />

                            {/* Caixa de Recorte 1:1 Sobreposta */}
                            {selection && (
                                <div
                                    className="absolute cursor-move touch-none border-2 border-white shadow-[0_0_0_9999px_rgba(2,6,23,0.75)]"
                                    style={{
                                        left: selection.x,
                                        top: selection.y,
                                        width: selection.size,
                                        height: selection.size
                                    }}
                                    onPointerDown={event => {
                                        event.currentTarget.setPointerCapture(event.pointerId);
                                        dragRef.current = { mode: 'move', x: event.clientX, y: event.clientY, selection };
                                    }}
                                    onPointerMove={move}
                                    onPointerUp={() => { dragRef.current = null; }}
                                    onPointerCancel={() => { dragRef.current = null; }}
                                >
                                    <span className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-white/95 px-3 py-1.5 text-[10px] font-black text-slate-700 shadow-md flex items-center gap-1.5 whitespace-nowrap">
                                        <i className="bi bi-arrows-move text-blue-600" aria-hidden="true" />
                                        Mova ou redimensione
                                    </span>

                                    {(['nw', 'ne', 'sw', 'se'] as const).map((corner: CropCorner) => (
                                        <span
                                            key={corner}
                                            onPointerDown={event => startResize(event, corner)}
                                            onPointerMove={move}
                                            onPointerUp={() => { dragRef.current = null; }}
                                            style={{ cursor: `${corner}-resize` }}
                                            className={`absolute h-4 w-4 touch-none rounded-full border-2 border-blue-600 bg-white shadow-md ${
                                                corner.includes('n') ? '-top-2' : '-bottom-2'
                                            } ${corner.includes('w') ? '-left-2' : '-right-2'}`}
                                        />
                                    ))}
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="flex items-center justify-between pt-1">
                    <div className="text-[11px] text-slate-400 font-medium">
                        Saída: 1080 × 1080 px com qualidade otimizada.
                    </div>
                    <div className="flex items-center gap-2">
                        <button
                            type="button"
                            onClick={onCancel}
                            disabled={isApplying}
                            className="rounded-xl px-5 py-2.5 text-xs font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                        >
                            Cancelar
                        </button>
                        <button
                            type="button"
                            onClick={finish}
                            disabled={!selection || isApplying || loading || loadError}
                            className="rounded-xl bg-blue-600 hover:bg-blue-700 px-6 py-2.5 text-xs font-black text-white shadow-lg shadow-blue-500/20 disabled:opacity-50 transition-all flex items-center gap-2 cursor-pointer active:scale-95"
                        >
                            {isApplying ? (
                                <>
                                    <i className="bi bi-arrow-clockwise animate-spin text-sm" />
                                    Processando...
                                </>
                            ) : (
                                <>
                                    <i className="bi bi-check-lg text-sm" />
                                    Concluir e Salvar
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default SquareImageCropper;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

interface TechnicalValueOption {
    readonly id?: string;
    readonly value: string;
}

interface TechnicalComboboxProps {
    readonly fieldName: string;
    readonly value?: string;
    readonly options: readonly TechnicalValueOption[];
    readonly placeholder?: string;
    readonly isInvalid?: boolean;
    readonly disabled?: boolean;
    readonly onChange: (val: string) => void;
}

export const TechnicalCombobox: React.FC<TechnicalComboboxProps> = ({
    fieldName,
    value,
    options,
    placeholder,
    isInvalid,
    disabled,
    onChange
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState(value || '');
    const containerRef = useRef<HTMLDivElement | null>(null);
    const inputRef = useRef<HTMLInputElement | null>(null);

    // Sincroniza o texto digitado se o valor mudar externamente
    useEffect(() => {
        setSearchTerm(value || '');
    }, [value]);

    // Fecha o dropdown ao clicar fora
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
                // Se fechou sem selecionar e o texto não bater com o valor atual, volta ao selecionado
                setSearchTerm(value || '');
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [value]);

    const cleanedSearch = searchTerm.trim();
    const isSearchAllowed = cleanedSearch.length >= 2;

    const filteredOptions = useMemo(() => {
        if (!isSearchAllowed) {
            return [];
        }
        const term = normalizeSearchTerm(cleanedSearch);
        return options.filter(opt => {
            const optVal = opt?.value ? String(opt.value) : '';
            return normalizeSearchTerm(optVal).includes(term);
        });
    }, [options, cleanedSearch, isSearchAllowed]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setSearchTerm(val);
        setIsOpen(true);
        // Se apagar tudo, limpa a seleção
        if (!val.trim()) {
            onChange('');
        }
    };

    const handleSelectOption = (optVal: string) => {
        setSearchTerm(optVal);
        onChange(optVal);
        setIsOpen(false);
        inputRef.current?.blur();
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Escape') {
            setIsOpen(false);
            setSearchTerm(value || '');
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (filteredOptions.length > 0) {
                handleSelectOption(filteredOptions[0].value);
            }
        } else if (e.key === 'ArrowDown') {
            setIsOpen(true);
        }
    };

    const hasSelectedValue = Boolean(value && String(value).trim() !== '');
    const isNotApplicable = String(value || '').trim().toLowerCase() === 'não se aplica' || 
                            String(value || '').trim().toLowerCase() === 'nao se aplica' || 
                            String(value || '').trim().toUpperCase() === 'N/A';

    return (
        <div ref={containerRef} className="relative w-full mt-1">
            <div className="relative flex items-center">
                <i className={`bi bi-search absolute left-0.5 top-1/2 -translate-y-1/2 text-[11px] pointer-events-none transition-colors ${
                    disabled
                        ? 'text-emerald-500'
                        : isInvalid
                        ? 'text-red-500'
                        : hasSelectedValue
                        ? 'text-blue-600 dark:text-blue-400'
                        : 'text-slate-400'
                }`} />

                <input
                    ref={inputRef}
                    type="text"
                    value={searchTerm}
                    readOnly={disabled}
                    onFocus={disabled ? undefined : () => setIsOpen(true)}
                    onChange={disabled ? undefined : handleInputChange}
                    onKeyDown={disabled ? undefined : handleKeyDown}
                    placeholder={placeholder || `Busque e selecione ${fieldName}...`}
                    className={`w-full pl-6 pr-6 py-2 border-b-2 border-t-0 border-x-0 rounded-none text-xs outline-none transition-all ${
                        disabled || isNotApplicable
                            ? 'bg-slate-100 dark:bg-slate-800/60 border-slate-300 dark:border-slate-700 text-slate-500 dark:text-slate-400 font-semibold cursor-not-allowed'
                            : isInvalid
                            ? 'bg-transparent border-red-500 text-red-600 dark:text-red-400 placeholder:text-red-300'
                            : 'bg-transparent border-slate-300 dark:border-slate-700 text-slate-800 dark:text-slate-200 placeholder:text-slate-400 focus:border-blue-600 dark:focus:border-blue-400'
                    } ${!disabled && !isNotApplicable && hasSelectedValue ? 'font-bold' : ''}`}
                />

                {!disabled && searchTerm && (
                    <button
                        type="button"
                        onClick={() => {
                            setSearchTerm('');
                            onChange('');
                            setIsOpen(true);
                            inputRef.current?.focus();
                        }}
                        aria-label="Limpar campo"
                        className="absolute right-0.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-1 cursor-pointer text-xs transition-colors"
                    >
                        <i className="bi bi-x-circle-fill" />
                    </button>
                )}
            </div>

            {/* Painel de Resultados logo abaixo do input */}
            {isOpen && (
                <div className="absolute left-0 right-0 top-full mt-1.5 z-50 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-xl overflow-hidden max-h-56 overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-150">
                    <div className="p-1.5 space-y-0.5">
                        {!isSearchAllowed ? (
                            <div className="p-4 text-center text-slate-400 text-xs">
                                <i className="bi bi-keyboard text-base text-blue-500 opacity-60 mb-1 block" />
                                <span className="font-bold text-slate-500 dark:text-slate-400">
                                    {cleanedSearch.length === 0 
                                        ? 'Digite no mínimo 2 caracteres para pesquisar' 
                                        : 'Digite mais 1 caractere para pesquisar'}
                                </span>
                            </div>
                        ) : filteredOptions.length === 0 ? (
                            <div className="p-4 text-center text-slate-400 text-xs">
                                <i className="bi bi-search text-base opacity-40 mb-1 block" />
                                <span>Nenhum resultado para "{searchTerm}"</span>
                            </div>
                        ) : (
                            filteredOptions.map((opt) => {
                                const isSelected = value === opt.value;
                                return (
                                    <button
                                        key={opt.id || opt.value}
                                        type="button"
                                        onMouseDown={(e) => {
                                            // onMouseDown dispara antes do blur do input
                                            e.preventDefault();
                                            handleSelectOption(opt.value);
                                        }}
                                        className={`w-full px-3 py-2 rounded-xl text-left text-xs font-bold flex items-center justify-between transition-colors cursor-pointer ${
                                            isSelected
                                                ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 font-black'
                                                : 'hover:bg-slate-100 dark:hover:bg-slate-800/80 text-slate-700 dark:text-slate-200'
                                        }`}
                                    >
                                        <span className="truncate">{opt.value}</span>
                                        {isSelected && (
                                            <i className="bi bi-check-circle-fill text-blue-600 dark:text-blue-400 text-xs shrink-0" />
                                        )}
                                    </button>
                                );
                            })
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import { TechnicalCombobox } from './TechnicalCombobox';
import { TechnicalFieldDefinition } from '@/pages/utils/technicalValuesService';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

type Props = { field: TechnicalFieldDefinition; value: any; disabled?: boolean; isInvalid?: boolean; onChange: (value: any) => void };

export const TechnicalFieldInput: React.FC<Props> = ({ field, value, disabled, isInvalid, onChange }) => {
    const type = field.dataType || 'list';
    const maxLength = 120;
    if (type === 'text_short' || type === 'text') return <input value={value ?? ''} maxLength={maxLength} disabled={disabled} onChange={e => onChange(e.target.value)} className="w-full border-b-2 border-slate-300 bg-transparent py-2 text-xs outline-none focus:border-blue-600" />;
    if (type === 'integer' || type === 'number') return <input type="number" step="1" placeholder={/porta|gaveta/i.test(field.name) ? 'Insira a quantidade de portas' : 'Insira um número inteiro'} value={value ?? ''} disabled={disabled} onChange={e => onChange(e.target.value === '' ? '' : Number(e.target.value))} className="w-full border-b-2 border-slate-300 bg-transparent py-2 text-xs outline-none focus:border-blue-600" />;
    if (type === 'decimal' || type === 'measure') return <DecimalInput value={value} disabled={disabled} onChange={onChange} />;
    if (type === 'radio') return <ChoiceSearch options={field.options} value={value} disabled={disabled} multiple={false} onChange={onChange} />;
    if (type === 'multi_select') {
        const selected = Array.isArray(value) ? value : value ? String(value).split(',').map(v => v.trim()).filter(Boolean) : [];
        return <ChoiceSearch options={field.options} value={selected} disabled={disabled} multiple onChange={onChange} />;
    }
    return <TechnicalCombobox fieldName={field.name} value={Array.isArray(value) ? value.join(', ') : value ?? ''} options={field.options} isInvalid={isInvalid} disabled={disabled} onChange={onChange} />;
};

function DecimalInput({ value, disabled, onChange }: { value: any; disabled?: boolean; onChange: (value: any) => void }) {
    const [draft, setDraft] = useState(() => formatDecimal(value));

    React.useEffect(() => {
        setDraft(formatDecimal(value));
    }, [value]);

    const handleMaskedChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const digits = event.target.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '');
        if (!digits) {
            setDraft('');
            onChange('');
            return;
        }
        const numeric = Number(digits) / 100;
        setDraft(formatDecimal(numeric));
        onChange(numeric);
    };

    return <input
        type="text"
        inputMode="decimal"
        placeholder="0,00"
        value={draft}
        disabled={disabled}
        onChange={handleMaskedChange}
        className="w-full border-b-2 border-slate-300 bg-transparent py-2 text-xs outline-none focus:border-blue-600"
    />;
}

function formatDecimal(value: any): string {
    if (value === '' || value === null || value === undefined) return '';
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric.toFixed(2).replace('.', ',') : '';
}

function ChoiceSearch({ options, value, disabled, multiple, onChange }: { options: readonly { id?: string; value: string }[]; value: string | string[]; disabled?: boolean; multiple: boolean; onChange: (v: any) => void }) {
    const [query, setQuery] = useState('');
    const searchRef = React.useRef<HTMLDivElement>(null);
    const selected = (Array.isArray(value) ? value : [value].filter(Boolean))
        .filter(item => normalizeSearchTerm(String(item)) !== normalizeSearchTerm('Não se aplica'));
    const term = normalizeSearchTerm(query);
    const displayValue = query || selected.join(', ');
    const filtered = useMemo(() => term.length < 2 ? [] : options.filter(o => normalizeSearchTerm(o.value).includes(term)), [options, term]);
    const exactMatch = term.length >= 2 ? options.find(o => normalizeSearchTerm(o.value) === term) : undefined;
    const isSelected = term.length === 0
        ? selected.length > 0
        : Boolean(exactMatch && selected.some(item => normalizeSearchTerm(item) === term));

    React.useEffect(() => {
        if (!exactMatch || isSelected || disabled) return;
        onChange(multiple ? [...selected, exactMatch.value] : exactMatch.value);
    }, [exactMatch, isSelected, disabled, multiple, onChange, selected]);

    React.useEffect(() => {
        const closeSuggestions = (event: MouseEvent) => {
            if (searchRef.current && !searchRef.current.contains(event.target as Node)) setQuery('');
        };
        document.addEventListener('mousedown', closeSuggestions);
        return () => document.removeEventListener('mousedown', closeSuggestions);
    }, []);

    return <div ref={searchRef} className="relative space-y-2">
        <div className="relative">
            <input value={displayValue} disabled={disabled} onChange={e => setQuery(e.target.value)} placeholder="Digite pelo menos 2 caracteres para pesquisar..." className={`w-full border-b-2 bg-transparent py-2 pr-8 text-xs outline-none focus:border-blue-600 ${isSelected ? 'border-emerald-500 text-emerald-700 dark:text-emerald-400' : 'border-slate-300'}`} />
            {isSelected && <i className="bi bi-check-lg absolute right-1 top-1/2 -translate-y-1/2 text-emerald-600 dark:text-emerald-400" aria-label="Opção selecionada" />}
        </div>
        {term.length >= 2 && <div className="absolute left-0 right-0 top-full z-40 mt-1 flex max-h-48 flex-col gap-1 overflow-y-auto rounded-xl border border-slate-200 bg-white p-1.5 shadow-xl dark:border-slate-700 dark:bg-slate-900">
            {filtered.map(o => <label key={o.id || o.value} className="text-xs"><input type={multiple ? 'checkbox' : 'radio'} name={multiple ? undefined : `technical-${options.map(x => x.id || x.value).join('-')}`} disabled={disabled} checked={selected.includes(o.value)} onChange={e => onChange(multiple ? (e.target.checked ? [...selected, o.value] : selected.filter(v => v !== o.value)) : o.value)} /> <span className="ml-1">{o.value}</span></label>)}
            {filtered.length === 0 && <span className="text-[10px] text-slate-400">Nenhuma opção encontrada.</span>}
        </div>}
    </div>;
}

import React, { useState, useMemo, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

interface TechnicalValueOption {
    readonly id?: string;
    readonly value: string;
}

interface TechnicalValueSelectModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly fieldName: string;
    readonly currentValue?: string;
    readonly options: readonly TechnicalValueOption[];
    readonly onSelect: (value: string) => void;
}

export const TechnicalValueSelectModal: React.FC<TechnicalValueSelectModalProps> = ({
    isOpen,
    onClose,
    fieldName,
    currentValue,
    options,
    onSelect
}) => {
    const [searchTerm, setSearchTerm] = useState('');
    const inputRef = React.useRef<HTMLInputElement | null>(null);

    useEffect(() => {
        if (isOpen) {
            setSearchTerm('');
            // Foca no input após renderizar
            const timer = setTimeout(() => {
                inputRef.current?.focus();
            }, 50);
            return () => clearTimeout(timer);
        }
    }, [isOpen]);

    const cleanedSearch = searchTerm.trim();
    const isSearchActive = cleanedSearch.length > 0;

    const filteredOptions = useMemo(() => {
        if (!isSearchActive) {
            return options;
        }
        const term = normalizeSearchTerm(cleanedSearch);
        return options.filter(opt => {
            const optVal = opt?.value ? String(opt.value) : '';
            return normalizeSearchTerm(optVal).includes(term);
        });
    }, [options, cleanedSearch, isSearchActive]);

    if (!isOpen) return null;

    const modalContent = (
        <div 
            className="fixed inset-0 z-[1000030] flex items-center justify-center p-4"
            onKeyDown={(e) => {
                if (e.key === 'Escape') {
                    e.stopPropagation();
                    onClose();
                }
            }}
        >
            <div 
                className="fixed inset-0 bg-slate-900/60 backdrop-blur-xs transition-opacity" 
                onClick={onClose} 
            />

            <div className="relative w-full max-w-md bg-white dark:bg-slate-900 rounded-3xl shadow-2xl border border-slate-200 dark:border-slate-800 overflow-hidden flex flex-col max-h-[85vh] animate-in fade-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between shrink-0">
                    <div>
                        <h3 className="text-base font-black text-slate-800 dark:text-slate-100 tracking-tight flex items-center gap-2">
                            <i className="bi bi-search text-blue-600" aria-hidden="true" />
                            <span>Pesquisar {fieldName}</span>
                        </h3>
                        <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-widest mt-0.5">
                            {options.length} {options.length === 1 ? 'opção cadastrada' : 'opções cadastradas'}
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-1.5 rounded-xl text-slate-400 hover:text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
                    >
                        <i className="bi bi-x-lg text-sm" />
                    </button>
                </div>

                {/* Input de Busca com borda apenas embaixo (Regra 9) e filtro imediato */}
                <div className="p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 shrink-0">
                    <div className="relative">
                        <i className="bi bi-search absolute left-1 top-1/2 -translate-y-1/2 text-slate-400 text-xs" />
                        <input
                            ref={inputRef}
                            autoFocus
                            type="text"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            placeholder={`Digite para pesquisar em ${fieldName}...`}
                            className="w-full pl-7 pr-8 py-2 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-300 dark:border-slate-700 rounded-none text-xs font-bold outline-none focus:border-blue-600 dark:focus:border-blue-400 dark:text-slate-100 placeholder:font-medium placeholder:text-slate-400 transition-all"
                        />
                        {searchTerm && (
                            <button
                                type="button"
                                onClick={() => setSearchTerm('')}
                                className="absolute right-1 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 text-xs cursor-pointer p-1"
                            >
                                <i className="bi bi-x-circle-fill" />
                            </button>
                        )}
                    </div>
                </div>

                {/* Lista de Opções */}
                <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-1 min-h-[220px]">
                    {filteredOptions.length === 0 ? (
                        <div className="p-8 text-center text-slate-400">
                            <i className="bi bi-search text-2xl opacity-40 mb-2 block" />
                            <p className="text-xs font-bold">Nenhum valor encontrado para "{searchTerm}"</p>
                        </div>
                    ) : (
                        filteredOptions.map((opt) => {
                            const isSelected = currentValue === opt.value;
                            return (
                                <button
                                    key={opt.id || opt.value}
                                    type="button"
                                    onClick={() => {
                                        onSelect(opt.value);
                                        onClose();
                                    }}
                                    className={`w-full px-4 py-2.5 rounded-2xl text-left text-xs font-bold flex items-center justify-between transition-all cursor-pointer ${
                                        isSelected
                                            ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 border border-blue-200 dark:border-blue-800 font-black'
                                            : 'hover:bg-slate-50 dark:hover:bg-slate-800/60 text-slate-700 dark:text-slate-200 border border-transparent'
                                    }`}
                                >
                                    <span>{opt.value}</span>
                                    {isSelected && (
                                        <i className="bi bi-check-circle-fill text-blue-600 dark:text-blue-400" />
                                    )}
                                </button>
                            );
                        })
                    )}
                </div>

                {/* Rodapé */}
                <div className="px-5 py-3 border-t border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/40 flex justify-end shrink-0">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-4 py-2 text-xs font-bold text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 cursor-pointer"
                    >
                        Fechar
                    </button>
                </div>
            </div>
        </div>
    );

    return createPortal(modalContent, document.body);
};

import React from 'react';
import type { Variation } from '../../../types/product.type';
