                    <button
                        type="button"
                        onClick={() => onEditCombo?.(v.id)}
                        className={`p-1.5 rounded-xl transition-all ${
                            v.comboItems?.length
                                ? 'bg-purple-600 text-white shadow-lg shadow-purple-500/30'
                                : 'bg-slate-100 dark:bg-slate-800 text-slate-400 hover:text-purple-600'
