import React, { useState, useRef, useEffect } from 'react';
import { toast } from 'react-toastify';
import { saveAttributeValue } from '@/pages/utils/variationService';
import type { DbAttributeValueItem } from './VariationIdentificationTab';

interface VariationAttributeValueInputProps {
    readonly attributeId?: string;
    readonly attributeName?: string;
    readonly value: string;
    readonly registeredValues: readonly DbAttributeValueItem[];
    readonly onChange: (newValue: string) => void;
    readonly onValueRegistered?: (created: DbAttributeValueItem) => void;
    readonly dataType?: 'list' | 'integer' | 'decimal' | 'text' | 'boolean' | 'measure';
    readonly unit?: string;
}

export const VariationAttributeValueInput: React.FC<VariationAttributeValueInputProps> = ({
    attributeId,
    attributeName,
    value,
    registeredValues,
    onChange,
    onValueRegistered,
    dataType = 'list',
    unit
}) => {
    const [isOpenSuggestions, setIsOpenSuggestions] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    const trimmedValue = (value || '').trim();

    // Verifica se o valor coincide com algum valor cadastrado para este atributo
    const isRegisteredValue = Boolean(
        trimmedValue &&
        registeredValues.some(
            (v) => v.value.trim().toLocaleLowerCase('pt-BR') === trimmedValue.toLocaleLowerCase('pt-BR')
        )
    );

    // Valor digitado mas ainda não existente no catálogo deste atributo
    const isUnregisteredValue = Boolean(trimmedValue && attributeId && !isRegisteredValue);

    // Fechar sugestões ao clicar fora
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpenSuggestions(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleRegisterNewValue = async () => {
        if (!attributeId || !trimmedValue || isSaving) return;

        setIsSaving(true);
        try {
            const saved = await saveAttributeValue(attributeId, trimmedValue);
            onChange(saved.value);
            onValueRegistered?.(saved);
            setIsOpenSuggestions(false);
            toast.success(`Valor "${saved.value}" cadastrado com sucesso!`);
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : 'Erro ao cadastrar valor';
            toast.error(message);
        } finally {
            setIsSaving(false);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            if (isUnregisteredValue) {
                void handleRegisterNewValue();
            } else {
                setIsOpenSuggestions(false);
            }
        } else if (e.key === 'Escape') {
            setIsOpenSuggestions(false);
        }
    };

    const term = trimmedValue.toLocaleLowerCase('pt-BR');
    const suggestions = registeredValues.filter((option) =>
        option.value.toLocaleLowerCase('pt-BR').includes(term)
    );

    const renderInput = () => {
        if (dataType === 'boolean') {
            return (
                <select
                    value={value}
                    onChange={(e) => onChange(e.target.value)}
                    className="box-border h-[34px] w-full bg-transparent border-b-2 border-t-0 border-x-0 outline-none px-1 py-0 text-xs font-bold transition-all border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200 focus:border-blue-500"
                >
                    <option value="">Selecione...</option>
                    <option value="Sim">Sim</option>
                    <option value="Não">Não</option>
                </select>
            );
        }

        if (dataType === 'integer' || dataType === 'decimal' || dataType === 'measure') {
            const isDecimal = dataType === 'decimal' || dataType === 'measure';
            return (
                <div className="relative flex items-center">
                    <input
                        type={isDecimal ? 'text' : 'number'}
                        inputMode={isDecimal ? 'decimal' : 'numeric'}
                        step={dataType === 'integer' ? '1' : '0.01'}
                        placeholder={isDecimal ? '0,00' : (/porta|gaveta/i.test(attributeName || '') ? 'Insira a quantidade de portas' : 'Insira um número inteiro')}
                        value={isDecimal ? formatDecimalValue(value) : value}
                        onChange={(e) => onChange(isDecimal ? maskDecimalValue(e.target.value) : e.target.value)}
                        className={`box-border h-[34px] w-full bg-transparent border-b-2 border-t-0 border-x-0 outline-none px-1 py-0 ${unit ? 'pr-8' : ''} text-xs font-bold transition-all border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200 focus:border-blue-500`}
                    />
                    {unit && (
                        <span className="absolute right-1 text-slate-400 font-bold text-[10px] select-none">
                            {unit}
                        </span>
                    )}
                </div>
            );
}

        if (dataType === 'text') {
            return (
                <input
                    type="text"
                    placeholder={attributeName ? `Valor de ${attributeName}...` : "Informe um valor..."}
                    value={value}
                    onChange={(e) => onChange(e.target.value)}
                    className="box-border h-[34px] w-full bg-transparent border-b-2 border-t-0 border-x-0 outline-none px-1 py-0 text-xs font-bold transition-all border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200 focus:border-blue-500"
                />
            );
        }

        // dataType === 'list' (padrão antigo)
        return (
            <>
                <div className="relative flex items-center">
                    <input
                        type="text"
                        placeholder={attributeName ? `Valor de ${attributeName}...` : "Pesquise ou informe um valor..."}
                        value={value}
                        onFocus={() => setIsOpenSuggestions(true)}
                        onChange={(e) => {
                            onChange(e.target.value);
                            setIsOpenSuggestions(true);
                        }}
                        onKeyDown={handleKeyDown}
                        className={`box-border h-[34px] w-full bg-transparent border-b-2 border-t-0 border-x-0 outline-none px-1 py-0 pr-8 text-xs font-bold transition-all ${
                            isRegisteredValue
                                ? 'border-emerald-500 dark:border-emerald-400 text-emerald-700 dark:text-emerald-400 focus:border-emerald-600 dark:focus:border-emerald-300'
                                : isUnregisteredValue
                                ? 'border-amber-400 dark:border-amber-500/80 text-slate-800 dark:text-slate-100 focus:border-blue-600 dark:focus:border-blue-400'
                                : 'border-slate-200 dark:border-slate-800 text-slate-800 dark:text-slate-200 focus:border-blue-600 dark:focus:border-blue-400'
                        }`}
                    />

                    {isRegisteredValue && (
                        <span
                            className="absolute right-1 top-1/2 -translate-y-1/2 flex items-center justify-center text-emerald-600 dark:text-emerald-400 pointer-events-none animate-in fade-in"
                            title="Valor cadastrado e selecionado"
                            data-testid="attribute-registered-check"
                        >
                            <i className="bi bi-check-lg text-base font-black" />
                        </span>
                    )}

                    {isUnregisteredValue && (
                        <button
                            type="button"
                            onClick={() => void handleRegisterNewValue()}
                            disabled={isSaving}
                            className="absolute right-1 top-1/2 -translate-y-1/2 p-1 rounded-md bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white transition-all shadow-sm flex items-center justify-center cursor-pointer disabled:opacity-50"
                            title="Cadastrar este valor"
                            aria-label="Cadastrar este valor"
                            data-testid="attribute-register-button"
                        >
                            {isSaving ? (
                                <i className="bi bi-arrow-repeat animate-spin text-xs" />
                            ) : (
                                <i className="bi bi-check-lg text-xs font-black" />
                            )}
                        </button>
                    )}
                </div>

                {isUnregisteredValue && (
                    <p
                        className="text-[10px] font-medium text-amber-600 dark:text-amber-400 flex items-center gap-1 mt-1 animate-in fade-in"
                        data-testid="attribute-unregistered-notice"
                    >
                        <i className="bi bi-exclamation-circle text-[10px] shrink-0" />
                        <span>Esse valor não está cadastrado. Deseja cadastrar?</span>
                    </p>
                )}

                {isOpenSuggestions && suggestions.length > 0 && (
                    <div className="absolute left-0 right-0 z-30 mt-1 max-h-44 overflow-y-auto rounded-xl border border-slate-200 bg-white p-1 shadow-xl dark:border-slate-700 dark:bg-slate-900 animate-in fade-in">
                        {suggestions.map((option) => (
                            <button
                                key={option.id}
                                type="button"
                                onMouseDown={(e) => e.preventDefault()}
                                onClick={() => {
                                    onChange(option.value);
                                    setIsOpenSuggestions(false);
                                }}
                                className="w-full rounded-lg px-3 py-2 text-left text-xs font-semibold text-slate-700 hover:bg-emerald-50 hover:text-emerald-700 dark:text-slate-200 dark:hover:bg-emerald-950/40 dark:hover:text-emerald-300 transition-colors flex items-center justify-between"
                            >
                                <span>{option.value}</span>
                                {trimmedValue.toLocaleLowerCase('pt-BR') === option.value.toLocaleLowerCase('pt-BR') && (
                                    <i className="bi bi-check-lg text-emerald-600 dark:text-emerald-400 text-xs font-black" />
                                )}
                            </button>
                        ))}
                    </div>
                )}
            </>
        );
    };

    return (
        <div ref={containerRef} className="relative flex-1 self-end space-y-1">
            {renderInput()}
        </div>
    );
};

function maskDecimalValue(input: string): string {
    const digits = input.replace(/\D/g, '').replace(/^0+(?=\d)/, '');
    if (!digits) return '';
    return (Number(digits) / 100).toFixed(2);
}

function formatDecimalValue(value: string): string {
    if (!value) return '';
    const numeric = Number(value.replace(',', '.'));
    return Number.isFinite(numeric) ? numeric.toFixed(2).replace('.', ',') : '';
}

import React, { useState } from 'react';
import type { Variation, ComboItem, Product } from '../../../../types/product.type';
import ProductAutocomplete from '../../../../../components/ProductAutocomplete';

interface VariationCompositionItemsTabProps {
    readonly formData: Variation;
    readonly setFormData: React.Dispatch<React.SetStateAction<Variation | null>>;
    readonly parentProduct: Product;
}

export const VariationCompositionItemsTab: React.FC<VariationCompositionItemsTabProps> = ({
    formData,
    setFormData,
    parentProduct
}) => {
    // Adiciona um item vazio para ser preenchido
    const handleAddNewEmptyRow = () => {
        setFormData(prev => {
            if (!prev) return prev;
            const currentItems = prev.comboItems || [];
            const newItem: ComboItem = {
                productId: '',
                variationId: undefined,
                quantity: 1,
                description: '',
                unitPrice: 0,
                stock: 0
            };
            return {
                ...prev,
                comboItems: [...currentItems, newItem]
            };
        });
    };

    const handleSelectProduct = (index: number, product: any, variation?: any) => {
        setFormData(prev => {
            if (!prev) return prev;
            const currentItems = [...(prev.comboItems || [])];
            currentItems[index] = {
                ...currentItems[index],
                productId: product.id,
                variationId: variation?.id,
                description: variation ? variation.name : product.name,
                unitPrice: variation?.unitPrice || product.unitPrice || 0,
                stock: variation?.stock || product.stock || 0
            };
            return { ...prev, comboItems: currentItems };
        });
    };

    const handleRemoveItem = (index: number) => {
        setFormData(prev => {
            if (!prev) return prev;
            const newItems = [...(prev.comboItems || [])];
            newItems.splice(index, 1);
            return { ...prev, comboItems: newItems };
        });
    };

    const handleQuantityChange = (index: number, quantity: number) => {
        if (quantity < 1) return;
        setFormData(prev => {
            if (!prev) return prev;
            const newItems = [...(prev.comboItems || [])];
            newItems[index] = { ...newItems[index], quantity };
            return { ...prev, comboItems: newItems };
        });
    };

    const handlePriceChange = (index: number, priceStr: string) => {
        const val = parseFloat(priceStr.replace(',', '.')) || 0;
        setFormData(prev => {
            if (!prev) return prev;
            const newItems = [...(prev.comboItems || [])];
            newItems[index] = { ...newItems[index], unitPrice: val };
            return { ...prev, comboItems: newItems };
        });
    };

    const items = formData.comboItems || [];
    const supplierId = parentProduct.supplierId || parentProduct.mainSupplierId;
    
    // Calcula o custo total da composição baseado nos itens
    const suggestedPrice = items.reduce((acc, item) => acc + (item.unitPrice * item.quantity), 0);

    return (
        <div className="flex flex-col gap-6 animate-in fade-in duration-200">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-slate-50 dark:bg-slate-800/50 p-4 rounded-2xl border border-slate-100 dark:border-slate-800">
                <div>
                    <h3 className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-widest flex items-center gap-2">
                        <i className="bi bi-box-seam text-blue-500"></i>
                        Produtos que compõem a composição
                    </h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 font-medium">
                        Adicione os produtos reais que compõem esta variação. O estoque será deduzido deles.
                    </p>
                </div>
                
                <button
                    type="button"
                    onClick={handleAddNewEmptyRow}
                    className="flex items-center justify-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:hover:bg-blue-900/40 rounded-xl font-bold transition-colors text-xs tracking-wide whitespace-nowrap"
                >
                    <i className="bi bi-plus-lg"></i>
                    Adicionar Produto
                </button>
            </div>

            {items.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-12 px-4 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-3xl bg-slate-50/50 dark:bg-slate-900/50">
                    <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/20 text-blue-500 rounded-full flex items-center justify-center mb-4">
                        <i className="bi bi-diagram-3 text-2xl"></i>
                    </div>
                    <h4 className="text-sm font-black text-slate-800 dark:text-slate-200 uppercase tracking-widest mb-2">
                        Composição Vazia
                    </h4>
                    <p className="text-xs text-slate-500 dark:text-slate-400 max-w-sm">
                        Esta variação ainda não possui itens. Adicione os produtos reais para que a baixa de estoque funcione corretamente.
                    </p>
                </div>
            ) : (
                <div className="flex flex-col gap-4">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="border-b border-slate-100 dark:border-slate-800">
                                    <th className="py-3 px-4 text-[10px] font-black uppercase tracking-widest text-slate-400">Produto</th>
                                    <th className="py-3 px-4 text-[10px] font-black uppercase tracking-widest text-slate-400 w-24">Qtd</th>
                                    <th className="py-3 px-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right w-32">Preço Unit.</th>
                                    <th className="py-3 px-4 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right w-32">Subtotal</th>
                                    <th className="py-3 px-4 w-12"></th>
                                </tr>
                            </thead>
                            <tbody>
                                {items.map((item, idx) => (
                                    <tr key={`${item.productId || 'new'}-${item.variationId || 'base'}-${idx}`} className="border-b border-slate-50 dark:border-slate-800/50 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                        <td className="py-3 px-4">
                                            {item.productId ? (
                                                <div className="flex flex-col">
                                                    <span className="text-xs font-bold text-slate-800 dark:text-slate-200">
                                                        {item.description}
                                                    </span>
                                                </div>
                                            ) : (
                                                <ProductAutocomplete
                                                    supplierId={supplierId}
                                                    onSelect={(p, v) => handleSelectProduct(idx, p, v)}
                                                    clearOnSelect={false}
                                                    excludeCombos={true}
                                                    placeholder="Buscar produto (mesmo fornecedor)"
                                                    inputClassName="w-full border-b border-slate-300 dark:border-slate-700 bg-transparent px-0 py-1 text-xs font-medium outline-none focus:border-blue-500 transition-colors"
                                                />
                                            )}
                                        </td>
                                        <td className="py-3 px-4">
                                            <input
                                                type="number"
                                                min="1"
                                                value={item.quantity || ''}
                                                onChange={(e) => handleQuantityChange(idx, Number(e.target.value))}
                                                className="w-16 border-b border-slate-300 dark:border-slate-700 bg-transparent px-1 py-1 text-center outline-none focus:border-blue-500 text-xs font-bold transition-colors"
                                            />
                                        </td>
                                        <td className="py-3 px-4 text-right">
                                            <div className="flex items-center justify-end gap-1">
                                                <span className="text-xs font-medium text-slate-800 dark:text-slate-200">
                                                    R$ {Number(item.unitPrice || 0).toFixed(2)}
                                                </span>
                                            </div>
                                        </td>
                                        <td className="py-3 px-4 text-right text-xs font-bold text-slate-800 dark:text-slate-200">
                                            R$ {(item.unitPrice * item.quantity).toFixed(2)}
                                        </td>
                                        <td className="py-3 px-4 text-right">
                                            <button
                                                type="button"
                                                onClick={() => handleRemoveItem(idx)}
                                                className="text-slate-400 hover:text-red-500 transition-colors"
                                                title="Remover Item"
                                            >
                                                <i className="bi bi-trash"></i>
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    
                    <div className="flex justify-end p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-xl border border-emerald-100 dark:border-emerald-900/30 mt-2">
                        <div className="text-right">
                            <p className="text-[10px] font-black uppercase tracking-widest text-emerald-600 dark:text-emerald-400">
                                Preço Sugerido da Composição
                            </p>
                            <p className="text-lg font-black text-emerald-700 dark:text-emerald-300">
                                R$ {suggestedPrice.toFixed(2)}
                            </p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default VariationCompositionItemsTab;

import React from 'react';
import Product, { Variation } from '../../../../types/product.type';
import { toTitleCase } from '@/pages/utils/textUtils';

export interface DbAttributeItem {
    readonly id: string;
    readonly name: string;
    readonly data_type?: 'list' | 'integer' | 'decimal' | 'text' | 'boolean' | 'measure';
    readonly unit?: string;
}

export interface DbAttributeValueItem {
    readonly id: string;
    readonly attribute_id: string;
    readonly value: string;
}

interface VariationIdentificationTabProps {
    readonly formData: Variation;
    readonly setFormData: React.Dispatch<React.SetStateAction<Variation | null>>;
    readonly parentProduct: Product;
    readonly diferenciarTitulo: boolean;
    readonly setDiferenciarTitulo: React.Dispatch<React.SetStateAction<boolean>>;
    readonly dbAttributes?: readonly DbAttributeItem[];
    readonly dbAttributeValues?: readonly DbAttributeValueItem[];
    readonly setIsManageAttributesOpen?: (open: boolean) => void;
    readonly getDefaultVariationName?: (attributes?: Variation['attributes']) => string;
    readonly getDefaultVariationTitle?: (attributes?: Variation['attributes']) => string;
    readonly fetchDbAttributes?: () => Promise<void>;
}

export const VariationIdentificationTab: React.FC<VariationIdentificationTabProps> = ({
    formData,
    setFormData,
    parentProduct,
    diferenciarTitulo,
    setDiferenciarTitulo
}) => {
    return (
        <div className="space-y-6 animate-in fade-in duration-350">
            {/* Linha com Nome (ERP) e Título (Catálogo) */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Nome da Variação (ERP) */}
                <div className="space-y-1.5">
                    <div className="flex items-center justify-between h-6">
                        <label className="text-[10px] uppercase font-black text-slate-400 dark:text-slate-500 tracking-widest flex items-center gap-1.5">
                            <span>Nome</span>
                            <span className="text-red-500 ml-0.5">*</span>
                        </label>
                        <button
                            type="button"
                            onClick={() => {
                                const newValue = !diferenciarTitulo;
                                setDiferenciarTitulo(newValue);
                                if (!newValue) {
                                    setFormData(prev => prev ? ({
                                        ...prev,
                                        title: prev.name,
                                        marketplaceTitle: prev.name
                                    }) : null);
                                }
                            }}
                            className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-colors ${
                                diferenciarTitulo 
                                    ? 'bg-purple-100 text-purple-700 dark:bg-purple-955/40 dark:text-purple-300' 
                                    : 'bg-slate-100 text-slate-500 dark:bg-slate-800 hover:bg-slate-200'
                            }`}
                        >
                            {diferenciarTitulo ? 'Usando Título Diferente' : 'Diferenciar Título no Catálogo'}
                        </button>
                    </div>
                    {(() => {
                        const parentPrefix = (parentProduct.name || parentProduct.description || 'Produto').trim();
                        const currentFullName = formData.name || '';
                        let currentSuffix = '';
                        if (currentFullName.toLowerCase().startsWith(parentPrefix.toLowerCase())) {
                            currentSuffix = currentFullName.slice(parentPrefix.length).replace(/^[\s\-_:]+/, '');
                        } else {
                            currentSuffix = currentFullName;
                        }

                        const handleSuffixChange = (newSuffix: string) => {
                            const trimmedSuffix = newSuffix.trimStart();
                            const newFullName = trimmedSuffix ? `${parentPrefix} ${trimmedSuffix}` : parentPrefix;
                            setFormData(prev => {
                                if (!prev) return null;
                                const next: Variation = { ...prev, name: newFullName };
                                if (!diferenciarTitulo) {
                                    next.title = newFullName;
                                    next.marketplaceTitle = newFullName;
                                }
                                return next;
                            });
                        };

                        return (
                            <div 
                                className="w-full flex items-center border-b-2 border-slate-200 dark:border-slate-800 focus-within:border-blue-600 dark:focus-within:border-blue-400 transition-colors py-1.5"
                                title="O nome do produto pai é imutável no início. Você pode editar livremente o que vem após o nome do pai."
                            >
                                <span className="inline-flex items-center px-2 py-1 rounded bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 text-xs font-bold font-mono shrink-0 select-none mr-2 border border-slate-200 dark:border-slate-700">
                                    {parentPrefix}
                                </span>
                                <input
                                    type="text"
                                    placeholder="Complemento da variação (ex: Branco 6 Portas)..."
                                    value={currentSuffix}
                                    onChange={e => handleSuffixChange(e.target.value)}
                                    className="w-full bg-transparent border-none outline-none text-xs font-bold text-slate-800 dark:text-slate-100 font-mono focus:ring-0 p-0"
                                    aria-label="Sufixo do nome da variação"
                                />
                            </div>
                        );
                    })()}
                </div>

                {/* Título da Variação (Catálogo) */}
                {diferenciarTitulo ? (
                    <div className="space-y-1.5 animate-in slide-in-from-right-2 duration-200">
                        <label className="text-[10px] uppercase font-black text-slate-400 dark:text-slate-500 tracking-widest flex items-center gap-1.5 h-6">
                            <span>Título no Catálogo</span>
                        </label>
                        <input
                            type="text"
                            placeholder="Título exibido no catálogo digital..."
                            value={formData.title || formData.marketplaceTitle || ""}
                            onChange={e => setFormData({ ...formData, title: e.target.value, marketplaceTitle: e.target.value })}
                            onBlur={() => {
                                const current = formData.title || formData.marketplaceTitle || '';
                                if (current) {
                                    const formatted = toTitleCase(current);
                                    if (formatted !== current) {
                                        setFormData(prev => prev ? ({ ...prev, title: formatted, marketplaceTitle: formatted }) : null);
                                    }
                                }
                            }}
                            className="w-full px-1 py-2.5 bg-transparent border-b-2 border-t-0 border-x-0 border-slate-200 dark:border-slate-800 outline-none text-xs font-bold text-slate-800 dark:text-slate-100 focus:border-blue-600 dark:focus:border-blue-400 transition-all font-mono"
                        />
                    </div>
                ) : null}
            </div>
        </div>
    );
};

