                                            <button
                                                onClick={() => {
                                                    setIsSidebarOpen(true);
                                                    setIsActionsMenuOpen(false);
                                                }}
                                                className="w-full text-left px-4 py-2.5 text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 flex items-center gap-3 transition-colors group"
                                            >
                                                <div className="w-8 h-8 rounded-xl bg-blue-50 text-blue-600 dark:bg-blue-500/10 dark:text-blue-400 flex items-center justify-center group-hover:scale-110 transition-transform">
                                                    <i className="bi bi-funnel" />
                                                </div>
                                                Filtros
                                            </button>

                                            <div className="h-px bg-slate-100 dark:bg-slate-800 my-1 mx-4"></div>

                                            <button
                                                onClick={() => {
                                                    setFilters(prev => ({ ...prev, activeOnly: prev.activeOnly === false ? true : false }));
                                                    setIsActionsMenuOpen(false);
                                                }}
                                                className="w-full text-left px-4 py-2.5 text-sm font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 flex items-center gap-3 transition-colors group"
                                            >
                                                <div className={`w-8 h-8 rounded-xl flex items-center justify-center group-hover:scale-110 transition-transform ${filters.activeOnly === false ? 'bg-amber-50 text-amber-600 dark:bg-amber-500/10 dark:text-amber-400' : 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400'}`}>
                                                    <i className={`bi ${filters.activeOnly === false ? 'bi-eye' : 'bi-eye-slash'}`} />
                                                </div>
                                                {filters.activeOnly === false ? 'Ocultar Inativos' : 'Mostrar Inativos'}
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Section: Product Table (Esquerda) + Sidebar Direita (Sanfonada) */}
                    <div className="flex gap-6 flex-1 items-start">
                        {/* Conteúdo Principal: Tabela de Produtos (Esquerda/Centro) */}
                        <div className="flex-1 min-w-0">
                            <ProductList
                                mode={mode}
                                filters={currentFilters}
                                title={currentTitle}
                                onCloseTrash={handleCloseSpecialView}
                                visibilitySettings={visibilitySettings}
                                onEdit={(p: any) => {
                                    if (p.isVariation) {
                                        setVariationParentProduct(p);
                                        setEditingVariation(resolveProductVariation(p));
                                        setIsVariationModalOpen(true);
                                    } else {
                                        setEditingProduct(p);
                                        setIsFormModalOpen(true);
                                    }
                                }}
                                onShowHistory={(p) => { setHistoryProduct(p); setIsHistoryModalOpen(true); }}
                                onLaunchStock={(p: any) => {
                                    if (p.isVariation) {
                                        setStockLaunchTarget({ variation: resolveProductVariation(p) });
                                    } else {
                                        setStockLaunchTarget({ product: p });
                                    }
                                    setIsStockModalOpen(true);
                                }}
                                onToggleColumn={toggleVisibility}
                                onSort={handleSort}
                                categoryTree={categoryTree}
                                ref={productListRef}
                                onRefresh={() => {
                                    productListRef.current?.refresh();
                                    fetchStats();
                                }}
                            />
                        </div>

                        <div className="hidden xl:block w-80 shrink-0 bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800/80 rounded-3xl shadow-sm p-4 space-y-4">
                            
                            {/* TÓPICO 1: Resumo do Catálogo (Sanfona) */}
                            <div className="border-b border-slate-100 dark:border-slate-800 pb-3">
                                <button
                                    type="button"
                                    onClick={() => toggleAccordion('summary')}
                                    className="w-full flex items-center justify-between py-2 text-left hover:opacity-80 transition-opacity"
                                >
                                    <div className="flex items-center gap-2.5">
                                        <div className="w-8 h-8 rounded-xl bg-blue-50 dark:bg-blue-950/50 text-blue-600 dark:text-blue-400 flex items-center justify-center font-bold text-sm">
                                            <i className="bi bi-pie-chart-fill" />
                                        </div>
                                        <h4 className="text-xs font-black uppercase tracking-wider text-slate-800 dark:text-slate-100">
                                            {mode === 'composition' ? 'Resumo das Composições' : 'Resumo dos Produtos'}
                                        </h4>
                                    </div>
                                    <i className={`bi bi-chevron-down text-slate-400 text-xs transition-transform duration-200 ${accordionOpen.summary ? 'rotate-180' : ''}`} />
                                </button>

                                {accordionOpen.summary && (
                                    <div className="flex flex-col gap-2 mt-3 animate-fade-in">
                                        <button 
                                            type="button"
                                            onClick={() => { setIsTrashOpen(false); setFilters(prev => ({ ...prev, activeOnly: undefined, isDraft: undefined })); }}
                                            className="w-full p-3 bg-blue-50/70 dark:bg-blue-950/40 hover:bg-blue-100/70 dark:hover:bg-blue-900/50 rounded-2xl border border-blue-100 dark:border-blue-900/50 flex items-center justify-between transition-colors text-left"
                                        >
                                            <div className="flex items-center gap-2">
                                                <i className="bi bi-boxes text-blue-600 dark:text-blue-400 text-sm" />
                                                <span className="text-[10px] font-black uppercase tracking-wider text-blue-800 dark:text-blue-300">Total de Cadastrados</span>
                                            </div>
                                            <span className="text-base font-black text-blue-800 dark:text-blue-300">
                                                {catalogStats.total}
                                            </span>
                                        </button>

                                        <div className="grid grid-cols-2 gap-2">
                                            <button 
                                                type="button"
                                                onClick={() => { setIsTrashOpen(false); setFilters(prev => ({ ...prev, activeOnly: true, isDraft: undefined })); }}
                                                className={`p-3 rounded-2xl border text-left transition-colors ${filters.activeOnly === true && !filters.isDraft ? 'bg-emerald-50 border-emerald-300 dark:bg-emerald-950/40 dark:border-emerald-800' : 'bg-slate-50 dark:bg-slate-950/60 hover:bg-slate-100 dark:hover:bg-slate-900 border-slate-200/60 dark:border-slate-800'}`}
                                            >
                                                <span className="text-[9px] font-black uppercase text-slate-400 block">Publicados</span>
                                                <span className="text-base font-black text-emerald-600 dark:text-emerald-400 mt-0.5 block">
                                                    {catalogStats.published}
                                                </span>
                                            </button>
                                            <button 
                                                type="button"
                                                onClick={() => {
                                                    setFilters(prev => ({ ...prev, activeOnly: prev.activeOnly === false ? undefined : false, isDraft: undefined }));
                                                }}
                                                className={`p-3 rounded-2xl border text-left transition-colors ${filters.activeOnly === false ? 'bg-rose-50 border-rose-300 dark:bg-rose-950/40 dark:border-rose-800' : 'bg-slate-50 dark:bg-slate-950/60 hover:bg-slate-100 dark:hover:bg-slate-900 border-slate-200/60 dark:border-slate-800'}`}
                                            >
                                                <span className="text-[9px] font-black uppercase text-slate-400 block">Desativados</span>
                                                <span className="text-base font-black text-rose-500 dark:text-rose-400 mt-0.5 block">
                                                    {catalogStats.disabled}
                                                </span>
                                            </button>
                                            <button 
                                                type="button"
                                                onClick={() => { setFilters(prev => ({ ...prev, isDraft: prev.isDraft === true ? undefined : true, activeOnly: undefined })); }}
                                                className={`col-span-2 p-3 rounded-2xl border flex items-center justify-between text-left transition-colors ${filters.isDraft === true ? 'bg-amber-50 border-amber-300 dark:bg-amber-950/40 dark:border-amber-800 shadow-sm' : 'bg-slate-50 dark:bg-slate-950/60 hover:bg-slate-100 dark:hover:bg-slate-900 border-slate-200/60 dark:border-slate-800'}`}
                                            >
                                                <div className="flex items-center gap-2">
                                                    <i className="bi bi-file-earmark-text text-amber-500 text-sm" />
                                                    <span className="text-[9px] font-black uppercase text-slate-500 dark:text-slate-400">Rascunhos (Em Cadastro)</span>
                                                </div>
                                                <span className="text-base font-black text-amber-600 dark:text-amber-400">
                                                    {catalogStats.drafts}
                                                </span>
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* TÓPICO 2: Filtros Avançados (Sanfona) */}
                            <div className="border-b border-slate-100 dark:border-slate-800 pb-3">
                                <button
                                    type="button"
                                    onClick={() => toggleAccordion('filters')}
                                    className="w-full flex items-center justify-between py-2 text-left hover:opacity-80 transition-opacity"
                                >
                                    <div className="flex items-center gap-2.5">
                                        <div className="w-8 h-8 rounded-xl bg-purple-50 dark:bg-purple-950/50 text-purple-600 dark:text-purple-400 flex items-center justify-center font-bold text-sm">
                                            <i className="bi bi-funnel-fill" />
                                        </div>
                                        <h4 className="text-xs font-black uppercase tracking-wider text-slate-800 dark:text-slate-100">
                                            Filtros
                                        </h4>
                                    </div>
                                    <i className={`bi bi-chevron-down text-slate-400 text-xs transition-transform duration-200 ${accordionOpen.filters ? 'rotate-180' : ''}`} />
                                </button>

                                {accordionOpen.filters && (
                                    <div className="mt-3 animate-fade-in">
                                        <ProductFilters filters={filters} setFilters={setFilters} />
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Modal de Filtros para Mobile (< lg) */}
            {isSidebarOpen && (
                <div 
                    role="dialog"
                    aria-modal="true"
                    aria-labelledby="mobile-filters-title"
                    onKeyDown={(e) => { if (e.key === 'Escape') setIsSidebarOpen(false); }}
                    className="fixed inset-0 z-[150] flex items-center justify-center p-4 animate-fade-in lg:hidden"
                >
                    <button
                        type="button"
                        aria-label="Fechar filtros avançados"
                        className="absolute inset-0 bg-slate-950/60 backdrop-blur-md cursor-default border-0 p-0 m-0 w-full h-full"
                        onClick={() => setIsSidebarOpen(false)}
                    />
                    <div 
                        className="relative bg-white dark:bg-slate-900 w-full max-w-xl rounded-3xl shadow-2xl flex flex-col overflow-hidden border border-slate-200 dark:border-slate-800 animate-slide-up max-h-[90vh]"
                        onClick={(e) => e.stopPropagation()}
                    >
                        <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/50">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-2xl bg-blue-50 dark:bg-blue-950/50 text-blue-600 dark:text-blue-400 flex items-center justify-center" aria-hidden="true">
                                    <i className="bi bi-funnel-fill text-lg" />
                                </div>
                                <div>
                                    <h3 id="mobile-filters-title" className="text-sm font-black text-slate-800 dark:text-slate-100 uppercase tracking-wider">Filtros Avançados</h3>
                                </div>
                            </div>
                            <button 
                                type="button" 
                                aria-label="Fechar filtros"
                                onClick={() => setIsSidebarOpen(false)}
                                className="w-8 h-8 flex items-center justify-center hover:bg-rose-50 dark:hover:bg-rose-950/30 text-slate-400 hover:text-rose-500 rounded-xl transition-all cursor-pointer"
                            >
                                <i className="bi bi-x-lg text-sm" aria-hidden="true" />
                            </button>
                        </div>
                        <div className="p-6 overflow-y-auto custom-scrollbar">
                            <ProductFilters filters={filters} setFilters={setFilters} />
                        </div>
                        <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 flex justify-end bg-slate-50/50 dark:bg-slate-900/50">
                            <button
                                type="button"
                                onClick={() => setIsSidebarOpen(false)}
                                className="px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-md transition-all active:scale-95"
                            >
                                Aplicar Filtros
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Form Modal */}
            <ProductFormModal
                isOpen={isFormModalOpen}
                onClose={() => { setIsFormModalOpen(false); setEditingProduct(null); setInitialFormData(null); }}
                onSuccess={() => {
                    productListRef.current?.refresh();
                    trashListRef.current?.refresh();
                    fetchStats();
                }}
                product={editingProduct}
                initialData={initialFormData}
            />

            <PriceHistoryModal
                isOpen={isHistoryModalOpen}
                onClose={() => { setIsHistoryModalOpen(false); setHistoryProduct(null); }}
                product={historyProduct}
            />

            <VariationFormModal
                isOpen={isVariationModalOpen}
                onClose={() => {
                    setIsVariationModalOpen(false);
                    setEditingVariation(null);
                    setVariationParentProduct(null);
                    productListRef.current?.refresh();
                    fetchStats();
                }}
                parentId={variationParentProduct?.parentId || ""}
                parentProduct={variationParentProduct || {} as any}
                variation={editingVariation}
            />

            <StockLaunchModal
                isOpen={isStockModalOpen}
                onClose={() => { setIsStockModalOpen(false); setStockLaunchTarget(null); }}
                targetProduct={stockLaunchTarget?.product || null}
                targetVariation={stockLaunchTarget?.variation}
            />
        </div>
    );
};

export default Products;

import React, { useState, useEffect, useCallback } from 'react';
import { formatCurrency, formatDateTime } from '@/pages/utils/formatters';
import Product from '@/pages/types/product.type';
import { updateInventoryMove } from '@/pages/utils/inventoryService';
import { toast } from 'react-toastify';
import { InventoryMoveEntry, PriceHistoryEntry, loadBatchHistory, loadPriceHistory } from '../priceHistory';

interface PriceHistoryModalProps {
    readonly product?: Product | null;
    readonly isOpen: boolean;
    readonly onClose: () => void;
}

export const PriceHistoryModal: React.FC<PriceHistoryModalProps> = ({ product, isOpen, onClose }) => {
    const [activeTab, setActiveTab] = useState<'prices' | 'batches'>('prices');
    const [priceHistory, setPriceHistory] = useState<PriceHistoryEntry[]>([]);
    const [batchHistory, setBatchHistory] = useState<InventoryMoveEntry[]>([]);
    const [loading, setLoading] = useState(true);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editCost, setEditCost] = useState<number>(0);
    const [editQty, setEditQty] = useState<number>(0);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                onClose();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, onClose]);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            if (activeTab === 'prices') {
                const prices = await loadPriceHistory(product?.id);
                setPriceHistory(prices);
            } else {
                const batches = await loadBatchHistory(product?.id);
                setBatchHistory(batches);
            }
        } catch (err: unknown) {
            console.error('[PriceHistoryModal] Erro ao buscar históricos:', err);
            toast.error('Erro ao carregar dados do histórico.');
        } finally {
            setLoading(false);
        }
    }, [activeTab, product?.id]);

    useEffect(() => {
        if (!isOpen) return;
        void fetchData();
    }, [isOpen, fetchData]);

    if (!isOpen) return null;

    const currentListCount = (activeTab === 'prices' ? priceHistory : batchHistory).length;

    return (
        <div 
            className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in" 
            onClick={onClose}
        >
            <div
                role="dialog"
                aria-modal="true"
                aria-labelledby="price-history-modal-title"
                className="bg-white dark:bg-slate-900 w-full max-w-4xl h-[85vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-slide-up border border-slate-100 dark:border-slate-800"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header */}
                <div className="px-8 pt-8 pb-4 border-b border-slate-100 dark:border-slate-800 bg-blue-50/50 dark:bg-blue-900/5 transition-all">
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-4">
                            <div className="bg-blue-600 p-2.5 rounded-2xl shadow-lg shadow-blue-200 dark:shadow-none">
                                <i className="bi bi-clock-history text-white text-xl" aria-hidden="true" />
                            </div>
                            <div>
                                <h2 id="price-history-modal-title" className="text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                    Históricos
                                </h2>
                                <p className="text-[10px] uppercase font-black text-blue-600 dark:text-blue-400 tracking-widest mt-0.5">
                                    {product ? `Produto: ${product.description}` : 'Auditoria Geral'}
                                </p>
                            </div>
                        </div>
                        <button 
                            type="button"
                            onClick={onClose} 
                            aria-label="Fechar modal"
                            className="w-10 h-10 flex items-center justify-center bg-white dark:bg-slate-800 hover:bg-red-50 dark:hover:bg-red-900/20 text-slate-400 hover:text-red-500 rounded-xl transition-all border border-slate-100 dark:border-slate-700 cursor-pointer"
                        >
                            <i className="bi bi-x-lg text-lg" aria-hidden="true" />
                        </button>
                    </div>

                    {/* Tabs */}
                    <div className="flex gap-2 p-1.5 bg-slate-100 dark:bg-slate-800 rounded-2xl w-fit" role="tablist" aria-label="Abas de histórico">
                        <button
                            type="button"
                            role="tab"
                            aria-selected={activeTab === 'prices'}
                            onClick={() => setActiveTab('prices')}
                            className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all cursor-pointer ${
                                activeTab === 'prices' 
                                ? 'bg-white dark:bg-slate-700 text-blue-600 dark:text-blue-400 shadow-sm' 
                                : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
                            }`}
                        >
                            <i className="bi bi-tags-fill mr-2" aria-hidden="true" />
                            Preços de Venda
                        </button>
                        <button
                            type="button"
                            role="tab"
                            aria-selected={activeTab === 'batches'}
                            onClick={() => setActiveTab('batches')}
                            className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all cursor-pointer ${
                                activeTab === 'batches' 
                                ? 'bg-white dark:bg-slate-700 text-emerald-600 dark:text-emerald-400 shadow-sm' 
                                : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'
                            }`}
                        >
                            <i className="bi bi-box-fill mr-2" aria-hidden="true" />
                            Entradas (Lotes/Custo)
                        </button>
                    </div>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto custom-scrollbar bg-white dark:bg-slate-900">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center py-24 gap-4">
                            <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
                            <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Carregando histórico...</p>
                        </div>
                    ) : currentListCount === 0 ? (
                        <div className="flex flex-col items-center justify-center py-24 gap-4 opacity-30">
                            <i className={`bi ${activeTab === 'prices' ? 'bi-journal-x' : 'bi-box-seam'} text-5xl text-slate-400`} aria-hidden="true" />
                            <p className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Nenhum registro encontrado</p>
                        </div>
                    ) : (
                        <table className="w-full text-left">
                            <thead className="sticky top-0 bg-slate-50/80 dark:bg-slate-800/80 backdrop-blur-md z-10 border-b border-slate-100 dark:border-slate-700">
                                <tr>
                                    <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400">Data e Hora</th>
                                    {activeTab === 'prices' ? (
                                        <>
                                            {!product && <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400">Produto</th>}
                                            <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400 text-right">Novo Preço</th>
                                            <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400 text-right">Novo Custo</th>
                                            <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400 text-center">Alteração</th>
                                        </>
                                    ) : (
                                        <>
                                            <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400 text-right">Quantidade</th>
                                            <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400 text-right">Custo do Lote</th>
                                            <th scope="col" className="px-8 py-4 text-[9px] font-black uppercase tracking-widest text-slate-400">Etiqueta/Obs</th>
                                        </>
                                    )}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                {activeTab === 'prices' 
                                    ? priceHistory.map((entry) => (
                                        <tr key={entry.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                                            <td className="px-8 py-5 whitespace-nowrap">
                                                <span className="text-xs text-slate-600 dark:text-slate-400 font-bold">
                                                    {formatDateTime(entry.changed_at)}
                                                </span>
                                            </td>
                                            {!product && (
                                                <td className="px-8 py-5">
                                                    <span className="text-xs font-black text-slate-700 dark:text-slate-200 uppercase tracking-tight">{entry.product_description}</span>
                                                </td>
                                            )}
                                            <td className="px-8 py-5 text-right">
                                                <div className="flex flex-col items-end">
                                                    <span className="text-xs font-black text-blue-600 dark:text-blue-400">
                                                        {formatCurrency(entry.new_unit_price)}
                                                    </span>
                                                    {entry.old_unit_price !== entry.new_unit_price && (
                                                        <span className="text-[9px] text-slate-400 line-through">
                                                            {formatCurrency(entry.old_unit_price)}
                                                        </span>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-8 py-5 text-right">
                                                <div className="flex flex-col items-end">
                                                    <span className="text-xs font-black text-emerald-600 dark:text-emerald-400">
                                                        {formatCurrency(entry.new_cost_price)}
                                                    </span>
                                                    {entry.old_cost_price !== entry.new_cost_price && (
                                                        <span className="text-[9px] text-slate-400 line-through">
                                                            {formatCurrency(entry.old_cost_price)}
                                                        </span>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-8 py-5 text-center">
                                                <span className={`px-2 py-1 rounded-lg text-[8px] font-black uppercase tracking-widest ${
                                                    entry.change_type === 'unit_price' ? 'bg-blue-100 text-blue-600' :
                                                    entry.change_type === 'cost_price' ? 'bg-emerald-100 text-emerald-600' :
                                                    'bg-indigo-100 text-indigo-600'
                                                }`}>
                                                    {entry.change_type === 'unit_price' ? 'Venda' : entry.change_type === 'cost_price' ? 'Custo' : 'Ambos'}
                                                </span>
                                            </td>
                                        </tr>
                                    ))
                                    : batchHistory.map((entry) => (
                                        <tr key={entry.id} className={`hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors ${editingId === entry.id ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}>
                                            <td className="px-8 py-5 whitespace-nowrap">
                                                <span className="text-xs text-slate-600 dark:text-slate-400 font-bold">
                                                    {formatDateTime(entry.date)}
                                                </span>
                                            </td>
                                            <td className="px-8 py-5 text-right">
                                                {editingId === entry.id ? (
                                                    <input 
                                                        type="number" 
                                                        aria-label="Editar quantidade"
                                                        value={editQty}
                                                        onChange={(e) => setEditQty(Number(e.target.value))}
                                                        className="w-20 bg-white dark:bg-slate-800 border border-blue-200 dark:border-blue-800 rounded px-2 py-1 text-right text-xs font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                                                    />
                                                ) : (
                                                    <div className="flex flex-col items-end">
                                                        <span className="text-xs font-black text-slate-800 dark:text-slate-100">
                                                            {entry.quantity} un
                                                        </span>
                                                        <span className={`text-[9px] font-bold ${entry.balance && entry.balance > 0 ? 'text-emerald-500' : 'text-slate-400'}`}>
                                                            {entry.balance} dispon.
                                                        </span>
                                                    </div>
                                                )}
                                            </td>
                                            <td className="px-8 py-5 text-right">
                                                {editingId === entry.id ? (
                                                    <div className="flex items-center justify-end gap-1">
                                                        <span className="text-[10px] font-black text-slate-400">R$</span>
                                                        <CurrencyInput
                                                            value={editCost}
                                                            onChangeValue={(val) => setEditCost(val)}
                                                            showBadge={false}
                                                            className="w-24 bg-white dark:bg-slate-800 border border-emerald-200 dark:border-emerald-800 rounded px-2 py-1 text-right text-xs font-bold text-emerald-600 focus:ring-2 focus:ring-emerald-500 outline-none"
                                                        />
                                                    </div>
                                                ) : (
                                                    <span className="text-emerald-600 dark:text-emerald-400 font-black text-sm">
                                                        {formatCurrency(entry.unit_cost || 0)}
                                                    </span>
                                                )}
                                            </td>
                                            <td className="px-8 py-5">
                                                <div className="flex items-center justify-between gap-4">
                                                    <div className="flex flex-col gap-1">
                                                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">{entry.label}</span>
                                                        {entry.observation && <p className="text-[10px] text-slate-400 italic">{entry.observation}</p>}
                                                    </div>
                                                    
                                                    <div className="flex items-center gap-2">
                                                        {editingId === entry.id ? (
                                                            <>
                                                                <button 
                                                                    type="button"
                                                                    onClick={async () => {
                                                                        setIsSaving(true);
                                                                        try {
                                                                            await updateInventoryMove(entry.id, {
                                                                                quantity: editQty,
                                                                                unitCost: editCost
                                                                            });
                                                                            toast.success('Lote atualizado com sucesso!');
                                                                            setEditingId(null);
                                                                            await fetchData();
                                                                        } catch (err: unknown) {
                                                                            console.error('[PriceHistoryModal] Erro ao atualizar lote:', err);
                                                                            toast.error('Erro ao atualizar lote.');
                                                                        } finally {
                                                                            setIsSaving(false);
                                                                        }
                                                                    }}
                                                                    disabled={isSaving}
                                                                    className="p-2 bg-emerald-500 text-white rounded-lg hover:bg-emerald-600 transition-colors shadow-lg shadow-emerald-100 dark:shadow-none cursor-pointer"
                                                                    title="Confirmar"
                                                                >
                                                                    {isSaving ? (
                                                                        <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                                                    ) : (
                                                                        <i className="bi bi-check-lg" aria-hidden="true" />
                                                                    )}
                                                                </button>
                                                                <button 
                                                                    type="button"
                                                                    onClick={() => setEditingId(null)}
                                                                    className="p-2 bg-slate-100 dark:bg-slate-700 text-slate-500 rounded-lg hover:bg-slate-200 cursor-pointer"
                                                                    title="Cancelar"
                                                                >
                                                                    <i className="bi bi-x-lg" aria-hidden="true" />
                                                                </button>
                                                            </>
                                                        ) : (
                                                            <button 
                                                                type="button"
                                                                onClick={() => {
                                                                    setEditingId(entry.id);
                                                                    setEditCost(entry.unit_cost || 0);
                                                                    setEditQty(entry.quantity);
                                                                }}
                                                                className="p-2 bg-slate-50 dark:bg-slate-800 text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-all cursor-pointer"
                                                                title="Editar Lote"
                                                            >
                                                                <i className="bi bi-pencil-square" aria-hidden="true" />
                                                            </button>
                                                        )}
                                                    </div>
                                                </div>
                                            </td>
                                        </tr>
                                    ))
                                }
                            </tbody>
                        </table>
                    )}
                </div>

                {/* Footer */}
                <div className="px-8 py-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 shrink-0 flex justify-between items-center">
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">
                        Total: {currentListCount} registros
                    </p>
                    <p className="text-[10px] text-slate-300 dark:text-slate-600 font-bold uppercase tracking-tight">
                        Rastreabilidade Morante Hub v2.0
                    </p>
                </div>
            </div>
            <style dangerouslySetInnerHTML={{ __html: `
                @keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
                @keyframes slide-up { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
                .animate-fade-in { animation: fade-in 0.2s ease-out forwards; }
                .animate-slide-up { animation: slide-up 0.3s cubic-bezier(0, 0, 0.2, 1) forwards; }
            `}} />
        </div>
    );
};

export default PriceHistoryModal;

import React from 'react';
import { useMergeVariation } from './MergeVariation/useMergeVariation';

export interface VariationOption {
    readonly id: string;
    readonly name: string;
    readonly sku?: string | null;
    readonly product?: {
        readonly name?: string | null;
        readonly description?: string | null;
    } | null;
}

export interface MergeVariationModalProps {
    readonly variation: {
        readonly variationId?: string;
        readonly id?: string;
        readonly name?: string;
        readonly sku?: string;
        readonly parentId?: string;
        readonly supplierId?: string;
    } | null;
    readonly onClose: () => void;
    readonly onMerged: () => void;
}

export const MergeVariationModal: React.FC<MergeVariationModalProps> = ({ variation, onClose, onMerged }) => {
    const {
        query,
        setQuery,
        options,
        setOptions,
        target,
        setTarget,
        saving,
        sourceId,
        confirm,
        handleCancel
    } = useMergeVariation(variation, onMerged, onClose);

    if (!variation) return null;
    const sourceLabel = variation.name || variation.sku || sourceId;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center">
            {/* Backdrop com blur dinâmico */}
            <div
                className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity"
                onClick={handleCancel}
                aria-hidden="true"
            />
            <div
                className="relative w-full max-w-2xl rounded-3xl bg-white shadow-2xl dark:bg-slate-900 border border-slate-100 dark:border-slate-800 overflow-hidden z-10 m-4"
                role="dialog"
                aria-modal="true"
                aria-labelledby="merge-variation-title"
            >
                <div className="flex items-start justify-between gap-4 border-b border-slate-100 p-6 dark:border-slate-800">
                    <div>
                        <h2 id="merge-variation-title" className="text-lg font-black text-slate-800 dark:text-white">
                            Mesclar com outra variação
                        </h2>
                        <p className="mt-1 text-xs text-slate-500">
                            “{sourceLabel}” continuará com seu UUID histórico e passará a apontar para a variação canônica.
                        </p>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-2 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors cursor-pointer"
                        aria-label="Fechar"
                    >
                        <i className="bi bi-x-lg text-base" />
                    </button>
                </div>

                <div className="space-y-4 p-6">
                    <div className="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-xs font-semibold text-amber-900 dark:border-amber-900/40 dark:bg-amber-950/30 dark:text-amber-300">
                        <i className="bi bi-shield-check mr-2 text-amber-600" />
                        Movimentações, recebimentos, quantidades, custos e fornecedor histórico não serão alterados.
                    </div>

                    <div>
                        <label className="text-xs font-black uppercase tracking-wider text-slate-700 dark:text-slate-300">
                            Variação canônica de destino
                        </label>
                        <div className="relative mt-2">
                            <input
                                autoFocus
                                value={query}
                                onChange={(e) => {
                                    setQuery(e.target.value);
                                    setTarget(null);
                                }}
                                placeholder="Pesquise por nome ou SKU..."
                                className={`w-full border-b-2 px-2 py-2.5 text-sm bg-transparent focus:outline-none transition-colors pr-10 ${
                                    target 
                                        ? 'border-emerald-500 text-emerald-600 dark:text-emerald-400 font-bold focus:border-emerald-500' 
                                        : 'border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white focus:border-blue-500 dark:focus:border-blue-500'
                                }`}
                            />
                            {target && (
                                <i className="bi bi-check-lg absolute right-3 top-1/2 -translate-y-1/2 text-emerald-500 text-lg font-bold" />
                            )}
                        </div>

                        {!target && query.trim().length >= 2 && (
                            <div className="mt-2 max-h-56 overflow-auto rounded-xl border border-slate-200 dark:border-slate-700 divide-y divide-slate-100 dark:divide-slate-800 shadow-lg">
                                {options.map((option) => (
                                    <button
                                        type="button"
                                        key={option.id}
                                        onClick={() => {
                                            setTarget(option);
                                            setQuery(option.name);
                                            setOptions([]);
                                        }}
                                        className="flex w-full flex-col p-3 text-left hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors cursor-pointer"
                                    >
                                        <span className="font-bold text-sm text-slate-800 dark:text-white">
                                            {option.name}
                                        </span>
                                        <span className="text-xs text-slate-500">
                                            {option.product?.name || option.product?.description || 'Produto pai'} {option.sku ? `• SKU: ${option.sku}` : ''}
                                        </span>
                                    </button>
                                ))}
                                {options.length === 0 && (
                                    <p className="p-4 text-xs text-slate-500 text-center font-medium">
                                        Nenhuma variação encontrada.
                                    </p>
                                )}
                            </div>
                        )}
                    </div>
                </div>

                <div className="flex justify-end gap-3 border-t border-slate-100 p-6 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
                    <button
                        type="button"
                        onClick={handleCancel}
                        disabled={saving}
                        className="rounded-xl px-5 py-2.5 text-xs font-black uppercase tracking-wider text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800 transition-colors cursor-pointer"
                    >
                        Cancelar
                    </button>
                    <button
                        type="button"
                        disabled={!target || saving}
                        onClick={confirm}
                        className="rounded-xl bg-indigo-600 hover:bg-indigo-700 px-5 py-2.5 text-xs font-black uppercase tracking-wider text-white disabled:opacity-40 transition-all shadow-md shadow-indigo-600/20 cursor-pointer"
                    >
                        {saving ? 'Mesclando…' : 'Confirmar mesclagem'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default MergeVariationModal;

import React from 'react';
import { Attribute } from './utils';

interface AttributeConflictResolverProps {
    readonly hasConflict: boolean;
    readonly attributes: Attribute[];
    readonly onAddAttribute: () => void;
    readonly onUpdateAttribute: (index: number, field: 'name' | 'value', value: string) => void;
}

export const AttributeConflictResolver: React.FC<AttributeConflictResolverProps> = ({
    hasConflict,
    attributes,
    onAddAttribute,
    onUpdateAttribute
}) => {
    if (!hasConflict) return null;

    return (
        <div className="rounded-2xl border border-red-200 bg-red-50 p-4 dark:border-red-900/60 dark:bg-red-950/30">
            <p className="text-xs font-bold text-red-800 dark:text-red-200">
                Já existe uma variação neste produto pai com esta mesma combinação de atributos.
            </p>
            <p className="mt-1 text-xs text-red-700 dark:text-red-300">
                Escolha um novo atributo ou valor antes de continuar.
            </p>
            <div className="mt-3 space-y-2">
                {attributes.length === 0 ? (
                    <button
                        type="button"
                        onClick={onAddAttribute}
                        className="rounded-lg bg-red-100 px-3 py-1.5 text-xs font-bold text-red-700 hover:bg-red-200 dark:bg-red-900/50 dark:text-red-300 dark:hover:bg-red-900 cursor-pointer"
                    >
                        <i className="bi bi-plus-lg mr-1" /> Adicionar atributo
                    </button>
                ) : (
                    attributes.map((attribute, index) => (
                        <div className="grid grid-cols-2 gap-2" key={`${attribute.name}-${index}`}>
                            <input
                                value={attribute.name}
                                onChange={(event) => onUpdateAttribute(index, 'name', event.target.value)}
                                placeholder="Atributo (Ex: Cor)"
                                className="rounded-xl border border-red-200 bg-white px-3 py-2 text-xs dark:border-red-900 dark:bg-slate-900 focus:outline-none focus:border-red-400"
                            />
                            <input
                                value={attribute.value}
                                onChange={(event) => onUpdateAttribute(index, 'value', event.target.value)}
                                placeholder="Valor (Ex: Azul)"
                                className="rounded-xl border border-red-200 bg-white px-3 py-2 text-xs dark:border-red-900 dark:bg-slate-900 focus:outline-none focus:border-red-400"
                            />
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { Family, familyName, familySku, normalize } from './utils';

interface FamilySearchSelectorProps {
    readonly families: readonly Family[];
    readonly targetFamilyId: string;
    readonly setTargetFamilyId: (id: string) => void;
}

export const FamilySearchSelector: React.FC<FamilySearchSelectorProps> = ({
    families,
    targetFamilyId,
    setTargetFamilyId
}) => {
    const [familySearch, setFamilySearch] = useState('');
    const [isFamilySuggestionsOpen, setIsFamilySuggestionsOpen] = useState(false);

    const normalizedFamilySearch = normalize(familySearch);
    const familySuggestions =
        normalizedFamilySearch.length >= 2
            ? families
                  .filter((family) =>
                      `${familyName(family)} ${familySku(family)}`
                          .toLocaleLowerCase('pt-BR')
                          .includes(normalizedFamilySearch)
                  )
                  .slice(0, 8)
            : [];

    return (
        <div className="relative z-50">
            <label htmlFor="new-family-search" className="block text-xs font-black uppercase tracking-wider text-slate-700 dark:text-slate-200">
                Novo produto pai
            </label>
            <div className="relative mt-2">
                <input
                    id="new-family-search"
                    value={familySearch}
                    onChange={(event) => {
                        setFamilySearch(event.target.value);
                        if (targetFamilyId) setTargetFamilyId('');
                        setIsFamilySuggestionsOpen(true);
                    }}
                    onFocus={() => setIsFamilySuggestionsOpen(true)}
                    placeholder="Digite ao menos 2 letras do nome ou código do produto pai..."
                    autoComplete="off"
                    className={`w-full rounded-none border-0 border-b-2 border-slate-200 bg-transparent py-4 pl-4 pr-12 text-base font-medium outline-none transition-all placeholder:text-slate-400 focus:border-indigo-500 focus:ring-0 dark:border-slate-700 dark:text-slate-100 ${
                        targetFamilyId ? 'text-emerald-600 dark:text-emerald-400 font-bold border-emerald-500 dark:border-emerald-500/50' : ''
                    }`}
                />
                {targetFamilyId && (
                    <i className="bi bi-check-lg absolute right-3 top-1/2 -translate-y-1/2 text-emerald-500 text-lg font-bold" />
                )}
            </div>
            {isFamilySuggestionsOpen && !targetFamilyId && normalizedFamilySearch.length >= 2 && (
                <div className="absolute z-[10060] mt-1 w-full overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl dark:border-slate-700 dark:bg-slate-900 divide-y divide-slate-100 dark:divide-slate-800">
                    {familySuggestions.length > 0 ? (
                        familySuggestions.map((family) => (
                            <button
                                type="button"
                                key={family.id}
                                onMouseDown={(event) => event.preventDefault()}
                                onClick={() => {
                                    setTargetFamilyId(family.id);
                                    setFamilySearch(`${familyName(family)}${familySku(family) ? ` — ${familySku(family)}` : ''}`);
                                    setIsFamilySuggestionsOpen(false);
                                }}
                                className="flex w-full flex-col px-4 py-3 text-left hover:bg-indigo-50 dark:hover:bg-slate-800 transition-colors cursor-pointer"
                            >
                                <span className="text-sm font-bold text-slate-800 dark:text-slate-100">
                                    {familyName(family)}
                                </span>
                                <span className="text-xs text-slate-500 dark:text-slate-400">
                                    Código: {familySku(family) || 'não informado'}
                                </span>
                            </button>
                        ))
                    ) : (
                        <p className="p-4 text-xs text-slate-500 text-center font-medium">
                            Nenhum produto pai encontrado.
                        </p>
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { supabase } from '@/pages/utils/supabaseConfig';
import { toast } from "react-toastify";

interface ProductType {
    id: string;
    name: string;
    created_at?: string;
}

const ProductTypes = () => {
    const [types, setTypes] = useState<ProductType[]>([]);
    const [newName, setNewName] = useState('');
    const [loading, setLoading] = useState(false);
    const [fetching, setFetching] = useState(false);

    const fetchTypes = async () => {
        setFetching(true);
        try {
            const { data, error } = await supabase
                .from('product_types')
                .select('*')
                .order('name', { ascending: true });
            
            if (error) {
                console.error("Erro ao buscar tipos:", error);
            } else {
                setTypes(data || []);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setFetching(false);
        }
    };

    useEffect(() => {
        fetchTypes();
    }, []);

    const handleAdd = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newName.trim()) return;

        setLoading(true);
        try {
            const { error } = await supabase
                .from('product_types')
                .insert([{ name: newName.trim().toUpperCase() }]);

            if (error) throw error;
            
            setNewName('');
            toast.success("Tipo adicionado!");
            fetchTypes();
        } catch (error: any) {
            toast.error("Erro ao adicionar tipo.");
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Tem certeza que deseja remover este tipo?")) return;

        try {
            const { error } = await supabase
                .from('product_types')
                .delete()
                .eq('id', id);

            if (error) throw error;
            toast.success("Tipo removido!");
            fetchTypes();
        } catch (error) {
            toast.error("Erro ao remover tipo.");
            console.error(error);
        }
    };

    return (
        <div className="p-4 md:p-8 flex flex-col gap-8 max-w-4xl mx-auto w-full animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex flex-col gap-2">
                <h1 className="text-3xl font-black text-slate-800 dark:text-slate-100 tracking-tight flex items-center gap-3">
                    <i className="bi bi-tag-fill text-blue-600"></i>
                    Gestão de Tipos de Móveis
                </h1>
                <p className="text-xs font-bold uppercase tracking-widest text-slate-400">
                    PADRONIZE OS PREFIXOS DOS TÍTULOS DOS SEUS PRODUTOS
                </p>
            </div>

            <div className="bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-slate-800 p-8 shadow-premium-lg flex flex-col gap-8">
                <form onSubmit={handleAdd} className="flex flex-col md:flex-row gap-4">
                    <div className="flex-1 relative">
                        <i className="bi bi-plus-circle absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"></i>
                        <input 
                            type="text"
                            value={newName}
                            onChange={(e) => setNewName(e.target.value)}
                            placeholder="EX: BALCÃO DE PIA, TORRE QUENTE, ARMÁRIO..."
                            className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none text-sm font-black focus:ring-4 focus:ring-blue-500/10 uppercase tracking-tight transition-all"
                        />
                    </div>
                    <button 
                        type="submit"
                        disabled={loading}
                        className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-blue-500/20 hover:bg-blue-700 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {loading ? (
                            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                        ) : (
                            <i className="bi bi-plus-lg"></i>
                        )}
                        Adicionar Novo Tipo
                    </button>
                </form>

                <div className="space-y-3">
                    <div className="flex items-center justify-between px-4">
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Tipos Cadastrados</span>
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{types.length} Itens</span>
                    </div>

                    {fetching ? (
                        <div className="py-20 text-center">
                            <div className="w-10 h-10 border-4 border-blue-600/30 border-t-blue-600 rounded-full animate-spin mx-auto mb-4" />
                            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 animate-pulse">Carregando...</p>
                        </div>
                    ) : types.length === 0 ? (
                        <div className="py-20 text-center bg-slate-50/50 dark:bg-slate-950/20 rounded-3xl border border-dashed border-slate-200 dark:border-slate-800">
                            <i className="bi bi-inbox text-4xl text-slate-200 dark:text-slate-800 mb-4 block"></i>
                            <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 italic">Nenhum tipo cadastrado ainda.</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            {types.map(t => (
                                <div key={t.id} className="flex items-center justify-between p-5 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl group hover:border-blue-200 dark:hover:border-blue-900/50 hover:shadow-premium-sm transition-all animate-in fade-in duration-300">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-xl bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 flex items-center justify-center font-black text-xs">
                                            {t.name.charAt(0)}
                                        </div>
                                        <span className="text-sm font-black text-slate-700 dark:text-slate-200 tracking-tight">{t.name}</span>
                                    </div>
                                    <button 
                                        onClick={() => handleDelete(t.id)}
                                        className="w-10 h-10 rounded-xl flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 md:opacity-0 group-hover:opacity-100 transition-all"
                                        title="Remover este tipo"
                                    >
                                        <i className="bi bi-trash-fill text-sm"></i>
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            <div className="p-8 bg-amber-50/50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/30 rounded-[2.5rem] flex items-start gap-4">
                <i className="bi bi-info-circle-fill text-amber-600 mt-1"></i>
                <div>
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-amber-800 dark:text-amber-400 mb-1">Dica de Gestão</h4>
                    <p className="text-[11px] text-amber-700/80 dark:text-amber-400/70 font-bold leading-relaxed">
                        Mantenha os nomes curtos e em letras maiúsculas para que os títulos dos produtos fiquem padronizados no catálogo e e-commerce. Ex: use "BALCÃO" em vez de "Balcão para cozinha".
                    </p>
                </div>
            </div>
        </div>
    );
};

export default ProductTypes;

import React, { useState, useEffect } from 'react';
import { ReconciliationFilterState, PendencyType } from '../types/reconciliation.types';
import CategoryAutocomplete from '../../../../../components/CategoryAutocomplete';

interface Props {
    filters: ReconciliationFilterState;
    onChange: (filters: ReconciliationFilterState) => void;
}

const INPUT_BASE = "w-full h-11 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl text-xs sm:text-sm font-semibold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 transition-all placeholder:font-normal placeholder:text-slate-400";

export const ReconciliationFiltersBar: React.FC<Props> = ({ filters, onChange }) => {
    const [searchTerm, setSearchTerm] = useState(filters.search || '');

    useEffect(() => {
        const timer = setTimeout(() => {
            if (searchTerm !== (filters.search || '')) {
                onChange({ ...filters, search: searchTerm || undefined });
            }
        }, 400);
        return () => clearTimeout(timer);
    }, [searchTerm]); // eslint-disable-line react-hooks/exhaustive-deps

    const hasActiveFilters = Boolean(
        (filters.pendencyType && filters.pendencyType !== 'all') ||
        filters.categoryId ||
        filters.supplierId ||
        filters.onlyCritical ||
        searchTerm
    );

    const handleClearFilters = () => {
        setSearchTerm('');
        onChange({});
    };

    return (
        <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm p-3 sm:p-4 mb-6">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-[1.2fr_1.5fr_2fr] gap-3 items-end">
                {/* 1. Tipo de Pendência */}
                <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest ml-1">
                        Tipo de Pendência
                    </label>
                    <select
                        value={filters.pendencyType || 'all'}
                        onChange={(e) => onChange({ ...filters, pendencyType: e.target.value as any })}
                        className={`${INPUT_BASE} px-3 cursor-pointer`}
                    >
                        <option value="all">Todas as pendências</option>
                        <option value="supplier">Sem fornecedores</option>
                        <option value="category">Sem categoria</option>
                        <option value="ncm">NCM ausente ou inválido</option>
                        <option value="attributes">Atributos obrigatórios / vazios</option>
                        <option value="price">Sem preço de venda</option>
                    </select>
                </div>

                {/* 2. Categoria */}
                <div className="flex flex-col gap-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest ml-1">
                        Categoria
                    </label>
                    <CategoryAutocomplete
                        selectedIds={filters.categoryId ? [filters.categoryId] : []}
