import React, { useState, useCallback } from 'react';
import { supabase } from '../../../../utils/supabaseConfig';
import Person from '../../../../types/person.type';

interface Props {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: (supplierId: string, replaceExisting: boolean) => Promise<void>;
    selectedCount: number;
    isAllFilteredSelected: boolean;
    totalFilteredCount: number;
}

export const ApplySupplierModal: React.FC<Props> = ({
    isOpen,
    onClose,
    onConfirm,
    selectedCount,
    isAllFilteredSelected,
    totalFilteredCount,
}) => {
    const [selectedSupplierId, setSelectedSupplierId] = useState<string>('');
    const [suppliers, setSuppliers] = useState<Person[]>([]);
    const [isSearching, setIsSearching] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // Busca fornecedores do Supabase com debounce embutido no hook do componente
    const searchSuppliers = useCallback(async (term: string) => {
        if (!term || term.trim().length < 2) {
            setSuppliers([]);
            return;
        }
        setIsSearching(true);
        try {
            const safe = term.replace(/"/g, '');
            const { data, error } = await supabase
                .from('people')
                .select('id, full_name, social_name, nickname, cpf_cnpj')
                .or(`full_name.ilike."%${safe}%",social_name.ilike."%${safe}%"`)
                .or('person_type.ilike.suppliers,person_type.ilike.supplier')
                .eq('deleted', false)
                .order('full_name')
                .limit(20);

            if (error) throw error;

            const mapped: Person[] = (data || []).map((p: any) => ({
                id: p.id,
                fullName: p.full_name || '',
                tradeName: p.social_name || p.nickname || '',
                cpfCnpj: p.cpf_cnpj || '',
            }));
            setSuppliers(mapped);
        } catch {
            setSuppliers([]);
        } finally {
            setIsSearching(false);
        }
    }, []);

    // Watcher de mudança de query — chamado pelo handleInputChange do hook interno
    // Precisamos interceptar o onSelect e antes disso fazer a busca
    const handleQueryChange = useCallback((term: string) => {
        searchSuppliers(term);
    }, [searchSuppliers]);

    if (!isOpen) return null;

    const affectedCount = isAllFilteredSelected ? totalFilteredCount : selectedCount;

    const handleConfirm = async () => {
        if (!selectedSupplierId) return;
        setIsSubmitting(true);
        try {
            // replaceExisting = false fixo: sempre adiciona sem substituir fornecedores existentes
            await onConfirm(selectedSupplierId, false);
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleSelect = (id: string) => {
        setSelectedSupplierId(id);
        if (!id) setSuppliers([]);
    };

    return (
        <div className="fixed inset-0 z-[99999] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-fade-in">
            <div className="bg-white dark:bg-slate-900 w-full max-w-md rounded-3xl shadow-2xl overflow-visible border border-slate-200 dark:border-slate-800 animate-slide-up">

                {/* Header */}
                <div className="px-6 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-2xl bg-purple-50 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400 flex items-center justify-center">
                            <i className="bi bi-magic text-lg"></i>
                        </div>
                        <div>
                            <h3 className="text-sm font-black uppercase tracking-wider text-slate-800 dark:text-slate-100">
                                Atribuir Fornecedor
                            </h3>
                            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-0.5">
                                Operação em lote
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        disabled={isSubmitting}
                        className="w-8 h-8 flex items-center justify-center rounded-xl text-slate-400 hover:bg-slate-100 hover:text-slate-600 transition-colors disabled:opacity-50"
                    >
                        <i className="bi bi-x-lg"></i>
                    </button>
                </div>

                <div className="p-6 space-y-6">
                    {/* Contador */}
                    <div className="bg-slate-50 dark:bg-slate-950 rounded-2xl p-4 border border-slate-200 dark:border-slate-800 flex items-center gap-4">
                        <div className="w-12 h-12 rounded-xl bg-blue-100 dark:bg-blue-900/40 text-blue-600 dark:text-blue-400 flex items-center justify-center shrink-0">
                            <span className="text-lg font-black">{affectedCount}</span>
                        </div>
                        <div>
                            <p className="text-sm font-bold text-slate-700 dark:text-slate-200">
                                Produtos selecionados
                            </p>
                            <p className="text-[11px] text-slate-500 font-medium leading-tight mt-0.5">
                                {isAllFilteredSelected
                                    ? 'Você selecionou todos os resultados do filtro atual.'
                                    : 'Você selecionou produtos manualmente nesta página.'}
                            </p>
                        </div>
                    </div>

                    {/* Campo de busca do fornecedor */}
                    <div className="space-y-2">
                        <label className="text-[11px] font-black uppercase text-slate-500 tracking-widest ml-1">
                            Fornecedor a atribuir
                        </label>

                        {/*
                          SupplierSearchField: input com busca live no Supabase.
                          Passamos os suppliers buscados dinamicamente para o componente
                          que faz a filtragem e exibe o dropdown.
                        */}
                        <SupplierSearchField
                            suppliers={suppliers}
                            selectedSupplierId={selectedSupplierId}
                            onSelect={handleSelect}
                            onQueryChange={handleQueryChange}
                            isSearching={isSearching}
                        />

                        <p className="text-[10px] text-slate-400 font-medium ml-1 mt-1">
                            O fornecedor será adicionado aos produtos sem substituir vínculos existentes.
                        </p>
                    </div>
                </div>

                {/* Footer */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/50 flex justify-end gap-3">
                    <button
                        onClick={onClose}
                        disabled={isSubmitting}
                        className="px-5 py-2.5 rounded-xl font-bold text-xs uppercase tracking-widest text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors disabled:opacity-50"
                    >
                        Cancelar
                    </button>
                    <button
                        onClick={handleConfirm}
                        disabled={!selectedSupplierId || isSubmitting}
                        className="flex items-center gap-2 px-6 py-2.5 rounded-xl bg-purple-600 hover:bg-purple-700 text-white font-bold text-xs uppercase tracking-widest shadow-md transition-all disabled:opacity-50 active:scale-95"
                    >
                        {isSubmitting ? (
                            <><i className="bi bi-arrow-repeat animate-spin"></i> Aplicando...</>
                        ) : (
                            <><i className="bi bi-check2"></i> Confirmar Atribuição</>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
};

// ─── Componente interno: input com busca live e dropdown ─────────────────────

interface SupplierSearchFieldProps {
    suppliers: Person[];
    selectedSupplierId: string;
    onSelect: (id: string) => void;
    onQueryChange: (term: string) => void;
    isSearching: boolean;
}

const SupplierSearchField: React.FC<SupplierSearchFieldProps> = ({
    suppliers,
    selectedSupplierId,
    onSelect,
    onQueryChange,
    isSearching,
}) => {
    const [query, setQuery] = useState('');
    const [open, setOpen] = useState(false);
    const [debounceTimer, setDebounceTimer] = useState<ReturnType<typeof setTimeout> | null>(null);

    const selectedSupplier = suppliers.find(s => s.id === selectedSupplierId);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        setQuery(val);
        onSelect(''); // limpa seleção ao digitar

        if (debounceTimer) clearTimeout(debounceTimer);
        const timer = setTimeout(() => {
            onQueryChange(val);
            setOpen(val.trim().length >= 2);
        }, 350);
        setDebounceTimer(timer);
    };

    const handleClear = () => {
        setQuery('');
        onSelect('');
        setOpen(false);
    };

    const handleSelectItem = (supplier: Person) => {
        setQuery(supplier.fullName);
        onSelect(supplier.id!);
        setOpen(false);
    };

    // Se tiver selecionado externamente, sincroniza o texto
    React.useEffect(() => {
        if (selectedSupplier && query !== selectedSupplier.fullName) {
            setQuery(selectedSupplier.fullName);
        }
    }, [selectedSupplier]); // eslint-disable-line react-hooks/exhaustive-deps

    return (
        <div className="relative">
            <div className="relative">
                <i className="bi bi-search absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 text-sm pointer-events-none"></i>
                <input
                    type="text"
                    autoComplete="off"
                    value={query}
                    onChange={handleChange}
                    onFocus={() => { if (query.trim().length >= 2 && suppliers.length > 0) setOpen(true); }}
                    onBlur={() => setTimeout(() => setOpen(false), 200)}
                    placeholder="Digite o nome do fornecedor..."
                    className="w-full h-11 pl-10 pr-9 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm font-semibold text-slate-700 dark:text-slate-200 outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all placeholder:font-normal placeholder:text-slate-400"
                />
                <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1">
                    {isSearching && (
                        <i className="bi bi-arrow-repeat animate-spin text-slate-400 text-sm"></i>
                    )}
                    {selectedSupplierId && !isSearching && (
                        <>
                            <i className="bi bi-check-circle-fill text-emerald-500 text-sm"></i>
                            <button type="button" onClick={handleClear} className="text-slate-400 hover:text-red-500 transition-colors ml-1">
                                <i className="bi bi-x-lg text-xs"></i>
                            </button>
                        </>
                    )}
                    {!selectedSupplierId && !isSearching && (
                        <i className="bi bi-truck text-slate-400 text-sm"></i>
                    )}
                </div>
            </div>

            {/* Dropdown de resultados */}
            {open && (
                <div className="absolute z-[99999] top-full left-0 right-0 mt-1 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl max-h-56 overflow-y-auto divide-y divide-slate-100 dark:divide-slate-800/50">
                    {suppliers.length === 0 ? (
                        <div className="px-4 py-4 text-center text-xs font-bold text-slate-400">
                            {isSearching ? 'Buscando...' : 'Nenhum fornecedor encontrado.'}
                        </div>
                    ) : (
                        suppliers.map(s => (
                            <button
                                key={s.id}
                                type="button"
                                onMouseDown={() => handleSelectItem(s)}
                                className="w-full px-4 py-3 text-left hover:bg-blue-50 dark:hover:bg-slate-800 transition-all flex flex-col gap-0.5"
                            >
                                <span className="text-xs font-bold text-slate-800 dark:text-slate-100 truncate">
                                    {s.fullName}
                                </span>
                                {s.tradeName && s.tradeName !== s.fullName && (
                                    <span className="text-[10px] text-slate-400 truncate">
                                        Fantasia: {s.tradeName}
                                    </span>
                                )}
                            </button>
                        ))
                    )}
                </div>
            )}
        </div>
    );
};

import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { toast } from 'react-toastify';
import {
    ReconciliationProductItem,
    ReconciliationFilterState,
    ReconciliationSummary,
    PendencyType
} from './types/reconciliation.types';
import {
    fetchProductsForReconciliation,
    applySupplierBatch,
    applyCategoryBatch,
    applyNcmBatch,
    applyAttributeBatch,
    saveSingleProductReconciliation
} from './services/reconciliationQueries';
import { ReconciliationSummaryHeader } from './components/ReconciliationSummaryHeader';
import { ReconciliationFiltersBar } from './components/ReconciliationFiltersBar';
import { ReconciliationProductCard } from './components/ReconciliationProductCard';
import { ReconciliationBatchBar } from './components/ReconciliationBatchBar';
import { ApplySupplierModal } from './modals/ApplySupplierModal';
import { ApplyCategoryModal } from './modals/ApplyCategoryModal';
import { ApplyNcmModal } from './modals/ApplyNcmModal';
import { ApplyAttributeModal } from './modals/ApplyAttributeModal';

export const ProductReconciliation: React.FC = () => {
    const [products, setProducts] = useState<ReconciliationProductItem[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [totalCount, setTotalCount] = useState(0);
    const [page, setPage] = useState(1);
    const pageSize = 15;

    const [filters, setFilters] = useState<ReconciliationFilterState>({ pendencyType: 'all' });
    const [summary, setSummary] = useState<ReconciliationSummary>({
        totalPendingProducts: 0,
        totalPendencies: 0,
        totalCritical: 0,
        chipCounts: { all: 0, supplier: 0, category: 0, ncm: 0, attributes: 0, price: 0 }
    });

    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [isAllFilteredSelected, setIsAllFilteredSelected] = useState(false);

    // Modais de lote
    const [isSupplierModalOpen, setIsSupplierModalOpen] = useState(false);
    const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
    const [isNcmModalOpen, setIsNcmModalOpen] = useState(false);
    const [isAttributeModalOpen, setIsAttributeModalOpen] = useState(false);

    const loadData = useCallback(async () => {
        setIsLoading(true);
        try {
            const { data, count, summary: sum } = await fetchProductsForReconciliation(page, pageSize, filters);
            setProducts(data);
            setTotalCount(count);
            setSummary(sum);
        } catch (error: any) {
            toast.error(error.message || 'Erro ao carregar conciliação de produtos.');
        } finally {
            setIsLoading(false);
        }
    }, [page, pageSize, filters]);

    useEffect(() => {
        setPage(1);
    }, [filters]);

    useEffect(() => {
        loadData();
    }, [loadData]);

    // Seleção de itens
    const handleSelectAllOnPage = (checked: boolean) => {
        if (!checked) {
            const newSet = new Set(selectedIds);
            products.forEach(p => newSet.delete(p.id));
            setSelectedIds(newSet);
            setIsAllFilteredSelected(false);
            return;
        }

        const newSet = new Set(selectedIds);
        products.forEach(p => newSet.add(p.id));
        setSelectedIds(newSet);
    };

    const handleSelectProduct = (id: string, checked: boolean) => {
        const newSet = new Set(selectedIds);
        if (checked) {
            newSet.add(id);
        } else {
            newSet.delete(id);
            setIsAllFilteredSelected(false);
        }
        setSelectedIds(newSet);
    };

    const handleClearSelection = () => {
        setSelectedIds(new Set());
        setIsAllFilteredSelected(false);
    };

    // Salvamento de produto individual
    const handleSaveSingleProduct = async (
        productId: string,
        productUpdates: any,
        variationUpdates?: any[]
    ): Promise<boolean> => {
        const result = await saveSingleProductReconciliation(productUpdates, variationUpdates);
        if (result.success) {
            await loadData();
            return true;
        }
        toast.error(result.error || 'Erro ao salvar produto.');
        return false;
    };

    // Lotes
    const getTargetIds = (): string[] => {
        return Array.from(selectedIds);
    };

    const handleApplySupplier = async (supplierId: string) => {
        const ids = getTargetIds();
        if (ids.length === 0) return;

        const res = await applySupplierBatch(ids, supplierId);
        if (res.success) {
            toast.success(`Fornecedor atribuído a ${res.updated} produto(s)!`);
            handleClearSelection();
            loadData();
        } else {
            toast.error(res.error || 'Erro ao aplicar fornecedor.');
        }
    };

    const handleApplyCategory = async (catId: string) => {
        const ids = getTargetIds();
        if (ids.length === 0) return;

        const res = await applyCategoryBatch(ids, catId);
        if (res.success) {
            toast.success(`Categoria atribuída a ${res.updated} produto(s)!`);
            handleClearSelection();
            loadData();
        } else {
            toast.error(res.error || 'Erro ao aplicar categoria.');
        }
    };

    const handleApplyNcm = async (ncmValue: string) => {
        const ids = getTargetIds();
        if (ids.length === 0) return;

        const res = await applyNcmBatch(ids, ncmValue);
        if (res.success) {
            toast.success(`NCM atribuído a ${res.updated} produto(s)!`);
            handleClearSelection();
            loadData();
        } else {
            toast.error(res.error || 'Erro ao aplicar NCM.');
        }
    };

    const handleApplyAttribute = async (attrName: string, attrValue: string) => {
        const ids = getTargetIds();
        if (ids.length === 0) return;

        const res = await applyAttributeBatch(ids, attrName, attrValue);
        if (res.success) {
            toast.success(`Atributo "${attrName}" atribuído a ${res.updated} variação(ões)!`);
            handleClearSelection();
            loadData();
        } else {
            toast.error(res.error || 'Erro ao aplicar atributo.');
        }
    };

    // Compatibilidade de atributos para lote
    const selectedProductsList = useMemo(() => {
        return products.filter(p => selectedIds.has(p.id));
    }, [products, selectedIds]);

    const isAttributeBatchCompatible = useMemo(() => {
        if (selectedProductsList.length === 0) return false;
        const firstCat = selectedProductsList[0].categoryId;
        if (!firstCat) return false;
        return selectedProductsList.every(p => p.categoryId === firstCat);
    }, [selectedProductsList]);

    const availableBatchAttributes = useMemo(() => {
        const attributes = new Map<string, {
            id: string;
            name: string;
            dataType?: 'list' | 'integer' | 'decimal' | 'text' | 'boolean' | 'measure';
            unit?: string;
        }>();

        selectedProductsList.forEach(product => {
            product.pendencies.forEach(pendency => {
                if (!pendency.attributeId || !pendency.attributeName) return;
                attributes.set(pendency.attributeId, {
                    id: pendency.attributeId,
                    name: pendency.attributeName,
                    dataType: pendency.attributeDataType,
                    unit: pendency.attributeUnit
                });
            });
        });

        return Array.from(attributes.values()).sort((left, right) => left.name.localeCompare(right.name, 'pt-BR'));
    }, [selectedProductsList]);

    const allOnPageSelected = products.length > 0 && products.every(p => selectedIds.has(p.id));

    return (
        <div className="p-3 sm:p-6 md:p-8 max-w-[1400px] mx-auto min-h-screen pb-32">
            {/* Header com Resumo Compacto e Chips */}
            <ReconciliationSummaryHeader
                summary={summary}
                currentFilter={filters}
                onSelectChip={(type: PendencyType | 'all' | 'attributes') => {
                    setFilters(prev => ({ ...prev, pendencyType: type }));
                }}
                onToggleCriticalOnly={() => {
                    setFilters(prev => ({ ...prev, onlyCritical: !prev.onlyCritical }));
                }}
            />

            {/* Barra de Filtros Compacta */}
            <ReconciliationFiltersBar
                filters={filters}
                onChange={setFilters}
            />

            {/* Barra de Ações em Lote */}
            <ReconciliationBatchBar
                selectedCount={selectedIds.size}
                totalFilteredCount={totalCount}
                isAllFilteredSelected={isAllFilteredSelected}
                onOpenSupplierModal={() => setIsSupplierModalOpen(true)}
                onOpenCategoryModal={() => setIsCategoryModalOpen(true)}
                onOpenNcmModal={() => setIsNcmModalOpen(true)}
                onOpenAttributeModal={() => setIsAttributeModalOpen(true)}
                isAttributeBatchCompatible={isAttributeBatchCompatible}
                onClearSelection={handleClearSelection}
            />

            {/* Lista Orientada a Pendências */}
            <div className="space-y-4">
                {/* Cabeçalho da Lista / Selecionar Todos */}
                {products.length > 0 && (
                    <div className="flex items-center justify-between px-3 py-2 text-xs font-bold text-slate-500">
                        <label className="flex items-center gap-2 cursor-pointer select-none">
                            <input
                                type="checkbox"
                                checked={allOnPageSelected}
                                onChange={(e) => handleSelectAllOnPage(e.target.checked)}
                                className="w-4 h-4 rounded text-purple-600 bg-white dark:bg-slate-800 border-slate-300 dark:border-slate-700 focus:ring-purple-500 cursor-pointer"
                            />
                            <span>Selecionar todos da página ({products.length})</span>
                        </label>

                        {totalCount > pageSize && !isAllFilteredSelected && allOnPageSelected && (
                            <button
                                type="button"
                                onClick={() => {
                                    setIsAllFilteredSelected(true);
                                    toast.success(`Todos os ${totalCount} produtos do filtro selecionados.`);
                                }}
                                className="text-purple-600 dark:text-purple-400 font-bold hover:underline ml-2"
                            >
                                Selecionar todos os {totalCount} do filtro
                            </button>
                        )}
                    </div>
                )}

                {/* Loading State */}
                {isLoading ? (
                    <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-12 text-center text-slate-400 font-bold text-sm">
                        <i className="bi bi-arrow-repeat animate-spin text-3xl mb-3 block text-purple-600"></i>
                        Carregando pendências do cadastro...
                    </div>
                ) : products.length === 0 ? (
                    /* Empty State */
                    <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 p-12 text-center">
                        <div className="w-16 h-16 rounded-3xl bg-emerald-100 dark:bg-emerald-950/40 text-emerald-600 dark:text-emerald-400 flex items-center justify-center mx-auto mb-4">
                            <i className="bi bi-check-circle-fill text-2xl"></i>
                        </div>
                        <h4 className="text-base font-black text-slate-800 dark:text-slate-100">
                            Nenhum produto com pendências encontrado!
                        </h4>
                        <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 max-w-sm mx-auto font-medium">
                            Seus produtos estão em conformidade com as regras obrigatórias de cadastro para os filtros atuais.
                        </p>
                    </div>
                ) : (
                    /* Lista de Cards */
                    products.map(product => (
                        <ReconciliationProductCard
                            key={product.id}
                            product={product}
                            isSelected={selectedIds.has(product.id)}
                            onToggleSelect={(checked) => handleSelectProduct(product.id, checked)}
                            onSaveProduct={handleSaveSingleProduct}
                        />
                    ))
                )}

                {/* Paginação Server-Side */}
                {totalCount > 0 && (
                    <div className="p-4 bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                        <span className="text-xs font-bold text-slate-500">
                            Mostrando {(page - 1) * pageSize + 1} até {Math.min(page * pageSize, totalCount)} de {totalCount} produtos
                        </span>

                        <div className="flex items-center gap-2 self-end sm:self-center">
                            <button
                                disabled={page === 1 || isLoading}
                                onClick={() => setPage(p => Math.max(1, p - 1))}
                                className="px-3.5 py-1.5 rounded-xl border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-300 text-xs font-bold hover:bg-slate-50 dark:hover:bg-slate-800 disabled:opacity-40 transition-colors flex items-center gap-1"
                            >
                                <i className="bi bi-chevron-left"></i> Anterior
                            </button>

                            <span className="text-xs font-black text-purple-600 dark:text-purple-400 px-2">
                                Página {page}
                            </span>

                            <button
                                disabled={page * pageSize >= totalCount || isLoading}
                                onClick={() => setPage(p => p + 1)}
                                className="px-3.5 py-1.5 rounded-xl border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-300 text-xs font-bold hover:bg-slate-50 dark:hover:bg-slate-800 disabled:opacity-40 transition-colors flex items-center gap-1"
                            >
                                Próxima <i className="bi bi-chevron-right"></i>
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Modais de Ações em Lote */}
            <ApplySupplierModal
                isOpen={isSupplierModalOpen}
                onClose={() => setIsSupplierModalOpen(false)}
                onConfirm={handleApplySupplier}
                selectedCount={selectedIds.size}
                isAllFilteredSelected={isAllFilteredSelected}
                totalFilteredCount={totalCount}
            />

            <ApplyCategoryModal
                isOpen={isCategoryModalOpen}
                onClose={() => setIsCategoryModalOpen(false)}
                onConfirm={handleApplyCategory}
                selectedCount={selectedIds.size}
            />

            <ApplyNcmModal
                isOpen={isNcmModalOpen}
                onClose={() => setIsNcmModalOpen(false)}
                onConfirm={handleApplyNcm}
                selectedCount={selectedIds.size}
            />

            <ApplyAttributeModal
                isOpen={isAttributeModalOpen}
                onClose={() => setIsAttributeModalOpen(false)}
                onConfirm={handleApplyAttribute}
                selectedCount={selectedIds.size}
                availableAttributes={availableBatchAttributes}
            />
        </div>
    );
};

export default ProductReconciliation;

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../../context/AuthContext';
import { supabase } from '@/pages/utils/supabaseConfig';
import { toast } from 'react-toastify';

const Profile = () => {
    const { user, profile, logout } = useAuth();
    const [loading, setLoading] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [fullName, setFullName] = useState(profile?.full_name || '');
    const [position, setPosition] = useState(profile?.position || '');
    const [phone, setPhone] = useState(profile?.phone || '');
    const [address, setAddress] = useState(profile?.address || '');
    const [city, setCity] = useState(profile?.city || '');
    const [stateValue, setStateValue] = useState(profile?.state || '');
    const [email, setEmail] = useState(user?.email || '');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Sync state when profile loads
    useEffect(() => {
        if (profile) {
            setFullName(prev => prev || profile.full_name || user?.user_metadata?.full_name || '');
            setPosition(prev => prev || profile.position || '');
            setPhone(prev => prev || profile.phone || user?.phone || user?.user_metadata?.phone || '');
            setAddress(prev => prev || profile.address || '');
            setCity(prev => prev || profile.city || '');
            setStateValue(prev => prev || profile.state || '');

            // Auto-set position if empty based on role
            if (!profile.position && !position && profile.role) {
                const roleMap: Record<string, string> = {
                    'seller': 'Vendedor',
                    'manager': 'Gerente',
                    'administrator': 'Gerente',
                    'deliverer': 'Entregador'
                };
                setPosition(roleMap[profile.role] || '');
            }
        }
        if (user) setEmail(user.email || '');
    }, [profile, user]);

    const handleUpdateProfile = async (e: any) => {
        e.preventDefault();
        setLoading(true);
        try {
            const now = (new (window as any).Date()).toISOString();
            const { error } = await supabase
                .from('profiles')
                .update({
                    full_name: fullName,
                    position: position,
                    phone: phone,
                    address: address,
                    city: city,
                    state: stateValue,
                    updated_at: now
                })
                .eq('id', user?.id);

            if (error) throw error;
            toast.success('Perfil atualizado com sucesso!');
        } catch (error: any) {
            toast.error(error.message || 'Erro ao atualizar perfil.');
        } finally {
            setLoading(false);
        }
    };

    const handleChangeEmail = async () => {
        if (!email || email === user?.email) return;
        setLoading(true);
        try {
            const { error } = await supabase.auth.updateUser({ email });
            if (error) throw error;
            toast.info('Verifique seu novo e-mail para confirmar a alteração.');
        } catch (error: any) {
            toast.error(error.message || 'Erro ao alterar e-mail.');
        } finally {
            setLoading(false);
        }
    };

    const handleChangePassword = async () => {
        if (!newPassword) return;
        if (newPassword !== confirmPassword) {
            toast.error('As senhas não coincidem.');
            return;
        }
        setLoading(true);
        try {
            const { error } = await supabase.auth.updateUser({ password: newPassword });
            if (error) throw error;
            toast.success('Senha alterada com sucesso!');
            setNewPassword('');
            setConfirmPassword('');
        } catch (error: any) {
            toast.error(error.message || 'Erro ao alterar senha.');
        } finally {
            setLoading(false);
        }
    };

    const uploadAvatar = async (event: any) => {
        try {
            setUploading(true);
            const files = event.target.files;
            if (!files || files.length === 0) {
                throw new (window as any).Error('Você deve selecionar uma imagem para upload.');
            }

            const file = files[0];
            const fileExt = file.name.split('.').pop();
            const fileName = `${user?.id}.${fileExt}`;
            const filePath = `${fileName}`;

            // Upload to Supabase Storage
            const { error: uploadError } = await supabase.storage
                .from('avatars')
                .upload(filePath, file, { upsert: true });

            if (uploadError) throw uploadError;

            // Get Public URL
            const { data: { publicUrl } } = supabase.storage
                .from('avatars')
                .getPublicUrl(filePath);

            // Update profile
            const { error: updateError } = await supabase
                .from('profiles')
                .update({ avatar_url: publicUrl })
                .eq('id', user?.id);

            if (updateError) throw updateError;

            toast.success('Foto de perfil atualizada!');
            (window as any).location.reload();
        } catch (error: any) {
            toast.error(error.message);
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="max-w-4xl mx-auto p-4 animate-slide-up">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

                {/* Lateral: Avatar e Info Básica */}
                <div className="md:col-span-1">
                    <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-xl border border-slate-100 dark:border-slate-800 text-center">
                        <div className="relative inline-block mb-6">
                            <div className="w-32 h-32 rounded-[2rem] bg-blue-50 dark:bg-blue-900/20 overflow-hidden border-4 border-white dark:border-slate-800 shadow-lg">
                                {profile?.avatar_url ? (
                                    <img src={profile.avatar_url} alt="Profile" className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center">
                                        <i className="bi bi-person-fill text-5xl text-blue-300"></i>
                                    </div>
                                )}
                            </div>
                            <button
                                onClick={() => (fileInputRef.current as any)?.click()}
                                disabled={uploading}
                                className="absolute -bottom-2 -right-2 w-10 h-10 bg-blue-600 hover:bg-blue-700 text-white rounded-xl shadow-lg flex items-center justify-center transition-all border-4 border-white dark:border-slate-900"
                            >
                                {uploading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <i className="bi bi-camera-fill text-sm"></i>}
                            </button>
                            <input
                                type="file"
                                className="hidden"
                                ref={fileInputRef}
                                accept="image/*"
                                onChange={uploadAvatar}
                            />
                        </div>
                        <h2 className="text-xl font-black text-slate-800 dark:text-slate-100">{profile?.full_name || 'Usuário'}</h2>
                        <p className="text-xs font-black uppercase tracking-widest text-blue-600 dark:text-blue-400 mt-1">{profile?.role}</p>

                        <div className="mt-8 pt-6 border-t border-slate-50 dark:border-slate-800 space-y-3">
                            <a 
                                href="https://drive.google.com/file/d/1UfEAzpIbgAYA6hG-fx7w7Ja73uXEVE74/view?usp=sharing"
                                target="_blank"
                                rel="noopener noreferrer"
                                className="w-full flex items-center justify-between p-3.5 rounded-2xl bg-emerald-500/10 dark:bg-emerald-500/15 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 font-bold hover:bg-emerald-500/20 transition-all text-xs"
                            >
                                <i className="bi bi-android2 text-base"></i>
                                Baixar App Android Oficial
                            </a>

                            {/* QR Code Container */}
                            <div className="p-3 bg-slate-50 dark:bg-slate-800/60 rounded-2xl border border-slate-100 dark:border-slate-800 flex items-center gap-3">
                                <div className="w-20 h-20 bg-white p-1 rounded-xl shadow-sm border border-slate-200 dark:border-slate-700 shrink-0">
                                    <img src="/mobile-qrcode.png" alt="QR Code Instalação Mobile" className="w-full h-full object-contain rounded-md" />
                                </div>
                                <div className="flex flex-col text-left">
                                    <span className="text-[10px] font-black uppercase tracking-wider text-emerald-600 dark:text-emerald-400">Instale no Celular</span>
                                    <span className="text-xs font-bold text-slate-700 dark:text-slate-200 leading-tight">Aponte a Câmera</span>
                                    <span className="text-[9px] text-slate-400 mt-1">QR Code direto para o APK v1.0.2</span>
                                </div>
                            </div>

                            <button
                                onClick={logout}
                                className="w-full py-3 bg-red-50 dark:bg-red-900/10 text-red-600 hover:bg-red-100 dark:hover:bg-red-900/20 rounded-2xl font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                            >
                                <i className="bi bi-box-arrow-right"></i>
                                Sair da Conta
                            </button>
                        </div>
                    </div>
                </div>

                {/* Principal: Formulários */}
                <div className="md:col-span-2 space-y-6">

                    {/* Dados Pessoais */}
                    <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-xl border border-slate-100 dark:border-slate-800">
                        <div className="flex items-center gap-4 mb-8">
                            <div className="w-12 h-12 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center">
                                <i className="bi bi-person-badge-fill text-blue-600 text-xl"></i>
                            </div>
                            <div>
                                <h3 className="text-lg font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Informações Pessoais</h3>
                                <p className="text-xs text-slate-400 font-bold italic">Mantenha seus dados sempre atualizados.</p>
                            </div>
                        </div>

                        <form onSubmit={handleUpdateProfile} className="space-y-4">
                            <div className="grid grid-cols-1 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">Nome Completo</label>
                                    <input
                                        type="text"
                                        value={fullName}
                                        onChange={(e: any) => setFullName(e.target.value)}
                                        className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                        placeholder="Seu nome"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">WhatsApp / Celular</label>
                                    <input
                                        type="text"
                                        value={phone}
                                        onChange={(e: any) => setPhone(e.target.value)}
                                        className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                        placeholder="(00) 00000-0000"
                                    />
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">Cargo Principal</label>
                                        <select
                                            value={position}
                                            onChange={(e: any) => setPosition(e.target.value)}
                                            className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all appearance-none"
                                        >
                                            <option value="">Selecione o cargo...</option>
                                            <option value="Vendedor">Vendedor</option>
                                            <option value="Gerente">Gerente</option>
                                            <option value="Entregador">Entregador</option>
                                            {position && !['Vendedor', 'Gerente', 'Entregador'].includes(position) && (
                                                <option value={position}>{position}</option>
                                            )}
                                        </select>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">E-mail</label>
                                        <div className="flex gap-2">
                                            <input
                                                type="email"
                                                value={email}
                                                readOnly
                                                className="grow bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-400 dark:text-slate-500 font-bold outline-none cursor-not-allowed"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">Endereço Residencial</label>
                                    <input
                                        type="text"
                                        value={address}
                                        onChange={(e: any) => setAddress(e.target.value)}
                                        className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                        placeholder="Rua, Número, Bairro"
                                    />
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">Cidade</label>
                                        <input
                                            type="text"
                                            value={city}
                                            onChange={(e: any) => setCity(e.target.value)}
                                            className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                            placeholder="Sua Cidade"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">Estado</label>
                                        <input
                                            type="text"
                                            value={stateValue}
                                            onChange={(e: any) => setStateValue(e.target.value)}
                                            className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                            placeholder="Ex: São Paulo"
                                        />
                                    </div>
                                </div>
                            </div>
                            <button
                                type="submit"
                                disabled={loading}
                                className="w-full mt-4 py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-blue-500/20 transition-all flex items-center justify-center gap-2"
                            >
                                {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : "Salvar Alterações"}
                            </button>
                        </form>
                    </div>

                    {/* Segurança */}
                    <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 shadow-xl border border-slate-100 dark:border-slate-800">
                        <div className="flex items-center gap-4 mb-8">
                            <div className="w-12 h-12 bg-slate-50 dark:bg-slate-800 rounded-2xl flex items-center justify-center">
                                <i className="bi bi-shield-lock-fill text-amber-600 text-xl"></i>
                            </div>
                            <div>
                                <h3 className="text-lg font-black text-slate-800 dark:text-slate-100 uppercase tracking-tight">Segurança da Conta</h3>
                                <p className="text-xs text-slate-400 font-bold italic">Gerencie sua senha de acesso.</p>
                            </div>
                        </div>

                        <div className="space-y-4">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">Nova Senha</label>
                                    <input
                                        type="password"
                                        value={newPassword}
                                        onChange={(e: any) => setNewPassword(e.target.value)}
                                        className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                        placeholder="••••••••"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 pl-4">Confirmar Senha</label>
                                    <input
                                        type="password"
                                        value={confirmPassword}
                                        onChange={(e: any) => setConfirmPassword(e.target.value)}
                                        className="w-full bg-slate-50 dark:bg-slate-800/50 border-none rounded-2xl p-4 text-slate-800 dark:text-slate-100 font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                                        placeholder="••••••••"
                                    />
                                </div>
                            </div>
                            <button
                                onClick={handleChangePassword}
                                disabled={loading || !newPassword}
                                className="w-full mt-4 py-4 bg-slate-800 dark:bg-slate-700 hover:bg-black text-white rounded-2xl font-black text-xs uppercase tracking-widest transition-all flex items-center justify-center gap-2"
                            >
                                {loading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : "Atualizar Senha"}
                            </button>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    );
};

export default Profile;

import React from "react";
import { PersonFiltersData } from "../PersonPage";

interface PersonFiltersProps {
    readonly filters: PersonFiltersData;
    readonly setFilters: React.Dispatch<React.SetStateAction<PersonFiltersData>>;
    readonly title: string;
    readonly collectionName: string;
}

const PersonFilters = ({ filters, setFilters, title, collectionName }: PersonFiltersProps) => {
    const isEmployee = collectionName === 'employees';
    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
    };

    const resetFilters = () => {
        setFilters({
            search: "",
            activeOnly: undefined,
            sortBy: "fullName",
            sortOrder: "asc",
            showTrash: filters.showTrash
        });
    };

    return (
        <aside className="w-full bg-white dark:bg-slate-900 flex flex-col h-full overflow-y-auto transition-colors">
            <div className="p-4 md:p-8 border-b border-slate-50 dark:border-slate-800">
                <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight flex items-center gap-3">
                    <i className="bi bi-filter-left text-blue-600 dark:text-blue-500" aria-hidden="true" />
                    Filtros
                </h3>
                <p className="text-[10px] uppercase font-black text-slate-400 dark:text-slate-500 tracking-widest mt-1">Refine sua busca de {title.toLowerCase()}</p>
            </div>

            <div className="p-4 md:p-8 flex flex-col gap-6">
                <div className="flex flex-col gap-6">
                    <div className="flex flex-col gap-2">
                        <label htmlFor="person-filter-search" className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Busca</label>
                        <div className="relative">
                            <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" aria-hidden="true" />
                            <input
                                id="person-filter-search"
                                type="text"
                                name="search"
                                aria-label={`Buscar ${title.toLowerCase()}`}
                                value={filters.search}
                                onChange={handleChange}
                                placeholder={isEmployee ? "Nome, email ou CPF..." : "Nome, email ou CPF/CNPJ..."}
                                className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm dark:text-slate-300 placeholder:text-slate-300 dark:placeholder:text-slate-700"
                            />
                        </div>
                    </div>

                    <div className="flex flex-col gap-2">
                        <label htmlFor="person-filter-status" className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Status</label>
                         <select
                            id="person-filter-status"
                            name="activeOnly"
                            aria-label="Filtrar por status ativo ou inativo"
                            value={filters.activeOnly === undefined ? "" : String(filters.activeOnly)}
                            onChange={(e) => {
                                const val = e.target.value;
                                setFilters(prev => ({ ...prev, activeOnly: val === "" ? undefined : val === "true" }));
                            }}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm appearance-none cursor-pointer dark:text-slate-300"
                        >
                            <option value="">Todos Status</option>
                            <option value="true">Ativos</option>
                            <option value="false">Inativos</option>
                        </select>
                    </div>
                </div>

            </div>

            <div className="mt-auto p-4 border-t border-slate-50 dark:border-slate-800">
                <button
                    type="button"
                    onClick={resetFilters}
                    aria-label="Limpar todos os filtros"
                    className="w-full py-4 text-xs font-black uppercase tracking-widest text-slate-400 dark:text-slate-600 hover:text-red-500 dark:hover:text-red-400 transition-colors flex items-center justify-center gap-2 cursor-pointer"
                >
                    <i className="bi bi-arrow-counterclockwise" aria-hidden="true" />
                    Limpar Filtros
                </button>
            </div>
        </aside>
    );
};

export default PersonFilters;

import React from "react";
import { PersonFiltersData } from "../PersonPage";
import { PersonTableSettings } from "./PersonTableSettings";
import { PersonVisibilitySettings } from "../../../../types/person.type";

interface PersonPageToolbarProps {
    filters: PersonFiltersData;
    setFilters: React.Dispatch<React.SetStateAction<PersonFiltersData>>;
    isSupplier: boolean;
    isCustomer: boolean;
    isEmployee: boolean;
    collectionName: string;
    isSidebarOpen: boolean;
    setIsSidebarOpen: (val: boolean) => void;
    setIsTrashOpen: (val: boolean) => void;
    visibilitySettings: PersonVisibilitySettings;
    toggleVisibility: (column: keyof PersonVisibilitySettings) => void;
}

export const PersonPageToolbar: React.FC<PersonPageToolbarProps> = ({
    filters,
    setFilters,
    isSupplier,
    isCustomer,
    isEmployee,
    collectionName,
    isSidebarOpen,
    setIsSidebarOpen,
    setIsTrashOpen,
    visibilitySettings,
    toggleVisibility,
}) => {
    const sidebarBtnClass = `flex items-center gap-2 px-4 py-2 rounded-xl transition-all shadow-sm font-bold text-xs uppercase tracking-widest border ${
        isSidebarOpen
            ? "bg-white text-blue-600 border-blue-100 dark:bg-slate-900 dark:border-blue-900/30"
            : "bg-white text-slate-600 border-slate-200 dark:bg-slate-900 dark:border-slate-800 hover:border-blue-200 dark:hover:border-blue-800"
    }`;

    return (
        <>
            {(isSupplier || isCustomer) && (
                <div className="relative mt-2">
                    <i className="bi bi-search pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-xs text-slate-400" />
                    <input
                        type="search"
                        value={filters.search}
                        onChange={(event) =>
                            setFilters((current) => ({ ...current, search: event.target.value }))
                        }
                        placeholder={
                            isCustomer
                                ? "Pesquisar cliente por nome, CPF/CNPJ, telefone ou e-mail..."
                                : "Pesquisar fornecedor por nome, razão social ou CPF/CNPJ"
                        }
                        className="w-full rounded-xl border border-slate-200 bg-white py-1.5 pl-8 pr-3 text-xs text-slate-700 outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200 dark:focus:ring-blue-900/30"
                    />
                </div>
            )}

            <div className={`flex flex-col ${isSupplier || isCustomer ? "gap-2 mt-2" : "gap-6 mt-4"}`}>
                {!isEmployee && !isSupplier && collectionName !== "customers" && (
                    <div className="flex justify-between items-center px-2">
                        <div className="flex gap-3">
                            <button
                                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                                className={sidebarBtnClass}
                            >
                                <i className={`bi ${isSidebarOpen ? "bi-funnel-fill" : "bi-funnel"}`} />
                                Filtros
                            </button>

                            <button
                                onClick={() => setIsTrashOpen(true)}
                                className="flex items-center gap-2 px-4 py-2 rounded-xl transition-all shadow-sm font-bold text-xs uppercase tracking-widest border bg-white text-slate-600 border-slate-200 dark:bg-slate-900 dark:border-slate-800 hover:border-red-200 dark:hover:border-red-800 hover:text-red-500"
                            >
                                <i className="bi bi-trash3" />
                                Lixeira
                            </button>
                        </div>

                        <PersonTableSettings
                            visibilitySettings={visibilitySettings}
                            toggleVisibility={toggleVisibility}
                            collectionName={collectionName}
                            isEmployee={isEmployee}
                        />
                    </div>
                )}
            </div>
        </>
    );
};

import React from "react";
import Person from "@/pages/types/person.type";
import { AddressAutocompleteInput } from "@/components/shared/AddressAutocompleteInput";
import AddressVerificationMap from "@/pages/App/SalesOrder/AddressVerificationMap";

interface PersonAddressSectionProps {
    formData: Partial<Person>;
    setFormData: React.Dispatch<React.SetStateAction<Partial<Person>>>;
    isEmployee: boolean;
    collectionName: string;
    isAddressOpen: boolean;
    setIsAddressOpen: React.Dispatch<React.SetStateAction<boolean>>;
    routeUrl: string;
    handleAddressChange: (field: string, value: string) => void;
    handleCepBlur: (e: React.FocusEvent<HTMLInputElement>) => Promise<void>;
}

export const PersonAddressSection: React.FC<PersonAddressSectionProps> = ({
    formData,
    setFormData,
    isEmployee,
    collectionName,
    isAddressOpen,
    setIsAddressOpen,
    routeUrl,
    handleAddressChange,
    handleCepBlur,
}) => {
    return (
        <div className="flex flex-col gap-4">
            <div 
                onClick={() => { if (isEmployee) setIsAddressOpen(prev => !prev); }}
                className={`flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-2 ${isEmployee ? 'cursor-pointer select-none group/addr py-1 hover:border-slate-300 dark:hover:border-slate-700 transition-colors' : ''}`}
            >
                <div className="flex items-center gap-2">
                    <i className="bi bi-geo-alt-fill text-blue-600"></i>
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-800 dark:text-slate-300">
                        Endereço {collectionName === 'customers' && !formData.noAddress && <span className="text-red-500">*</span>}
                    </h4>
                    {isEmployee && (
                        <span className="text-[10px] font-medium text-slate-400 dark:text-slate-500 ml-1">
                            (Opcional - clique para {isAddressOpen ? 'recolher' : 'expandir'})
