import { useEffect, useMemo, useRef, useState } from "react";
import DropdownPortal from "@/components/shared/DropdownPortal";
import { getRecentPeople, searchPeople } from "@/pages/utils/personService";
import CustomerData from '@/pages/types/customerData.type';
import Person from '@/pages/types/person.type';
import { ValidationErrors } from '@/pages/utils/validations';
import { toTitleCase } from '@/pages/utils/formatters';
import { canSearchCustomers, getCustomerSearchQuery, matchesCustomerSearch } from '@/pages/utils/customerSearch';
import PersonFormModal from '@/pages/App/Registrations/shared/modals/PersonFormModal';

interface Props {
    customerData: CustomerData;
    setCustomerData: React.Dispatch<React.SetStateAction<CustomerData>>;
    errors: ValidationErrors;
    isPickup: boolean;
    marketingOrigin?: string;
    setMarketingOrigin?: (origin: string) => void;
    isBudget?: boolean;
}

const EMPTY_ADDRESS = {
    cep: "", street: "", number: "", complement: "",
    neighborhood: "", city: "", observation: "",
};

const CustomerDataInputs = ({ customerData, setCustomerData, errors, marketingOrigin, setMarketingOrigin }: Props) => {
    const [customers, setCustomers] = useState<Person[]>([]);
    const [searchTerm, setSearchTerm] = useState(customerData.fullName || "");
    const [isOpen, setIsOpen] = useState(false);
    const [isNewCustomerOpen, setIsNewCustomerOpen] = useState(false);
    const [editingPerson, setEditingPerson] = useState<Person | null>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const hasError = Boolean(errors.customer_fullName || errors.customer_phone);

    // Load recent on mount
    useEffect(() => {
        getRecentPeople('customers', 20).then(data => {
            setCustomers(data.filter((customer) => customer.active && !customer.deleted));
        });
    }, []);

    // Debounced search on typing
    useEffect(() => {
        if (!searchTerm.trim() || searchTerm.trim().length < 2) return;

        const delay = setTimeout(async () => {
            try {
                const found = await searchPeople(searchTerm, 'customers', 20);
                setCustomers(prev => {
                    const combined = [...prev, ...found.filter(c => c.active && !c.deleted)];
                    return Array.from(new Map(combined.map(p => [p.id, p])).values());
                });
            } catch (e) {
                console.error("Erro ao pesquisar clientes no input:", e);
            }
        }, 300);

        return () => clearTimeout(delay);
    }, [searchTerm]);
    useEffect(() => {
        if (!isOpen) setSearchTerm(customerData.fullName || "");
    }, [customerData.fullName, isOpen]);

    useEffect(() => {
        const closeOnOutsideClick = (event: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) setIsOpen(false);
        };
        document.addEventListener("mousedown", closeOnOutsideClick);
        return () => document.removeEventListener("mousedown", closeOnOutsideClick);
    }, []);

    const selectedPerson = useMemo(() => {
        if (!customerData.id) return null;
        return customers.find((c) => c.id === customerData.id) || null;
    }, [customers, customerData.id]);

    const filteredCustomers = useMemo(() => {
        if (!canSearchCustomers(searchTerm)) return [];
        const query = getCustomerSearchQuery(searchTerm);
        return customers.filter((customer) => matchesCustomerSearch(query, {
            name: customer.fullName || customer.tradeName,
            phone: customer.phone,
        }));
    }, [customers, searchTerm]);

    const clearCustomer = () => {
        setCustomerData({
            id: undefined, fullName: "", phone: "", noPhone: false,
            noAddress: false, fullAddress: EMPTY_ADDRESS, additionalContacts: [],
        });
        setSearchTerm("");
        setIsOpen(false);
    };

    const selectCustomer = (customer: Person) => {
        const formattedName = toTitleCase(customer.fullName || customer.tradeName || "");
        setCustomerData({
            id: customer.id,
            fullName: formattedName,
            phone: customer.phone || "",
            noPhone: customer.noPhone || false,
            noAddress: customer.noAddress || Boolean(customer.fullAddress?.noAddress),
            fullAddress: customer.fullAddress || EMPTY_ADDRESS,
            additionalContacts: customer.additionalContacts || [],
        });
        setSearchTerm(formattedName);
        if (customer.marketingOrigin) setMarketingOrigin?.(customer.marketingOrigin);
        setIsOpen(false);
    };

    const handleEditCustomer = () => {
        setIsOpen(false);
        if (selectedPerson) {
            setEditingPerson(selectedPerson);
        } else if (customerData.id || customerData.fullName) {
            const fallbackPerson: Partial<Person> = {
                id: customerData.id,
                fullName: customerData.fullName,
                phone: customerData.phone,
                noPhone: customerData.noPhone,
                noAddress: customerData.noAddress,
                fullAddress: customerData.fullAddress || EMPTY_ADDRESS,
                additionalContacts: customerData.additionalContacts || [],
                marketingOrigin: customerData.marketingOrigin || marketingOrigin || "",
                type: "customers"
            };
            setEditingPerson(fallbackPerson as Person);
        }
    };

    const isCustomerSelected = Boolean((customerData.id || customerData.fullName) && searchTerm.trim());

    return (
        <div ref={wrapperRef} className="relative w-full">
            <div className="mb-2 ml-1 flex items-center justify-between gap-3">
                <label className={`text-[10px] font-black uppercase tracking-widest ${hasError ? "text-red-600 dark:text-red-400" : "text-slate-400 dark:text-slate-500"}`}>
                    Selecionar cliente <span className="text-red-500">*</span>
                </label>
                <button
                    type="button"
                    onClick={() => { setIsOpen(false); setIsNewCustomerOpen(true); }}
                    className="flex items-center gap-1 text-[10px] font-black uppercase tracking-wider text-blue-600 transition-colors hover:text-blue-800 dark:text-blue-400 dark:hover:text-blue-300"
                >
                    <i className="bi bi-plus-lg" />
                    Novo cliente
                </button>
            </div>
            <div className="relative">
                {isCustomerSelected && (
                    <div className="pointer-events-none absolute left-3 top-1/2 flex -translate-y-1/2 items-center text-emerald-600 dark:text-emerald-400 animate-fade-in">
                        <i className="bi bi-check-circle-fill text-sm sm:text-base" />
                    </div>
                )}
                <input
                    type="text"
                    value={searchTerm}
                    onKeyDown={(e) => {
                        if ((e.key === "Backspace" || e.key === "Delete") && Boolean(customerData.id)) {
                            e.preventDefault();
                            clearCustomer();
                        }
                    }}
                    onChange={(event) => {
                        const value = event.target.value;
                        if (customerData.id && value !== searchTerm) {
                            clearCustomer();
                            return;
                        }
                        setSearchTerm(value);
                        setIsOpen(canSearchCustomers(value));
                        if (!value) clearCustomer();
                    }}
                    onFocus={() => setIsOpen(canSearchCustomers(searchTerm))}
                    placeholder="Busque pelo nome ou telefone..."
                    className={`w-full border-b-2 bg-transparent py-3 pr-20 text-sm outline-none transition-all placeholder:text-slate-300 dark:placeholder:text-slate-700 ${
                        hasError
                            ? "pl-3 border-red-500 focus:border-red-600 text-red-700 dark:text-red-300"
                            : isCustomerSelected
                            ? "pl-9 border-emerald-500 focus:border-emerald-600 dark:border-emerald-500 dark:focus:border-emerald-400 font-medium text-slate-800 dark:text-slate-100"
                            : "pl-3 border-slate-200 focus:border-blue-600 dark:border-slate-700 dark:text-slate-300 dark:focus:border-blue-500"
                    }`}
                />
                <div className="absolute right-3 top-1/2 flex -translate-y-1/2 items-center gap-2.5">
                    {Boolean(customerData.id || customerData.fullName) && (
                        <button
                            type="button"
                            onClick={handleEditCustomer}
                            className="text-slate-400 transition-colors hover:text-blue-600 dark:hover:text-blue-400"
                            title="Editar cliente selecionado"
                        >
                            <i className="bi bi-pencil-fill text-xs" />
                        </button>
                    )}
                    {searchTerm && (
                        <button type="button" onClick={clearCustomer} className="text-slate-400 transition-colors hover:text-slate-700 dark:hover:text-slate-200" title="Limpar cliente">
                            <i className="bi bi-x-circle-fill" />
                        </button>
                    )}
                    <i className={`bi bi-chevron-down text-slate-400 transition-transform ${isOpen ? "rotate-180" : ""}`} />
                </div>
            </div>

            {hasError && <p className="mt-2 text-xs font-bold text-red-500">{errors.customer_fullName || errors.customer_phone}</p>}

            <DropdownPortal anchorRef={wrapperRef} isOpen={isOpen}>
                <div className="mt-1 border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900">
                    {filteredCustomers.length === 0 ? (
                        <p className="p-4 text-center text-sm text-slate-400">Nenhum cliente encontrado.</p>
                    ) : filteredCustomers.map((customer) => (
                        <button key={customer.id} type="button" onClick={() => selectCustomer(customer)} className="flex w-full items-center gap-4 border-b border-slate-100 px-3 py-2.5 text-left transition-colors last:border-0 hover:bg-slate-50 dark:border-slate-800 dark:hover:bg-slate-800">
                            <strong className="min-w-0 flex-1 truncate text-sm text-slate-800 dark:text-slate-200">{toTitleCase(customer.fullName || customer.tradeName)}</strong>
                            {customer.phone && <small className="shrink-0 text-xs text-slate-400">{customer.phone}</small>}
                            {customer.fullAddress?.street && (
                                <small className="min-w-0 max-w-[40%] truncate text-xs text-slate-400">
                                    {toTitleCase(customer.fullAddress.street)}{customer.fullAddress.number ? `, ${customer.fullAddress.number}` : ""}
                                </small>
                            )}
                            {customerData.id === customer.id && <i className="bi bi-check-lg shrink-0 text-blue-600" />}
                        </button>
                    ))}
                </div>
            </DropdownPortal>

            <PersonFormModal
                isOpen={isNewCustomerOpen}
                onClose={() => setIsNewCustomerOpen(false)}
                onSuccess={(customer) => {
                    setCustomers((current) => [...current.filter((item) => item.id !== customer.id), customer]);
                    selectCustomer(customer);
                    setIsNewCustomerOpen(false);
                }}
                collectionName="customers"
                title="Cliente"
            />

            <PersonFormModal
                isOpen={Boolean(editingPerson)}
                onClose={() => setEditingPerson(null)}
                person={editingPerson}
                onSuccess={(customer) => {
                    setCustomers((current) => [...current.filter((item) => item.id !== customer.id), customer]);
                    selectCustomer(customer);
                    setEditingPerson(null);
                }}
                collectionName="customers"
                title="Editar Cliente"
            />
        </div>
    );
};

export default CustomerDataInputs;

import React from "react";
import CurrencyInput from "@/components/CurrencyInput";

export interface Filters {
    dateRange: { start: string; end: string };
    dateType: "personalizado" | "hoje" | "esse_mes" | "mes_passado" | "ultimo_semestre" | "esse_ano";
    customerName: string;
    productName: string;
    status: string;
    orderType: string;
    seller: string;
    valueRange: { min: number; max: number };
    sortBy: string;
    sortOrder: "asc" | "desc";
    multiSort: { key: string; order: "asc" | "desc" }[];
    searchId?: string;
    isBudgetView?: boolean;
    isAssistanceView?: boolean;
    isReturnView?: boolean;
}

interface OrderFiltersProps {
    readonly filters: Filters;
    readonly setFilters: React.Dispatch<React.SetStateAction<Filters>>;
}

const OrderFilters = ({ filters, setFilters }: OrderFiltersProps) => {
    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        if (name.includes(".")) {
            const [parent, child] = name.split(".");
            if (parent === "dateRange") {
                setFilters(prev => ({
                    ...prev,
                    dateRange: {
                        ...prev.dateRange,
                        [child]: value
                    }
                }));
            } else if (parent === "valueRange") {
                setFilters(prev => ({
                    ...prev,
                    valueRange: {
                        ...prev.valueRange,
                        [child]: Number(value) || 0
                    }
                }));
            }
        } else {
            setFilters(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleDateTypeChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const type = e.target.value as Filters['dateType'];
        const now = new Date();
        let start = "";
        let end = "";

        const formatDate = (date: Date) => {
            return date.toISOString().split('T')[0];
        };

        switch (type) {
            case "hoje":
                start = formatDate(now);
                end = formatDate(now);
                break;
            case "esse_mes":
                const firstDayOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
                const lastDayOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
                start = formatDate(firstDayOfMonth);
                end = formatDate(lastDayOfMonth);
                break;
            case "mes_passado":
                start = formatDate(new Date(now.getFullYear(), now.getMonth() - 1, 1));
                end = formatDate(new Date(now.getFullYear(), now.getMonth(), 0));
                break;
            case "ultimo_semestre":
                start = formatDate(new Date(now.getFullYear(), now.getMonth() - 6, 1));
                end = formatDate(new Date(now.getFullYear(), now.getMonth(), 0));
                break;
            case "esse_ano":
                start = formatDate(new Date(now.getFullYear(), 0, 1));
                end = formatDate(new Date(now.getFullYear(), 11, 31));
                break;
            case "personalizado":
                start = filters.dateRange.start;
                end = filters.dateRange.end;
                break;
        }

        setFilters(prev => ({
            ...prev,
            dateType: type,
            dateRange: { start, end }
        }));
    };

    const resetFilters = () => {
        setFilters({
            dateRange: { start: "", end: "" },
            dateType: "personalizado",
            customerName: "",
            productName: "",
            status: "",
            orderType: "",
            seller: "",
            valueRange: { min: 0, max: 1000000 },
            sortBy: "date",
            sortOrder: "desc",
            multiSort: [{ key: 'date', order: 'desc' }],
            searchId: "",
            isBudgetView: filters.isBudgetView,
            isAssistanceView: filters.isAssistanceView
        });
    };

    return (
        <aside className="w-full bg-white dark:bg-slate-900 flex flex-col h-full overflow-y-auto transition-colors">
            <div className="p-4 md:p-8 border-b border-slate-50 dark:border-slate-800">
                <h3 className="text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight flex items-center gap-3">
                    <i className="bi bi-filter-left text-blue-600 dark:text-blue-500"></i>
                    Filtros
                </h3>
                <p className="text-[10px] uppercase font-black text-slate-400 dark:text-slate-500 tracking-widest mt-1">Refine sua busca de pedidos</p>
            </div>

            <div className="p-4 md:p-8 flex flex-col gap-6">
                {filters.searchId && (
                    <div className="flex items-center justify-between p-3 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-xl">
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black uppercase text-blue-500 tracking-widest">Filtrando por Código:</span>
                            <span className="text-sm font-bold text-blue-700 dark:text-blue-400 font-mono">{filters.searchId.slice(-8)}</span>
                        </div>
                        <button
                            onClick={() => setFilters(prev => ({ ...prev, searchId: "" }))}
                            className="p-2 text-blue-400 hover:text-blue-600 dark:hover:text-blue-300 hover:bg-blue-100 dark:hover:bg-blue-800/50 rounded-lg transition-colors"
                        >
                            <i className="bi bi-x-lg text-lg"></i>
                        </button>
                    </div>
                )}

                {/* Search Inputs */}
                <div className="flex flex-col gap-6">
                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Cliente</label>
                        <div className="relative">
                            <i className="bi bi-person absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600"></i>
                            <input
                                type="text"
                                name="customerName"
                                value={filters.customerName}
                                onChange={handleChange}
                                placeholder="Nome do cliente..."
                                className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm dark:text-slate-300 placeholder:text-slate-300 dark:placeholder:text-slate-700 min-w-[160px]"
                            />
                        </div>
                    </div>

                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Produto</label>
                        <div className="relative">
                            <i className="bi bi-box absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600"></i>
                            <input
                                type="text"
                                name="productName"
                                value={filters.productName}
                                onChange={handleChange}
                                placeholder="Título do produto..."
                                className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm dark:text-slate-300 placeholder:text-slate-300 dark:placeholder:text-slate-700 min-w-[160px]"
                            />
                        </div>
                    </div>

                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Status</label>
                        <select
                            name="status"
                            value={filters.status}
                            onChange={handleChange}
                            className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm appearance-none cursor-pointer dark:text-slate-300 min-w-[140px]"
                        >
                            <option value="">Todos os Status</option>
                            <option value="draft">Rascunho</option>
                            <option value="waiting">Aguardando</option>
                            <option value="scheduled">Agendado</option>
                            <option value="in_transit">Em Trânsito</option>
                            <option value="delivered">Entregue</option>
                            <option value="fulfilled">Atendido</option>
                            <option value="cancelled">Cancelado</option>
                        </select>
                    </div>

                    {!filters.isBudgetView && !filters.isAssistanceView && (
                        <div className="flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Tipo de Pedido</label>
                            <select
                                name="orderType"
                                value={filters.orderType}
                                onChange={handleChange}
                                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm appearance-none cursor-pointer dark:text-slate-300 min-w-[140px]"
                            >
                                <option value="">Todos os Tipos</option>
                                <option value="sale">Venda</option>
                                <option value="showroom">Showroom</option>
                            </select>
                        </div>
                    )}

                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Atendente Principal</label>
                        <div className="relative">
                            <i className="bi bi-person-badge absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600"></i>
                            <input
                                type="text"
                                name="seller"
                                value={filters.seller}
                                onChange={handleChange}
                                placeholder="Nome do atendente..."
                                className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm dark:text-slate-300 placeholder:text-slate-300 dark:placeholder:text-slate-700 min-w-[160px]"
                            />
                        </div>
                    </div>
                </div>

                {/* Date Range Selection */}
                <div className="flex flex-col gap-4">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-800 dark:text-slate-300 border-b border-slate-50 dark:border-slate-800 pb-2">Período</h4>
                    <div className="flex flex-col gap-4">
                        <div className="flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Tipo de Período</label>
                            <select
                                name="dateType"
                                value={filters.dateType}
                                onChange={handleDateTypeChange}
                                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm appearance-none cursor-pointer dark:text-slate-300 min-w-[140px]"
                            >
                                <option value="personalizado" className="dark:bg-slate-900">Personalizado</option>
                                <option value="hoje" className="dark:bg-slate-900">Hoje</option>
                                <option value="esse_mes" className="dark:bg-slate-900">Esse Mês</option>
                                <option value="mes_passado" className="dark:bg-slate-900">Mês Passado</option>
                                <option value="ultimo_semestre" className="dark:bg-slate-900">Último Semestre</option>
                                <option value="esse_ano" className="dark:bg-slate-900">Esse Ano</option>
                            </select>
                        </div>

                        {filters.dateType === "personalizado" && (
                            <div className="grid grid-cols-1 gap-4 animate-fade-in">
                                <div className="flex flex-col gap-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Início</label>
                                    <input
                                        type="date"
                                        name="dateRange.start"
                                        value={filters.dateRange.start}
                                        onChange={handleChange}
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm dark:text-slate-300"
                                    />
                                </div>
                                <div className="flex flex-col gap-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Fim</label>
                                    <input
                                        type="date"
                                        name="dateRange.end"
                                        value={filters.dateRange.end}
                                        onChange={handleChange}
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm dark:text-slate-300"
                                    />
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                {/* Values Selection */}
                <div className="flex flex-col gap-6">
                    <div className="flex flex-col gap-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Valor Mínimo</label>
                        <div className="relative">
                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600 text-xs font-bold">R$</span>
                            <input
                                type="number"
                                name="valueRange.min"
                                value={filters.valueRange.min}
                                onChange={handleChange}
                                className="w-full pl-10 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm dark:text-slate-300"
                            />
                        </div>
                    </div>
                </div>
            </div>

            <div className="mt-auto p-4 border-t border-slate-50 dark:border-slate-800">
                <button
                    onClick={resetFilters}
                    className="w-full py-4 text-xs font-black uppercase tracking-widest text-slate-400 dark:text-slate-600 hover:text-red-500 dark:hover:text-red-400 transition-colors flex items-center justify-center gap-2"
                >
                    <i className="bi bi-arrow-counterclockwise"></i>
                    Limpar Filtros
                </button>
            </div>
        </aside>
    );
};

