import React, { useEffect, useRef, useState } from 'react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { getSettings } from '@/pages/utils/settingsService';
import { autoCalculateRouteDistance, searchAddressSuggestions, RouteResult } from '@/pages/utils/maps';
import { formatCurrency } from '@/pages/utils/formatters';
import DropdownPortal from '@/components/shared/DropdownPortal';
import { AddressAutocompleteInput } from '@/components/shared/AddressAutocompleteInput';
import { calculateFreightByDistance } from '@/pages/utils/shippingPricing';

const FreightCalculation = () => {
    const mapContainer = useRef<HTMLDivElement>(null);
    const mapRef = useRef<maplibregl.Map | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [suggestions, setSuggestions] = useState<any[]>([]);
    const [routeResult, setRouteResult] = useState<RouteResult | null>(null);
    const searchContainerRef = useRef<HTMLDivElement>(null);

    const [addressForm, setAddressForm] = useState({
        street: '',
        number: '',
        neighborhood: '',
        city: 'Colombo',
        state: 'PR',
        cep: '',
        complement: '',
        observation: ''
    });

    const settings = getSettings();
    const origin: [number, number] = settings.storeOriginCoords;

    const handleSearch = async (query: string) => {
        if (query.length < 3) {
            setSuggestions([]);
            return;
        }
        const results = await searchAddressSuggestions(query);
        setSuggestions(results);
    };

    const handleSelectSuggestion = (suggestion: any) => {
        const addr = suggestion.address;
        setAddressForm({
            street: addr.road || addr.pedestrian || '',
            number: addr.house_number || '',
            neighborhood: addr.suburb || addr.neighbourhood || '',
            city: addr.city || addr.town || addr.village || 'Colombo',
            state: addr.state || 'PR',
            cep: addr.postcode || '',
            complement: '',
            observation: ''
        });
        setSuggestions([]);
    };

    const calculateFreight = async () => {
        setLoading(true);
        setError(null);
        try {
            const result = await autoCalculateRouteDistance(addressForm);
            if (result) {
                setRouteResult(result);
            } else {
                setError("Não foi possível calcular a rota para este endereço. Verifique os dados.");
            }
        } catch (err) {
            setError("Erro ao processar cálculo. Tente novamente.");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (!mapContainer.current) return;

        const map = new maplibregl.Map({
            container: mapContainer.current,
            style: 'https://basemaps.cartocdn.com/gl/positron-gl-style/style.json',
            center: origin,
            zoom: 12,
            attributionControl: false
        });

        mapRef.current = map;
        map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');

        map.on('load', () => {
            // Store marker (red)
            const storeEl = document.createElement('div');
            storeEl.innerHTML = `<svg width="32" height="44" viewBox="0 0 32 44" fill="none" xmlns="http://www.w3.org/2000/svg">
                 <path d="M16 0C7.16 0 0 7.16 0 16c0 12 16 28 16 28s16-16 16-28C32 7.16 24.84 0 16 0z" fill="#dc2626"/>
                 <circle cx="16" cy="16" r="6" fill="white"/>
             </svg>`;
            new maplibregl.Marker({ element: storeEl, anchor: 'bottom' })
                .setLngLat(origin)
                .setPopup(new maplibregl.Popup({ offset: 25 }).setHTML('<strong>Nossa Loja</strong>'))
                .addTo(map);

            if (routeResult) {
                // Destination marker (blue)
                const destEl = document.createElement('div');
                destEl.innerHTML = `<svg width="32" height="44" viewBox="0 0 32 44" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M16 0C7.16 0 0 7.16 0 16c0 12 16 28 16 28s16-16 16-28C32 7.16 24.84 0 16 0z" fill="#2563eb"/>
                    <circle cx="16" cy="16" r="6" fill="white"/>
                </svg>`;
                new maplibregl.Marker({ element: destEl, anchor: 'bottom' })
                    .setLngLat(routeResult.destinationCoords)
                    .setPopup(new maplibregl.Popup({ offset: 25 }).setHTML('<strong>Entrega</strong>'))
                    .addTo(map);

                // Add route line
                if (routeResult.routeGeoJSON) {
                    map.addSource('route', {
                        type: 'geojson',
                        data: {
                            type: 'Feature',
                            properties: {},
                            geometry: routeResult.routeGeoJSON
                        }
                    });

                    map.addLayer({
                        id: 'route-layer',
                        type: 'line',
                        source: 'route',
                        layout: { 'line-join': 'round', 'line-cap': 'round' },
                        paint: {
                            'line-color': '#3b82f6',
                            'line-width': 5,
                            'line-opacity': 0.8
                        }
                    });

                    const bounds = new maplibregl.LngLatBounds();
                    bounds.extend(origin);
                    bounds.extend(routeResult.destinationCoords);
                    routeResult.routeGeoJSON.coordinates.forEach((coord: [number, number]) => bounds.extend(coord));
                    map.fitBounds(bounds, { padding: 50, maxZoom: 15 });
                }
            }
        });

        return () => {
            if (mapRef.current) mapRef.current.remove();
        };
    }, [routeResult, origin]);

    return (
        <div className="flex flex-col h-full bg-slate-50 dark:bg-slate-950">
            <header className="p-6 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 shrink-0">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight">Cálculo de Frete</h2>
                        <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mt-1">Simulação de custos logísticos por distância</p>
                    </div>

                    {routeResult && (
                        <div className="flex gap-4 animate-fade-in">
                            <div className="bg-blue-50 dark:bg-blue-900/20 px-4 py-2 rounded-2xl border border-blue-100 dark:border-blue-900/30">
                                <p className="text-[9px] font-black uppercase tracking-widest text-blue-400 mb-0.5">Distância</p>
                                <p className="text-lg font-black text-blue-700 dark:text-blue-300 tracking-tight">{routeResult.distanceKm} km</p>
                            </div>
                            <div className="bg-emerald-50 dark:bg-emerald-900/20 px-4 py-2 rounded-2xl border border-emerald-100 dark:border-emerald-900/30">
                                <p className="text-[9px] font-black uppercase tracking-widest text-emerald-400 mb-0.5">Valor Sugerido</p>
                                <p className="text-lg font-black text-emerald-700 dark:text-emerald-300 tracking-tight">
                                    {formatCurrency(calculateFreightByDistance(routeResult.distanceKm))}
                                </p>
                            </div>
                        </div>
                    )}
                </div>
            </header>

            <div className="flex-1 flex flex-col overflow-hidden">
                {/* Fixed Search Form */}
                <div className="p-6 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-20">
                    <div className="max-w-4xl mx-auto space-y-6">
                        <div className="relative group" ref={searchContainerRef}>
                            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 group-focus-within:text-blue-500 transition-colors mb-2 block">
                                Digite o Endereço para Pesquisa Rápida
                            </label>
                            <div className="relative">
                                <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                                <input
                                    type="text"
                                    placeholder="Ex: R. Cascavel, Colombo..."
                                    className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-700 rounded-3xl text-sm font-bold focus:outline-none focus:ring-4 focus:ring-blue-100 dark:focus:ring-blue-900/20 transition-all placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                    onChange={(e) => handleSearch(e.target.value)}
                                />
                                <DropdownPortal anchorRef={searchContainerRef} isOpen={suggestions.length > 0}>
                                    <div className="mt-2 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-[2rem] shadow-2xl overflow-hidden animate-slide-up">
                                        {suggestions.map((s, idx) => (
                                            <button
                                                key={idx}
                                                onClick={() => handleSelectSuggestion(s)}
                                                className="w-full p-4 text-left hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors flex items-center gap-4 border-b border-slate-50 dark:border-slate-800 last:border-0"
                                            >
                                                <div className="w-8 h-8 bg-slate-100 dark:bg-slate-800 rounded-xl flex items-center justify-center shrink-0">
                                                    <i className="bi bi-geo-alt-fill text-slate-400" />
                                                </div>
                                                <div>
                                                    <p className="text-sm font-bold text-slate-700 dark:text-slate-200 line-clamp-1">{s.display_name}</p>
                                                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{s.address.suburb || s.address.city}</p>
                                                </div>
                                            </button>
                                        ))}
                                    </div>
                                </DropdownPortal>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                            <AddressAutocompleteInput
                                value={addressForm.street}
                                onChange={(val) => setAddressForm({ ...addressForm, street: val })}
                                onSelectAddress={(data) => {
                                    setAddressForm(prev => ({
                                        ...prev,
                                        street: data.street,
                                        number: data.number || prev.number,
                                        neighborhood: data.neighborhood || prev.neighborhood,
                                        city: data.city || prev.city,
                                        state: data.state || prev.state,
                                        cep: data.cep || prev.cep,
                                    }));
                                }}
                                cityHint={addressForm.city}
                                stateHint={addressForm.state || 'PR'}
                                label="Rua"
                                className="md:col-span-2"
                                inputClassName="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-50 dark:border-slate-700 rounded-2xl text-xs font-bold text-slate-800 dark:text-slate-100"
                            />
                            <div>
                                <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 mb-1.5 block">Nº</label>
                                <input
                                    type="text"
                                    value={addressForm.number}
                                    onChange={(e) => setAddressForm({ ...addressForm, number: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-50 dark:border-slate-700 rounded-2xl text-xs font-bold"
                                />
                            </div>
                            <div>
                                <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 mb-1.5 block">Bairro</label>
                                <input
                                    type="text"
                                    value={addressForm.neighborhood}
                                    onChange={(e) => setAddressForm({ ...addressForm, neighborhood: e.target.value })}
                                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-800/50 border border-slate-50 dark:border-slate-700 rounded-2xl text-xs font-bold"
                                />
                            </div>
                        </div>

                        <div className="flex flex-wrap items-center justify-between gap-4 pt-2">
                            <div className="flex gap-4">
                                <div className="bg-slate-50 dark:bg-slate-800 px-4 py-2 rounded-xl">
                                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Cidade: </span>
                                    <span className="text-[10px] font-black text-slate-800 dark:text-slate-100">{addressForm.city}</span>
                                </div>
                                <div className="bg-slate-50 dark:bg-slate-800 px-4 py-2 rounded-xl">
                                    <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">UF: </span>
                                    <span className="text-[10px] font-black text-slate-800 dark:text-slate-100">{addressForm.state}</span>
                                </div>
                            </div>

                            <button
                                onClick={calculateFreight}
                                disabled={loading || !addressForm.street}
                                className="w-full md:w-auto px-8 py-4 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 dark:disabled:bg-slate-800 text-white rounded-3xl font-black uppercase tracking-[0.2em] text-xs shadow-xl shadow-blue-200 dark:shadow-none transition-all flex items-center justify-center gap-3"
                            >
                                {loading ? (
                                    <>
                                        <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                                        Calculando...
                                    </>
                                ) : (
                                    <>
                                        <i className="bi bi-calculator" />
                                        Calcular Valor
                                    </>
                                )}
                            </button>
                        </div>

                        {error && (
                            <div className="p-4 bg-rose-50 dark:bg-rose-900/10 border border-rose-100 dark:border-rose-900/30 rounded-2xl animate-fade-in">
                                <p className="text-xs font-bold text-rose-600 dark:text-rose-400 flex items-center gap-2">
                                    <i className="bi bi-exclamation-circle-fill" /> {error}
                                </p>
                            </div>
                        )}
                    </div>
                </div>

                <div className="flex-1 relative">
                    <div ref={mapContainer} className="w-full h-full" />
                </div>
            </div>
        </div>
    );
};

export default FreightCalculation;

import React from "react";
import ItemsTable from '../ItemsTable';
import ShippingInputs from './ShippingData';
import PaymentsTable from '../PaymentsTable/Index';
import PersonalInfos from './CustomerData';
import FormHeader from './FormHeader';
import FormFooter from './FormFooter';
import SectionCard from '@/components/SectionCard';
import { useSalesOrderForm } from '../useSalesOrderForm';
import NoticeInput from '@/components/NoticeInput';


import { getSettings } from '@/pages/utils/settingsService';

import SellerInput from './SellerInput';

type SalesOrderFormSectionProps = {
    form: ReturnType<typeof useSalesOrderForm>;
    scrollRef?: React.RefObject<HTMLDivElement>;
    onLoadJSON?: (data: any) => void;
    onOpenSellerSearch?: () => void;
    sellerRef?: React.RefObject<HTMLButtonElement>;
    /** Se true, destaca visualmente os itens sem produto vinculado (temporários) */
    highlightTemporaryItems?: boolean;
};

const SalesOrderFormSection = ({ form, scrollRef, onLoadJSON, onOpenSellerSearch, sellerRef, highlightTemporaryItems }: SalesOrderFormSectionProps) => {
    const { state, actions } = form;
    const isPickup = state.shipping.deliveryMethod === 'pickup';
    const { currentStep } = state;
    const isBudget = state.currentOrder.orderType === 'budget';
    const isReturn = state.currentOrder.orderType === 'return';
    const [itemsTab, setItemsTab] = React.useState<'products' | 'services'>('products');
    
    // Resolve all handling options
    const settings = getSettings();
    const allOptions = [
        ...(settings.deliveryHandlingOptions || []),
        ...(settings.pickupHandlingOptions || [])
    ];

    return (
        <form
            className="flex flex-col w-full h-full bg-white dark:bg-slate-900 relative transition-colors duration-300 overflow-hidden"
            onKeyDown={(e) => { if (e.key === 'Enter') e.preventDefault(); }}
        >
            {/* Scrollable Body */}
            <div 
                ref={scrollRef}
                className="flex-1 overflow-y-auto p-4 md:p-8 pt-4 custom-scrollbar"
            >
                {/* Wizard Steps Content */}
                <div className="max-w-[1400px] mx-auto pb-10">
                    {currentStep === 1 && (
                        <div className="max-w-4xl mx-auto animate-fade-in space-y-6">
                            <FormHeader
                                currentOrder={state.currentOrder}
                                onClearForm={actions.clearForm}
                                orderDate={state.orderDate}
                                setOrderDate={actions.setOrderDate}
                                seller={state.seller}
                                setSeller={actions.setSeller}
                                isSavingDraft={state.isSavingDraft}
                                errors={state.errors}
                                deliveryMethod={state.shipping.deliveryMethod}
                                setDeliveryMethod={(method) => actions.setShipping(prev => ({ ...prev, deliveryMethod: method }))}
                                status={state.status}
                                isSaving={state.isSaving}
                                onMainAction={state.status === 'draft' ? actions.handleCompleteOrder : actions.handleSaveOrder}
                                currentOrderId={state.currentOrderId}
                                isBudget={isBudget}
                                onLoadJSON={onLoadJSON}
                            />

                            <SectionCard
                                icon="bi bi-info-circle"
                                iconBg="bg-blue-600 shadow-blue-100 dark:shadow-blue-900/20"
                                title="Informações básicas"
                            >
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <SellerInput
                                        value={state.seller}
                                        sellerId={state.sellerId}
                                        onChange={actions.setSeller}
                                        onSelectSeller={(sellerData) => {
                                            if (actions.setSellerData) {
                                                actions.setSellerData(sellerData);
                                            } else {
                                                actions.setSeller(sellerData.name);
                                            }
                                        }}
                                        onAddNewSeller={onOpenSellerSearch}
                                    />

                                    <div className="flex flex-col relative w-full group">
                                        <div className="flex items-center justify-between mb-2 ml-1">
                                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 flex items-center gap-1.5">
                                                <i className="bi bi-calendar-event text-blue-500 text-xs" />
                                                Data do Pedido
                                            </label>
                                        </div>

                                        <input
                                            type="datetime-local"
                                            value={state.orderDate}
                                            onChange={(e) => actions.setOrderDate(e.target.value)}
                                            className="w-full border-b-2 border-slate-200 bg-transparent px-3 py-3 text-sm font-bold text-slate-800 outline-none transition-colors focus:border-blue-600 dark:border-slate-700 dark:text-slate-100 dark:focus:border-blue-500 [color-scheme:light] dark:[color-scheme:dark]"
                                        />
                                    </div>
                                </div>
                            </SectionCard>
                        </div>
                    )}

                    {currentStep === 2 && (
                        <div className="flex flex-col gap-6 animate-fade-in">
                            <SectionCard
                                icon="bi bi-box-seam"
                                iconBg="bg-blue-600 shadow-blue-100 dark:shadow-blue-900/20"
                                title="Itens do Pedido"
                                compactHeader
                            >
                                <ItemsTable
                                    items={state.items}
                                    setItems={actions.setItems}
                                    summary={state.itemsSummary}
                                    deliveryMethod={state.shipping.deliveryMethod}
                                    errors={state.errors}
                                    onSelectProduct={actions.handleSelectProduct}
                                    isBudget={isBudget}
                                    isReturn={isReturn}
                                    highlightTemporaryItems={highlightTemporaryItems}
                                    activeTab={itemsTab}
                                    onTabChange={setItemsTab}
                                />
                            </SectionCard>
                        </div>
                    )}

                    {currentStep === 3 && (
                        <div className="max-w-4xl mx-auto animate-fade-in space-y-8">
                            <SectionCard
                                icon="bi bi-person-badge"
                                iconBg="bg-purple-600 shadow-purple-100 dark:shadow-purple-900/20"
                                title="Cliente"
                                className="bg-white dark:bg-slate-900"
                            >
                                <PersonalInfos
                                    customerData={state.customerData}
                                    setCustomerData={actions.setCustomerData}
                                    errors={state.errors}
                                    isPickup={isPickup}
                                    marketingOrigin={state.marketingOrigin}
                                    setMarketingOrigin={actions.setMarketingOrigin}
                                    isBudget={isBudget}
                                />
                            </SectionCard>

                        </div>
                    )}

                    {currentStep === 4 && (
                        <div className="max-w-4xl mx-auto animate-fade-in space-y-8">
                            <SectionCard
                                icon={isPickup ? "bi bi-shop" : "bi bi-truck"}
                                iconBg={isPickup ? "bg-emerald-500 shadow-emerald-100 dark:shadow-emerald-900/20" : "bg-orange-500 shadow-orange-100 dark:shadow-orange-900/20"}
                                title={isBudget ? "Frete e Entrega" : "Logística"}
                                className="bg-white dark:bg-slate-900 transition-colors duration-300"
                            >
                                <ShippingInputs
                                    shipping={state.shipping}
                                    setShipping={actions.setShipping}
                                    customerData={state.customerData}
                                    isCalculatingDistance={state.isCalculatingDistance}
                                    onAutoCalculateDistance={() => {
                                        const targetAddr = (state.shipping.useCustomerAddress === false && state.shipping.deliveryAddress)
                                            ? state.shipping.deliveryAddress
                                            : state.customerData.fullAddress;
                                        actions.handleAutoCalculateDistance(targetAddr);
                                    }}
                                    errors={state.errors}
                                    orderType={state.currentOrder.orderType}
                                />
                            </SectionCard>

                            <SectionCard
                                icon="bi bi-info-circle-fill"
                                iconBg="bg-amber-600 shadow-amber-100 dark:shadow-amber-900/20"
                                title={isBudget ? "Avisos sobre o Orçamento" : (isPickup ? "Avisos sobre a Retirada" : "Avisos sobre a Entrega")}
                                className="bg-white dark:bg-slate-900"
                            >
                                <NoticeInput
                                    value={state.observation}
                                    onChange={(val) => actions.setObservation(val)}
                                    placeholder={isBudget ? "Observações gerais da proposta..." : (isPickup ? "Instruções específicas para a retirada..." : "Instruções específicas para a entrega/montagem...")}
                                />
                            </SectionCard>
                        </div>
                    )}

                    {currentStep === 5 && (
                        <div className="max-w-5xl mx-auto animate-fade-in">
                            <SectionCard
                                icon={isBudget ? "bi bi-calculator" : "bi bi-credit-card-2-front"}
                                iconBg="bg-indigo-600 shadow-indigo-100 dark:shadow-indigo-900/20"
                                title="Pagamentos"
                                action={
                                    <button
                                        type="button"
                                        onClick={() => actions.setPayments((payments) => [...payments, {
                                            method: 'Verificar', amount: 0, fee: 0, feeType: 'fixed', status: ''
                                        }])}
                                        className="flex items-center gap-2 rounded-xl bg-indigo-600 px-3 py-2 text-[10px] font-black uppercase tracking-wider text-white transition-all hover:bg-indigo-700 active:scale-95"
                                    >
                                        <i className="bi bi-plus-lg" />
                                        <span className="hidden sm:inline">Adicionar pagamento</span>
                                    </button>
                                }
                            >
                                <div className="overflow-x-auto rounded-3xl border border-slate-100 bg-white transition-colors duration-300 dark:border-slate-800 dark:bg-slate-900">
                                    {isBudget && state.payments.length === 0 && (
                                        <div className="p-8 bg-slate-50/50 dark:bg-slate-800/30 border-b border-slate-100 dark:border-slate-800 flex flex-col items-center gap-4 text-center">
                                            <div className="flex flex-col gap-1">
                                                <p className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Apenas orçamento de valores?</p>
                                                <p className="text-[11px] text-slate-400 font-medium">Você pode pular esta etapa se não precisar definir as formas de pagamento agora.</p>
                                            </div>
                                            <button 
                                                type="button"
                                                onClick={actions.goToNextStep}
                                                className="px-6 py-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 dark:text-indigo-400 hover:bg-slate-50 dark:hover:bg-slate-800 hover:border-indigo-200 transition-all flex items-center gap-3 shadow-sm hover:shadow-md active:scale-95"
                                            >
                                                <i className="bi bi-fast-forward-fill text-sm" /> Não Informar Pagamento / Ir para Resumo
                                            </button>
                                        </div>
                                    )}
                                    <PaymentsTable
                                        payments={state.payments}
                                        setPayments={actions.setPayments}
                                        summary={state.paymentsSummary}
                                        errors={state.errors}
                                    />
                                </div>
                            </SectionCard>
                        </div>
                    )}

                </div>
            </div>

            <FormFooter
                currentOrder={state.currentOrder}
                totalOrderValue={state.paymentsSummary.totalOrderValue}
                isSaving={state.isSaving}
                isSavingDraft={state.isSavingDraft}
                onCompleteOrder={state.status === 'draft' ? actions.handleCompleteOrder : actions.handleSaveOrder}
                onPrev={actions.goToPrevStep}
                onNext={actions.goToNextStep}
                currentStep={currentStep}
                buttonLabel={isBudget ? "Salvar Orçamento" : (state.status === 'draft' ? "Finalizar Cadastro" : "Salvar Edição")}
                colorScheme={isBudget ? "indigo" : (state.status === 'draft' ? "emerald" : "blue")}
            />
            
            <style dangerouslySetInnerHTML={{ __html: `@keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } } .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }` }} />
        </form>
    );
};

export default SalesOrderFormSection;

import React, { useState, useEffect, useRef } from 'react';
import { subscribeToPeople } from '@/pages/utils/personService';
import Person from '@/pages/types/person.type';
import { isValidEmployee } from '@/pages/utils/accessRoles';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

interface SellerInputProps {
    value: string;
    sellerId?: string;
    onChange: (sellerName: string) => void;
    onSelectSeller?: (seller: { name: string; id?: string }) => void;
    onAddNewSeller?: () => void;
    placeholder?: string;
    className?: string;
    isAIFilling?: boolean;
}

export const SellerInput: React.FC<SellerInputProps> = ({
    value,
    sellerId,
    onChange,
    onSelectSeller,
    onAddNewSeller,
    placeholder = "Digite para buscar vendedor...",
    className = "",
    isAIFilling = false
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const [employees, setEmployees] = useState<Person[]>([]);
    const [filterText, setFilterText] = useState(value || '');
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        setFilterText(value || '');
    }, [value]);

    useEffect(() => {
        const unsub = subscribeToPeople('employees', (data) => {
            const validEmployees = data.filter(e => isValidEmployee(e));
            setEmployees(validEmployees);
        });
        return unsub;
    }, []);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const filtered = employees.filter(e => {
        const term = normalizeSearchTerm(filterText);
        return (
            normalizeSearchTerm(e.fullName || '').includes(term) ||
            normalizeSearchTerm(e.nickname || '').includes(term) ||
            normalizeSearchTerm(e.position || '').includes(term)
        );
    });

    return (
        <div ref={containerRef} className={`relative flex-1 flex flex-col group ${className}`}>
            <div className="flex items-center justify-between mb-2 ml-1">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 flex items-center gap-1.5">
                    <i className="bi bi-person-badge text-blue-500 text-xs" />
                    Vendedor
                </label>

                {isAIFilling && (
                    <span className="px-2.5 py-0.5 rounded-full bg-gradient-to-r from-violet-600 to-indigo-600 text-white text-[9px] font-black uppercase tracking-wider flex items-center gap-1 shadow-sm animate-pulse">
                        <i className="bi bi-stars" /> IA trabalhando neste campo...
                    </span>
                )}
            </div>

            <div className="relative flex items-center">
                <input
                    type="text"
                    value={filterText}
                    onChange={(e) => {
                        const newVal = e.target.value;
                        setFilterText(newVal);
                        onChange(newVal);
                        setIsOpen(true);
                    }}
                    onFocus={() => setIsOpen(true)}
                    placeholder={placeholder}
                    className={`w-full border-b-2 bg-transparent px-3 py-3 text-sm font-bold text-slate-800 placeholder:text-slate-400 outline-none transition-colors dark:text-slate-100 dark:placeholder:text-slate-600 ${
                        isAIFilling
                        ? 'border-violet-500 animate-pulse bg-violet-50/20 dark:bg-violet-950/20'
                        : 'border-slate-200 dark:border-slate-700 focus:border-blue-600 dark:focus:border-blue-500'
                    }`}
                />
                <div className="absolute right-4 top-1/2 -translate-y-1/2 flex items-center gap-2">
                    {filterText ? (
                        <button
                            type="button"
                            onClick={(e) => {
                                e.stopPropagation();
                                setFilterText('');
                                onChange('');
                                setIsOpen(true);
                            }}
                            className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors"
                            title="Limpar vendedor"
                        >
                            <i className="bi bi-x-circle-fill text-sm" />
                        </button>
                    ) : (
                        <i className={`bi bi-chevron-down text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
                    )}
                </div>
            </div>

            {/* Dropdown Modal que aparece diretamente abaixo do campo de texto com base no filtro */}
            {isOpen && (
                <div className="absolute top-[calc(100%+6px)] left-0 right-0 z-50 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl max-h-64 overflow-y-auto custom-scrollbar p-1.5 animate-slide-up">
                    {filtered.length > 0 ? (
                        <div className="flex flex-col gap-0.5">
                            {filtered.map((e) => {
                                const sellerName = e.nickname || e.fullName;
                                const isSelected = (sellerId && String(e.id) === String(sellerId)) || (value || '').toLowerCase() === sellerName.toLowerCase() || (value || '').toLowerCase() === e.fullName.toLowerCase();
                                return (
                                    <button
                                        key={e.id}
                                        type="button"
                                        onClick={() => {
                                            onChange(sellerName);
                                            if (onSelectSeller) {
                                                onSelectSeller({ name: sellerName, id: e.id ? String(e.id) : undefined });
                                            }
                                            setFilterText(sellerName);
                                            setIsOpen(false);
                                        }}
                                        className={`flex items-center justify-between p-2.5 rounded-xl transition-all text-left w-full ${
                                            isSelected 
                                                ? 'bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 font-bold' 
                                                : 'hover:bg-slate-50 dark:hover:bg-slate-800/60 text-slate-700 dark:text-slate-200'
                                        }`}
                                    >
                                        <div className="flex items-center gap-2.5 min-w-0">
                                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${isSelected ? 'bg-blue-600 text-white' : 'bg-slate-100 dark:bg-slate-800 text-slate-500'}`}>
                                                <i className="bi bi-person-fill text-sm" />
                                            </div>
                                            <div className="flex flex-col min-w-0">
                                                <span className="text-xs font-bold truncate">{e.fullName}</span>
                                                <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-tight">
                                                    {e.nickname && <span className="text-blue-500">@{e.nickname}</span>}
                                                    {e.position && <span>• {e.position}</span>}
                                                </div>
                                            </div>
                                        </div>
                                        {isSelected && <i className="bi bi-check-lg text-blue-600 dark:text-blue-400 text-base ml-2 shrink-0" />}
                                    </button>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="p-4 text-center">
                            <span className="text-xs font-medium text-slate-400 block mb-1">Nenhum vendedor encontrado</span>
                        </div>
                    )}

                    {onAddNewSeller && (
                        <button
                            type="button"
                            onClick={() => {
                                setIsOpen(false);
                                onAddNewSeller();
                            }}
                            className="flex items-center justify-center gap-2 w-full p-2.5 mt-1 border-t border-slate-100 dark:border-slate-800 text-xs font-bold text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/30 rounded-xl transition-all"
                        >
                            <i className="bi bi-plus-circle-fill text-sm" />
                            <span>Cadastrar Novo Vendedor</span>
                        </button>
                    )}
                </div>
            )}
        </div>
    );
};
export default SellerInput;

import React from "react";
import { AddressAutocompleteInput } from "@/components/shared/AddressAutocompleteInput";
import Shipping from '@/pages/types/Shipping.type';
import CustomerData from '@/pages/types/customerData.type';
import { getShippingRouteUrl, getAddressByCep } from '@/pages/utils/maps';
import { ValidationErrors } from '@/pages/utils/validations';
import { calculateFreightByDistance } from '@/pages/utils/shippingPricing';
import FreteDistancia from '../ShippingComponents/FreteDistancia';
import Agendamento from '../ShippingComponents/Agendamento';
import MapRoute from '../ShippingComponents/MapRoute';
import { PatternFormat as PatternFormatBase } from "react-number-format";
const PatternFormat = PatternFormatBase as any;
import SmartInput from '@/components/SmartInput';
import AddressVerificationMap from './AddressVerificationMap';

interface Props {
    shipping: Shipping;
    setShipping: React.Dispatch<React.SetStateAction<Shipping>>;
    customerData: CustomerData;
    isCalculatingDistance?: boolean;
    onAutoCalculateDistance?: () => void;
    errors: ValidationErrors;
    orderType?: string;
}

const ShippingData = ({ shipping, setShipping, customerData, isCalculatingDistance, onAutoCalculateDistance, errors, orderType }: Props) => {
    
    // Auto-enable noAddress for "Consumidor Final" or if it is a Pickup
    React.useEffect(() => {
        const isFinalConsumer = customerData.fullName?.toLowerCase().trim() === 'consumidor final';
        const isPickup = shipping.deliveryMethod === 'pickup';
        
        if ((isFinalConsumer || isPickup) && !shipping.noAddress) {
            setShipping(prev => ({ ...prev, noAddress: true }));
        }
    }, [customerData.fullName, shipping.deliveryMethod]);

    const activeAddress = orderType === 'budget' 
        ? customerData.fullAddress
        : ((shipping.useCustomerAddress === false) && shipping.deliveryAddress
            ? shipping.deliveryAddress
            : customerData.fullAddress);

    const route = getShippingRouteUrl(activeAddress);
    const onChangeShippingValue = (newValue: number) => {
        setShipping((prev: Shipping) => ({ ...prev, value: newValue, autoCalculateValue: false }));
    };

    const onChangeDistance = (newValue: string) => {
        const numValue = parseFloat(newValue.replace(',', '.'));
        setShipping((prev: Shipping) => {
            const distance = Number.isFinite(numValue) && numValue > 0 ? numValue : undefined;
            let value = prev.value;

            // Calcula o frete baseado na distância APENAS se o cálculo automático estiver ativado
            if (distance !== undefined && prev.autoCalculateValue) {
                value = calculateFreightByDistance(distance);
            }

            return { ...prev, distance, value };
        });
    };

    const onChangeScheduling = (
        key: keyof Shipping["scheduling"],
        value: string | Date | boolean
    ) => {
        setShipping((prev: Shipping) => {
            const newScheduling = { ...prev.scheduling, [key]: value };

            if (newScheduling.type === 'fixed') {
                newScheduling.time = newScheduling.startTime || '';
            } else {
                newScheduling.time = `${newScheduling.startTime || ''} às ${newScheduling.endTime || ''}`;
            }

            return {
                ...prev,
                scheduling: newScheduling as Shipping["scheduling"],
            };
        });
    };

    const handleCepBlur = async (e: React.FocusEvent<HTMLInputElement>) => {
        const cepValue = e.target.value.replace(/\D/g, "");
        if (cepValue.length === 8) {
            try {
                const data = await getAddressByCep(cepValue);
                if (data && !(data as any).error) {
                    setShipping(prev => ({
                        ...prev,
                        deliveryAddress: {
                            ...prev.deliveryAddress!,
                            street: data.street || prev.deliveryAddress?.street || "",
                            neighborhood: data.neighborhood || prev.deliveryAddress?.neighborhood || "",
                            city: data.city || prev.deliveryAddress?.city || "",
                            state: (data.state || prev.deliveryAddress?.state || "PR").toUpperCase(),
                        }
                    }));
                }
            } catch (error) {
                console.error("Erro ao buscar CEP", error);
            }
        }
    };

    const updateDeliveryAddress = (field: keyof NonNullable<Shipping['deliveryAddress']>, value: string) => {
        setShipping(prev => ({
            ...prev,
            deliveryAddress: {
                ...prev.deliveryAddress!,
                [field]: value
            }
        }));
    };

    return (
        <div className="flex flex-col gap-8 w-full">
            <div className="flex flex-col gap-10 w-full lg:gap-12">
                <div className="flex flex-col gap-10">
                        {/* Address status toggle */}
                        <div className="flex flex-col gap-4">
                            <div className="flex items-center justify-between">
                                <h4 className="text-xs font-black uppercase tracking-widest text-slate-400">
                                    {shipping.deliveryMethod === 'pickup' ? 'Local de Retirada / Endereço' : 'Endereço de Entrega'}
                                </h4>
                                <div className="flex items-center gap-3">
                                <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
                                    Endereço pendente?
                                </span>
                                <button
                                    type="button"
                                    role="switch"
                                    aria-checked={shipping.noAddress}
                                    aria-label="Marcar endereço como pendente"
                                    onClick={() => setShipping(prev => ({ ...prev, noAddress: !prev.noAddress }))}
                                    className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full border transition-colors focus:outline-none focus:ring-2 focus:ring-amber-400 focus:ring-offset-2 dark:focus:ring-offset-slate-900 ${
                                        shipping.noAddress
                                            ? 'border-amber-500 bg-amber-500'
                                            : 'border-slate-300 bg-slate-200 hover:bg-slate-300 dark:border-slate-600 dark:bg-slate-700 dark:hover:bg-slate-600'
                                    }`}
                                >
                                    <span className={`inline-block h-4 w-4 transform rounded-full bg-white shadow-sm transition-transform ${shipping.noAddress ? 'translate-x-6' : 'translate-x-1'}`} />
                                </button>
                                <span className={`text-[9px] font-black uppercase tracking-widest ${shipping.noAddress ? 'text-amber-600 dark:text-amber-400' : 'text-slate-400'}`}>
                                    {shipping.noAddress ? 'Sim' : 'Não'}
                                </span>
                                </div>
                            </div>
                            
                            {shipping.noAddress && (
                                <div className="bg-amber-50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/30 rounded-2xl p-4 animate-fade-in">
                                    <p className="text-[11px] font-bold text-amber-700 dark:text-amber-400 leading-relaxed flex items-center gap-2">
                                        <i className="bi bi-info-circle-fill"></i>
                                        O endereço de entrega foi marcado como não informado. O sistema permitirá prosseguir sem preencher os campos de rua e número.
                                    </p>
                                </div>
                            )}
                        </div>

                        {!shipping.noAddress && (
                            <div className="flex flex-col gap-10 animate-slide-up">
                        {/* Custom Delivery Address Toggle */}
                        {orderType !== 'budget' && (
                            <label className="flex w-fit cursor-pointer items-center gap-3 group">
                                <div className="relative flex items-center">
                                    <input
                                        type="checkbox"
                                        className="sr-only peer"
                                        checked={shipping.useCustomerAddress !== false}
                                        onChange={(e) => setShipping(prev => ({ ...prev, useCustomerAddress: e.target.checked }))}
                                    />
                                    <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer dark:bg-slate-700 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all dark:border-slate-600 peer-checked:bg-blue-600"></div>
                                </div>
                                <span className="text-sm font-bold text-slate-700 transition-colors group-hover:text-blue-600 dark:text-slate-300 dark:group-hover:text-blue-400">
                                    Usar o mesmo endereço do cliente?
                                </span>
                            </label>
                        )}

                        {orderType !== 'budget' && shipping.useCustomerAddress === false && (
                            <div className="mt-0 flex flex-col gap-4 animate-slide-up">
                                <h4 className="text-xs font-black uppercase tracking-widest text-slate-400 mb-2">
                                    Endereço de Entrega Alternativo
                                </h4>

                                <div className="flex flex-col md:flex-row gap-4">
                                    <div className="flex-[1]">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1 ml-1 block">CEP</label>
                                        <PatternFormat
                                            format="#####-###"
                                            className="w-full border-b-2 border-slate-200 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors focus:border-blue-600 dark:border-slate-800 dark:text-slate-300 dark:focus:border-blue-500"
                                            placeholder="00000-000"
                                            value={shipping.deliveryAddress?.cep || ""}
                                            onChange={(e: React.ChangeEvent<HTMLInputElement>) => updateDeliveryAddress('cep', e.target.value)}
                                            onBlur={handleCepBlur}
                                        />
                                    </div>
                                    <AddressAutocompleteInput
                                        value={shipping.deliveryAddress?.street || ""}
                                        onChange={val => updateDeliveryAddress('street', val)}
                                        onSelectAddress={data => {
                                            setShipping(prev => ({
                                                ...prev,
                                                deliveryAddress: {
                                                    ...prev.deliveryAddress!,
                                                    street: data.street,
                                                    neighborhood: data.neighborhood || prev.deliveryAddress?.neighborhood || "",
                                                    city: data.city || prev.deliveryAddress?.city || "",
                                                    state: data.state || prev.deliveryAddress?.state || "PR",
                                                    cep: data.cep || prev.deliveryAddress?.cep || "",
                                                    number: data.number || prev.deliveryAddress?.number || "",
                                                    mapsUrl: prev.deliveryAddress?.mapsUrl || ""
                                                }
                                            }));
                                        }}
                                        cityHint={shipping.deliveryAddress?.city}
                                        stateHint={shipping.deliveryAddress?.state || "PR"}
                                        variant="underline"
                                        hasError={!!errors['deliveryAddress_street']}
                                        label="Rua/Avenida"
                                        placeholder="Nome da rua"
                                        required
                                        className="flex-[3] relative group/field"
                                    />
                                    <div className="flex-[1] relative group/field">
                                        <label className={`text-[10px] font-black uppercase tracking-widest mb-1 ml-1 block ${errors['deliveryAddress_number'] ? 'text-red-600 dark:text-red-400' : 'text-slate-400'}`}>Número <span className="text-red-500">*</span></label>
                                        <input
                                            type="text"
                                            className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors dark:text-slate-300 ${errors['deliveryAddress_number'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-500'}`}
                                            placeholder="Ex: 123"
                                            value={shipping.deliveryAddress?.number || ""}
                                            onChange={e => updateDeliveryAddress('number', e.target.value)}
                                        />
                                    </div>
                                </div>

                                <div className="flex flex-col md:flex-row gap-4">
                                    <div className="flex-1">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1 ml-1 block">Complemento</label>
                                        <input
                                            type="text"
                                            className="w-full border-b-2 border-slate-200 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors focus:border-blue-600 dark:border-slate-800 dark:text-slate-300 dark:focus:border-blue-500"
                                            placeholder="Apto, Bloco, etc"
                                            value={shipping.deliveryAddress?.complement || ""}
                                            onChange={e => updateDeliveryAddress('complement', e.target.value)}
                                        />
                                    </div>
                                    <div className="flex-1 relative group/field">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1 ml-1 block">Bairro</label>
                                        <input
                                            type="text"
                                            className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors dark:text-slate-300 ${errors['deliveryAddress_neighborhood'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-500'}`}
                                            placeholder="Seu bairro"
                                            value={shipping.deliveryAddress?.neighborhood || ""}
                                            onChange={e => updateDeliveryAddress('neighborhood', e.target.value)}
                                        />
                                    </div>
                                    <div className="flex-[1.5] relative group/field">
                                        <label className={`text-[10px] font-black uppercase tracking-widest mb-1 ml-1 block ${errors['deliveryAddress_city'] ? 'text-red-600 dark:text-red-400' : 'text-slate-400'}`}>Cidade <span className="text-red-500">*</span></label>
                                        <input
                                            type="text"
                                            className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors dark:text-slate-300 ${errors['deliveryAddress_city'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-500'}`}
                                            placeholder="Nome da cidade"
                                            value={shipping.deliveryAddress?.city || ""}
                                            onChange={e => updateDeliveryAddress('city', e.target.value)}
                                        />
                                    </div>
                                    <div className="flex-[0.6] relative group/field">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1 ml-1 block">UF</label>
                                        <input
                                            type="text"
                                            maxLength={2}
                                            className="w-full border-b-2 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors dark:text-slate-300 border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-500 text-center"
                                            placeholder="PR"
                                            value={shipping.deliveryAddress?.state || "PR"}
                                            onChange={e => updateDeliveryAddress('state', e.target.value.toUpperCase())}
                                        />
                                    </div>
                                </div>

                                <div className="flex flex-col md:flex-row gap-4">
                                    <div className="flex-1 relative group/field">
                                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1 ml-1 block">Tipo de Moradia</label>
                                        <select
                                            className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors dark:text-slate-300 ${errors['deliveryAddress_housingType'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 dark:border-slate-800 focus:border-blue-600 dark:focus:border-blue-500'}`}
                                            value={shipping.deliveryAddress?.housingType || ""}
                                            onChange={e => updateDeliveryAddress('housingType', e.target.value)}
                                        >
                                            <option value="" disabled>Selecione o tipo...</option>
                                            <option value="Casa">Casa</option>
                                            <option value="Apartamento">Apartamento</option>
                                            <option value="Condomínio Residencial">Condomínio Residencial</option>
                                            <option value="Kitnet">Kitnet</option>
                                            <option value="Estabelecimento Comercial">Estabelecimento Comercial</option>
                                            <option value="Chácara">Chácara</option>
                                        </select>
                                    </div>
                                    <div className="flex-[2]">
                                        <SmartInput
                                            label="Ponto de Referência / Observação de Entrega"
                                            value={shipping.deliveryAddress?.observation || ""}
                                            onValueChange={val => updateDeliveryAddress('observation', val)}
                                            tableName="orders"
                                            columnName="observation"
                                            placeholder="Ex: Casa verde em frente a padaria..."
                                            icon="bi-geo-alt"
                                            className="bg-amber-50 dark:bg-amber-900/10 border-amber-200 dark:border-amber-900/30"
                                        />
                                    </div>
                                </div>

                                <div className="flex flex-col md:flex-row gap-4 mt-2">
                                    <div className="flex-1 relative group/field">
                                        <div className="flex items-center justify-between mb-1 ml-1">
                                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-1">
                                                <i className="bi bi-geo-alt-fill text-red-500" />
                                                Link / URL do Google Maps (Localização Exata)
                                            </label>
                                            {shipping.deliveryAddress?.mapsUrl && (
                                                <a
                                                    href={shipping.deliveryAddress.mapsUrl}
                                                    target="_blank"
                                                    rel="noreferrer"
                                                    className="text-[9px] font-black uppercase text-blue-600 dark:text-blue-400 hover:underline flex items-center gap-1"
                                                >
                                                    <i className="bi bi-box-arrow-up-right" /> Testar Link
                                                </a>
                                            )}
                                        </div>
                                        <input
                                            type="url"
                                            className="w-full border-b-2 border-slate-200 bg-transparent px-3 py-2 text-sm font-bold text-slate-700 outline-none transition-colors focus:border-blue-600 dark:border-slate-800 dark:text-slate-300 dark:focus:border-blue-500 placeholder:font-normal"
                                            placeholder="https://maps.app.goo.gl/... ou link copiado do Google Maps"
                                            value={shipping.deliveryAddress?.mapsUrl || ""}
                                            onChange={e => updateDeliveryAddress('mapsUrl', e.target.value)}
                                        />
                                    </div>
                                </div>

                                {/* Address Verification Map for custom address */}
                                <div className="mt-2 animate-fade-in">
                                    <AddressVerificationMap 
                                        address={{
                                            street: shipping.deliveryAddress?.street || "",
                                            number: shipping.deliveryAddress?.number || "",
                                            neighborhood: shipping.deliveryAddress?.neighborhood || "",
                                            city: shipping.deliveryAddress?.city || ""
                                        }}
                                    />
                                </div>
                            </div>
                        )}
                        
                        <FreteDistancia
                            value={shipping.value}
                            distance={shipping.distance}
                            routeUrl={route}
                            onChangeValue={onChangeShippingValue}
                            onChangeDistance={onChangeDistance}
                            onAutoCalculateDistance={onAutoCalculateDistance}
                            isCalculatingDistance={isCalculatingDistance}
                            errors={errors}
                        />
                            </div>
                        )}
                    </div>
                {orderType !== 'budget' && (
                    <Agendamento
                        scheduling={shipping.scheduling}
                        onChangeScheduling={onChangeScheduling}
                        errors={errors}
                        isPickup={shipping.deliveryMethod === 'pickup'}
                    />
                )}
            </div>

            {shipping.destinationCoords && shipping.deliveryMethod !== 'pickup' && (
                <div className="w-full flex flex-col gap-2 relative group -mt-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500 ml-1">Rota de Entrega</label>
                    <MapRoute
                        destinationCoords={shipping.destinationCoords as [number, number]}
                        routeGeoJSON={shipping.routeGeoJSON}
                        className="h-80 w-full animate-slide-up"
                    />
                </div>
            )}
        </div>
    );
};

export default ShippingData;

import React, { useState, useEffect, useRef } from "react";
import { toast } from "react-toastify";
import { aiService } from "@/pages/utils/aiService";

interface SmartAIFillModalProps {
    isOpen: boolean;
    onClose: () => void;
    onApplyData: (data: any) => void;
    onStartLiveMode?: () => void;
    sellerList?: string[];
}

export const SmartAIFillModal: React.FC<SmartAIFillModalProps> = ({
    isOpen,
    onClose,
    onApplyData,
    onStartLiveMode,
    sellerList = []
}) => {
    const [promptText, setPromptText] = useState("");
    const [isListening, setIsListening] = useState(false);
    const [isProcessingAI, setIsProcessingAI] = useState(false);
    const [lastParsedResult, setLastParsedResult] = useState<any>(null);
    const [activeTab, setActiveTab] = useState<'ai' | 'json_manual'>('ai');
    const [manualJSON, setManualJSON] = useState("");
    const [liveTranscript, setLiveTranscript] = useState("");

    const recognitionRef = useRef<any>(null);

    // Inicialização da Web Speech API para Transcrição de Áudio ao Vivo
    useEffect(() => {
        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (SpeechRecognition) {
            const recognition = new SpeechRecognition();
            recognition.continuous = true;
            recognition.interimResults = true;
            recognition.lang = 'pt-BR';

            recognition.onresult = (event: any) => {
                let currentInterim = '';
                let currentFinal = '';

                for (let i = event.resultIndex; i < event.results.length; i++) {
                    const transcript = event.results[i][0].transcript;
                    if (event.results[i].isFinal) {
                        currentFinal += transcript + ' ';
                    } else {
                        currentInterim += transcript;
                    }
                }

                if (currentFinal) {
                    setPromptText(prev => {
                        const spacer = prev && !prev.endsWith(' ') ? ' ' : '';
                        return prev + spacer + currentFinal;
                    });
                }
                setLiveTranscript(currentInterim);
            };

            recognition.onerror = (event: any) => {
                console.warn("Speech recognition error:", event.error);
                if (event.error !== 'no-speech') {
                    setIsListening(false);
                    toast.warn(`Microfone: ${event.error === 'not-allowed' ? 'Permissão de microfone negada no navegador' : event.error}`);
                }
            };

            recognition.onend = () => {
                setIsListening(false);
                setLiveTranscript("");
            };

            recognitionRef.current = recognition;
        }

        return () => {
            if (recognitionRef.current) {
                try {
                    recognitionRef.current.stop();
                } catch {
                    // ignore
                }
            }
        };
    }, []);

    const toggleListening = () => {
        if (!recognitionRef.current) {
            toast.warn("Seu navegador não suporta reconhecimento de voz nativo. Use o Google Chrome ou digite/cole o texto no campo.");
            return;
        }

        if (isListening) {
            recognitionRef.current.stop();
            setIsListening(false);
            setLiveTranscript("");
            toast.info("Gravação de áudio pausada.");
        } else {
            try {
                recognitionRef.current.start();
                setIsListening(true);
                toast.success("Ouvindo! Pode ditar os dados do pedido...");
            } catch (err: any) {
                console.error("Erro ao iniciar reconhecimento:", err);
                setIsListening(false);
            }
        }
    };

    const handleGenerateAI = async () => {
        const fullText = (promptText + (liveTranscript ? ` ${liveTranscript}` : "")).trim();
        if (!fullText) {
            toast.warn("Por favor, fale no microfone ou digite o texto do pedido para a IA analisar.");
            return;
        }

        if (isListening && recognitionRef.current) {
            try {
                recognitionRef.current.stop();
                setIsListening(false);
            } catch {}
        }

        setIsProcessingAI(true);
        try {
            const result = await aiService.parseOrderFromFreeText(fullText, sellerList);
            setLastParsedResult(result);
            toast.success("Pedido analisado com sucesso pela IA Gemini!");
        } catch (err: any) {
            console.error("Erro ao processar pedido com IA:", err);
            toast.error(err.message || "Falha ao analisar o pedido com a IA Gemini.");
        } finally {
            setIsProcessingAI(false);
        }
    };

    const handleConfirmApply = () => {
        if (!lastParsedResult?.rawJSON) {
            toast.warn("Gere ou processe o pedido com a IA antes de aplicar.");
            return;
        }
        onApplyData(lastParsedResult.rawJSON);
        onClose();
    };

    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const parsed = JSON.parse(event.target?.result as string);
                onApplyData(parsed);
                onClose();
            } catch (err: any) {
                toast.error("Arquivo JSON inválido: " + err.message);
            }
        };
        reader.readAsText(file);
    };

    const handleProcessManualJSON = () => {
        try {
            const parsed = JSON.parse(manualJSON);
            onApplyData(parsed);
            onClose();
        } catch (err: any) {
            toast.error("JSON inválido: " + err.message);
        }
    };

    if (!isOpen) return null;

    const identified = lastParsedResult?.identifiedFields || {};
    const warnings = lastParsedResult?.warnings || [];
    const missing = lastParsedResult?.missingRequiredFields || [];

    return (
        <div 
            className="fixed inset-0 z-[200] flex items-center justify-center p-3 sm:p-4 bg-slate-950/70 backdrop-blur-md animate-fade-in"
            onClick={onClose}
        >
            <div 
                className="bg-white dark:bg-slate-900 w-full max-w-3xl rounded-3xl shadow-2xl flex flex-col overflow-hidden border border-slate-200 dark:border-slate-800 max-h-[90vh] animate-slide-up"
                onClick={(e) => e.stopPropagation()}
            >
                {/* Header com Gradiente de IA e Estrelas */}
                <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-gradient-to-r from-violet-600/10 via-blue-600/10 to-transparent dark:from-violet-950/40 dark:via-blue-950/30">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-violet-600 via-indigo-600 to-blue-500 flex items-center justify-center text-white shadow-lg shadow-violet-500/25">
                            <i className="bi bi-stars text-lg animate-pulse" />
                        </div>
                        <div>
                            <div className="flex items-center gap-2">
                                <h3 className="text-base font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                    Preenchimento Inteligente IA
                                </h3>
                                <span className="px-2 py-0.5 rounded-full bg-gradient-to-r from-violet-600 to-blue-600 text-[9px] font-black uppercase text-white tracking-widest shadow-sm">
                                    Gemini 2.5
                                </span>
                            </div>
                            <p className="text-[11px] font-semibold text-slate-400 dark:text-slate-500">
                                Fale ao vivo ou digite os dados e a IA estrutura o pedido instantaneamente
                            </p>
                        </div>
                    </div>

                    <div className="flex items-center gap-2">
                        <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700">
                            <button
                                type="button"
                                onClick={() => setActiveTab('ai')}
                                className={`flex items-center gap-1.5 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all ${
                                    activeTab === 'ai'
                                    ? 'bg-gradient-to-r from-violet-600 to-blue-600 text-white shadow-sm'
                                    : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-200'
                                }`}
                            >
                                <i className="bi bi-stars text-xs" /> IA & Voz
                            </button>
                            <button
                                type="button"
                                onClick={() => setActiveTab('json_manual')}
                                className={`flex items-center gap-1.5 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all ${
                                    activeTab === 'json_manual'
                                    ? 'bg-white dark:bg-slate-700 text-slate-800 dark:text-slate-100 shadow-sm'
                                    : 'text-slate-500 hover:text-slate-800 dark:hover:text-slate-200'
                                }`}
                            >
                                <i className="bi bi-filetype-json text-xs" /> JSON
                            </button>
                        </div>

                        <button 
                            type="button"
                            onClick={onClose}
                            className="w-8 h-8 flex items-center justify-center hover:bg-rose-50 dark:hover:bg-rose-950/30 text-slate-400 hover:text-rose-500 rounded-xl transition-all"
                        >
                            <i className="bi bi-x-lg text-sm" />
                        </button>
                    </div>
                </div>

                {/* Conteúdo Principal */}
                <div className="p-6 overflow-y-auto flex-1 custom-scrollbar flex flex-col gap-5">
                    {activeTab === 'ai' ? (
                        <>
                            {/* Botão Principal: Live de Áudio ao Vivo */}
                            <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-4 rounded-2xl bg-gradient-to-r from-violet-500/10 via-blue-500/10 to-indigo-500/10 dark:from-violet-950/30 dark:via-blue-950/20 dark:to-indigo-950/30 border border-violet-200/60 dark:border-violet-800/40">
                                <div className="flex items-center gap-3">
                                    <div className={`relative flex items-center justify-center w-12 h-12 rounded-2xl transition-all ${
                                        isListening 
                                        ? 'bg-rose-600 text-white shadow-lg shadow-rose-500/40 animate-pulse' 
                                        : 'bg-gradient-to-tr from-violet-600 to-blue-600 text-white shadow-md shadow-blue-500/20'
                                    }`}>
                                        <i className={`bi ${isListening ? 'bi-mic-fill' : 'bi-mic'} text-xl`} />
                                        {isListening && (
                                            <span className="absolute -top-1 -right-1 flex h-3 w-3">
                                                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-rose-400 opacity-75"></span>
                                                <span className="relative inline-flex rounded-full h-3 w-3 bg-rose-500"></span>
                                            </span>
                                        )}
                                    </div>
                                    <div>
                                        <h4 className="text-xs font-black uppercase tracking-wider text-slate-800 dark:text-slate-100 flex items-center gap-2">
                                            {isListening ? "Gravando Áudio ao Vivo..." : "Falar ao Vivo com a IA"}
                                            {isListening && (
                                                <span className="px-2 py-0.5 rounded-md bg-rose-100 dark:bg-rose-950/50 text-rose-600 dark:text-rose-400 text-[9px] font-black animate-pulse">
                                                    LIVE
                                                </span>
                                            )}
                                        </h4>
                                        <p className="text-[11px] font-medium text-slate-500 dark:text-slate-400">
                                            {isListening 
                                                ? "Fale normalmente: cliente, endereço, produtos, valores e forma de pagamento." 
                                                : "Clique no botão ao lado para ditar o pedido por voz em tempo real."}
                                        </p>
                                    </div>
                                </div>

                                <button
                                    type="button"
                                    onClick={toggleListening}
                                    className={`px-5 py-2.5 rounded-xl font-black text-xs uppercase tracking-wider transition-all flex items-center justify-center gap-2 shrink-0 ${
                                        isListening
                                        ? 'bg-rose-600 hover:bg-rose-700 text-white shadow-lg shadow-rose-600/30 scale-105'
                                        : 'bg-gradient-to-r from-violet-600 via-indigo-600 to-blue-600 hover:opacity-95 text-white shadow-lg shadow-violet-600/25 hover:scale-105 active:scale-95'
                                    }`}
                                >
                                    <i className={`bi ${isListening ? 'bi-stop-fill' : 'bi-broadcast'} text-sm`} />
                                    {isListening ? 'Parar Escuta' : 'Iniciar Live de Voz'}
                                </button>
                            </div>

                            {/* Campo de Texto Livre com Transcrição ao Vivo */}
                            <div className="flex flex-col gap-2">
                                <div className="flex justify-between items-center">
                                    <label className="text-[11px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-300 flex items-center gap-2">
                                        <i className="bi bi-chat-left-text text-violet-500" /> Texto / Anotações do Pedido:
                                    </label>
                                    {promptText && (
                                        <button
                                            type="button"
                                            onClick={() => {
                                                setPromptText("");
                                                setLiveTranscript("");
                                            }}
                                            className="text-[10px] font-bold text-slate-400 hover:text-rose-500 transition-colors"
                                        >
                                            Limpar Texto
                                        </button>
                                    )}
                                </div>

                                <div className="relative">
                                    <textarea
                                        value={promptText + (liveTranscript ? ` ${liveTranscript}` : "")}
                                        onChange={(e) => setPromptText(e.target.value)}
                                        placeholder="Exemplo: O cliente é Angelina da Silva, telefone (11) 98765-4321, mora na Rua das Flores 123, comprou um Sofá Retrátil 3 Lugares por 2500 reais e uma Mesa de Jantar com 4 Cadeiras por 1200 reais. Entrega agendada para sábado de manhã com montagem no local, pagamento 50% no Pix e o restante no cartão..."
                                        rows={5}
                                        className="w-full p-4 text-xs font-medium bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-violet-500 focus:border-transparent outline-none custom-scrollbar text-slate-800 dark:text-slate-100 placeholder-slate-400 resize-none transition-all"
                                    />
                                    {isListening && (
                                        <div className="absolute bottom-3 right-3 flex items-center gap-1.5 px-3 py-1 bg-rose-50 dark:bg-rose-950/60 border border-rose-200 dark:border-rose-800/80 rounded-full">
                                            <span className="w-2 h-2 rounded-full bg-rose-500 animate-ping" />
                                            <span className="text-[9px] font-black uppercase tracking-widest text-rose-600 dark:text-rose-400">
                                                Transcrevendo ao vivo...
                                            </span>
                                        </div>
                                    )}
                                </div>

                                <div className="flex flex-wrap items-center justify-between gap-3 pt-1">
                                    <p className="text-[10px] text-slate-400 dark:text-slate-500 font-medium">
                                        💡 Você pode alterar o texto a qualquer momento e clicar em Gerar novamente.
                                    </p>
                                    <button
                                        type="button"
                                        onClick={handleGenerateAI}
                                        disabled={isProcessingAI}
                                        className="px-6 py-2.5 bg-gradient-to-r from-violet-600 via-indigo-600 to-blue-600 hover:from-violet-700 hover:to-blue-700 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-violet-500/20 flex items-center gap-2 transition-all active:scale-95 disabled:opacity-50"
                                    >
                                        {isProcessingAI ? (
                                            <>
                                                <i className="bi bi-arrow-repeat animate-spin text-sm" />
                                                Processando com IA...
                                            </>
                                        ) : (
                                            <>
                                                <i className="bi bi-stars text-sm" />
                                                {lastParsedResult ? 'Gerar / Atualizar Novamente' : 'Gerar Pedido com IA'}
                                            </>
                                        )}
                                    </button>
                                </div>
                            </div>

                            {/* Área de Validação e Feedback da IA (Campos Identificados e Avisos de Campos Faltantes) */}
                            {lastParsedResult && (
                                <div className="flex flex-col gap-4 p-5 rounded-2xl bg-slate-50 dark:bg-slate-950/80 border border-slate-200 dark:border-slate-800 animate-fade-in">
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-2">
                                            <div className="w-2 h-2 rounded-full bg-emerald-500" />
                                            <h4 className="text-xs font-black uppercase tracking-widest text-slate-700 dark:text-slate-200">
                                                Resultado da Análise da IA
                                            </h4>
                                        </div>
                                        <span className="text-[10px] font-bold text-slate-400">
                                            {lastParsedResult.summary}
                                        </span>
                                    </div>

                                    {/* Grid de Dados Identificados */}
                                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
                                        <div className="p-3 rounded-xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800">
                                            <span className="text-[9px] font-black uppercase tracking-wider text-slate-400">Cliente</span>
                                            <p className="text-xs font-bold text-slate-800 dark:text-slate-100 truncate mt-0.5">
                                                {identified.clientName || 'Não identificado'}
                                            </p>
                                        </div>
                                        <div className="p-3 rounded-xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800">
                                            <span className="text-[9px] font-black uppercase tracking-wider text-slate-400">Telefone</span>
                                            <p className="text-xs font-bold text-slate-800 dark:text-slate-100 truncate mt-0.5">
                                                {identified.clientPhone || 'Não informado'}
                                            </p>
                                        </div>
                                        <div className="p-3 rounded-xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800">
                                            <span className="text-[9px] font-black uppercase tracking-wider text-slate-400">Produtos</span>
                                            <p className="text-xs font-bold text-blue-600 dark:text-blue-400 mt-0.5">
                                                {identified.itemsCount ? `${identified.itemsCount} item(ns)` : '0 itens'}
                                            </p>
                                        </div>
                                        <div className="p-3 rounded-xl bg-white dark:bg-slate-900 border border-slate-200/80 dark:border-slate-800">
                                            <span className="text-[9px] font-black uppercase tracking-wider text-slate-400">Valor Total</span>
                                            <p className="text-xs font-black text-emerald-600 dark:text-emerald-400 mt-0.5">
                                                {identified.totalAmount 
                                                    ? Number(identified.totalAmount).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
                                                    : 'R$ 0,00'}
                                            </p>
                                        </div>
                                    </div>

                                    {/* ÁREA DE AVISOS E CAMPOS OBRIGATÓRIOS FALTANTES (DESTAQUE) */}
                                    {(missing.length > 0 || warnings.length > 0) && (
                                        <div className="flex flex-col gap-2 p-4 rounded-xl bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-900/50">
                                            <div className="flex items-center gap-2 text-amber-700 dark:text-amber-400">
                                                <i className="bi bi-exclamation-triangle-fill text-sm" />
                                                <span className="text-[11px] font-black uppercase tracking-wider">
                                                    Avisos e Campos Importantes Faltantes:
                                                </span>
                                            </div>
                                            <div className="flex flex-wrap gap-2 pt-1">
                                                {missing.map((m: string, idx: number) => (
                                                    <div 
                                                        key={`missing-${idx}`}
                                                        className="px-2.5 py-1 rounded-lg bg-amber-100/80 dark:bg-amber-900/40 border border-amber-300 dark:border-amber-700/60 text-[10px] font-bold text-amber-800 dark:text-amber-200 flex items-center gap-1.5"
                                                    >
                                                        <i className="bi bi-x-circle-fill text-amber-600 dark:text-amber-400 text-[10px]" />
                                                        {m}
                                                    </div>
                                                ))}
                                                {warnings.map((w: string, idx: number) => (
                                                    <div 
                                                        key={`warn-${idx}`}
                                                        className="px-2.5 py-1 rounded-lg bg-blue-100/60 dark:bg-blue-900/30 border border-blue-200 dark:border-blue-800 text-[10px] font-semibold text-blue-800 dark:text-blue-200 flex items-center gap-1.5"
                                                    >
                                                        <i className="bi bi-info-circle-fill text-blue-500 text-[10px]" />
                                                        {w}
                                                    </div>
                                                ))}
                                            </div>
                                            <p className="text-[10px] text-amber-700/80 dark:text-amber-400/80 mt-1">
                                                Você pode complementar as informações no texto acima e clicar em "Gerar / Atualizar Novamente" ou aplicar e preencher manualmente no formulário.
                                            </p>
                                        </div>
                                    )}

                                    {/* Botão de Aplicação no Pedido */}
                                    <div className="flex justify-end pt-2">
                                        <button
                                            type="button"
                                            onClick={handleConfirmApply}
                                            className="px-6 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-emerald-600/20 flex items-center gap-2 transition-all active:scale-95"
                                        >
                                            <i className="bi bi-check2-circle text-base" />
                                            Injetar e Preencher no Pedido
                                        </button>
                                    </div>
                                </div>
                            )}
                        </>
                    ) : (
                        /* Aba de Importação Manual JSON */
                        <div className="flex flex-col gap-4 animate-fade-in">
                            <p className="text-xs font-medium text-slate-500 dark:text-slate-400">
                                Carregue um arquivo JSON gerado anteriormente ou cole a estrutura JSON diretamente abaixo.
                            </p>

                            <div className="flex items-center gap-3">
                                <label className="flex items-center gap-2 px-4 py-2.5 bg-blue-50 hover:bg-blue-100 dark:bg-blue-900/20 dark:hover:bg-blue-900/30 border border-blue-200 dark:border-blue-800 rounded-xl text-[10px] font-black uppercase tracking-widest text-blue-600 dark:text-blue-400 transition-all cursor-pointer shadow-sm">
                                    <i className="bi bi-cloud-upload-fill text-xs" /> Carregar Arquivo JSON
                                    <input
                                        type="file"
                                        accept=".json"
                                        onChange={handleFileUpload}
                                        className="hidden"
                                    />
                                </label>
                            </div>

                            <div className="flex flex-col gap-2">
                                <textarea
                                    value={manualJSON}
                                    onChange={(e) => setManualJSON(e.target.value)}
                                    placeholder="Cole aqui o JSON estruturado..."
                                    rows={8}
                                    className="w-full p-3.5 text-xs font-mono bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none custom-scrollbar text-slate-800 dark:text-slate-200"
                                />
                                <button
                                    type="button"
                                    onClick={handleProcessManualJSON}
                                    className="self-end px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-md transition-all active:scale-95"
                                >
                                    Processar e Preencher
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default SmartAIFillModal;

import React from 'react';
import Product, { Variation } from '../../../types/product.type';
import ProductAutocomplete from '../../../../components/ProductAutocomplete';
import Item from '../../../types/items.type';
import Service from '../../../types/service.type';
import { calcItemTotalValue } from '../../../utils/calculations';
import CurrencyOrPercentInput from '../../../../components/CurrencyOrPercentInput';
import UnitInput from './UnitInput';
import CurrencyInput from '../../../../components/CurrencyInput';
import CurrencyDisplay from '../../../../components/CurrencyDisplay';
import { ValidationErrors } from '../../../utils/validations';
import { getSettings } from '@/pages/utils/settingsService';
import ServiceAutocomplete from './ServiceAutocomplete';

interface Props {
    item: Item;
    productItems: Item[];
    onChange: (idx: number, key: keyof Item, value: string | number) => void;
    onBatchChange: (idx: number, changes: Partial<Item>) => void;
    onToggleDiscountType: () => void;
    onDelete: () => void;
    idx: number;
    deliveryMethod: 'delivery' | 'pickup';
    errors: ValidationErrors;
    isMobile?: boolean;
    onSelectProduct: (idx: number, product: Product, variation?: Variation) => void;
    isBudget?: boolean;
    isReturn?: boolean;
    hideHandling?: boolean;
    highlightAsTemporary?: boolean;
    isExpanded?: boolean;
    onToggleExpand?: () => void;
}

const BodyRow = ({
    item,
    productItems,
    onChange,
    onBatchChange,
    onDelete,
    idx,
    deliveryMethod,
    errors,
    isMobile,
    onSelectProduct,
    isBudget,
    isReturn,
    hideHandling,
    highlightAsTemporary,
    isExpanded = true,
    onToggleExpand
}: Props) => {
    const isService = item.itemType === 'service';
    const shouldHideHandling = Boolean(isService || hideHandling || isBudget || isReturn);
    const isLinkedProduct = Boolean(!isService && item.description?.trim() && item.productId);
    const isTemporaryProduct = Boolean(!isService && item.description?.trim() && !item.productId);
    const errorKey = `item_${idx}_description`;
    const error = errors[errorKey];
    const handlingErrorKey = `item_${idx}_handlingType`;
    const handlingError = !isService && errors[handlingErrorKey];
    const itemHasError = Boolean(error || handlingError);
    const settings = getSettings();
    const serviceProductLink = isService ? (
        <div className="mt-2">
            <label className="mb-1 ml-1 block text-[10px] font-black uppercase tracking-wider text-slate-400">Vincular ao produto</label>
            <select
                aria-label="Vincular ao produto"
                value={item.linkedProductOrderItemId || ''}
                onChange={event => onChange(idx, 'linkedProductOrderItemId', event.target.value)}
                className="w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs text-slate-700 outline-none focus:border-blue-500 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-200"
            >
                <option value="">Sem vínculo</option>
                {productItems.map((product, productIndex) => (
                    <option key={product.orderItemId || productIndex} value={product.orderItemId || ''} disabled={!product.orderItemId}>
                        {product.description || 'Produto sem descrição'} — {product.code || 'Sem SKU'} (linha {productIndex + 1})
                    </option>
                ))}
            </select>
        </div>
    ) : null;

    // Valores calculados com arredondamento preciso para evitar dízimas de ponto flutuante
    const discountInValue = item.discountType === "fixed" 
        ? item.unitDiscount 
        : Math.round(((item.unitPrice * item.unitDiscount) / 100) * 100) / 100;

    const discountInPercent = item.discountType === "percentage" 
        ? item.unitDiscount 
        : (item.unitPrice > 0 ? Math.round(((item.unitDiscount / item.unitPrice) * 100) * 100) / 100 : 0);

    const initialSubtotal = Math.round((item.unitPrice - discountInValue) * 100) / 100;

    // Estados locais temporários para digitação livre sem disparar recálculos prematuros
    const [tempUnitPrice, setTempUnitPrice] = React.useState(item.unitPrice || 0);
    const [tempDiscountValue, setTempDiscountValue] = React.useState(discountInValue);
    const [tempDiscountPercent, setTempDiscountPercent] = React.useState(discountInPercent);
    const [tempSubtotal, setTempSubtotal] = React.useState(initialSubtotal);
    const [tempObservation, setTempObservation] = React.useState(item.observation || '');

    // Sincronizar estados locais apenas quando os valores persistidos mudam externamente
    React.useEffect(() => {
        setTempUnitPrice(item.unitPrice || 0);
        setTempDiscountValue(discountInValue);
        setTempDiscountPercent(discountInPercent);
        setTempSubtotal(initialSubtotal);
        setTempObservation(item.observation || '');
    }, [item.unitPrice, discountInValue, discountInPercent, initialSubtotal, item.observation]);

    const commitObservation = () => {
        if ((item.observation || '') !== tempObservation) {
            onChange(idx, 'observation', tempObservation);
        }
    };

    const commitUnitPrice = () => {
        const newUnitPrice = Math.max(0, Math.round(tempUnitPrice * 100) / 100);
        if (item.discountType === 'percentage') {
            const percentVal = Math.min(100, Math.max(0, item.unitDiscount || 0));
            const calculatedDiscountVal = Math.round(((newUnitPrice * percentVal) / 100) * 100) / 100;
            const calculatedSubtotal = Math.max(0, Math.round((newUnitPrice - calculatedDiscountVal) * 100) / 100);
            setTempUnitPrice(newUnitPrice);
            setTempDiscountValue(calculatedDiscountVal);
            setTempSubtotal(calculatedSubtotal);
            onBatchChange(idx, { unitPrice: newUnitPrice });
        } else {
            const discountVal = item.unitDiscount || 0;
            const effectiveDiscount = Math.min(discountVal, newUnitPrice);
            const calculatedPercent = newUnitPrice > 0 ? Math.min(100, Math.round(((effectiveDiscount / newUnitPrice) * 100) * 100) / 100) : 0;
            const calculatedSubtotal = Math.max(0, Math.round((newUnitPrice - effectiveDiscount) * 100) / 100);
            setTempUnitPrice(newUnitPrice);
            setTempDiscountPercent(calculatedPercent);
            setTempSubtotal(calculatedSubtotal);
            onBatchChange(idx, { unitPrice: newUnitPrice });
        }
    };

    const commitDiscountPercent = () => {
        const percentVal = Math.min(100, Math.max(0, Math.round(tempDiscountPercent * 100) / 100));
        const currentUnitPrice = item.unitPrice || 0;
        const calculatedDiscountVal = Math.min(currentUnitPrice, Math.round(((currentUnitPrice * percentVal) / 100) * 100) / 100);
        const calculatedSubtotal = Math.max(0, Math.round((currentUnitPrice - calculatedDiscountVal) * 100) / 100);

        setTempDiscountPercent(percentVal);
        setTempDiscountValue(calculatedDiscountVal);
        setTempSubtotal(calculatedSubtotal);

        onBatchChange(idx, { 
            discountType: 'percentage', 
            unitDiscount: percentVal 
        });
    };

    const commitDiscountValue = () => {
        const currentUnitPrice = item.unitPrice || 0;
        const val = Math.max(0, Math.round(tempDiscountValue * 100) / 100);
        const effectiveDiscount = Math.min(val, currentUnitPrice);
        const calculatedPercent = currentUnitPrice > 0 
            ? Math.min(100, Math.round(((effectiveDiscount / currentUnitPrice) * 100) * 100) / 100) 
            : 0;
        const calculatedSubtotal = Math.max(0, Math.round((currentUnitPrice - effectiveDiscount) * 100) / 100);

        setTempDiscountValue(effectiveDiscount);
        setTempDiscountPercent(calculatedPercent);
        setTempSubtotal(calculatedSubtotal);

        onBatchChange(idx, { 
            discountType: 'fixed', 
            unitDiscount: effectiveDiscount 
        });
    };

    const commitSubtotal = () => {
        const currentUnitPrice = item.unitPrice || 0;
        const val = Math.min(currentUnitPrice, Math.max(0, Math.round(tempSubtotal * 100) / 100));
        if (val >= currentUnitPrice) {
            setTempSubtotal(currentUnitPrice);
            setTempDiscountValue(0);
            setTempDiscountPercent(0);
            onBatchChange(idx, {
                discountType: 'fixed',
                unitDiscount: 0
            });
        } else {
            const newDiscount = Math.round((currentUnitPrice - val) * 100) / 100;
            const newPercent = currentUnitPrice > 0 ? Math.min(100, Math.round(((newDiscount / currentUnitPrice) * 100) * 100) / 100) : 0;
            setTempSubtotal(val);
            setTempDiscountValue(newDiscount);
            setTempDiscountPercent(newPercent);
            onBatchChange(idx, {
                discountType: 'fixed',
                unitDiscount: newDiscount
            });
        }
    };

    const handleSelectService = (service: Service) => {
        onBatchChange(idx, {
            description: service.description,
            unitPrice: service.unitPrice || 0,
            costPrice: service.costPrice || 0,
            itemType: 'service'
        });
    };

    // VISUALIZAÇÃO EM CARD (isMobile / width < 1280px)
    if (isMobile) {
        // MODO COMPACTO
        if (!isExpanded) {
            return (
                <div
                    onClick={onToggleExpand}
                    className={`px-3.5 py-2.5 bg-white dark:bg-slate-900 border rounded-2xl ${
                        highlightAsTemporary 
                            ? 'border-amber-400 dark:border-amber-500 ring-2 ring-amber-400/20 bg-amber-50/10 dark:bg-amber-950/10' 
                            : itemHasError
                            ? 'border-red-500 ring-2 ring-red-500/10' 
                            : 'border-slate-200/80 dark:border-slate-800'
                    } shadow-sm hover:shadow-md transition-all cursor-pointer flex items-center justify-between gap-3 group`}
                >
                    <div className="flex items-center gap-2.5 min-w-0 flex-1">
                        <div className={`w-7 h-7 rounded-xl flex items-center justify-center shrink-0 text-xs ${
                            isService
                                ? 'bg-amber-50 dark:bg-amber-950/40 text-amber-600 dark:text-amber-400 border border-amber-100 dark:border-amber-900/40'
                                : 'bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 border border-blue-100 dark:border-blue-900/40'
                        }`}>
                            <i className={`bi ${isService ? 'bi-tools' : 'bi-box-seam'}`} />
                        </div>

                        <div className="min-w-0 flex-1">
                            <div className="flex items-center gap-2 flex-wrap">
                                <span className={`text-xs font-bold truncate ${itemHasError ? 'text-red-600 dark:text-red-400' : 'text-slate-800 dark:text-slate-100'}`}>
                                    {item.description?.trim() || (
                                        <span className="text-slate-400 italic font-normal">
                                            {isService ? 'Serviço sem descrição' : 'Produto sem descrição'}
                                        </span>
                                    )}
                                </span>
                                {isTemporaryProduct && <TemporaryProductAlert />}
                                {item.handlingType && !shouldHideHandling && (
                                    <span className="px-1.5 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-[10px] font-semibold text-slate-500">
                                        {item.handlingType}
                                    </span>
                                )}
                            </div>
                            {item.observation && (
                                <div className="text-[10px] text-slate-400 truncate max-w-sm mt-0.5">
                                    {item.observation}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="flex items-center gap-3 shrink-0">
                        <div className="text-right">
                            <span className="text-[10px] text-slate-400 font-bold block leading-none">
                                {item.quantity || 1} un
                            </span>
                            <span className="text-xs font-black text-blue-600 dark:text-blue-400">
                                <CurrencyDisplay value={calcItemTotalValue(item)} />
                            </span>
                        </div>

                        <div className="flex items-center gap-1">
                            <button
                                type="button"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onToggleExpand?.();
                                }}
                                className="w-7 h-7 flex items-center justify-center text-slate-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-950/30 rounded-lg transition-colors"
                                title="Editar item"
                            >
                                <i className="bi bi-pencil text-xs" />
                            </button>
                            {!item.isComboItem && (
                                <button
                                    type="button"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        onDelete();
                                    }}
                                    className="w-7 h-7 flex items-center justify-center text-slate-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/30 rounded-lg transition-colors"
                                    title="Excluir item"
                                >
                                    <i className="bi bi-trash text-xs" />
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            );
        }

        // MODO EXPANDIDO (FORMULÁRIO COMPACTO)
        return (
            <div className={`p-3.5 sm:p-4 bg-white dark:bg-slate-900 border rounded-2xl ${
                highlightAsTemporary 
                    ? 'border-amber-400 dark:border-amber-500 ring-2 ring-amber-400/20 bg-amber-50/10 dark:bg-amber-950/10' 
                    : itemHasError
                    ? 'border-red-500 ring-2 ring-red-500/10' 
                    : 'border-slate-200/80 dark:border-slate-800'
            } shadow-sm relative group transition-all space-y-3`}>
                
                {/* Cabeçalho do Card Expandido com Ações */}
                <div className={`flex items-center justify-between border-b pb-2 ${itemHasError ? 'border-red-300 dark:border-red-800' : 'border-slate-100 dark:border-slate-800'}`}>
                    <div className="flex items-center gap-2">
                        <span className={`w-5 h-5 rounded-lg flex items-center justify-center text-[10px] ${
                            isService
                                ? 'bg-amber-50 dark:bg-amber-950/40 text-amber-600 dark:text-amber-400'
                                : 'bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400'
                        }`}>
                            <i className={`bi ${isService ? 'bi-tools' : 'bi-box-seam'}`} />
                        </span>
                        <span className={`text-[11px] font-black uppercase tracking-wider ${itemHasError ? 'text-red-600 dark:text-red-400' : 'text-slate-500 dark:text-slate-400'}`}>
                            Item #{idx + 1} • {isService ? 'Serviço' : 'Produto'}
                        </span>
                    </div>

                    <div className="flex items-center gap-1">
                        <button
                            type="button"
                            onClick={onToggleExpand}
                            className="px-2 py-1 flex items-center gap-1 text-[11px] font-bold text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
                            title="Recolher item"
                        >
                            <span>Recolher</span>
                            <i className="bi bi-chevron-up text-xs" />
                        </button>
                        {!item.isComboItem && (
                            <button
                                type="button"
                                onClick={onDelete}
                                className="w-7 h-7 flex items-center justify-center text-slate-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/30 rounded-lg transition-colors"
                                title="Excluir item"
                            >
                                <i className="bi bi-trash text-xs" />
                            </button>
                        )}
                    </div>
                </div>

                {/* Linha 1: Descrição */}
                <div className="w-full">
                    <label className={`text-[10px] font-black uppercase tracking-wider mb-1 flex items-center gap-1.5 ml-1 ${error ? 'text-red-600 dark:text-red-400' : 'text-slate-400 dark:text-slate-500'}`}>
                        <span>{isService ? 'Descrição do Serviço' : 'Descrição do Item'}</span> <span className="text-red-500">*</span>
                        {isTemporaryProduct && <TemporaryProductAlert />}
                    </label>
                    {isService ? (
                        <ServiceAutocomplete
                            value={item.description}
                            onChange={(val) => onChange(idx, 'description', val)}
                            onSelectService={handleSelectService}
                            placeholder="Buscar serviço cadastrado ou digite o nome..."
                            className={error ? 'border-red-500 ring-2 ring-red-500' : ''}
                        />
                    ) : !item.isComboItem ? (
                        <ProductAutocomplete
                            value={item.description}
                            onChange={(val) => onChange(idx, 'description', val)}
                            onSelect={(p, v) => onSelectProduct(idx, p, v)}
                            placeholder="Buscar produto no catálogo..."
                            isTemporary={isTemporaryProduct}
                            isSelected={isLinkedProduct}
                            className={error ? 'border-red-500 rounded-2xl ring-2 ring-red-500' : ''}
                        />
                    ) : (
                        <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 dark:bg-slate-800/40 rounded-2xl border border-slate-100 dark:border-slate-800">
                            <i className="bi bi-arrow-return-right text-slate-400" />
                            <span className="text-xs italic font-bold text-slate-600 dark:text-slate-300">{item.description}</span>
                        </div>
                    )}
                </div>
                {serviceProductLink}

                {/* Linha 2: Manuseio (se produto) e Observação */}
                {!item.isComboItem && (
                    <div className="flex flex-wrap sm:flex-nowrap items-start gap-3">
                        {!shouldHideHandling && (
                            <div className="w-full sm:w-[220px] md:w-[240px] shrink-0">
                                <label className={`text-[10px] font-black uppercase tracking-wider mb-1 block ml-1 ${handlingError ? 'text-red-600 dark:text-red-400' : 'text-slate-400 dark:text-slate-500'}`}>
                                    Tipo de Manuseio <span className="text-red-500">*</span>
                                </label>
                                <select
                                    className={`w-full appearance-none border-b-2 bg-transparent px-3 py-1.5 text-xs font-bold text-slate-700 outline-none transition-colors dark:text-slate-200 ${handlingError ? 'border-red-500 focus:border-red-500' : 'border-slate-200 focus:border-blue-600 dark:border-slate-700 dark:focus:border-blue-500'}`}
                                    value={item.handlingType || ''}
                                    onChange={(e) => {
                                        const val = e.target.value;
                                        if (!val) return;
                                        if (item.handlingType === val) return;
                                        onChange(idx, 'handlingType', val);
                                    }}
                                >
                                    <option value="" disabled className="dark:bg-slate-900">Manuseio...</option>
                                    {(() => {
                                        const options = deliveryMethod === 'delivery' ? (settings.deliveryHandlingOptions || []) : (settings.pickupHandlingOptions || []);
                                        const isSelectedInOptions = item.handlingType && options.some(o => o.label === item.handlingType);
                                        
                                        return (
                                            <>
                                                {options.map(opt => (
                                                    <option key={opt.label} value={opt.label} className="dark:bg-slate-900">{opt.label}</option>
                                                ))}
                                                {item.handlingType && !isSelectedInOptions && (
                                                    <option value={item.handlingType} className="italic text-slate-400">
                                                        {item.handlingType} (Atual)
                                                    </option>
                                                )}
                                            </>
                                        );
                                    })()}
                                </select>
                            </div>
                        )}

                        <div className="flex-1 min-w-[200px] w-full">
                            <label className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500 mb-1 block ml-1">
                                Observação
                            </label>
                            <input
                                type="text"
                                value={tempObservation}
                                onChange={(e) => setTempObservation(e.target.value)}
                                onBlur={commitObservation}
                                placeholder="Observação sobre este item..."
                                className="w-full bg-slate-50/70 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-700 focus:border-blue-500 px-3 py-1.5 rounded-xl text-xs font-medium text-slate-700 dark:text-slate-200 outline-none transition-all placeholder:text-slate-400"
                            />
                        </div>
                    </div>
                )}

                {/* Linha 3: Grid de Valores */}
                {!item.isComboItem && (
                    <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-2.5 items-end pt-1">
                        <div className="w-full">
                            <label className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500 mb-1 block ml-1">
                                Qtd. <span className="text-red-500">*</span>
                            </label>
                            <UnitInput
                                value={item.quantity}
                                onChange={(value: number) => onChange(idx, 'quantity', value)}
                                disabled={item.isComboItem}
                            />
                        </div>

                        <div className="w-full">
                            <label className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500 mb-1 block ml-1">
                                Preço Un. <span className="text-red-500">*</span>
                            </label>
                            <CurrencyInput
                                value={tempUnitPrice}
                                onChange={(val: number) => setTempUnitPrice(val)}
                                onBlur={commitUnitPrice}
                            />
                        </div>

                        <div className="w-full">
                            <label className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500 mb-1 block ml-1">
                                Desc. R$
                            </label>
                            <CurrencyInput
                                value={tempDiscountValue}
                                max={item.unitPrice || undefined}
                                onChange={(val: number) => setTempDiscountValue(val)}
                                onBlur={commitDiscountValue}
                            />
                        </div>

                        <div className="w-full">
                            <label className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500 mb-1 block ml-1">
                                Desc. %
                            </label>
                            <CurrencyOrPercentInput
                                prefix=""
                                suffix=" %"
                                value={tempDiscountPercent}
                                max={100}
                                onChange={(val: number) => setTempDiscountPercent(val)}
                                onBlur={commitDiscountPercent}
                            />
                        </div>

                        <div className="w-full">
                            <label className="text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500 mb-1 block ml-1">
                                Preço Un. Líq.
                            </label>
                            <CurrencyInput
                                value={tempSubtotal}
                                max={item.unitPrice || undefined}
                                onChange={(val: number) => setTempSubtotal(val)}
                                onBlur={commitSubtotal}
                            />
                        </div>

                        {/* Total do Item */}
                        <div className="w-full flex flex-col items-end justify-center px-3 py-1.5 bg-blue-50/70 dark:bg-blue-950/30 border border-blue-100/80 dark:border-blue-900/40 rounded-xl min-h-[44px]">
                            <span className="text-[8px] font-black uppercase text-blue-600/70 dark:text-blue-400/70 tracking-widest">Total</span>
                            <div className="text-xs font-black text-blue-600 dark:text-blue-400">
                                <CurrencyDisplay value={calcItemTotalValue(item)} />
                            </div>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    // VISUALIZAÇÃO EM TABELA (width >= 1280px)
    return (
        <tr className={`group transition-colors border-b border-slate-100 dark:border-slate-800 last:border-0 font-sans ${highlightAsTemporary ? 'bg-amber-50/50 dark:bg-amber-950/20 ring-2 ring-inset ring-amber-400/50' : 'hover:bg-slate-50/50 dark:hover:bg-slate-800/20'}`}>
            <td className="px-3 py-1.5 relative group/desc">
                {isService ? (
                    <>
                        <ServiceAutocomplete
                            value={item.description}
                            onChange={(val) => onChange(idx, 'description', val)}
                            onSelectService={handleSelectService}
                            placeholder="Descrição do serviço..."
                            className={error ? 'border-red-500 rounded-xl ring-2 ring-red-500' : ''}
                        />
                        <div className="mt-1 flex items-center gap-2">
                            <input
                                type="text"
                                value={tempObservation}
                                onChange={(e) => setTempObservation(e.target.value)}
                                onBlur={commitObservation}
                                placeholder="Observação..."
                                className="w-full bg-slate-50/60 dark:bg-slate-800/40 border border-slate-200/80 dark:border-slate-700/80 focus:border-blue-500 px-2 py-0.5 rounded-lg text-[11px] font-medium text-slate-700 dark:text-slate-200 outline-none transition-all placeholder:text-slate-400"
                            />
                        </div>
                        {serviceProductLink}
                    </>
                ) : !item.isComboItem ? (
                    <>
                    <ProductAutocomplete
                        value={item.description}
                        onChange={(val) => onChange(idx, 'description', val)}
                        onSelect={(p, v) => onSelectProduct(idx, p, v)}
                        placeholder="Busque ou digite um produto..."
                        isTemporary={isTemporaryProduct}
                        isSelected={isLinkedProduct}
                        className={error ? 'border-red-500 rounded-xl ring-2 ring-red-500' : ''}
                    />
                    <div className="mt-1 flex items-center gap-2">
                        <input
                            type="text"
                            value={tempObservation}
                            onChange={(e) => setTempObservation(e.target.value)}
                            onBlur={commitObservation}
                            placeholder="Observação (ex: salvados, peça do mostruário com avaria)..."
                            className="w-full bg-slate-50/60 dark:bg-slate-800/40 border border-slate-200/80 dark:border-slate-700/80 focus:border-blue-500 px-2 py-0.5 rounded-lg text-[11px] font-medium text-slate-700 dark:text-slate-200 outline-none transition-all placeholder:text-slate-400"
                        />
                    </div>
                    {isLinkedProduct && (
                        <div className="flex items-center gap-1 mt-0.5 text-[9px] font-bold text-emerald-600 dark:text-emerald-400 ml-1">
                            <i className="bi bi-check-circle-fill text-emerald-500 text-[10px]" />
                            <span>Produto vinculado ao catálogo</span>
                        </div>
                    )}
                    {isTemporaryProduct && (
                        <div className="mt-0.5 ml-1">
                            <TemporaryProductAlert />
                        </div>
                    )}
                    </>
                ) : (
                    <div className="flex items-center gap-2 pl-3">
                        <i className="bi bi-arrow-return-right text-slate-300" />
                        <span className="text-xs italic text-slate-500 dark:text-slate-400">{item.description}</span>
                    </div>
                )}
                {error && (
                    <div className="absolute left-4 -top-8 hidden group-hover/desc:flex items-center px-2 py-1 bg-red-500 text-white text-[10px] font-bold rounded shadow-lg z-50 whitespace-nowrap font-sans">
                        {error}
                        <div className="absolute -bottom-1 left-4 w-2 h-2 bg-red-500 rotate-45" />
                    </div>
                )}
            </td>
            {!shouldHideHandling && (
                <td className="px-2 py-1.5 w-[140px]">
                    {!item.isComboItem && (
                        <div className="relative group/hsel">
                            <select
                                className={`w-full appearance-none border-b-2 bg-transparent px-2 py-1 text-[11px] font-bold text-slate-600 outline-none transition-colors dark:text-slate-400 ${handlingError ? 'border-red-500 focus:border-red-500' : 'border-slate-200 focus:border-blue-600 dark:border-slate-800 dark:focus:border-blue-500'}`}
                                value={item.handlingType || ''}
                                onChange={(e) => {
                                    const val = e.target.value;
                                    if (!val) return;
                                    if (item.handlingType === val) return;
                                    onChange(idx, 'handlingType', val);
                                }}
                            >
                                <option value="" disabled className="dark:bg-slate-900">Manuseio...</option>
                                {(() => {
                                    const options = deliveryMethod === 'delivery' ? (settings.deliveryHandlingOptions || []) : (settings.pickupHandlingOptions || []);
                                    const isSelectedInOptions = item.handlingType && options.some(o => o.label === item.handlingType);
                                    
                                    return (
                                        <>
                                            {options.map(opt => (
                                                <option key={opt.label} value={opt.label} className="dark:bg-slate-900">{opt.label}</option>
                                            ))}
                                            {item.handlingType && !isSelectedInOptions && (
                                                <option value={item.handlingType} className="italic text-slate-400">
                                                    {item.handlingType} (Atual)
                                                </option>
                                            )}
                                        </>
                                    );
                                })()}
                            </select>
                        </div>
                    )}
                </td>
            )}
            {isService && !hideHandling && !isBudget && !isReturn && (
                <td className="px-2 py-1.5 w-[140px] text-center text-xs text-slate-300 dark:text-slate-700">
                    -
                </td>
            )}
            <td className="px-2 py-1.5 w-[80px]">
                <UnitInput
                    value={item.quantity}
                    onChange={(value: number) => onChange(idx, 'quantity', value)}
                    disabled={item.isComboItem}
                />
            </td>
            <td className="px-2 py-1.5 w-[110px]">
                {!item.isComboItem ? (
                    <CurrencyInput
                        value={tempUnitPrice}
                        onChange={(val: number) => setTempUnitPrice(val)}
                        onBlur={commitUnitPrice}
                        className="w-full bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 focus:border-blue-500 px-2 py-1 rounded-xl text-xs font-bold outline-none text-right"
                    />
