export default BodyRow;

import React, { useState, useEffect, useRef } from 'react';
import Service from '../../../types/service.type';
import { subscribeToServices } from '../../../utils/serviceService';

interface ServiceAutocompleteProps {
    value: string;
    onChange: (val: string) => void;
    onSelectService?: (service: Service) => void;
    placeholder?: string;
    className?: string;
}

export const ServiceAutocomplete: React.FC<ServiceAutocompleteProps> = ({
    value,
    onChange,
    onSelectService,
    placeholder = 'Descrição do serviço (ou escolha um cadastrado)...',
    className = ''
}) => {
    const [services, setServices] = useState<Service[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const unsubscribe = subscribeToServices((data) => {
            setServices(data.filter((s) => s.active && !s.deleted));
        });
        return () => unsubscribe();
    }, []);

    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const filteredServices = services.filter((s) =>
        s.description.toLowerCase().includes((value || '').toLowerCase())
    );

    return (
        <div ref={containerRef} className="relative w-full">
            <div className="relative flex items-center">
                <input
                    type="text"
                    value={value}
                    onChange={(e) => {
                        onChange(e.target.value);
                        setIsOpen(true);
                    }}
                    onFocus={() => setIsOpen(true)}
                    placeholder={placeholder}
                    className={`w-full bg-slate-50/70 dark:bg-slate-800/40 border border-slate-200 dark:border-slate-700 focus:border-blue-500 px-3 py-2 rounded-2xl text-xs font-bold text-slate-800 dark:text-slate-100 outline-none transition-all placeholder:text-slate-400 placeholder:font-normal ${className}`}
                />
                {services.length > 0 && (
                    <button
                        type="button"
                        onClick={() => setIsOpen(!isOpen)}
                        className="absolute right-2.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 text-xs transition-colors p-1"
                        title="Ver serviços cadastrados"
                    >
                        <i className={`bi bi-chevron-${isOpen ? 'up' : 'down'}`} />
                    </button>
                )}
            </div>

            {isOpen && filteredServices.length > 0 && (
                <div className="absolute left-0 right-0 top-full mt-1.5 z-50 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-xl max-h-48 overflow-y-auto custom-scrollbar p-1.5 animate-in fade-in slide-in-from-top-1 duration-150">
                    <div className="text-[10px] font-black uppercase tracking-wider text-slate-400 px-2.5 py-1">
                        Serviços Cadastrados
                    </div>
                    {filteredServices.map((service) => (
                        <button
                            key={service.id || service.description}
                            type="button"
                            onClick={() => {
                                onChange(service.description);
                                if (onSelectService) {
                                    onSelectService(service);
                                }
                                setIsOpen(false);
                            }}
                            className="w-full text-left px-2.5 py-2 hover:bg-blue-50 dark:hover:bg-blue-950/40 rounded-xl flex items-center justify-between text-xs transition-colors group"
                        >
                            <span className="font-bold text-slate-700 dark:text-slate-200 group-hover:text-blue-600 dark:group-hover:text-blue-400">
                                {service.description}
                            </span>
                            {service.unitPrice > 0 && (
                                <span className="font-extrabold text-blue-600 dark:text-blue-400 text-[11px] ml-2 shrink-0">
                                    {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(service.unitPrice)}
                                </span>
                            )}
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
};

export default ServiceAutocomplete;

import React, { useState, useEffect, useMemo } from "react";
import CustomerData from '@/pages/types/customerData.type';
import Person from '@/pages/types/person.type';
import Order from '@/pages/types/order.type';
import { getRecentPeople, searchPeople } from '@/pages/utils/personService';
import { getOrdersByCustomerInfo } from '@/pages/utils/orderSearchQueries';
import { canSearchCustomers, getCustomerSearchQuery, matchesCustomerSearch } from "@/pages/utils/customerSearch";

interface CustomerSearchEntry {
    id: string;
    fullName: string;
    phone: string;
    source: 'cadastro' | 'pedido';
    totalOrders: number;
    lastOrder?: string;
    customerData: CustomerData;
}

interface Props {
    readonly onSelect: (customer: CustomerData) => void;
    readonly onClose: () => void;
    readonly onAddNew?: () => void;
    readonly initialSearch?: string;
}

const CustomerSearchModal = ({ onSelect, onClose, onAddNew, initialSearch = "" }: Props) => {
    const [search, setSearch] = useState(initialSearch);
    const [people, setPeople] = useState<Person[]>([]);
    const [orders, setOrders] = useState<Partial<Order>[]>([]);
    const [loadingPeople, setLoadingPeople] = useState(true);
    const [loadingOrders, setLoadingOrders] = useState(true);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === "Escape") {
                onClose();
            }
        };
        window.addEventListener("keydown", handleKeyDown);
        return () => window.removeEventListener("keydown", handleKeyDown);
    }, [onClose]);

    // Load recent on mount
    useEffect(() => {
        const loadRecent = async () => {
            setLoadingPeople(true);
            setLoadingOrders(true);
            try {
                const recents = await getRecentPeople('customers', 20);
                setPeople(recents);
            } catch (err) {
                console.error("Erro ao carregar recentes:", err);
            } finally {
                setLoadingPeople(false);
                setLoadingOrders(false);
            }
        };
        loadRecent();
    }, []);

    // Debounced search
    useEffect(() => {
        if (!search.trim() || search.trim().length < 2) return;

        const delay = setTimeout(async () => {
            setLoadingPeople(true);
            setLoadingOrders(true);
            try {
                const [foundPeople, foundOrders] = await Promise.all([
                    searchPeople(search, 'customers', 30),
                    getOrdersByCustomerInfo(search)
                ]);
                setPeople(foundPeople);
                setOrders(foundOrders.map(o => ({
                    id: o.id,
                    date: o.date,
                    customerData: o.customerData,
                    deleted: o.deleted
                })));
            } catch (e) {
                console.error("Erro ao pesquisar clientes:", e);
            } finally {
                setLoadingPeople(false);
                setLoadingOrders(false);
            }
        }, 350);

        return () => clearTimeout(delay);
    }, [search]);

    // Orders are now loaded in the search effect.
    // Build unified customer list: merge cadastro + order history
    const customerList = useMemo<CustomerSearchEntry[]>(() => {
        const map = new Map<string, CustomerSearchEntry>();

        // Add from People registry
        people.forEach(p => {
            const name = (p.fullName || p.tradeName || '').trim();
            if (!name) return;
            const key = name.toLowerCase();

            map.set(key, {
                id: p.id || key,
                fullName: name,
                phone: p.phone || '',
                source: 'cadastro',
                totalOrders: 0,
                customerData: {
                    fullName: name,
                    phone: p.phone || '',
                    noPhone: p.noPhone || false,
                    fullAddress: p.fullAddress || {
                        cep: '', street: '', number: '', complement: '',
                        neighborhood: '', city: '', observation: ''
                    }
                }
            });
        });

        // Enrich from order history
        orders.forEach(o => {
            const name = (o.customerData?.fullName || '').trim();
            if (!name) return;
            const key = name.toLowerCase();

            const existing = map.get(key);
            if (existing) {
                existing.totalOrders += 1;
                if (!existing.lastOrder || o.date > (existing.lastOrder || '')) {
                    existing.lastOrder = o.date;
                }
                // Update address if order has more complete data
                if (o.customerData?.fullAddress?.street && !existing.customerData.fullAddress.street) {
                    existing.customerData = {
                        ...existing.customerData,
                        ...o.customerData
                    };
                }
            } else {
                map.set(key, {
                    id: key,
                    fullName: name,
                    phone: o.customerData?.phone || '',
                    source: 'pedido',
                    totalOrders: 1,
                    lastOrder: o.date,
                    customerData: {
                        fullName: name,
                        phone: o.customerData?.phone || '',
                        noPhone: o.customerData?.noPhone || false,
                        fullAddress: o.customerData?.fullAddress || {
                            cep: '', street: '', number: '', complement: '',
                            neighborhood: '', city: '', observation: ''
                        }
                    }
                });
            }
        });

        // Sort: registered first, then by total orders desc, then alphabetically
        return Array.from(map.values()).sort((a, b) => {
            if (a.source === 'cadastro' && b.source !== 'cadastro') return -1;
            if (b.source === 'cadastro' && a.source !== 'cadastro') return 1;
            if (b.totalOrders !== a.totalOrders) return b.totalOrders - a.totalOrders;
            return a.fullName.localeCompare(b.fullName);
        });
    }, [people, orders]);

    const [selectedType, setSelectedType] = useState<'all' | 'customer' | 'employee' | 'supplier'>('all');

    const filtered = useMemo(() => {
        let list = customerList;
        
        // Apply type filter
        if (selectedType !== 'all') {
            list = list.filter(c => {
                const p = people.find(p => p.id === c.id);
                if (!p) return selectedType === 'customer'; // Default guest to customer
                if (selectedType === 'customer') return p.type === 'customers';
                if (selectedType === 'employee') return p.type === 'employees';
                if (selectedType === 'supplier') return p.type === 'suppliers';
                return true;
            });
        }

        // We already searched in the server, but we can do a local filter to match the UI behavior
        // if the server returned broader results than what the user specifically typed.
        if (!search.trim()) return list;
        if (!canSearchCustomers(search)) return [];
        const query = getCustomerSearchQuery(search);
        return list.filter(c => {
            const addr = c.customerData.fullAddress;
            return matchesCustomerSearch(query, {
                name: c.fullName,
                phone: c.phone,
                address: `${addr?.street || ''} ${addr?.number || ''} ${addr?.neighborhood || ''} ${addr?.city || ''}`,
            });
        });
    }, [customerList, search, selectedType, people]);

    const isLoading = loadingPeople || loadingOrders;

    return (
        <div className="fixed inset-0 z-[200] flex items-end sm:items-center justify-center p-0 sm:p-4">
            <button
                type="button"
                aria-label="Fechar busca avançada de clientes"
                className="fixed inset-0 bg-slate-900/60 backdrop-blur-[3px] transition-opacity"
                onClick={onClose}
            />
            <div
                role="dialog"
                aria-modal="true"
                aria-labelledby="customer-search-title"
                className="relative z-10 bg-white dark:bg-slate-900 w-full max-w-2xl rounded-t-[2.5rem] sm:rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden border-t sm:border border-slate-100 dark:border-slate-800"
                style={{ height: '90vh', maxHeight: '90vh' }}
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="px-8 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-blue-50 dark:bg-blue-900/10 shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="bg-blue-600 p-2.5 rounded-2xl shadow-lg shadow-blue-200 dark:shadow-blue-900/30">
                            <i className="bi bi-people-fill text-white text-xl" />
                        </div>
                        <div>
                            <h2 id="customer-search-title" className="text-lg font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                Busca Avançada de Clientes
                            </h2>
                            <p className="text-[10px] uppercase font-black text-blue-600 dark:text-blue-400 tracking-widest mt-0.5">
                                Cadastro + Histórico de Pedidos
                            </p>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        {onAddNew && (
                            <button
                                type="button"
                                onClick={onAddNew}
                                className="flex items-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-xl transition-all shadow-lg shadow-emerald-200 dark:shadow-none active:scale-95 font-black text-[10px] uppercase tracking-widest"
                            >
                                <i className="bi bi-person-plus-fill" />
                                <span className="hidden sm:inline">Novo Cliente</span>
                            </button>
                        )}
                        <button
                            type="button"
                            aria-label="Fechar"
                            onClick={onClose}
                            className="p-2 hover:bg-blue-100 dark:hover:bg-blue-900/30 rounded-full transition-colors text-slate-400 hover:text-slate-600"
                        >
                            <i className="bi bi-x-lg text-xl" />
                        </button>
                    </div>
                </div>

                {/* Search Bar & Filters */}
                <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 shrink-0">
                    <div className="flex flex-col gap-4">
                        <div className="relative">
                            <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                            <input
                                autoFocus
                                type="text"
                                placeholder="Digite ao menos 2 caracteres para buscar..."
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                                className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm font-bold text-slate-700 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 transition-all placeholder:font-normal placeholder:text-slate-400"
                            />
                            {search && (
                                <button
                                    type="button"
                                    aria-label="Limpar busca"
                                    onClick={() => setSearch('')}
                                    className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                                >
                                    <i className="bi bi-x-circle-fill" />
                                </button>
                            )}
                        </div>

                        {/* Type Tabs */}
                        <div className="flex gap-1.5 p-1 bg-slate-100 dark:bg-slate-950 rounded-xl w-fit">
                            {(
                                [
                                    { id: 'all', label: 'Todos', icon: 'bi-grid' },
                                    { id: 'customer', label: 'Clientes', icon: 'bi-person' },
                                    { id: 'employee', label: 'Funcionários', icon: 'bi-person-badge' },
                                    { id: 'supplier', label: 'Fornecedores', icon: 'bi-truck' }
                                ] as const
                            ).map(tab => (
                                <button
                                    key={tab.id}
                                    type="button"
                                    onClick={() => setSelectedType(tab.id)}
                                    className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${selectedType === tab.id ? 'bg-white dark:bg-slate-800 text-blue-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                                >
                                    <i className={`bi ${tab.icon}`} />
                                    {tab.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="flex items-center gap-4 mt-3 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        <span className="flex items-center gap-1.5">
                            <span className="w-2 h-2 rounded-full bg-blue-500" />
                            Cadastrado
                        </span>
                        <span className="flex items-center gap-1.5">
                            <span className="w-2 h-2 rounded-full bg-emerald-500" />
                            Histórico de Pedidos
                        </span>
                        <span className="ml-auto">
                            {isLoading ? 'Carregando...' : `${filtered.length} registro(s)`}
                        </span>
                    </div>
                </div>

                {/* Customer List */}
                <div className="flex-1 overflow-y-auto custom-scrollbar">
                    {isLoading ? (
                        <div className="flex items-center justify-center py-16 gap-3 text-slate-400">
                            <i className="bi bi-hourglass-split animate-spin text-2xl" />
                            <span className="text-sm font-bold">Carregando clientes...</span>
                        </div>
                    ) : filtered.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-16 text-slate-400 gap-4">
                            <i className="bi bi-person-x text-4xl opacity-30" />
                            <div className="text-center">
                                <p className="text-sm font-bold">{search.trim() && !canSearchCustomers(search) ? "Digite ao menos 2 caracteres" : "Nenhum cliente encontrado"}</p>
                                <p className="text-xs text-slate-400">{search.trim() && !canSearchCustomers(search) ? "Use nome, telefone, cidade ou bairro" : "Tente outro nome, telefone ou cidade"}</p>
                            </div>
                            {onAddNew && (
                                <button
                                    onClick={onAddNew}
                                    className="mt-2 flex items-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl transition-all shadow-xl shadow-blue-200 dark:shadow-none active:scale-95 font-black text-xs uppercase tracking-widest"
                                >
                                    <i className="bi bi-person-plus-fill" />
                                    Cadastrar Novo Cliente
                                </button>
                            )}
                        </div>
                    ) : (
                        <table className="w-full text-left">
                            <thead className="sticky top-0 bg-slate-50 dark:bg-slate-800/80 backdrop-blur-sm z-10">
                                <tr className="border-b border-slate-100 dark:border-slate-700">
                                    <th className="px-6 py-3 text-[9px] font-black uppercase tracking-widest text-slate-400">Cliente</th>
                                    <th className="px-4 py-3 text-[9px] font-black uppercase tracking-widest text-slate-400">Telefone</th>
                                    <th className="px-4 py-3 text-[9px] font-black uppercase tracking-widest text-slate-400 hidden sm:table-cell">Endereço</th>
                                    <th className="px-4 py-3 text-[9px] font-black uppercase tracking-widest text-slate-400 text-center">Pedidos</th>
                                    <th className="px-4 py-3 text-[9px] font-black uppercase tracking-widest text-slate-400 text-center">Origem</th>
                                    <th className="px-4 py-3" />
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                                {filtered.map((c) => (
                                    <tr
                                        key={c.id}
                                        role="button"
                                        tabIndex={0}
                                        onClick={() => { onSelect(c.customerData); onClose(); }}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter' || e.key === ' ') {
                                                e.preventDefault();
                                                onSelect(c.customerData);
                                                onClose();
                                            }
                                        }}
                                        className="hover:bg-blue-50/60 dark:hover:bg-blue-900/10 cursor-pointer transition-colors group focus:outline-none focus:bg-blue-50/80 dark:focus:bg-blue-900/20"
                                    >
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-white text-xs font-black shrink-0 ${c.source === 'cadastro' ? 'bg-blue-500' : 'bg-emerald-500'}`}>
                                                    {c.fullName.charAt(0).toUpperCase()}
                                                </div>
                                                <span className="text-sm font-bold text-slate-800 dark:text-slate-200">
                                                    {c.fullName}
                                                </span>
                                            </div>
                                        </td>
                                        <td className="px-4 py-4">
                                            <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">
                                                {c.phone || <span className="italic text-slate-300">—</span>}
                                            </span>
                                        </td>
                                        <td className="px-4 py-4 hidden sm:table-cell">
                                            <span className="text-xs text-slate-400 font-medium">
                                                {c.customerData.fullAddress.city
                                                    ? `${c.customerData.fullAddress.neighborhood ? c.customerData.fullAddress.neighborhood + ', ' : ''}${c.customerData.fullAddress.city}`
                                                    : <span className="italic text-slate-300">Sem endereço</span>
                                                }
                                            </span>
                                        </td>
                                        <td className="px-4 py-4 text-center">
                                            {c.totalOrders > 0 ? (
                                                <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400 rounded-full text-[9px] font-black uppercase">
                                                    <i className="bi bi-cart-check" />
                                                    {c.totalOrders}
                                                </span>
                                            ) : (
                                                <span className="text-slate-300 text-xs">—</span>
                                            )}
                                        </td>
                                        <td className="px-4 py-4 text-center">
                                            <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-black uppercase ${
                                                c.source === 'cadastro'
                                                    ? 'bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400'
                                                    : 'bg-emerald-50 dark:bg-emerald-900/20 text-emerald-600 dark:text-emerald-400'
                                            }`}>
                                                <i className={`bi ${c.source === 'cadastro' ? 'bi-person-check' : 'bi-receipt'}`} />
                                                {c.source === 'cadastro' ? 'Cadastro' : 'Pedido'}
                                            </span>
                                        </td>
                                        <td className="px-4 py-4 text-right">
                                            <button
                                                type="button"
                                                onClick={() => { onSelect(c.customerData); onClose(); }}
                                                className="opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-blue-700 shadow-lg shadow-blue-200 dark:shadow-none"
                                            >
                                                Selecionar
                                                <i className="bi bi-arrow-right" />
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>

                {/* Footer */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 shrink-0 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
                    <p className="text-[10px] text-slate-400 font-bold">
                        Clique em qualquer linha para selecionar o cliente
                    </p>
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-4 py-2 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-red-500 transition-colors"
                    >
                        Cancelar
                    </button>
                </div>
            </div>
        </div>
    );
};

export default CustomerSearchModal;

import React, { useState, useEffect, useMemo } from "react";
import Person from '@/pages/types/person.type';
import { subscribeToPeople } from '@/pages/utils/personService';
import { normalizeSearchTerm } from "@/pages/utils/textUtils";

interface Props {
    onSelect: (sellerName: string) => void;
    onClose: () => void;
}

const EmployeeSearchModal = ({ onSelect, onClose }: Props) => {
    const [search, setSearch] = useState("");
    const [employees, setEmployees] = useState<Person[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // subscribeToPeople('employees') will automatically fetch employees + profiles with a position
        const unsub = subscribeToPeople('employees', (data) => {
            setEmployees(data.filter(p => p.active && !p.deleted));
            setLoading(false);
        });
        return () => { if (unsub) unsub(); };
    }, []);

    const filtered = useMemo(() => {
        if (!search.trim()) return employees;
        const s = normalizeSearchTerm(search);
        return employees.filter(e =>
            normalizeSearchTerm(e.fullName || '').includes(s) ||
            normalizeSearchTerm(e.position || '').includes(s)
        );
    }, [employees, search]);

    return (
        <div
            className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-[3px] animate-fade-in"
            onClick={onClose}
        >
            <div
                className="bg-white dark:bg-slate-900 w-full max-w-2xl rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-slide-up border border-slate-100 dark:border-slate-800"
                style={{ maxHeight: '85vh' }}
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="px-8 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-blue-50 dark:bg-blue-900/10 shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="bg-blue-600 p-2.5 rounded-2xl shadow-lg shadow-blue-200 dark:shadow-blue-900/30">
                            <i className="bi bi-person-badge text-white text-xl" />
                        </div>
                        <div>
                            <h2 className="text-lg font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                Selecionar Atendente Principal
                            </h2>
                            <p className="text-[10px] uppercase font-black text-blue-600 dark:text-blue-400 tracking-widest mt-0.5">
                                Pesquise entre os funcionários
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-blue-100 dark:hover:bg-blue-900/30 rounded-full transition-colors text-slate-400 hover:text-slate-600"
                    >
                        <i className="bi bi-x-lg text-xl" />
                    </button>
                </div>

                {/* Search Bar */}
                <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 shrink-0">
                    <div className="relative">
                        <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input
                            autoFocus
                            type="text"
                            placeholder="Busque por nome ou cargo..."
                            value={search}
                            onChange={e => setSearch(e.target.value)}
                            className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm font-bold text-slate-700 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 transition-all placeholder:font-normal placeholder:text-slate-400"
                        />
                        {search && (
                            <button
                                onClick={() => setSearch('')}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                            >
                                <i className="bi bi-x-circle-fill" />
                            </button>
                        )}
                    </div>
                    <div className="flex items-center gap-4 mt-3 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        <span className="ml-auto">
                            {loading ? 'Carregando...' : `${filtered.length} funcionário(s) encontrados`}
                        </span>
                    </div>
                </div>

                {/* Employee List */}
                <div className="flex-1 overflow-y-auto custom-scrollbar bg-white dark:bg-slate-900">
                    {loading ? (
                        <div className="flex items-center justify-center py-16 gap-3 text-slate-400">
                            <i className="bi bi-hourglass-split animate-spin text-2xl" />
                            <span className="text-sm font-bold">Carregando funcionários...</span>
                        </div>
                    ) : filtered.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-16 text-slate-400 gap-3">
                            <i className="bi bi-person-x text-4xl opacity-30" />
                            <p className="text-sm font-bold">Nenhum funcionário encontrado</p>
                        </div>
                    ) : (
                        <div className="flex flex-col p-4 gap-2">
                            {filtered.map(emp => (
                                <button
                                    key={emp.id}
                                    onClick={() => { onSelect(emp.fullName); onClose(); }}
                                    className="flex items-center justify-between p-4 rounded-2xl border border-slate-100 dark:border-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/20 hover:border-blue-200 dark:hover:border-blue-800/50 transition-all group text-left"
                                >
                                    <div className="flex flex-col gap-1">
                                        <span className="text-sm font-bold text-slate-800 dark:text-slate-100 group-hover:text-blue-700 dark:group-hover:text-blue-300 transition-colors">
                                            {emp.fullName}
                                        </span>
                                        <div className="flex gap-2 items-center">
                                            {emp.position && (
                                                <span className="text-[10px] uppercase font-black tracking-widest text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-full">
                                                    {emp.position}
                                                </span>
                                            )}
                                            {emp.phone && (
                                                <span className="text-xs font-medium text-slate-500 flex items-center gap-1">
                                                    <i className="bi bi-telephone text-[10px]" />
                                                    {emp.phone}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                    <i className="bi bi-chevron-right text-slate-300 group-hover:text-blue-500 transition-colors" />
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 shrink-0 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
                    <p className="text-[10px] text-slate-400 font-bold">
                        Clique em qualquer funcionário para selecioná-lo
                    </p>
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-red-500 transition-colors"
                    >
                        Cancelar
                    </button>
                </div>
            </div>
        </div>
    );
};

export default EmployeeSearchModal;

import React, { useState, useMemo } from "react";
import Order from '@/pages/types/order.type';
import { formatCurrency, formatToBRDate } from '@/pages/utils/formatters';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

interface OrderSelectionModalProps {
    orders: Order[];
    onSelect: (order: Order) => void;
    onClose: () => void;
    title?: string;
    subtitle?: string;
}

const OrderSelectionModal = ({ orders, onSelect, onClose, title = "Selecionar Pedido Original", subtitle = "Busque a venda que originou a assistência" }: OrderSelectionModalProps) => {
    const [searchTerm, setSearchTerm] = useState("");
    const [sortField, setSortField] = useState<"id" | "date" | "customer">("date");
    const [sortOrder, setSortOrder] = useState<"asc" | "desc">("desc");

    const filteredOrders = useMemo(() => {
        const normTerm = normalizeSearchTerm(searchTerm);
        return orders
            .filter(o => 
                normalizeSearchTerm(o.id || "").includes(normTerm) ||
                normalizeSearchTerm(o.customerData?.fullName || "").includes(normTerm)
            )
            .sort((a, b) => {
                let comparison = 0;
                if (sortField === "id") comparison = (a.id || "").localeCompare(b.id || "");
                else if (sortField === "date") comparison = (a.date || "").localeCompare(b.date || "");
                else if (sortField === "customer") comparison = (a.customerData?.fullName || "").localeCompare(b.customerData?.fullName || "");
                
                return sortOrder === "asc" ? comparison : -comparison;
            });
    }, [orders, searchTerm, sortField, sortOrder]);

    const handleSort = (field: typeof sortField) => {
        if (sortField === field) setSortOrder(sortOrder === "asc" ? "desc" : "asc");
        else {
            setSortField(field);
            setSortOrder("desc");
        }
    };

    return (
        <div className="fixed inset-0 z-[110] flex items-end sm:items-center justify-center p-0 sm:p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in" onClick={onClose}>
            <div className="bg-white dark:bg-slate-900 w-full max-w-4xl rounded-t-[2.5rem] sm:rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-slide-up border-t sm:border border-slate-100 dark:border-slate-800" style={{ height: '90vh', maxHeight: '90vh' }} onClick={e => e.stopPropagation()}>
                {/* Header */}
                <div className="px-8 py-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-950">
                    <div>
                        <h2 className="text-xl font-black text-slate-800 dark:text-slate-100 tracking-tight">{title}</h2>
                        <p className="text-[10px] uppercase font-black text-slate-400 tracking-widest mt-0.5">{subtitle}</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-full transition-colors text-slate-400">
                        <i className="bi bi-x-lg text-xl" />
                    </button>
                </div>

                {/* Filters */}
                <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex gap-4">
                    <div className="relative flex-1 group">
                        <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                        <input
                            type="text"
                            placeholder="Buscar por Código ou Nome do Cliente..."
                            value={searchTerm}
                            onChange={e => setSearchTerm(e.target.value)}
                            className="w-full pl-12 pr-4 py-3 bg-slate-100 dark:bg-slate-950 border-none rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500/20 transition-all"
                        />
                    </div>
                </div>

                {/* Table */}
                <div className="flex-1 overflow-auto custom-scrollbar p-6">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-100 dark:border-slate-800">
                                <th className="px-4 py-3 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => handleSort("id")}>
                                    ID {sortField === "id" && <i className={`bi bi-sort-${sortOrder === "asc" ? "up" : "down"}`} />}
                                </th>
                                <th className="px-4 py-3 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => handleSort("date")}>
                                    Data {sortField === "date" && <i className={`bi bi-sort-${sortOrder === "asc" ? "up" : "down"}`} />}
                                </th>
                                <th className="px-4 py-3 cursor-pointer hover:text-blue-600 transition-colors" onClick={() => handleSort("customer")}>
                                    Cliente {sortField === "customer" && <i className={`bi bi-sort-${sortOrder === "asc" ? "up" : "down"}`} />}
                                </th>
                                <th className="px-4 py-3 text-right">Valor</th>
                                <th className="px-4 py-3 text-center">Ação</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                            {filteredOrders.length > 0 ? (
                                filteredOrders.map(o => (
                                    <tr key={o.id} className="hover:bg-blue-50/50 dark:hover:bg-blue-900/10 transition-colors group">
                                        <td className="px-4 py-4 text-xs font-mono font-bold text-slate-500">#{o.id}</td>
                                        <td className="px-4 py-4 text-xs font-bold text-slate-700 dark:text-slate-300">{formatToBRDate(o.date)}</td>
                                        <td className="px-4 py-4 text-xs font-bold text-slate-800 dark:text-slate-100">{o.customerData?.fullName}</td>
                                        <td className="px-4 py-4 text-xs font-black text-blue-600 dark:text-blue-400 text-right">
                                            {formatCurrency(o.paymentsSummary?.totalOrderValue || 0)}
                                        </td>
                                        <td className="px-4 py-4 text-center">
                                            <button
                                                onClick={() => onSelect(o)}
                                                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-[10px] font-black uppercase tracking-widest rounded-xl transition-all shadow-sm active:scale-95"
                                            >
                                                Selecionar
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={5} className="py-12 text-center text-slate-400 font-bold italic">Nenhum pedido encontrado.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

