                                                                    </p>
                                                                    <p className="text-[11px] font-bold text-slate-700 dark:text-slate-200 flex justify-between">
                                                                        <span className="text-slate-400 font-black uppercase text-[8px]">Giro Mensal:</span>
                                                                        {data.x.toFixed(1)} un.
                                                                    </p>
                                                                </div>
                                                            );
                                                        }
                                                        return null;
                                                    }}
                                                />
