                                                                                                <div className="h-1 bg-slate-200 dark:bg-slate-800 rounded-full overflow-hidden">
                                                                                                    <div className="h-full bg-indigo-500" style={{ width: `${perc}%` }}></div>
                                                                                                </div>
                                                                                            </div>
                                                                                        );
                                                                                    })}
                                                                                </div>

                                                                                {/* Coluna 2: Cenário Otimista (Benchmark Q1) */}
