                                        <input 
                                            type="number" 
                                            value={maxProfit || ''} 
                                            onChange={(e) => setMaxProfit(Number(e.target.value))} 
                                            placeholder="∞" 
                                            className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl pl-9 pr-2 py-3 text-[11px] font-bold shadow-inner" 
                                        />
                                    </div>
                                </div>
                            </div>

