                                            key={opt.key}
                                            onClick={() => handleSort(opt.key)}
                                            className={`flex items-center justify-between p-4 rounded-xl border font-black text-[10px] uppercase tracking-widest transition-all ${sortConfig.key === opt.key ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-500/30' : 'bg-slate-50 dark:bg-slate-950 border-slate-100 dark:border-slate-800 text-slate-400 hover:text-indigo-600'}`}
                                        >
                                            {opt.label}
                                            {sortConfig.key === opt.key && <i className={`bi bi-sort-${sortConfig.direction === 'asc' ? 'down' : 'up'}`}></i>}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </aside>
            </main>

            <ReportConfigModal 
                isOpen={isConfigOpen} 
                onClose={() => setIsConfigOpen(false)} 
                onSave={handleUpdateReport} 
                initialConfig={reportConfig}
                initialSource={reportSource}
                initialName={reportName}
                initialExcludedItems={reportConfig?.excludedItems || []}
                availableItems={rawResults.map(r => ({ product: r.product, qty: r.totalQuantity, profit: r.totalProfit, supplier: r.supplier }))}
                loading={loading}
            />

            <ItemExclusionModal 
                isOpen={isExclusionOpen}
                onClose={() => setIsExclusionOpen(false)}
                items={allProducts.filter(i => selectedSuppliers.includes(i.supplier || 'N/A') || selectedSuppliers.length === 0)}
                initialExcludedItems={reportConfig?.excludedItems || []}
                onConfirm={(nextExcluded: string[]) => {
                    setReportConfig((prev: any) => {
                        const nextConfig = { ...prev, excludedItems: nextExcluded };
                        handleUpdateReport({ name: reportName, source: reportSource, config: nextConfig });
                        return nextConfig;
                    });
                }}
            />

            <ProductReferenceModal 
                isOpen={isReferenceOpen}
                onClose={() => setIsReferenceOpen(false)}
                availableProducts={rawResults.map(i => ({ name: i.product, supplier: i.supplier || '' }))}
            />

            {hoveredResult && (
                <div className="fixed inset-0 z-[9999] flex items-center justify-center px-6">
                    <div className="absolute inset-0 bg-slate-950/40 backdrop-blur-md animate-fade-in" onClick={handleCloseModal}></div>
                    <div 
                        className="relative bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 p-12 rounded-[4rem] shadow-2xl w-full max-w-[550px] flex flex-col gap-10 animate-scale-in"
                    >
                        <button 
                            onClick={handleCloseModal}
                            className="absolute top-8 right-8 w-12 h-12 rounded-full bg-slate-50 dark:bg-slate-800 text-slate-400 hover:text-red-500 hover:bg-red-50 transition-all flex items-center justify-center border border-slate-100 dark:border-slate-700 shadow-sm"
                        >
                            <i className="bi bi-x-lg text-lg"></i>
                        </button>

                        <div className="flex justify-between items-start pr-12">
                            <div className="flex-1">
                                <h4 className="text-[11px] font-black text-indigo-600 uppercase tracking-[0.4em] mb-4">Análise Estratégica</h4>
                                <p className="text-3xl font-black text-slate-800 dark:text-slate-100 leading-[1.1] tracking-tighter">{hoveredResult.product}</p>
                                <p className="text-sm font-bold text-slate-400 uppercase tracking-widest mt-3">{hoveredResult.supplier}</p>
                            </div>
                            <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center font-black text-3xl shadow-inner ${hoveredResult.classification === 'A' ? 'bg-blue-50 text-blue-600' : hoveredResult.classification === 'B' ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-50 text-slate-300'}`}>
                                {hoveredResult.classification}
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div className="bg-slate-50 dark:bg-slate-955 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-2">Giro Período</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-blue-500">{hoveredResult.totalQuantity} <span className="text-[10px] font-bold opacity-40 uppercase ml-1">un.</span></span>
                            </div>
                            <div className="bg-slate-50 dark:bg-slate-955 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-2">Preço de Custo</span>
                                <span className="text-2xl font-black text-amber-600">{(hoveredResult.avgCost || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                            </div>
                            <div className="bg-slate-50 dark:bg-slate-955 p-6 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-2">Giro Mensal</span>
                                <span className="text-2xl font-black text-indigo-600">{(hoveredResult.totalQuantity / (monthCount || 1)).toFixed(1)} <span className="text-[10px] font-bold opacity-40 uppercase ml-1">un.</span></span>
                            </div>
                        </div>

                        <div className="flex flex-col gap-4">
                            <div className="flex justify-between items-end py-5 border-b border-slate-100 dark:border-slate-800">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Faturamento Período</span>
                                <span className="text-xl font-black text-slate-800 dark:text-slate-100">{hoveredResult.totalRevenue.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                            </div>
                            <div className="flex justify-between items-end py-5 border-b border-slate-100 dark:border-slate-800">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Lucro Total Acumulado</span>
                                <span className="text-xl font-black text-emerald-600">{hoveredResult.totalProfit.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                            </div>
                            <div className="flex justify-between items-end p-8 bg-indigo-600 rounded-[2.5rem] shadow-2xl shadow-indigo-500/30 mt-4">
                                <span className="text-[11px] font-black text-white/70 uppercase tracking-widest">Lucro Médio/Mês</span>
                                <span className="text-2xl font-black text-white">{hoveredResult.monthlyProfit.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}</span>
                            </div>
                        </div>

                        <div className="flex items-center justify-center p-5 bg-slate-50 dark:bg-slate-955 rounded-[1.5rem] border border-slate-100 dark:border-slate-800">
                            <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">
                                Participação no Lucro Total: <span className="text-indigo-600 ml-1">{hoveredResult.accumulatedPercentage.toFixed(2)}%</span>
                            </p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ReportView;

import React, { useState, useMemo } from 'react';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

interface ItemExclusionModalProps {
    isOpen: boolean;
    onClose: () => void;
    items: any[];
    initialExcludedItems: string[];
    onConfirm: (excludedItems: string[]) => void;
}

const ItemExclusionModal: React.FC<ItemExclusionModalProps> = ({ 
    isOpen, onClose, items, initialExcludedItems, onConfirm 
}) => {
    const [localExcludedItems, setLocalExcludedItems] = useState<string[]>(initialExcludedItems);
    
    // Sincronizar estado local quando o modal abrir
    React.useEffect(() => {
        if (isOpen) {
            setLocalExcludedItems(initialExcludedItems);
        }
    }, [isOpen, initialExcludedItems]);

    const onToggleItemLocal = (productName: string) => {
        setLocalExcludedItems(prev => 
            prev.includes(productName) ? prev.filter(i => i !== productName) : [...prev, productName]
        );
    };

    const [searchTerm, setSearchTerm] = useState('');
    const [selectedSupplier, setSelectedSupplier] = useState<string>('');
    const [selectedQuadrant, setSelectedQuadrant] = useState<string>('');
    const [sortConfig, setSortConfig] = useState<{ key: string, direction: 'asc' | 'desc' }>({ key: 'qty', direction: 'desc' });

    const uniqueSuppliers = useMemo(() => {
        const suppliers = items.map(i => i.supplier).filter(Boolean);
        return Array.from(new Set(suppliers)).sort();
    }, [items]);

    const filteredAndSortedItems = useMemo(() => {
        let result = items.filter(item => {
            const matchesSearch = normalizeSearchTerm(item.product).includes(normalizeSearchTerm(searchTerm)) || 
                                   (item.supplier && normalizeSearchTerm(item.supplier).includes(normalizeSearchTerm(searchTerm)));
            const matchesSupplier = selectedSupplier ? item.supplier === selectedSupplier : true;
            
            const itemQuadrant = item.quadrant;
            const matchesQuadrant = selectedQuadrant ? String(itemQuadrant) === String(selectedQuadrant) : true;
            
            return matchesSearch && matchesSupplier && matchesQuadrant;
        });

        if (sortConfig.key) {
            result.sort((a, b) => {
                const aVal = a[sortConfig.key];
                const bVal = b[sortConfig.key];
                if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        return result;
    }, [items, searchTerm, selectedSupplier, selectedQuadrant, sortConfig]);

    const handleSort = (key: string) => {
        setSortConfig(prev => ({
            key,
            direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
        }));
    };

    if (!isOpen) return null;

    const quadrants = [
        { id: 1, label: 'Q1: Estrelas', color: 'text-emerald-500' },
        { id: 2, label: 'Q2: Potencial', color: 'text-blue-500' },
        { id: 3, label: 'Q3: Volume', color: 'text-amber-500' },
        { id: 4, label: 'Q4: Problemas', color: 'text-slate-500' },
    ];

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
            <div className="bg-white dark:bg-slate-900 w-[95vw] max-w-[1600px] h-[90vh] rounded-[3rem] shadow-2xl overflow-hidden animate-slide-up flex flex-col">
                <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white dark:bg-slate-900 sticky top-0">
                    <div className="flex flex-col">
                        <h2 className="text-xl font-black text-slate-800 dark:text-slate-100 flex items-center gap-3">
                            <i className="bi bi-filter-square-fill text-indigo-600 text-2xl"></i> Gerenciar Itens
                        </h2>
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">
                            Mostrando {filteredAndSortedItems.length} de {items.length} itens totais
                        </span>
                    </div>
                    <button onClick={onClose} className="w-10 h-10 rounded-full bg-slate-50 dark:bg-slate-950 flex items-center justify-center text-slate-500 hover:text-red-500 transition-all">
                        <i className="bi bi-x-lg text-xl"></i>
                    </button>
                </div>

                <div className="px-10 py-8 bg-slate-50 dark:bg-slate-955 border-b border-slate-100 dark:border-slate-800 flex flex-wrap gap-6 items-center">
                    <div className="flex-1 min-w-[300px] relative flex items-center">
                        <div className="absolute left-5 text-slate-400 pointer-events-none">
                            <i className="bi bi-search text-base"></i>
                        </div>
                        <input 
                            type="text" 
                            placeholder="Pesquisar itens por nome..." 
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 rounded-[1.5rem] pl-14 pr-6 py-4 text-sm font-bold text-slate-700 dark:text-slate-100 outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10 transition-all shadow-sm placeholder:text-slate-300"
                        />
                    </div>

                    <div className="w-full sm:w-64 relative">
                        <div className="absolute left-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-indigo-500 uppercase pointer-events-none">Fornecedor</div>
                        <select
                            value={selectedSupplier}
                            onChange={(e) => setSelectedSupplier(e.target.value)}
                            className="w-full bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 rounded-[1.5rem] pl-24 pr-4 py-4 text-xs font-black outline-none focus:border-indigo-500 transition-all text-slate-600 dark:text-slate-300 appearance-none cursor-pointer shadow-sm"
                        >
                            <option value="">TODOS</option>
                            {uniqueSuppliers.map(s => (
                                <option key={s as string} value={s as string}>{String(s).toUpperCase()}</option>
                            ))}
                        </select>
                        <i className="bi bi-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"></i>
                    </div>

                    <div className="w-full sm:w-64 relative">
                        <div className="absolute left-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-indigo-500 uppercase pointer-events-none">Quadrante</div>
                        <select
                            value={selectedQuadrant}
                            onChange={(e) => setSelectedQuadrant(e.target.value)}
                            className="w-full bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 rounded-[1.5rem] pl-24 pr-4 py-4 text-xs font-black outline-none focus:border-indigo-500 transition-all text-slate-600 dark:text-slate-300 appearance-none cursor-pointer shadow-sm"
                        >
                            <option value="">TODOS</option>
                            {quadrants.map(q => {
                                const count = items.filter(i => String(i.quadrant) === String(q.id)).length;
                                return (
                                    <option key={q.id} value={q.id}>
                                        {q.label.toUpperCase()} ({count})
                                    </option>
                                );
                            })}
                        </select>
                        <i className="bi bi-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"></i>
                    </div>

                    <div className="flex items-center gap-3">
                        <button 
                            onClick={() => {
                                const namesToSelect = filteredAndSortedItems.map(i => i.product);
                                // Se estamos marcando todos os FILTRADOS, devemos removê-los da lista de excluídos
                                setLocalExcludedItems(prev => prev.filter(name => !namesToSelect.includes(name)));
                            }}
                            className="px-6 py-4 bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 rounded-[1.5rem] text-[10px] font-black uppercase tracking-[0.1em] text-slate-600 hover:text-indigo-600 hover:border-indigo-200 transition-all shadow-sm flex items-center gap-2 whitespace-nowrap"
                        >
                            <i className="bi bi-check-all text-lg"></i>
                            Incluir Filtrados
                        </button>
                        <button 
                            onClick={() => {
                                const namesToExclude = filteredAndSortedItems.map(i => i.product);
                                // Se estamos limpando os FILTRADOS, devemos adicioná-los à lista de excluídos
                                setLocalExcludedItems(prev => {
                                    const next = [...prev];
                                    namesToExclude.forEach(name => {
                                        if (!next.includes(name)) next.push(name);
                                    });
                                    return next;
                                });
                            }}
                            className="px-6 py-4 bg-white dark:bg-slate-900 border-2 border-slate-200 dark:border-slate-800 rounded-[1.5rem] text-[10px] font-black uppercase tracking-[0.1em] text-slate-600 hover:text-red-600 hover:border-red-200 transition-all shadow-sm flex items-center gap-2 whitespace-nowrap"
                        >
                            <i className="bi bi-x-circle text-sm"></i>
                            Excluir Filtrados
                        </button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar">
                    <table className="w-full text-left">
                        <thead className="sticky top-0 bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 z-10">
                            <tr>
                                <th className="px-8 py-5 text-[9px] font-black uppercase tracking-widest text-slate-400 w-16">Incluir</th>
                                <th onClick={() => handleSort('product')} className="px-4 py-5 text-[9px] font-black uppercase tracking-widest text-slate-400 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors">
                                    Descrição <i className={`bi bi-sort-${sortConfig.key === 'product' ? (sortConfig.direction === 'asc' ? 'down' : 'up') : 'down-up'} ml-1 opacity-40`}></i>
                                </th>
                                <th onClick={() => handleSort('supplier')} className="px-4 py-5 text-[9px] font-black uppercase tracking-widest text-slate-400 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors">
                                    Fornecedor <i className={`bi bi-sort-${sortConfig.key === 'supplier' ? (sortConfig.direction === 'asc' ? 'down' : 'up') : 'down-up'} ml-1 opacity-40`}></i>
                                </th>
                                <th onClick={() => handleSort('qty')} className="px-4 py-5 text-[9px] font-black uppercase tracking-widest text-slate-400 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors text-right w-24">
                                    Qtd. <i className={`bi bi-sort-${sortConfig.key === 'qty' ? (sortConfig.direction === 'asc' ? 'down' : 'up') : 'down-up'} ml-1 opacity-40`}></i>
                                </th>
                                <th onClick={() => handleSort('profit')} className="px-4 py-5 text-[9px] font-black uppercase tracking-widest text-slate-400 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors text-right w-32">
                                    Lucro <i className={`bi bi-sort-${sortConfig.key === 'profit' ? (sortConfig.direction === 'asc' ? 'down' : 'up') : 'down-up'} ml-1 opacity-40`}></i>
                                </th>
                                <th onClick={() => handleSort('quadrant')} className="px-8 py-5 text-[9px] font-black uppercase tracking-widest text-slate-400 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors text-right w-24">
                                    Matriz <i className={`bi bi-sort-${sortConfig.key === 'quadrant' ? (sortConfig.direction === 'asc' ? 'down' : 'up') : 'down-up'} ml-1 opacity-40`}></i>
                                </th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                            {filteredAndSortedItems.map((item, index) => {
                                const isExcluded = localExcludedItems.includes(item.product);
                                return (
                                    <tr 
                                        key={index}
                                        onClick={() => onToggleItemLocal(item.product)}
                                        className={`hover:bg-slate-50/50 dark:hover:bg-slate-900/50 transition-all cursor-pointer ${isExcluded ? 'opacity-40 grayscale-[0.5]' : ''}`}
                                    >
                                        <td className="px-8 py-4">
                                            <div className={`w-5 h-5 rounded-md border flex items-center justify-center transition-all ${!isExcluded ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700'}`}>
                                                {!isExcluded && <i className="bi bi-check text-base"></i>}
                                            </div>
                                        </td>
                                        <td className="px-4 py-4">
                                            <p className="text-[11px] font-bold text-slate-700 dark:text-slate-200 leading-tight">{item.product}</p>
                                        </td>
                                        <td className="px-4 py-4">
                                            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{item.supplier}</p>
                                        </td>
                                        <td className="px-4 py-4 text-right">
                                            <span className="text-[11px] font-black text-slate-500">{item.qty}</span>
                                        </td>
                                        <td className="px-8 py-4 text-right text-[11px] font-black text-emerald-600">
                                            {item.profit.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                        </td>
                                        <td className="px-8 py-4 text-right">
                                            <span className={`text-[10px] font-black px-2 py-1 rounded-lg ${item.quadrant === 1 ? 'bg-emerald-50 text-emerald-600' : item.quadrant === 2 ? 'bg-blue-50 text-blue-600' : item.quadrant === 3 ? 'bg-amber-50 text-amber-600' : 'bg-slate-50 text-slate-400'}`}>
                                                Q{item.quadrant}
                                            </span>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                <div className="p-8 border-t border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900">
                    <button 
                        onClick={() => {
                            onConfirm(localExcludedItems);
                            onClose();
                        }}
                        className="w-full py-4 bg-slate-900 dark:bg-indigo-600 hover:opacity-90 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-xl shadow-indigo-500/10"
                    >
                        Concluído ({items.length - localExcludedItems.length} itens inclusos)
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ItemExclusionModal;

import React, { useState, useEffect, useMemo } from 'react';
import { supabase } from '@/pages/utils/supabaseConfig';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

interface ProductReference {
    id: string;
    master_name: string;
    reference_name: string;
}

interface ProductReferenceModalProps {
    isOpen: boolean;
    onClose: () => void;
    availableProducts: { name: string, supplier: string }[];
}

const ProductReferenceModal: React.FC<ProductReferenceModalProps> = ({ 
    isOpen, onClose, availableProducts 
}) => {
    const [references, setReferences] = useState<ProductReference[]>([]);
    const [loading, setLoading] = useState(false);
    const [newMaster, setNewMaster] = useState('');
    const [newReference, setNewReference] = useState('');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedSupplier, setSelectedSupplier] = useState<string>('');

    const uniqueSuppliers = useMemo(() => {
        const suppliers = availableProducts.map(i => i.supplier).filter(Boolean);
        return Array.from(new Set(suppliers)).sort();
    }, [availableProducts]);

    const filteredSuggestions = useMemo(() => {
        return availableProducts.filter(p => !selectedSupplier || p.supplier === selectedSupplier);
    }, [availableProducts, selectedSupplier]);

    useEffect(() => {
        if (isOpen) fetchReferences();
    }, [isOpen]);

    const fetchReferences = async () => {
        setLoading(true);
        const { data, error } = await supabase
            .from('product_references')
            .select('*')
            .order('master_name', { ascending: true });
        
        if (error) {
            console.error('Erro ao buscar referências:', error);
        } else {
            setReferences(data || []);
        }
        setLoading(false);
    };

    const handleAdd = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMaster || !newReference) return;

        setLoading(true);
        const { error } = await supabase
            .from('product_references')
            .insert([{ master_name: newMaster, reference_name: newReference }]);

        if (error) {
            alert('Erro ao adicionar referência: ' + error.message);
        } else {
            setNewReference('');
            fetchReferences();
        }
        setLoading(false);
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Deseja excluir esta referência?')) return;
        
        setLoading(true);
        const { error } = await supabase
            .from('product_references')
            .delete()
            .eq('id', id);

        if (error) {
            alert('Erro ao excluir: ' + error.message);
        } else {
            fetchReferences();
        }
        setLoading(false);
    };

    const normSearch = normalizeSearchTerm(searchTerm);
    const filteredReferences = references.filter(r => 
        normalizeSearchTerm(r.master_name).includes(normSearch) ||
        normalizeSearchTerm(r.reference_name).includes(normSearch)
    );

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
            <div className="bg-white dark:bg-slate-900 w-[95vw] max-w-[1400px] h-[90vh] rounded-[3rem] shadow-2xl overflow-hidden animate-slide-up flex flex-col">
