export default SalesOrderReportsBling;

import React from "react";
import Shipping from "../../../types/Shipping.type";
import { ValidationErrors } from "../../../utils/validations";

interface AgendamentoProps {
    scheduling: Shipping["scheduling"];
    onChangeScheduling: (key: keyof Shipping["scheduling"], value: string | Date | boolean) => void;
    errors: ValidationErrors;
    isPickup?: boolean;
    hideSchedulingShortcuts?: boolean;
    hideNotice?: boolean;
    title?: string;
}

const Agendamento = ({ scheduling, onChangeScheduling, errors, isPickup, hideSchedulingShortcuts, hideNotice, title }: AgendamentoProps) => {
    if (!scheduling) return null;
    const hasError = errors['shipping_date'] || errors['shipping_time'];
    const onScheduleChange = (key: keyof Shipping['scheduling'], value: string | Date | boolean) => {
        if (key !== 'immediatePickup') onChangeScheduling('immediatePickup', false);
        onChangeScheduling(key, value);
    };

    return (
        <div className="flex-1 flex flex-col min-w-0">
            <div className="flex items-center justify-between mb-4 ml-1">
                <label className="text-sm font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">
                    {title || (isPickup ? 'Agendamento da Retirada' : 'Agendamento da Entrega')}
                </label>
                
                {!hideSchedulingShortcuts && <div className="flex items-center gap-2">
                    <button
                        type="button"
                            onClick={() => {
                                const isPending = !scheduling.pendingScheduling;
                                onChangeScheduling("immediatePickup", false);
                                onChangeScheduling("pendingScheduling", isPending);
                            if (isPending) {
                                onChangeScheduling("date", "");
                                onChangeScheduling("startTime", "");
                                onChangeScheduling("notInformed", false);
                            }
                        }}
                        className={`px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border flex items-center gap-2 ${
                            scheduling.pendingScheduling 
                                ? 'bg-orange-500 border-orange-500 text-white shadow-lg shadow-orange-200 dark:shadow-none' 
                                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-orange-300'
                        }`}
                    >
                        <i className={`bi ${scheduling.pendingScheduling ? 'bi-clock-history' : 'bi-clock-fill'}`} />
                        {scheduling.pendingScheduling ? 'Agendamento Pendente' : 'Marcar p/ Agendar Depois'}
                    </button>

                    {isPickup && (
                        <button
                            type="button"
                            onClick={() => {
                                const now = new Date();
                                const date = now.toISOString().split('T')[0];
                                const hours = String(now.getHours()).padStart(2, '0');
                                const mins = String(now.getMinutes()).padStart(2, '0');
                                const time = `${hours}:${mins}`;
                                
                                onChangeScheduling("pendingScheduling", false);
                                onChangeScheduling("immediatePickup", true);
                                onChangeScheduling("notInformed", false);
                                onChangeScheduling("date", date);
                                onChangeScheduling("endDate", "");
                                onChangeScheduling("dateType", "fixed");
                                onChangeScheduling("type", "fixed");
                                onChangeScheduling("startTime", time);
                                onChangeScheduling("endTime", "");
                            }}
                            className="px-3 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest transition-all border bg-emerald-500 border-emerald-500 text-white shadow-sm hover:bg-emerald-600 active:scale-95 flex items-center gap-2"
                        >
                            <i className="bi bi-lightning-fill" /> Retirada Imediata
                        </button>
                    )}
                </div>}
            </div>

            <div className={`w-full transition-opacity ${scheduling.pendingScheduling ? 'opacity-90' : (hasError ? 'text-red-500' : '')}`}>
                
                {scheduling.pendingScheduling && (
                    <div className="flex items-center gap-4 py-4 px-4 bg-orange-50/50 dark:bg-orange-900/10 border border-dashed border-orange-200 dark:border-orange-800 rounded-2xl mb-6 animate-fade-in">
                        <div className="w-10 h-10 rounded-xl bg-orange-100 dark:bg-orange-900/30 flex items-center justify-center text-orange-600 dark:text-orange-400 shrink-0">
                            <i className="bi bi-clock-history text-xl" />
                        </div>
                        <div className="flex flex-col">
                            <h4 className="text-[11px] font-black text-orange-700 dark:text-orange-400 uppercase tracking-widest leading-none mb-1">Agendamento em Aberto</h4>
                            <p className="text-[9px] font-bold text-orange-600/70 dark:text-orange-500/70 uppercase leading-tight">
                                Este pedido será agendado em breve.
                            </p>
                        </div>
                    </div>
                )}

                {(!scheduling.notInformed || hideNotice) ? (
                    <div className={`flex flex-col gap-6 w-full transition-all duration-300 ${scheduling.pendingScheduling ? 'opacity-40 grayscale-[0.5] pointer-events-none' : ''}`}>
                        {/* Section 1: DATE */}
                        <div className="flex flex-col gap-3">
                            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 w-full">
                                <div className="w-full sm:w-auto min-w-[140px]">
                                    <select
                                        disabled={scheduling.pendingScheduling}
                                        className="w-full bg-transparent border-0 border-b border-slate-200 dark:border-slate-800 p-2 focus:border-blue-600 dark:focus:border-blue-500 outline-none text-sm font-bold text-slate-600 dark:text-slate-300 transition-all"
                                        value={scheduling.dateType || 'fixed'}
                                        onChange={(e) => onScheduleChange("dateType", e.target.value as any)}
                                    >
                                        <option value="fixed" className="dark:bg-slate-900">Data Fixa</option>
                                        <option value="range" className="dark:bg-slate-900">Período de Data</option>
                                    </select>
                                </div>

                                <div className="flex-1 flex flex-row items-center gap-3 relative group w-full">
                                    <div className="flex-1 relative">
                                        <input
                                            type="date"
                                            disabled={scheduling.pendingScheduling}
                                            className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm outline-none transition-colors dark:text-slate-300 ${errors['shipping_date'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 focus:border-blue-600 dark:border-slate-800 dark:focus:border-blue-500'}`}
                                            value={scheduling.date || ''}
                                            onChange={(e) => onScheduleChange("date", e.target.value)}
                                        />
                                    </div>

                                    {scheduling.dateType === 'range' && (
                                        <>
                                            <span className="text-[10px] font-black uppercase text-slate-300 dark:text-slate-500 tracking-widest shrink-0 px-1">Até</span>
                                            <div className="flex-1 relative">
                                                <input
                                                    type="date"
                                                    disabled={scheduling.pendingScheduling}
                                                    className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm outline-none transition-colors dark:text-slate-300 ${errors['shipping_date'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 focus:border-blue-600 dark:border-slate-800 dark:focus:border-blue-500'}`}
                                                    value={scheduling.endDate || ''}
                                                    onChange={(e) => onScheduleChange("endDate", e.target.value)}
                                                />
                                            </div>
                                        </>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Section 2: TIME */}
                        <div className="flex flex-col gap-3 py-4 border-t border-slate-100 dark:border-slate-800/50">
                            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 w-full py-2">
                                <div className="w-full sm:w-auto min-w-[140px]">
                                    <select
                                        disabled={scheduling.pendingScheduling}
                                        className="w-full bg-transparent border-0 border-b border-slate-200 dark:border-slate-800 p-2 focus:border-blue-600 dark:focus:border-blue-500 outline-none text-sm font-bold text-slate-600 dark:text-slate-300 transition-all"
                                        value={scheduling.type || 'fixed'}
                                        onChange={(e) => onScheduleChange("type", e.target.value as any)}
                                    >
                                        <option value="fixed" className="dark:bg-slate-900">Horário Fixo</option>
                                        <option value="range" className="dark:bg-slate-900">Período de Horário</option>
                                    </select>
                                </div>

                                <div className="flex-1 flex flex-row items-center gap-3 relative group w-full">
                                    <div className="flex-1 relative group/time">
                                        <input
                                            type="time"
                                            disabled={scheduling.pendingScheduling}
                                            className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm outline-none transition-colors dark:text-slate-300 ${errors['shipping_time'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 focus:border-blue-600 dark:border-slate-800 dark:focus:border-blue-500'}`}
                                            value={scheduling.startTime || ''}
                                            onChange={(e) => onScheduleChange("startTime", e.target.value)}
                                        />
                                    </div>

                                    {scheduling.type === 'range' && (
                                        <>
                                            <span className="text-[10px] font-black uppercase text-slate-300 dark:text-slate-500 tracking-widest shrink-0 px-1">Até</span>
                                            <div className="flex-1 relative group/time">
                                                <input
                                                    type="time"
                                                    disabled={scheduling.pendingScheduling}
                                                    className={`w-full border-b-2 bg-transparent px-3 py-2 text-sm outline-none transition-colors dark:text-slate-300 ${errors['shipping_time'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 focus:border-blue-600 dark:border-slate-800 dark:focus:border-blue-500'}`}
                                                    value={scheduling.endTime || ''}
                                                    onChange={(e) => onScheduleChange("endTime", e.target.value)}
                                                />
                                            </div>
                                        </>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="flex-1 bg-amber-50/50 dark:bg-amber-900/10 border border-dashed border-amber-200 dark:border-amber-900/30 rounded-2xl px-6 py-4 flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full bg-amber-100 dark:bg-amber-900/30 flex items-center justify-center text-amber-600 dark:text-amber-500 grow-0 shrink-0">
                            <i className="bi bi-exclamation-triangle-fill text-xl" />
                        </div>
                        <div className="flex flex-col">
                            <span className="text-xs font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest">Aviso de Agendamento</span>
                            <span className="text-[11px] font-medium text-amber-600/80 dark:text-amber-500/80 uppercase tracking-tight">
                                Data e horário não serão informados para esta {isPickup ? 'retirada' : 'entrega'}
                            </span>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Agendamento;

import React from "react";
import { NumericFormat as NumericFormatBase } from "react-number-format";
const NumericFormat = NumericFormatBase as any;
import { ValidationErrors } from "../../../utils/validations";

interface FreteDistanciaProps {
    value: number;
    distance?: number;
    routeUrl: string;
    onChangeValue: (val: number) => void;
    onChangeDistance: (val: string) => void;
    onAutoCalculateDistance?: () => void;
    isCalculatingDistance?: boolean;
    errors: ValidationErrors;
}

const FreteDistancia = ({
    value,
    distance,
    routeUrl,
    onChangeValue,
    onChangeDistance,
    onAutoCalculateDistance,
    isCalculatingDistance,
    errors
}: FreteDistanciaProps) => {
    return (
        <div className="flex flex-col gap-2.5">
            {/* Cabeçalho */}
            <div className="flex items-center justify-between gap-4">
                <span className="text-sm font-black uppercase tracking-widest text-slate-500 dark:text-slate-400">Frete & Distância</span>

                <div className="flex items-center gap-2">
                    <button
                        type="button"
                        onClick={onAutoCalculateDistance}
                        disabled={!onAutoCalculateDistance || isCalculatingDistance}
                        className="inline-flex items-center gap-1.5 rounded-lg bg-amber-500 px-2.5 py-1.5 text-[10px] font-black uppercase tracking-wider text-white shadow-sm transition-colors hover:bg-amber-600 disabled:cursor-wait disabled:opacity-60"
                        title="Consultar a rota, preencher a distância e calcular o frete automaticamente"
                    >
                        <i className="bi bi-lightning-charge-fill" aria-hidden="true" />
                        <span>Auto preencher</span>
                    </button>
                    <a
                        href={routeUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-[10px] font-black uppercase tracking-wider text-blue-600 transition-colors hover:bg-blue-50 hover:text-blue-800 dark:text-blue-400 dark:hover:bg-blue-950/30 dark:hover:text-blue-300"
                        title="Consultar a distância manualmente no Google Maps"
                    >
                        <i className="bi bi-geo-alt-fill text-xs" />
                        <span>Consultar distância manualmente</span>
                    </a>
                </div>
            </div>

            {/* Inputs de Valor do Frete e Distância KM */}
            <div className="flex h-fit flex-1 flex-row flex-wrap items-end gap-6 sm:gap-8">
                {/* Valor do Frete */}
                <div className="group relative flex w-44 max-w-full flex-none flex-col">
                    <label className="mb-1 ml-1 text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500">
                        Valor do Frete
                    </label>
                    <div className="relative">
                        <NumericFormat
                            className={`w-full border-b-2 bg-transparent py-2 pl-2 pr-2 text-sm font-bold outline-none transition-colors placeholder:text-slate-300 dark:text-slate-300 dark:placeholder:text-slate-700 ${errors['shipping_value'] ? 'border-red-500 focus:border-red-500' : 'border-slate-200 focus:border-blue-600 dark:border-slate-700 dark:focus:border-blue-500'}`}
                            value={value === 0 ? "" : value}
                            allowNegative={false}
                            thousandSeparator="."
                            prefix={"R$ "}
                            decimalScale={2}
                            decimalSeparator=","
                            onFocus={(e: any) => e.target.select()}
                            onValueChange={(values: any) => onChangeValue(values.floatValue || 0)}
                        />
                        {errors['shipping_value'] && (
                            <div className="absolute left-0 -top-8 hidden group-hover:flex items-center px-2 py-1 bg-red-500 text-white text-[10px] font-bold rounded shadow-lg z-50 whitespace-nowrap">
                                {errors['shipping_value']}
                                <div className="absolute -bottom-1 left-4 w-2 h-2 bg-red-500 rotate-45" />
                            </div>
                        )}
                    </div>
                </div>

                {/* Distância KM */}
                <div className="group relative flex w-44 max-w-full flex-none flex-col">
                        <label className="mb-1 ml-1 text-[10px] font-black uppercase tracking-wider text-slate-400 dark:text-slate-500">
                        Distância KM <span className="text-red-500" aria-hidden="true">*</span>
                    </label>
                    <div className="relative">
                        <input
                            type="text"
                            inputMode="decimal"
                            aria-label="Distância em quilômetros (obrigatória)"
                            aria-invalid={Boolean(errors['shipping_distance'])}
                            className={`w-full border-b-2 bg-transparent px-2 py-2 text-sm font-bold outline-none transition-colors placeholder:text-slate-300 focus:border-blue-600 dark:text-slate-300 dark:placeholder:text-slate-700 dark:focus:border-blue-500 ${errors['shipping_distance'] ? 'border-red-500' : 'border-slate-200 dark:border-slate-700'}`}
                            value={distance !== undefined ? distance.toString().replace('.', ',') : ''}
                            onChange={(e) => onChangeDistance(e.target.value)}
                            placeholder={isCalculatingDistance ? 'Calculando...' : 'Ex: 5,5'}
                        />
                        {isCalculatingDistance && <span className="sr-only" role="status">Calculando distância</span>}
                        {errors['shipping_distance'] && (
                            <p className="mt-1 text-[10px] font-semibold text-red-500">{errors['shipping_distance']}</p>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default FreteDistancia;

import { useState } from "react";
import { ServiceVisibilitySettings } from "../../types/service.type";
import ServiceFormModal from "./ServiceFormModal";
import ServiceTable from "./ServiceTable";
import { useServices } from "./useServices";
import type Service from "../../types/service.type";
import { normalizeSearchTerm } from "../../utils/textUtils";

type VisibilityKey = keyof ServiceVisibilitySettings;

const COLUMN_OPTIONS: { key: VisibilityKey; label: string }[] = [
    { key: "id", label: "ID" },
    { key: "description", label: "Descrição" },
    { key: "unitPrice", label: "Preço" },
];

const DEFAULT_VISIBILITY: ServiceVisibilitySettings = {
    id: true,
    description: true,
    unitPrice: true,
    actions: true,
};

const Services = () => {
    const { services, handleDelete } = useServices();

    const [searchTerm, setSearchTerm] = useState("");
    const [isFormOpen, setIsFormOpen] = useState(false);
    const [editingService, setEditingService] = useState<Service | null>(null);
    const [visibility, setVisibility] = useState<ServiceVisibilitySettings>(DEFAULT_VISIBILITY);
    const [showVisibilityMenu, setShowVisibilityMenu] = useState(false);

    const toggleColumn = (key: VisibilityKey) =>
        setVisibility((prev) => ({ ...prev, [key]: !prev[key] }));

    const openEdit = (service: Service) => {
        setEditingService(service);
        setIsFormOpen(true);
    };

    const openAdd = () => {
        setEditingService(null);
        setIsFormOpen(true);
    };

    const normSearch = normalizeSearchTerm(searchTerm);
    const filteredServices = services.filter(
        (s) =>
            normalizeSearchTerm(s.description).includes(normSearch) ||
            (s.id && normalizeSearchTerm(s.id).includes(normSearch))
    );

    return (
