                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>

                        <button
                            onClick={openAdd}
                            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-500/20 transition-all active:scale-95 flex items-center gap-2"
                        >
                            <i className="bi bi-plus-lg text-sm" />
                            <span className="hidden sm:inline">Novo Serviço</span>
                        </button>
                    </div>
                </div>
            </header>

            {/* Table */}
            <main className="flex-1 overflow-x-auto overflow-y-auto p-8 relative z-10 custom-scrollbar">
                <div className="max-w-7xl mx-auto min-w-[800px]">
                    <div className="bg-white dark:bg-slate-950 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-slate-50 dark:bg-slate-900/50 border-b border-slate-100 dark:border-slate-800">
                                    {visibility.id && (
                                        <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">
                                            ID
                                        </th>
                                    )}
                                    {visibility.description && (
                                        <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400">
                                            Descrição
                                        </th>
                                    )}
                                    {visibility.unitPrice && (
                                        <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">
                                            Preço
                                        </th>
                                    )}
                                    {visibility.actions && (
                                        <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest text-slate-400 text-center w-24">
                                            Ações
                                        </th>
                                    )}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50 dark:divide-slate-800/50">
                                <ServiceTable
                                    services={filteredServices}
                                    visibility={visibility}
                                    onEdit={openEdit}
                                    onDelete={handleDelete}
                                    searchTerm={searchTerm}
                                />
                            </tbody>
                        </table>
                    </div>
                </div>
            </main>

            <ServiceFormModal
                isOpen={isFormOpen}
                onClose={() => setIsFormOpen(false)}
                service={editingService}
            />
        </div>
    );
};

export default Services;

import React, { useState, useEffect, useRef } from "react";
import Service from "../../types/service.type";
import { saveService } from "../../utils/serviceService";
import { toast } from "react-toastify";
import CurrencyInput from '../../../components/CurrencyInput';

interface ServiceFormModalProps {
    isOpen: boolean;
    onClose: () => void;
    service?: Service | null;
}

const ServiceFormModal = ({ isOpen, onClose, service }: ServiceFormModalProps) => {
    const [loading, setLoading] = useState(false);
    const isInitialMount = useRef(true);
    
    const initialFormData: Partial<Service> = {
        description: "",
        unitPrice: 0,
        costPrice: 0,
        active: true,
    };

    const [formData, setFormData] = useState<Partial<Service>>(initialFormData);

    useEffect(() => {
        if (service) {
            setFormData(service);
        } else {
            setFormData(initialFormData);
        }
        isInitialMount.current = true;
    }, [service, isOpen]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.description) {
            toast.error("A descrição é obrigatória.");
            return;
        }

        setLoading(true);
        try {
            const dataToSave = { ...formData, isDraft: false } as Service;
            await saveService(dataToSave);
            toast.success(service ? "Serviço atualizado!" : "Serviço criado com sucesso!");
            onClose();
        } catch (error) {
            toast.error("Erro ao salvar o serviço.");
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={onClose} />
            <div className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-slide-up border border-slate-100 dark:border-slate-800 flex flex-col">
                {/* Header */}
                <div className="p-8 border-b border-slate-50 dark:border-slate-800 flex items-center justify-between shrink-0">
                    <div>
                        <h2 className="text-2xl font-black text-slate-800 dark:text-slate-100 tracking-tight">
                            {service ? "Editar Serviço" : "Novo Serviço"}
                        </h2>
                        <p className="text-[10px] uppercase font-black text-slate-400 dark:text-slate-500 tracking-widest mt-1">
                            {service ? `Editando ID: ${service.id}` : "Configure as informações detalhadas do serviço"}
                        </p>
                    </div>
                    <button onClick={onClose} className="p-2 text-slate-400 hover:text-red-500 transition-colors ml-auto">
                        <i className="bi bi-x-lg text-xl"></i>
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto custom-scrollbar p-8">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="md:col-span-2 flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Descrição do Serviço</label>
                            <input
                                type="text"
                                required
                                value={formData.description}
                                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                className="w-full px-4 py-4 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-sm font-bold dark:text-slate-100"
                                placeholder="Ex: Manutenção Preventiva"
                            />
                        </div>

                        <div className="flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Preço de Venda (R$)</label>
                            <CurrencyInput
                                value={formData.unitPrice || 0}
                                onChangeValue={(val) => setFormData({ ...formData, unitPrice: val })}
                                className="w-full px-4 py-4 bg-blue-50/50 dark:bg-blue-900/10 border border-blue-100/50 dark:border-blue-900/30 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all text-lg font-black text-blue-600 dark:text-blue-400"
                            />
                        </div>
                        <div className="flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Preço de Custo (R$)</label>
                            <CurrencyInput
                                value={formData.costPrice || 0}
                                onChangeValue={(val) => setFormData({ ...formData, costPrice: val })}
                                className="w-full px-4 py-4 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-slate-500 outline-none transition-all text-sm font-bold dark:text-slate-100"
                            />
                        </div>
                        <div className="md:col-span-2 flex items-center gap-4 bg-slate-50 dark:bg-slate-950 p-4 rounded-2xl border border-slate-100 dark:border-slate-800">
                            <div className="flex-1">
                                <h4 className="text-xs font-black uppercase tracking-widest text-slate-800 dark:text-slate-200">Status do Serviço</h4>
                                <p className="text-[10px] text-slate-400 uppercase font-bold tracking-widest">Serviços inativos não aparecem em novas vendas</p>
                            </div>
                            <div className={`w-14 h-8 rounded-full p-1 cursor-pointer transition-colors ${formData.active ? 'bg-emerald-500' : 'bg-slate-300 dark:bg-slate-700'}`} onClick={() => setFormData({ ...formData, active: !formData.active })}>
                                <div className={`w-6 h-6 bg-white rounded-full transition-transform shadow-sm ${formData.active ? 'translate-x-6' : 'translate-x-0'}`} />
                            </div>
                        </div>
                    </div>
                </form>

                <div className="p-8 border-t border-slate-50 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 flex justify-end gap-3 shrink-0">
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-6 py-3 rounded-xl font-bold text-xs uppercase tracking-widest text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 transition-all active:scale-95 border border-transparent hover:bg-slate-100 dark:hover:bg-slate-800"
                    >
                        Cancelar
                    </button>
                    <button
                        type="button"
                        onClick={handleSubmit}
                        disabled={loading}
                        className="px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-black text-xs uppercase tracking-widest shadow-xl shadow-blue-200 dark:shadow-none transition-all active:scale-95 flex items-center gap-2"
                    >
                        {loading ? (
                            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                            <i className="bi bi-check-lg" />
                        )}
                        {service ? "Salvar Alterações" : "Criar Serviço"}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ServiceFormModal;

import React, { useState } from 'react';
import { AppSettings } from '@/pages/utils/settingsService';
import { toast } from 'react-toastify';
import { compressImage } from '@/pages/utils/imageUtils';

interface AIPromptsSectionProps {
    settings: AppSettings;
    onChange: (path: string, value: any) => void;
}

const AIPromptsSection = ({ settings, onChange }: AIPromptsSectionProps) => {
    const [isCompressing, setIsCompressing] = useState(false);

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsCompressing(true);
        try {
            const base64 = await compressImage(file, { maxMB: 0.1, maxWidth: 512 });
            onChange('aiPrompts.aiAvatar', base64);
            toast.success("Foto do assistente atualizada!");
        } catch (err) {
            // Error toast handled in utility
        } finally {
            setIsCompressing(false);
        }
    };

    return (
        <div className="flex flex-col">
            <div className="p-8 bg-indigo-50/30 dark:bg-indigo-900/10 border-b border-indigo-100 dark:border-indigo-900/30">
                <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-2xl bg-indigo-500 flex items-center justify-center text-white shadow-lg shadow-indigo-200 dark:shadow-none overflow-hidden relative group">
                        {settings.aiPrompts.aiAvatar ? (
                           <img src={settings.aiPrompts.aiAvatar} alt="Avatar" className="w-full h-full object-cover" />
                        ) : (
                           <i className="bi bi-robot text-2xl"></i>
                        )}
                    </div>
                    <div>
                        <h4 className="font-black text-slate-800 dark:text-slate-100 text-lg tracking-tight uppercase">Assistente de IA</h4>
                        <p className="text-[10px] text-indigo-600 dark:text-indigo-400 font-black uppercase tracking-widest mt-0.5">Configure como a inteligência artificial interage com você</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 p-8 border-b border-slate-100 dark:border-slate-800">
                <div className="flex flex-col gap-2 shadow-sm p-4 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Nome do Assistente</label>
                    <input
                        type="text"
                        value={settings.aiPrompts.aiName}
                        onChange={(e) => onChange('aiPrompts.aiName', e.target.value)}
                        placeholder="Ex: Lizandro"
                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-2xl outline-none text-sm font-bold dark:text-slate-200"
                    />
                </div>
                <div className="flex flex-col gap-2 shadow-sm p-4 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 relative">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 dark:text-slate-500">Avatar do Assistente</label>
                    <div className="flex items-center gap-4 mt-1">
                        <div className="w-12 h-12 rounded-full bg-slate-100 dark:bg-slate-800 border-2 border-white dark:border-slate-700 shadow-sm overflow-hidden flex-shrink-0">
                            {settings.aiPrompts.aiAvatar ? (
                                <img src={settings.aiPrompts.aiAvatar} alt="Preview" className="w-full h-full object-cover" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-slate-300">
                                    <i className="bi bi-person-fill text-xl"></i>
                                </div>
                            )}
                        </div>
                        <label className="flex-1 cursor-pointer">
                            <div className={`px-4 py-3 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 rounded-2xl border-2 border-dashed border-indigo-200 dark:border-indigo-900/50 hover:bg-indigo-100 dark:hover:bg-indigo-900/30 transition-all flex items-center justify-center gap-2 text-xs font-black uppercase tracking-widest ${isCompressing ? 'opacity-50 pointer-events-none' : ''}`}>
                                {isCompressing ? (
                                    <><div className="w-3 h-3 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> Processando...</>
                                ) : (
                                    <><i className="bi bi-camera-fill text-sm"></i> Alterar Foto</>
                                )}
                            </div>
                            <input
                                type="file"
                                accept="image/*"
                                onChange={handleFileChange}
                                className="hidden"
                            />
                        </label>
                        {settings.aiPrompts.aiAvatar && (
                            <button 
                                onClick={() => onChange('aiPrompts.aiAvatar', '')}
                                className="p-3 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-colors"
                                title="Remover Foto"
                            >
                                <i className="bi bi-trash3-fill text-sm"></i>
                            </button>
                        )}
                    </div>
                </div>
            </div>

            <div className="p-8 hover:bg-slate-50/50 dark:hover:bg-slate-800/30 transition-colors border-b border-slate-100 dark:border-slate-800">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
