            >
                <div className={`w-12 h-12 rounded-2xl bg-blue-50 dark:bg-blue-900/10 flex items-center justify-center shadow-sm`}>
                    <i className={`bi bi-arrow-counterclockwise text-blue-500 text-2xl`}></i>
