    finalCost,
    effectiveMarkup,
    onChangeMarkup,
    onConfirm,
    onDiscardAndCreateNew,
}: InboundAiNewVariationModalProps) {
    const isVisible = Boolean(
        classifyingItem && classification && classification.decision === 'NEW_VARIATION_OF_EXISTING_PRODUCT'
    );

    useEffect(() => {
        if (!isVisible) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onDiscardAndCreateNew();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isVisible, onDiscardAndCreateNew]);

    if (!isVisible || !classifyingItem || !classification) {
        return null;
    }

    const numericMarkup = Number(effectiveMarkup.replace(',', '.'));
    const estimatedPrice = Number.isFinite(numericMarkup) && numericMarkup >= 0
        ? formatCurrency(finalCost * (1 + numericMarkup / 100))
        : 'Informe o acréscimo';

    return (
        <div
            className="fixed inset-0 z-[1000005] flex items-center justify-center p-4"
            role="dialog"
            aria-modal="true"
            aria-labelledby="ai-new-variation-title"
        >
            <button
                type="button"
                aria-label="Fechar confirmação de nova variação"
                onClick={onDiscardAndCreateNew}
                className="absolute inset-0 bg-slate-950/60 backdrop-blur-sm cursor-default border-0 p-0 m-0 w-full h-full"
            />
            <section className="relative w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900">
                <div className="flex items-center gap-2">
                    <i className="bi bi-diagram-2 text-indigo-500" aria-hidden="true" />
                    <h3 id="ai-new-variation-title" className="text-base font-black text-slate-800 dark:text-slate-100">
                        Nova variação em produto pai existente
                    </h3>
                </div>
                <p className="mt-3 text-sm text-slate-600 dark:text-slate-300">
                    A IA identificou que este item deve ser cadastrado como variação de um produto pai existente.
                </p>
                <div className="mt-4 space-y-1 rounded-xl bg-indigo-50 p-3 text-xs dark:bg-indigo-950/30">
                    <p className="font-bold text-slate-700 dark:text-slate-200">
                        Item da NF: {classifyingItem.productDescription}
                    </p>
                    <p className="text-slate-600 dark:text-slate-300">
                        Produto pai sugerido: <b className="text-indigo-700 dark:text-indigo-300">{classification.normalizedParentName || '—'}</b>
                    </p>
                    {classification.extractedAttributes.color && (
                        <p className="text-slate-500">Cor da nova variação: <b>{classification.extractedAttributes.color}</b></p>
                    )}
                    {classification.extractedAttributes.measure && (
                        <p className="text-slate-500">Medida: <b>{classification.extractedAttributes.measure}</b></p>
                    )}
                    {classification.extractedAttributes.material && (
                        <p className="text-slate-500">Material: <b>{classification.extractedAttributes.material}</b></p>
                    )}
                    <p className="text-slate-400">Confiança: {Math.round(classification.confidence * 100)}%</p>
                </div>
                <label className="mt-4 block text-xs font-black text-slate-600 dark:text-slate-300">
                    Acréscimo sobre o custo final (%)
                    <input
                        type="number"
                        min="0"
                        step="0.01"
                        required
                        value={effectiveMarkup}
                        onChange={(event) => onChangeMarkup(event.target.value)}
                        className="mt-1 w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-950 transition-colors"
                    />
                </label>
                <p className="mt-2 text-xs text-slate-500">
                    Custo final unitário: <b>{formatCurrency(finalCost)}</b> · Preço estimado: <b>{estimatedPrice}</b>
                </p>
                <div className="mt-5 flex justify-end gap-2">
                    <button
                        type="button"
                        onClick={onDiscardAndCreateNew}
                        className="rounded-lg px-3 py-2 text-xs font-black text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                    >
                        Criar como produto independente
                    </button>
                    <button
                        type="button"
                        onClick={onConfirm}
                        className="rounded-lg bg-indigo-600 px-3 py-2 text-xs font-black text-white hover:bg-indigo-700 transition-colors"
                    >
                        Cadastrar variação no produto pai
                    </button>
                </div>
            </section>
        </div>
    );
}

export default InboundAiNewVariationModal;

import React from 'react';
import type { InboundInvoiceItem } from '@/pages/utils/inboundNfe/inboundNfeTypes';
import type { AiClassification } from '../hooks/useInboundInvoiceClassification';
import { formatCurrency } from '@/pages/utils/formatters';
import { itemCostWithAdditionalCosts } from '@/pages/utils/inboundNfe/inboundItemCosts';

interface InboundClassificationModalsProps {
    isPreparingProduct: boolean;
    isClassifying: boolean;
    classifyingItem: InboundInvoiceItem | null;
    aiClassification: AiClassification | null;
    effectiveMarkup: string;
    onEffectiveMarkupChange: (markup: string) => void;
    onConfirmExistingVariation: () => void;
    onConfirmNewVariation: () => void;
    onDiscardAndCreateNew: () => void;
}

export const InboundClassificationModals: React.FC<InboundClassificationModalsProps> = ({
    isPreparingProduct,
    isClassifying,
    classifyingItem,
    aiClassification,
    effectiveMarkup,
    onEffectiveMarkupChange,
    onConfirmExistingVariation,
    onConfirmNewVariation,
    onDiscardAndCreateNew,
}) => {
    const finalCost = classifyingItem ? itemCostWithAdditionalCosts(classifyingItem) : 0;
    const parsedMarkup = Number(effectiveMarkup.replace(',', '.'));
    const estimatedPrice = effectiveMarkup.trim() && Number.isFinite(parsedMarkup)
        ? formatCurrency(finalCost * (1 + parsedMarkup / 100))
        : 'Informe o acréscimo';

    return (
        <>
            {/* Modal: Preparando formulário */}
            {isPreparingProduct && (
                <div className="fixed inset-0 z-[1000006] flex items-center justify-center bg-slate-950/60 p-4">
                    <section className="w-full max-w-sm rounded-2xl bg-white p-6 text-center shadow-2xl dark:bg-slate-900">
                        <i className="bi bi-arrow-repeat text-3xl text-emerald-600 animate-spin inline-block" />
                        <h3 className="mt-3 text-base font-black text-slate-800 dark:text-slate-100">Preparando formulário...</h3>
                        <p className="mt-2 text-xs text-slate-500 dark:text-slate-400">Classificando categoria e estruturando dados do produto com IA.</p>
                    </section>
                </div>
            )}

            {/* Modal: Classificando item com IA */}
            {isClassifying && classifyingItem && (
                <div className="fixed inset-0 z-[1000005] flex items-center justify-center bg-slate-950/60 p-4">
                    <section className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900 text-center">
                        <i className="bi bi-stars text-3xl text-indigo-500 animate-pulse" />
                        <h3 className="mt-3 text-base font-black text-slate-800 dark:text-slate-100">Analisando com IA...</h3>
                        <p className="mt-2 text-sm text-slate-500 dark:text-slate-400">Comparando com os produtos do fornecedor para sugerir o melhor vínculo.</p>
                        <p className="mt-3 rounded-xl bg-slate-50 p-3 text-xs font-bold text-slate-700 dark:bg-slate-950 dark:text-slate-200">{classifyingItem.productDescription}</p>
                    </section>
                </div>
            )}

            {/* Modal: EXISTING_VARIATION — confirmar vínculo com variação já existente */}
            {!isClassifying && aiClassification?.decision === 'EXISTING_VARIATION' && classifyingItem && (
                <div className="fixed inset-0 z-[1000005] flex items-center justify-center bg-slate-950/60 p-4">
                    <section className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900">
                        <div className="flex items-center gap-2">
                            <i className="bi bi-stars text-indigo-500" />
                            <h3 className="text-base font-black text-slate-800 dark:text-slate-100">Variação já existe no ERP</h3>
                        </div>
                        <p className="mt-3 text-sm text-slate-600 dark:text-slate-300">A IA identificou que este item já está cadastrado como uma variação existente.</p>
                        <div className="mt-4 space-y-1 rounded-xl bg-slate-50 p-3 text-xs dark:bg-slate-950">
                            <p className="font-bold text-slate-700 dark:text-slate-200">Item da NF: {classifyingItem.productDescription}</p>
                            <p className="text-slate-500">Produto sugerido: <b className="text-emerald-700 dark:text-emerald-300">{aiClassification.normalizedParentName || '—'}</b></p>
                            {aiClassification.extractedAttributes.color && <p className="text-slate-500">Cor detectada: <b>{aiClassification.extractedAttributes.color}</b></p>}
                            {aiClassification.extractedAttributes.measure && <p className="text-slate-500">Medida detectada: <b>{aiClassification.extractedAttributes.measure}</b></p>}
                            <p className="text-slate-400">Confiança: {Math.round(aiClassification.confidence * 100)}%</p>
                            {aiClassification.reasons.length > 0 && (
                                <ul className="mt-1 list-disc pl-4 text-slate-400">
                                    {aiClassification.reasons.map((r: string, i: number) => <li key={i}>{r}</li>)}
                                </ul>
                            )}
                        </div>
                        <div className="mt-5 flex justify-end gap-2">
                            <button
                                type="button"
                                onClick={onDiscardAndCreateNew}
                                className="rounded-lg px-3 py-2 text-xs font-black text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer"
                            >
                                Criar como produto novo
                            </button>
                            <button
                                type="button"
                                onClick={onConfirmExistingVariation}
                                className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-black text-white hover:bg-emerald-700 cursor-pointer"
                            >
                                Vincular à variação existente
                            </button>
                        </div>
                    </section>
                </div>
            )}

            {/* Modal: NEW_VARIATION_OF_EXISTING_PRODUCT — criar variação dentro do produto pai */}
            {!isClassifying && aiClassification?.decision === 'NEW_VARIATION_OF_EXISTING_PRODUCT' && classifyingItem && (
                <div className="fixed inset-0 z-[1000005] flex items-center justify-center bg-slate-950/60 p-4">
                    <section className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-900">
                        <div className="flex items-center gap-2">
                            <i className="bi bi-diagram-2 text-indigo-500" />
                            <h3 className="text-base font-black text-slate-800 dark:text-slate-100">Nova variação em produto pai existente</h3>
                        </div>
                        <p className="mt-3 text-sm text-slate-600 dark:text-slate-300">A IA identificou que este item deve ser cadastrado como variação de um produto pai existente.</p>
                        <div className="mt-4 space-y-1 rounded-xl bg-indigo-50 p-3 text-xs dark:bg-indigo-950/30">
                            <p className="font-bold text-slate-700 dark:text-slate-200">Item da NF: {classifyingItem.productDescription}</p>
                            <p className="text-slate-600 dark:text-slate-300">Produto pai sugerido: <b className="text-indigo-700 dark:text-indigo-300">{aiClassification.normalizedParentName || '—'}</b></p>
                            {aiClassification.extractedAttributes.color && <p className="text-slate-500">Cor da nova variação: <b>{aiClassification.extractedAttributes.color}</b></p>}
                            {aiClassification.extractedAttributes.measure && <p className="text-slate-500">Medida: <b>{aiClassification.extractedAttributes.measure}</b></p>}
                            {aiClassification.extractedAttributes.material && <p className="text-slate-500">Material: <b>{aiClassification.extractedAttributes.material}</b></p>}
                            <p className="text-slate-400">Confiança: {Math.round(aiClassification.confidence * 100)}%</p>
                        </div>
                        <label className="mt-4 block text-xs font-black text-slate-600 dark:text-slate-300">
                            Acréscimo sobre o custo final (%)
                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                required
                                value={effectiveMarkup}
                                onChange={(event) => onEffectiveMarkupChange(event.target.value)}
                                className="mt-1 w-full rounded-lg border px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-950"
                            />
                        </label>
                        <p className="mt-2 text-xs text-slate-500">
                            Custo final unitário: <b>{formatCurrency(finalCost)}</b> · Preço estimado: <b>{estimatedPrice}</b>
                        </p>
                        <div className="mt-5 flex justify-end gap-2">
                            <button
                                type="button"
                                onClick={onDiscardAndCreateNew}
                                className="rounded-lg px-3 py-2 text-xs font-black text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 cursor-pointer"
                            >
                                Criar como produto independente
                            </button>
                            <button
                                type="button"
                                onClick={onConfirmNewVariation}
                                className="rounded-lg bg-indigo-600 px-3 py-2 text-xs font-black text-white hover:bg-indigo-700 cursor-pointer"
                            >
                                Cadastrar variação no produto pai
                            </button>
                        </div>
                    </section>
                </div>
            )}
        </>
    );
};

import React, { useRef, useState } from 'react';
import { toast } from 'react-toastify';
import { InboundInvoice } from '@/pages/utils/inboundNfe/inboundNfeTypes';
import { InboundDuplicateKeyAlertModal } from './InboundDuplicateKeyAlertModal';
import { useInboundDocumentImport } from '../hooks/useInboundDocumentImport';
import QRScannerModal from '@/components/shared/QRScannerModal';
import { consultInvoiceByAccessKey } from '@/pages/utils/inboundNfe/services/sefazInboundSyncService';

interface InboundDocumentImportModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly onImportSuccess: (invoice: InboundInvoice) => void;
    readonly initialFile?: File | null;
}

const ACCEPTED_FILE_TYPES = 'text/xml,application/xml,.xml';

export const InboundDocumentImportModal: React.FC<InboundDocumentImportModalProps> = ({
    isOpen,
    onClose,
    onImportSuccess,
    initialFile,
}) => {
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [accessKey, setAccessKey] = useState('');
    const [isScannerOpen, setIsScannerOpen] = useState(false);
    const [isDirectSyncing, setIsDirectSyncing] = useState(false);
    const {
        isLoading,
        statusMessage,
        isDraggingFile,
        setIsDraggingFile,
        duplicateAlertOpen,
        setDuplicateAlertOpen,
        duplicateKey,
        duplicateExistingInvoice,
        handleFile,
        handleXmlString,
    } = useInboundDocumentImport({ isOpen, onClose, onImportSuccess, initialFile });

    if (!isOpen) return null;

    const handleScan = (value: string) => {
        const digits = value.replace(/\D/g, '');
        const key = digits.length === 44 ? digits : value.match(/(?:^|\D)(\d{44})(?:\D|$)/)?.[1];
        setIsScannerOpen(false);
        if (key) setAccessKey(key);
    };

    const handleDirectSefazQuery = async () => {
        const clean = accessKey.replace(/\D/g, '');
        if (clean.length !== 44) {
            toast.warn('A chave de acesso deve conter exatamente 44 dígitos.');
            return;
        }

        setIsDirectSyncing(true);
        try {
            const res = await consultInvoiceByAccessKey(clean);
            if (res.success && res.document?.xml) {
                toast.success('XML oficial obtido diretamente do Web Service SEFAZ!');
                await handleXmlString(res.document.xml);
            } else if (res.success) {
                toast.info(res.message || 'Dados da NF-e processados com sucesso no Ambiente Nacional.');
                onClose();
            } else {
                toast.error(res.message || 'Documento não localizado no Ambiente Nacional para esta chave.');
            }
        } catch (err: any) {
            toast.error(err.message || 'Erro na consulta mTLS com a SEFAZ.');
        } finally {
            setIsDirectSyncing(false);
        }
    };

    return (
        <>
            <div
                role="dialog"
                aria-modal="true"
                aria-labelledby="inbound-doc-modal-title"
                onKeyDown={(e) => {
                    if (e.key === 'Escape' && !isLoading) onClose();
                }}
                className="fixed inset-0 z-[1000002] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm animate-in fade-in"
            >
                <div className="relative w-full max-w-xl rounded-3xl bg-white shadow-2xl border border-slate-100 dark:bg-slate-900 dark:border-slate-800 animate-in zoom-in-95 duration-150 overflow-hidden">
                    {/* Header */}
                    <header className="flex items-center justify-between border-b border-slate-100 dark:border-slate-800 p-5 px-6">
                        <div>
                            <h2
                                id="inbound-doc-modal-title"
                                className="text-base font-black text-slate-800 dark:text-slate-100 flex items-center gap-2"
                            >
                                <i className="bi bi-file-earmark-arrow-up text-blue-600 text-lg" aria-hidden="true" />
                                Importar XML da NF-e
                            </h2>
                            <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                                Importe o arquivo XML da nota fiscal para conferência e entrada no estoque.
                            </p>
                        </div>
                        <button
                            type="button"
                            disabled={isLoading}
                            onClick={onClose}
                            aria-label="Fechar modal"
                            className="rounded-xl p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
                        >
                            <i className="bi bi-x-lg text-sm" aria-hidden="true" />
                        </button>
                    </header>

                    {/* Conteúdo Principal */}
                    <main className="p-6 space-y-4">
                        {/* Estado de Carregamento / Progresso */}
                        {isLoading && (
                            <div className="rounded-2xl border border-blue-100 bg-blue-50/70 p-4 dark:border-blue-900/50 dark:bg-blue-950/40 flex items-center gap-3 animate-pulse">
                                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-blue-600 text-white shadow-md">
                                    <i className="bi bi-arrow-repeat animate-spin text-xl" aria-hidden="true" />
                                </div>
                                <div className="min-w-0 flex-1">
                                    <p className="text-xs font-black text-blue-900 dark:text-blue-100">
                                        {statusMessage || 'Processando nota fiscal...'}
                                    </p>
                                    <p className="text-[11px] text-blue-700/80 dark:text-blue-300">
                                        Aguarde enquanto salvamos as informações.
                                    </p>
                                </div>
                            </div>
                        )}

                        {/* Link de Consulta e Dropzone de Arquivo XML */}
                        <div className="space-y-2.5">
                            <div className="flex flex-col gap-2 mb-4 p-4 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50">
                                <label htmlFor="accessKey" className="text-xs font-bold text-slate-700 dark:text-slate-200 flex items-center gap-2">
                                    <i className="bi bi-key text-blue-500" /> Consultar Chave de Acesso
                                </label>
                                <div className="flex items-center gap-2">
                                    <input
                                        id="accessKey"
                                        type="text"
                                        placeholder="Digite os 44 dígitos da chave de acesso..."
                                        value={accessKey}
                                        onChange={(e) => setAccessKey(e.target.value.replace(/\D/g, ''))}
                                        maxLength={44}
                                        className="flex-1 rounded-lg border border-slate-300 bg-white px-3 py-2 text-xs font-medium text-slate-700 placeholder:text-slate-400 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-100 dark:placeholder:text-slate-500"
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setIsScannerOpen(true)}
                                        aria-label="Escanear QR Code ou código de barras da chave NF-e"
                                        title="Escanear chave da NF-e"
                                        className="inline-flex h-9 w-10 shrink-0 items-center justify-center rounded-lg border border-slate-300 bg-white text-slate-600 hover:border-blue-400 hover:text-blue-600 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-300"
                                    >
                                        <i className="bi bi-upc-scan" aria-hidden="true" />
                                    </button>
                                    <button
                                        type="button"
                                        disabled={accessKey.length !== 44 || isDirectSyncing || isLoading}
                                        onClick={handleDirectSefazQuery}
                                        title="Buscar e importar NF-e diretamente pelo Web Service do Ambiente Nacional"
                                        className={`inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-xs font-bold text-white transition-all ${
                                            accessKey.length === 44 && !isDirectSyncing && !isLoading
                                                ? 'bg-blue-600 hover:bg-blue-700 cursor-pointer shadow-sm'
                                                : 'bg-slate-300 dark:bg-slate-700 cursor-not-allowed text-slate-500 dark:text-slate-400 opacity-60'
                                        }`}
                                    >
                                        <i className={`bi ${isDirectSyncing ? 'bi-arrow-repeat animate-spin' : 'bi-cloud-arrow-down-fill'}`} aria-hidden="true" />
                                        {isDirectSyncing ? 'Buscando...' : 'Buscar SEFAZ Direto'}
                                    </button>
                                    <a
                                        href={`https://www.nfe.fazenda.gov.br/portal/consultaRecaptcha.aspx?tipoConsulta=resumo&nfe=${accessKey}`}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        title="Abrir portal da SEFAZ para consulta manual no navegador (contingência)"
                                        className={`inline-flex items-center gap-1.5 rounded-lg border border-slate-300 px-3 py-2 text-xs font-bold text-slate-700 hover:bg-slate-100 dark:border-slate-700 dark:text-slate-200 dark:hover:bg-slate-800 transition-colors ${
                                            accessKey.length === 44 
                                                ? 'cursor-pointer' 
                                                : 'cursor-not-allowed text-slate-400 dark:text-slate-500 border-dashed opacity-50'
                                        }`}
                                        onClick={(e) => {
                                            if (accessKey.length !== 44) e.preventDefault();
                                        }}
                                    >
                                        <i className="bi bi-box-arrow-up-right text-[11px]" aria-hidden="true" />
                                        Consultar no Portal
                                    </a>
                                </div>
                            </div>

                            <div className="flex items-center justify-between">
                                <span className="text-xs font-semibold text-slate-600 dark:text-slate-300">
                                    Arquivo XML da NF-e
                                </span>
                            </div>

                            <input
                                ref={fileInputRef}
                                type="file"
                                accept={ACCEPTED_FILE_TYPES}
                                className="hidden"
                                onChange={(event) => void handleFile(event.target.files?.[0])}
                            />
                            <button
                                type="button"
                                disabled={isLoading}
                                onClick={() => fileInputRef.current?.click()}
                                onDragOver={(e) => {
                                    e.preventDefault();
                                    if (!isLoading) setIsDraggingFile(true);
                                }}
                                onDragLeave={() => setIsDraggingFile(false)}
                                onDrop={(e) => {
                                    e.preventDefault();
                                    setIsDraggingFile(false);
                                    void handleFile(e.dataTransfer.files?.[0]);
                                }}
                                className={`flex w-full flex-col items-center justify-center rounded-2xl border-2 border-dashed p-8 text-center transition-all cursor-pointer ${
                                    isDraggingFile
                                        ? 'border-blue-500 bg-blue-50 text-blue-700 dark:bg-blue-950/40'
                                        : 'border-slate-200 bg-slate-50/50 text-slate-600 hover:border-blue-400 hover:bg-blue-50/30 dark:border-slate-700 dark:bg-slate-950/40 dark:text-slate-300'
                                } disabled:cursor-wait disabled:opacity-60`}
                            >
                                <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-100 text-blue-600 dark:bg-blue-950/80 dark:text-blue-400 mb-3 shadow-sm">
                                    <i className="bi bi-cloud-arrow-up text-3xl" aria-hidden="true" />
                                </div>
                                <span className="text-sm font-bold text-slate-700 dark:text-slate-200">
                                    Clique para escolher ou arraste o arquivo aqui
                                </span>
                                <span className="text-xs text-slate-400 mt-1">
                                    Formato aceito: <b>XML</b> oficial da NF-e
                                </span>
                            </button>
                        </div>
                    </main>

                    {/* Footer */}
                    <footer className="flex justify-end border-t border-slate-100 dark:border-slate-800 p-4 px-6 bg-slate-50/50 dark:bg-slate-950/40">
                        <button
                            type="button"
                            disabled={isLoading}
                            onClick={onClose}
                            className="rounded-xl border border-slate-200 bg-white px-4 py-2 text-xs font-bold text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700 transition-colors cursor-pointer disabled:opacity-50"
                        >
                            Cancelar
                        </button>
                    </footer>
                </div>
            </div>

            {/* Modal de Alerta de Chave Duplicada */}
            <InboundDuplicateKeyAlertModal
                isOpen={duplicateAlertOpen}
                duplicateKey={duplicateKey}
                existingInvoice={duplicateExistingInvoice}
                onClose={() => setDuplicateAlertOpen(false)}
            />
            <QRScannerModal
                isOpen={isScannerOpen}
                onClose={() => setIsScannerOpen(false)}
                onScan={handleScan}
                title="Escanear chave da NF-e"
                accessKeyMode
            />
        </>
    );
};

