export default InventoryProductSearchModal;

import React from 'react';
import labelMdf from '../../../../../assets/label_mdf.png';
import { calculateLabelPhysicalSize } from '../utils/LabelPhysicalGeometry';
import ProductSearchInput from './ProductSearchInput';


interface LabelQueueProps {
    labelItems: any[];
    setLabelItems: React.Dispatch<React.SetStateAction<any[]>>;
    printingMode: 'simple' | 'advanced';
    config: any;
    products?: any[];
    onSelectProduct?: (index: number, product: any) => void;
    selectedCategory?: string | null;
}

const LabelQueue: React.FC<LabelQueueProps> = ({ 
    labelItems, 
    setLabelItems, 
    printingMode,
    config,
    products = [],
    onSelectProduct,
    selectedCategory
}) => {
    const [dragOverIdx, setDragOverIdx] = React.useState<number | null>(null);
    const labelPhysicalSize = calculateLabelPhysicalSize(config || {});
    const isPriceQueue = selectedCategory === 'precos';
    
    const updateItem = (idx: number, updates: any) => {
        const newItems = [...labelItems];
        newItems[idx] = { ...newItems[idx], ...updates };
        setLabelItems(newItems);
    };

    const updateExtraField = (itemIdx: number, fieldId: string, value: string) => {
        const newItems = [...labelItems];
        const item = { ...newItems[itemIdx] };
        if (item.extraFields) {
            item.extraFields = item.extraFields.map((f: any) => 
                f.id === fieldId ? { ...f, text: value } : f
            );
            newItems[itemIdx] = item;
            setLabelItems(newItems);
        }
    };

    const removeItem = (idx: number) => {
        setLabelItems(prev => prev.filter((_, i) => i !== idx));
    };

    const handleDragStart = (e: React.DragEvent, index: number) => {
        e.dataTransfer.setData('text/plain', index.toString());
        e.dataTransfer.effectAllowed = 'move';
    };

    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault();
        if (dragOverIdx !== index) {
            setDragOverIdx(index);
        }
    };

    const handleDragLeave = () => {
        setDragOverIdx(null);
    };

    const handleDrop = (e: React.DragEvent, targetIndex: number) => {
        e.preventDefault();
        setDragOverIdx(null);
        const sourceIndexStr = e.dataTransfer.getData('text/plain');
        if (sourceIndexStr) {
            const sourceIndex = parseInt(sourceIndexStr, 10);
            if (sourceIndex !== targetIndex && sourceIndex >= 0 && sourceIndex < labelItems.length) {
                const newItems = [...labelItems];
                const [movedItem] = newItems.splice(sourceIndex, 1);
                newItems.splice(targetIndex, 0, movedItem);
                setLabelItems(newItems);
            }
        }
    };

    if (labelItems.length === 0) {
        return (
            <div className="py-8 flex flex-col items-center justify-center text-slate-400 dark:text-slate-500">
                <i className="bi bi-tags text-4xl mb-4 opacity-50" />
                <p className="text-xs font-black uppercase tracking-widest text-center">
                    Nenhuma etiqueta adicionada
                </p>
                <p className="text-[10px] font-bold text-center mt-2 max-w-[200px] leading-relaxed opacity-80">
                    Busque um produto acima para começar a montar a impressão.
                </p>
            </div>
        );
    }

    return (
        <div className="flex flex-col gap-3">
            {labelItems.map((item, idx) => (
                <div
                    key={idx} 
                    draggable={true}
                    onDragStart={(e) => handleDragStart(e, idx)}
                    onDragOver={(e) => handleDragOver(e, idx)}
                    onDragLeave={handleDragLeave}
                    onDrop={(e) => handleDrop(e, idx)}
                    className={`group relative w-full ${isPriceQueue ? 'max-w-none min-h-[132px] flex items-center' : 'max-w-2xl flex items-center'} bg-white dark:bg-slate-900 rounded-[1.75rem] p-3 transition-all duration-300 gap-3 ${
                        'cursor-grab active:cursor-grabbing'
                    } ${
                        dragOverIdx === idx 
                            ? 'border-2 border-dashed border-blue-500 bg-blue-500/5 scale-[1.01] z-10' 
                            : ''
                    }`}
                >
                    <div className="flex items-center gap-2 shrink-0">
                        <div className="text-slate-350 dark:text-slate-650 hover:text-slate-450 px-1 py-2 flex items-center justify-center pointer-events-none select-none">
                            <i className="bi bi-grip-vertical text-base opacity-60" />
                        </div>
                        {isPriceQueue && (
                            <div className="flex flex-col items-center gap-1">
                                <span className="text-[7px] font-black uppercase tracking-wider text-slate-400">Imagem / Produto</span>
                                <button
                                    type="button"
                                    onClick={() => updateItem(idx, item.printingMode === 'advanced'
                                        ? { printingMode: 'simple', image: '', isBlank: true, name: '', price: '', promoPrice: '', sku: '' }
                                        : { printingMode: 'advanced', image: '', isBlank: true, name: '', price: '', promoPrice: '', sku: '' }
                                    )}
                                    aria-pressed={item.printingMode === 'advanced'}
                                    className={`relative h-5 w-10 shrink-0 overflow-hidden rounded-full p-0.5 transition-colors ${item.printingMode === 'advanced' ? 'bg-emerald-500' : 'bg-blue-600'}`}
                                    title={item.printingMode === 'advanced' ? 'Modo produto' : 'Modo imagem'}
                                >
                                    <span className={`absolute inset-y-0.5 left-0.5 w-4 rounded-full bg-white shadow-sm transition-transform ${item.printingMode === 'advanced' ? 'translate-x-5' : 'translate-x-0'}`} />
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Miniatura Interativa */}
                    {selectedCategory !== 'identificacao' && (!isPriceQueue || item.printingMode !== 'advanced') && (
                        <div className="flex flex-col gap-2 items-center">
                            <div
                                className={`relative shrink-0 rounded-[1.25rem] bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 flex items-center justify-center overflow-hidden p-1.5 group/thumb shadow-inner ${isPriceQueue ? 'w-32 sm:w-36' : 'w-16 h-16'}`}
                                style={isPriceQueue ? { aspectRatio: `${labelPhysicalSize.widthMm} / ${labelPhysicalSize.heightMm}` } : undefined}
                            >
                                {item.isBlank && !item.image ? (
                                    <div className="w-full h-full rounded-lg flex items-center justify-center bg-blue-600" />
                                ) : (
                                    <img 
                                        src={item.image || labelMdf} 
                                        style={{ 
                                            transform: `scale(${item.scale || 1}) rotate(${item.rotation || 0}deg)`,
                                            objectFit: item.imageFit || 'contain'
                                        }} 
                                        className="max-w-full max-h-full transition-all duration-500" 
                                        alt="" 
                                    />
                                )}
                                {item.isBlank ? (
                                    <div className="absolute inset-0 bg-blue-600/90 backdrop-blur-sm flex items-center justify-center p-2">
                                        <label className="w-full h-full flex items-center justify-center text-white rounded-xl cursor-pointer hover:bg-blue-500/40 active:scale-95 transition-all">
                                            <i className="bi bi-image text-xl" aria-label="Selecionar imagem" />
                                            <input
                                                type="file"
                                                accept="image/*"
                                                className="hidden"
                                                onChange={(e) => {
                                                    const file = e.target.files?.[0];
                                                    if (file) {
                                                        const reader = new FileReader();
                                                        reader.onload = (ev) => updateItem(idx, { image: ev.target?.result as string, isBlank: false, printingMode: 'simple' });
                                                        reader.readAsDataURL(file);
                                                    }
                                                    e.target.value = '';
                                                }}
                                            />
                                        </label>
                                    </div>
                                ) : (
                                    <div className="absolute inset-0 bg-blue-600/90 backdrop-blur-sm opacity-0 group-hover/thumb:opacity-100 flex flex-col items-center justify-center gap-2 transition-all p-2">
                                        <label className="w-full text-center py-1.5 bg-white text-blue-600 rounded-xl text-[8px] font-black uppercase cursor-pointer hover:scale-105 active:scale-95 transition-all shadow-lg">
                                            Trocar Imagem
                                            <input 
                                                type="file" accept="image/*" className="hidden" 
                                                onChange={(e) => {
                                                    const file = e.target.files?.[0];
                                                    if (file) {
                                                        const reader = new FileReader();
                                                        reader.onload = (ev) => updateItem(idx, { image: ev.target?.result as string });
                                                        reader.readAsDataURL(file);
                                                    }
                                                }} 
                                            />
                                        </label>
                                    </div>
                                )}
                            </div>

                            {!isPriceQueue && !item.isBlank && (item.productImages?.length > 0 || item.parentImages?.length > 0) && (() => {
                                const allImages = [...(item.productImages || []), ...(item.parentImages || [])];
                                if (allImages.length <= 1) return null;
                                const currentIndex = item.currentImageIndex || 0;
                                return (
                                    <div className="flex items-center gap-1 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg px-1 py-0.5 shadow-sm mt-[-4px]">
                                        <button 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                const newIndex = (currentIndex - 1 + allImages.length) % allImages.length;
                                                updateItem(idx, { currentImageIndex: newIndex, image: allImages[newIndex].image_url });
                                            }}
                                            className="text-slate-400 hover:text-blue-500 p-0.5"
                                        >
                                            <i className="bi bi-chevron-left text-[10px]" />
                                        </button>
                                        <span className="text-[9px] font-bold text-slate-500 select-none min-w-[20px] text-center">
                                            {currentIndex + 1}/{allImages.length}
                                        </span>
                                        <button 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                const newIndex = (currentIndex + 1) % allImages.length;
                                                updateItem(idx, { currentImageIndex: newIndex, image: allImages[newIndex].image_url });
                                            }}
                                            className="text-slate-400 hover:text-blue-500 p-0.5"
                                        >
                                            <i className="bi bi-chevron-right text-[10px]" />
                                        </button>
                                    </div>
                                );
                            })()}
                        </div>
                    )}

                    <div className="flex-1 flex flex-col gap-3 min-w-0">
                        {/* CABEÇALHO DO ITEM (Produto / SKU) e AÇÕES (Qtd / Lixeira) */}
                        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                            {/* Nome e SKU */}
                            <div className="min-w-0 flex-1">
                        {item.isBlank ? (
                                    (selectedCategory === 'precos' && item.printingMode === 'advanced') || selectedCategory === 'identificacao' ? (
                                        <ProductSearchInput
                                            products={products}
                                            selectedProduct={null}
                                            onSelectProduct={(product) => product && onSelectProduct?.(idx, product)}
                                            placeholder="Buscar produto ou SKU..."
                                            hideIcon
                                        />
                                    ) : selectedCategory === 'precos' ? null : (
                                        <>
                                            <label className="text-[8px] font-black uppercase text-slate-400 mb-0.5 block tracking-widest">
                                                Espaçador
                                            </label>
                                            <h4 className="text-[11px] font-black text-slate-800 dark:text-white uppercase truncate tracking-tighter">
                                                Etiqueta Em Branco
                                            </h4>
                                        </>
                                    )
                                ) : (
                                    <>
                                        <h4 className="text-xs font-black text-slate-800 dark:text-slate-100 uppercase truncate" title={item.name || 'Produto sem nome'}>
                                            {item.name || 'Produto sem nome'}
                                        </h4>
                                        <div className="flex items-center gap-2 mt-1">
                                            {selectedCategory !== 'precos' && (item.sku || item.code) && (
                                                <div className="flex items-center gap-1.5">
                                                    <span className="text-[8px] font-black uppercase tracking-widest text-slate-400">SKU</span>
                                                    <span className="text-[10px] text-slate-600 dark:text-slate-300 font-bold truncate uppercase tracking-wide bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded">
                                                        {item.sku || item.code}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    </>
                                )}
                            </div>
                            
                            {/* Quantidade e Lixeira */}
                            <div className="flex items-center gap-2 shrink-0 self-end sm:self-auto">
                                <div className="flex items-center gap-1 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-lg px-1.5 py-1 shrink-0">
                                    <span className="text-[9px] font-black text-slate-400 mr-1 uppercase hidden md:inline">Qtd</span>
                                    <button onClick={() => updateItem(idx, { quantity: Math.max(1, (item.quantity || 1) - 1) })} className="text-slate-500 hover:text-blue-500 w-5 h-5 flex items-center justify-center bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded shadow-sm"><i className="bi bi-dash" /></button>
                                    <input 
                                        type="number" 
                                        value={item.quantity || 1}
                                        onChange={e => updateItem(idx, { quantity: Math.max(1, parseInt(e.target.value) || 1) })}
                                        className="w-8 bg-transparent text-center text-xs font-black outline-none text-slate-700 dark:text-slate-200"
                                    />
                                    <button onClick={() => updateItem(idx, { quantity: (item.quantity || 1) + 1 })} className="text-slate-500 hover:text-blue-500 w-5 h-5 flex items-center justify-center bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded shadow-sm"><i className="bi bi-plus" /></button>
                                </div>

                                <button 
                                    onClick={() => removeItem(idx)}
                                    className="w-8 h-8 rounded-lg bg-white dark:bg-slate-900 text-slate-400 hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition-all flex items-center justify-center border border-slate-200 dark:border-slate-800 shrink-0 shadow-sm"
                                    title="Remover item"
                                >
                                    <i className="bi bi-trash3-fill text-sm" />
                                </button>
                            </div>
                        </div>

                        {/* OPÇÕES DE LOGO / IMAGEM LIVRE (Zoom) */}
                        {selectedCategory === 'logos' && !item.isBlank && item.printingMode === 'simple' && (
                            <div className="pt-2 border-t border-slate-100 dark:border-slate-800 mt-1">
                                <div className="flex items-center gap-2 w-max bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-lg px-1.5 py-1">
                                    <span className="text-[8px] font-black uppercase tracking-widest text-slate-400 mr-1 hidden md:inline">Escala</span>
                                    <button 
                                        onClick={() => updateItem(idx, { scale: Math.max(0.1, parseFloat(((item.scale || 1) - 0.05).toFixed(2))) })}
                                        className="w-5 h-5 rounded bg-white dark:bg-slate-900 border border-slate-200 shadow-sm flex items-center justify-center text-slate-500 hover:text-blue-500"
                                    >
                                        <i className="bi bi-dash text-xs" />
                                    </button>
                                    <input 
                                        type="number" step="5" min="10" max="2000"
                                        value={Math.round((item.scale || 1) * 100)}
                                        onChange={e => updateItem(idx, { scale: Math.max(0.1, Math.min(20, (parseFloat(e.target.value) || 100) / 100)) })}
                                        className="w-10 bg-transparent text-[10px] font-black outline-none text-center"
                                    />
                                    <span className="text-[9px] font-black text-slate-400">%</span>
                                    <button 
                                        onClick={() => updateItem(idx, { scale: Math.min(20, parseFloat(((item.scale || 1) + 0.05).toFixed(2))) })}
                                        className="w-5 h-5 rounded bg-white dark:bg-slate-900 border border-slate-200 shadow-sm flex items-center justify-center text-slate-500 hover:text-blue-500"
                                    >
                                        <i className="bi bi-plus text-xs" />
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            ))}
        </div>
    );
};

export default LabelQueue;

import React, { useState, useEffect, useRef } from 'react';
import Product from '@/pages/types/product.type';
import { supabase } from '@/pages/utils/supabaseConfig';
import { processProductData } from '../utils/LabelUtils';
import { getSelectedProductDisplayName } from '@/pages/utils/productVariationDefaults';

const LABEL_PRODUCT_COLUMNS = 'id, name, description, code, unit_price, cost_price, price, promo_price, stock, active, deleted_at, has_variations, category, unit, images, is_combo';
const LABEL_VARIATION_COLUMNS = `id, product_id, name, description, sku, price, promo_price, stock, image_url, active,
    products(${LABEL_PRODUCT_COLUMNS})`;

interface ProductSearchInputProps {
    products: Product[];
    selectedProduct?: Product | null;
    onSelectProduct: (product: Product | null) => void;
    placeholder?: string;
    className?: string;
    hideIcon?: boolean;
}

export const ProductSearchInput: React.FC<ProductSearchInputProps> = ({
    products,
    selectedProduct = null,
    onSelectProduct,
    placeholder = "Digite para buscar produto...",
    className = "",
    hideIcon = false
}) => {
    const normalizeSearchText = (value: unknown) => String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLocaleLowerCase('pt-BR');

    // A sintaxe do filtro `or` do PostgREST usa vírgulas e parênteses como
    // separadores. Removê-los do termo evita que uma busca comum quebre a consulta.
    const getSafeSearchTerm = (value: string) => value.trim().replace(/[(),]/g, ' ').replace(/[%_]/g, '');

    const buildProductSearchFilter = (term: string) =>
        `name.ilike.%${term}%,description.ilike.%${term}%,code.ilike.%${term}%`;

    const buildVariationSearchFilter = (term: string) =>
        `name.ilike.%${term}%,description.ilike.%${term}%,sku.ilike.%${term}%`;

    // Retorna o Título/Nome do produto priorizando title, name e description
    const getProductTitle = (p?: Product | null) => {
        if (!p) return '';
        return p.title || p.name || p.description || '';
    };

    const [isOpen, setIsOpen] = useState(false);
    const [filterText, setFilterText] = useState(getProductTitle(selectedProduct));
    const [dbSearchResults, setDbSearchResults] = useState<Product[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [dropdownMaxHeight, setDropdownMaxHeight] = useState(288);
    const containerRef = useRef<HTMLDivElement>(null);
    const searchTimeoutRef = useRef<number | null>(null);

    useEffect(() => {
        if (!selectedProduct) {
            setFilterText('');
        } else {
            setFilterText(getProductTitle(selectedProduct));
        }
    }, [selectedProduct]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // O painel de resultados ocupa todo o espaço livre abaixo da busca. Assim,
    // listas grandes rolam dentro dele sem ficar escondidas pela tela.
    useEffect(() => {
        if (!isOpen) return;

        const updateDropdownHeight = () => {
            const bottom = containerRef.current?.getBoundingClientRect().bottom;
            if (bottom === undefined) return;
            setDropdownMaxHeight(Math.max(0, window.innerHeight - bottom - 16));
        };

        updateDropdownHeight();
        window.addEventListener('resize', updateDropdownHeight);
        window.addEventListener('scroll', updateDropdownHeight, true);
        return () => {
            window.removeEventListener('resize', updateDropdownHeight);
            window.removeEventListener('scroll', updateDropdownHeight, true);
        };
    }, [isOpen]);

    // BUSCA AO VIVO NO SUPABASE POR TÍTULO, NOME, CÓDIGO, SKU OU DESCRIÇÃO
    useEffect(() => {
        if (!filterText.trim() || filterText.trim().length < 2) {
            setDbSearchResults([]);
            setIsLoading(false);
            return;
        }

        if (searchTimeoutRef.current) {
            clearTimeout(searchTimeoutRef.current);
        }

        searchTimeoutRef.current = window.setTimeout(async () => {
            setIsLoading(true);
            try {
                const term = getSafeSearchTerm(filterText);
                if (!term) {
                    setDbSearchResults([]);
                    return;
                }

                // A busca anterior incluía `variations::text` na tabela products.
                // Em instalações onde as variações ficam na tabela própria, esse
                // filtro invalida toda a pesquisa. Agora cada fonte é consultada
                // com os seus campos reais, inclusive o SKU da variação.
                const productsQuery = supabase
                    .from('products')
                    .select(LABEL_PRODUCT_COLUMNS)
                    .is('deleted_at', null)
                    .or('is_combo.eq.false,is_combo.is.null')
                    .or(buildProductSearchFilter(term))
                    .limit(50);

                const variationsQuery = supabase
                    .from('product_variations')
                    .select(LABEL_VARIATION_COLUMNS)
                    .is('merged_to_variation_id', null)
                    .or(buildVariationSearchFilter(term))
                    .limit(50);

                const [productsResponse, variationsResponse] = await Promise.all([productsQuery, variationsQuery]);

                if (productsResponse.error) {
                    console.error('Erro no Supabase ao buscar produtos:', productsResponse.error);
                }
                if (variationsResponse.error) {
                    console.error('Erro no Supabase ao buscar variações:', variationsResponse.error);
                }

                // Extrai as variações filhas do produto pai e descarta o próprio pai caso ele tenha variações
                const productResults = processProductData(productsResponse.data || [])
                    .filter((p: any) => !p.isParent);
                const variationResults = (variationsResponse.data || []).flatMap((variation: any) => {
                    const parent = variation.products;
                    if (!parent) return [];
                    const variationTitle = variation.name || variation.description || variation.sku || '';
                    const title = getSelectedProductDisplayName(parent, variation) || variationTitle;

                    return [{
                        ...parent,
                        id: variation.id,
                        variationId: variation.id,
                        sku: variation.sku || parent.sku || parent.code,
                        title,
                        description: title,
                        variationName: variationTitle,
                        unitPrice: variation.price ?? variation.unit_price ?? parent.unit_price ?? parent.unitPrice ?? 0,
                        promoPrice: variation.promo_price ?? variation.promoPrice ?? parent.promo_price ?? parent.promoPrice,
                        stock: variation.stock ?? parent.stock,
                        images: variation.images || variation.image_url ? (variation.images || [variation.image_url]) : parent.images,
                        parentImages: parent.images || [],
                        isVariation: true,
                        parentId: parent.id,
                    } as Product];
                });

                const resultMap = new Map<string, Product>();
                [...productResults, ...variationResults].forEach(product => {
                    if (product.id) resultMap.set(String(product.id), product);
                });
                setDbSearchResults(Array.from(resultMap.values()));
            } catch (err) {
                console.error("Erro na busca de produtos:", err);
            } finally {
                setIsLoading(false);
            }
        }, 200);

        return () => {
            if (searchTimeoutRef.current) {
                clearTimeout(searchTimeoutRef.current);
            }
        };
    }, [filterText]);

    // COMBINA OS PRODUTOS DA PROP LOCAL COM OS RESULTADOS AO VIVO DO BANCO DE DADOS
    const combinedProducts = React.useMemo(() => {
        const term = normalizeSearchText(filterText.trim());
        
        if (term.length < 2) {
            return [];
        }

        // 1. Filtrar lista local por título, nome, código ou SKU
        const localFiltered = (products || []).filter(p => {
            const pTitle = normalizeSearchText(getProductTitle(p));
            const pCode = normalizeSearchText(p.code);
            const pSku = normalizeSearchText(p.sku);
            const pDesc = normalizeSearchText(p.description);
            const pCat = normalizeSearchText(p.category);
            return pTitle.includes(term) || pDesc.includes(term) || pCode.includes(term) || pSku.includes(term) || pCat.includes(term);
        });

        // 2. Combinar com resultados remotos do Supabase evitando duplicatas por ID
        const map = new Map<string, Product>();
        localFiltered.forEach(p => { if (p.id) map.set(String(p.id), p); });
        dbSearchResults.forEach(p => { if (p.id) map.set(String(p.id), p); });

        return Array.from(map.values());
    }, [products, dbSearchResults, filterText]);

    const formatCurrency = (val: number | string | undefined) => {
        if (!val) return 'R$ 0,00';
        const num = typeof val === 'string' ? parseFloat(val.replace(',', '.')) : val;
        if (isNaN(num)) return 'R$ 0,00';
        return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    };

    return (
        <div ref={containerRef} className={`relative flex-1 ${className}`}>
            <div className="flex items-center gap-3 w-full px-2 py-2 bg-transparent border-b-2 border-slate-200 dark:border-slate-800 focus-within:border-blue-500 transition-colors cursor-text min-w-[240px]">
                {!hideIcon && (
                    <span className="w-6 h-6 rounded-xl flex items-center justify-center shrink-0">
                        {isLoading ? (
                            <i className="bi bi-arrow-repeat text-xs animate-spin text-blue-500" />
                        ) : (
                            <i className="bi bi-search text-xs text-slate-400" />
                        )}
                    </span>
                )}

                <div className="flex flex-col min-w-0 flex-1">
                    <input
                        type="text"
                        value={filterText}
                        onChange={(e) => {
                            setFilterText(e.target.value);
                            setIsOpen(true);
                        }}
                        onFocus={() => setIsOpen(true)}
                        placeholder={placeholder}
                        className="bg-transparent border-0 p-0 focus:ring-0 text-sm font-medium text-slate-800 dark:text-slate-100 placeholder:text-slate-400 outline-none w-full truncate"
                    />
                </div>

                {filterText && (
                    <button
                        type="button"
                        onClick={(e) => {
                            e.stopPropagation();
                            setFilterText('');
                            onSelectProduct(null);
                            setIsOpen(true);
                        }}
                        className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-1 transition-colors"
                        title="Limpar busca"
                    >
                        <i className="bi bi-x-circle-fill text-sm" />
                    </button>
                )}
            </div>

            {/* Dropdown Popover Modal filtrado */}
            {isOpen && (
                <div
                    className="absolute top-[calc(100%+6px)] left-0 right-0 z-[1000] bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl overflow-y-auto custom-scrollbar p-1.5 animate-slide-up"
                    style={{ maxHeight: dropdownMaxHeight }}
                >
                    {filterText.trim().length > 0 && filterText.trim().length < 2 ? (
                        <div className="p-4 text-center">
                            <span className="text-xs font-medium text-slate-400 block">Digite pelo menos 2 caracteres para buscar...</span>
                        </div>
                    ) : isLoading && combinedProducts.length === 0 ? (
                        <div className="p-4 text-center text-slate-400 text-xs font-bold flex items-center justify-center gap-2">
                            <i className="bi bi-arrow-repeat animate-spin text-sm text-blue-500" />
                            <span>Buscando produtos no banco de dados...</span>
                        </div>
                    ) : combinedProducts.length > 0 ? (
                        <div className="flex flex-col gap-0.5">
                            {combinedProducts.slice(0, 50).map((p) => {
                                const isSelected = selectedProduct?.id === p.id;
                                const title = getProductTitle(p);
                                const priceText = formatCurrency(p.unitPrice || (p as any).unit_price || (p as any).price);
                                
                                return (
                                    <button
                                        key={p.id}
                                        type="button"
                                        onClick={() => {
                                            setFilterText('');
                                            setDbSearchResults([]);
                                            onSelectProduct(p);
                                            setIsOpen(false);
                                        }}
                                        className={`flex items-center justify-between p-3 rounded-xl transition-all text-left w-full cursor-pointer ${
                                            isSelected 
                                                ? 'bg-blue-50 dark:bg-blue-950/40 text-blue-600 dark:text-blue-400 font-bold' 
                                                : 'hover:bg-slate-50 dark:hover:bg-slate-800/60 text-slate-700 dark:text-slate-200'
                                        }`}
                                    >
                                        <div className="flex items-center gap-3 min-w-0">
                                            <div className="flex flex-col min-w-0">
                                                <span className="text-xs font-black uppercase truncate">{title}</span>
                                                <div className="flex items-center gap-2 text-[9px] font-bold text-slate-400 uppercase tracking-tight">
                                                    {(p.sku || p.code) && (
                                                        <span className="bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded text-slate-500">
                                                            SKU: {p.sku || p.code}
                                                        </span>
                                                    )}
                                                    {p.category && <span>&bull; {p.category}</span>}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-3 shrink-0 ml-2">
                                            <span className="text-xs font-black text-emerald-600 dark:text-emerald-400">
                                                {priceText}
                                            </span>
                                            {isSelected && <i className="bi bi-check-lg text-blue-600 dark:text-blue-400 text-base" />}
                                        </div>
                                    </button>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="p-4 text-center">
                            <span className="text-xs font-medium text-slate-400 block mb-1">Nenhum produto encontrado com "{filterText}"</span>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default ProductSearchInput;

import React, { useState } from 'react';
import { toast } from 'react-toastify';

const BOOTSTRAP_ICONS_URL = "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css";
const GOOGLE_FONTS_URL = "https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&family=Montserrat:wght@400;700;900&family=Oswald:wght@400;700&family=Roboto:wght@400;700;900&family=Playfair+Display:wght@400;700;900&family=Bebas+Neue&family=Libre+Barcode+128&display=swap";

import type { GridModel as BaseGridModel } from '../types/LabelGridModelTypes';


// Este modal mantém campos adicionais de composição usados pelos modelos legados.
// O tipo-base continua centralizado em gridModel; aqui só declaramos a extensão
// específica do editor para preservar os modelos já salvos.
export interface GridModel extends BaseGridModel {
    priceFormat?: 'split' | 'standard';
    priceSymbolPosX?: number; priceSymbolPosY?: number;
    priceSymbolFontSize?: number; priceSymbolBold?: boolean; priceSymbolColor?: string;
    priceDecimalsPosX?: number; priceDecimalsPosY?: number;
    priceDecimalsFontSize?: number; priceDecimalsBold?: boolean; priceDecimalsColor?: string;
    oldPriceFontSize?: number; oldPriceColor?: string; oldPriceBold?: boolean;
    oldPriceAlign?: 'left' | 'center' | 'right'; oldPriceVAlign?: 'top' | 'middle' | 'bottom';
    oldPricePosX?: number; oldPricePosY?: number; oldPriceWidth?: number; oldPriceHeight?: number;
    promoNamePosX?: number; promoNamePosY?: number; promoNameFontSize?: number;
    promoNameAlign?: 'left' | 'center' | 'right'; promoNameVAlign?: 'top' | 'middle' | 'bottom';
    promoNameColor?: string; promoNameBold?: boolean; promoNameWidth?: number; promoNameHeight?: number;
    promoNameBgColor?: string;
    promoBarcodePosX?: number; promoBarcodePosY?: number;
    // Split Price Promoção
    promoPriceSymbolPosX?: number; promoPriceSymbolPosY?: number;
    promoPriceSymbolFontSize?: number; promoPriceSymbolBold?: boolean; promoPriceSymbolColor?: string;
    promoPriceDecimalsPosX?: number; promoPriceDecimalsPosY?: number;
    promoPriceDecimalsFontSize?: number; promoPriceDecimalsBold?: boolean; promoPriceDecimalsColor?: string;
    promoPriceFontSize?: number; promoPriceBold?: boolean; promoPriceColor?: string;
    promoPriceAlign?: 'left' | 'center' | 'right'; promoPriceVAlign?: 'top' | 'middle' | 'bottom';
    // Áreas de Segurança
    nameWidth?: number;
    nameHeight?: number;
    priceWidth?: number;
    priceHeight?: number;
    promoWidth?: number;
    promoHeight?: number;
    bg_color?: string;
    nameBgColor?: string;
    priceBgColor?: string;
    promoBgColor?: string;
