    // Estados de Posicionamento
    const [namePos, setNamePos] = useState({ x: 50, y: 30 });
    const [pricePos, setPricePos] = useState({ x: 50, y: 60 });
    const [promoPos, setPromoPos] = useState({ x: 50, y: 75 });
