    const [promoBarcodePos, setPromoBarcodePos] = useState({ x: 50, y: 85 });

    // Campos Extras (Texto Livre)
    const [extraFields, setExtraFields] = useState<any[]>([]);
    const [extraFieldsPromo, setExtraFieldsPromo] = useState<any[]>([]);

    const addExtraField = () => {
        const newField = {
            id: `extra_${Date.now()}`,
            text: 'Novo Texto',
            x: 50,
            y: 50,
