                                                                {name}
                                                            </h4>
                                                            <div className="flex items-center gap-2 mt-0.5">
                                                                {prod.code && (
                                                                    <span className="text-[9px] font-bold text-slate-400 bg-slate-200 dark:bg-slate-800 px-1.5 py-0.5 rounded-md uppercase">
