                                                                    </span>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>

                                                    <div className="flex items-center gap-4 shrink-0 text-right">
                                                        <div>
                                                            {hasPromo ? (
                                                                <>
                                                                    <span className="text-[10px] text-slate-400 line-through block font-bold">
