                                                        >
                                                            Puxar
                                                        </button>
                                                    </div>
                                                </div>
                                            );
                                        })
                                    )}
                                </div>
                            </div>
                        )}

                        {/* Conteúdo Aba 2: Preenchimento Manual */}
