                                                    ? 'border-blue-500 shadow-xl shadow-blue-500/10 ring-4 ring-blue-500/10 dark:ring-blue-500/20' 
                                                    : 'border-slate-200 dark:border-slate-800 hover:border-blue-300 dark:hover:border-slate-700 hover:shadow-lg'
                                            }`}
                                        >
                                            <div className="space-y-3">
                                                <div className="flex items-center justify-between gap-2">
                                                    <div className="flex items-center gap-3">
                                                        <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${isActive ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400'}`}>
                                                            <i className={`bi ${model.icon || 'bi-grid-1x2-fill'} text-lg`} />
                                                        </div>
                                                        <div>
                                                            <h4 className="text-sm font-black uppercase text-slate-800 dark:text-slate-100 tracking-tight">
                                                                {model.name}
                                                            </h4>
                                                            <span className="text-[10px] font-bold text-slate-400">
                                                                {model.paperSize} &bull; {dims.width} x {dims.height} mm
                                                            </span>
                                                        </div>
                                                    </div>

                                                    {isActive && (
                                                        <span className="px-2.5 py-1 bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300 text-[9px] font-black uppercase rounded-lg flex items-center gap-1">
                                                            <i className="bi bi-check-circle-fill text-[10px]" /> Ativo
                                                        </span>
                                                    )}
                                                </div>

                                                <div className="p-3 bg-slate-50 dark:bg-slate-800/50 rounded-2xl space-y-1 text-[10px] font-bold text-slate-500 dark:text-slate-400 border border-slate-100 dark:border-slate-800">
                                                    <div className="flex justify-between">
                                                        <span>Capacidade:</span>
                                                        <strong className="text-slate-700 dark:text-slate-200">{model.columns * model.rows} etiquetas/folha</strong>
                                                    </div>
                                                    <div className="flex justify-between">
                                                        <span>Grade:</span>
                                                        <strong className="text-slate-700 dark:text-slate-200">{model.columns} colunas x {model.rows} linhas</strong>
                                                    </div>
                                                    <div className="flex justify-between">
                                                        <span>Margens T/B/L/R:</span>
                                                        <span className="text-slate-600 dark:text-slate-300">{model.marginT}/{model.marginB}/{model.marginL}/{model.marginR} mm</span>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex items-center gap-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                                                <button
                                                    type="button"
                                                    onClick={() => {
                                                        selectLayout(model);
                                                        setGridModalOpen(false);
                                                        setIsModelManagerModalOpen(false);
                                                        toast.success(`Modelo "${model.name}" selecionado!`);
                                                    }}
                                                    className={`flex-1 py-2.5 px-3 rounded-2xl font-black text-xs uppercase tracking-wider transition-all flex items-center justify-center gap-2 cursor-pointer ${
                                                        isActive 
                                                            ? 'bg-emerald-600 text-white shadow-md' 
                                                            : 'bg-blue-600 hover:bg-blue-700 text-white shadow-md shadow-blue-500/20 active:scale-95'
                                                    }`}
                                                >
                                                    <i className={`bi ${isActive ? 'bi-check-lg' : 'bi-check2-circle'}`} />
                                                    {isActive ? 'Selecionado' : 'Usar Modelo'}
                                                </button>

                                                <button
                                                    type="button"
                                                    onClick={() => {
                                                        setEditingGridModel(model);
                                                        setGridModalOpen(true);
                                                    }}
                                                    className="p-2.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 text-slate-600 dark:text-slate-300 rounded-2xl transition-colors cursor-pointer"
                                                    title="Editar Especifica├º├Áes"
                                                >
                                                    <i className="bi bi-pencil-fill text-xs" />
                                                </button>

                                                {isCustom && (
                                                    <button
                                                        type="button"
                                                        onClick={async () => {
                                                            if (window.confirm(`Excluir modelo "${model.name}"?`)) {
                                                                await handleDeleteLayout(model.id);
                                                            }
                                                        }}
                                                        className="p-2.5 bg-red-50 dark:bg-red-900/20 hover:bg-red-100 text-red-600 rounded-2xl transition-colors cursor-pointer"
                                                        title="Excluir Modelo"
                                                    >
                                                        <i className="bi bi-trash3-fill text-xs" />
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </div>
            )}

             <LabelImageModal 
                isOpen={isImageModalOpen}
                onClose={() => setIsImageModalOpen(false)}
                currentCategory={selectedCategory}
                onSelect={(image) => {
                    if (selectedCategory === 'logos') {
                        setLogoItems(prev => [...prev, { image, quantity: 1, imageFit: config.imageFit || 'contain', name: 'DA BIBLIOTECA' }]);
                    } else {
                        setSelectedImage(image);
                    }
                    setIsImageModalOpen(false);
                    toast.success('Imagem selecionada da biblioteca!');
                }}
             />

             <PriceLabelArtEditorModal 
                isOpen={isPriceLabelArtEditorOpen}
                onClose={() => {
                    setIsPriceLabelArtEditorOpen(false);
                    setArtVersion(prev => prev + 1);
                    if (location.pathname === '/templates/price-label' && window.opener) window.close();
                }}
                config={{
                    ...config,
                    artConfig: savedArtConfigs[String(config.layoutId || 'preco_2x5_restored')] || savedArtConfigs['preco_2x5_restored'] || config.artConfig
                }}
                onArtConfigLoaded={(loadedArtConfig: any) => {
                    const layoutId = String(config.layoutId || 'preco_2x5_restored');
                    setSavedArtConfigs(prev => ({
                        ...prev,
                        [layoutId]: loadedArtConfig,
                        'preco_2x5_restored': loadedArtConfig,
                    }));
                    setConfig(prev => ({ ...prev, artConfig: loadedArtConfig }));
                    setArtVersion(prev => prev + 1);
                }}
                onSaveConfig={async (updated: any) => {
                    const layoutId = String(config.layoutId || 'preco_2x5_restored');
                    const groupPos = updated.dePricePorGroupPos;
                    if (layoutId && updated.artConfig) {
                        const { error } = await supabase.from('label_art_configs').upsert({
                            layout_id: layoutId,
                            category: selectedCategory || 'precos',
                            art_config: updated.artConfig,
                            updated_at: new Date().toISOString(),
                        }, { onConflict: 'layout_id' });
                        if (error) throw error;
                    }
                    if (layoutId && (groupPos || updated.artConfig) && /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(String(layoutId))) {
                        const { error } = await supabase
                            .from('label_layouts')
                            .update({
                                ...(groupPos ? {
                                    de_price_por_group_pos_x: groupPos.x,
                                    de_price_por_group_pos_y: groupPos.y,
                                    de_price_por_group_rotation: updated.dePricePorGroupRotation ?? 0,
                                    de_price_por_group_gap: updated.dePricePorGroupGap ?? 10,
                                } : {}),
                                ...(updated.artConfig ? { art_config: updated.artConfig } : {}),
                            })
                            .eq('id', layoutId);
                        if (error) throw error;
                    }

                    if (updated.artConfig) {
                        setSavedArtConfigs(prev => ({
                            ...prev,
                            [layoutId]: updated.artConfig,
                            'preco_2x5_restored': updated.artConfig,
                        }));
                        publishPriceLabelTemplateUpdate({
                            layoutId,
                            artConfig: updated.artConfig,
                        });
                    }
                    setConfig(prev => ({
                        ...prev,
                        ...updated,
                        artConfig: updated.artConfig || prev.artConfig,
                    }));
                    setArtVersion(prev => prev + 1);
                }}
                initialProduct={selectedProductToAdd ? {
                    name: selectedProductToAdd.description,
                    price: String(selectedProductToAdd.unitPrice || (selectedProductToAdd as any).price || ''),
                    promoPrice: (selectedProductToAdd as any).promoPrice || '',
                    sku: selectedProductToAdd.sku || selectedProductToAdd.code || ''
                } : undefined}
             />
        </>
    );
};

import React, { useState, useEffect } from 'react';
import { PackageMinus, PackagePlus, Scale } from 'lucide-react';
import type InventoryMove from '@/pages/types/inventoryMove.type';
import { updateInventoryMove } from '@/pages/utils/inventoryService';
import { toast } from 'react-toastify';

export interface InventoryMoveEditModalProps {
    readonly move: InventoryMove | null;
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly onSuccess?: () => void;
}

/**
 * Modal para edição manual controlada de movimentações de estoque (tipo, quantidade, data e justificativa).
 */
export const InventoryMoveEditModal: React.FC<InventoryMoveEditModalProps> = ({
    move,
    isOpen,
    onClose,
    onSuccess,
}) => {
    const [type, setType] = useState<'entry' | 'withdrawal' | 'balance'>('entry');
    const [quantity, setQuantity] = useState<number>(0);
    const [date, setDate] = useState<string>('');
    const [observation, setObservation] = useState<string>('');
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        if (move && isOpen) {
            setType((move.type === 'adjustment' || move.type === 'balance') ? 'balance' : (move.type === 'entry' ? 'entry' : 'withdrawal'));
            setQuantity(move.quantity || 0);
            setDate(move.date ? move.date.substring(0, 10) : new Date().toISOString().substring(0, 10));
            setObservation(move.observation || move.label || '');
        }

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && !isSaving) {
                onClose();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [move, isOpen, isSaving, onClose]);

    if (!isOpen || !move) return null;

    const handleSave = async () => {
        if (type !== 'balance' && quantity <= 0) {
            toast.error('Por favor, informe uma quantidade maior que zero.');
            return;
        }

        if (type === 'balance' && quantity === 0) {
            toast.error('O valor do ajuste não pode ser zero.');
            return;
        }

        if (!observation.trim()) {
            toast.error('Por favor, informe um motivo ou observação.');
            return;
        }

        setIsSaving(true);
        try {
            await updateInventoryMove(move.id!, {
                type,
                quantity,
                date: date ? new Date(date + 'T12:00:00Z').toISOString() : new Date().toISOString(),
                label: observation.trim(),
                observation: observation.trim(),
            });

            toast.success('Movimentação atualizada com sucesso!');
            onSuccess?.();
            onClose();
        } catch (error: unknown) {
            console.error('Erro ao atualizar movimentação:', error);
            const message = error instanceof Error ? error.message : 'Não foi possível atualizar a movimentação.';
            toast.error(message);
        } finally {
            setIsSaving(false);
        }
    };

    const theme =
        type === 'entry'
            ? { header: 'bg-emerald-600', confirm: 'bg-emerald-600 hover:bg-emerald-700' }
            : type === 'withdrawal'
            ? { header: 'bg-red-600', confirm: 'bg-red-600 hover:bg-red-700' }
            : { header: 'bg-amber-500', confirm: 'bg-amber-500 hover:bg-amber-600' };

    return (
        <div
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-fade-in"
            role="dialog"
            aria-modal="true"
            aria-label="Editar Movimentação de Estoque"
        >
            <div
                className="absolute inset-0 bg-slate-950/60 backdrop-blur-sm cursor-pointer"
                onClick={onClose}
                aria-hidden="true"
            />

            <div className="relative w-full max-w-md rounded-3xl bg-white shadow-2xl overflow-hidden animate-slide-up dark:bg-slate-900 border border-slate-100 dark:border-slate-800">
                {/* Header */}
                <div className={`flex items-center justify-between px-6 py-4 text-white ${theme.header}`}>
                    <div className="flex items-center gap-2">
                        <i className="bi bi-pencil-square text-lg" aria-hidden="true" />
                        <h2 className="text-sm font-black uppercase tracking-wider">Editar Movimentação</h2>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="rounded-lg p-1.5 transition-colors hover:bg-white/10 cursor-pointer"
                        aria-label="Fechar modal"
                    >
                        <i className="bi bi-x-lg text-base" aria-hidden="true" />
                    </button>
                </div>

                <div className="p-6 space-y-4">
                    {/* Detalhes do Produto */}
                    <div className="p-3.5 bg-slate-50 dark:bg-slate-950 rounded-2xl border border-slate-100 dark:border-slate-800">
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                            Produto
                        </span>
                        <p className="text-xs font-bold text-slate-800 dark:text-slate-200 mt-0.5 truncate">
                            {move.productName || move.productDescription || 'Produto'}
                        </p>
                    </div>

                    {/* Tipo */}
                    <div className="grid grid-cols-3 gap-2">
                        {(['entry', 'withdrawal', 'balance'] as const).map((t) => (
                            <button
                                key={t}
                                type="button"
                                onClick={() => setType(t)}
                                className={`flex flex-col items-center gap-1 p-2.5 rounded-xl border-2 transition-all cursor-pointer ${
                                    type === t
                                        ? t === 'entry'
                                            ? 'bg-emerald-50 border-emerald-500 text-emerald-600 dark:bg-emerald-900/20'
                                            : t === 'withdrawal'
                                            ? 'bg-red-50 border-red-500 text-red-600 dark:bg-red-900/20'
                                            : 'bg-amber-50 border-amber-500 text-amber-600 dark:bg-amber-900/20'
                                        : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200'
                                }`}
                            >
                                {t === 'entry' ? (
                                    <PackagePlus className="h-5 w-5" aria-hidden="true" />
                                ) : t === 'withdrawal' ? (
                                    <PackageMinus className="h-5 w-5" aria-hidden="true" />
                                ) : (
                                    <Scale className="h-5 w-5" aria-hidden="true" />
                                )}
                                <span className="text-[9px] font-black uppercase tracking-wider">
                                    {t === 'entry' ? 'Entrada' : t === 'withdrawal' ? 'Saída' : 'Ajuste'}
                                </span>
                            </button>
                        ))}
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        {/* Quantidade */}
                        <div className="flex flex-col gap-1.5">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                {type === 'balance' ? 'Valor do Ajuste (+ ou -)' : 'Quantidade'}
                            </label>
                            <input
                                type="number"
                                value={quantity}
                                onChange={(e) => setQuantity(Number(e.target.value))}
                                className="w-full bg-slate-50 dark:bg-slate-950 px-3.5 py-2.5 rounded-xl border border-slate-200 dark:border-slate-800 outline-none focus:ring-2 focus:ring-emerald-500 transition-all font-black text-base text-slate-800 dark:text-slate-100"
                            />
                        </div>

                        {/* Data */}
                        <div className="flex flex-col gap-1.5">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                Data
                            </label>
                            <input
                                type="date"
                                value={date}
                                onChange={(e) => setDate(e.target.value)}
                                className="w-full bg-slate-50 dark:bg-slate-950 px-3 py-2.5 rounded-xl border border-slate-200 dark:border-slate-800 outline-none focus:ring-2 focus:ring-emerald-500 transition-all font-bold text-xs text-slate-800 dark:text-slate-100"
                            />
                        </div>
                    </div>

                    {/* Motivo / Observação */}
                    <div className="flex flex-col gap-1.5">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                            Motivo / Observação *
                        </label>
                        <input
                            type="text"
                            value={observation}
                            onChange={(e) => setObservation(e.target.value)}
                            placeholder="Descreva o motivo da movimentação..."
                            className="w-full bg-slate-50 dark:bg-slate-950 px-3.5 py-2.5 rounded-xl border border-slate-200 dark:border-slate-800 outline-none focus:ring-2 focus:ring-emerald-500 transition-all font-bold text-xs text-slate-800 dark:text-slate-100"
                        />
                    </div>

                    {/* Ações */}
                    <div className="pt-2 flex justify-end gap-2.5">
                        <button
                            type="button"
                            onClick={onClose}
                            disabled={isSaving}
                            className="rounded-xl px-4 py-2.5 text-xs font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all cursor-pointer"
                        >
                            Cancelar
                        </button>
                        <button
                            type="button"
                            onClick={handleSave}
                            disabled={isSaving}
                            className={`rounded-xl px-5 py-2.5 text-xs font-black uppercase tracking-wider text-white shadow-md transition-all active:scale-95 disabled:opacity-50 cursor-pointer ${theme.confirm}`}
                        >
                            {isSaving ? 'Salvando...' : 'Salvar Alterações'}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default InventoryMoveEditModal;

import { useEffect, useState } from 'react';
import type Purchase from '@/pages/types/purchase.type';
import type Product from '@/pages/types/product.type';
import { subscribeToProducts } from '@/pages/utils/productService';
import { saveInventoryMove } from '@/pages/utils/inventoryService';
import { updatePurchase } from '@/pages/utils/purchaseService';
import { toast } from 'react-toastify';

interface PurchaseStockEntryModalProps {
    readonly purchase: Purchase | null;
    readonly isOpen: boolean;
    readonly onClose: () => void;
}

export function PurchaseStockEntryModal({ purchase, isOpen, onClose }: PurchaseStockEntryModalProps) {
    const [products, setProducts] = useState<Product[]>([]);
    const [date, setDate] = useState('');
    const [observation, setObservation] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, onClose]);

    useEffect(() => {
        if (!isOpen || !purchase) return;
        setDate(purchase.date?.slice(0, 10) || new Date().toISOString().slice(0, 10));
        setObservation(`Pedido de Compra #${purchase.id?.slice(-4)}${purchase.invoiceNumber ? ` | NF: ${purchase.invoiceNumber}` : ''}${purchase.observation ? ` | ${purchase.observation}` : ''}`);
        return subscribeToProducts((data) => setProducts(data.filter((product) => !product.deleted)));
    }, [isOpen, purchase]);

    const handleSave = async () => {
        if (!purchase || !observation.trim()) {
            toast.error('Informe a observação da movimentação.');
            return;
        }
        const missingProduct = purchase.items.find((item) => !products.some((product) => product.id === item.productId));
        if (missingProduct) {
            toast.error(`Produto não encontrado: ${missingProduct.description}.`);
            return;
        }
        setIsSaving(true);
        try {
            for (const item of purchase.items) {
                const product = products.find((current) => current.id === item.productId);
                if (!product) continue;
                const variation = product.variations?.find((current) => current.id === item.variationId);
                await saveInventoryMove({
                    productId: item.productId,
                    variationId: item.variationId,
                    productDescription: item.description,
                    type: 'entry',
                    quantity: item.quantity,
                    date: new Date(`${date}T12:00:00`).toISOString(),
                    label: `Entrada a partir do Pedido #${purchase.purchaseNumber || purchase.id?.slice(-4)}`,
                    observation,
                    unitCost: item.unitCost,
                    relatedEntityId: purchase.id,
                    relatedEntityType: 'purchase_order'
                }, variation ? Number(variation.stock || 0) : Number(product.stock || 0));
            }
            if (purchase.id) {
                await updatePurchase(purchase.id, { stockProcessed: true });
            }
            toast.success('Movimentações de entrada registradas com sucesso!');
            onClose();
        } catch (error: unknown) {
            console.error('Erro ao registrar movimentações:', error);
            toast.error('Não foi possível registrar as movimentações.');
        } finally {
            setIsSaving(false);
        }
    };

    if (!isOpen || !purchase) return null;

    return (
        <div
            className="fixed inset-x-0 bottom-0 top-14 z-40 flex items-center justify-center p-0 xl:inset-0 xl:z-50 xl:p-4"
            role="dialog"
            aria-modal="true"
            aria-labelledby="purchase-stock-entry-title"
        >
            <button
                type="button"
                aria-label="Fechar"
                className="absolute inset-0 bg-slate-900/60 cursor-default"
                onClick={onClose}
            />
            <div className="relative flex h-full w-full flex-col overflow-hidden rounded-none border-0 bg-white shadow-2xl dark:bg-slate-900 xl:h-auto xl:max-h-[90vh] xl:max-w-2xl xl:rounded-[2rem] xl:border xl:border-slate-100 xl:dark:border-slate-800">
                <header className="flex shrink-0 items-center justify-between bg-emerald-600 p-6 text-white">
                    <div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-emerald-100">
                            Pedido #{purchase.purchaseNumber || purchase.id?.slice(-4)} · {purchase.supplierName}
                        </p>
                        <h2 id="purchase-stock-entry-title" className="mt-1 text-xl font-black">
                            Entrada a partir deste pedido
                        </h2>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        aria-label="Fechar"
                        className="rounded-xl p-2 hover:bg-white/10 transition-colors"
                    >
                        <i className="bi bi-x-lg" aria-hidden="true" />
                    </button>
                </header>
                <div className="flex-1 space-y-5 overflow-y-auto p-6">
                    <div className="grid grid-cols-3 gap-3">
                        <button
                            type="button"
                            className="flex flex-col items-center gap-2 rounded-2xl border-2 border-emerald-500 bg-emerald-50 p-4 text-emerald-600 shadow-lg shadow-emerald-100 dark:bg-emerald-900/20"
                        >
                            <i className="bi bi-plus-circle text-xl" aria-hidden="true" />
                            <span className="text-[9px] font-black uppercase tracking-widest">Entrada</span>
                        </button>
                        <button
                            type="button"
                            disabled
                            className="flex cursor-not-allowed flex-col items-center gap-2 rounded-2xl border-2 border-slate-100 bg-slate-50 p-4 text-slate-300 opacity-60 dark:border-slate-800 dark:bg-slate-900"
                        >
                            <i className="bi bi-dash-circle text-xl" aria-hidden="true" />
                            <span className="text-[9px] font-black uppercase tracking-widest">Saída</span>
                        </button>
                        <button
                            type="button"
                            disabled
                            className="flex cursor-not-allowed flex-col items-center gap-2 rounded-2xl border-2 border-slate-100 bg-slate-50 p-4 text-slate-300 opacity-60 dark:border-slate-800 dark:bg-slate-900"
                        >
                            <span className="text-xl leading-none" aria-hidden="true">⚖</span>
                            <span className="text-[9px] font-black uppercase tracking-widest">Ajuste</span>
                        </button>
                    </div>
                    <div className="overflow-hidden rounded-2xl border border-slate-100 dark:border-slate-800">
                        <table className="w-full text-left text-sm">
                            <thead className="bg-slate-50 text-[10px] font-black uppercase tracking-widest text-slate-400 dark:bg-slate-800">
                                <tr>
                                    <th scope="col" className="px-4 py-3">Produto</th>
                                    <th scope="col" className="px-4 py-3 text-right">Quantidade</th>
                                </tr>
