                            <tbody>
                                {purchase.items.map((item) => (
                                    <tr key={`${item.productId}-${item.variationId || ''}`} className="border-t border-slate-100 dark:border-slate-800">
                                        <td className="px-4 py-3 font-bold text-slate-700 dark:text-slate-100">{item.description}</td>
                                        <td className="px-4 py-3 text-right font-black">{item.quantity}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                    <div className="grid gap-4 sm:grid-cols-3">
                        <label className="flex flex-col gap-2 text-[10px] font-black uppercase tracking-widest text-slate-400">
                            Data
                            <input
                                type="date"
                                value={date}
                                onChange={(event) => setDate(event.target.value)}
                                className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm font-bold text-slate-700 outline-none focus:border-emerald-500 dark:border-slate-700 dark:bg-slate-800 dark:text-white transition-colors"
                            />
                        </label>
                        <label className="flex flex-col gap-2 text-[10px] font-black uppercase tracking-widest text-slate-400 sm:col-span-2">
                            Observação
                            <textarea
                                value={observation}
                                onChange={(event) => setObservation(event.target.value)}
                                rows={2}
                                className="resize-none rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm font-medium normal-case tracking-normal text-slate-700 outline-none focus:border-emerald-500 dark:border-slate-700 dark:bg-slate-800 dark:text-white transition-colors"
                            />
                        </label>
                    </div>
                    <button
                        type="button"
                        disabled={isSaving}
                        onClick={handleSave}
                        className="w-full rounded-2xl bg-emerald-600 py-4 text-xs font-black uppercase tracking-widest text-white transition-colors hover:bg-emerald-700 disabled:opacity-60 shadow-md"
                    >
                        {isSaving ? 'Registrando...' : 'Confirmar movimentações de entrada'}
                    </button>
                </div>
            </div>
        </div>
    );
}

export default PurchaseStockEntryModal;

import React, { useState, useEffect, useMemo } from 'react';
import { PackageMinus, PackagePlus, Scale } from 'lucide-react';
import Product, { Variation } from '../../../types/product.type';
import { saveInventoryMove, subscribeToInventoryMoves } from '@/pages/utils/inventoryService';
import { toast } from 'react-toastify';
import InventoryMove from '../../../types/inventoryMove.type';
import { calculateInventoryTimelineBalance } from '@/pages/utils/inventoryTimelineBalance';

export interface StockLaunchModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly targetProduct: Product | null;
    readonly targetVariation?: Variation;
    readonly currentStock?: number;
}

export type LaunchType = 'entry' | 'exit' | 'adjustment';

interface VariationDisplayNameLike extends Partial<Variation> {
    readonly displayName?: string;
}

/**
 * Modal rápido para lançamento manual de entrada, saída ou ajuste de inventário de produtos e variações.
 */
export const StockLaunchModal: React.FC<StockLaunchModalProps> = ({
    isOpen,
    onClose,
    targetProduct,
    targetVariation,
    currentStock: propCurrentStock,
}) => {
    const [type, setType] = useState<LaunchType>('entry');
    const [quantity, setQuantity] = useState<number>(0);
    const [newDesiredStock, setNewDesiredStock] = useState<string>('');
    const [reason, setReason] = useState('');
    const [isSaving, setIsSaving] = useState(false);
    const [moves, setMoves] = useState<readonly InventoryMove[]>([]);

    useEffect(() => {
        if (!isOpen) return;
        return subscribeToInventoryMoves((data) => setMoves(data || []));
    }, [isOpen]);

    useEffect(() => {
        if (isOpen) {
            setQuantity(0);
            setNewDesiredStock('');
            setReason('');
            setType('entry');
        }

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && !isSaving) {
                onClose();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, isSaving, onClose]);

    const activeVariation = targetVariation || targetProduct?.variations?.[0];
    const variationWithDisplayName = activeVariation as VariationDisplayNameLike | undefined;
    const variationName = activeVariation?.name || variationWithDisplayName?.displayName || '';

    // Calcula o saldo dinamicamente a partir das movimentações reais
    const currentStock = useMemo(() => {
        if (!targetProduct) return 0;

        const targetVarId = activeVariation?.id;
        const relevantMoves = moves.filter((m) => {
            if (m.status === 'cancelled') return false;
            if (m.productId !== targetProduct.id) return false;
            if (targetVarId && m.variationId) {
                return String(m.variationId) === String(targetVarId);
            }
            return true;
        });

        const timelineBalance = calculateInventoryTimelineBalance(relevantMoves);
        if (timelineBalance !== null) return timelineBalance;

        if (propCurrentStock !== undefined) return propCurrentStock;
        return Number(activeVariation?.stock !== undefined ? activeVariation.stock : targetProduct.stock || 0);
    }, [targetProduct, activeVariation, propCurrentStock, moves]);

    if (!isOpen || !targetProduct) return null;

    const fullDisplayName = variationName && variationName.trim() ? variationName.trim() : 'Variação não identificada';
    const adjustmentDiff = newDesiredStock !== '' ? Number(newDesiredStock) - currentStock : 0;

    const handleSave = async () => {
        let moveQuantity = quantity;

        if (type === 'adjustment') {
            if (newDesiredStock === '') {
                toast.error('Por favor, informe o novo saldo do produto.');
                return;
            }
            moveQuantity = Number(newDesiredStock) - currentStock;
            if (moveQuantity === 0) {
                toast.error('O novo saldo informado é idêntico ao saldo atual.');
                return;
            }
        } else {
            if (quantity <= 0) {
                toast.error('Por favor, informe uma quantidade maior que zero.');
                return;
            }
        }

        if (!reason.trim()) {
            toast.error('Por favor, declare o motivo da movimentação.');
            return;
        }

        if (!activeVariation?.id) {
            toast.error('Esta operação exige uma variação cadastrada. Vincule ou crie a variação antes de movimentar o estoque.');
            return;
        }

        setIsSaving(true);
        try {
            const move: InventoryMove = {
                productId: targetProduct.id!,
                variationId: activeVariation.id,
                productDescription: fullDisplayName,
                type: type === 'adjustment' ? 'balance' : type === 'entry' ? 'entry' : 'withdrawal',
                quantity: moveQuantity,
                date: new Date().toISOString(),
                label: reason.trim(),
                observation: reason.trim(),
            };

            await saveInventoryMove(move, currentStock);

            toast.success('Movimentação registrada com sucesso! ✨');
            onClose();
            setQuantity(0);
            setNewDesiredStock('');
            setReason('');
        } catch (error: unknown) {
            console.error('Erro ao salvar movimentação:', error);
            const message = error instanceof Error ? error.message : 'Erro ao salvar lançamento de estoque.';
            toast.error(message);
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div
            className="fixed inset-0 z-[100] flex items-center justify-center p-4"
            role="dialog"
            aria-modal="true"
            aria-label="Nova Movimentação de Estoque"
        >
            <div
                className="absolute inset-0 bg-slate-950/60 backdrop-blur-sm animate-fade-in cursor-pointer"
                onClick={onClose}
                aria-hidden="true"
            />

            <div className="relative w-full max-w-lg bg-white dark:bg-slate-900 rounded-3xl shadow-2xl overflow-hidden animate-slide-up border border-slate-100 dark:border-slate-800">
                {/* Header Dinâmico */}
                <div
                    className={`flex items-center justify-between px-8 py-5 transition-colors text-white ${
                        type === 'entry'
                            ? 'bg-emerald-600'
                            : type === 'exit'
                            ? 'bg-rose-600'
                            : 'bg-amber-500'
                    }`}
                >
                    <div className="flex items-center gap-3">
                        <div className="p-2 rounded-xl bg-white/10 backdrop-blur-sm">
                            <i className="bi bi-arrow-left-right text-lg" aria-hidden="true" />
                        </div>
                        <div>
                            <h3 className="text-sm font-black uppercase tracking-wider">
                                Nova Movimentação de Estoque
                            </h3>
                            <p className="text-[11px] font-medium text-white/80">
                                {type === 'entry'
                                    ? 'Entrada no estoque'
                                    : type === 'exit'
                                    ? 'Saída do estoque'
                                    : 'Ajuste de inventário'}
                            </p>
                        </div>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-2 rounded-xl text-white/80 hover:text-white hover:bg-white/10 transition-colors cursor-pointer"
                        aria-label="Fechar modal"
                    >
                        <i className="bi bi-x-lg text-lg" aria-hidden="true" />
                    </button>
                </div>

                <div className="p-8 space-y-6">
                    {/* Resumo do Produto Selecionado */}
                    <div className="p-4 rounded-2xl bg-slate-50 dark:bg-slate-950 border border-slate-100 dark:border-slate-800">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-xl bg-emerald-100 dark:bg-emerald-950/50 flex items-center justify-center text-emerald-600 shrink-0">
                                <i className="bi bi-box-seam text-lg" aria-hidden="true" />
                            </div>
                            <div className="min-w-0 flex-1">
                                <h4 className="text-xs font-bold text-slate-800 dark:text-slate-200 truncate">
                                    {fullDisplayName}
                                </h4>
                                <p className="text-xs text-slate-500 font-medium tracking-tight mt-0.5">
                                    Saldo Atual:{' '}
                                    <span className="font-black text-slate-700 dark:text-slate-200">
                                        {currentStock} {targetProduct.unit || 'UN'}
                                    </span>
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Tipo de Movimentação */}
                    <div className="grid grid-cols-3 gap-3">
                        {(['entry', 'exit', 'adjustment'] as const).map((t) => (
                            <button
                                key={t}
                                type="button"
                                onClick={() => setType(t)}
                                className={`flex flex-col items-center gap-1.5 p-3.5 rounded-2xl border-2 transition-all cursor-pointer ${
                                    type === t
                                        ? t === 'entry'
                                            ? 'bg-emerald-50 border-emerald-500 text-emerald-600 dark:bg-emerald-900/20 shadow-lg shadow-emerald-100 dark:shadow-none'
                                            : t === 'exit'
                                            ? 'bg-red-50 border-red-500 text-red-600 dark:bg-red-900/20 shadow-lg shadow-red-100 dark:shadow-none'
                                            : 'bg-amber-50 border-amber-500 text-amber-600 dark:bg-amber-900/20 shadow-lg shadow-amber-100 dark:shadow-none'
                                        : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 text-slate-400 hover:border-slate-200'
                                }`}
                            >
                                {t === 'entry' ? (
                                    <PackagePlus className="h-6 w-6" aria-hidden="true" />
                                ) : t === 'exit' ? (
                                    <PackageMinus className="h-6 w-6" aria-hidden="true" />
                                ) : (
                                    <Scale className="h-6 w-6" aria-hidden="true" />
                                )}
                                <span className="text-[9px] font-black uppercase tracking-widest">
                                    {t === 'entry' ? 'Entrada' : t === 'exit' ? 'Saída' : 'Ajuste'}
                                </span>
                            </button>
                        ))}
                    </div>

                    {/* Formulário de Quantidade / Novo Saldo */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {type === 'adjustment' ? (
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                    Novo Saldo do Produto
                                </label>
                                <input
                                    type="number"
                                    value={newDesiredStock}
                                    onChange={(e) => setNewDesiredStock(e.target.value)}
                                    placeholder={`Saldo atual: ${currentStock}`}
                                    className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl px-4 py-2.5 text-xs font-bold text-slate-800 dark:text-white outline-none focus:border-amber-500 transition-colors"
                                    autoFocus
                                />
                                {newDesiredStock !== '' && (
                                    <div className="text-[10px] font-bold text-slate-500 dark:text-slate-400 pt-1 flex items-center gap-1.5">
                                        <span>Ajuste resultante:</span>
                                        <span
                                            className={`px-2 py-0.5 rounded-md font-black text-[11px] ${
                                                adjustmentDiff > 0
                                                    ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300'
                                                    : adjustmentDiff < 0
                                                    ? 'bg-rose-100 text-rose-700 dark:bg-rose-950/40 dark:text-rose-300'
                                                    : 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400'
                                            }`}
                                        >
                                            {adjustmentDiff > 0 ? `+${adjustmentDiff}` : adjustmentDiff}{' '}
                                            {targetProduct.unit || 'un'}
                                        </span>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                    Quantidade *
                                </label>
                                <input
                                    type="number"
                                    value={quantity || ''}
                                    onChange={(e) => setQuantity(Number(e.target.value))}
                                    placeholder="0"
                                    min="1"
                                    className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl px-4 py-2.5 text-xs font-bold text-slate-800 dark:text-white outline-none focus:border-emerald-500 transition-colors"
                                    autoFocus
                                />
                            </div>
                        )}

                        <div className="space-y-1.5">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                Motivo / Observação *
                            </label>
                            <input
                                type="text"
                                value={reason}
                                onChange={(e) => setReason(e.target.value)}
                                placeholder="Ex: Balanço de estoque, contagem física..."
                                className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl px-4 py-2.5 text-xs font-bold text-slate-800 dark:text-white outline-none focus:border-slate-400 transition-colors"
                            />
                        </div>
                    </div>

                    {/* Botão de Confirmação */}
                    <button
                        type="button"
                        onClick={handleSave}
                        disabled={isSaving}
                        className={`w-full py-3.5 rounded-xl font-black uppercase tracking-wider text-xs text-white shadow-lg transition-all active:scale-[0.98] cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 ${
                            type === 'entry'
                                ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200 dark:shadow-none'
                                : type === 'exit'
                                ? 'bg-rose-600 hover:bg-rose-700 shadow-rose-200 dark:shadow-none'
                                : 'bg-amber-500 hover:bg-amber-600 shadow-amber-200 dark:shadow-none'
                        }`}
                    >
                        {isSaving ? (
                            <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        ) : (
                            <>
                                <i className="bi bi-check2 text-base" aria-hidden="true" />
                                <span>Confirmar Movimentação</span>
                            </>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default StockLaunchModal;

import React, { useEffect, useMemo, useRef, useState } from 'react';
import Person from '@/pages/types/person.type';
import DropdownPortal from '@/components/shared/DropdownPortal';

export interface PurchaseSupplierFilterProps {
    readonly suppliers: readonly Person[];
    readonly selectedSupplierId: string;
    readonly onSelect: (supplierId: string) => void;
}

/**
 * Componente de filtro de fornecedores em pedidos de compra com busca reativa e dropdown flutuante seguro via portal.
 */
export const PurchaseSupplierFilter: React.FC<PurchaseSupplierFilterProps> = ({
    suppliers,
    selectedSupplierId,
    onSelect,
}) => {
    const [query, setQuery] = useState('');
    const [isOpen, setIsOpen] = useState(false);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const selectedSupplier = suppliers.find((supplier) => supplier.id === selectedSupplierId);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (!wrapperRef.current?.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };

        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                setIsOpen(false);
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        window.addEventListener('keydown', handleKeyDown);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, []);

    const suggestions = useMemo(() => {
        const normalizedQuery = query.trim().toLocaleLowerCase();
        if (!normalizedQuery) return suppliers;
        return suppliers.filter((supplier) =>
            [supplier.fullName, supplier.tradeName, supplier.cpfCnpj].some((value) =>
                value?.toLocaleLowerCase().includes(normalizedQuery)
            )
        );
    }, [query, suppliers]);

    return (
        <div ref={wrapperRef} className="relative flex-1 max-w-md">
            <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 z-10" aria-hidden="true" />
            <input
                type="text"
                autoComplete="off"
                role="combobox"
                aria-expanded={isOpen && !selectedSupplier}
                aria-label="Buscar fornecedor"
                value={selectedSupplier ? '' : query}
                onFocus={() => setIsOpen(true)}
                onChange={(event) => {
                    onSelect('');
                    setQuery(event.target.value);
                    setIsOpen(true);
                }}
                placeholder="Buscar e selecionar fornecedor..."
                className="w-full pl-12 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border-none rounded-2xl text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all dark:text-slate-200"
            />
            {selectedSupplier && (
                <div className="absolute inset-y-1.5 left-11 right-1.5 flex items-center justify-between gap-2 rounded-xl bg-blue-600 px-3 text-sm font-bold text-white shadow-sm">
                    <span className="truncate">
                        <i className="bi bi-truck mr-2" aria-hidden="true" />
                        {selectedSupplier.fullName}
                    </span>
                    <button
                        type="button"
                        onClick={() => {
                            onSelect('');
                            setQuery('');
                        }}
                        className="rounded-md px-1 text-blue-100 hover:bg-blue-700 hover:text-white"
                        title="Limpar fornecedor"
                        aria-label="Limpar fornecedor selecionado"
                    >
                        <i className="bi bi-x-lg" aria-hidden="true" />
                    </button>
                </div>
            )}
            <DropdownPortal anchorRef={wrapperRef} isOpen={isOpen && !selectedSupplier}>
                <div
                    role="listbox"
                    aria-label="Sugestões de fornecedores"
                    className="max-h-64 overflow-y-auto rounded-2xl border border-slate-100 bg-white shadow-2xl dark:border-slate-800 dark:bg-slate-900 custom-scrollbar"
                >
                    {suggestions.length > 0 ? (
                        suggestions.map((supplier) => (
                            <button
                                key={supplier.id}
                                type="button"
                                role="option"
                                aria-selected={supplier.id === selectedSupplierId}
                                className="block w-full px-4 py-3 text-left hover:bg-blue-50 dark:hover:bg-slate-800 transition-colors"
                                onClick={() => {
                                    onSelect(supplier.id || '');
                                    setQuery('');
                                    setIsOpen(false);
                                }}
                            >
                                <span className="block text-sm font-bold text-slate-700 dark:text-slate-100">
                                    {supplier.fullName}
                                </span>
                                {supplier.tradeName && (
                                    <span className="text-xs text-slate-400">{supplier.tradeName}</span>
                                )}
                            </button>
                        ))
                    ) : (
                        <p className="px-4 py-5 text-center text-sm text-slate-400">
                            Nenhum fornecedor encontrado.
                        </p>
                    )}
                </div>
            </DropdownPortal>
        </div>
    );
};

export default PurchaseSupplierFilter;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import Purchase, { PurchaseItem } from '../../../../types/purchase.type';
import Product from '../../../../types/product.type';
import Person from '../../../../types/person.type';
import { subscribeToProducts } from '@/pages/utils/productService';
import { subscribeToPeople } from '@/pages/utils/personService';
import { savePurchase, updatePurchase } from '../../../../utils/purchaseService';
import { toast } from 'react-toastify';
import { formatCurrency } from '../../../../utils/formatters';
import SupplierAutocomplete from '@/components/SupplierAutocomplete';
import { supabase } from '@/pages/utils/supabaseConfig';
import imageCompression from 'browser-image-compression';
import { PurchaseItemsSection } from '@/components/PurchaseItemsSection';

export interface PurchaseFormModalProps {
    readonly isOpen: boolean;
    readonly onClose: () => void;
    readonly purchase?: Purchase | null;
    readonly initialPurchase?: Purchase | null;
}

interface ProductSupplierLookupLike extends Partial<Product> {
    readonly supplier_ids?: readonly string[];
    readonly main_supplier_id?: string;
    readonly supplier_id?: string;
}

/**
 * Modal principal de criação e edição de pedidos de compra, cálculo automático de IPI/Frete e lançamento em estoque.
 */
export const PurchaseFormModal: React.FC<PurchaseFormModalProps> = ({
    isOpen,
    onClose,
    purchase,
    initialPurchase,
}) => {
    const activePurchase = purchase || initialPurchase;
    const [suppliers, setSuppliers] = useState<readonly Person[]>([]);
    const [products, setProducts] = useState<readonly Product[]>([]);
    const [selectedSupplierId, setSelectedSupplierId] = useState('');
    const [items, setItems] = useState<readonly PurchaseItem[]>([]);
    const [isSaving, setIsSaving] = useState(false);
    const [attachments, setAttachments] = useState<readonly string[]>([]);
    const [isUploading, setIsUploading] = useState(false);
    const [purchaseDate, setPurchaseDate] = useState(new Date().toISOString().split('T')[0]);
    const [ipiPercent, setIpiPercent] = useState(0);
    const [freightPercent, setFreightPercent] = useState(0);
    const [validationErrors, setValidationErrors] = useState({ supplier: false, items: false });
    const [draftId, setDraftId] = useState<string | null>(null);
    const [isAutoSaving, setIsAutoSaving] = useState(false);

    // Campos legados mantidos como constantes
    const observation = '';
    const invoiceNumber = '';
    const invoiceDate = '';

    useEffect(() => {
        if (isOpen) {
            const unsubSuppliers = subscribeToPeople('suppliers', (data) => {
                setSuppliers(data.filter((p) => !p.deleted && p.type === 'suppliers'));
            });
            const unsubProducts = subscribeToProducts((data) => {
                setProducts(data.filter((p) => !p.deleted && p.itemType === 'product'));
            });

            if (activePurchase) {
                setSelectedSupplierId(activePurchase.supplierId || '');
                setPurchaseDate(
                    activePurchase.date
                        ? activePurchase.date.includes('T')
                            ? activePurchase.date.split('T')[0]
                            : activePurchase.date
                        : new Date().toISOString().split('T')[0]
                );
                setIpiPercent(activePurchase.ipiPercent || 0);
                setFreightPercent(activePurchase.freightPercent || 0);
                setAttachments(activePurchase.attachments || []);
                setItems(activePurchase.items || []);
                setValidationErrors({ supplier: false, items: false });
                setDraftId(null);
            } else {
                setSelectedSupplierId('');
                setPurchaseDate(new Date().toISOString().split('T')[0]);
                setIpiPercent(0);
                setFreightPercent(0);
                setAttachments([]);
                setItems([]);
                setValidationErrors({ supplier: false, items: false });
                setDraftId(null);
            }

            const handleKeyDown = (e: KeyboardEvent) => {
                if (e.key === 'Escape') {
                    handleCancelOrClose();
                }
            };

            window.addEventListener('keydown', handleKeyDown);

            return () => {
                unsubSuppliers();
                unsubProducts();
                window.removeEventListener('keydown', handleKeyDown);
            };
        }
    }, [isOpen, activePurchase]);

    const handleAddItem = (newItem: PurchaseItem) => {
        const product = products.find((p) => p.id === newItem.productId) as ProductSupplierLookupLike | undefined;
        const supplierIds = product?.supplierIds || product?.supplier_ids || [];
        const prodSupplierId =
            product?.mainSupplierId ||
            product?.supplierId ||
            product?.main_supplier_id ||
            product?.supplier_id;

        const productUsesSelectedSupplier =
            !selectedSupplierId ||
            !product ||
            supplierIds.includes(selectedSupplierId) ||
            prodSupplierId === selectedSupplierId;

        if (!selectedSupplierId && prodSupplierId) {
            setSelectedSupplierId(prodSupplierId);
        } else if (selectedSupplierId && !productUsesSelectedSupplier) {
            const prodSupplier = suppliers.find((s) => s.id === prodSupplierId);
            toast.error(
                `Este produto pertence ao fornecedor "${prodSupplier?.fullName || 'outro fornecedor'}". Remova os itens para trocar de fornecedor.`
            );
            return false;
        }

        setItems((currentItems) => [...currentItems, newItem]);
        setValidationErrors((current) => ({ ...current, items: false }));
        return true;
    };

    const handleRemoveItem = (idx: number) => {
        setItems(items.filter((_, i) => i !== idx));
    };

    const compressImage = async (file: File): Promise<File> => {
        if (!file.type.startsWith('image/')) return file;
        if (file.size <= 2 * 1024 * 1024) return file;

        const options = {
            maxSizeMB: 2,
            useWebWorker: true,
        };
        try {
            return await imageCompression(file, options);
        } catch (error: unknown) {
            console.error('Erro ao comprimir imagem:', error);
            return file;
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        if (attachments.length + files.length > 5) {
            toast.error('Você pode anexar no máximo 5 arquivos (PDF ou imagem).');
            return;
        }

        setIsUploading(true);
        try {
            const uploadedUrls = [...attachments];
            for (let i = 0; i < files.length; i++) {
                let file = files[i];

                if (file.type.startsWith('image/') && file.size > 2 * 1024 * 1024) {
                    file = await compressImage(file);
                }

                const fileExt = file.name.split('.').pop();
                const fileName = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}.${fileExt}`;
                const filePath = `purchases/${fileName}`;

                const { error } = await supabase.storage.from('purchase-attachments').upload(filePath, file);

                if (error) throw error;

                const { data: publicUrlData } = supabase.storage
                    .from('purchase-attachments')
                    .getPublicUrl(filePath);

                if (publicUrlData?.publicUrl) {
                    uploadedUrls.push(publicUrlData.publicUrl);
                }
            }
            setAttachments(uploadedUrls);
            toast.success('Arquivo(s) anexado(s) com sucesso!');
        } catch (error: unknown) {
            console.error('Erro ao fazer upload do arquivo:', error);
            toast.error('Erro ao fazer upload dos documentos do pedido.');
        } finally {
            setIsUploading(false);
            e.target.value = '';
        }
    };

    const handleRemoveAttachment = (idx: number) => {
        setAttachments(attachments.filter((_, i) => i !== idx));
    };

    // Cálculo dinâmico de custos com IPI e Frete
    const processedItems = items.map((item) => {
        const rawBase = item.baseCost ?? item.unitCost;
        const baseCost = Number.isFinite(Number(rawBase)) ? Number(rawBase) : 0;
        const safeIpi = Number.isFinite(Number(ipiPercent)) ? Number(ipiPercent) : 0;
        const safeFreight = Number.isFinite(Number(freightPercent)) ? Number(freightPercent) : 0;
        const qty = Number.isFinite(Number(item.quantity)) ? Number(item.quantity) : 0;

        const itemIpi = baseCost * (safeIpi / 100);
        const itemFreight = baseCost * (safeFreight / 100);
        const itemUnitCost = baseCost + itemIpi + itemFreight;
        const itemTotalCost = qty * itemUnitCost;

        return {
            ...item,
            quantity: qty,
            unitCost: Number.isFinite(itemUnitCost) ? Number(itemUnitCost.toFixed(2)) : 0,
            totalCost: Number.isFinite(itemTotalCost) ? Number(itemTotalCost.toFixed(2)) : 0,
        };
    });

    const totalValue = processedItems.reduce((sum, item) => sum + (Number(item.totalCost) || 0), 0);


    const handleCancelOrClose = async () => {
        if (!activePurchase?.id && !draftId && items.length > 0) {
            try {
                const supplier = suppliers.find((s) => s.id === selectedSupplierId);
                const draftPurchase: Purchase = {
                    supplierId: selectedSupplierId,
                    supplierName: supplier?.fullName || 'Fornecedor Rascunho',
                    date: new Date(purchaseDate).toISOString(),
                    items: processedItems,
                    totalValue,
                    observation,
                    status: 'ordered',
                    invoiceNumber,
                    invoiceDate,
                    invoiceStatus: 'pending',
                    attachments: [...attachments],
                    ipiPercent,
                    freightPercent,
                };

                await savePurchase(draftPurchase);
                toast.info('Pedido de compra salvo como rascunho!');
            } catch (err: unknown) {
                console.error('Erro ao salvar rascunho de compra:', err);
            }
        }
        onClose();
    };

    useEffect(() => {
        if (!isOpen || activePurchase?.id || !items.length) return;
        const timer = window.setTimeout(async () => {
            setIsAutoSaving(true);
            try {
                const supplier = suppliers.find((item) => item.id === selectedSupplierId);
                const payload: Purchase = {
                    supplierId: selectedSupplierId,
                    supplierName: supplier?.fullName || 'Fornecedor Rascunho',
                    date: new Date(purchaseDate).toISOString(),
                    items: processedItems,
                    totalValue,
                    observation,
                    status: 'ordered',
                    invoiceNumber,
                    invoiceDate,
                    invoiceStatus: 'pending',
                    attachments: [...attachments],
                    ipiPercent,
                    freightPercent,
                };
                if (draftId) {
                    await updatePurchase(draftId, payload);
                } else {
                    const savedId = await savePurchase(payload);
                    if (savedId) setDraftId(savedId);
                }
            } catch (error: unknown) {
                console.error('Erro ao salvar rascunho automático:', error);
            } finally {
                setIsAutoSaving(false);
            }
        }, 700);
        return () => window.clearTimeout(timer);
    }, [
        isOpen,
        activePurchase?.id,
        items,
        selectedSupplierId,
        suppliers,
        purchaseDate,
        ipiPercent,
        freightPercent,
        attachments,
        draftId,
        totalValue,
    ]);

    const handleSave = async (status: 'ordered' | 'fulfilled') => {
        if (!selectedSupplierId || items.length === 0) {
            setValidationErrors({ supplier: !selectedSupplierId, items: items.length === 0 });
            toast.error(
                !selectedSupplierId && items.length === 0
                    ? 'Selecione o fornecedor e adicione pelo menos um item.'
                    : !selectedSupplierId
                    ? 'Selecione um fornecedor para salvar o pedido.'
                    : 'Adicione pelo menos um item ao pedido.'
            );
            return;
        }

        const supplier = suppliers.find((s) => s.id === selectedSupplierId);

        setIsSaving(true);
        try {
            const purchasePayload: Purchase = {
                supplierId: selectedSupplierId,
                supplierName: supplier?.fullName || activePurchase?.supplierName || 'Fornecedor',
                date: new Date(purchaseDate).toISOString(),
                items: processedItems,
                totalValue,
                observation,
                status: activePurchase?.status === 'cancelled' ? 'cancelled' : status,
                invoiceNumber: invoiceNumber || activePurchase?.invoiceNumber,
                invoiceDate: invoiceDate || activePurchase?.invoiceDate,
                invoiceStatus: status === 'fulfilled' ? 'received' : activePurchase?.invoiceStatus || 'pending',
                fiscalKey: '',
                attachments: [...attachments],
                ipiPercent,
                freightPercent,
            };

            const purchaseId = activePurchase?.id || draftId;
            const hasOnlyRegisteredProducts = processedItems.every((item) =>
                products.some((product) => String(product.id) === String(item.productId))
            );
            if (purchaseId) {
                await updatePurchase(purchaseId, purchasePayload);
                toast.success('Pedido de compra atualizado com sucesso!');
            } else {
                const savedId = await savePurchase(purchasePayload);
                let message = savedId ? 'Pedido de compra confirmado!' : 'Não foi possível salvar o pedido de compra.';
                if (!hasOnlyRegisteredProducts) {
                    message += ' Há item temporário para vincular antes do recebimento.';
                }
                toast.success(message);
            }
            onClose();
        } catch (error: unknown) {
            console.error('Erro ao salvar compra:', error);
            const message = error instanceof Error ? error.message : 'Erro ao salvar o pedido de compra.';
            toast.error(message);
        } finally {
            setIsSaving(false);
        }
    };

    if (!isOpen) return null;

    const modalContent = (
        <div
            className="fixed inset-0 z-[999999] flex items-center justify-center p-0 xl:p-6"
            role="dialog"
            aria-modal="true"
            aria-label={activePurchase?.id ? `Editar Pedido #${activePurchase.purchaseNumber || activePurchase.id.slice(-4)}` : 'Novo Pedido de Compra'}
        >
            <button
                type="button"
                className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in border-0 cursor-default"
                onClick={handleCancelOrClose}
                aria-label="Fechar pedido de compra"
            />

            <div className="relative bg-white dark:bg-slate-900 w-full h-full xl:h-auto xl:max-h-[90vh] xl:max-w-7xl rounded-none xl:rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-slide-up border-0 xl:border border-slate-100 dark:border-slate-800 transition-all">

                {/* Header Compacto */}
                <div className="px-4 py-3 sm:px-6 sm:py-3.5 xl:px-8 xl:py-5 bg-blue-600 text-white flex items-center justify-between gap-3 shrink-0 shadow-sm">
                    <div className="min-w-0">
                        <div className="flex items-center gap-2.5 flex-wrap">
                            <h2 className="text-base sm:text-lg xl:text-xl font-black tracking-tight uppercase truncate">
                                {activePurchase?.id
                                    ? `Editar Pedido #${activePurchase.purchaseNumber || activePurchase.id.slice(-4)}`
                                    : 'Novo Pedido de Compra'}
                            </h2>
                            {activePurchase?.status && (
                                <span
                                    className={`px-2.5 py-0.5 rounded-full text-[9px] sm:text-[10px] font-black uppercase tracking-wider ${
                                        activePurchase.status === 'fulfilled'
                                            ? 'bg-emerald-500/20 text-emerald-100 border border-emerald-400/30'
                                            : activePurchase.status === 'ordered'
                                            ? 'bg-white/20 text-white border border-white/30'
                                            : 'bg-red-500/20 text-red-100 border border-red-400/30'
                                    }`}
                                >
                                    {activePurchase.status === 'fulfilled'
                                        ? 'Atendido'
                                        : activePurchase.status === 'ordered'
                                        ? 'Em Ordem'
                                        : 'Cancelado'}
                                </span>
                            )}
                        </div>
                        <p className="hidden xl:block text-[10px] font-black uppercase tracking-[0.15em] text-blue-200 mt-0.5">
                            {activePurchase?.id
                                ? `Alteração de dados e itens • ${activePurchase.supplierName}`
                                : 'Entrada de mercadorias via fornecedor'}
                        </p>
                    </div>
                    <div className="flex items-center gap-2 shrink-0">
                        <button
                            type="button"
                            onClick={handleCancelOrClose}
                            className="p-1.5 sm:p-2 hover:bg-white/10 rounded-xl transition-colors"
                            aria-label="Fechar modal"
                        >
                            <i className="bi bi-x-lg text-lg" aria-hidden="true" />
                        </button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-6 xl:p-8 space-y-8 custom-scrollbar">
                    {/* Supplier, Date, IPI & Freight */}
                    <div className="grid grid-cols-1 md:grid-cols-5 gap-6 items-end">
                        <div className="md:col-span-2 flex flex-col gap-2">
                            <SupplierAutocomplete
                                suppliers={[...suppliers]}
                                selectedSupplierId={selectedSupplierId}
                                onSelect={setSelectedSupplierId}
                                disabled={items.length > 0}
                                disabledReason="Para alterar o fornecedor, remova todos os itens do pedido."
                                placeholder="Buscar fornecedor..."
                                inputClassName="w-full bg-transparent border-0 border-b-2 border-slate-200 dark:border-slate-700 p-2 focus:border-blue-600 dark:focus:border-blue-500 outline-none text-sm font-bold text-slate-700 dark:text-slate-300 transition-all focus:ring-0 focus:shadow-sm rounded-none"
                            />
                            {validationErrors.supplier && (
                                <span className="text-xs font-bold text-red-500">Selecione um fornecedor.</span>
                            )}
                        </div>
                        <div className="flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                Data do Pedido
                            </label>
                            <input
                                type="date"
                                value={purchaseDate}
                                onChange={(e) => setPurchaseDate(e.target.value)}
                                className="w-full bg-transparent border-0 border-b-2 border-slate-200 dark:border-slate-700 p-2 focus:border-blue-600 dark:focus:border-blue-500 outline-none text-sm font-bold text-slate-700 dark:text-slate-200 transition-all focus:ring-0 rounded-none"
                            />
                        </div>
                        <div className="flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                IPI (%)
                            </label>
                            <div className="relative border-0 border-b-2 border-slate-200 dark:border-slate-700 focus-within:border-blue-600 dark:focus-within:border-blue-500 transition-all">
                                <input
                                    type="number"
                                    placeholder="0"
                                    value={ipiPercent || ''}
                                    onChange={(e) => setIpiPercent(Number(e.target.value))}
                                    className="w-full bg-transparent p-2 outline-none font-bold text-sm text-slate-700 dark:text-slate-200 border-none focus:ring-0 rounded-none"
                                />
                                <div className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 font-bold text-xs select-none">
                                    %
                                </div>
                            </div>
                        </div>
                        <div className="flex flex-col gap-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                Frete (%)
                            </label>
                            <div className="relative border-0 border-b-2 border-slate-200 dark:border-slate-700 focus-within:border-blue-600 dark:focus-within:border-blue-500 transition-all">
                                <input
                                    type="number"
                                    placeholder="0"
                                    value={freightPercent || ''}
                                    onChange={(e) => setFreightPercent(Number(e.target.value))}
                                    className="w-full bg-transparent p-2 outline-none font-bold text-sm text-slate-700 dark:text-slate-200 border-none focus:ring-0 rounded-none"
                                />
                                <div className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 font-bold text-xs select-none">
                                    %
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Documento do pedido */}
                    <div className="flex flex-col gap-4 border-t border-slate-100 dark:border-slate-800/30 pt-6">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
                            {/* Lado esquerdo: Upload e Listagem de arquivos */}
                            <div className="flex flex-col gap-2 w-full">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">
                                    Anexar documento do pedido (PDF ou imagem · máx. 5)
                                </label>
                                <label
                                    className={`flex flex-col items-center justify-center border-2 border-dashed rounded-2xl p-4 text-center cursor-pointer transition-all hover:bg-slate-50/20 dark:hover:bg-slate-950/10 ${
                                        attachments.length >= 5
                                            ? 'opacity-50 pointer-events-none border-slate-200'
                                            : 'border-slate-300 dark:border-slate-800 hover:border-blue-500'
                                    }`}
                                >
                                    <i
                                        className={`bi ${
                                            isUploading ? 'bi-arrow-repeat animate-spin' : 'bi-cloud-arrow-up-fill'
                                        } text-blue-600 dark:text-blue-400 text-2xl mb-1`}
                                        aria-hidden="true"
                                    />
                                    <span className="text-xs font-bold text-slate-700 dark:text-slate-300">
                                        {isUploading
                                            ? 'Enviando arquivos...'
                                            : 'Arraste ou clique para anexar documento do pedido'}
                                    </span>
                                    <span className="text-[10px] text-slate-400 mt-0.5">
                                        Formatos: PDF, PNG, JPG (Enviados: {attachments.length}/5)
                                    </span>
                                    <input
                                        type="file"
                                        multiple
                                        accept="application/pdf,image/*"
                                        onChange={handleFileUpload}
                                        disabled={isUploading || attachments.length >= 5}
                                        className="hidden"
                                    />
                                </label>

                                {attachments.length > 0 && (
                                    <div className="grid grid-cols-1 gap-2 mt-2">
                                        {attachments.map((url, idx) => {
                                            const fileName =
                                                url.split('/').pop()?.slice(-25) ||
                                                `Documento do pedido #${idx + 1}`;
                                            return (
                                                <div
                                                    key={idx}
                                                    className="flex items-center justify-between p-3 bg-slate-50/50 dark:bg-slate-950/30 border border-slate-100 dark:border-slate-800/50 rounded-xl gap-3 shadow-sm animate-slide-up"
                                                >
                                                    <div className="flex items-center gap-3 min-w-0 flex-1">
                                                        <i
                                                            className="bi bi-file-earmark-pdf-fill text-red-500 shrink-0 text-base"
                                                            aria-hidden="true"
                                                        />
                                                        <a
                                                            href={url}
                                                            target="_blank"
                                                            rel="noopener noreferrer"
                                                            className="text-xs font-bold text-slate-700 dark:text-slate-300 hover:text-blue-600 dark:hover:text-blue-400 truncate hover:underline"
                                                        >
                                                            {fileName}
                                                        </a>
                                                    </div>
                                                    <button
                                                        type="button"
                                                        onClick={() => handleRemoveAttachment(idx)}
                                                        className="p-1 hover:bg-red-50 dark:hover:bg-red-950/20 text-red-500 rounded-lg transition-colors shrink-0"
                                                        title="Remover anexo"
                                                        aria-label="Remover anexo"
                                                    >
                                                        <i className="bi bi-trash text-xs" aria-hidden="true" />
                                                    </button>
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Section of Purchase Items */}
                    <PurchaseItemsSection
                        items={[...items]}
                        onAddItem={handleAddItem}
                        onRemoveItem={handleRemoveItem}
                        ipiPercent={ipiPercent}
                        freightPercent={freightPercent}
                        formatCurrency={formatCurrency}
                        supplierId={selectedSupplierId}
                        onSupplierAutoSelect={(supId) => setSelectedSupplierId(supId)}
                        hasError={validationErrors.items}
                    />
                </div>

                {/* Footer Actions */}
                <div className="p-6 xl:p-8 bg-slate-50 dark:bg-slate-950/40 border-t border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row justify-between items-center gap-4 shrink-0">
                    {!activePurchase?.id && (
                        <p className="text-xs font-bold text-slate-400">
                            <i
                                className={`bi ${
                                    isAutoSaving ? 'bi-arrow-repeat animate-spin' : 'bi-cloud-check-fill'
                                } mr-1.5 text-blue-500`}
                                aria-hidden="true"
                            />
                            Rascunho: salvo automaticamente
                        </p>
                    )}
                    <button
                        type="button"
                        onClick={handleCancelOrClose}
                        className="w-full sm:w-auto px-6 py-3.5 bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 font-bold rounded-2xl border border-slate-200 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors"
                    >
                        Cancelar / Fechar
                    </button>
                    <div className="flex gap-3 w-full sm:w-auto justify-end">
                        <button
                            type="button"
                            onClick={() =>
                                handleSave(activePurchase?.status === 'fulfilled' ? 'fulfilled' : 'ordered')
                            }
                            disabled={isSaving}
                            className="w-full sm:w-auto px-8 py-3.5 bg-blue-600 text-white font-bold rounded-2xl hover:bg-blue-700 transition-all shadow-lg shadow-blue-200 dark:shadow-none flex items-center justify-center gap-2"
                        >
                            <i className="bi bi-check2-circle text-lg" aria-hidden="true" />
                            <span>{activePurchase?.id ? 'Salvar Alterações' : 'Confirmar Pedido'}</span>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );

    return typeof document !== 'undefined' ? createPortal(modalContent, document.body) : modalContent;
};

export default PurchaseFormModal;

[Divergência: ${discrepancyNote}]`
                    : purchase.observation,
            });

            toast.success('Conferência salva. Registre o recebimento em Recebimentos de Mercadorias para movimentar o estoque.');
            onClose();
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : 'Erro ao salvar conferência.';
            toast.error(message);
        } finally {
            setIsSaving(false);
        }
    };

    return (
        <div
            className="fixed inset-0 z-[999999] flex items-center justify-center p-2 sm:p-4 xl:p-6"
            role="dialog"
            aria-modal="true"
            aria-label="Conferência de Compra"
        >
            <button
                type="button"
                className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm animate-fade-in border-0 cursor-default"
                onClick={onClose}
                aria-label="Fechar conferência de compra"
            />

            <div className="relative bg-white dark:bg-slate-900 w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-slide-up border border-slate-100 dark:border-slate-800 flex flex-col max-h-[90vh]">
                <div className="p-8 bg-blue-600 text-white flex items-center justify-between shrink-0">
                    <div>
                        <h2 className="text-2xl font-black tracking-tight uppercase">
                            3-Way Match: Conferência de Compra
                        </h2>
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-200 mt-1">
                            Pedido #{purchase.id?.slice(-4)} • {purchase.supplierName} • {formatToBRDate(purchase.date)}
                        </p>
                    </div>
                    <div className="flex gap-4">
                        <button
                            type="button"
                            onClick={handlePrint}
                            className="bg-white/20 hover:bg-white/30 text-white px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-all"
                        >
                            <i className="bi bi-printer" aria-hidden="true" />
                            Imprimir
                        </button>
                        <button
                            type="button"
                            onClick={() => setIsScannerOpen(true)}
                            className="bg-white/20 hover:bg-white/30 text-white px-5 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 transition-all"
                        >
                            <i className="bi bi-qr-code-scan" aria-hidden="true" />
                            Escanear
                        </button>
                        <button
                            type="button"
                            onClick={onClose}
                            className="p-2 hover:bg-white/10 rounded-xl transition-colors"
                            aria-label="Fechar modal"
                        >
                            <i className="bi bi-x-lg text-xl" aria-hidden="true" />
                        </button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
                    {/* NF Info Header */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 p-6 bg-slate-50 dark:bg-slate-900/50 rounded-[2rem] border border-slate-100 dark:border-slate-800">
                        <div className="flex flex-col gap-2">
