                    <div className="space-y-4">
                        <div className="grid grid-cols-12 px-6 text-[9px] font-black uppercase tracking-widest text-slate-400">
                            <div className="col-span-5">Produto</div>
                            <div className="col-span-2 text-center">Pedido</div>
                            <div className="col-span-2 text-center">NF (Faturado)</div>
                            <div className="col-span-3 text-center">Físico (Recebido)</div>
                        </div>

                        {purchase.items.map((item, index) => {
                            const key = item.productId + (item.variationId || '');
                            const received = scannedItems[key] || 0;
                            const invoiced = invoicedQuantities[key] || 0;
                            const isMatch = received === item.quantity && received === invoiced;
                            const hasDivergence = received !== item.quantity || received !== invoiced;

                            return (
                                <div
                                    key={index}
                                    className={`p-5 rounded-[1.5rem] border transition-all ${
                                        isMatch
                                            ? 'bg-emerald-50/50 border-emerald-100 dark:bg-emerald-900/10'
                                            : hasDivergence
                                            ? 'bg-amber-50/50 border-amber-100 dark:bg-amber-900/10'
                                            : 'bg-slate-50 border-slate-100 dark:bg-slate-900/50'
                                    }`}
                                >
                                    <div className="grid grid-cols-12 items-center gap-4">
                                        <div className="col-span-5 flex items-center gap-3">
                                            <div
                                                className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                                                    isMatch
                                                        ? 'bg-emerald-100 text-emerald-600'
                                                        : hasDivergence
                                                        ? 'bg-amber-100 text-amber-600'
                                                        : 'bg-blue-100 text-blue-600'
                                                }`}
                                            >
                                                <i
                                                    className={`bi ${
                                                        isMatch
                                                            ? 'bi-check-lg'
                                                            : hasDivergence
                                                            ? 'bi-exclamation-triangle'
                                                            : 'bi-box-seam'
                                                    } text-lg`}
                                                    aria-hidden="true"
                                                />
                                            </div>
                                            <div className="min-w-0">
                                                <h4 className="text-xs font-bold text-slate-800 dark:text-slate-100 truncate">
                                                    {item.description}
                                                </h4>
                                                {hasDivergence && (
                                                    <p className="text-[9px] font-black text-amber-600 dark:text-amber-400 mt-0.5 animate-pulse uppercase tracking-tighter">
                                                        Divergência
                                                    </p>
                                                )}
                                            </div>
                                        </div>

                                        <div className="col-span-2 text-center text-xs font-black text-slate-400">
                                            {item.quantity}
                                        </div>

                                        <div className="col-span-2 flex justify-center">
                                            <input
                                                type="number"
                                                value={invoiced}
                                                onChange={(e) => updateInvoicedQty(key, Number(e.target.value))}
                                                className="w-14 h-9 text-center bg-white dark:bg-slate-950 border border-slate-100 dark:border-slate-800 rounded-xl font-black text-xs text-slate-600 dark:text-slate-300 outline-none focus:ring-2 focus:ring-blue-500"
                                            />
                                        </div>

                                        <div className="col-span-3 flex justify-center">
                                            <div className="flex items-center bg-white dark:bg-slate-950 rounded-xl border border-slate-100 dark:border-slate-800 overflow-hidden shadow-sm">
                                                <button
                                                    type="button"
                                                    onClick={() => updateReceivedQty(key, Math.max(0, received - 1))}
                                                    className="w-10 h-9 flex items-center justify-center text-slate-400 hover:text-red-500 transition-all font-black"
                                                    aria-label="Diminuir recebimento"
                                                >
                                                    <i className="bi bi-dash text-lg" aria-hidden="true" />
                                                </button>
                                                <input
                                                    type="number"
                                                    value={received}
                                                    onChange={(e) => updateReceivedQty(key, Number(e.target.value))}
                                                    className={`w-12 h-9 text-center bg-transparent border-none outline-none font-black text-xs ${
                                                        received === invoiced
                                                            ? 'text-emerald-600 font-black'
                                                            : 'text-amber-600 font-black'
                                                    }`}
                                                />
                                                <button
                                                    type="button"
                                                    onClick={() => updateReceivedQty(key, received + 1)}
                                                    className="w-10 h-9 flex items-center justify-center text-slate-400 hover:text-emerald-500 transition-all font-black"
                                                    aria-label="Aumentar recebimento"
                                                >
                                                    <i className="bi bi-plus text-lg" aria-hidden="true" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>

                <div className="p-8 border-t border-slate-50 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 shrink-0">
                    <button
                        type="button"
                        onClick={handleSave}
                        disabled={isSaving}
                        className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-3xl font-black uppercase tracking-widest shadow-xl shadow-blue-200 dark:shadow-none transition-all active:scale-95 disabled:opacity-50 flex items-center justify-center gap-3"
                    >
                        {isSaving ? (
                            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        ) : (
                            <i className="bi bi-check-lg text-xl" aria-hidden="true" />
                        )}
                        Finalizar Conferência
                    </button>
                </div>
            </div>

            <ErrorBoundary name="Scanner de Recebimento">
                <QRScannerModal
                    isOpen={isScannerOpen}
                    onClose={() => setIsScannerOpen(false)}
                    onScan={handleScan}
                    closeOnScan={false}
                    title="Escanear Itens do Pedido"
                />
            </ErrorBoundary>
        </div>
    );
};

export default PurchaseReceiptCheckModal;

import React, { useState, useEffect, useMemo } from 'react';
import Person from '../../../../types/person.type';
import { subscribeToPeople } from '@/pages/utils/personService';
import { normalizeSearchTerm } from '@/pages/utils/textUtils';

export interface SupplierSearchModalProps {
    readonly onSelect: (supplier: Person) => void;
    readonly onClose: () => void;
}

/**
 * Modal de busca e seleção de fornecedores ativos para inclusão em pedidos de compra.
 */
export const SupplierSearchModal: React.FC<SupplierSearchModalProps> = ({ onSelect, onClose }) => {
    const [search, setSearch] = useState('');
    const [suppliers, setSuppliers] = useState<readonly Person[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const unsub = subscribeToPeople('suppliers', (data) => {
            setSuppliers(data.filter((p) => p.active && !p.deleted && p.type === 'suppliers'));
            setLoading(false);
        });

        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                onClose();
            }
        };

        window.addEventListener('keydown', handleKeyDown);

        return () => {
            if (unsub) unsub();
            window.removeEventListener('keydown', handleKeyDown);
        };
    }, [onClose]);

    const filtered = useMemo(() => {
        if (!search.trim()) return suppliers;
        const s = normalizeSearchTerm(search);
        return suppliers.filter(
            (e) =>
                normalizeSearchTerm(e.fullName || '').includes(s) ||
                normalizeSearchTerm(e.tradeName || '').includes(s) ||
                (e.cpfCnpj || '').includes(s)
        );
    }, [suppliers, search]);

    return (
        <div
            className="fixed inset-0 z-[200] flex items-center justify-center p-4"
            role="dialog"
            aria-modal="true"
            aria-label="Selecionar Fornecedor"
        >
            <button
                type="button"
                className="absolute inset-0 bg-slate-900/60 backdrop-blur-[3px] animate-fade-in border-0 cursor-default"
                onClick={onClose}
                aria-label="Fechar seleção de fornecedor"
            />
            <div
                className="relative bg-white dark:bg-slate-900 w-full max-w-2xl rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-slide-up border border-slate-100 dark:border-slate-800 max-h-[85vh]"
            >

                {/* Header */}
                <div className="px-8 py-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-blue-50 dark:bg-blue-900/10 shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="bg-blue-600 p-2.5 rounded-2xl shadow-lg shadow-blue-200 dark:shadow-blue-900/30">
                            <i className="bi bi-truck text-white text-xl" aria-hidden="true" />
                        </div>
                        <div>
                            <h2 className="text-lg font-black text-slate-800 dark:text-slate-100 tracking-tight">
                                Selecionar Fornecedor
                            </h2>
                            <p className="text-[10px] uppercase font-black text-blue-600 dark:text-blue-400 tracking-widest mt-0.5">
                                Pesquise entre os canais de suprimento
                            </p>
                        </div>
                    </div>
                    <button
                        type="button"
                        onClick={onClose}
                        className="p-2 hover:bg-blue-100 dark:hover:bg-blue-900/30 rounded-full transition-colors text-slate-400 hover:text-slate-600"
                        aria-label="Fechar modal"
                    >
                        <i className="bi bi-x-lg text-xl" aria-hidden="true" />
                    </button>
                </div>

                {/* Search Bar */}
                <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 shrink-0">
                    <div className="relative">
                        <i className="bi bi-search absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input
                            autoFocus
                            type="text"
                            placeholder="Busque por nome, razão social ou CNPJ..."
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            className="w-full pl-11 pr-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-2xl text-sm font-bold text-slate-700 dark:text-slate-300 focus:outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-500 transition-all placeholder:font-normal placeholder:text-slate-400"
                        />
                        {search && (
                            <button
                                type="button"
                                onClick={() => setSearch('')}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
                                aria-label="Limpar pesquisa"
                            >
                                <i className="bi bi-x-circle-fill" aria-hidden="true" />
                            </button>
                        )}
                    </div>
                    <div className="flex items-center gap-4 mt-3 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        <span className="ml-auto">
                            {loading ? 'Carregando...' : `${filtered.length} fornecedor(es) encontrados`}
                        </span>
                    </div>
                </div>

                {/* List */}
                <div className="flex-1 overflow-y-auto custom-scrollbar bg-white dark:bg-slate-900 p-4">
                    {loading ? (
                        <div className="flex items-center justify-center py-16 gap-3 text-slate-400">
                            <i className="bi bi-hourglass-split animate-spin text-2xl" aria-hidden="true" />
                            <span className="text-sm font-bold">Carregando fornecedores...</span>
                        </div>
                    ) : filtered.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-16 text-slate-400 gap-3">
                            <i className="bi bi-truck-flatbed text-4xl opacity-30" aria-hidden="true" />
                            <p className="text-sm font-bold">Nenhum fornecedor encontrado</p>
                        </div>
                    ) : (
                        <div className="flex flex-col gap-2">
                            {filtered.map((sup) => (
                                <button
                                    type="button"
                                    key={sup.id}
                                    onClick={() => {
                                        onSelect(sup);
                                        onClose();
                                    }}
                                    className="flex items-center justify-between p-4 rounded-3xl border border-slate-100 dark:border-slate-800 hover:bg-blue-50 dark:hover:bg-blue-900/20 hover:border-blue-200 dark:hover:border-blue-800/50 transition-all group text-left"
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 rounded-2xl bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center text-blue-600 dark:text-blue-400 font-black text-xs uppercase">
                                            {sup.fullName?.substring(0, 2)}
                                        </div>
                                        <div className="flex flex-col gap-0.5">
                                            <span className="text-sm font-black text-slate-800 dark:text-slate-100 group-hover:text-blue-700 dark:group-hover:text-blue-300 transition-colors">
                                                {sup.fullName}
                                            </span>
                                            <div className="flex gap-2 items-center">
                                                {sup.tradeName && (
                                                    <span className="text-[10px] uppercase font-black tracking-widest text-slate-400">
                                                        {sup.tradeName}
                                                    </span>
                                                )}
                                                {sup.cpfCnpj && (
                                                    <span className="text-xs font-medium text-slate-500 flex items-center gap-1">
                                                        <i className="bi bi-card-text text-[10px]" aria-hidden="true" />
                                                        {sup.cpfCnpj}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                    <i className="bi bi-chevron-right text-slate-300 group-hover:text-blue-500 transition-colors" aria-hidden="true" />
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-6 py-4 border-t border-slate-100 dark:border-slate-800 shrink-0 flex items-center justify-between bg-slate-50/50 dark:bg-slate-900/50">
                    <p className="text-[10px] text-slate-400 font-bold">
                        Clique em um fornecedor para selecioná-lo
                    </p>
                    <button
                        type="button"
                        onClick={onClose}
                        className="px-4 py-2 text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-red-500 transition-colors"
                    >
                        Cancelar
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SupplierSearchModal;

import { toast } from 'react-toastify';
import ProductAutocomplete from '@/components/ProductAutocomplete';
import type Product from '@/pages/types/product.type';
import type { Variation } from '@/pages/types/product.type';

export type InboundReceiptItemComposition = {
    id: string;
    productId: string;
    variationId?: string;
    productName: string;
    quantity: number;
    referenceSalePrice: number;
};

interface CompositionManagerProps {
    composition: InboundReceiptItemComposition[];
    onChangeComposition: (newComposition: InboundReceiptItemComposition[]) => void;
    totalItemCost: number;
}

export function InboundCompositionManager({ composition, onChangeComposition, totalItemCost }: CompositionManagerProps) {
    const handleAdd = (prod: Product, variation?: Variation) => {
        const salePrice = variation?.unitPrice || prod.unitPrice || 0;

        const exists = composition.some(c => c.productId === prod.id && c.variationId === variation?.id);
        if (exists) {
            toast.error('Este produto já está na composição. Altere a quantidade se necessário.');
            return;
        }

        const newComp: InboundReceiptItemComposition = {
            id: crypto.randomUUID(),
            productId: prod.id!,
            variationId: variation?.id,
            productName: variation?.name || prod.name || prod.title || 'Produto',
            quantity: 1,
            referenceSalePrice: salePrice,
        };
        onChangeComposition([...composition, newComp]);
    };

    const handleRemove = (id: string) => {
        onChangeComposition(composition.filter(c => c.id !== id));
    };

    const handleUpdateQuantity = (id: string, qty: number) => {
        onChangeComposition(composition.map(c => c.id === id ? { ...c, quantity: Math.max(1, qty) } : c));
    };

    const totalWeightBase = composition.reduce((sum, c) => sum + (c.referenceSalePrice * c.quantity), 0);

    return (
        <div className="space-y-3">
            {composition.length > 0 && (
                <div className="flex flex-col gap-2">
                    {composition.map((c, idx) => {
                        const weightValue = c.referenceSalePrice * c.quantity;
                        const weightPercent = totalWeightBase > 0 ? (weightValue / totalWeightBase) : 0;

                        // Último item absorve a diferença para evitar dízimas que somadas não fecham o total
                        let rateio = 0;
                        if (idx === composition.length - 1) {
                            const previousRateioSum = composition.slice(0, -1).reduce((sum, prevC) => {
                                const w = totalWeightBase > 0 ? ((prevC.referenceSalePrice * prevC.quantity) / totalWeightBase) : 0;
                                return sum + Number((totalItemCost * w).toFixed(2));
                            }, 0);
                            rateio = Math.max(0, totalItemCost - previousRateioSum);
                        } else {
                            rateio = Number((totalItemCost * weightPercent).toFixed(2));
                        }

                        return (
                            <div key={c.id} className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-3 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl hover:bg-slate-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                <div className="flex items-center gap-3 flex-1 overflow-hidden">
                                    <button type="button" onClick={() => handleRemove(c.id)} className="text-slate-400 hover:text-red-500 transition-colors shrink-0 outline-none">
                                        <i className="bi bi-trash3-fill text-sm"></i>
                                    </button>

                                    <div className="w-16 shrink-0">
                                        <input
                                            type="number"
                                            min="1"
                                            value={c.quantity}
                                            onChange={(e) => handleUpdateQuantity(c.id, Number(e.target.value))}
                                            className="w-full text-center bg-transparent border-b border-slate-300 dark:border-slate-600 outline-none focus:border-blue-500 font-bold"
                                        />
                                    </div>

                                    <span className="text-[10px] font-bold text-emerald-700 bg-emerald-50 dark:bg-emerald-900/30 border border-emerald-200 dark:border-emerald-800 rounded-full px-2 py-0.5 truncate max-w-full">
                                        {c.productName}
                                    </span>
                                </div>

                                <div className="flex items-center gap-4 text-[10px] shrink-0 justify-end sm:justify-start">
                                    <div className="flex flex-col text-right">
                                        <span className="text-slate-400 uppercase tracking-widest text-[8px] font-black">Preço Ref.</span>
                                        <span className="font-bold text-slate-600 dark:text-slate-300">R$ {c.referenceSalePrice.toFixed(2)} un</span>
                                    </div>
                                    <div className="flex flex-col text-right">
                                        <span className="text-slate-400 uppercase tracking-widest text-[8px] font-black">Rateio</span>
                                        <span className="font-black text-emerald-600 dark:text-emerald-400">R$ {rateio.toFixed(2)}</span>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            <ProductAutocomplete
                value=""
                clearOnSelect={true}
                onSelect={handleAdd}
                placeholder="Buscar produto para compor o item..."
            />

            {composition.length === 0 && (
                <p className="text-[10px] text-amber-600 bg-amber-50 dark:bg-amber-900/30 p-2 rounded-lg border border-amber-200 dark:border-amber-800/50 flex items-center gap-2">
                    <i className="bi bi-exclamation-triangle-fill"></i>
                    Adicione pelo menos um produto para formar a composição.
                </p>
            )}
            {composition.some(c => c.referenceSalePrice <= 0) && (
                <p className="text-[10px] text-amber-600 bg-amber-50 dark:bg-amber-900/30 p-2 rounded-lg border border-amber-200 dark:border-amber-800/50 flex items-center gap-2 mt-1">
                    <i className="bi bi-info-circle-fill"></i>
                    Alguns itens estão com preço de venda zerado. Isso afetará o cálculo de rateio.
                </p>
            )}
        </div>
    );
}

export default InboundCompositionManager;

import ProductAutocomplete from '@/components/ProductAutocomplete';
import CurrencyInput from '@/components/CurrencyInput';
import type { PurchaseItem } from '@/pages/types/purchase.type';
import { InboundCompositionManager } from './InboundCompositionManager';
import type { InboundReceiptItem } from './InboundNfeItemsSection';

interface InboundReceiptItemRowProps {
    readonly item: InboundReceiptItem;
    readonly processedItem?: PurchaseItem;
    readonly onChange: (itemNumber: number, update: Partial<InboundReceiptItem>) => void;
    readonly formatCurrency: (value: number) => string;
    readonly onQuickRegister: (itemNumber: number, item: InboundReceiptItem) => void;
}

export function InboundReceiptItemRow({
    item,
    processedItem,
    onChange,
    formatCurrency,
    onQuickRegister,
}: InboundReceiptItemRowProps) {
    const quantity = Math.max(1, item.quantity);
    const unitDiscount = processedItem?.discountUnit || 0;
    const unitFreight = processedItem?.freightUnit ?? ((item.freightValue || 0) / quantity);
    const unitOther = processedItem?.otherExpensesUnit ?? ((item.totalAdditionalCosts || 0) / quantity);
    const totalUnit = processedItem
        ? processedItem.unitCost
        : Math.max(0, item.unitCost - unitDiscount + (item.ipiValue || 0) / quantity + unitFreight + unitOther);
    const totalItem = processedItem ? processedItem.totalCost : totalUnit * item.quantity;
    const itemSubtotal = item.quantity * item.unitCost;

    return (
        <div className="p-5 space-y-3.5 hover:bg-slate-50/40 dark:hover:bg-slate-800/20 transition-colors">
            {/* Bloco Superior: Produto da NF-e e vínculo com ERP */}
            <div className="grid gap-4 lg:grid-cols-2">
                {/* Lado esquerdo: informações da NF-e */}
                <div className="space-y-1.5">
                    <div className="flex flex-wrap items-center gap-2">
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Produto da NF-e</span>
                        {item.unit && (
                            <span className="rounded-md bg-slate-100 px-1.5 py-0.5 text-[9px] font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-300 uppercase">
                                UN: {item.unit}
                            </span>
                        )}
                        {(item as unknown as Record<string, unknown>).code && (
                            <span className="rounded-md bg-slate-100 px-1.5 py-0.5 text-[9px] font-mono font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-300">
                                Cód. Fornecedor: {String((item as unknown as Record<string, unknown>).code)}
                            </span>
                        )}
                    </div>
                    <p className="text-sm font-black text-slate-800 dark:text-slate-100 leading-snug">
                        {item.productDescription}
                    </p>
                </div>

