    const [invoices, setInvoices] = useState<InboundInvoice[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [mappingInvoice, setMappingInvoice] = useState<InboundInvoice | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [loadError, setLoadError] = useState('');
    const [dateFilter, setDateFilter] = useState<DateFilterConfig>(() => ({
        mode: 'current_month',
        customMonth: getCurrentYearMonth(),
        startMonth: getPreviousYearMonth(),
        endMonth: getCurrentYearMonth(),
    }));

    useEffect(() => {
        if (!isOpen) return;
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, onClose]);

    const loadInvoices = async () => {
        setIsLoading(true);
        setLoadError('');
        try {
            const list = await fetchInboundInvoices();
            setInvoices(list);
        } catch (e: unknown) {
            console.error('Erro ao carregar NF-e para recebimento:', e);
            setLoadError('Não foi possível carregar as notas fiscais. Tente novamente.');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        if (isOpen) {
            void loadInvoices();
        }
    }, [isOpen]);

    const available = useMemo(() => {
        const term = normalizeSearchTerm(searchTerm);
        const termDigits = normalizeDigits(searchTerm);
        return invoices
            .filter((inv) => inv.status !== 'received')
            .filter((inv) => isInDateFilter(inv.issuedAt, dateFilter))
            .filter((inv) => {
                if (!term) return true;
                const emitter = normalizeSearchTerm(inv.emitterName || '');
                const cnpj = normalizeDigits(inv.emitterCnpj || '');
                const key = normalizeDigits(inv.nfeKey || '');
                const number = normalizeDigits(inv.nfeNumber || '');
                return emitter.includes(term) || (termDigits.length > 0 && (cnpj.includes(termDigits) || number.includes(termDigits) || key.includes(termDigits)));
            })
            .sort((left, right) => Number(new Date(right.issuedAt)) - Number(new Date(left.issuedAt)));
    }, [invoices, searchTerm, dateFilter]);

    if (!isOpen) return null;

    return (
        <div
            className="fixed inset-0 z-[1000001] flex items-center justify-center p-4 animate-in fade-in"
            role="dialog"
            aria-modal="true"
            aria-labelledby="inbound-invoice-picker-title"
        >
            <button
                type="button"
                aria-label="Fechar seleção de nota fiscal de entrada"
                onClick={onClose}
                className="absolute inset-0 bg-slate-950/60 backdrop-blur-sm cursor-default border-0 p-0 m-0 w-full h-full"
            />
            <section className="relative max-h-[88vh] w-full max-w-3xl overflow-hidden rounded-3xl bg-white shadow-2xl dark:bg-slate-900 flex flex-col">
                <header className="flex items-center justify-between border-b border-slate-100 p-5 dark:border-slate-800">
                    <div className="flex items-center gap-3">
                        <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-600/10 text-indigo-600">
                            <i className="bi bi-file-earmark-arrow-down-fill text-lg" aria-hidden="true" />
                        </div>
                        <div>
                            <h3 id="inbound-invoice-picker-title" className="text-base font-black text-slate-800 dark:text-slate-100">
                                Usar Nota Fiscal de Entrada
                            </h3>
                            <p className="text-xs text-slate-400">
                                Selecione uma NF-e para importar fornecedor, chave e itens automaticamente
                            </p>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <button
                            type="button"
                            onClick={() => setIsCreateModalOpen(true)}
                            className="rounded-xl bg-emerald-600 px-3 py-1.5 text-xs font-black text-white shadow-sm hover:bg-emerald-700 transition-colors"
                        >
                            <i className="bi bi-plus-lg mr-1.5" aria-hidden="true" />
                            Cadastrar nova NF de entrada
                        </button>
                        <button
                            type="button"
                            onClick={onClose}
                            aria-label="Fechar"
                            className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                        >
                            <i className="bi bi-x-lg" aria-hidden="true" />
                        </button>
                    </div>
                </header>

                <div className="space-y-3 border-b border-slate-100 p-4 dark:border-slate-800">
                    <div className="relative">
                        <i className="bi bi-search absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 text-xs" aria-hidden="true" />
                        <input
                            type="text"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            placeholder="Emitente, CNPJ, nº da nota ou chave de acesso"
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pl-9 pr-4 text-xs font-medium text-slate-700 outline-none focus:bg-white focus:border-indigo-500 dark:border-slate-800 dark:bg-slate-950 dark:text-slate-200 transition-colors"
                        />
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        <div className="flex flex-wrap items-center gap-2 rounded-xl border border-slate-200 bg-white p-1.5 text-xs font-bold text-slate-700 shadow-sm dark:border-slate-800 dark:bg-slate-900 dark:text-slate-200">
                            <div className="flex items-center gap-1.5 px-2 py-1">
                                <i className="bi bi-calendar-event text-blue-600 dark:text-blue-400 text-sm" aria-hidden="true" />
                                <span className="text-slate-500 font-semibold">Período:</span>
                            </div>

                            <select
                                value={dateFilter.mode}
                                onChange={(e) => setDateFilter({ ...dateFilter, mode: e.target.value as DateFilterMode })}
                                className="rounded-lg bg-slate-100 px-3 py-1.5 text-xs font-bold text-slate-800 outline-none cursor-pointer border border-transparent focus:border-blue-500 dark:bg-slate-800 dark:text-slate-100"
                            >
                                <option value="current_month">Mês Atual</option>
                                <option value="previous_month">Mês Anterior</option>
                                <option value="current_year">Este Ano</option>
                                <option value="previous_year">Ano Passado</option>
                                <option value="custom_month">Outro Mês</option>
                                <option value="custom_range">Intervalo Personalizado</option>
                            </select>

                            {dateFilter.mode === 'custom_month' && (
                                <div className="flex items-center gap-1.5 pl-1">
                                    <input
                                        type="month"
                                        required
                                        value={dateFilter.customMonth}
                                        onChange={(e) => {
                                            if (e.target.value) {
                                                setDateFilter({
                                                    ...dateFilter,
                                                    customMonth: e.target.value,
                                                });
                                            }
                                        }}
                                        className="rounded-lg bg-slate-100 px-2.5 py-1 text-xs font-bold text-slate-800 outline-none cursor-pointer border border-slate-200 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                                    />
                                </div>
                            )}

                            {dateFilter.mode === 'custom_range' && (
                                <div className="flex items-center gap-2 pl-1">
                                    <div className="flex items-center gap-1">
                                        <span className="text-[11px] text-slate-400">De:</span>
                                        <input
                                            type="month"
                                            required
                                            value={dateFilter.startMonth}
                                            onChange={(e) => {
                                                if (e.target.value) {
                                                    setDateFilter({
                                                        ...dateFilter,
                                                        startMonth: e.target.value,
                                                    });
                                                }
                                            }}
                                            className="rounded-lg bg-slate-100 px-2.5 py-1 text-xs font-bold text-slate-800 outline-none cursor-pointer border border-slate-200 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                                        />
                                    </div>
                                    <div className="flex items-center gap-1">
                                        <span className="text-[11px] text-slate-400">Até:</span>
                                        <input
                                            type="month"
                                            required
                                            value={dateFilter.endMonth}
                                            onChange={(e) => {
                                                if (e.target.value) {
                                                    setDateFilter({
                                                        ...dateFilter,
                                                        endMonth: e.target.value,
                                                    });
                                                }
                                            }}
                                            className="rounded-lg bg-slate-100 px-2.5 py-1 text-xs font-bold text-slate-800 outline-none cursor-pointer border border-slate-200 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-100"
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-5 space-y-3">
                    {isLoading ? (
                        <div className="py-12 text-center text-sm font-bold text-slate-400">
                            <i className="bi bi-arrow-repeat mb-2 block animate-spin text-2xl" aria-hidden="true" />
                            Buscando notas fiscais...
                        </div>
                    ) : loadError ? (
                        <div className="py-12 text-center text-sm font-bold text-red-500">
                            <p>{loadError}</p>
                            <button
                                type="button"
                                onClick={() => void loadInvoices()}
                                className="mt-3 rounded-xl bg-red-50 px-4 py-2 text-xs font-black text-red-700 hover:bg-red-100 transition-colors"
                            >
                                Tentar novamente
                            </button>
                        </div>
                    ) : available.length === 0 ? (
                        <div className="py-12 text-center text-slate-400">
                            <i className="bi bi-inbox text-3xl text-slate-300 dark:text-slate-700" aria-hidden="true" />
                            <p className="mt-2 text-xs font-bold">Nenhuma nota fiscal encontrada para os filtros selecionados.</p>
                            <button
                                type="button"
                                onClick={() => setIsCreateModalOpen(true)}
                                className="mt-3 rounded-xl bg-emerald-600 px-4 py-2 text-xs font-black text-white hover:bg-emerald-700 transition-colors"
                            >
                                Cadastrar nova NF de entrada
                            </button>
                        </div>
                    ) : (
                        available.map((inv) => {
                            const isFullyLinked = Boolean(
                                inv.items && inv.items.length > 0 && inv.items.every((item) => Boolean(item.matchedProductId))
                            );

                            return (
                                <div
                                    key={inv.id}
                                    className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 rounded-2xl border border-slate-200/80 bg-white p-4 shadow-sm hover:border-indigo-400 transition-all dark:border-slate-800 dark:bg-slate-950"
                                >
                                    <div className="space-y-1 min-w-0">
                                        <div className="flex items-center gap-2">
                                            <span className="font-bold text-xs text-slate-800 dark:text-slate-100">
                                                NF-e #{inv.nfeNumber}
                                            </span>
                                            <span className="text-[10px] text-slate-400">Série {inv.series}</span>
                                            <span className="rounded-full bg-blue-100 px-2 py-0.5 text-[9px] font-black uppercase text-blue-700 dark:bg-blue-950 dark:text-blue-300">
                                                {inv.itemsCount || inv.items?.length || 0} itens
                                            </span>
                                        </div>
                                        <p className="text-xs font-semibold text-slate-700 dark:text-slate-300 truncate">
                                            {inv.emitterName}
                                        </p>
                                        <p className="text-[10px] text-slate-500">
                                            CNPJ: {inv.emitterCnpj || 'Não informado'} · Emissão: {formatToBRDate(inv.issuedAt)}
                                        </p>
                                        <p className="text-[10px] font-mono text-slate-400 truncate">
                                            Chave: {inv.nfeKey}
                                        </p>
                                        <div className="flex items-center gap-1.5 flex-wrap pt-0.5">
                                            <span className={`inline-flex rounded-full px-2 py-0.5 text-[9px] font-black uppercase ${inv.status === 'received' ? 'bg-slate-100 text-slate-500 dark:bg-slate-800 dark:text-slate-400' : 'bg-blue-100 text-blue-700 dark:bg-blue-950 dark:text-blue-300'}`}>
                                                {statusLabel(inv.status)}
                                            </span>
                                            {isFullyLinked ? (
                                                <span className="inline-flex items-center gap-1 rounded-full bg-emerald-100 px-2 py-0.5 text-[9px] font-black uppercase text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300">
                                                    <i className="bi bi-check2-all text-[11px]" aria-hidden="true" /> Vinculação Completa
                                                </span>
                                            ) : (
                                                <span className="inline-flex items-center gap-1 rounded-full bg-amber-100 px-2 py-0.5 text-[9px] font-black uppercase text-amber-800 dark:bg-amber-950 dark:text-amber-300">
                                                    <i className="bi bi-exclamation-circle text-[10px]" aria-hidden="true" /> Vinculações Pendentes
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex items-center justify-between sm:justify-end gap-4 shrink-0 pt-2 sm:pt-0 border-t sm:border-t-0 border-slate-100 dark:border-slate-800">
                                        <div className="text-right">
                                            <span className="block text-[10px] uppercase tracking-wider text-slate-400">Total</span>
                                            <span className="text-sm font-black text-emerald-600">
                                                {formatCurrency(inv.totalInvoice)}
                                            </span>
                                        </div>
                                        {isFullyLinked ? (
                                            <button
                                                type="button"
                                                onClick={() => {
                                                    onSelect(inv);
                                                    onClose();
                                                }}
                                                className="rounded-xl bg-indigo-600 px-3.5 py-2 text-xs font-black uppercase tracking-wider text-white shadow-sm hover:bg-indigo-700 active:scale-95 transition-all"
                                            >
                                                Usar NF
                                            </button>
                                        ) : (
                                            <button
                                                type="button"
                                                onClick={() => setMappingInvoice(inv)}
                                                className="rounded-xl bg-blue-600 px-3.5 py-2 text-xs font-black uppercase tracking-wider text-white shadow-sm hover:bg-blue-700 active:scale-95 transition-all"
                                            >
                                                Finalizar Vinculação
                                            </button>
                                        )}
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>
            </section>

            <InboundDocumentImportModal
                isOpen={isCreateModalOpen}
                onClose={() => setIsCreateModalOpen(false)}
                onImportSuccess={(newInv) => {
                    setInvoices((current) => [newInv, ...current.filter((invoice) => invoice.id !== newInv.id)]);
                    setIsCreateModalOpen(false);
                    onCreate(newInv);
                }}
            />

            {mappingInvoice && (
                <ManageInboundInvoiceMappingsModal
                    isOpen={Boolean(mappingInvoice)}
                    onClose={() => setMappingInvoice(null)}
                    invoice={mappingInvoice}
                    onSaveSuccess={() => {
                        void loadInvoices();
                    }}
                />
            )}
        </div>
    );
}

export default InboundInvoiceReceiptPickerModal;

import { useMemo, useState } from "react";
import SectionCard from "../../../components/SectionCard";
import { systemDocumentation, DocumentationSection } from "./systemDocumentation";
import { userDocumentation } from "./userDocumentation";
import DocumentationFlow from "./DocumentationFlow";
import EngineeringImpactMap from "./EngineeringImpactMap";
import { engineeringImpactMaps } from "./engineeringImpactMaps";
import ArchitectureDocsSection from "./ArchitectureDocsSection";

type DocTab = "manual" | "architecture" | "all";

const DocumentationList = ({ title, icon, color, items }: { title: string; icon: string; color: string; items: string[] }) => (
    <section>
        <h2 className={`mb-2 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest ${color}`}><i className={`bi ${icon}`} /> {title}</h2>
        <ul className="space-y-2">{items.map((item) => <li key={item} className="flex gap-2 text-xs leading-relaxed text-slate-600 dark:text-slate-400"><i className="bi bi-dot text-lg leading-3 text-slate-400" />{item}</li>)}</ul>
    </section>
);

const SystemDocs = () => {
    const [activeTab, setActiveTab] = useState<DocTab>("manual");
    const [searchTerm, setSearchTerm] = useState("");

    const activeDocumentation = useMemo<DocumentationSection[]>(() => {
        if (activeTab === "manual") return userDocumentation;
        if (activeTab === "architecture") return systemDocumentation;
        return [...userDocumentation, ...systemDocumentation];
    }, [activeTab]);

    const sections = useMemo(() => {
        const search = searchTerm.trim().toLocaleLowerCase("pt-BR");
        if (!search) return activeDocumentation;
        return activeDocumentation.filter((section) =>
            [section.title, section.summary, ...section.rules].join(" ").toLocaleLowerCase("pt-BR").includes(search)
        );
    }, [activeDocumentation, searchTerm]);

    return (
        <main className="mx-auto flex max-w-6xl flex-col gap-6 pb-20">
            <header className="rounded-3xl border border-blue-100 bg-blue-50/60 p-6 dark:border-blue-900/40 dark:bg-blue-950/20">
                <div className="flex items-center justify-between">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-600">Base Conhecimento & Regras Oficiais</p>
                    <span className="bg-blue-600 text-white text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full">
                        Morante Hub ERP
                    </span>
                </div>
                <h1 className="mt-2 flex items-center gap-3 text-2xl font-black text-slate-800 dark:text-slate-100">
                    <i className="bi bi-book-half text-blue-600" /> Documentação do Sistema
                </h1>
                <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-600 dark:text-slate-400">
                    Guia completo de regras de negócio, operação por cargo, movimentações de estoque, automações e arquitetura do ERP.
                </p>
            </header>

            {/* Abas Principais de Navegação */}
            <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between rounded-2xl border border-slate-100 bg-white p-2 shadow-sm dark:border-slate-800 dark:bg-slate-900">
                <div className="flex flex-wrap items-center gap-1.5">
                    <button
                        type="button"
                        onClick={() => setActiveTab("manual")}
                        className={`flex items-center gap-2 rounded-xl px-4 py-2.5 text-xs font-black transition-all ${
                            activeTab === "manual"
                                ? "bg-blue-600 text-white shadow-md"
                                : "text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"
                        }`}
                    >
                        <i className="bi bi-person-workspace text-sm" />
                        Manual Operacional
                    </button>

                    <button
                        type="button"
                        onClick={() => setActiveTab("architecture")}
                        className={`flex items-center gap-2 rounded-xl px-4 py-2.5 text-xs font-black transition-all ${
                            activeTab === "architecture"
                                ? "bg-indigo-600 text-white shadow-md"
                                : "text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"
                        }`}
                    >
                        <i className="bi bi-cpu-fill text-sm text-indigo-400" />
                        Modelagem & Arquitetura (Devs / IA)
                    </button>

                    <button
                        type="button"
                        onClick={() => setActiveTab("all")}
                        className={`flex items-center gap-2 rounded-xl px-4 py-2.5 text-xs font-black transition-all ${
                            activeTab === "all"
                                ? "bg-slate-800 text-white shadow-md dark:bg-slate-700"
                                : "text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"
                        }`}
                    >
                        <i className="bi bi-layers-half text-sm" />
                        Visão Geral Completa
                    </button>
                </div>

                <div className="relative min-w-[16rem]">
                    <i className="bi bi-search absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 text-xs" />
                    <input
                        value={searchTerm}
                        onChange={(event) => setSearchTerm(event.target.value)}
                        placeholder="Pesquisar regras ou termos..."
                        className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2 pl-9 pr-3 text-xs font-semibold outline-none transition focus:border-blue-600 focus:bg-white dark:border-slate-800 dark:bg-slate-955/50 dark:text-slate-100"
                    />
                </div>
            </div>

            {/* Conteúdo da Aba Selecionada */}
            {activeTab === "architecture" ? (
                <ArchitectureDocsSection />
            ) : (
                <div className="grid grid-cols-1 gap-5 lg:grid-cols-2">
                    {sections.map((section) => (
                        <SectionCard key={section.title} title={section.title} icon={`bi ${section.icon}`} iconBg="bg-slate-100 dark:bg-slate-800">
                            <div className="space-y-4">
                                <p className="text-sm text-slate-600 dark:text-slate-400 font-medium leading-relaxed">{section.summary}</p>
                                <DocumentationList title="Regras e Funcionamento" icon="bi-diagram-3-fill" color="text-blue-600" items={section.rules} />
                                {engineeringImpactMaps[section.title] && <EngineeringImpactMap impacts={engineeringImpactMaps[section.title]} />}
                                <DocumentationFlow steps={section.flow} />
                            </div>
                        </SectionCard>
                    ))}
                </div>
            )}

            {activeTab !== "architecture" && sections.length === 0 && (
                <p className="py-16 text-center text-sm font-bold text-slate-400">Nenhum tópico de documentação encontrado.</p>
            )}
        </main>
    );
};

export default SystemDocs;

import { useMemo, useState } from 'react';
import VariationType, { VariationOption } from '../../types/variation.type';
import { normalizeSearchTerm } from '../../utils/textUtils';

const VALUE_PREVIEW_LIMIT = 15;

interface AttributeCardProps {
    readonly attribute: VariationType;
    readonly onAddValues: (attribute: VariationType, input: string) => Promise<boolean>;
    readonly onDeleteAttribute: (attributeId: string, event: React.MouseEvent) => void;
    readonly onDeleteValue: (attribute: VariationType, option: VariationOption) => Promise<void>;
    readonly onEdit: (attribute: VariationType) => void;
}

export function AttributeCard({ attribute, onAddValues, onDeleteAttribute, onDeleteValue, onEdit }: AttributeCardProps) {
    const canAddOptions = ['radio', 'multi_select'].includes(attribute.dataType || '');
    const [isExpanded, setIsExpanded] = useState(false);
    const [showAll, setShowAll] = useState(false);
    const [valueSearch, setValueSearch] = useState('');
    const [isAdding, setIsAdding] = useState(false);
    const [newValues, setNewValues] = useState('');
    const [menuOpen, setMenuOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    const filteredValues = useMemo(() => {
        const search = normalizeSearchTerm(valueSearch);
        if (!search) return attribute.options;
        return attribute.options.filter((option) => normalizeSearchTerm(option.value).includes(search));
    }, [attribute.options, valueSearch]);

    const visibleValues = valueSearch || showAll ? filteredValues : filteredValues.slice(0, VALUE_PREVIEW_LIMIT);
    const hiddenValueCount = Math.max(0, filteredValues.length - visibleValues.length);
    const hasManyValues = attribute.options.length > VALUE_PREVIEW_LIMIT;

    const submitValues = async () => {
        if (!newValues.trim() || isSaving) return;
        setIsSaving(true);
        const saved = await onAddValues(attribute, newValues);
        setIsSaving(false);
        if (saved) {
            setNewValues('');
            setIsAdding(false);
            setShowAll(true);
        }
    };

    const getSubtitle = () => {
        switch (attribute.dataType) {
            case 'measure':
                return 'Número Decimal';
            case 'integer':
                return 'Número Inteiro';
            case 'number':
                return 'Número Inteiro';
            case 'decimal':
                return 'Número Decimal';
            case 'text':
            case 'text_short':
            case 'text_long':
                return 'Texto';
            case 'radio':
                return `Escolha única • ${attribute.options.length} ${attribute.options.length === 1 ? 'opção' : 'opções'}`;
            case 'multi_select':
                return `Escolha múltipla • ${attribute.options.length} ${attribute.options.length === 1 ? 'opção' : 'opções'}`;
            default:
                return 'Texto';
        }
    };

    return (
        <article className="bg-white dark:bg-slate-950 border border-slate-200/80 dark:border-slate-800 rounded-3xl shadow-sm overflow-visible">
            <div className="flex items-center gap-3 px-5 py-4 sm:px-6">
                <div className="min-w-0 flex-1 flex items-center justify-between gap-4 text-left">
                    <span className="min-w-0">
