import React, { useState, useEffect } from 'react';
import { TextInput, TextInputProps, StyleSheet, View, Text } from 'react-native';

export interface CurrencyInputProps extends Omit<TextInputProps, 'value' | 'onChangeText' | 'onChange'> {
    value: number | null | undefined;
    onChangeValue: (value: number | null) => void;
    /** Prefixo, padrão "R$ " */
    prefix?: string;
    /** Cor do texto */
    color?: string;
    /** Quando verdadeiro, não permite edição e tem estilo ofuscado */
    disabled?: boolean;
}

/**
 * CurrencyInput
 * Componente padronizado para entrada de valores monetários no App Mobile.
 * Implementa digitação da direita para a esquerda (ex: digita 1, fica 0,01. Digita 12, fica 0,12).
 * 
 * @param value Valor numérico (number | null). O componente gerencia a formatação internamente.
 * @param onChangeValue Callback que recebe o valor numérico em reais (ex: 12.50).
 */
export function CurrencyInput({
    value,
    onChangeValue,
    prefix = 'R$ ',
    color = '#1e293b', // slate-800
    disabled = false,
    style,
    ...rest
}: CurrencyInputProps) {
    const [displayValue, setDisplayValue] = useState('');

    // Sincroniza valor externo com estado interno
    useEffect(() => {
        if (value === null || value === undefined || isNaN(value)) {
            setDisplayValue('');
            return;
        }

        // Converte o valor number (ex: 12.34) para a string formatada em pt-BR (ex: "R$ 12,34")
        const formatted = new Intl.NumberFormat('pt-BR', {
            style: 'currency',
            currency: 'BRL',
            minimumFractionDigits: 2,
        }).format(value);

        // Remove o "R$" padrão do Intl se o prefixo customizado for diferente ou se quisermos forçar o prefixo prop
        const numberPart = formatted.replace(/^R\$\s?/, '');
        setDisplayValue(prefix + numberPart);
    }, [value, prefix]);

    const handleChangeText = (text: string) => {
        if (disabled) return;

        // Remove tudo que não for dígito
        const digitsOnly = text.replace(/\D/g, '');

        if (!digitsOnly) {
            onChangeValue(null);
            setDisplayValue('');
            return;
        }

        // Transforma os dígitos de volta em número de ponto flutuante considerando 2 casas
        // Ex: "123" -> 1.23
        const numericValue = parseInt(digitsOnly, 10) / 100;

        onChangeValue(numericValue);

        // A formatação visual de atualização imediata da digitação
        const formatted = new Intl.NumberFormat('pt-BR', {
            style: 'currency',
            currency: 'BRL',
            minimumFractionDigits: 2,
        }).format(numericValue);

        const numberPart = formatted.replace(/^R\$\s?/, '');
        setDisplayValue(prefix + numberPart);
    };

    return (
        <TextInput
            style={[
                styles.input,
                { color: disabled ? '#94a3b8' : color },
                disabled && styles.disabled,
                style
            ]}
            keyboardType="numeric"
            value={displayValue}
            onChangeText={handleChangeText}
            editable={!disabled}
            selectTextOnFocus={true}
            {...rest}
        />
    );
}

const styles = StyleSheet.create({
    input: {
        fontSize: 14,
        fontWeight: 'bold',
        minHeight: 40,
        paddingHorizontal: 12,
        paddingVertical: 8,
        borderWidth: 1,
        borderColor: '#e2e8f0', // slate-200
        borderRadius: 8,
        backgroundColor: '#ffffff',
    },
    disabled: {
        backgroundColor: '#f1f5f9', // slate-100
        borderColor: '#f1f5f9',
    }
});

