import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { View, Text, TouchableOpacity, Modal, StyleSheet, TextInput, FlatList } from 'react-native';
import { X, Search, Check, Folder } from 'lucide-react-native';
import type { FinancialCategory } from '../../../services/mobileFinanceService';
import { sortCategoriesWithOthersAtEnd } from '../../../services/financial/mobileCategoryService';

interface Props {
  visible: boolean;
  onClose: () => void;
  categories: FinancialCategory[];
  selectedCategoryId: string;
  onSelectCategory: (category: FinancialCategory) => void;
  initialSearchText?: string;
  isDarkMode?: boolean;
}

const normalize = (str: string): string => {
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
};

export const CategorySelectModal: React.FC<Props> = ({
  visible,
  onClose,
  categories,
  selectedCategoryId,
  onSelectCategory,
  initialSearchText = '',
  isDarkMode = false,
}) => {
  const insets = useSafeAreaInsets();
  const [searchText, setSearchText] = useState(initialSearchText);

  React.useEffect(() => {
    if (visible) {
      setSearchText(initialSearchText);
    }
  }, [visible, initialSearchText]);

  const filteredCategories = useMemo(() => {
    let result = categories;
    if (searchText.trim()) {
      const term = normalize(searchText);
      result = categories.filter(c => normalize(c.name).includes(term));
    }
    return sortCategoriesWithOthersAtEnd(result);
  }, [categories, searchText]);

  return (
    <Modal visible={visible} animationType="slide" transparent={true} onRequestClose={onClose}>
      <View style={[styles.overlay, { paddingTop: insets.top, paddingBottom: Math.max(insets.bottom, 16) }]}>
        <View style={[styles.modalContent, isDarkMode && styles.modalContentDark]}>
          {/* Header */}
          <View style={styles.header}>
            <View style={styles.headerTitleRow}>
              <Folder size={18} color={isDarkMode ? '#60a5fa' : '#3b82f6'} />
              <Text style={[styles.title, isDarkMode && styles.titleDark]}>Selecionar Categoria</Text>
            </View>
            <TouchableOpacity onPress={onClose} style={styles.closeBtn}>
              <X size={20} color={isDarkMode ? '#94a3b8' : '#64748b'} />
            </TouchableOpacity>
          </View>

          {/* Search Input */}
          <View style={[styles.searchContainer, isDarkMode && styles.searchContainerDark]}>
            <Search size={16} color={isDarkMode ? '#94a3b8' : '#64748b'} />
            <TextInput
              style={[styles.searchInput, isDarkMode && styles.searchInputDark]}
              placeholder="Pesquisar categoria..."
              placeholderTextColor={isDarkMode ? '#64748b' : '#94a3b8'}
              value={searchText}
              onChangeText={setSearchText}
              autoFocus={true}
              clearButtonMode="while-editing"
            />
            {searchText.length > 0 && (
              <TouchableOpacity onPress={() => setSearchText('')} style={styles.clearSearchBtn}>
                <X size={14} color={isDarkMode ? '#94a3b8' : '#64748b'} />
              </TouchableOpacity>
            )}
          </View>

          {/* List */}
          <FlatList
            data={filteredCategories}
            keyExtractor={item => item.id}
            keyboardShouldPersistTaps="handled"
            contentContainerStyle={styles.listContent}
            ListEmptyComponent={
              <View style={styles.emptyContainer}>
                <Text style={[styles.emptyText, isDarkMode && styles.emptyTextDark]}>
                  Nenhuma categoria encontrada para "{searchText}".
                </Text>
              </View>
            }
            renderItem={({ item }) => {
              const isSelected = item.id === selectedCategoryId;
              return (
                <TouchableOpacity
                  testID={`cat-item-${item.name}`}
                  accessibilityRole="button"
                  accessibilityLabel={`Categoria ${item.name}`}
                  style={[
                    styles.itemRow,
                    isDarkMode && styles.itemRowDark,
                    isSelected && (isDarkMode ? styles.itemRowSelectedDark : styles.itemRowSelected),
                  ]}
                  onPress={() => {
                    onSelectCategory(item);
                    onClose();
                  }}
                  {...({
                    onClick: () => {
                      onSelectCategory(item);
                      onClose();
                    },
                  } as any)}
                >
                  <Text
                    style={[
                      styles.itemText,
                      isDarkMode && styles.itemTextDark,
                      isSelected && styles.itemTextSelected,
                    ]}
                  >
                    {item.name}
                  </Text>
                  {isSelected && <Check size={18} color="#3b82f6" />}
                </TouchableOpacity>
              );
            }}
          />
        </View>
      </View>
    </Modal>
  );
};

const styles = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,0.55)',
    justifyContent: 'flex-end',
  },
  modalContent: {
    backgroundColor: '#ffffff',
