  },
  searchInputDark: {
    color: '#f8fafc',
  },
  clearSearchBtn: {
    padding: 4,
  },
  listContent: {
    paddingVertical: 6,
  },
  itemRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 12,
    paddingHorizontal: 12,
    borderRadius: 8,
    marginBottom: 4,
  },
  itemRowDark: {
    backgroundColor: 'transparent',
  },
  itemRowSelected: {
    backgroundColor: '#eff6ff',
  },
  itemRowSelectedDark: {
    backgroundColor: '#1e3a8a33',
  },
  itemText: {
    fontSize: 14,
    fontWeight: '500',
    color: '#334155',
  },
  itemTextDark: {
    color: '#cbd5e1',
  },
  itemTextSelected: {
