import { AudioLines, Send } from 'lucide-react-native';

interface Props {
  inputText: string;
  loading: boolean;
  isDarkMode?: boolean;
  onChangeInputText: (text: string) => void;
  onSendMessage: () => void;
  onStartLive: () => void;
}

export const FinancialChatInputBar: React.FC<Props> = ({
  inputText,
  loading,
  isDarkMode,
  onChangeInputText,
  onSendMessage,
  onStartLive,
}) => {
  return (
    <View style={[styles.inputContainer, isDarkMode && styles.inputContainerDark]}>
      <TextInput
        style={[styles.textInput, isDarkMode && styles.textInputDark]}
        placeholder="Descreva a movimentação ou dúvida..."
        placeholderTextColor={isDarkMode ? '#64748b' : '#94a3b8'}
        value={inputText}
        onChangeText={onChangeInputText}
        multiline
        maxLength={500}
      />

      {inputText.trim() ? (
        <TouchableOpacity
          style={[styles.sendBtn, loading ? styles.sendBtnDisabled : null]}
          onPress={onSendMessage}
          disabled={loading}
          activeOpacity={0.8}
          accessibilityRole="button"
          accessibilityLabel="Enviar mensagem"
        >
          <Send size={16} color="#ffffff" />
        </TouchableOpacity>
      ) : (
        <TouchableOpacity
          style={styles.voiceModeBtn}
          onPress={onStartLive}
          accessibilityRole="button"
          accessibilityLabel="Voice Mode"
          accessibilityHint="Iniciar conversa por voz Gemini Live"
          activeOpacity={0.8}
        >
          <AudioLines size={18} color="#ffffff" />
        </TouchableOpacity>
      )}
    </View>
  );
};

