                  </Text>
                ) : null}
              </View>
            </TouchableOpacity>
          );
        })}
        {matchingCategories.length === 0 && (
          <Text style={styles.emptyCategoriesText}>Nenhuma categoria encontrada para “{search}”.</Text>
        )}
      </ScrollView>
      ) : (
        <Text style={styles.emptyCategoriesText}>Digite ao menos 2 caracteres para pesquisar.</Text>
      )}
    </View>
  );
};

