  return <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}><View style={[styles.backdrop, { paddingTop: insets.top, paddingBottom: Math.max(insets.bottom, 16) }]}><View style={[styles.content, dark && styles.darkContent]}><View style={styles.header}><View style={styles.titleRow}><Tag size={20} color="#2563eb" /><Text style={[styles.title, dark && styles.light]}>Tipos de Produto</Text></View><TouchableOpacity onPress={onClose}><X size={20} color={dark ? '#cbd5e1' : '#64748b'} /></TouchableOpacity></View><View style={styles.form}><TextInput value={name} onChangeText={setName} placeholder="Ex.: BALCÃO DE PIA" placeholderTextColor="#94a3b8" style={[styles.input, dark && styles.darkInput, dark && styles.light]} autoCapitalize="characters" /><TouchableOpacity onPress={() => void add()} style={styles.add}><Plus size={17} color="#fff" /></TouchableOpacity></View>{loading ? <ActivityIndicator color="#2563eb" /> : <ScrollView>{types.length === 0 ? <Text style={styles.empty}>Nenhum tipo cadastrado.</Text> : types.map(item => <View key={item.id} style={[styles.item, dark && styles.darkItem]}><Text style={[styles.itemText, dark && styles.light]}>{item.name}</Text><TouchableOpacity onPress={() => remove(item)}><Trash2 size={16} color="#ef4444" /></TouchableOpacity></View>)}</ScrollView>}</View></View></Modal>;
