import { supabase } from '../../../../services/supabaseClient';

import { clearInventoryScopeCache, fetchInventoryScopeSuppliers, fetchInventoryScopeProducts } from '../../../../services/stockService';

export interface SearchableProduct {
    id: string;
    variation_id?: string;
    sku?: string | null;
    code?: string | null;
    barcode?: string | null;
    name: string;
    description?: string;
    stock: number;
    unit?: string;
    main_supplier_id?: string;
    supplier_id?: string;
    supplier_ids?: string[];
    supplierNames?: string;
    assignedSupplier?: string;
}

interface Props {
    isDarkMode: boolean;
    visible: boolean;
    onClose: () => void;
    onSelect: (product: SearchableProduct) => void;
}

export const InventoryProductSearchModal: React.FC<Props> = ({ isDarkMode, visible, onClose, onSelect }) => {
  const insets = useSafeAreaInsets();
    const [search, setSearch] = useState('');
    const [products, setProducts] = useState<SearchableProduct[]>([]);
    const [loading, setLoading] = useState(true);

    const bg = isDarkMode ? '#0f172a' : '#f8fafc';
    const surface = isDarkMode ? '#1e293b' : '#ffffff';
    const border = isDarkMode ? '#334155' : '#e2e8f0';
    const textPrimary = isDarkMode ? '#f1f5f9' : '#0f172a';
    const muted = isDarkMode ? '#94a3b8' : '#64748b';

    useEffect(() => {
        if (!visible) return;
        setLoading(true);

        Promise.all([
            fetchInventoryScopeSuppliers().catch(() => []),
            fetchInventoryScopeProducts('full').catch(() => []),
        ]).then(([supplierData, scopeProducts]) => {
            const suppliersList = (supplierData || []) as Array<{ id: string | number; full_name?: string }>;
            const suppliersMap = new Map<string, string>();
            for (const s of suppliersList) {
                if (s.id && s.full_name) {
                    suppliersMap.set(String(s.id), s.full_name);
                }
            }

            const resolveSuppliers = (p: any) => {
                const ids = [...new Set([p.main_supplier_id, p.supplier_id, ...(p.supplier_ids || [])].filter(Boolean).map(String))];
                const names = ids.map(id => suppliersMap.get(id)).filter(Boolean);
                const supplierNames = names.join(' / ') || 'Fábrica não informada';
                const assignedSupplier = names[0] || 'Sem fornecedor';
                return { supplierNames, assignedSupplier };
            };

            const mapped = (scopeProducts || []).map((product: any) => {
                const { supplierNames, assignedSupplier } = resolveSuppliers(product);
                return {
                    id: String(product.id),
                    variation_id: product.variation_id ? String(product.variation_id) : undefined,
                    name: product.name || product.description || 'Produto',
                    description: product.description,
                    sku: product.sku || product.code || '',
                    code: product.code || '',
                    barcode: product.barcode || '',
                    stock: product.stock ?? 0,
                    unit: product.unit || 'UN',
                    supplierNames,
                    assignedSupplier,
                } as SearchableProduct;
            });

            setProducts(mapped);
            setLoading(false);
        }).catch((err) => {
            console.error('Erro ao buscar catálogo de produtos para escopo:', err);
            setLoading(false);
        });
    }, [visible]);

    const filtered = search.length < 2
        ? products.slice(0, 30)
        : products.filter(p =>
            `${p.name || p.description || ''} ${p.sku || ''}`.toLowerCase().includes(search.toLowerCase())
          ).slice(0, 30);

    const handleSelect = (product: SearchableProduct) => {
        onSelect(product);
        setSearch('');
        onClose();
    };

    return (
        <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
            <View style={[styles.container, { backgroundColor: bg }, { paddingTop: insets.top, paddingBottom: Math.max(insets.bottom, 16) }]}>
                {/* Header */}
                <View style={[styles.header, { backgroundColor: '#7c3aed', paddingTop: 50 }]}>
                    <View style={{ flex: 1 }}>
                        <Text style={styles.headerTitle}>Buscar Produto</Text>
                        <Text style={styles.headerSubtitle}>Selecione para adicionar à contagem</Text>
                    </View>
                    <TouchableOpacity testID="close-modal-btn" onPress={onClose} style={styles.closeBtn}>
                        <X size={24} color="#ffffff" />
                    </TouchableOpacity>
                </View>

                {/* Search bar */}
                <View style={[styles.searchBar, { backgroundColor: surface, borderBottomColor: border }]}>
                    <View style={[styles.searchBox, { backgroundColor: bg, borderColor: border }]}>
                        <Search size={18} color={muted} />
                        <TextInput
                            testID="search-product-input"
                            style={[styles.searchInput, { color: textPrimary }]}
                            autoFocus
                            value={search}
                            onChangeText={setSearch}
                            placeholder="Nome, SKU, código..."
                            placeholderTextColor={muted}
                        />
                        {search.length > 0 && (
                            <TouchableOpacity onPress={() => setSearch('')}>
                                <X size={16} color={muted} />
                            </TouchableOpacity>
                        )}
                    </View>
                </View>

                {/* Results */}
                {loading ? (
                    <View style={styles.centered}>
                        <ActivityIndicator size="large" color="#7c3aed" />
                    </View>
                ) : (
                    <FlatList
                        data={filtered}
                        keyExtractor={item => item.variation_id ? `${item.id}-${item.variation_id}` : String(item.id)}
                        contentContainerStyle={styles.listContent}
                        ListEmptyComponent={
                            <View style={styles.centered}>
                                <Text style={{ color: muted, textAlign: 'center' }}>
                                    {search.length > 0 ? 'Nenhum produto encontrado' : 'Digite para buscar produtos'}
                                </Text>
                            </View>
                        }
                        renderItem={({ item }) => (
                            <TouchableOpacity
                                testID="product-search-item"
                                style={[styles.productItem, { backgroundColor: surface, borderColor: border }]}
                                onPress={() => handleSelect(item)}
                            >
                                <View style={{ flex: 1 }}>
                                    <Text style={[styles.productName, { color: textPrimary }]} numberOfLines={1}>
                                        {item.name || item.description || 'Produto'}
                                    </Text>
                                    <Text style={[styles.productStock, { color: muted }]}>
                                        {item.supplierNames && item.supplierNames !== 'Fábrica não informada' ? `${item.supplierNames} · ` : ''}
                                        {item.sku ? `SKU: ${item.sku} · ` : ''}Estoque: {item.stock ?? 0} {item.unit || 'UN'}
                                    </Text>
                                </View>
                                <View style={styles.addBtn}>
                                    <Text style={styles.addBtnText}>+ Add</Text>
                                </View>
                            </TouchableOpacity>
                        )}
                    />
                )}
            </View>
        </Modal>
    );
};

